//! evaluator — AST ツリーウォーク実行エンジン。
//!
//! 式を評価し、文を実行する。クラス/メソッド解決、変数バインディング、
//! ビルトイン関数ディスパッチを行う。

const std = @import("std");
const types = @import("types.zig");
const ast = @import("ast.zig");
const env_mod = @import("env.zig");
const builtins = @import("builtins.zig");
const utils = @import("utils.zig");
const regex = @import("regex.zig");
const Value = types.Value;
const Env = env_mod.Env;

const soql_missing_field_message =
    "SObject row was retrieved via SOQL without querying the requested field: ";

pub const StmtResult = union(enum) {
    normal,
    return_val: Value,
    break_signal,
    continue_signal,
};

pub const CustomChildRelationship = struct {
    child_type: []const u8,
    fk_field: []const u8,
};

pub const SummaryFilter = struct {
    field_path: []const u8,
    operation: []const u8,
    value: []const u8,
};

pub const PicklistValueMetadata = struct {
    label: []const u8,
    value: []const u8,
    is_default: bool = false,
};

pub const FieldMetadata = struct {
    label: ?[]const u8 = null,
    inline_help_text: ?[]const u8 = null,
    is_unique: bool = false,
    is_external_id: bool = false,
    case_sensitive: bool = false,
    is_required: bool = false,
    length: ?i64 = null,
    reference_to: ?[]const u8 = null,
    formula: ?[]const u8 = null,
    formula_blank_as_zero: bool = false,
    summarized_field: ?[]const u8 = null,
    summary_foreign_key: ?[]const u8 = null,
    summary_operation: ?[]const u8 = null,
    summary_filters: []const SummaryFilter = &.{},
    picklist_values: []const PicklistValueMetadata = &.{},
};

pub const FieldSetMemberMetadata = struct {
    field_path: []const u8,
    is_required: bool = false,
};

pub const FieldSetMetadata = struct {
    name: []const u8,
    qualified_name: []const u8,
    label: []const u8,
    namespace: []const u8 = "",
    members: []const FieldSetMemberMetadata = &.{},
};

pub const Evaluator = struct {
    arena: std.mem.Allocator,
    /// I/O 抽象 (0.16 Io refactor)。ファイル操作・乱数・時刻で利用する。
    io: std.Io,
    /// classes map 専用 allocator (parse_arena — テスト間で保持される)
    class_arena: ?std.mem.Allocator = null,
    global_env: *Env,
    stdout: std.ArrayListUnmanaged(u8) = .empty,
    classes: std.StringArrayHashMapUnmanaged(*ast.ClassDecl) = .empty,
    return_value: Value = .void_val,
    assertion_failure: ?[]const u8 = null,
    // インメモリ SObject ストア
    store: std.StringArrayHashMapUnmanaged(std.ArrayListUnmanaged(Value)) = .empty,
    next_id: u64 = 1,
    /// Id → SObject type_name mapping (populated by insertRecord and createId)
    id_type_map: std.StringArrayHashMapUnmanaged([]const u8) = .empty,
    // bypass リスト (TriggerHandler.bypass 等)
    bypasses: std.StringArrayHashMapUnmanaged(void) = .empty,
    // 削除済みレコードのゴミ箱 (undelete 用)
    trash: std.StringArrayHashMapUnmanaged(std.ArrayListUnmanaged(Value)) = .empty,
    // 例外ハンドリング
    pending_exception: ?Value = null,
    // HttpCalloutMock
    callout_mock: ?Value = null,
    // Current class name for static field resolution
    current_class: ?[]const u8 = null,
    // Property getter currently being evaluated
    // (to prevent infinite recursion in self-referencing getters)
    evaluating_getter: ?[]const u8 = null,
    evaluating_getter_instance: ?*types.ObjectInstance = null,
    // JSON round-trip: store last serialized value for deserialize
    last_json_value: ?Value = null,
    // SOSL fixed search results (set by Test.setFixedSearchResults)
    fixed_search_results: ?Value = null,
    // Class name of the currently executing constructor
    // (for correct super() dispatch)
    current_constructor_class: ?[]const u8 = null,
    // Call depth counter (stack overflow guard)
    call_depth: u32 = 0,
    max_call_depth: u32 = 500,
    // Scheduled jobs store (System.schedule → CronTrigger queries)
    scheduled_jobs: std.StringArrayHashMapUnmanaged([]const u8) = .empty,
    // Schedulable instances queued during Test.startTest();
    // executed on Test.stopTest()
    pending_schedulables: std.ArrayListUnmanaged(Value) = .empty,
    // Class source code
    // (class name → source text, for ApexClass.Body queries)
    class_sources: std.StringArrayHashMapUnmanaged([]const u8) = .empty,
    // Trigger source code
    // (trigger name → source text, for ApexTrigger.Body queries)
    trigger_sources: std.StringArrayHashMapUnmanaged([]const u8) = .empty,
    // Whether current test has @isTest(SeeAllData=true) annotation
    see_all_data: bool = false,
    // Whether running as a restricted user
    // (System.runAs with min-access or marketing user)
    is_restricted_user: bool = false,
    // Whether running as a minimum-access user specifically
    // (stricter than is_restricted_user)
    is_min_access_user: bool = false,
    // Whether running as a standard user
    // (has CRUD on business objects but not setup objects)
    is_standard_user: bool = false,
    // ApexPages message store
    // (for ApexPages.addMessages / hasMessages / getMessages)
    apex_pages_messages: std.ArrayListUnmanaged(Value) = .empty,
    // Trigger declarations (object name → list of triggers)
    triggers: std.StringArrayHashMapUnmanaged(std.ArrayListUnmanaged(*ast.TriggerDecl)) = .empty,
    // Trigger context variables
    trigger_context: ?TriggerContext = null,
    // Source paths for metadata lookup
    // (e.g., picklist values from field-meta.xml)
    source_paths: []const []const u8 = &.{},
    // SObject field default values from field-meta.xml
    // (type_name → field_name → default Value)
    field_defaults: std.StringArrayHashMapUnmanaged(
        std.StringArrayHashMapUnmanaged(Value),
    ) = .empty,
    /// field-meta.xml から読み取ったフィールド型情報。
    /// field_types[TypeName][FieldName] = "DateTime" 等。
    field_types: std.StringArrayHashMapUnmanaged(
        std.StringArrayHashMapUnmanaged([]const u8),
    ) = .empty,
    /// field-meta.xml から読み取ったフィールド制約・参照先。
    /// field_metadata[TypeName][FieldName] = metadata。
    field_metadata: std.StringArrayHashMapUnmanaged(
        std.StringArrayHashMapUnmanaged(FieldMetadata),
    ) = .empty,
    /// field-meta.xml から読み取った child relationship 情報。key = lowercase("{parent}|{relationship}").
    child_relationships: std.StringArrayHashMapUnmanaged(CustomChildRelationship) = .empty,
    /// object-meta.xml で `<customSettingsType>` が指定されている Custom Setting オブジェクト名の集合。
    custom_setting_types: std.StringArrayHashMapUnmanaged(void) = .empty,
    /// object-meta.xml で読み取った Custom Setting 種別。`Hierarchy` / `List` を保持する。
    custom_setting_kinds: std.StringArrayHashMapUnmanaged([]const u8) = .empty,
    /// object-meta.xml `<label>` を格納。object_labels[TypeName] = entity label.
    object_labels: std.StringArrayHashMapUnmanaged([]const u8) = .empty,
    /// object-meta.xml `<pluralLabel>` を格納。object_label_plurals[TypeName] = plural label.
    object_label_plurals: std.StringArrayHashMapUnmanaged([]const u8) = .empty,
    /// fieldSet-meta.xml から読み取った field set 情報。
    /// field_sets[TypeName][QualifiedFieldSetName] = metadata。
    field_sets: std.StringArrayHashMapUnmanaged(
        std.StringArrayHashMapUnmanaged(FieldSetMetadata),
    ) = .empty,
    /// class name (lowercase simple/FQ inner name) -> outer class name.
    outer_class_by_inner_name: std.StringArrayHashMapUnmanaged([]const u8) = .empty,
    class_lookup_cache_built: bool = false,
    static_field_owner_cache: std.StringArrayHashMapUnmanaged(?FieldLookup) = .empty,
    visible_enum_decl_cache: std.StringArrayHashMapUnmanaged(?*ast.EnumDecl) = .empty,
    /// Parsed Custom Metadata records loaded once from source paths.
    custom_metadata_records: std.StringArrayHashMapUnmanaged(
        std.ArrayListUnmanaged(Value),
    ) = .empty,
    custom_metadata_indexed_files: std.StringArrayHashMapUnmanaged(void) = .empty,
    custom_metadata_paths_indexed: bool = false,
    custom_metadata_loaded_types: std.StringArrayHashMapUnmanaged(void) = .empty,
    // System.Limits counters
    limits_dml: u32 = 0,
    limits_dml_rows: u32 = 0,
    limits_soql: u32 = 0,
    limits_publish_immediate: u32 = 0,
    limits_queueable: u32 = 0,
    limits_callouts: u32 = 0,
    limits_email_invocations: u32 = 0,
    reserved_single_email_capacity: i64 = 0,
    // Trigger recursion depth counter
    trigger_depth: u32 = 0,
    // Cast type hints for method overload resolution
    // (set by evalMethodCall, consumed by findBestMethodInClassFiltered)
    cast_type_hints: ?[]const ?[]const u8 = null,
    // Pending event callback for Test.getEventBus().fail() support
    pending_event_callback: ?struct {
        callback: *types.ObjectInstance,
        event: Value,
    } = null,
    // Lazy static initialization: tracks which classes have been statically initialized
    static_inited: std.StringArrayHashMapUnmanaged(void) = .empty,
    // Call stack for stack trace generation (Exception.getStackTraceString)
    call_stack: std.ArrayListUnmanaged(CallFrame) = .empty,
    // Line number of the current call-site expression (set before callMethod/callInstanceMethod)
    current_call_line: u32 = 0,
    // Current user context (defaults to the synthetic system test user)
    current_user_id: []const u8 = "005000000000001",
    current_profile_id: []const u8 = "00e000000000001",
    // Ephemeral User record surfaced inside `System.runAs(...)`. When set, UserInfo
    // methods read from here instead of the data store, so tests that build a
    // throw-away User (without inserting it) still get the values they configured.
    current_user_override: ?*types.SObject = null,
    // Batch job execution queue used to model chained Database.executeBatch calls
    pending_batch_jobs: std.ArrayListUnmanaged(Value) = .empty,
    batch_job_runner_active: bool = false,
    batch_lifecycle_depth: u32 = 0,
    active_batch_context: ?*types.ObjectInstance = null,
    active_batch_job_id: ?[]const u8 = null,
    active_queueable_job_id: ?[]const u8 = null,
    attached_finalizer: ?*types.ObjectInstance = null,

    pub const CallFrame = struct {
        class_name: []const u8,
        method_name: []const u8,
        line: u32,
    };

    const TriggerContext = struct {
        is_executing: bool = false,
        is_insert: bool = false,
        is_update: bool = false,
        is_delete: bool = false,
        is_undelete: bool = false,
        is_before: bool = false,
        is_after: bool = false,
        new_list: ?Value = null,
        old_list: ?Value = null,
        new_map: ?Value = null,
        old_map: ?Value = null,
        size: i64 = 0,
        operation_type: ?[]const u8 = null,
    };

    pub fn init(arena: std.mem.Allocator, io: std.Io) !Evaluator {
        const global = try arena.create(Env);
        global.* = Env.init(arena);
        return .{ .arena = arena, .io = io, .global_env = global };
    }

    pub fn reset_for_test(self: *Evaluator) void {
        self.assertion_failure = null;
        self.return_value = .void_val;
        self.stdout = .empty;
        self.store = .empty;
        self.static_inited = .empty;
        self.static_field_owner_cache = .empty;
        self.visible_enum_decl_cache = .empty;
        self.custom_metadata_loaded_types = .empty;
        self.next_id = 1;
        self.bypasses = .empty;
        self.pending_exception = null;
        self.callout_mock = null;
        self.fixed_search_results = null;
        self.trash = .empty;
        self.last_json_value = null;
        self.call_depth = 0;
        self.scheduled_jobs = .empty;
        self.pending_schedulables = .empty;
        self.is_restricted_user = false;
        self.is_min_access_user = false;
        self.is_standard_user = false;
        self.pending_event_callback = null;
        self.apex_pages_messages = .empty;
        self.current_user_id = "005000000000001";
        self.current_profile_id = "00e000000000001";
        self.active_batch_context = null;
        self.active_batch_job_id = null;
        self.active_queueable_job_id = null;
        self.attached_finalizer = null;

        // Clear cache partitions and ApexPages state
        _ = self.global_env.bindings.orderedRemove("Cache.Session.partition");
        _ = self.global_env.bindings.orderedRemove("Cache.Org.partition");
        var cache_partition_keys: std.ArrayListUnmanaged([]const u8) = .empty;
        for (self.global_env.bindings.keys()) |key| {
            if (std.mem.startsWith(u8, key, "Cache.Session.partition:") or
                std.mem.startsWith(u8, key, "Cache.Org.partition:"))
            {
                cache_partition_keys.append(self.arena, key) catch {};
            }
        }
        for (cache_partition_keys.items) |key| {
            _ = self.global_env.bindings.orderedRemove(key);
        }
        _ = self.global_env.bindings.orderedRemove("ApexPages.currentPageRef");
    }

    fn create_builtin_user_record(
        self: *Evaluator,
        user_id: []const u8,
        profile_id: []const u8,
        username: []const u8,
        alias: []const u8,
        first_name: []const u8,
        last_name: []const u8,
        display_name: []const u8,
    ) !Value {
        const user = try self.arena.create(types.SObject);
        user.* = .{ .type_name = "User" };
        user.id = user_id;
        try user.fields.put(self.arena, "Id", Value{ .string = user_id });
        try user.fields.put(self.arena, "FirstName", Value{ .string = first_name });
        try user.fields.put(self.arena, "LastName", Value{ .string = last_name });
        try user.fields.put(self.arena, "Name", Value{ .string = display_name });
        try user.fields.put(self.arena, "Email", Value{ .string = username });
        try user.fields.put(self.arena, "Username", Value{ .string = username });
        try user.fields.put(self.arena, "ProfileId", Value{ .string = profile_id });
        const profile = try self.arena.create(types.SObject);
        profile.* = .{ .type_name = "Profile", .id = profile_id };
        try profile.fields.put(self.arena, "Id", Value{ .string = profile_id });
        try self.populate_synthetic_profile(profile, "System Administrator");
        try user.fields.put(self.arena, "Profile", Value{ .sobject = profile });
        try user.fields.put(self.arena, "UserType", Value{ .string = "Standard" });
        try user.fields.put(self.arena, "IsActive", Value{ .boolean = true });
        try user.fields.put(self.arena, "Alias", Value{ .string = alias });
        try user.fields.put(self.arena, "TimeZoneSidKey", Value{ .string = "America/Los_Angeles" });
        try user.fields.put(self.arena, "LocaleSidKey", Value{ .string = "en_US" });
        try user.fields.put(self.arena, "EmailEncodingKey", Value{ .string = "UTF-8" });
        try user.fields.put(self.arena, "LanguageLocaleKey", Value{ .string = "en_US" });
        try user.fields.put(self.arena, "CommunityNickname", Value{ .string = alias });
        return Value{ .sobject = user };
    }

    fn create_default_user_record(self: *Evaluator) !Value {
        if (self.store.get("User")) |users| {
            for (users.items) |existing| {
                if (existing != .sobject or existing.sobject.id == null) continue;
                if (std.ascii.eqlIgnoreCase(existing.sobject.id.?, "005000000000001")) {
                    const clone = try self.clone_s_object(existing.sobject);
                    return Value{ .sobject = clone };
                }
            }
        }
        return self.create_builtin_user_record(
            "005000000000001",
            "00e000000000001",
            "testuser@example.com",
            "tuser",
            "Test",
            "User",
            "Test User",
        );
    }

    /// Create a synthetic User record for UserInfo.getUserId()
    /// — used by SOQL when no User records exist in store
    pub fn create_current_user_record(self: *Evaluator) !Value {
        if (self.current_user_override) |override| {
            if (override.id) |override_id| {
                if (std.ascii.eqlIgnoreCase(override_id, self.current_user_id)) {
                    const clone = try self.clone_s_object(override);
                    return Value{ .sobject = clone };
                }
            }
        }
        if (self.store.get("User")) |users| {
            for (users.items) |existing| {
                if (existing != .sobject or existing.sobject.id == null) continue;
                if (std.ascii.eqlIgnoreCase(existing.sobject.id.?, self.current_user_id)) {
                    const clone = try self.clone_s_object(existing.sobject);
                    return Value{ .sobject = clone };
                }
            }
        }
        if (std.ascii.eqlIgnoreCase(self.current_user_id, "005000000000001")) {
            return self.create_default_user_record();
        }
        return self.create_builtin_user_record(
            self.current_user_id,
            self.current_profile_id,
            "testuser@example.com",
            "tuser",
            "Test",
            "User",
            "Test User",
        );
    }

    fn should_synthesize_builtin_user(self: *Evaluator, soql: []const u8, current_env: *Env) bool {
        if (self.extract_where_field_value(soql, "Id", current_env)) |user_id| {
            if (std.ascii.eqlIgnoreCase(user_id, self.current_user_id)) return true;
        }
        if (self.extract_where_field_value(soql, "Alias", current_env)) |alias| {
            if (std.ascii.startsWithIgnoreCase(alias, "autoproc") or
                std.ascii.eqlIgnoreCase(alias, "tuser"))
            {
                return true;
            }
        }
        if (self.extract_where_field_value(soql, "Username", current_env)) |username| {
            if (std.ascii.startsWithIgnoreCase(username, "autoproc@") or
                std.ascii.eqlIgnoreCase(username, "testuser@example.com"))
            {
                return true;
            }
            if (std.ascii.startsWithIgnoreCase(username, "autoproc")) return true;
        }
        return false;
    }

    fn current_user_field_value(
        self: *Evaluator,
        field_name: []const u8,
        fallback: []const u8,
    ) []const u8 {
        if (self.store.get("User")) |users| {
            for (users.items) |existing| {
                if (existing != .sobject or existing.sobject.id == null) continue;
                if (!std.ascii.eqlIgnoreCase(existing.sobject.id.?, self.current_user_id)) continue;
                if (utils.sobject_get(&existing.sobject.fields, field_name)) |field_value| {
                    if (field_value == .string) return field_value.string;
                }
            }
        }
        return fallback;
    }

    fn query_matches_default_synthetic_user(
        self: *Evaluator,
        soql: []const u8,
        current_env: *Env,
    ) bool {
        if (self.extract_where_field_value(soql, "Id", current_env)) |user_id| {
            if (std.ascii.eqlIgnoreCase(user_id, "005000000000001")) return true;
        }
        if (self.extract_where_field_value(soql, "Alias", current_env)) |alias| {
            if (std.ascii.eqlIgnoreCase(alias, "tuser")) return true;
        }
        if (self.extract_where_field_value(soql, "Username", current_env)) |username| {
            if (std.ascii.eqlIgnoreCase(username, "testuser@example.com")) return true;
        }
        return false;
    }

    fn query_matches_current_user(self: *Evaluator, soql: []const u8, current_env: *Env) bool {
        if (self.extract_where_field_value(soql, "Id", current_env)) |user_id| {
            if (std.ascii.eqlIgnoreCase(user_id, self.current_user_id)) return true;
        }
        if (self.extract_where_field_value(soql, "Alias", current_env)) |alias| {
            const current_alias = self.current_user_field_value("Alias", "tuser");
            if (std.ascii.eqlIgnoreCase(alias, current_alias)) return true;
        }
        if (self.extract_where_field_value(soql, "Username", current_env)) |username| {
            const current_username = self.current_user_field_value(
                "Username",
                "testuser@example.com",
            );
            if (std.ascii.eqlIgnoreCase(username, current_username)) return true;
        }
        return false;
    }

    /// Resolve picklist API name to label using field-meta.xml
    fn resolve_picklist_label(
        self: *Evaluator,
        obj_type: []const u8,
        field_name: []const u8,
        api_name: []const u8,
    ) ?[]const u8 {
        if (self.get_field_metadata(obj_type, field_name)) |metadata| {
            for (metadata.picklist_values) |picklist_value| {
                if (std.mem.eql(u8, picklist_value.value, api_name)) return picklist_value.label;
            }
        }
        const suffix = std.fmt.allocPrint(
            self.arena,
            "objects/{s}/fields/{s}.field-meta.xml",
            .{ obj_type, field_name },
        ) catch return null;
        return self.resolve_picklist_label_from_sources(suffix, api_name);
    }

    fn resolve_picklist_label_from_sources(
        self: *Evaluator,
        suffix: []const u8,
        api_name: []const u8,
    ) ?[]const u8 {
        for (self.source_paths) |base_path| {
            // Try to find the field-meta.xml by walking common SFDX paths
            // Also try parent directories (e.g., "force-app/main/default/classes" → "force-app")
            const parent1 = std.fs.path.dirname(base_path) orelse base_path; // strip "classes"
            const parent2 = std.fs.path.dirname(parent1) orelse parent1; // strip "default"
            const parent3 = std.fs.path.dirname(parent2) orelse parent2; // strip "main"
            const candidates = [_][]const u8{
                "main/default",
                ".",
                "force-app/main/default",
                "src/main/default",
            };
            // Also try from parent directories
            const base_paths = [_][]const u8{ base_path, parent1, parent2, parent3 };
            for (base_paths) |bp| {
                for (candidates) |sub| {
                    const xml_path = std.fs.path.join(
                        self.arena,
                        &.{ bp, sub, suffix },
                    ) catch continue;
                    const content = std.Io.Dir.cwd().readFileAlloc(
                        self.io,
                        xml_path,
                        self.arena,
                        .limited(512 * 1024),
                    ) catch continue;
                    if (find_picklist_label_in_xml(content, api_name)) |label| {
                        return label;
                    }
                }
            }
        }
        return null;
    }

    fn find_picklist_label_in_xml(content: []const u8, api_name: []const u8) ?[]const u8 {
        var pos: usize = 0;
        while (pos < content.len) {
            const value_start = std.mem.indexOfPos(
                u8,
                content,
                pos,
                "<value>",
            ) orelse break;
            const value_end = std.mem.indexOfPos(
                u8,
                content,
                value_start,
                "</value>",
            ) orelse break;
            const block = content[value_start..value_end];
            if (find_picklist_label_in_value_block(block, api_name)) |label| {
                return label;
            }
            pos = value_end + 8;
        }
        return null;
    }

    fn find_picklist_label_in_value_block(block: []const u8, api_name: []const u8) ?[]const u8 {
        const fn_tag = "<fullName>";
        const fn_end_tag = "</fullName>";
        const fn_start = std.mem.indexOf(u8, block, fn_tag) orelse return null;
        const fn_content_start = fn_start + fn_tag.len;
        const fn_end = std.mem.indexOfPos(
            u8,
            block,
            fn_content_start,
            fn_end_tag,
        ) orelse return null;
        const full_name = block[fn_content_start..fn_end];
        if (!std.mem.eql(u8, full_name, api_name)) return null;

        const lbl_tag = "<label>";
        const lbl_end_tag = "</label>";
        const lbl_start = std.mem.indexOf(u8, block, lbl_tag) orelse return null;
        const lbl_content_start = lbl_start + lbl_tag.len;
        const lbl_end = std.mem.indexOfPos(
            u8,
            block,
            lbl_content_start,
            lbl_end_tag,
        ) orelse return null;
        return block[lbl_content_start..lbl_end];
    }

    /// Create a synthetic Profile record — used by SOQL when no Profile records exist in store
    pub fn create_current_profile_record(self: *Evaluator) !Value {
        const profile = try self.arena.create(types.SObject);
        profile.* = .{ .type_name = "Profile", .id = self.current_profile_id };
        try profile.fields.put(self.arena, "Id", Value{ .string = self.current_profile_id });
        try self.populate_synthetic_profile(profile, "System Administrator");
        return Value{ .sobject = profile };
    }

    /// Create a synthetic Profile record — used by SOQL when no Profile records exist in store
    pub fn create_default_profile_record(self: *Evaluator) !Value {
        return self.create_current_profile_record();
    }

    /// Create a synthetic Profile matching the WHERE clause Name — used by SOQL seeding.
    /// Falls back to "System Administrator" if no Name condition is found.
    fn create_profile_for_query(self: *Evaluator, soql: []const u8, current_env: *Env) !Value {
        if (self.extract_where_field_value(soql, "Id", current_env)) |profile_id| {
            if (std.ascii.eqlIgnoreCase(profile_id, self.current_profile_id)) {
                return self.create_current_profile_record();
            }
        }
        const profile = try self.arena.create(types.SObject);
        profile.* = .{ .type_name = "Profile" };
        // Extract Name value from WHERE clause: WHERE Name = 'Xyz' or WHERE Name = :var
        const profile_name =
            self.extract_where_field_value(soql, "Name", current_env) orelse
            "System Administrator";
        const profile_id = try self.alloc_id();
        profile.id = profile_id;
        try profile.fields.put(self.arena, "Id", Value{ .string = profile_id });
        try self.populate_synthetic_profile(profile, profile_name);
        try self.apply_queried_synthetic_profile_flags(profile, soql, current_env);
        return Value{ .sobject = profile };
    }

    fn populate_synthetic_profile(
        self: *Evaluator,
        profile: *types.SObject,
        profile_name: []const u8,
    ) !void {
        try profile.fields.put(self.arena, "Name", Value{ .string = profile_name });

        const is_guest_profile = std.ascii.indexOfIgnoreCase(profile_name, "Guest") != null;
        try profile.fields.put(
            self.arena,
            "UserType",
            Value{ .string = if (is_guest_profile) "Guest" else "Standard" },
        );
        if (!is_guest_profile) {
            try profile.fields.put(
                self.arena,
                "PermissionsPrivacyDataAccess",
                Value{ .boolean = false },
            );
            try profile.fields.put(
                self.arena,
                "PermissionsSubmitMacrosAllowed",
                Value{ .boolean = true },
            );
            try profile.fields.put(
                self.arena,
                "PermissionsMassInlineEdit",
                Value{ .boolean = true },
            );
        }

        const license = try self.arena.create(types.SObject);
        const license_id = try std.fmt.allocPrint(self.arena, "0LQ{d:0>15}", .{self.next_id});
        self.next_id += 1;
        license.* = .{ .type_name = "UserLicense", .id = license_id };
        try license.fields.put(self.arena, "Id", Value{ .string = license_id });
        if (is_guest_profile) {
            try license.fields.put(self.arena, "Name", Value{ .string = "Guest User License" });
            try license.fields.put(
                self.arena,
                "LicenseDefinitionKey",
                Value{ .string = "PID_Guest_User" },
            );
        } else {
            try license.fields.put(self.arena, "Name", Value{ .string = "Salesforce" });
            try license.fields.put(self.arena, "LicenseDefinitionKey", Value{ .string = "SFDC" });
        }
        try profile.fields.put(self.arena, "UserLicenseId", Value{ .string = license_id });
        try profile.fields.put(self.arena, "UserLicense", Value{ .sobject = license });
    }

    fn apply_queried_synthetic_profile_flags(
        self: *Evaluator,
        profile: *types.SObject,
        soql: []const u8,
        current_env: *Env,
    ) !void {
        const where_clause = extract_where_clause(soql) orelse return;
        var seen: std.StringArrayHashMapUnmanaged(void) = .empty;
        var pos: usize = 0;
        while (pos < where_clause.len) : (pos += 1) {
            if (!std.mem.startsWith(u8, where_clause[pos..], "Permissions")) continue;
            var end = pos + "Permissions".len;
            while (end < where_clause.len) : (end += 1) {
                const ch = where_clause[end];
                if (!std.ascii.isAlphanumeric(ch) and ch != '_') break;
            }
            const field_name = where_clause[pos..end];
            if (field_name.len == "Permissions".len) continue;
            if (seen.contains(field_name)) {
                pos = end - 1;
                continue;
            }
            try seen.put(self.arena, field_name, {});
            if (self.extract_where_field_value(soql, field_name, current_env)) |raw_value| {
                if (std.ascii.eqlIgnoreCase(raw_value, "true")) {
                    try profile.fields.put(self.arena, field_name, Value{ .boolean = true });
                } else if (std.ascii.eqlIgnoreCase(raw_value, "false")) {
                    try profile.fields.put(self.arena, field_name, Value{ .boolean = false });
                } else {
                    try profile.fields.put(self.arena, field_name, Value{ .string = raw_value });
                }
            }
            pos = end - 1;
        }
    }

    fn find_profile_by_name(self: *Evaluator, profile_name: []const u8) ?*types.SObject {
        if (self.store.get("Profile")) |profiles| {
            for (profiles.items) |record| {
                if (record != .sobject) continue;
                if (utils.sobject_get(&record.sobject.fields, "Name")) |name| {
                    if (name == .string and std.ascii.eqlIgnoreCase(name.string, profile_name)) {
                        return record.sobject;
                    }
                }
            }
        }
        return null;
    }

    fn is_guest_user_id(self: *Evaluator, user_id: []const u8) bool {
        if (self.store.get("User")) |users| {
            for (users.items) |record| {
                if (record != .sobject or record.sobject.id == null) continue;
                if (!std.ascii.eqlIgnoreCase(record.sobject.id.?, user_id)) continue;
                if (utils.sobject_get(&record.sobject.fields, "UserType")) |user_type| {
                    if (user_type == .string and
                        std.ascii.eqlIgnoreCase(user_type.string, "Guest"))
                    {
                        return true;
                    }
                }
                if (utils.sobject_get(&record.sobject.fields, "Profile")) |profile_val| {
                    if (profile_val == .sobject) {
                        if (utils.sobject_get(
                            &profile_val.sobject.fields,
                            "UserType",
                        )) |profile_user_type| {
                            if (profile_user_type == .string and
                                std.ascii.eqlIgnoreCase(profile_user_type.string, "Guest"))
                            {
                                return true;
                            }
                        }
                    }
                }
                return false;
            }
        }
        return false;
    }

    fn has_exact_where_field_comparison(
        self: *Evaluator,
        soql: []const u8,
        field_name: []const u8,
    ) bool {
        _ = self;
        const where_clause = extract_where_clause(soql) orelse return false;
        var pos: usize = 0;
        while (pos + field_name.len <= where_clause.len) : (pos += 1) {
            if (!std.ascii.eqlIgnoreCase(
                where_clause[pos .. pos + field_name.len],
                field_name,
            )) continue;
            if (!(pos == 0 or
                is_soql_whitespace(where_clause[pos - 1]) or
                where_clause[pos - 1] == '(')) continue;
            var j = pos + field_name.len;
            while (j < where_clause.len and is_soql_whitespace(where_clause[j])) j += 1;
            if (j < where_clause.len and where_clause[j] == '=') return true;
        }
        return false;
    }

    fn has_where_field_like_comparison(
        self: *Evaluator,
        soql: []const u8,
        field_name: []const u8,
    ) bool {
        _ = self;
        const where_clause = extract_where_clause(soql) orelse return false;
        var pos: usize = 0;
        while (pos + field_name.len <= where_clause.len) : (pos += 1) {
            if (!std.ascii.eqlIgnoreCase(
                where_clause[pos .. pos + field_name.len],
                field_name,
            )) continue;
            if (!(pos == 0 or
                is_soql_whitespace(where_clause[pos - 1]) or
                where_clause[pos - 1] == '(')) continue;
            var j = pos + field_name.len;
            while (j < where_clause.len and is_soql_whitespace(where_clause[j])) j += 1;
            if (j + 4 <= where_clause.len and
                std.ascii.eqlIgnoreCase(where_clause[j .. j + 4], "LIKE"))
            {
                return true;
            }
        }
        return false;
    }

    fn collapse_like_wildcards(self: *Evaluator, pattern: []const u8) []const u8 {
        var has_repeated_percent = false;
        var prev_was_percent = false;
        for (pattern) |ch| {
            if (ch == '%') {
                if (prev_was_percent) {
                    has_repeated_percent = true;
                    break;
                }
                prev_was_percent = true;
            } else {
                prev_was_percent = false;
            }
        }
        if (!has_repeated_percent) return pattern;

        const buf = self.arena.alloc(u8, pattern.len) catch return pattern;
        var write_idx: usize = 0;
        prev_was_percent = false;
        for (pattern) |ch| {
            if (ch == '%') {
                if (prev_was_percent) continue;
                prev_was_percent = true;
            } else {
                prev_was_percent = false;
            }
            buf[write_idx] = ch;
            write_idx += 1;
        }
        return buf[0..write_idx];
    }

    fn create_user_for_query(self: *Evaluator, soql: []const u8, current_env: *Env) !Value {
        if (self.query_matches_default_synthetic_user(soql, current_env)) {
            return self.create_default_user_record();
        }
        if (self.query_matches_current_user(soql, current_env)) {
            return self.create_current_user_record();
        }
        const user = try self.arena.create(types.SObject);
        const alias = self.extract_where_field_value(soql, "Alias", current_env) orelse "tuser";
        const username =
            self.extract_where_field_value(soql, "Username", current_env) orelse
            if (std.ascii.startsWithIgnoreCase(alias, "autoproc"))
                "autoproc@example.com"
            else
                "testuser@example.com";
        const user_id = try std.fmt.allocPrint(self.arena, "005{d:0>15}", .{self.next_id});
        self.next_id += 1;
        user.* = .{ .type_name = "User", .id = user_id };
        try user.fields.put(self.arena, "Id", Value{ .string = user_id });
        try user.fields.put(self.arena, "Username", Value{ .string = username });
        try user.fields.put(self.arena, "Email", Value{ .string = username });
        try user.fields.put(self.arena, "Alias", Value{ .string = alias });
        try user.fields.put(self.arena, "TimeZoneSidKey", Value{ .string = "America/Los_Angeles" });

        const is_automated_process =
            std.ascii.startsWithIgnoreCase(username, "autoproc@") or
            std.ascii.startsWithIgnoreCase(alias, "autoproc");
        const has_null_profile =
            self.has_where_field_null_literal(soql, "Profile.Name");
        const profile_name_opt =
            if (self.has_exact_where_field_comparison(soql, "Profile.Name") and
            !has_null_profile)
                self.extract_where_field_value(soql, "Profile.Name", current_env)
            else
                null;
        const explicit_user_type =
            if (self.has_exact_where_field_comparison(soql, "Profile.UserType"))
                self.extract_where_field_value(soql, "Profile.UserType", current_env)
            else if (self.has_exact_where_field_comparison(soql, "UserType"))
                self.extract_where_field_value(soql, "UserType", current_env)
            else
                null;

        const should_materialize_profile =
            (!is_automated_process and !has_null_profile) or
            profile_name_opt != null or
            explicit_user_type != null;
        if (should_materialize_profile) {
            try self.attach_synthetic_profile_to_user(user, profile_name_opt, explicit_user_type);
        } else {
            try user.fields.put(
                self.arena,
                "UserType",
                Value{ .string = "AutomatedProcess" },
            );
        }

        try user.fields.put(self.arena, "FirstName", Value{ .string = "Test" });
        try user.fields.put(
            self.arena,
            "LastName",
            Value{ .string = if (is_automated_process) "Process" else "User" },
        );
        try user.fields.put(
            self.arena,
            "Name",
            Value{ .string = if (is_automated_process) "Automated Process" else "Test User" },
        );
        return Value{ .sobject = user };
    }

    /// `create_user_for_query` から抽出。`Profile.Name` / `UserType` の WHERE
    /// ヒントに基づいてプロファイル SObject を生成（またはキャッシュから取得）し、
    /// 合成ユーザーレコードに `ProfileId` / `Profile` / `UserType` を紐付ける。
    fn attach_synthetic_profile_to_user(
        self: *Evaluator,
        user: *types.SObject,
        profile_name_opt: ?[]const u8,
        explicit_user_type: ?[]const u8,
    ) !void {
        const profile_name =
            profile_name_opt orelse if (explicit_user_type) |user_type|
                (if (std.ascii.eqlIgnoreCase(user_type, "Guest"))
                    "Logger Test LWR Site Guest Profile"
                else
                    "Standard User")
            else
                "Standard User";
        const profile = if (self.find_profile_by_name(profile_name)) |existing|
            existing
        else blk: {
            const created = try self.arena.create(types.SObject);
            const profile_id = try std.fmt.allocPrint(self.arena, "00e{d:0>15}", .{self.next_id});
            self.next_id += 1;
            created.* = .{ .type_name = "Profile", .id = profile_id };
            try created.fields.put(self.arena, "Id", Value{ .string = profile_id });
            try self.populate_synthetic_profile(created, profile_name);
            const gop = try self.store.getOrPut(self.arena, "Profile");
            if (!gop.found_existing) gop.value_ptr.* = .empty;
            try gop.value_ptr.append(self.arena, Value{ .sobject = created });
            break :blk created;
        };
        if (explicit_user_type) |user_type| {
            try profile.fields.put(self.arena, "UserType", Value{ .string = user_type });
        }
        try user.fields.put(self.arena, "ProfileId", Value{ .string = profile.id.? });
        try user.fields.put(self.arena, "Profile", Value{ .sobject = profile });
        if (utils.sobject_get(&profile.fields, "UserType")) |profile_user_type| {
            try user.fields.put(self.arena, "UserType", profile_user_type);
        }
    }

    fn append_record_ids_from_value(
        self: *Evaluator,
        value: Value,
        record_ids: *std.ArrayListUnmanaged([]const u8),
    ) !void {
        switch (value) {
            .string => |s| if (s.len > 0) try record_ids.append(self.arena, s),
            .sobject => |sob| if (sob.id) |id| try record_ids.append(self.arena, id),
            .list => |list| {
                for (list.items.items) |item| {
                    try self.append_record_ids_from_value(item, record_ids);
                }
            },
            .set => |set| {
                for (set.entries.values()) |item| {
                    try self.append_record_ids_from_value(item, record_ids);
                }
            },
            .map => |map| {
                for (map.entries.keys()) |key| {
                    if (key.len > 0) try record_ids.append(self.arena, key);
                }
            },
            else => {
                const coerced = utils.coerce_to_string(value, self.arena) catch return;
                if (coerced.len > 0) try record_ids.append(self.arena, coerced);
            },
        }
    }

    fn can_delete_record_via_user_record_access(self: *Evaluator, record_id: []const u8) bool {
        const type_name = self.find_record_type_by_id(record_id) orelse blk: {
            if (record_id.len < 3) break :blk "SObject";
            break :blk sobject_type_from_prefix(record_id[0..3]);
        };
        if (std.ascii.eqlIgnoreCase(type_name, "SObject")) return false;
        if (std.ascii.eqlIgnoreCase(type_name, "User")) return false;
        if (self.is_setup_object(type_name)) return false;
        return true;
    }

    fn seed_user_record_access_records(
        self: *Evaluator,
        soql: []const u8,
        current_env: *Env,
        records: *std.ArrayListUnmanaged(Value),
    ) !void {
        const where_clause = extract_where_clause(soql) orelse return;
        const requested_user_id =
            self.extract_where_field_value(soql, "UserId", current_env) orelse blk: {
                if (std.ascii.indexOfIgnoreCase(
                    where_clause,
                    "UserId = :System.UserInfo.getUserId()",
                ) != null) {
                    break :blk self.current_user_id;
                }
                break :blk null;
            };
        if (requested_user_id) |user_id| {
            if (!std.ascii.eqlIgnoreCase(user_id, self.current_user_id)) return;
        }

        var record_ids: std.ArrayListUnmanaged([]const u8) = .empty;
        if (std.ascii.indexOfIgnoreCase(where_clause, "RecordId IN :")) |in_pos| {
            var j = in_pos + "RecordId IN :".len;
            const start = j;
            j = scan_bind_expression_end(where_clause, j);
            if (j > start) {
                if (self.lookup_bind_value(current_env, where_clause[start..j])) |bind_val| {
                    try self.append_record_ids_from_value(bind_val, &record_ids);
                }
            }
        }
        if (record_ids.items.len == 0) {
            if (self.extract_where_field_value(soql, "RecordId", current_env)) |record_id| {
                try record_ids.append(self.arena, record_id);
            }
        }

        for (record_ids.items) |record_id| {
            const access = try self.arena.create(types.SObject);
            const access_id = try self.alloc_id();
            const has_delete_access = self.can_delete_record_via_user_record_access(record_id);
            access.* = .{ .type_name = "UserRecordAccess", .id = access_id };
            try access.fields.put(self.arena, "Id", Value{ .string = access_id });
            try access.fields.put(self.arena, "UserId", Value{ .string = self.current_user_id });
            try access.fields.put(self.arena, "RecordId", Value{ .string = record_id });
            try access.fields.put(
                self.arena,
                "HasReadAccess",
                Value{ .boolean = has_delete_access },
            );
            try access.fields.put(
                self.arena,
                "HasEditAccess",
                Value{ .boolean = has_delete_access },
            );
            try access.fields.put(
                self.arena,
                "HasDeleteAccess",
                Value{ .boolean = has_delete_access },
            );

            const access_value = Value{ .sobject = access };
            if (self.matches_where(access_value, soql, current_env)) {
                try records.append(self.arena, access_value);
            }
        }
    }

    /// Seed stub records for setup objects queried with IN clause
    /// (PermissionSet, PermissionSetLicense, etc.).
    /// Extracts names from WHERE Name/DeveloperName IN (:var)
    /// or IN ('a','b') and creates a stub for each.
    fn seed_named_records(
        self: *Evaluator,
        obj_type: []const u8,
        soql: []const u8,
        current_env: *Env,
        records: *std.ArrayListUnmanaged(Value),
    ) !void {
        const where_clause = extract_where_clause(soql) orelse return;
        // Collect names from the IN clause
        // — supports both bind variables (Set/List) and literal lists
        var names: std.ArrayListUnmanaged([]const u8) = .empty;
        // Check for IN :var pattern
        if (std.ascii.indexOfIgnoreCase(where_clause, " IN :")) |in_pos| {
            var j = in_pos + 5; // skip " IN :"
            const start = j;
            j = scan_bind_expression_end(where_clause, j);
            if (j > start) {
                const var_name = where_clause[start..j];
                if (self.lookup_bind_value(current_env, var_name)) |val| {
                    if (val == .set) {
                        for (val.set.entries.values()) |item| {
                            if (item == .string) try names.append(self.arena, item.string);
                        }
                    } else if (val == .list) {
                        for (val.list.items.items) |item| {
                            if (item == .string) try names.append(self.arena, item.string);
                        }
                    }
                }
            }
        }
        // Also check for IN ('a', 'b', 'c') pattern
        if (names.items.len == 0) {
            if (std.ascii.indexOfIgnoreCase(where_clause, " IN (")) |in_pos| {
                var j = in_pos + 5;
                while (j < where_clause.len and where_clause[j] != ')') {
                    while (j < where_clause.len and
                        where_clause[j] != '\'' and
                        where_clause[j] != ')') : (j += 1)
                    {}
                    if (j < where_clause.len and where_clause[j] == '\'') {
                        j += 1;
                        const start = j;
                        while (j < where_clause.len and where_clause[j] != '\'') j += 1;
                        if (j > start) try names.append(self.arena, where_clause[start..j]);
                        if (j < where_clause.len) j += 1;
                    }
                }
            }
        }
        // Create stub records for each name
        for (names.items) |name| {
            const stub = try self.arena.create(types.SObject);
            stub.* = .{ .type_name = obj_type };
            const stub_id = try self.alloc_id();
            stub.id = stub_id;
            try stub.fields.put(self.arena, "Id", Value{ .string = stub_id });
            try stub.fields.put(self.arena, "Name", Value{ .string = name });
            try stub.fields.put(self.arena, "DeveloperName", Value{ .string = name });
            try records.append(self.arena, Value{ .sobject = stub });
            // Also store in data store so subsequent queries can find them
            const gop = try self.store.getOrPut(self.arena, obj_type);
            if (!gop.found_existing) gop.value_ptr.* = .empty;
            try gop.value_ptr.append(self.arena, Value{ .sobject = stub });
        }
    }

    /// Seed synthetic RecordType records into the store for all known SObject types.
    /// IDs are kept in sync with createRecordTypeInfo/createDescribeResult in builtins.zig.
    fn seed_record_type_store(self: *Evaluator) !void {
        const gop = try self.store.getOrPut(self.arena, "RecordType");
        if (!gop.found_existing) gop.value_ptr.* = .empty;
        if (gop.value_ptr.items.len > 0) return; // already seeded

        // Each SObject type gets a Master RecordType with a unique ID based on index.
        // Only seed types that typically carry record types in real orgs —
        // Task/Event/User/Solution rarely do, and pre-seeding them surfaces
        // the Master/Default pair to utility classes whose own `uses record
        // types` heuristic relies on `Database.countQuery` being zero when
        // none are configured.
        const known_types = [_][]const u8{
            "Account", "Contact", "Opportunity", "Lead", "Case", "Campaign",
        };
        for (known_types, 0..) |obj_name, idx| {
            // Master RecordType — unique ID per SObject type
            const master = try self.arena.create(types.SObject);
            master.* = .{ .type_name = "RecordType" };
            const master_id = try std.fmt.allocPrint(self.arena, "0120000000000{d:0>2}AAA", .{idx});
            master.id = master_id;
            try master.fields.put(self.arena, "Id", Value{ .string = master_id });
            try master.fields.put(self.arena, "Name", Value{ .string = "Master" });
            try master.fields.put(self.arena, "DeveloperName", Value{ .string = "Master" });
            try master.fields.put(self.arena, "SobjectType", Value{ .string = obj_name });
            try master.fields.put(self.arena, "IsActive", Value{ .boolean = true });
            try gop.value_ptr.append(self.arena, Value{ .sobject = master });

            // All known SObject types get an additional "Default" RecordType
            {
                const default_rt = try self.arena.create(types.SObject);
                default_rt.* = .{ .type_name = "RecordType" };
                const def_id = try std.fmt.allocPrint(
                    self.arena,
                    "0120000000001{d:0>2}AAA",
                    .{idx},
                );
                default_rt.id = def_id;
                try default_rt.fields.put(self.arena, "Id", Value{ .string = def_id });
                try default_rt.fields.put(self.arena, "Name", Value{ .string = "Default" });
                try default_rt.fields.put(
                    self.arena,
                    "DeveloperName",
                    Value{ .string = "Default" },
                );
                try default_rt.fields.put(
                    self.arena,
                    "SobjectType",
                    Value{ .string = obj_name },
                );
                try default_rt.fields.put(
                    self.arena,
                    "IsActive",
                    Value{ .boolean = true },
                );
                try gop.value_ptr.append(self.arena, Value{ .sobject = default_rt });
            }
        }
    }

    /// Convert picklist field values from API name (fullName) to label on custom objects.
    fn convert_picklist_values(self: *Evaluator, obj: *types.SObject) !void {
        if (!std.mem.endsWith(u8, obj.type_name, "__c")) return;
        for (obj.fields.keys(), obj.fields.values()) |field_name, *field_val| {
            if (field_val.* != .string or !std.mem.endsWith(u8, field_name, "__c")) continue;
            if (self.resolve_picklist_label(obj.type_name, field_name, field_val.string)) |label| {
                field_val.* = Value{ .string = label };
            }
        }
    }

    /// Re-initialize static fields for a single class (test class reset)
    pub fn re_init_class_static_fields(self: *Evaluator, cd: *ast.ClassDecl) void {
        const saved_class = self.current_class;
        self.current_class = cd.name;
        defer self.current_class = saved_class;
        // Protect caller's stack-trace state: static initializers may evaluate
        // `new_expr` which clobbers current_call_line and the top frame's line.
        const saved_call_line = self.current_call_line;
        const saved_top_line: ?u32 = if (self.call_stack.items.len > 0)
            self.call_stack.items[self.call_stack.items.len - 1].line
        else
            null;
        defer {
            self.current_call_line = saved_call_line;
            if (saved_top_line) |tl| {
                if (self.call_stack.items.len > 0)
                    self.call_stack.items[self.call_stack.items.len - 1].line = tl;
            }
        }
        // Initialize static fields in declaration order, then re-run any initializer
        // whose result was `null_val` in case it referenced a later-declared field.
        // This matches Apex's behaviour where `X = Y.method()` pairs with a later
        // `Y = ...` declaration without a compile error.
        for (cd.members) |member| {
            switch (member) {
                .field_decl => |fd| {
                    if (fd.modifiers.is_static) {
                        const val = if (fd.initializer) |init_expr|
                            self.eval_expr(init_expr, self.global_env) catch Value.null_val
                        else
                            default_value(fd.type_ref);
                        const key = std.fmt.allocPrint(
                            self.arena,
                            "{s}.{s}",
                            .{ cd.name, fd.name },
                        ) catch continue;
                        self.global_env.set(key, val) catch {
                            self.global_env.define(key, val) catch {};
                        };
                    }
                },
                else => {},
            }
        }
        self.retry_class_static_field_initializers(cd);
    }

    fn retry_class_static_field_initializers(
        self: *Evaluator,
        cd: *ast.ClassDecl,
    ) void {
        // Second pass: retry initializers that produced null but had a real expression.
        // Bounded retry guards against circular references.
        var retry_attempts: u8 = 0;
        while (retry_attempts < 4) : (retry_attempts += 1) {
            var made_progress = false;
            for (cd.members) |member| {
                switch (member) {
                    .field_decl => |fd| {
                        if (!fd.modifiers.is_static) continue;
                        const init_expr = fd.initializer orelse continue;
                        const key = std.fmt.allocPrint(
                            self.arena,
                            "{s}.{s}",
                            .{ cd.name, fd.name },
                        ) catch continue;
                        const current = self.global_env.get(key) orelse Value.null_val;
                        if (current != .null_val) continue;
                        const val =
                            self.eval_expr(init_expr, self.global_env) catch Value.null_val;
                        if (val == .null_val) continue;
                        self.global_env.set(key, val) catch {
                            self.global_env.define(key, val) catch {};
                        };
                        made_progress = true;
                    },
                    else => {},
                }
            }
            if (!made_progress) break;
        }
    }

    /// Register static field placeholders (null values) without evaluating initializers.
    /// Used to prepare global_env keys so that lazy init can later fill in real values.
    pub fn register_static_field_placeholders(self: *Evaluator, cd: *ast.ClassDecl) void {
        for (cd.members) |member| {
            switch (member) {
                .field_decl => |fd| {
                    if (fd.modifiers.is_static) {
                        const key = std.fmt.allocPrint(
                            self.arena,
                            "{s}.{s}",
                            .{ cd.name, fd.name },
                        ) catch continue;
                        self.global_env.define(key, default_value(fd.type_ref)) catch {};
                    }
                },
                else => {},
            }
        }
    }

    /// Resolve a class name to its fully-qualified form
    /// (e.g., "InnerClass" → "OuterClass.InnerClass").
    /// If the name already contains a dot or no FQ match is found, returns the original name.
    fn resolve_full_class_name(self: *Evaluator, name: []const u8) []const u8 {
        if (std.mem.indexOfScalar(u8, name, '.') != null) return name;
        var iter = self.classes.iterator();
        while (iter.next()) |entry| {
            const key = entry.key_ptr.*;
            // Look for "Outer.Name" pattern where Name matches
            if (std.mem.indexOfScalar(u8, key, '.')) |di| {
                if (std.ascii.eqlIgnoreCase(key[di + 1 ..], name)) return key;
            }
        }
        return name;
    }

    fn simple_class_name(name: []const u8) []const u8 {
        if (std.mem.lastIndexOfScalar(u8, name, '.')) |di| return name[di + 1 ..];
        return name;
    }

    fn has_top_level_class(self: *Evaluator, name: []const u8) bool {
        for (self.class_sources.keys()) |class_name| {
            if (std.ascii.eqlIgnoreCase(class_name, name)) return true;
        }
        return false;
    }

    fn find_inner_class_fq(
        self: *Evaluator,
        outer_name: []const u8,
        simple_name: []const u8,
    ) ?[]const u8 {
        const outer_decl = self.find_class(outer_name) orelse return null;
        for (outer_decl.members) |member| {
            switch (member) {
                .class_decl => |inner_cd| {
                    if (std.ascii.eqlIgnoreCase(inner_cd.name, simple_name)) {
                        return std.fmt.allocPrint(
                            self.arena,
                            "{s}.{s}",
                            .{ outer_name, inner_cd.name },
                        ) catch null;
                    }
                },
                else => {},
            }
        }
        return null;
    }

    fn resolve_visible_user_class_in_scope(
        self: *Evaluator,
        current_env: ?*Env,
        simple_name: []const u8,
    ) ?[]const u8 {
        if (std.mem.indexOfScalar(u8, simple_name, '.') != null) {
            if (self.find_class(simple_name) != null) return simple_name;
            return null;
        }

        const scope_class = blk: {
            if (current_env) |env| {
                if (env.get_this()) |this_val| {
                    if (this_val == .object) break :blk this_val.object.class_name;
                }
            }
            break :blk self.current_class;
        };

        if (scope_class) |scope_name| {
            if (std.ascii.eqlIgnoreCase(simple_class_name(scope_name), simple_name)) {
                return scope_name;
            }
            if (self.find_inner_class_fq(scope_name, simple_name)) |fq| return fq;
            if (self.find_outer_class_name(scope_name)) |outer_name| {
                if (std.ascii.eqlIgnoreCase(simple_class_name(outer_name), simple_name)) {
                    return outer_name;
                }
                if (self.find_inner_class_fq(outer_name, simple_name)) |fq| return fq;
            }
        }

        if (self.has_top_level_class(simple_name)) return simple_name;
        return null;
    }

    fn is_builtin_static_namespace(simple_name: []const u8) bool {
        const builtin_names = [_][]const u8{
            "System",      "String",       "Id",          "Integer",
            "Long",        "Boolean",      "Decimal",     "Double",
            "Date",        "Math",         "Time",        "TimeZone",
            "DateTime",    "JSON",         "UserInfo",    "LoggingLevel",
            "Quiddity",    "UUID",         "OrgLimits",   "Database",
            "RestContext", "HttpResponse", "HttpRequest", "Schema",
            "Security",    "AccessLevel",  "ConnectApi",  "FeatureManagement",
            "Limits",      "Script",       "Pattern",     "Type",
            "Request",     "Crypto",       "Blob",        "EncodingUtil",
            "Messaging",   "EventBus",     "Test",        "Cache",
            "Http",        "CanTheUser",   "OrgShape",    "ApexPages",
            "Network",     "Url",          "URL",         "AccessType",
        };
        inline for (builtin_names) |builtin_name| {
            if (std.ascii.eqlIgnoreCase(simple_name, builtin_name)) return true;
        }
        return false;
    }

    /// Build a Salesforce-format stack trace string for a constructed Exception.
    /// Format: "Class.ClassName.methodName: line N, column 1\n..."
    /// Exceptions created inside constructors only expose the constructor and
    /// its immediate caller; otherwise Apex preserves the surrounding call
    /// stack and appends the synthetic anonymous entry point.
    pub fn build_stack_trace_string(self: *Evaluator) ![]const u8 {
        var buf: std.ArrayListUnmanaged(u8) = .empty;
        var i: usize = self.call_stack.items.len;
        const max_frames = blk: {
            if (self.call_stack.items.len == 0) break :blk @as(usize, 0);
            const top = self.call_stack.items[self.call_stack.items.len - 1];
            if (std.mem.eql(u8, top.method_name, "<init>")) break :blk @as(usize, 2);
            break :blk self.call_stack.items.len;
        };
        var emitted_frames: usize = 0;
        while (i > 0 and emitted_frames < max_frames) {
            i -= 1;
            const f = self.call_stack.items[i];
            if (buf.items.len > 0) try buf.append(self.arena, '\n');
            const fq = self.resolve_full_class_name(f.class_name);
            const line = if (f.line > 0) f.line else 1;
            const entry = try std.fmt.allocPrint(
                self.arena,
                "Class.{s}.{s}: line {d}, column 1",
                .{ fq, f.method_name, line },
            );
            try buf.appendSlice(self.arena, entry);
            emitted_frames += 1;
        }
        if (buf.items.len > 0) try buf.append(self.arena, '\n');
        try buf.appendSlice(self.arena, "AnonymousBlock: line 1, column 1");
        return buf.items;
    }

    /// Lazily ensure a class's static fields and static init blocks have been evaluated.
    /// Called on first access to a class (method call, field access, or instantiation).
    pub fn ensure_static_init(self: *Evaluator, class_name: []const u8) void {
        // Fast path: already initialized
        if (self.static_inited.get(class_name) != null) return;
        // Case-insensitive lookup
        var iter = self.classes.iterator();
        while (iter.next()) |entry| {
            if (std.ascii.eqlIgnoreCase(entry.key_ptr.*, class_name)) {
                if (self.static_inited.get(entry.key_ptr.*) != null) return;
                const cd = entry.value_ptr.*;
                // Mark as initialized BEFORE evaluating to prevent infinite recursion
                // on circular static dependencies (matches Salesforce behavior: circular
                // deps see null/default for the not-yet-evaluated class).
                self.static_inited.put(self.arena, entry.key_ptr.*, {}) catch return;
                self.re_init_class_static_fields(cd);
                self.run_class_static_inits(cd);
                return;
            }
        }
    }

    /// Run static init blocks for a single class
    pub fn run_class_static_inits(self: *Evaluator, cd: *ast.ClassDecl) void {
        const saved_class = self.current_class;
        self.current_class = cd.name;
        defer self.current_class = saved_class;

        for (cd.members) |member| {
            switch (member) {
                .static_init => |body| {
                    self.run_static_init_body(cd, body);
                },
                else => {},
            }
        }
    }

    // -----------------------------------------------------------------------
    // トップレベル
    // -----------------------------------------------------------------------

    pub fn load_decls(self: *Evaluator, decls: []const ast.Decl) anyerror!void {
        const ca = self.class_arena orelse self.arena;
        // Pass 1: Register all classes, inner classes, enums, and static field placeholders
        for (decls) |decl| {
            switch (decl) {
                .class_decl => |cd| {
                    try self.register_class_recursive(ca, cd, null);
                },
                .trigger_decl => |td| {
                    const obj_lower = std.ascii.lowerString(
                        self.arena.alloc(u8, td.object_name.len) catch continue,
                        td.object_name,
                    );
                    const gop = self.triggers.getOrPut(self.arena, obj_lower) catch continue;
                    if (!gop.found_existing) gop.value_ptr.* = .empty;
                    gop.value_ptr.append(self.arena, td) catch {};
                },
                else => {},
            }
        }
        // Pass 2 is deferred: static field initializers and static init blocks
        // are evaluated lazily via ensureStaticInit() on first class access.
        // This matches Salesforce behavior where static initialization happens
        // when a class is first referenced, not at load time.
    }

    /// Register source code for a class (used for ApexClass.Body queries)
    pub fn register_class_source(
        self: *Evaluator,
        class_name: []const u8,
        source: []const u8,
    ) !void {
        try self.class_sources.put(self.arena, class_name, source);
    }

    pub fn register_trigger_source(
        self: *Evaluator,
        trigger_name: []const u8,
        source: []const u8,
    ) !void {
        try self.trigger_sources.put(self.arena, trigger_name, source);
    }

    /// Execute all static initializer blocks. Should be called after all files are loaded.
    pub fn run_static_inits(self: *Evaluator) void {
        var class_iter = self.classes.iterator();
        while (class_iter.next()) |entry| {
            const cd = entry.value_ptr.*;
            for (cd.members) |member| {
                switch (member) {
                    .static_init => |body| {
                        self.run_static_init_body(cd, body);
                    },
                    else => {},
                }
            }
        }
    }

    fn run_static_init_body(self: *Evaluator, cd: *ast.ClassDecl, body: []const ast.Stmt) void {
        const init_env = self.global_env.child() catch return;
        var static_keys: std.ArrayListUnmanaged([]const u8) = .empty;
        var original_values: std.ArrayListUnmanaged(Value) = .empty;

        for (cd.members) |member| {
            switch (member) {
                .field_decl => |fd| {
                    if (fd.modifiers.is_static) {
                        const key = std.fmt.allocPrint(
                            self.arena,
                            "{s}.{s}",
                            .{ cd.name, fd.name },
                        ) catch continue;
                        const cur = self.global_env.get(key) orelse Value.null_val;
                        static_keys.append(self.arena, key) catch continue;
                        original_values.append(self.arena, cur) catch continue;
                        init_env.define(fd.name, cur) catch {};
                    }
                },
                else => {},
            }
        }

        _ = self.exec_block(body, init_env) catch {};

        var static_index: usize = 0;
        for (cd.members) |member| {
            switch (member) {
                .field_decl => |fd| {
                    if (fd.modifiers.is_static) {
                        const key = if (static_index < static_keys.items.len)
                            static_keys.items[static_index]
                        else
                            std.fmt.allocPrint(
                                self.arena,
                                "{s}.{s}",
                                .{ cd.name, fd.name },
                            ) catch continue;
                        const original_value = if (static_index < original_values.items.len)
                            original_values.items[static_index]
                        else
                            Value.null_val;
                        static_index += 1;
                        const local_value = init_env.get(fd.name) orelse Value.null_val;
                        const global_value = self.global_env.get(key) orelse Value.null_val;
                        const writeback_value =
                            if (!utils.value_eql(local_value, original_value))
                                local_value
                            else
                                global_value;
                        self.global_env.set(key, writeback_value) catch {
                            self.global_env.define(key, writeback_value) catch {};
                        };
                    }
                },
                else => {},
            }
        }
    }

    pub fn call_method(
        self: *Evaluator,
        class_name: []const u8,
        method_name: []const u8,
        args: []const Value,
    ) anyerror!Value {
        self.call_depth +|= 1;
        defer self.call_depth -|= 1;

        if (self.call_depth > self.max_call_depth) {
            return .null_val;
        }
        // Push call frame for stack trace generation (use current_call_line set by caller)
        const frame_line = self.current_call_line;
        self.current_call_line = 0;
        try self.call_stack.append(self.arena, .{
            .class_name = class_name,
            .method_name = method_name,
            .line = frame_line,
        });
        defer _ = self.call_stack.pop();
        // Lazy static init: ensure the class's static fields/blocks are initialized
        self.ensure_static_init(class_name);
        if (self.find_class(class_name)) |cd| {
            if (cd.super_class) |sc| self.ensure_static_init(sc.name);
        }
        // EventBus.publish → store events in the store so they can be queried, and fire triggers
        if (std.ascii.eqlIgnoreCase(class_name, "EventBus") and
            std.ascii.eqlIgnoreCase(method_name, "publish"))
        {
            self.limits_publish_immediate += 1;
            const PublishResult = struct {
                success: bool,
                id: ?[]const u8,
            };
            const publish_one = struct {
                fn run(self_eval: *Evaluator, item: Value) !PublishResult {
                    if (item != .sobject) return .{ .success = false, .id = null };
                    self_eval.pending_exception = null;
                    self_eval.insert_record(item.sobject) catch |err| {
                        if (err == error.ApexException) {
                            self_eval.pending_exception = null;
                            return .{ .success = false, .id = null };
                        }
                        return err;
                    };
                    return .{
                        .success = true,
                        .id = self_eval.sobject_id_for_result(item.sobject),
                    };
                }
            }.run;

            const successful_items = try self.arena.create(types.ListValue);
            successful_items.* = .{};
            var any_publish_success = false;

            const result = if (args.len > 0 and args[0] == .list) blk: {
                const results = try self.arena.create(types.ListValue);
                results.* = .{};
                for (args[0].list.items.items) |item| {
                    const publish_result = try publish_one(self, item);
                    if (publish_result.success) {
                        any_publish_success = true;
                        try successful_items.items.append(self.arena, item);
                    }
                    try results.items.append(
                        self.arena,
                        try self.create_dml_result_value(
                            "Database.SaveResult",
                            publish_result.success,
                            publish_result.id,
                            null,
                        ),
                    );
                }
                break :blk Value{ .list = results };
            } else blk: {
                const publish_result: PublishResult = if (args.len > 0)
                    try publish_one(self, args[0])
                else
                    .{ .success = false, .id = null };
                if (publish_result.success and args.len > 0) {
                    any_publish_success = true;
                    try successful_items.items.append(self.arena, args[0]);
                }
                break :blk try self.create_dml_result_value(
                    "Database.SaveResult",
                    publish_result.success,
                    publish_result.id,
                    null,
                );
            };
            if (any_publish_success) {
                // Platform event triggers run in a separate transaction in Salesforce,
                // so save/restore DML/SOQL limits to avoid counting trigger DML in caller's limits.
                const event_type =
                    if (successful_items.items.items.len > 0 and
                    successful_items.items.items[0] == .sobject)
                        successful_items.items.items[0].sobject.type_name
                    else
                        null;
                if (event_type) |et| {
                    const saved_dml = self.limits_dml;
                    const saved_dml_rows = self.limits_dml_rows;
                    const saved_soql = self.limits_soql;
                    var record_list = try self.build_record_list(Value{ .list = successful_items });
                    self.fire_trigger(et, .after_insert, &record_list, null) catch {};
                    self.limits_dml = saved_dml;
                    self.limits_dml_rows = saved_dml_rows;
                    self.limits_soql = saved_soql;
                }
            }
            // If a callback is provided (second arg), store it for later
            // processing by Test.getEventBus()
            if (args.len >= 2 and args[1] == .object and any_publish_success) {
                const callback = args[1].object;
                // Store callback info for Test.getEventBus().fail() support
                self.pending_event_callback = .{
                    .callback = callback,
                    .event = if (args[0] == .sobject) args[0] else .null_val,
                };
                if (self.find_class(callback.class_name)) |cb_class| {
                    // Build EventBus.PublishResult with EventUuids
                    const pub_result = try self.arena.create(types.ObjectInstance);
                    pub_result.* = .{ .class_name = "EventBus.PublishResult" };
                    const uuid_list = try self.arena.create(types.ListValue);
                    uuid_list.* = .{};
                    // Add the EventUuid from the event
                    if (args[0] == .sobject) {
                        if (utils.sobject_get(&args[0].sobject.fields, "EventUuid")) |uuid_val| {
                            try uuid_list.items.append(self.arena, uuid_val);
                        }
                    }
                    try pub_result.fields.put(self.arena, "eventUuids", Value{ .list = uuid_list });
                    // Call onSuccess(result) on the callback (will be
                    // overridden by fail() if called)
                    _ = self.call_instance_method(
                        cb_class,
                        callback,
                        "onSuccess",
                        &.{Value{ .object = pub_result }},
                    ) catch {};
                }
            }
            if (args.len > 0) {
                const clearLiveEventId = struct {
                    fn run(item: Value) void {
                        if (item != .sobject) return;
                        if (!std.mem.endsWith(u8, item.sobject.type_name, "__e")) return;
                        _ = item.sobject.fields.orderedRemove("Id");
                    }
                }.run;
                if (args[0] == .sobject) {
                    clearLiveEventId(args[0]);
                } else if (args[0] == .list) {
                    for (args[0].list.items.items) |item| clearLiveEventId(item);
                }
            }
            return result;
        }
        if ((std.ascii.eqlIgnoreCase(class_name, "Search") or
            std.ascii.eqlIgnoreCase(class_name, "System.Search")) and
            std.ascii.eqlIgnoreCase(method_name, "query"))
        {
            if (args.len > 0 and args[0] == .string) {
                return self.execute_sosl(args[0].string);
            }
            const outer = try self.arena.create(types.ListValue);
            outer.* = .{};
            return Value{ .list = outer };
        }

        // Custom Metadata Type: Type__mdt.getInstance(developerName) / getAll()
        if (std.mem.endsWith(u8, class_name, "__mdt")) {
            // Ensure records are loaded
            {
                var found_in_store = false;
                var si = self.store.iterator();
                while (si.next()) |entry| {
                    if (std.ascii.eqlIgnoreCase(entry.key_ptr.*, class_name)) {
                        found_in_store = true;
                        break;
                    }
                }
                if (!found_in_store) self.load_custom_metadata_from_files(class_name) catch {};
            }
            if (std.ascii.eqlIgnoreCase(method_name, "getInstance") and
                args.len > 0 and args[0] == .string)
            {
                const dev_name = args[0].string;
                var mdt_iter = self.store.iterator();
                while (mdt_iter.next()) |entry| {
                    if (std.ascii.eqlIgnoreCase(entry.key_ptr.*, class_name)) {
                        for (entry.value_ptr.items) |item| {
                            if (item == .sobject) {
                                if (utils.sobject_get(&item.sobject.fields, "DeveloperName")) |dn| {
                                    if (dn == .string and
                                        std.ascii.eqlIgnoreCase(dn.string, dev_name))
                                    {
                                        return item;
                                    }
                                }
                            }
                        }
                    }
                }
                return Value.null_val;
            }
            if (std.ascii.eqlIgnoreCase(method_name, "getAll")) {
                const map = try self.arena.create(types.MapValue);
                map.* = .{};
                var mdt_iter = self.store.iterator();
                while (mdt_iter.next()) |entry| {
                    if (std.ascii.eqlIgnoreCase(entry.key_ptr.*, class_name)) {
                        for (entry.value_ptr.items) |item| {
                            if (item == .sobject) {
                                if (utils.sobject_get(&item.sobject.fields, "DeveloperName")) |dn| {
                                    if (dn == .string) {
                                        try map.entries.put(self.arena, dn.string, item);
                                    }
                                }
                            }
                        }
                    }
                }
                return Value{ .map = map };
            }
        }

        if (try self.handle_custom_setting_static_method(class_name, method_name, args)) |result| {
            return result;
        }

        // Database methods that need store access. Preserve user-defined classes named
        // Database, which Apex can still reference unqualified while the platform
        // namespace remains reachable through System.Database.
        if (std.ascii.eqlIgnoreCase(class_name, "Database") and
            self.find_class(class_name) == null)
        {
            return self.handle_database_method(method_name, args, self.global_env);
        }

        // Builtin class stubs (before user-defined classes), except when the
        // class name itself is a user-defined class that intentionally shadows
        // a builtin static namespace like Security or CanTheUser.
        if (!(is_builtin_static_namespace(class_name) and self.find_class(class_name) != null)) {
            var bctx = builtins.BuiltinContext{
                .arena = self.arena,
                .stdout = &self.stdout,
                .pending_exception = &self.pending_exception,
                .see_all_data = self.see_all_data,
                .eval = self,
            };
            if (try builtins.dispatch_static(&bctx, class_name, method_name, args)) |result| {
                return result;
            }
        }

        // Case-insensitive class lookup (before user-defined classes)
        var iter = self.classes.iterator();
        while (iter.next()) |entry| {
            if (std.ascii.eqlIgnoreCase(entry.key_ptr.*, class_name)) {
                const prev_class = self.current_class;
                self.current_class = entry.key_ptr.*;
                defer self.current_class = prev_class;
                // Try type-aware resolution first (prefer static methods for callMethod)
                if (self.find_best_method_in_class_filtered(
                    entry.value_ptr.*,
                    method_name,
                    args,
                    true,
                )) |md| {
                    return self.execute_method(md, args);
                }
                // Fallback to any method (not just static)
                if (self.find_best_method_in_class(entry.value_ptr.*, method_name, args)) |md| {
                    return self.execute_method(md, args);
                }
                // Fallback: find any name match
                var any_name_match = false;
                for (entry.value_ptr.*.members) |member| {
                    switch (member) {
                        .method_decl => |md| {
                            if (std.ascii.eqlIgnoreCase(md.name, method_name)) {
                                any_name_match = true;
                                break;
                            }
                        },
                        else => {},
                    }
                }
                if (any_name_match) return Value.null_val;
                return Value.null_val; // method not found in class, return null
            }
        }
        // Check if class_name is an enum (inner or top-level)
        {
            var enum_iter = self.classes.iterator();
            while (enum_iter.next()) |entry| {
                for (entry.value_ptr.*.members) |member| {
                    switch (member) {
                        .enum_decl => |ed| {
                            if (std.ascii.eqlIgnoreCase(ed.name, class_name)) {
                                if (std.ascii.eqlIgnoreCase(method_name, "valueOf") and
                                    args.len > 0 and args[0] == .string)
                                {
                                    for (ed.values) |v| {
                                        if (std.ascii.eqlIgnoreCase(v, args[0].string)) {
                                            return Value{ .string = v };
                                        }
                                    }
                                    const exc = try self.arena.create(types.ObjectInstance);
                                    exc.* = .{ .class_name = "System.NoSuchElementException" };
                                    try exc.fields.put(self.arena, "message", Value{
                                        .string = try std.fmt.allocPrint(
                                            self.arena,
                                            "No enum constant {s}.{s}",
                                            .{ class_name, args[0].string },
                                        ),
                                    });
                                    self.pending_exception = Value{ .object = exc };
                                    return error.ApexException;
                                }
                                if (std.ascii.eqlIgnoreCase(method_name, "values")) {
                                    const list = try self.arena.create(types.ListValue);
                                    list.* = .{};
                                    for (ed.values) |v| {
                                        try list.items.append(self.arena, Value{ .string = v });
                                    }
                                    return Value{ .list = list };
                                }
                                for (ed.values) |v| {
                                    if (std.ascii.eqlIgnoreCase(v, method_name)) {
                                        return Value{ .string = v };
                                    }
                                }
                            }
                        },
                        else => {},
                    }
                }
            }
        }
        // TestFactory / TestDataHelpers builtin stubs (only when no user-defined class found)
        if (try self.handle_test_factory(class_name, method_name, args)) |result| {
            return result;
        }
        return Value.null_val; // class not found, return null instead of error
    }

    fn execute_method(
        self: *Evaluator,
        method: *ast.MethodDecl,
        args: []const Value,
    ) anyerror!Value {
        const method_env = try self.global_env.child();

        for (method.params, 0..) |param, i| {
            const val = if (i < args.len)
                try self.prepare_method_arg_value(args[i])
            else
                Value.null_val;
            const declared_type = self.render_type_ref(param.type_ref);
            try method_env.define_typed(
                param.name,
                self.annotate_declared_collection_type(val, declared_type),
                declared_type,
            );
        }
        const saved_rv = self.return_value;
        self.return_value = .void_val;
        const result = try self.exec_block(method.body, method_env);
        const ret = switch (result) {
            .return_val => |v| v,
            else => self.return_value,
        };
        self.return_value = saved_rv;
        return ret;
    }

    // -----------------------------------------------------------------------
    // 文の実行
    // -----------------------------------------------------------------------

    pub fn exec_block(
        self: *Evaluator,
        stmts: []const ast.Stmt,
        current_env: *Env,
    ) anyerror!StmtResult {
        for (stmts) |stmt| {
            if (self.assertion_failure != null) return .normal;
            const result = try self.exec_stmt(stmt, current_env);
            switch (result) {
                .normal => {},
                else => return result,
            }
        }
        return .normal;
    }

    pub fn exec_stmt(self: *Evaluator, stmt: ast.Stmt, current_env: *Env) anyerror!StmtResult {
        return switch (stmt) {
            .expr_stmt => |expr| try self.exec_expr_stmt(expr, current_env),
            .var_decl => |vd| try self.exec_var_decl_stmt(vd, current_env),
            .block => |stmts| try self.exec_block_stmt(stmts, current_env),
            .if_stmt => |if_s| try self.exec_if_stmt(if_s, current_env),
            .for_stmt => |fs| try self.exec_for_stmt(fs, current_env),
            .for_each_stmt => |fes| try self.exec_for_each_stmt(fes, current_env),
            .while_stmt => |ws| try self.exec_while_stmt(ws, current_env),
            .do_while => |dw| try self.exec_do_while_stmt(dw, current_env),
            .return_stmt => |rs| try self.exec_return_stmt(rs, current_env),
            .break_stmt => .break_signal,
            .continue_stmt => .continue_signal,
            .switch_stmt => |sw| try self.exec_switch_stmt(sw, current_env),
            .try_stmt => |ts| try self.exec_try_stmt(ts, current_env),
            .throw_stmt => |ts| try self.exec_throw_stmt(ts, current_env),
            .dml_stmt => |dml| try self.exec_dml_stmt(dml, current_env),
            .run_as_stmt => |ras| try self.exec_run_as_stmt(ras, current_env),
        };
    }

    fn exec_expr_stmt(self: *Evaluator, expr: *ast.Expr, current_env: *Env) !StmtResult {
        _ = try self.eval_expr(expr, current_env);
        return .normal;
    }

    fn exec_var_decl_stmt(self: *Evaluator, vd: anytype, current_env: *Env) !StmtResult {
        var val = if (vd.initializer) |init_expr|
            try self.eval_expr(init_expr, current_env)
        else
            default_value(vd.type_ref);
        const declared_type = self.render_type_ref(vd.type_ref);
        val = try self.coerce_soql_assignment_to_declared_type(
            val,
            vd.initializer,
            declared_type,
        );
        val = self.annotate_declared_collection_type(val, declared_type);
        try current_env.define_typed(vd.name, val, declared_type);
        return .normal;
    }

    fn exec_block_stmt(self: *Evaluator, stmts: []const ast.Stmt, current_env: *Env) !StmtResult {
        const block_env = try current_env.child();
        return self.exec_block(stmts, block_env);
    }

    fn exec_if_stmt(self: *Evaluator, if_s: anytype, current_env: *Env) !StmtResult {
        const cond = try self.eval_expr(if_s.condition, current_env);
        if (utils.coerce_to_bool(cond) catch false) {
            return self.exec_block(if_s.then_body, current_env);
        }
        if (if_s.else_body) |else_body| return self.exec_block(else_body, current_env);
        return .normal;
    }

    fn exec_for_stmt(self: *Evaluator, fs: anytype, current_env: *Env) !StmtResult {
        const loop_env = try current_env.child();
        try self.exec_for_stmt_init(fs.init, loop_env);
        return try self.run_for_stmt_loop(fs, loop_env);
    }

    fn exec_for_stmt_init(self: *Evaluator, init_stmt_opt: anytype, loop_env: *Env) !void {
        if (init_stmt_opt) |init_stmt| {
            switch (init_stmt.*) {
                .block => |init_stmts| {
                    for (init_stmts) |init_item| {
                        _ = try self.exec_stmt(init_item, loop_env);
                    }
                },
                else => _ = try self.exec_stmt(init_stmt.*, loop_env),
            }
        }
    }

    fn run_for_stmt_loop(self: *Evaluator, fs: anytype, loop_env: *Env) !StmtResult {
        var iterations: u32 = 0;
        while (iterations < 100_000) : (iterations += 1) {
            if (fs.condition) |cond| {
                const cv = try self.eval_expr(cond, loop_env);
                if (!(utils.coerce_to_bool(cv) catch false)) break;
            }
            const result = try self.exec_block(fs.body, loop_env);
            switch (result) {
                .break_signal => break,
                .continue_signal => {},
                .return_val => return result,
                .normal => {},
            }
            if (fs.update) |upd| _ = try self.eval_expr(upd, loop_env);
        }
        return .normal;
    }

    fn exec_for_each_stmt(self: *Evaluator, fes: anytype, current_env: *Env) !StmtResult {
        const iterable = try self.eval_expr(fes.iterable, current_env);
        return switch (iterable) {
            .null_val => blk: {
                try self.throw_null_pointer_exception();
                break :blk .normal;
            },
            .list => |list| try self.exec_for_each_list_stmt(fes, list, current_env),
            .set => |set| try self.exec_for_each_set_stmt(fes, set, current_env),
            .map => |map| try self.exec_for_each_map_stmt(fes, map, current_env),
            .object => try self.exec_for_each_object_stmt(fes, iterable, current_env),
            else => .normal,
        };
    }

    fn exec_for_each_list_stmt(
        self: *Evaluator,
        fes: anytype,
        list: *types.ListValue,
        current_env: *Env,
    ) !StmtResult {
        if (self.should_chunk_for_each_list(fes, list)) {
            return try self.exec_for_each_list_chunks(fes, list.items.items, current_env);
        }
        return try self.exec_for_each_list_items(fes, list.items.items, current_env);
    }

    fn should_chunk_for_each_list(self: *Evaluator, fes: anytype, list: *types.ListValue) bool {
        _ = self;
        const elem_type_is_list =
            std.ascii.eqlIgnoreCase(fes.elem_type.name, "List") and fes.elem_type.params.len > 0;
        const iterable_is_list_of_lists = blk: {
            if (list.element_type) |et| {
                if (std.ascii.startsWithIgnoreCase(et, "List")) break :blk true;
                if (std.ascii.startsWithIgnoreCase(et, "Set")) break :blk true;
                if (std.ascii.startsWithIgnoreCase(et, "Map")) break :blk true;
            }
            for (list.items.items) |item| {
                switch (item) {
                    .list, .set, .map => break :blk true,
                    else => {},
                }
                break;
            }
            break :blk false;
        };
        return elem_type_is_list and !iterable_is_list_of_lists;
    }

    fn exec_for_each_list_chunks(
        self: *Evaluator,
        fes: anytype,
        items: []const Value,
        current_env: *Env,
    ) !StmtResult {
        const loop_env = try current_env.child();
        const chunk_size: usize = 200;
        var offset: usize = 0;
        while (offset < items.len) {
            const end = @min(offset + chunk_size, items.len);
            const chunk = try self.make_for_each_chunk_list(items[offset..end]);
            const result = try self.execute_bound_loop_body(
                loop_env,
                fes.elem_name,
                Value{ .list = chunk },
                fes.body,
            );
            switch (result) {
                .break_signal => break,
                .continue_signal => {},
                .return_val => return result,
                .normal => {},
            }
            offset = end;
        }
        return .normal;
    }

    fn make_for_each_chunk_list(self: *Evaluator, items: []const Value) !*types.ListValue {
        const chunk_list = try self.arena.create(types.ListValue);
        chunk_list.* = .{};
        for (items) |item| try chunk_list.items.append(self.arena, item);
        return chunk_list;
    }

    fn exec_for_each_list_items(
        self: *Evaluator,
        fes: anytype,
        items: []const Value,
        current_env: *Env,
    ) !StmtResult {
        const loop_env = try current_env.child();
        for (items) |item| {
            const result = try self.execute_bound_loop_body(
                loop_env,
                fes.elem_name,
                item,
                fes.body,
            );
            switch (result) {
                .break_signal => break,
                .continue_signal => {},
                .return_val => return result,
                .normal => {},
            }
        }
        return .normal;
    }

    fn exec_for_each_set_stmt(
        self: *Evaluator,
        fes: anytype,
        set: *types.SetValue,
        current_env: *Env,
    ) !StmtResult {
        const loop_env = try current_env.child();
        var values_copy: std.ArrayListUnmanaged(Value) = .empty;
        for (set.entries.values()) |item| try values_copy.append(self.arena, item);
        for (values_copy.items) |item| {
            const result = try self.execute_bound_loop_body(
                loop_env,
                fes.elem_name,
                item,
                fes.body,
            );
            switch (result) {
                .break_signal => break,
                .continue_signal => {},
                .return_val => return result,
                .normal => {},
            }
        }
        return .normal;
    }

    fn exec_for_each_map_stmt(
        self: *Evaluator,
        fes: anytype,
        map: *types.MapValue,
        current_env: *Env,
    ) !StmtResult {
        const loop_env = try current_env.child();
        for (map.entries.values()) |val| {
            const result = try self.execute_bound_loop_body(loop_env, fes.elem_name, val, fes.body);
            switch (result) {
                .break_signal => break,
                .continue_signal => {},
                .return_val => return result,
                .normal => {},
            }
        }
        return .normal;
    }

    fn exec_for_each_object_stmt(
        self: *Evaluator,
        fes: anytype,
        iterable: Value,
        current_env: *Env,
    ) !StmtResult {
        const iterator_obj = self.resolve_for_each_iterator_value(iterable);
        if (iterator_obj != .object) return .normal;

        const iter_cd = self.find_class(iterator_obj.object.class_name);
        if (iter_cd == null) return .normal;

        const loop_env = try current_env.child();
        var iterations: u32 = 0;
        while (iterations < 100_000) : (iterations += 1) {
            const has_next = self.call_instance_method(
                iter_cd.?,
                iterator_obj.object,
                "hasNext",
                &.{},
            ) catch break;
            if (!(utils.coerce_to_bool(has_next) catch false)) break;
            const next_val = try self.call_instance_method(
                iter_cd.?,
                iterator_obj.object,
                "next",
                &.{},
            );
            const result = try self.execute_bound_loop_body(
                loop_env,
                fes.elem_name,
                next_val,
                fes.body,
            );
            switch (result) {
                .break_signal => break,
                .continue_signal => {},
                .return_val => return result,
                .normal => {},
            }
        }
        return .normal;
    }

    fn resolve_for_each_iterator_value(self: *Evaluator, iterable: Value) Value {
        if (iterable != .object) return iterable;
        if (self.find_class(iterable.object.class_name)) |cd| {
            return self.call_instance_method(cd, iterable.object, "iterator", &.{}) catch iterable;
        }
        return iterable;
    }

    fn execute_bound_loop_body(
        self: *Evaluator,
        loop_env: *Env,
        name: []const u8,
        value: Value,
        body: []const ast.Stmt,
    ) !StmtResult {
        loop_env.set(name, value) catch {
            try loop_env.define(name, value);
        };
        return try self.exec_block(body, loop_env);
    }

    fn exec_while_stmt(self: *Evaluator, ws: anytype, current_env: *Env) !StmtResult {
        var iterations: u32 = 0;
        while (iterations < 100_000) : (iterations += 1) {
            const cv = try self.eval_expr(ws.condition, current_env);
            if (!(utils.coerce_to_bool(cv) catch false)) break;
            const result = try self.exec_block(ws.body, current_env);
            switch (result) {
                .break_signal => break,
                .continue_signal => {},
                .return_val => return result,
                .normal => {},
            }
        }
        return .normal;
    }

    fn exec_do_while_stmt(self: *Evaluator, dw: anytype, current_env: *Env) !StmtResult {
        var iterations: u32 = 0;
        while (iterations < 100_000) : (iterations += 1) {
            const result = try self.exec_block(dw.body, current_env);
            switch (result) {
                .break_signal => break,
                .continue_signal => {},
                .return_val => return result,
                .normal => {},
            }
            const cv = try self.eval_expr(dw.condition, current_env);
            if (!(utils.coerce_to_bool(cv) catch false)) break;
        }
        return .normal;
    }

    fn exec_return_stmt(self: *Evaluator, rs: anytype, current_env: *Env) !StmtResult {
        const val = if (rs.value) |v| try self.eval_expr(v, current_env) else Value.void_val;
        self.return_value = val;
        return .{ .return_val = val };
    }

    fn exec_switch_stmt(self: *Evaluator, sw: anytype, current_env: *Env) !StmtResult {
        const subject = try self.eval_expr(sw.subject, current_env);
        for (sw.when_clauses) |clause| {
            switch (clause.pattern) {
                .values => |values| {
                    if (try self.switch_clause_matches_subject(subject, values, current_env)) {
                        return self.exec_block(clause.body, current_env);
                    }
                },
                .else_clause => return self.exec_block(clause.body, current_env),
            }
        }
        return .normal;
    }

    fn switch_clause_matches_subject(
        self: *Evaluator,
        subject: Value,
        values: anytype,
        current_env: *Env,
    ) !bool {
        for (values) |val_expr| {
            var val_copy = val_expr;
            if (try self.switch_value_matches_subject(subject, &val_copy, current_env)) return true;
        }
        return false;
    }

    fn switch_value_matches_subject(
        self: *Evaluator,
        subject: Value,
        val_copy: *ast.Expr,
        current_env: *Env,
    ) !bool {
        const when_val = try self.eval_expr(val_copy, current_env);
        if (subject == .string and when_val == .string) {
            if (std.mem.eql(u8, subject.string, when_val.string)) return true;
        } else if (utils.value_eql(subject, when_val)) {
            return true;
        }
        if (subject == .string and val_copy.* == .identifier) {
            if (std.ascii.eqlIgnoreCase(subject.string, val_copy.identifier.name)) return true;
        }
        if (subject == .string and when_val == .null_val and val_copy.* == .identifier) {
            if (std.ascii.eqlIgnoreCase(subject.string, val_copy.identifier.name)) return true;
        }
        return self.switch_type_pattern_matches_subject(subject, val_copy);
    }

    fn switch_type_pattern_matches_subject(
        self: *Evaluator,
        subject: Value,
        val_copy: *ast.Expr,
    ) bool {
        if (self.switch_type_pattern_name(val_copy)) |type_name| {
            if (subject == .sobject and
                std.ascii.eqlIgnoreCase(subject.sobject.type_name, type_name))
            {
                return true;
            }
            if (subject == .object) {
                const subject_simple =
                    if (std.mem.lastIndexOfScalar(u8, subject.object.class_name, '.')) |di|
                        subject.object.class_name[di + 1 ..]
                    else
                        subject.object.class_name;
                if (std.ascii.eqlIgnoreCase(subject_simple, type_name)) return true;
            }
        }
        return false;
    }

    fn exec_try_stmt(self: *Evaluator, ts: anytype, current_env: *Env) !StmtResult {
        const result = self.exec_block(ts.body, current_env);
        if (result) |r| {
            if (ts.finally_body) |fb| _ = try self.exec_block(fb, current_env);
            return r;
        } else |body_err| {
            if (ts.catches.len == 0) {
                if (ts.finally_body) |fb| _ = self.exec_block(fb, current_env) catch {};
                return body_err;
            }
            return try self.exec_try_catch_path(ts, current_env);
        }
    }

    fn exec_try_catch_path(self: *Evaluator, ts: anytype, current_env: *Env) !StmtResult {
        const exc_obj = try self.take_pending_exception_object();
        const selected = self.select_matching_catch_clause(ts.catches, exc_obj.class_name);
        const catch_env = try current_env.child();
        try catch_env.define(selected.name, Value{ .object = exc_obj });
        if (self.exec_block(selected.body, catch_env)) |catch_result| {
            if (ts.finally_body) |fb| _ = try self.exec_block(fb, current_env);
            return catch_result;
        } else |catch_err| {
            if (ts.finally_body) |fb| _ = self.exec_block(fb, current_env) catch {};
            return catch_err;
        }
    }

    fn take_pending_exception_object(self: *Evaluator) !*types.ObjectInstance {
        const exc_val = if (self.pending_exception) |pe| pe else blk: {
            const exc = try self.arena.create(types.ObjectInstance);
            exc.* = .{ .class_name = "Exception" };
            break :blk Value{ .object = exc };
        };
        self.pending_exception = null;
        if (exc_val == .object) return exc_val.object;
        const exc = try self.arena.create(types.ObjectInstance);
        exc.* = .{ .class_name = "Exception" };
        return exc;
    }

    fn select_matching_catch_clause(
        self: *Evaluator,
        catches: []const ast.CatchClause,
        exc_class_name: []const u8,
    ) *const ast.CatchClause {
        var matched: ?*const ast.CatchClause = null;
        var generic: ?*const ast.CatchClause = null;
        for (catches) |*cc| {
            if (self.catch_clause_matches_exception(cc, exc_class_name)) {
                matched = cc;
                break;
            }
            if (self.is_generic_exception_catch(cc.exception_type.name)) generic = cc;
        }
        return matched orelse generic orelse &catches[0];
    }

    fn catch_clause_matches_exception(
        self: *Evaluator,
        cc: *const ast.CatchClause,
        exc_class_name: []const u8,
    ) bool {
        const catch_type = cc.exception_type.name;
        const catch_simple = simple_type_name(catch_type);
        const exc_simple = simple_type_name(exc_class_name);
        if (std.ascii.eqlIgnoreCase(catch_type, exc_class_name) or
            std.ascii.eqlIgnoreCase(catch_simple, exc_simple) or
            std.ascii.eqlIgnoreCase(catch_simple, exc_class_name) or
            std.ascii.eqlIgnoreCase(catch_type, exc_simple))
        {
            return true;
        }
        if (self.find_class(exc_class_name)) |exc_cd| {
            if (exc_cd.super_class) |sc| {
                const sc_simple = simple_type_name(sc.name);
                if (std.ascii.eqlIgnoreCase(catch_simple, sc_simple) or
                    std.ascii.eqlIgnoreCase(catch_type, sc.name))
                {
                    return true;
                }
            }
        }
        return false;
    }

    fn is_generic_exception_catch(self: *Evaluator, catch_type: []const u8) bool {
        _ = self;
        return std.ascii.eqlIgnoreCase(catch_type, "Exception") or
            std.ascii.eqlIgnoreCase(catch_type, "System.Exception");
    }

    fn simple_type_name(type_name: []const u8) []const u8 {
        return if (std.mem.lastIndexOfScalar(u8, type_name, '.')) |di|
            type_name[di + 1 ..]
        else
            type_name;
    }

    fn exec_throw_stmt(self: *Evaluator, ts: anytype, current_env: *Env) !StmtResult {
        const exc_val = try self.eval_expr(ts.expr, current_env);
        self.pending_exception = exc_val;
        return error.ApexException;
    }

    fn exec_dml_stmt(self: *Evaluator, dml: anytype, current_env: *Env) !StmtResult {
        const target = try self.eval_expr(dml.target, current_env);
        try self.enforce_user_mode_dml_access(dml.is_user_mode, target);
        try self.execute_dml(dml.op, target);
        return .normal;
    }

    fn enforce_user_mode_dml_access(self: *Evaluator, is_user_mode: bool, target: Value) !void {
        const has_permset_dml = if (self.store.get("PermissionSetAssignment")) |psa|
            psa.items.len > 0
        else
            false;
        if (!is_user_mode or !self.is_min_access_user or has_permset_dml) return;

        const from_type = self.get_target_object_type(target) orelse "SObject";
        const msg = try std.fmt.allocPrint(
            self.arena,
            "No Access: Access to entity '{s}' denied",
            .{from_type},
        );
        const exc = try self.arena.create(types.ObjectInstance);
        exc.* = .{ .class_name = "System.NoAccessException" };
        try exc.fields.put(self.arena, "message", Value{ .string = msg });
        self.pending_exception = Value{ .object = exc };
        return error.ApexException;
    }

    const RunAsState = struct {
        restricted: bool,
        min_access: bool,
        standard: bool,
        user_id: []const u8,
        profile_id: []const u8,
        user_override: ?*types.SObject,
    };

    fn exec_run_as_stmt(self: *Evaluator, ras: anytype, current_env: *Env) !StmtResult {
        const user_val = try self.eval_expr(ras.user_expr, current_env);
        const previous = self.capture_run_as_state();
        defer self.restore_run_as_state(previous);

        self.current_user_override = if (user_val == .sobject) user_val.sobject else null;
        self.apply_run_as_user_flags(user_val);
        return try self.exec_block(ras.body, current_env);
    }

    fn capture_run_as_state(self: *Evaluator) RunAsState {
        return .{
            .restricted = self.is_restricted_user,
            .min_access = self.is_min_access_user,
            .standard = self.is_standard_user,
            .user_id = self.current_user_id,
            .profile_id = self.current_profile_id,
            .user_override = self.current_user_override,
        };
    }

    fn restore_run_as_state(self: *Evaluator, state: RunAsState) void {
        self.is_restricted_user = state.restricted;
        self.is_min_access_user = state.min_access;
        self.is_standard_user = state.standard;
        self.current_user_id = state.user_id;
        self.current_profile_id = state.profile_id;
        self.current_user_override = state.user_override;
    }

    fn apply_run_as_user_flags(self: *Evaluator, user_val: Value) void {
        if (user_val == .sobject) {
            self.apply_run_as_s_object_flags(user_val.sobject);
            return;
        }
        self.is_restricted_user = true;
        self.is_min_access_user = true;
        self.is_standard_user = false;
    }

    fn apply_run_as_s_object_flags(self: *Evaluator, user: *types.SObject) void {
        if (user.id == null) {
            const uid = self.alloc_id() catch return;
            user.id = uid;
            user.fields.put(self.arena, "Id", Value{ .string = uid }) catch return;
        }
        if (user.id) |uid| self.current_user_id = uid;
        if (utils.sobject_get(&user.fields, "ProfileId") orelse
            utils.sobject_get(&user.fields, "profileId")) |pv|
        {
            if (pv == .string) self.current_profile_id = pv.string;
        } else if (utils.sobject_get(&user.fields, "Profile")) |prof| {
            if (prof == .sobject and prof.sobject.id != null) {
                self.current_profile_id = prof.sobject.id.?;
            }
        }

        if (self.lookup_run_as_profile_name(user)) |pn| {
            self.is_restricted_user = self.is_restricted_profile_name(pn);
            self.is_min_access_user = std.ascii.indexOfIgnoreCase(pn, "Minimum Access") != null or
                std.ascii.indexOfIgnoreCase(pn, "MinAccess") != null;
            self.is_standard_user = self.is_standard_profile_name(pn);
            return;
        }
        self.is_restricted_user = false;
        self.is_min_access_user = false;
        self.is_standard_user = false;
    }

    fn lookup_run_as_profile_name(self: *Evaluator, user: *types.SObject) ?[]const u8 {
        if (self.get_user_profile_name(user)) |profile_name| return profile_name;
        if (self.find_record_by_id("Profile", self.current_profile_id)) |profile_val| {
            if (profile_val == .sobject) {
                if (utils.sobject_get(&profile_val.sobject.fields, "Name")) |name| {
                    if (name == .string) return name.string;
                }
            }
        }
        return null;
    }

    fn throw_null_pointer_exception(self: *Evaluator) !void {
        const exc = try self.arena.create(types.ObjectInstance);
        exc.* = .{ .class_name = "System.NullPointerException" };
        try exc.fields.put(self.arena, "message", Value{
            .string = "Attempt to de-reference a null object",
        });
        self.pending_exception = Value{ .object = exc };
        return error.ApexException;
    }

    fn switch_type_pattern_name(self: *Evaluator, expr: *const ast.Expr) ?[]const u8 {
        _ = self;
        return switch (expr.*) {
            .identifier => |id| id.name,
            .field_access => |fa| fa.field,
            else => null,
        };
    }

    // -----------------------------------------------------------------------
    // DML 操作
    // -----------------------------------------------------------------------

    pub fn execute_dml(self: *Evaluator, op: ast.DmlOp, target: Value) anyerror!void {
        try self.execute_dml_with_external_id_internal(op, target, null, true, null);
    }

    fn execute_dml_with_external_id(
        self: *Evaluator,
        op: ast.DmlOp,
        target: Value,
        external_id_field: ?[]const u8,
    ) anyerror!void {
        try self.execute_dml_with_external_id_internal(op, target, external_id_field, true, null);
    }

    fn execute_dml_with_external_id_internal(
        self: *Evaluator,
        op: ast.DmlOp,
        target: Value,
        external_id_field: ?[]const u8,
        count_limits: bool,
        old_records_override: ?std.ArrayListUnmanaged(Value),
    ) anyerror!void {
        if (target == .list and target.list.items.items.len == 0) return;
        if (count_limits) self.count_dml_statement_limits(target);
        try self.throw_if_null_dml_target(target);

        const obj_type = self.get_target_object_type(target);
        const trigger_events = dml_trigger_events(op);
        var record_list = try self.build_record_list(target);
        self.clear_dml_record_errors(&record_list);
        const old_records = try self.build_dml_old_records(op, &record_list, old_records_override);

        if (trigger_events.before) |evt| {
            if (obj_type) |ot| {
                try self.fire_trigger(ot, evt, &record_list, old_records);
            }
        }
        try self.fail_if_records_have_errors(&record_list, op, false);

        try self.execute_dml_records(op, target, external_id_field);

        if (trigger_events.after != null) {
            record_list = try self.rebuild_after_dml_record_list(op, target, &record_list);
        }
        if (trigger_events.after) |evt| {
            if (obj_type) |ot| {
                try self.fire_trigger(ot, evt, &record_list, old_records);
            }
        }
        try self.fail_if_records_have_errors(&record_list, op, true);

        if (obj_type) |ot| {
            try self.apply_rollup_summary_side_effects(ot, record_list.items, old_records);
        }
        self.cleanup_dml_side_effects(op, obj_type);
    }

    const DmlTriggerEvents = struct {
        before: ?ast.TriggerEvent,
        after: ?ast.TriggerEvent,
    };

    fn count_dml_statement_limits(self: *Evaluator, target: Value) void {
        self.limits_dml += 1;
        if (target == .list) {
            self.limits_dml_rows += @intCast(target.list.items.items.len);
        } else {
            self.limits_dml_rows += 1;
        }
    }

    fn throw_if_null_dml_target(self: *Evaluator, target: Value) !void {
        if (target != .null_val) return;
        const exc = try self.arena.create(types.ObjectInstance);
        exc.* = .{ .class_name = "System.NullPointerException" };
        try exc.fields.put(self.arena, "message", Value{
            .string = "Attempt to de-reference a null object",
        });
        self.pending_exception = Value{ .object = exc };
        return error.ApexException;
    }

    fn dml_trigger_events(op: ast.DmlOp) DmlTriggerEvents {
        return .{
            .before = switch (op) {
                .insert => .before_insert,
                .update => .before_update,
                .delete => .before_delete,
                else => null,
            },
            .after = switch (op) {
                .insert => .after_insert,
                .update => .after_update,
                .delete => .after_delete,
                .undelete => .after_undelete,
                else => null,
            },
        };
    }

    fn clear_dml_record_errors(_: *Evaluator, record_list: *std.ArrayListUnmanaged(Value)) void {
        for (record_list.items) |item| {
            if (item == .sobject) {
                if (item.sobject.fields.get("errors")) |_| {
                    _ = item.sobject.fields.orderedRemove("errors");
                }
            }
        }
    }

    fn build_dml_old_records(
        self: *Evaluator,
        op: ast.DmlOp,
        record_list: *std.ArrayListUnmanaged(Value),
        old_records_override: ?std.ArrayListUnmanaged(Value),
    ) !?std.ArrayListUnmanaged(Value) {
        if (old_records_override) |override| return override;
        if (op != .update and op != .delete) return null;
        var old_records = std.ArrayListUnmanaged(Value).empty;
        for (record_list.items) |item| {
            if (item != .sobject or item.sobject.id == null) continue;
            if (self.find_record_in_store(item.sobject.type_name, item.sobject.id.?)) |stored| {
                try old_records.append(self.arena, try self.clone_old_dml_record(stored));
            } else {
                try old_records.append(self.arena, item);
            }
        }
        return old_records;
    }

    fn clone_old_dml_record(self: *Evaluator, stored: Value) !Value {
        if (stored != .sobject) return stored;
        const clone = try self.arena.create(types.SObject);
        clone.* = .{ .type_name = stored.sobject.type_name };
        clone.id = stored.sobject.id;
        for (stored.sobject.fields.keys(), stored.sobject.fields.values()) |key, value| {
            try clone.fields.put(self.arena, key, value);
        }
        return Value{ .sobject = clone };
    }

    fn fail_if_records_have_errors(
        self: *Evaluator,
        record_list: *std.ArrayListUnmanaged(Value),
        op: ast.DmlOp,
        rollback_after_trigger: bool,
    ) !void {
        for (record_list.items) |item| {
            if (item != .sobject) continue;
            const errors = utils.sobject_get(&item.sobject.fields, "errors") orelse continue;
            if (errors != .list or errors.list.items.items.len == 0) continue;
            if (rollback_after_trigger and op == .undelete) {
                self.rollback_undelete(record_list) catch {};
            }
            return self.throw_dml_exception(dml_error_message(errors.list.items.items[0]));
        }
    }

    fn dml_error_message(first_error: Value) []const u8 {
        if (first_error == .object) {
            if (first_error.object.fields.get("message")) |message| {
                if (message == .string) return message.string;
            }
        }
        return "Trigger added error";
    }

    fn throw_dml_exception(self: *Evaluator, message: []const u8) !void {
        const exc = try self.arena.create(types.ObjectInstance);
        exc.* = .{ .class_name = "DmlException" };
        try exc.fields.put(self.arena, "message", Value{ .string = message });
        self.pending_exception = Value{ .object = exc };
        return error.ApexException;
    }

    fn execute_dml_records(
        self: *Evaluator,
        op: ast.DmlOp,
        target: Value,
        external_id_field: ?[]const u8,
    ) !void {
        switch (op) {
            .insert => try self.execute_insert_records(target),
            .update => {
                if (target == .sobject) {
                    try self.update_record(target.sobject);
                } else if (target == .list) {
                    for (target.list.items.items) |item| {
                        if (item == .sobject) try self.update_record(item.sobject);
                    }
                }
            },
            .upsert => {
                if (target == .sobject) {
                    try self.upsert_record(target.sobject, external_id_field);
                } else if (target == .list) {
                    for (target.list.items.items) |item| {
                        if (item == .sobject) {
                            try self.upsert_record(item.sobject, external_id_field);
                        }
                    }
                }
            },
            .delete => {
                if (target == .sobject) {
                    try self.delete_record(target.sobject);
                } else if (target == .list) {
                    for (target.list.items.items) |item| {
                        if (item == .sobject) try self.delete_record(item.sobject);
                    }
                }
            },
            .undelete => {
                if (target == .sobject) {
                    try self.undelete_record(target.sobject);
                } else if (target == .list) {
                    for (target.list.items.items) |item| {
                        if (item == .sobject) try self.undelete_record(item.sobject);
                    }
                }
            },
            .merge => {},
        }
    }

    fn execute_insert_records(self: *Evaluator, target: Value) !void {
        if (target == .sobject) return self.insert_record(target.sobject);
        if (target != .list) return;
        for (target.list.items.items) |item| {
            if (item != .sobject) continue;
            if (try self.validate_required_fields(item.sobject, false)) |err_msg| {
                return self.throw_dml_exception(err_msg);
            }
        }
        for (target.list.items.items) |item| {
            if (item == .sobject) try self.insert_record(item.sobject);
        }
    }

    fn rebuild_after_dml_record_list(
        self: *Evaluator,
        op: ast.DmlOp,
        target: Value,
        record_list: *std.ArrayListUnmanaged(Value),
    ) !std.ArrayListUnmanaged(Value) {
        if (op != .update) return self.build_record_list(target);
        var new_list = std.ArrayListUnmanaged(Value).empty;
        for (record_list.items) |item| {
            if (item == .sobject and item.sobject.id != null) {
                if (self.find_record_in_store(item.sobject.type_name, item.sobject.id.?)) |stored| {
                    try new_list.append(self.arena, stored);
                } else {
                    try new_list.append(self.arena, item);
                }
            } else {
                try new_list.append(self.arena, item);
            }
        }
        return new_list;
    }

    fn cleanup_dml_side_effects(self: *Evaluator, op: ast.DmlOp, obj_type: ?[]const u8) void {
        if (op != .delete and op != .update) return;
        const type_name = obj_type orelse return;
        if (std.ascii.eqlIgnoreCase(type_name, "DuplicateRecordItem")) {
            self.cleanup_orphaned_duplicate_record_sets() catch {};
        }
    }

    fn custom_prefix_category(type_name: []const u8) u8 {
        if (std.mem.endsWith(u8, type_name, "__mdt")) return 'm';
        if (std.mem.endsWith(u8, type_name, "__e")) return 'e';
        if (std.mem.endsWith(u8, type_name, "__b")) return 'b';
        if (std.mem.endsWith(u8, type_name, "__ChangeEvent")) return 'c';
        if (std.mem.endsWith(u8, type_name, "__History")) return 'h';
        if (std.mem.endsWith(u8, type_name, "__Share")) return 's';
        return 'a';
    }

    fn hashed_custom_key_prefix(type_name: []const u8) [3]u8 {
        const alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz";
        var hash: u32 = 2166136261;
        for (type_name) |ch| {
            hash ^= @as(u32, std.ascii.toLower(ch));
            hash *%= 16777619;
        }
        const suffix = hash % @as(u32, alphabet.len * alphabet.len);
        return .{
            custom_prefix_category(type_name),
            alphabet[@intCast(suffix / alphabet.len)],
            alphabet[@intCast(suffix % alphabet.len)],
        };
    }

    fn is_template_s_object_type(type_name: []const u8) bool {
        return std.ascii.eqlIgnoreCase(type_name, "CaseComment") or
            std.mem.endsWith(u8, type_name, "History") or
            std.mem.endsWith(u8, type_name, "__History");
    }

    /// Return the 3-character Salesforce key prefix for known SObject types.
    pub fn sobject_key_prefix(type_name: []const u8) [3]u8 {
        if (std.ascii.eqlIgnoreCase(type_name, "Account")) return .{ '0', '0', '1' };
        if (std.ascii.eqlIgnoreCase(type_name, "Contact")) return .{ '0', '0', '3' };
        if (std.ascii.eqlIgnoreCase(type_name, "Opportunity")) return .{ '0', '0', '6' };
        if (std.ascii.eqlIgnoreCase(type_name, "OpportunityContactRole"))
            return .{ '0', '0', 'K' };
        if (std.ascii.eqlIgnoreCase(type_name, "OpportunityStage")) return .{ '0', '1', 'J' };
        if (std.ascii.eqlIgnoreCase(type_name, "Lead")) return .{ '0', '0', 'Q' };
        if (std.ascii.eqlIgnoreCase(type_name, "Case")) return .{ '5', '0', '0' };
        if (std.ascii.eqlIgnoreCase(type_name, "Task")) return .{ '0', '0', 'T' };
        if (std.ascii.eqlIgnoreCase(type_name, "Event")) return .{ '0', '0', 'U' };
        if (std.ascii.eqlIgnoreCase(type_name, "User")) return .{ '0', '0', '5' };
        if (std.ascii.eqlIgnoreCase(type_name, "Campaign")) return .{ '7', '0', '1' };
        if (std.ascii.eqlIgnoreCase(type_name, "CampaignMember")) return .{ '0', '0', 'v' };
        if (std.ascii.eqlIgnoreCase(type_name, "Product2")) return .{ '0', '1', 't' };
        if (std.ascii.eqlIgnoreCase(type_name, "Pricebook2")) return .{ '0', '1', 's' };
        if (std.ascii.eqlIgnoreCase(type_name, "PricebookEntry")) return .{ '0', '1', 'u' };
        if (std.ascii.eqlIgnoreCase(type_name, "Contract")) return .{ '8', '0', '0' };
        if (std.ascii.eqlIgnoreCase(type_name, "Order")) return .{ '8', '0', '1' };
        if (std.ascii.eqlIgnoreCase(type_name, "ContentDocument")) return .{ '0', '6', '9' };
        if (std.ascii.eqlIgnoreCase(type_name, "ContentVersion")) return .{ '0', '6', '8' };
        if (std.ascii.eqlIgnoreCase(type_name, "ContentDocumentLink")) return .{ '0', '6', 'A' };
        if (std.ascii.eqlIgnoreCase(type_name, "EmailMessage")) return .{ '0', '2', 's' };
        if (std.ascii.eqlIgnoreCase(type_name, "EmailMessageRelation")) return .{ '0', 'J', 'A' };
        if (std.ascii.eqlIgnoreCase(type_name, "Organization")) return .{ '0', '0', 'D' };
        if (std.ascii.eqlIgnoreCase(type_name, "RecordType")) return .{ '0', '1', '2' };
        if (std.ascii.eqlIgnoreCase(type_name, "CaseComment")) return .{ '0', '0', 'N' };
        if (std.ascii.eqlIgnoreCase(type_name, "DuplicateRecordSet")) return .{ '0', 'D', 'n' };
        if (std.ascii.eqlIgnoreCase(type_name, "DuplicateRecordItem")) return .{ '0', 'D', 'o' };
        if (std.ascii.eqlIgnoreCase(type_name, "DuplicateRule")) return .{ '0', 'B', 'm' };
        if (std.ascii.eqlIgnoreCase(type_name, "Group")) return .{ '0', '0', 'G' };
        if (std.ascii.eqlIgnoreCase(type_name, "Profile")) return .{ '0', '0', 'e' };
        if (std.ascii.eqlIgnoreCase(type_name, "PermissionSet")) return .{ '0', 'P', 'S' };
        if (std.ascii.eqlIgnoreCase(type_name, "PermissionSetAssignment")) {
            return .{ '0', 'P', 'a' };
        }
        if (std.ascii.eqlIgnoreCase(type_name, "FieldPermissions")) return .{ '0', 'F', 'P' };
        if (std.ascii.eqlIgnoreCase(type_name, "ObjectPermissions")) return .{ '0', 'O', 'P' };
        if (std.ascii.eqlIgnoreCase(type_name, "Attachment")) return .{ '0', '0', 'P' };
        if (std.ascii.eqlIgnoreCase(type_name, "Note")) return .{ '0', '0', '2' };
        if (std.ascii.eqlIgnoreCase(type_name, "Solution")) return .{ '5', '0', '1' };
        if (std.ascii.eqlIgnoreCase(type_name, "OpportunityLineItem")) return .{ '0', '0', 'k' };
        if (std.ascii.eqlIgnoreCase(type_name, "Quote")) return .{ '0', 'Q', '0' };
        if (std.ascii.eqlIgnoreCase(type_name, "QuoteLineItem")) return .{ '0', 'Q', 'L' };
        if (std.mem.endsWith(u8, type_name, "__c") or
            std.mem.endsWith(u8, type_name, "__e") or
            std.mem.endsWith(u8, type_name, "__mdt") or
            std.mem.endsWith(u8, type_name, "__b") or
            std.mem.endsWith(u8, type_name, "__ChangeEvent") or
            std.mem.endsWith(u8, type_name, "__History") or
            std.mem.endsWith(u8, type_name, "__Share"))
        {
            return hashed_custom_key_prefix(type_name);
        }
        // Default: use first 3 chars of type name (padded)
        if (type_name.len >= 3) return .{ type_name[0], type_name[1], type_name[2] };
        if (type_name.len == 2) return .{ type_name[0], type_name[1], '0' };
        if (type_name.len == 1) return .{ type_name[0], '0', '0' };
        return .{ 'a', '0', '0' };
    }

    fn sobject_type_from_prefix(prefix: []const u8) []const u8 {
        if (std.mem.eql(u8, prefix, "001")) return "Account";
        if (std.mem.eql(u8, prefix, "003")) return "Contact";
        if (std.mem.eql(u8, prefix, "006")) return "Opportunity";
        if (std.mem.eql(u8, prefix, "00Q")) return "Lead";
        if (std.mem.eql(u8, prefix, "500")) return "Case";
        if (std.mem.eql(u8, prefix, "00T")) return "Task";
        if (std.mem.eql(u8, prefix, "00U")) return "Event";
        if (std.mem.eql(u8, prefix, "005")) return "User";
        if (std.mem.eql(u8, prefix, "701")) return "Campaign";
        if (std.mem.eql(u8, prefix, "00e")) return "Profile";
        if (std.mem.eql(u8, prefix, "0PS")) return "PermissionSet";
        if (std.mem.eql(u8, prefix, "069")) return "ContentDocument";
        if (std.mem.eql(u8, prefix, "068")) return "ContentVersion";
        if (std.mem.eql(u8, prefix, "00G")) return "Group";
        if (std.mem.eql(u8, prefix, "012")) return "RecordType";
        if (std.mem.eql(u8, prefix, "00N")) return "CaseComment";
        if (std.mem.eql(u8, prefix, "501")) return "Solution";
        if (std.mem.eql(u8, prefix, "800")) return "Contract";
        if (std.mem.eql(u8, prefix, "801")) return "Order";
        if (std.ascii.eqlIgnoreCase(prefix, "00D")) return "Organization";
        return "SObject";
    }

    fn has_implicit_name_field(type_name: []const u8) bool {
        if (std.ascii.eqlIgnoreCase(type_name, "EmailMessage")) return false;
        if (std.ascii.eqlIgnoreCase(type_name, "EmailMessageRelation")) return false;
        return true;
    }

    fn get_target_object_type(self: *Evaluator, target: Value) ?[]const u8 {
        _ = self;
        if (target == .sobject) return target.sobject.type_name;
        if (target == .list) {
            for (target.list.items.items) |item| {
                if (item == .sobject) return item.sobject.type_name;
            }
        }
        return null;
    }

    fn build_record_list(self: *Evaluator, target: Value) !std.ArrayListUnmanaged(Value) {
        var list: std.ArrayListUnmanaged(Value) = .empty;
        if (target == .sobject) {
            try list.append(self.arena, target);
        } else if (target == .list) {
            for (target.list.items.items) |item| {
                try list.append(self.arena, item);
            }
        }
        return list;
    }

    fn find_record_in_store(self: *Evaluator, type_name: []const u8, id: []const u8) ?Value {
        var store_iter = self.store.iterator();
        while (store_iter.next()) |entry| {
            if (!std.ascii.eqlIgnoreCase(entry.key_ptr.*, type_name)) continue;
            for (entry.value_ptr.items) |record| {
                if (record == .sobject and record.sobject.id != null) {
                    if (std.mem.eql(u8, record.sobject.id.?, id)) {
                        return record;
                    }
                }
            }
        }
        return null;
    }

    fn make_s_object_field_token(
        self: *Evaluator,
        object_type: []const u8,
        field_name: []const u8,
    ) !Value {
        const field = try self.arena.create(types.ObjectInstance);
        field.* = .{ .class_name = "Schema.SObjectField" };
        try field.fields.put(self.arena, "objectType", Value{ .string = object_type });
        try field.fields.put(self.arena, "fieldName", Value{ .string = field_name });
        try field.fields.put(self.arena, "name", Value{ .string = field_name });
        return Value{ .object = field };
    }

    fn extract_s_object_field_name(field_value: Value) ?[]const u8 {
        return switch (field_value) {
            .string => |s| s,
            .object => |obj| blk: {
                if (obj.fields.get("fieldName")) |field_name| {
                    if (field_name == .string) break :blk field_name.string;
                }
                if (obj.fields.get("name")) |field_name| {
                    if (field_name == .string) break :blk field_name.string;
                }
                break :blk null;
            },
            else => null,
        };
    }

    fn get_upsert_field_value(obj: *types.SObject, field_name: []const u8) Value {
        if (std.ascii.eqlIgnoreCase(field_name, "Id")) {
            if (obj.id) |id| return Value{ .string = id };
        }
        return utils.sobject_get(&obj.fields, field_name) orelse Value.null_val;
    }

    fn get_field_metadata(
        self: *Evaluator,
        type_name: []const u8,
        field_name: []const u8,
    ) ?FieldMetadata {
        const type_meta = self.field_metadata.get(type_name) orelse return null;
        if (type_meta.get(field_name)) |meta| return meta;
        var iter = type_meta.iterator();
        while (iter.next()) |entry| {
            if (std.ascii.eqlIgnoreCase(entry.key_ptr.*, field_name)) return entry.value_ptr.*;
        }
        return null;
    }

    fn field_values_equal_with_metadata(
        _: *Evaluator,
        metadata: ?FieldMetadata,
        lhs: Value,
        rhs: Value,
    ) bool {
        if (metadata) |meta| {
            if (!meta.case_sensitive and lhs == .string and rhs == .string) {
                return std.ascii.eqlIgnoreCase(lhs.string, rhs.string);
            }
        }
        return utils.value_eql(lhs, rhs);
    }

    fn find_record_by_field_value(
        self: *Evaluator,
        type_name: []const u8,
        field_name: []const u8,
        field_value: Value,
    ) ?*types.SObject {
        const metadata = self.get_field_metadata(type_name, field_name);
        var store_iter = self.store.iterator();
        while (store_iter.next()) |entry| {
            if (!std.ascii.eqlIgnoreCase(entry.key_ptr.*, type_name)) continue;
            for (entry.value_ptr.items) |record| {
                if (record != .sobject) continue;
                const existing_value = get_upsert_field_value(record.sobject, field_name);
                if (existing_value != .null_val and
                    self.field_values_equal_with_metadata(
                        metadata,
                        existing_value,
                        field_value,
                    ))
                {
                    return record.sobject;
                }
            }
        }
        return null;
    }

    fn find_unique_field_conflict(
        self: *Evaluator,
        obj: *types.SObject,
        only_present: bool,
    ) ?[]const u8 {
        const type_meta = self.field_metadata.get(obj.type_name) orelse return null;
        var field_iter = type_meta.iterator();
        while (field_iter.next()) |entry| {
            const field_name = entry.key_ptr.*;
            const metadata = entry.value_ptr.*;
            if (!metadata.is_unique) continue;

            const field_value = get_upsert_field_value(obj, field_name);
            if (field_value == .null_val) {
                if (only_present) continue;
                continue;
            }

            if (self.find_record_by_field_value(
                obj.type_name,
                field_name,
                field_value,
            )) |existing| {
                if (obj.id != null and existing.id != null and
                    std.ascii.eqlIgnoreCase(obj.id.?, existing.id.?))
                {
                    continue;
                }
                return field_name;
            }
        }
        return null;
    }

    fn throw_duplicate_value(self: *Evaluator, field_name: []const u8) anyerror {
        const msg = try std.fmt.allocPrint(
            self.arena,
            "DUPLICATE_VALUE: duplicate value found: {s}",
            .{field_name},
        );
        const exc = try self.arena.create(types.ObjectInstance);
        exc.* = .{ .class_name = "DmlException" };
        try exc.fields.put(self.arena, "message", Value{ .string = msg });
        self.pending_exception = Value{ .object = exc };
        return error.ApexException;
    }

    fn will_upsert_create_record(
        self: *Evaluator,
        obj: *types.SObject,
        external_id_field: ?[]const u8,
    ) bool {
        if (obj.id != null) return false;
        if (utils.sobject_get(&obj.fields, "Id")) |id_val| {
            if (id_val != .null_val) return false;
        }
        if (external_id_field) |field_name| {
            const field_value = get_upsert_field_value(obj, field_name);
            if (field_value != .null_val and
                self.find_record_by_field_value(
                    obj.type_name,
                    field_name,
                    field_value,
                ) != null)
            {
                return false;
            }
        }
        return true;
    }

    /// Get the profile name for a User SObject by checking Profile field or looking up profileId.
    pub fn get_user_profile_name(self: *Evaluator, user: *types.SObject) ?[]const u8 {
        // Check the Profile field directly (SObject reference)
        if (utils.sobject_get(&user.fields, "Profile")) |pv| {
            if (pv == .sobject) {
                if (utils.sobject_get(&pv.sobject.fields, "Name")) |name| {
                    if (name == .string) return name.string;
                }
            }
        }
        // Check profileId → look up in the store
        if (utils.sobject_get(&user.fields, "profileId") orelse
            utils.sobject_get(&user.fields, "ProfileId")) |pid|
        {
            const pid_str = if (pid == .string) pid.string else null;
            if (pid_str) |profile_id| {
                var store_iter = self.store.iterator();
                while (store_iter.next()) |entry| {
                    if (std.ascii.eqlIgnoreCase(entry.key_ptr.*, "Profile")) {
                        for (entry.value_ptr.items) |rec| {
                            if (rec == .sobject and rec.sobject.id != null and
                                std.mem.eql(u8, rec.sobject.id.?, profile_id))
                            {
                                if (utils.sobject_get(&rec.sobject.fields, "Name")) |name| {
                                    if (name == .string) return name.string;
                                }
                            }
                        }
                    }
                }
            }
        }
        return null;
    }

    pub fn is_restricted_profile_name(_: *Evaluator, name: []const u8) bool {
        return std.ascii.indexOfIgnoreCase(name, "Minimum Access") != null or
            std.ascii.indexOfIgnoreCase(name, "MinAccess") != null or
            std.ascii.indexOfIgnoreCase(name, "Marketing") != null;
    }

    pub fn is_standard_profile_name(_: *Evaluator, name: []const u8) bool {
        return std.ascii.eqlIgnoreCase(name, "Standard User") or
            std.ascii.eqlIgnoreCase(name, "Standard Platform User") or
            std.ascii.eqlIgnoreCase(name, "Read Only") or
            std.ascii.eqlIgnoreCase(name, "Chatter Free User") or
            std.ascii.eqlIgnoreCase(name, "Chatter External User");
    }

    pub fn is_system_admin_profile_name(_: *Evaluator, name: []const u8) bool {
        return std.ascii.eqlIgnoreCase(name, "System Administrator") or
            std.ascii.eqlIgnoreCase(name, "システム管理者") or
            std.ascii.eqlIgnoreCase(name, "Administrador del sistema") or
            std.ascii.eqlIgnoreCase(name, "Systemadministrator") or
            std.ascii.eqlIgnoreCase(name, "Administrateur système") or
            std.ascii.eqlIgnoreCase(name, "Systeembeheerder") or
            std.ascii.eqlIgnoreCase(name, "Administrador do sistema");
    }

    fn current_profile_name(self: *Evaluator) ?[]const u8 {
        if (self.current_user_override) |user| {
            if (self.get_user_profile_name(user)) |profile_name| return profile_name;
        }
        if (self.find_record_by_id("Profile", self.current_profile_id)) |profile_val| {
            if (profile_val == .sobject) {
                if (utils.sobject_get(&profile_val.sobject.fields, "Name")) |name| {
                    if (name == .string) return name.string;
                }
            }
        }
        if (std.ascii.eqlIgnoreCase(self.current_profile_id, "00e000000000001")) {
            return "System Administrator";
        }
        return null;
    }

    fn user_profile_id(self: *Evaluator, user: *types.SObject) ?[]const u8 {
        _ = self;
        if (utils.sobject_get(&user.fields, "ProfileId") orelse
            utils.sobject_get(&user.fields, "profileId")) |profile_id|
        {
            if (profile_id == .string) return profile_id.string;
        }
        if (utils.sobject_get(&user.fields, "Profile")) |profile| {
            if (profile == .sobject) return profile.sobject.id;
        }
        return null;
    }

    /// Check if an SObject type is a setup/admin object (not CRUD-accessible by Standard User)
    pub fn is_setup_object(_: *Evaluator, obj_name: []const u8) bool {
        const setup_objects = [_][]const u8{
            "User",
            "Profile",
            "PermissionSet",
            "PermissionSetLicense",
            "PermissionSetAssignment",
            "PermissionSetLicenseAssign",
            "PermissionSetGroup",
            "Group",
            "GroupMember",
            "UserRole",
            "Organization",
            "ApexClass",
            "ApexTrigger",
            "AccountBrand",
            "CustomPermission",
            "SetupEntityAccess",
        };
        for (setup_objects) |so| {
            if (std.ascii.eqlIgnoreCase(obj_name, so)) return true;
        }
        return false;
    }

    const TriggerContextValues = struct {
        new_list: *types.ListValue,
        old_list: ?*types.ListValue,
        new_map: ?Value,
        old_map: ?Value,
    };

    fn fire_trigger(
        self: *Evaluator,
        obj_type: []const u8,
        event: ast.TriggerEvent,
        new_records: *std.ArrayListUnmanaged(Value),
        old_records: ?std.ArrayListUnmanaged(Value),
    ) anyerror!void {
        // Trigger recursion guard — limit to 8 levels (Salesforce allows deep trigger chains)
        if (self.trigger_depth >= 8) return;
        self.trigger_depth += 1;
        defer self.trigger_depth -= 1;

        // Lowercase object type for lookup
        const obj_lower = std.ascii.lowerString(
            self.arena.alloc(u8, obj_type.len) catch return,
            obj_type,
        );

        const trigger_list = self.triggers.get(obj_lower) orelse return;

        for (trigger_list.items) |td| {
            if (!trigger_handles_event(td, event)) continue;
            const prev_context = self.trigger_context;
            try self.install_trigger_context(event, new_records, old_records);
            defer self.trigger_context = prev_context;

            try self.execute_trigger_body(td);
        }
    }

    fn trigger_handles_event(td: *ast.TriggerDecl, event: ast.TriggerEvent) bool {
        for (td.events) |e| {
            if (e == event) return true;
        }
        return false;
    }

    fn install_trigger_context(
        self: *Evaluator,
        event: ast.TriggerEvent,
        new_records: *std.ArrayListUnmanaged(Value),
        old_records: ?std.ArrayListUnmanaged(Value),
    ) !void {
        const values = try self.build_trigger_context_values(event, new_records, old_records);
        const is_before = trigger_event_is_before(event);
        const is_delete = event == .before_delete or event == .after_delete;
        self.trigger_context = .{
            .is_executing = true,
            .is_insert = event == .before_insert or event == .after_insert,
            .is_update = event == .before_update or event == .after_update,
            .is_delete = is_delete,
            .is_undelete = event == .after_undelete,
            .is_before = is_before,
            .is_after = !is_before,
            .new_list = if (is_delete) null else Value{ .list = values.new_list },
            .old_list = trigger_old_list_value(is_delete, values.new_list, values.old_list),
            .new_map = values.new_map,
            .old_map = values.old_map,
            .size = @intCast(new_records.items.len),
            .operation_type = trigger_operation_type(event),
        };
    }

    fn build_trigger_context_values(
        self: *Evaluator,
        event: ast.TriggerEvent,
        new_records: *std.ArrayListUnmanaged(Value),
        old_records: ?std.ArrayListUnmanaged(Value),
    ) !TriggerContextValues {
        const new_list = try self.list_from_records(new_records.items);
        const old_list = if (old_records) |ors| try self.list_from_records(ors.items) else null;
        const new_map = if (event != .before_insert)
            Value{ .map = try self.map_from_record_ids(new_records.items) }
        else
            null;
        const old_map = if (old_records) |ors|
            Value{ .map = try self.map_from_record_ids(ors.items) }
        else
            null;
        return .{
            .new_list = new_list,
            .old_list = old_list,
            .new_map = new_map,
            .old_map = old_map,
        };
    }

    fn list_from_records(self: *Evaluator, records: []const Value) !*types.ListValue {
        const list = try self.arena.create(types.ListValue);
        list.* = .{};
        for (records) |item| {
            try list.items.append(self.arena, item);
        }
        return list;
    }

    fn map_from_record_ids(self: *Evaluator, records: []const Value) !*types.MapValue {
        const map = try self.arena.create(types.MapValue);
        map.* = .{};
        for (records) |item| {
            if (item == .sobject and item.sobject.id != null) {
                try map.entries.put(self.arena, item.sobject.id.?, item);
            }
        }
        return map;
    }

    fn trigger_event_is_before(event: ast.TriggerEvent) bool {
        return event == .before_insert or event == .before_update or event == .before_delete;
    }

    fn trigger_old_list_value(
        is_delete: bool,
        new_list: *types.ListValue,
        old_list: ?*types.ListValue,
    ) ?Value {
        if (old_list) |olv| return Value{ .list = olv };
        if (is_delete) return Value{ .list = new_list };
        return null;
    }

    fn trigger_operation_type(event: ast.TriggerEvent) []const u8 {
        return switch (event) {
            .before_insert => "BEFORE_INSERT",
            .before_update => "BEFORE_UPDATE",
            .before_delete => "BEFORE_DELETE",
            .after_insert => "AFTER_INSERT",
            .after_update => "AFTER_UPDATE",
            .after_delete => "AFTER_DELETE",
            .after_undelete => "AFTER_UNDELETE",
        };
    }

    fn execute_trigger_body(self: *Evaluator, td: *ast.TriggerDecl) anyerror!void {
        const trigger_env = try self.global_env.child();
        _ = self.exec_block(td.body, trigger_env) catch |err| {
            return self.wrap_trigger_exception(err);
        };
    }

    fn wrap_trigger_exception(self: *Evaluator, err: anyerror) anyerror!void {
        if (err != error.ApexException) return err;
        const pe = self.pending_exception orelse return err;
        if (pe != .object) return err;
        if (std.ascii.indexOfIgnoreCase(pe.object.class_name, "DmlException") != null) {
            return err;
        }
        const msg = if (pe.object.fields.get("message")) |m|
            (if (m == .string) m.string else "Trigger exception")
        else
            "Trigger exception";
        const dml_exc = try self.arena.create(types.ObjectInstance);
        dml_exc.* = .{ .class_name = "DmlException" };
        try dml_exc.fields.put(self.arena, "message", Value{ .string = msg });
        self.pending_exception = Value{ .object = dml_exc };
        return err;
    }

    fn insert_record(self: *Evaluator, obj: *types.SObject) anyerror!void {
        try self.reject_insert_id(obj);
        try self.apply_missing_field_defaults(obj);
        if (try self.validate_required_fields(obj, false)) |err_msg| {
            try self.throw_dml_exception(err_msg);
        }

        const id = try self.assign_insert_id(obj);
        const timestamps = capture_insert_timestamps(self.arena, obj);
        try self.apply_insert_audit_fields(obj);
        try self.apply_insert_name(obj, id);
        try self.apply_insert_owner(obj);
        try self.resolve_insert_relationship_fields(obj);
        if (self.find_unique_field_conflict(obj, false)) |field_name| {
            obj.id = null;
            try obj.fields.put(self.arena, "Id", Value.null_val);
            return self.throw_duplicate_value(field_name);
        }

        const snapshot = try self.store_insert_snapshot(obj, id, timestamps);
        try self.apply_insert_side_effects(obj, snapshot, id);
    }

    const InsertTimestamps = struct {
        now_str: []const u8,
        generated_created_date: bool,
        generated_last_modified_date: bool,
        generated_system_modstamp: bool,
    };

    fn reject_insert_id(self: *Evaluator, obj: *types.SObject) !void {
        if (obj.id != null) return self.throw_insert_id_error();
        if (utils.sobject_get(&obj.fields, "Id")) |id_val| {
            if (id_val != .null_val) return self.throw_insert_id_error();
        }
    }

    fn throw_insert_id_error(self: *Evaluator) !void {
        try self.throw_dml_exception(
            "INVALID_FIELD_FOR_INSERT_UPDATE: cannot specify Id in an insert call",
        );
    }

    fn assign_insert_id(self: *Evaluator, obj: *types.SObject) ![]const u8 {
        const key_prefix = sobject_key_prefix(obj.type_name);
        const id = try std.fmt.allocPrint(
            self.arena,
            "{s}{d:0>15}",
            .{ &key_prefix, self.next_id },
        );
        self.next_id += 1;
        obj.id = id;
        try obj.fields.put(self.arena, "Id", Value{ .string = id });
        try self.id_type_map.put(self.arena, id, obj.type_name);
        return id;
    }

    fn capture_insert_timestamps(
        arena: std.mem.Allocator,
        obj: *types.SObject,
    ) InsertTimestamps {
        const generated_last_modified_date =
            utils.sobject_get(&obj.fields, "LastModifiedDate") == null;
        return .{
            .now_str = builtins.current_date_time_string(arena) catch "2026-01-01T00:00:00Z",
            .generated_created_date = utils.sobject_get(&obj.fields, "CreatedDate") == null,
            .generated_last_modified_date = generated_last_modified_date,
            .generated_system_modstamp = utils.sobject_get(&obj.fields, "SystemModstamp") == null,
        };
    }

    fn apply_insert_audit_fields(self: *Evaluator, obj: *types.SObject) !void {
        if (utils.sobject_get(&obj.fields, "CreatedById") == null) {
            try obj.fields.put(self.arena, "CreatedById", Value{ .string = "005000000000001" });
        }
        if (utils.sobject_get(&obj.fields, "CreatedBy") == null) {
            try obj.fields.put(self.arena, "CreatedBy", try self.make_system_user_value());
        }
        if (utils.sobject_get(&obj.fields, "LastModifiedById") == null) {
            try obj.fields.put(
                self.arena,
                "LastModifiedById",
                Value{ .string = "005000000000001" },
            );
        }
        if (utils.sobject_get(&obj.fields, "LastModifiedBy") == null) {
            try obj.fields.put(
                self.arena,
                "LastModifiedBy",
                try self.make_system_user_value(),
            );
        }
    }

    fn make_system_user_value(self: *Evaluator) !Value {
        const user = try self.arena.create(types.SObject);
        user.* = .{ .type_name = "User", .id = "005000000000001" };
        try user.fields.put(self.arena, "Id", Value{ .string = "005000000000001" });
        try user.fields.put(self.arena, "Name", Value{ .string = "Test User" });
        try user.fields.put(self.arena, "Username", Value{ .string = "testuser@example.com" });
        return Value{ .sobject = user };
    }

    fn apply_insert_name(self: *Evaluator, obj: *types.SObject, id: []const u8) !void {
        const existing_name = utils.sobject_get(&obj.fields, "Name");
        if (!has_implicit_name_field(obj.type_name)) return;
        if (existing_name != null and existing_name.? != .null_val) return;
        if (std.ascii.eqlIgnoreCase(obj.type_name, "Contact") or
            std.ascii.eqlIgnoreCase(obj.type_name, "Lead"))
        {
            try obj.fields.put(
                self.arena,
                "Name",
                Value{ .string = try self.contact_or_lead_insert_name(obj) },
            );
        } else if (existing_name != null and existing_name.? == .null_val) {
            try obj.fields.put(self.arena, "Name", Value{ .string = id });
        } else {
            const auto_name = try std.fmt.allocPrint(
                self.arena,
                "{s}-{d:0>4}",
                .{ obj.type_name, self.next_id - 1 },
            );
            try obj.fields.put(self.arena, "Name", Value{ .string = auto_name });
        }
    }

    fn contact_or_lead_insert_name(self: *Evaluator, obj: *types.SObject) ![]const u8 {
        const first = if (utils.sobject_get(&obj.fields, "FirstName")) |v|
            (if (v == .string) v.string else "")
        else
            "";
        const last = if (utils.sobject_get(&obj.fields, "LastName")) |v|
            (if (v == .string) v.string else "")
        else
            "";
        if (first.len > 0 and last.len > 0) {
            return std.fmt.allocPrint(self.arena, "{s} {s}", .{ first, last });
        }
        if (last.len > 0) return last;
        if (first.len > 0) return first;
        return std.fmt.allocPrint(
            self.arena,
            "{s}-{d:0>4}",
            .{ obj.type_name, self.next_id - 1 },
        );
    }

    fn apply_insert_owner(self: *Evaluator, obj: *types.SObject) !void {
        if (utils.sobject_get(&obj.fields, "OwnerId") == null) {
            const default_owner_id = if (self.is_guest_user_id(self.current_user_id))
                "005000000000001"
            else
                self.current_user_id;
            try obj.fields.put(self.arena, "OwnerId", Value{ .string = default_owner_id });
        }
        if (utils.sobject_get(&obj.fields, "OwnerId")) |owner_val| {
            if (owner_val == .string and self.is_guest_user_id(owner_val.string)) {
                try obj.fields.put(self.arena, "OwnerId", Value{ .string = "005000000000001" });
            }
        }
    }

    fn resolve_insert_relationship_fields(self: *Evaluator, obj: *types.SObject) !void {
        var rel_keys_buf: [16][]const u8 = undefined;
        var rel_vals_buf: [16]Value = undefined;
        var rel_count: usize = 0;
        for (obj.fields.keys(), obj.fields.values()) |field_name, field_value| {
            if (field_value != .sobject or rel_count >= rel_keys_buf.len) continue;
            if (try self.resolve_insert_relationship_field(
                obj,
                field_name,
                field_value,
            )) |resolved| {
                rel_keys_buf[rel_count] = resolved.key;
                rel_vals_buf[rel_count] = resolved.value;
                rel_count += 1;
            }
        }
        for (rel_keys_buf[0..rel_count], rel_vals_buf[0..rel_count]) |key, value| {
            try obj.fields.put(self.arena, key, value);
        }
    }

    const ResolvedRelationshipField = struct {
        key: []const u8,
        value: Value,
    };

    fn resolve_insert_relationship_field(
        self: *Evaluator,
        obj: *types.SObject,
        field_name: []const u8,
        field_value: Value,
    ) !?ResolvedRelationshipField {
        const fk_name = try std.fmt.allocPrint(self.arena, "{s}Id", .{field_name});
        if (utils.sobject_get(&obj.fields, fk_name) != null) return null;
        if (field_value.sobject.id) |ref_id| {
            return .{ .key = fk_name, .value = Value{ .string = ref_id } };
        }
        return self.resolve_external_id_relationship(fk_name, field_value.sobject);
    }

    fn resolve_external_id_relationship(
        self: *Evaluator,
        fk_name: []const u8,
        ref_obj: *types.SObject,
    ) ?ResolvedRelationshipField {
        for (ref_obj.fields.keys(), ref_obj.fields.values()) |field_name, field_value| {
            if (!is_external_id_field_name(field_name) or field_value != .string) continue;
            const record_id =
                self.find_record_id_by_field_value(
                    ref_obj.type_name,
                    field_name,
                    field_value.string,
                ) orelse return null;
            return .{ .key = fk_name, .value = Value{ .string = record_id } };
        }
        return null;
    }

    fn is_external_id_field_name(field_name: []const u8) bool {
        return std.mem.endsWith(u8, field_name, "__c") or std.mem.endsWith(u8, field_name, "Id__c");
    }

    fn find_record_id_by_field_value(
        self: *Evaluator,
        type_name: []const u8,
        field_name: []const u8,
        field_value: []const u8,
    ) ?[]const u8 {
        const records = self.store.get(type_name) orelse return null;
        for (records.items) |record| {
            if (record != .sobject or record.sobject.id == null) continue;
            if (utils.sobject_get(&record.sobject.fields, field_name)) |stored_val| {
                if (stored_val == .string and std.mem.eql(u8, stored_val.string, field_value)) {
                    return record.sobject.id.?;
                }
            }
        }
        return null;
    }

    fn store_insert_snapshot(
        self: *Evaluator,
        obj: *types.SObject,
        id: []const u8,
        timestamps: InsertTimestamps,
    ) !*types.SObject {
        const snapshot = try self.arena.create(types.SObject);
        snapshot.* = .{ .type_name = obj.type_name, .id = id };
        for (obj.fields.keys(), obj.fields.values()) |k, v| {
            try snapshot.fields.put(self.arena, k, v);
        }
        if (timestamps.generated_created_date) {
            try snapshot.fields.put(
                self.arena,
                "CreatedDate",
                Value{ .string = timestamps.now_str },
            );
        }
        if (timestamps.generated_last_modified_date) {
            try snapshot.fields.put(
                self.arena,
                "LastModifiedDate",
                Value{ .string = timestamps.now_str },
            );
        }
        if (timestamps.generated_system_modstamp) {
            try snapshot.fields.put(
                self.arena,
                "SystemModstamp",
                Value{ .string = timestamps.now_str },
            );
        }
        const gop = try self.store.getOrPut(self.arena, obj.type_name);
        if (!gop.found_existing) {
            gop.value_ptr.* = .empty;
        }
        try gop.value_ptr.append(self.arena, Value{ .sobject = snapshot });
        return snapshot;
    }

    fn apply_insert_side_effects(
        self: *Evaluator,
        obj: *types.SObject,
        snapshot: *types.SObject,
        id: []const u8,
    ) !void {
        try self.apply_content_distribution_defaults(obj, snapshot);
        try self.apply_content_version_defaults(obj, snapshot);
        try self.apply_content_document_link_insert(obj, snapshot);
        try self.apply_content_version_insert(obj, snapshot, id);
        try self.apply_npsp_contact_household_account_insert(obj, snapshot);
        try self.apply_npsp_address_insert(obj);
        try self.create_default_campaign_member_statuses(obj, id);
        try self.create_email_message_relations(obj, id);
        if (std.ascii.eqlIgnoreCase(obj.type_name, "DuplicateRecordItem")) {
            try self.update_duplicate_record_set_count(obj, 1);
        }
        if (std.ascii.eqlIgnoreCase(obj.type_name, "DuplicateRecordSet")) {
            if (utils.sobject_get(&obj.fields, "RecordCount") == null) {
                try obj.fields.put(self.arena, "RecordCount", Value{ .integer = 0 });
                try snapshot.fields.put(self.arena, "RecordCount", Value{ .integer = 0 });
            }
        }
    }

    fn apply_npsp_contact_household_account_insert(
        self: *Evaluator,
        obj: *types.SObject,
        snapshot: *types.SObject,
    ) !void {
        if (!std.ascii.eqlIgnoreCase(obj.type_name, "Contact")) return;
        if (utils.sobject_get(&obj.fields, "AccountId")) |account_id| {
            if (account_id != .null_val) return;
        }
        if (!self.npsp_household_model_available()) return;

        const account = try self.create_npsp_household_account_for_contact(obj);
        const account_id = account.id orelse return;
        try obj.fields.put(self.arena, "AccountId", Value{ .string = account_id });
        try obj.fields.put(self.arena, "Account", Value{ .sobject = account });
        try snapshot.fields.put(self.arena, "AccountId", Value{ .string = account_id });
        try snapshot.fields.put(self.arena, "Account", Value{ .sobject = account });
    }

    fn npsp_household_model_available(self: *Evaluator) bool {
        return self.find_class("CAO_Constants") != null or
            self.find_class("HouseholdNamingService") != null;
    }

    fn create_npsp_household_account_for_contact(
        self: *Evaluator,
        contact: *types.SObject,
    ) !*types.SObject {
        const account = try self.arena.create(types.SObject);
        account.* = .{ .type_name = "Account" };
        const account_id = try self.assign_insert_id(account);
        const account_name = try self.default_household_account_name(contact);
        try account.fields.put(self.arena, "Name", Value{ .string = account_name });
        try account.fields.put(
            self.arena,
            "npe01__SYSTEM_AccountType__c",
            Value{ .string = "Household Account" },
        );
        try account.fields.put(self.arena, "Type", Value{ .string = "Household" });
        try self.apply_insert_audit_fields(account);
        try self.apply_insert_owner(account);

        const gop = try self.store.getOrPut(self.arena, "Account");
        if (!gop.found_existing) gop.value_ptr.* = .empty;
        try gop.value_ptr.append(self.arena, Value{ .sobject = account });
        try self.id_type_map.put(self.arena, account_id, "Account");
        return account;
    }

    fn default_household_account_name(self: *Evaluator, contact: *types.SObject) ![]const u8 {
        const last = if (utils.sobject_get(&contact.fields, "LastName")) |value|
            if (value == .string) value.string else ""
        else
            "";
        if (last.len > 0) {
            return std.fmt.allocPrint(self.arena, "{s} Household", .{last});
        }
        return std.fmt.allocPrint(self.arena, "Household {d}", .{self.next_id});
    }

    fn apply_npsp_address_insert(self: *Evaluator, obj: *types.SObject) !void {
        if (!std.ascii.eqlIgnoreCase(obj.type_name, "Address__c")) return;
        const household_id_val =
            utils.sobject_get(&obj.fields, "Household_Account__c") orelse return;
        if (household_id_val != .string) return;
        const household_id = household_id_val.string;
        try self.apply_npsp_address_to_household(household_id, obj);
        try self.apply_npsp_address_to_household_contacts(household_id, obj);
    }

    fn apply_npsp_address_to_household(
        self: *Evaluator,
        household_id: []const u8,
        address: *types.SObject,
    ) !void {
        const account = self.find_stored_sobject_by_id("Account", household_id) orelse return;
        try self.copy_npsp_address_field(address, account, "MailingStreet__c", "BillingStreet");
        try self.copy_npsp_address_field(address, account, "MailingCity__c", "BillingCity");
        try self.copy_npsp_address_field(address, account, "MailingState__c", "BillingState");
        try self.copy_npsp_address_field(
            address,
            account,
            "MailingPostalCode__c",
            "BillingPostalCode",
        );
        try self.copy_npsp_address_field(address, account, "MailingCountry__c", "BillingCountry");
    }

    fn apply_npsp_address_to_household_contacts(
        self: *Evaluator,
        household_id: []const u8,
        address: *types.SObject,
    ) !void {
        const contacts = self.store.get("Contact") orelse return;
        for (contacts.items) |contact_val| {
            if (contact_val != .sobject) continue;
            const contact = contact_val.sobject;
            const account_id = utils.sobject_get(&contact.fields, "AccountId") orelse continue;
            if (account_id != .string or
                !std.ascii.eqlIgnoreCase(account_id.string, household_id))
            {
                continue;
            }
            try self.copy_npsp_address_field(address, contact, "MailingStreet__c", "MailingStreet");
            try self.copy_npsp_address_field(address, contact, "MailingCity__c", "MailingCity");
            try self.copy_npsp_address_field(address, contact, "MailingState__c", "MailingState");
            try self.copy_npsp_address_field(
                address,
                contact,
                "MailingPostalCode__c",
                "MailingPostalCode",
            );
            try self.copy_npsp_address_field(
                address,
                contact,
                "MailingCountry__c",
                "MailingCountry",
            );
        }
    }

    fn copy_npsp_address_field(
        self: *Evaluator,
        source: *types.SObject,
        target: *types.SObject,
        source_field: []const u8,
        target_field: []const u8,
    ) !void {
        const value = utils.sobject_get(&source.fields, source_field) orelse return;
        if (value == .null_val) return;
        try target.fields.put(self.arena, target_field, value);
    }

    fn find_stored_sobject_by_id(
        self: *Evaluator,
        type_name: []const u8,
        id: []const u8,
    ) ?*types.SObject {
        const records = self.store.get(type_name) orelse return null;
        for (records.items) |record| {
            if (record != .sobject) continue;
            if (record.sobject.id) |record_id| {
                if (std.ascii.eqlIgnoreCase(record_id, id)) return record.sobject;
            }
        }
        return null;
    }

    fn apply_content_distribution_defaults(
        self: *Evaluator,
        obj: *types.SObject,
        snapshot: *types.SObject,
    ) !void {
        if (!std.ascii.eqlIgnoreCase(obj.type_name, "ContentDistribution")) return;
        if (utils.sobject_get(&obj.fields, "ContentDownloadUrl") != null) return;
        const url = Value{ .string = "https://mock.salesforce.com/content/download" };
        try obj.fields.put(self.arena, "ContentDownloadUrl", url);
        try snapshot.fields.put(self.arena, "ContentDownloadUrl", url);
    }

    fn apply_content_version_defaults(
        self: *Evaluator,
        obj: *types.SObject,
        snapshot: *types.SObject,
    ) !void {
        if (!std.ascii.eqlIgnoreCase(obj.type_name, "ContentVersion")) return;
        if (utils.sobject_get(&obj.fields, "IsLatest") != null) return;
        try obj.fields.put(self.arena, "IsLatest", Value{ .boolean = true });
        try snapshot.fields.put(self.arena, "IsLatest", Value{ .boolean = true });
    }

    fn apply_content_document_link_insert(
        self: *Evaluator,
        obj: *types.SObject,
        snapshot: *types.SObject,
    ) !void {
        if (!std.ascii.eqlIgnoreCase(obj.type_name, "ContentDocumentLink")) return;
        try self.validate_content_document_link_target(obj);
        const cd_id_val = utils.sobject_get(&obj.fields, "ContentDocumentId");
        if (cd_id_val != null and cd_id_val.? == .string) {
            if (self.find_record_by_id("ContentDocument", cd_id_val.?.string)) |cd_rec| {
                if (cd_rec == .sobject) {
                    try obj.fields.put(self.arena, "ContentDocument", cd_rec);
                    try snapshot.fields.put(self.arena, "ContentDocument", cd_rec);
                }
            }
        }
    }

    fn validate_content_document_link_target(self: *Evaluator, obj: *types.SObject) !void {
        const linked_entity_id = utils.sobject_get(&obj.fields, "LinkedEntityId") orelse return;
        if (linked_entity_id != .string) return;
        if (self.record_id_exists(linked_entity_id.string)) return;
        try self.throw_dml_exception(
            "INVALID_FIELD_FOR_INSERT_UPDATE: LinkedEntityId does not reference a valid record",
        );
    }

    fn record_id_exists(self: *Evaluator, record_id: []const u8) bool {
        var store_iter = self.store.iterator();
        while (store_iter.next()) |entry| {
            for (entry.value_ptr.items) |record| {
                if (record == .sobject and record.sobject.id != null) {
                    if (std.mem.eql(u8, record.sobject.id.?, record_id)) return true;
                }
            }
        }
        return false;
    }

    fn apply_content_version_insert(
        self: *Evaluator,
        obj: *types.SObject,
        snapshot: *types.SObject,
        id: []const u8,
    ) !void {
        if (!std.ascii.eqlIgnoreCase(obj.type_name, "ContentVersion")) return;
        const first_pub_loc = utils.sobject_get(&obj.fields, "FirstPublishLocationId");
        const cd_id = try self.alloc_id();
        const file_type = self.content_version_file_type(obj);
        try self.create_content_document_for_version(obj, cd_id, id, file_type);
        try obj.fields.put(self.arena, "ContentDocumentId", Value{ .string = cd_id });
        try snapshot.fields.put(self.arena, "ContentDocumentId", Value{ .string = cd_id });
        if (first_pub_loc != null and first_pub_loc.? != .null_val) {
            try self.create_content_document_link_for_version(
                cd_id,
                id,
                file_type,
                first_pub_loc.?,
            );
        }
    }

    fn content_version_file_type(self: *Evaluator, obj: *types.SObject) []const u8 {
        _ = self;
        const path_on_client = if (utils.sobject_get(&obj.fields, "PathOnClient")) |poc|
            (if (poc == .string) poc.string else "")
        else
            "";
        if (std.ascii.endsWithIgnoreCase(path_on_client, ".png")) return "PNG";
        if (std.ascii.endsWithIgnoreCase(path_on_client, ".jpg") or
            std.ascii.endsWithIgnoreCase(path_on_client, ".jpeg")) return "JPG";
        if (std.ascii.endsWithIgnoreCase(path_on_client, ".gif")) return "GIF";
        if (std.ascii.endsWithIgnoreCase(path_on_client, ".pdf")) return "PDF";
        if (std.ascii.endsWithIgnoreCase(path_on_client, ".docx")) return "WORD_X";
        if (std.ascii.endsWithIgnoreCase(path_on_client, ".xlsx")) return "EXCEL_X";
        if (std.ascii.endsWithIgnoreCase(path_on_client, ".pptx")) return "POWER_POINT_X";
        if (std.ascii.endsWithIgnoreCase(path_on_client, ".m4a")) return "M4A";
        return "UNKNOWN";
    }

    fn create_content_document_for_version(
        self: *Evaluator,
        obj: *types.SObject,
        cd_id: []const u8,
        version_id: []const u8,
        file_type: []const u8,
    ) !void {
        const cd = try self.arena.create(types.SObject);
        cd.* = .{ .type_name = "ContentDocument", .id = cd_id };
        try cd.fields.put(self.arena, "Id", Value{ .string = cd_id });
        try cd.fields.put(self.arena, "LatestPublishedVersionId", Value{ .string = version_id });
        try cd.fields.put(
            self.arena,
            "Title",
            utils.sobject_get(&obj.fields, "Title") orelse Value{ .string = "Untitled" },
        );
        try cd.fields.put(self.arena, "FileType", Value{ .string = file_type });
        try self.append_sobject_to_store("ContentDocument", cd);
    }

    fn create_content_document_link_for_version(
        self: *Evaluator,
        cd_id: []const u8,
        version_id: []const u8,
        file_type: []const u8,
        linked_entity_id: Value,
    ) !void {
        const cdl_id = try self.alloc_id();
        const cdl = try self.arena.create(types.SObject);
        cdl.* = .{ .type_name = "ContentDocumentLink", .id = cdl_id };
        try cdl.fields.put(self.arena, "Id", Value{ .string = cdl_id });
        try cdl.fields.put(self.arena, "ContentDocumentId", Value{ .string = cd_id });
        try cdl.fields.put(self.arena, "LinkedEntityId", linked_entity_id);
        try cdl.fields.put(
            self.arena,
            "ContentDocument",
            try self.content_document_ref(cd_id, version_id, file_type),
        );
        try self.append_sobject_to_store("ContentDocumentLink", cdl);
    }

    fn content_document_ref(
        self: *Evaluator,
        cd_id: []const u8,
        version_id: []const u8,
        file_type: []const u8,
    ) !Value {
        const cd_ref = try self.arena.create(types.SObject);
        cd_ref.* = .{ .type_name = "ContentDocument", .id = cd_id };
        try cd_ref.fields.put(self.arena, "Id", Value{ .string = cd_id });
        try cd_ref.fields.put(
            self.arena,
            "LatestPublishedVersionId",
            Value{ .string = version_id },
        );
        try cd_ref.fields.put(self.arena, "FileType", Value{ .string = file_type });
        return Value{ .sobject = cd_ref };
    }

    const DefaultCampaignMemberStatus = struct {
        label: []const u8,
        is_default: bool,
        has_responded: bool,
        sort_order: i64,
    };

    fn create_default_campaign_member_statuses(
        self: *Evaluator,
        obj: *types.SObject,
        campaign_id: []const u8,
    ) !void {
        if (!std.ascii.eqlIgnoreCase(obj.type_name, "Campaign")) return;
        const default_statuses = [_]DefaultCampaignMemberStatus{
            .{
                .label = "Sent",
                .is_default = true,
                .has_responded = false,
                .sort_order = 1,
            },
            .{
                .label = "Responded",
                .is_default = false,
                .has_responded = true,
                .sort_order = 2,
            },
        };
        for (default_statuses) |status| {
            try self.create_campaign_member_status(campaign_id, status);
        }
    }

    fn create_campaign_member_status(
        self: *Evaluator,
        campaign_id: []const u8,
        status: DefaultCampaignMemberStatus,
    ) !void {
        const cms_id = try self.alloc_id();
        const cms = try self.arena.create(types.SObject);
        cms.* = .{ .type_name = "CampaignMemberStatus", .id = cms_id };
        try cms.fields.put(self.arena, "Id", Value{ .string = cms_id });
        try cms.fields.put(self.arena, "CampaignId", Value{ .string = campaign_id });
        try cms.fields.put(self.arena, "Label", Value{ .string = status.label });
        try cms.fields.put(self.arena, "IsDefault", Value{ .boolean = status.is_default });
        try cms.fields.put(self.arena, "HasResponded", Value{ .boolean = status.has_responded });
        try cms.fields.put(self.arena, "SortOrder", Value{ .integer = status.sort_order });
        try self.append_sobject_to_store("CampaignMemberStatus", cms);
    }

    fn create_email_message_relations(
        self: *Evaluator,
        obj: *types.SObject,
        email_message_id: []const u8,
    ) !void {
        if (!std.ascii.eqlIgnoreCase(obj.type_name, "EmailMessage")) return;
        const to_ids_val = utils.sobject_get(&obj.fields, "toIds") orelse return;
        if (to_ids_val != .list) return;
        for (to_ids_val.list.items.items) |to_id_item| {
            if (to_id_item == .string) {
                try self.create_email_message_relation(email_message_id, to_id_item);
            }
        }
    }

    fn create_email_message_relation(
        self: *Evaluator,
        email_message_id: []const u8,
        relation_id: Value,
    ) !void {
        const emr_id = try self.alloc_id();
        const emr = try self.arena.create(types.SObject);
        emr.* = .{ .type_name = "EmailMessageRelation", .id = emr_id };
        try emr.fields.put(self.arena, "Id", Value{ .string = emr_id });
        try emr.fields.put(self.arena, "EmailMessageId", Value{ .string = email_message_id });
        try emr.fields.put(self.arena, "RelationId", relation_id);
        try emr.fields.put(self.arena, "RelationType", Value{ .string = "ToAddress" });
        try self.append_sobject_to_store("EmailMessageRelation", emr);
    }

    fn append_sobject_to_store(self: *Evaluator, type_name: []const u8, obj: *types.SObject) !void {
        const gop = try self.store.getOrPut(self.arena, type_name);
        if (!gop.found_existing) gop.value_ptr.* = .empty;
        try gop.value_ptr.append(self.arena, Value{ .sobject = obj });
    }

    /// Validate required fields on an SObject.
    /// When `only_present` is true (for updates), only validate fields that are
    /// explicitly present in the object's fields map — missing fields are not changed.
    fn validate_required_fields(
        self: *Evaluator,
        obj: *types.SObject,
        only_present: bool,
    ) !?[]const u8 {
        const type_name = obj.type_name;
        if (std.ascii.eqlIgnoreCase(type_name, "Account")) {
            const name_val = utils.sobject_get(&obj.fields, "Name");
            // Insert: field must exist and be non-null/non-empty
            // Update: field must not be explicitly set to null/empty
            if (name_val == null) {
                if (!only_present) return try self.required_field_missing_message("Name");
            } else if (name_val.? == .null_val) {
                return "REQUIRED_FIELD_MISSING: Required fields are missing: [Name]";
            } else if (name_val.? == .string and name_val.?.string.len == 0) {
                return "REQUIRED_FIELD_MISSING: Required fields are missing: [Name]";
            }
        }
        if (std.ascii.eqlIgnoreCase(type_name, "Contact")) {
            const name_val = utils.sobject_get(&obj.fields, "LastName");
            if (name_val == null) {
                if (!only_present) {
                    return try self.required_field_missing_message("LastName");
                }
            } else if (name_val.? == .null_val) {
                return "REQUIRED_FIELD_MISSING: Required fields are missing: [LastName]";
            }
        }
        if (std.ascii.eqlIgnoreCase(type_name, "Opportunity")) {
            const name_val = utils.sobject_get(&obj.fields, "Name");
            if (name_val == null) {
                if (!only_present) return try self.required_field_missing_message("Name");
            } else if (name_val.? == .null_val) {
                return "REQUIRED_FIELD_MISSING: Required fields are missing: [Name]";
            }
        }
        if (std.ascii.eqlIgnoreCase(type_name, "ContentVersion")) {
            if (validate_content_version_required(obj)) |err_msg| return err_msg;
        }
        if (std.ascii.eqlIgnoreCase(type_name, "Address__c")) {
            if (try self.validate_npsp_address_fields(obj)) |err_msg| return err_msg;
        }
        if (self.field_metadata.get(type_name)) |field_map| {
            var iter = field_map.iterator();
            while (iter.next()) |entry| {
                const field_name = entry.key_ptr.*;
                const meta = entry.value_ptr.*;
                if (!meta.is_required) continue;

                const field_val = utils.sobject_get(&obj.fields, field_name);
                if (field_val == null) {
                    if (!only_present) {
                        return try self.required_field_missing_message(field_name);
                    }
                    continue;
                }
                if (field_val.? == .null_val) {
                    return try self.required_field_missing_message(field_name);
                }
                if (field_val.? == .string and
                    std.mem.trim(u8, field_val.?.string, " \t\r\n").len == 0)
                {
                    return try self.required_field_missing_message(field_name);
                }
            }
        }
        return null;
    }

    fn validate_npsp_address_fields(
        self: *Evaluator,
        obj: *types.SObject,
    ) !?[]const u8 {
        if (utils.sobject_get(&obj.fields, "Household_Account__c")) |household_id| {
            if (household_id == .string and
                !std.mem.startsWith(u8, household_id.string, "001"))
            {
                const message = try std.fmt.allocPrint(
                    self.arena,
                    "FIELD_INTEGRITY_EXCEPTION: Household Account: id value of incorrect type: {s}",
                    .{household_id.string},
                );
                return message;
            }
        }
        if (utils.sobject_get(&obj.fields, "MailingCity__c")) |city| {
            if (city == .string and city.string.len > 40) {
                return "STRING_TOO_LONG: Billing City: data value too large";
            }
        }
        return null;
    }

    fn required_field_missing_message(
        self: *Evaluator,
        field_name: []const u8,
    ) ![]const u8 {
        return std.fmt.allocPrint(
            self.arena,
            "REQUIRED_FIELD_MISSING: Required fields are missing: [{s}]",
            .{field_name},
        );
    }

    /// ContentVersion の必須フィールド (`PathOnClient`, `VersionData`) を
    /// チェックする。違反があれば Apex と同じ REQUIRED_FIELD_MISSING
    /// メッセージを返す。`validate_required_fields` の ContentVersion ブロックを抽出。
    fn validate_content_version_required(obj: *types.SObject) ?[]const u8 {
        const poc_val = utils.sobject_get(&obj.fields, "PathOnClient");
        if (poc_val == null or poc_val.? == .null_val) {
            return "REQUIRED_FIELD_MISSING: Required fields are missing: [PathOnClient]";
        }
        if (poc_val.? == .string and poc_val.?.string.len == 0) {
            return "REQUIRED_FIELD_MISSING: Required fields are missing: [PathOnClient]";
        }
        const vd_val = utils.sobject_get(&obj.fields, "VersionData");
        if (vd_val == null or vd_val.? == .null_val) {
            return "REQUIRED_FIELD_MISSING: Required fields are missing: [VersionData]";
        }
        if (vd_val.? == .object) {
            if (utils.sobject_get(&vd_val.?.object.fields, "value")) |inner| {
                if (inner == .string and inner.string.len == 0) {
                    return "REQUIRED_FIELD_MISSING: Required fields are missing: [VersionData]";
                }
            }
        }
        return null;
    }

    fn apply_missing_field_defaults(self: *Evaluator, obj: *types.SObject) !void {
        if (self.field_defaults.get(obj.type_name)) |defaults| {
            // `default_val` avoids shadowing the module-level
            // `default_value` function produced by the snake_case rename.
            for (defaults.keys(), defaults.values()) |field_name, default_val| {
                if (self.get_s_object_field_value_case_insensitive(obj, field_name) != null) {
                    continue;
                }
                try utils.sobject_put(&obj.fields, self.arena, field_name, default_val);
            }
        }
        // Platform-level defaults that don't live in field-meta.xml. Real Apex
        // sets these for common standard objects when the caller omits them;
        // without the defaults tests that filter by IsActive=TRUE etc. miss
        // their freshly-inserted records.
        try self.apply_standard_object_defaults(obj);
    }

    fn apply_standard_object_defaults(self: *Evaluator, obj: *types.SObject) !void {
        if (std.ascii.eqlIgnoreCase(obj.type_name, "User")) {
            if (self.get_s_object_field_value_case_insensitive(obj, "IsActive") == null) {
                try utils.sobject_put(
                    &obj.fields,
                    self.arena,
                    "IsActive",
                    Value{ .boolean = true },
                );
            }
        }
    }

    fn update_record(self: *Evaluator, obj: *types.SObject) anyerror!void {
        // Validate only fields explicitly present (Salesforce doesn't
        // re-validate all required fields on update)
        if (try self.validate_required_fields(obj, true)) |err_msg| {
            const exc = try self.arena.create(types.ObjectInstance);
            exc.* = .{ .class_name = "DmlException" };
            try exc.fields.put(self.arena, "message", Value{ .string = err_msg });
            self.pending_exception = Value{ .object = exc };
            return error.ApexException;
        }
        // If no Id, throw DmlException
        try self.ensure_update_record_id(obj);
        // Validate that the record exists in the store (if it has an Id)
        if (obj.id) |record_id| {
            try self.reject_guest_owner_update(obj);
            const found_rec = self.find_update_target_record(obj, record_id);
            if (found_rec == null) {
                const exc = try self.arena.create(types.ObjectInstance);
                exc.* = .{ .class_name = "DmlException" };
                try exc.fields.put(
                    self.arena,
                    "message",
                    Value{
                        .string = "INVALID_CROSS_REFERENCE_KEY: invalid cross reference id",
                    },
                );
                self.pending_exception = Value{ .object = exc };
                return error.ApexException;
            }
            if (self.find_unique_field_conflict(obj, true)) |field_name| {
                return self.throw_duplicate_value(field_name);
            }
            try self.copy_update_fields_to_store(obj, found_rec.?);
        }
    }

    fn ensure_update_record_id(self: *Evaluator, obj: *types.SObject) !void {
        if (obj.id != null) return;
        const id_field = utils.sobject_get(&obj.fields, "Id");
        if (id_field == null or id_field.? == .null_val) {
            const exc = try self.arena.create(types.ObjectInstance);
            exc.* = .{ .class_name = "DmlException" };
            try exc.fields.put(
                self.arena,
                "message",
                Value{ .string = "MISSING_ARGUMENT: Id not specified in an update call:" },
            );
            self.pending_exception = Value{ .object = exc };
            return error.ApexException;
        }
        if (id_field.? == .string) obj.id = id_field.?.string;
    }

    const guest_owner_record_error_message =
        "FIELD_INTEGRITY_EXCEPTION, field integrity exception " ++
        "(Guest users cannot be record owners.)";

    fn reject_guest_owner_update(self: *Evaluator, obj: *types.SObject) !void {
        const owner_val = utils.sobject_get(&obj.fields, "OwnerId") orelse return;
        if (owner_val != .string or !self.is_guest_user_id(owner_val.string)) return;
        const exc = try self.arena.create(types.ObjectInstance);
        exc.* = .{ .class_name = "DmlException" };
        try exc.fields.put(
            self.arena,
            "message",
            Value{ .string = guest_owner_record_error_message },
        );
        self.pending_exception = Value{ .object = exc };
        return error.ApexException;
    }

    fn find_update_target_record(
        self: *Evaluator,
        obj: *types.SObject,
        record_id: []const u8,
    ) ?*types.SObject {
        if (self.store.getPtr(obj.type_name)) |records| {
            for (records.items) |rec| {
                if (rec == .sobject and rec.sobject.id != null and
                    std.mem.eql(u8, rec.sobject.id.?, record_id))
                {
                    return rec.sobject;
                }
            }
        }
        if (utils.sobject_get(&obj.fields, "Id")) |id_val| {
            if (id_val == .string) {
                return self.find_update_target_record_by_id_field(obj, id_val.string);
            }
        }
        return null;
    }

    fn find_update_target_record_by_id_field(
        self: *Evaluator,
        obj: *types.SObject,
        id_field: []const u8,
    ) ?*types.SObject {
        var store_iter = self.store.iterator();
        while (store_iter.next()) |entry| {
            if (!std.ascii.eqlIgnoreCase(entry.key_ptr.*, obj.type_name)) continue;
            for (entry.value_ptr.items) |rec| {
                if (rec == .sobject and rec.sobject.id != null and
                    std.mem.eql(u8, rec.sobject.id.?, id_field))
                {
                    return rec.sobject;
                }
            }
        }
        return null;
    }

    fn copy_update_fields_to_store(
        self: *Evaluator,
        obj: *types.SObject,
        stored: *types.SObject,
    ) !void {
        const now_str = builtins.current_date_time_string(self.arena) catch "2026-01-01T00:00:00Z";
        utils.sobject_put(
            &obj.fields,
            self.arena,
            "LastModifiedDate",
            Value{ .string = now_str },
        ) catch {};
        utils.sobject_put(
            &obj.fields,
            self.arena,
            "LastModifiedById",
            Value{ .string = "005000000000001" },
        ) catch {};
        if (utils.sobject_get(&obj.fields, "LastModifiedBy") == null) {
            try self.put_last_modified_by_stub(obj);
        }
        if (stored == obj) {
            const keys = self.arena.dupe([]const u8, obj.fields.keys()) catch return;
            const vals = self.arena.dupe(Value, obj.fields.values()) catch return;
            for (keys, vals) |k, v| {
                utils.sobject_put(&stored.fields, self.arena, k, v) catch {};
            }
        } else {
            for (obj.fields.keys(), obj.fields.values()) |k, v| {
                utils.sobject_put(&stored.fields, self.arena, k, v) catch {};
            }
        }
        try self.refresh_contact_or_lead_name_after_update(obj, stored);
    }

    fn refresh_contact_or_lead_name_after_update(
        self: *Evaluator,
        obj: *types.SObject,
        stored: *types.SObject,
    ) !void {
        if (!std.ascii.eqlIgnoreCase(stored.type_name, "Contact") and
            !std.ascii.eqlIgnoreCase(stored.type_name, "Lead"))
        {
            return;
        }
        if (utils.sobject_get(&obj.fields, "FirstName") == null and
            utils.sobject_get(&obj.fields, "LastName") == null)
        {
            return;
        }
        try utils.sobject_put(
            &stored.fields,
            self.arena,
            "Name",
            Value{ .string = try self.contact_or_lead_insert_name(stored) },
        );
    }

    fn put_last_modified_by_stub(self: *Evaluator, obj: *types.SObject) !void {
        const modified_by = try self.arena.create(types.SObject);
        modified_by.* = .{ .type_name = "User", .id = "005000000000001" };
        try modified_by.fields.put(self.arena, "Id", Value{ .string = "005000000000001" });
        try modified_by.fields.put(self.arena, "Name", Value{ .string = "Test User" });
        try modified_by.fields.put(
            self.arena,
            "Username",
            Value{ .string = "testuser@example.com" },
        );
        try obj.fields.put(self.arena, "LastModifiedBy", Value{ .sobject = modified_by });
    }

    /// `upsert_record` の external id 分岐を抽出。マッチする既存レコードが
    /// 見つかり update したら `true` を、まだ insert に落ちるべき場合は
    /// `false` を返す。
    fn upsert_by_external_id(
        self: *Evaluator,
        obj: *types.SObject,
        field_name: []const u8,
    ) anyerror!bool {
        if (std.ascii.eqlIgnoreCase(field_name, "Id")) {
            if (obj.id != null) {
                try self.update_record(obj);
                return true;
            }
            if (utils.sobject_get(&obj.fields, "Id")) |id_val| {
                if (id_val == .string and id_val.string.len > 0) {
                    obj.id = id_val.string;
                    try self.update_record(obj);
                    return true;
                }
            }
            try self.insert_record(obj);
            return true;
        }
        const field_value = get_upsert_field_value(obj, field_name);
        if (field_value == .null_val) {
            const exc = try self.arena.create(types.ObjectInstance);
            exc.* = .{ .class_name = "DmlException" };
            try exc.fields.put(
                self.arena,
                "message",
                Value{
                    .string = "MISSING_ARGUMENT: external id field not specified in an upsert call",
                },
            );
            self.pending_exception = Value{ .object = exc };
            return error.ApexException;
        }
        if (self.find_record_by_field_value(obj.type_name, field_name, field_value)) |existing| {
            if (existing.id) |existing_id| {
                obj.id = existing_id;
                try utils.sobject_put(
                    &obj.fields,
                    self.arena,
                    "Id",
                    Value{ .string = existing_id },
                );
            }
            try self.update_record(obj);
            return true;
        }
        return false;
    }

    fn upsert_record(
        self: *Evaluator,
        obj: *types.SObject,
        external_id_field: ?[]const u8,
    ) anyerror!void {
        if (external_id_field) |field_name| {
            if (try self.upsert_by_external_id(obj, field_name)) return;
        }
        if (obj.id != null) {
            // Check if record exists in store
            const record_id = obj.id.?;
            var found = false;
            if (self.store.getPtr(obj.type_name)) |records| {
                for (records.items) |rec| {
                    if (rec == .sobject and rec.sobject.id != null and
                        std.mem.eql(u8, rec.sobject.id.?, record_id))
                    {
                        found = true;
                        break;
                    }
                }
            }
            // Also check Id field
            if (!found) {
                if (utils.sobject_get(&obj.fields, "Id")) |id_val| {
                    if (id_val == .string) {
                        var store_iter = self.store.iterator();
                        while (store_iter.next()) |entry| {
                            if (std.ascii.eqlIgnoreCase(entry.key_ptr.*, obj.type_name)) {
                                for (entry.value_ptr.items) |rec| {
                                    if (rec == .sobject and rec.sobject.id != null and
                                        std.mem.eql(u8, rec.sobject.id.?, id_val.string))
                                    {
                                        found = true;
                                        break;
                                    }
                                }
                            }
                        }
                    }
                }
            }
            if (found) {
                try self.update_record(obj);
            } else {
                // Invalid cross reference Id — throw DmlException
                const exc = try self.arena.create(types.ObjectInstance);
                exc.* = .{ .class_name = "DmlException" };
                try exc.fields.put(
                    self.arena,
                    "message",
                    Value{
                        .string = "INVALID_CROSS_REFERENCE_KEY: invalid cross reference id",
                    },
                );
                self.pending_exception = Value{ .object = exc };
                return error.ApexException;
            }
        } else {
            try self.insert_record(obj);
        }
    }

    fn delete_record(self: *Evaluator, obj: *types.SObject) anyerror!void {
        if (obj.id == null) {
            const exc = try self.arena.create(types.ObjectInstance);
            exc.* = .{ .class_name = "DmlException" };
            try exc.fields.put(
                self.arena,
                "message",
                Value{ .string = "ENTITY_IS_DELETED: entity is deleted" },
            );
            self.pending_exception = Value{ .object = exc };
            return error.ApexException;
        }
        var found = false;
        if (self.store.getPtr(obj.type_name)) |records| {
            var i: usize = 0;
            while (i < records.items.len) {
                if (records.items[i] == .sobject and records.items[i].sobject.id != null and
                    std.mem.eql(u8, records.items[i].sobject.id.?, obj.id.?))
                {
                    // Move to trash for potential undelete
                    const removed = records.orderedRemove(i);
                    if (removed == .sobject) {
                        try removed.sobject.fields.put(
                            self.arena,
                            "IsDeleted",
                            Value{ .boolean = true },
                        );
                    }
                    const trash_gop = try self.trash.getOrPut(self.arena, obj.type_name);
                    if (!trash_gop.found_existing) trash_gop.value_ptr.* = .empty;
                    try trash_gop.value_ptr.append(self.arena, removed);
                    // Mark the original record's IsDeleted field
                    try obj.fields.put(self.arena, "IsDeleted", Value{ .boolean = true });
                    found = true;
                } else {
                    i += 1;
                }
            }
        }
        if (!found) {
            const exc = try self.arena.create(types.ObjectInstance);
            exc.* = .{ .class_name = "DmlException" };
            try exc.fields.put(
                self.arena,
                "message",
                Value{ .string = "ENTITY_IS_DELETED: entity is deleted" },
            );
            self.pending_exception = Value{ .object = exc };
            return error.ApexException;
        }
        // Auto-maintain RecordCount on DuplicateRecordSet when DuplicateRecordItem is deleted
        if (std.ascii.eqlIgnoreCase(obj.type_name, "DuplicateRecordItem")) {
            try self.update_duplicate_record_set_count(obj, -1);
        }
    }

    /// Reverse an AFTER_UNDELETE when its trigger added errors: move each record
    /// back from the active store into the recycle bin, mirroring real Apex's
    /// transactional rollback so the same record can be undeleted again.
    fn rollback_undelete(self: *Evaluator, record_list: *std.ArrayListUnmanaged(Value)) !void {
        for (record_list.items) |item| {
            if (item != .sobject) continue;
            const obj = item.sobject;
            const rid = obj.id orelse continue;
            if (self.store.getPtr(obj.type_name)) |recs| {
                var idx: usize = 0;
                while (idx < recs.items.len) {
                    const rec = recs.items[idx];
                    if (rec == .sobject and rec.sobject.id != null and
                        std.mem.eql(u8, rec.sobject.id.?, rid))
                    {
                        const pulled = recs.orderedRemove(idx);
                        if (pulled == .sobject) {
                            try pulled.sobject.fields.put(
                                self.arena,
                                "IsDeleted",
                                Value{ .boolean = true },
                            );
                        }
                        const gop = try self.trash.getOrPut(self.arena, obj.type_name);
                        if (!gop.found_existing) gop.value_ptr.* = .empty;
                        try gop.value_ptr.append(self.arena, pulled);
                        try obj.fields.put(self.arena, "IsDeleted", Value{ .boolean = true });
                        break;
                    } else {
                        idx += 1;
                    }
                }
            }
        }
    }

    fn undelete_record(self: *Evaluator, obj: *types.SObject) anyerror!void {
        if (obj.id == null) {
            const exc = try self.arena.create(types.ObjectInstance);
            exc.* = .{ .class_name = "DmlException" };
            try exc.fields.put(
                self.arena,
                "message",
                Value{ .string = "UNDELETE_FAILED: entity not in recycle bin" },
            );
            self.pending_exception = Value{ .object = exc };
            return error.ApexException;
        }
        var found = false;
        if (self.trash.getPtr(obj.type_name)) |trashed| {
            var i: usize = 0;
            while (i < trashed.items.len) {
                if (trashed.items[i] == .sobject and trashed.items[i].sobject.id != null and
                    std.mem.eql(u8, trashed.items[i].sobject.id.?, obj.id.?))
                {
                    const restored = trashed.orderedRemove(i);
                    if (restored == .sobject) {
                        try restored.sobject.fields.put(
                            self.arena,
                            "IsDeleted",
                            Value{ .boolean = false },
                        );
                    }
                    const gop = try self.store.getOrPut(self.arena, obj.type_name);
                    if (!gop.found_existing) gop.value_ptr.* = .empty;
                    try gop.value_ptr.append(self.arena, restored);
                    try obj.fields.put(self.arena, "IsDeleted", Value{ .boolean = false });
                    found = true;
                } else {
                    i += 1;
                }
            }
        }
        if (!found) {
            const exc = try self.arena.create(types.ObjectInstance);
            exc.* = .{ .class_name = "DmlException" };
            try exc.fields.put(
                self.arena,
                "message",
                Value{ .string = "UNDELETE_FAILED: entity not in recycle bin" },
            );
            self.pending_exception = Value{ .object = exc };
            return error.ApexException;
        }
    }

    /// Auto-maintain RecordCount on DuplicateRecordSet when
    /// DuplicateRecordItem is inserted/deleted.
    /// `delta` is +1 for insert, -1 for delete.
    fn update_duplicate_record_set_count(self: *Evaluator, dri: *types.SObject, delta: i64) !void {
        const drs_id_val = utils.sobject_get(&dri.fields, "DuplicateRecordSetId") orelse return;
        if (drs_id_val != .string) return;
        const drs_id = drs_id_val.string;

        // Find the DuplicateRecordSet in the store and update RecordCount
        if (self.store.getPtr("DuplicateRecordSet")) |records| {
            for (records.items) |rec| {
                if (rec == .sobject and rec.sobject.id != null and
                    std.mem.eql(u8, rec.sobject.id.?, drs_id))
                {
                    const old_count: i64 =
                        if (utils.sobject_get(&rec.sobject.fields, "RecordCount")) |v|
                            (if (v == .integer) v.integer else 0)
                        else
                            0;
                    const new_count = @max(old_count + delta, 0);
                    try rec.sobject.fields.put(
                        self.arena,
                        "RecordCount",
                        Value{ .integer = new_count },
                    );
                    break;
                }
            }
        }
    }

    /// Auto-delete DuplicateRecordSet records with RecordCount < 2
    /// (and not freshly created with count 0).
    /// This mirrors the Salesforce trigger chain behavior:
    /// DRI delete → DRS trigger → auto-delete orphaned DRS.
    fn cleanup_orphaned_duplicate_record_sets(self: *Evaluator) !void {
        if (self.store.getPtr("DuplicateRecordSet")) |records| {
            var i: usize = 0;
            while (i < records.items.len) {
                const rec = records.items[i];
                if (rec == .sobject) {
                    const count = if (utils.sobject_get(&rec.sobject.fields, "RecordCount")) |v|
                        (if (v == .integer) v.integer else 0)
                    else
                        0;
                    // Delete DRS when RecordCount > 0 but < 2
                    // (i.e., 1 — single duplicate remaining).
                    // Also delete when RecordCount == 0 and there were items
                    // before (indicated by Object_Type__c being set).
                    if (count >= 1 and count < 2) {
                        const removed = records.orderedRemove(i);
                        const trash_gop = try self.trash.getOrPut(self.arena, "DuplicateRecordSet");
                        if (!trash_gop.found_existing) trash_gop.value_ptr.* = .empty;
                        try trash_gop.value_ptr.append(self.arena, removed);
                        continue;
                    }
                }
                i += 1;
            }
        }
    }

    /// Attach the fflib-compatible `getInaccessibleFields()` payload onto a
    /// freshly-created QueryException. Layout is `Map<String, Set<String>>`
    /// where the key is the SObject API name and the value is the set of
    /// fields the running user cannot read. If object-level access is denied
    /// we surface every SELECT column; if only a subset of fields fail the
    /// field-level check we list just those fields. Called from the user-mode
    /// SOQL security gate before the exception is stashed in pending_exception.
    fn attach_inaccessible_fields_to_exception(
        self: *Evaluator,
        exc: *types.ObjectInstance,
        soql: []const u8,
        from_type_name: []const u8,
    ) !void {
        const inaccessible_map = try self.arena.create(types.MapValue);
        inaccessible_map.* = .{};
        const field_set = try self.arena.create(types.SetValue);
        field_set.* = .{};

        const select_start = if (std.ascii.indexOfIgnoreCase(soql, "SELECT")) |si| si + 6 else 0;
        const from_start = std.ascii.indexOfIgnoreCase(soql, "FROM") orelse soql.len;
        if (from_start > select_start) {
            const clause = std.mem.trim(u8, soql[select_start..from_start], " \t\n\r");
            const object_denied = !self.resolve_object_read_access_by_name(from_type_name);
            var field_iter = std.mem.splitScalar(u8, clause, ',');
            while (field_iter.next()) |raw_field| {
                const trimmed = std.mem.trim(u8, raw_field, " \t\n\r");
                if (trimmed.len == 0) continue;
                // Skip subqueries and function expressions (COUNT(), etc.) — they
                // don't correspond to a single column name the caller would check.
                if (trimmed[0] == '(' or std.mem.indexOfScalar(u8, trimmed, '(') != null) continue;
                // Skip dotted relationship fields — only surface root-level names.
                if (std.mem.indexOfScalar(u8, trimmed, '.') != null) continue;
                const include = object_denied or
                    !self.resolve_field_read_access_by_name(from_type_name, trimmed);
                if (!include) continue;
                const key = try self.arena.dupe(u8, trimmed);
                try field_set.entries.put(self.arena, key, Value{ .string = key });
            }
        }

        if (field_set.entries.count() > 0) {
            const sobj_key = try self.arena.dupe(u8, from_type_name);
            try inaccessible_map.entries.put(self.arena, sobj_key, Value{ .set = field_set });
        }
        try exc.fields.put(self.arena, "inaccessibleFields", Value{ .map = inaccessible_map });
    }

    fn resolve_object_read_access_by_name(self: *Evaluator, obj_name: []const u8) bool {
        if (!self.is_restricted_user) return true;
        return builtins.resolve_object_crud_permission_public(self, obj_name, "read");
    }

    fn resolve_field_read_access_by_name(
        self: *Evaluator,
        obj_name: []const u8,
        field_name: []const u8,
    ) bool {
        if (!self.is_restricted_user) return true;
        return builtins.resolve_field_read_permission_public(self, obj_name, field_name);
    }

    // -----------------------------------------------------------------------
    // SOQL 実行
    // -----------------------------------------------------------------------

    pub fn execute_soql(self: *Evaluator, raw: []const u8, current_env: *Env) !Value {
        self.limits_soql += 1;
        var soql = try self.normalize_soql_query(raw);
        try self.enforce_restricted_soql_access(soql);
        if (soql.len > 4 and std.ascii.eqlIgnoreCase(soql[0..4], "FIND")) {
            return self.execute_sosl(soql);
        }

        const all_rows_info = strip_all_rows_clause(soql);
        soql = all_rows_info.soql;
        const include_all_rows = all_rows_info.include_all_rows;
        if (try self.execute_soql_early_result(soql, current_env, include_all_rows)) |result| {
            return result;
        }

        const from_type = extract_from_type(soql) orelse return self.make_empty_list();
        var records: std.ArrayListUnmanaged(Value) = .empty;
        try self.collect_soql_records(from_type, soql, current_env, include_all_rows, &records);
        try self.ensure_selected_soql_fields(soql, &records);
        try self.seed_empty_soql_records(from_type, soql, current_env, &records);
        try self.ensure_known_soql_type(from_type, soql, current_env, records.items.len != 0);
        try self.finalize_soql_records(from_type, soql, current_env, &records);
        const list = try self.arena.create(types.ListValue);
        list.* = .{ .items = records };
        return Value{ .list = list };
    }

    fn normalize_soql_query(self: *Evaluator, raw: []const u8) ![]const u8 {
        var soql = raw;
        if (soql.len > 2 and soql[0] == '[') soql = soql[1 .. soql.len - 1];
        return std.mem.trim(u8, try self.strip_soql_line_comments(soql), " \t\n\r");
    }

    fn enforce_restricted_soql_access(self: *Evaluator, soql: []const u8) !void {
        if (!self.is_restricted_user) return;
        if (std.ascii.indexOfIgnoreCase(soql, "WITH SECURITY_ENFORCED") == null and
            std.ascii.indexOfIgnoreCase(soql, "WITH USER_MODE") == null and
            std.ascii.indexOfIgnoreCase(soql, "USER_MODE") == null)
        {
            return;
        }
        const from_type_name = extract_from_type(soql) orelse "SObject";
        const msg = try std.fmt.allocPrint(
            self.arena,
            unsupported_soql_type_message,
            .{from_type_name},
        );
        const exc = try self.arena.create(types.ObjectInstance);
        exc.* = .{ .class_name = "System.QueryException" };
        try exc.fields.put(self.arena, "message", Value{ .string = msg });
        try self.attach_inaccessible_fields_to_exception(exc, soql, from_type_name);
        self.pending_exception = Value{ .object = exc };
        return error.ApexException;
    }

    fn strip_all_rows_clause(soql: []const u8) struct { soql: []const u8, include_all_rows: bool } {
        if (soql.len > 8 and std.ascii.eqlIgnoreCase(soql[soql.len - 8 ..], "ALL ROWS")) {
            return .{
                .soql = std.mem.trim(u8, soql[0 .. soql.len - 8], " \t\n\r"),
                .include_all_rows = true,
            };
        }
        return .{ .soql = soql, .include_all_rows = false };
    }

    fn execute_soql_early_result(
        self: *Evaluator,
        soql: []const u8,
        current_env: *Env,
        include_all_rows: bool,
    ) !?Value {
        if (std.ascii.indexOfIgnoreCase(soql, "count()") != null) {
            return try self.execute_soql_count_query(soql, current_env, include_all_rows);
        }
        if (std.ascii.indexOfIgnoreCase(soql, "SUM(") orelse
            std.ascii.indexOfIgnoreCase(soql, "AVG(") orelse
            std.ascii.indexOfIgnoreCase(soql, "MIN(") orelse
            std.ascii.indexOfIgnoreCase(soql, "MAX(") orelse
            std.ascii.indexOfIgnoreCase(soql, "COUNT(")) |_|
        {
            if (std.ascii.indexOfIgnoreCase(soql, "count()") == null or
                std.ascii.indexOfIgnoreCase(soql, "group by") != null)
            {
                return try self.execute_aggregate_query(soql, current_env, include_all_rows);
            }
        }
        if (std.ascii.indexOfIgnoreCase(soql, "group by") != null) {
            return try self.execute_aggregate_query(soql, current_env, include_all_rows);
        }
        return null;
    }

    fn execute_soql_count_query(
        self: *Evaluator,
        soql: []const u8,
        current_env: *Env,
        include_all_rows: bool,
    ) !Value {
        const from_type = extract_from_type(soql) orelse return Value{ .integer = 0 };
        var count: i64 = 0;
        var store_iter = self.store.iterator();
        while (store_iter.next()) |entry| {
            if (std.ascii.eqlIgnoreCase(entry.key_ptr.*, from_type)) {
                count += self.count_matching_query_records(
                    entry.value_ptr.items,
                    soql,
                    current_env,
                );
                break;
            }
        }
        if (include_all_rows) {
            var trash_iter = self.trash.iterator();
            while (trash_iter.next()) |entry| {
                if (std.ascii.eqlIgnoreCase(entry.key_ptr.*, from_type)) {
                    count += self.count_matching_query_records(
                        entry.value_ptr.items,
                        soql,
                        current_env,
                    );
                    break;
                }
            }
        }
        return Value{ .integer = count };
    }

    fn count_matching_query_records(
        self: *Evaluator,
        source_records: []const Value,
        soql: []const u8,
        current_env: *Env,
    ) i64 {
        var count: i64 = 0;
        for (source_records) |record| {
            if (self.matches_where(record, soql, current_env)) count += 1;
        }
        return count;
    }

    fn collect_soql_records(
        self: *Evaluator,
        from_type: []const u8,
        soql: []const u8,
        current_env: *Env,
        include_all_rows: bool,
        records: *std.ArrayListUnmanaged(Value),
    ) !void {
        try self.append_matching_store_records_for_query(
            from_type,
            soql,
            current_env,
            include_all_rows,
            records,
        );
        if (records.items.len == 0 and std.ascii.eqlIgnoreCase(from_type, "UserRecordAccess")) {
            try self.seed_user_record_access_records(soql, current_env, records);
        }
        try self.seed_named_query_records_if_needed(from_type, soql, current_env, records);
        try self.load_query_custom_metadata_records(
            from_type,
            soql,
            current_env,
            include_all_rows,
            records,
        );
        if (include_all_rows) {
            try self.append_matching_trash_records_for_query(from_type, soql, current_env, records);
        }
    }

    fn append_matching_store_records_for_query(
        self: *Evaluator,
        from_type: []const u8,
        soql: []const u8,
        current_env: *Env,
        include_all_rows: bool,
        records: *std.ArrayListUnmanaged(Value),
    ) !void {
        var store_iter = self.store.iterator();
        while (store_iter.next()) |entry| {
            if (std.ascii.eqlIgnoreCase(entry.key_ptr.*, from_type)) {
                try self.append_matching_query_records(
                    entry.value_ptr.items,
                    soql,
                    current_env,
                    if (include_all_rows) false else null,
                    records,
                );
                break;
            }
        }
    }

    fn append_matching_query_records(
        self: *Evaluator,
        source_records: []const Value,
        soql: []const u8,
        current_env: *Env,
        is_deleted: ?bool,
        records: *std.ArrayListUnmanaged(Value),
    ) !void {
        for (source_records) |record| {
            if (!self.matches_where(record, soql, current_env)) continue;
            if (record == .sobject) {
                const copy = try self.clone_s_object(record.sobject);
                if (is_deleted) |deleted| {
                    try utils.sobject_put(
                        &copy.fields,
                        self.arena,
                        "IsDeleted",
                        Value{ .boolean = deleted },
                    );
                }
                try records.append(self.arena, Value{ .sobject = copy });
            } else {
                try records.append(self.arena, record);
            }
        }
    }

    fn seed_named_query_records_if_needed(
        self: *Evaluator,
        from_type: []const u8,
        soql: []const u8,
        current_env: *Env,
        records: *std.ArrayListUnmanaged(Value),
    ) !void {
        if (records.items.len != 0) return;
        if (!std.ascii.eqlIgnoreCase(from_type, "PermissionSet") and
            !std.ascii.eqlIgnoreCase(from_type, "PermissionSetLicense"))
        {
            return;
        }
        const where_clause = extract_where_clause(soql) orelse return;
        if (std.ascii.indexOfIgnoreCase(where_clause, " IN :") == null and
            std.ascii.indexOfIgnoreCase(where_clause, " IN (") == null)
        {
            return;
        }
        try self.seed_named_records(from_type, soql, current_env, records);
    }

    fn load_query_custom_metadata_records(
        self: *Evaluator,
        from_type: []const u8,
        soql: []const u8,
        current_env: *Env,
        include_all_rows: bool,
        records: *std.ArrayListUnmanaged(Value),
    ) !void {
        if (records.items.len != 0 or
            !std.mem.endsWith(u8, from_type, "__mdt") or
            self.store.get(from_type) != null)
        {
            return;
        }
        const has_hardcoded_stub =
            (try self.generate_metadata_stub(from_type, soql, current_env)) != null;
        if (has_hardcoded_stub) return;
        try self.load_custom_metadata_from_files(from_type);
        var mdt_iter = self.store.iterator();
        while (mdt_iter.next()) |entry| {
            if (std.ascii.eqlIgnoreCase(entry.key_ptr.*, from_type)) {
                try self.append_matching_query_records(
                    entry.value_ptr.items,
                    soql,
                    current_env,
                    if (include_all_rows) false else null,
                    records,
                );
                break;
            }
        }
    }

    fn append_matching_trash_records_for_query(
        self: *Evaluator,
        from_type: []const u8,
        soql: []const u8,
        current_env: *Env,
        records: *std.ArrayListUnmanaged(Value),
    ) !void {
        var trash_iter = self.trash.iterator();
        while (trash_iter.next()) |entry| {
            if (std.ascii.eqlIgnoreCase(entry.key_ptr.*, from_type)) {
                try self.append_matching_query_records(
                    entry.value_ptr.items,
                    soql,
                    current_env,
                    true,
                    records,
                );
                break;
            }
        }
    }

    fn ensure_selected_soql_fields(
        self: *Evaluator,
        soql: []const u8,
        records: *std.ArrayListUnmanaged(Value),
    ) !void {
        const select_start = if (std.ascii.indexOfIgnoreCase(soql, "SELECT")) |si| si + 6 else 0;
        const from_start = std.ascii.indexOfIgnoreCase(soql, "FROM") orelse soql.len;
        if (from_start <= select_start) return;
        const select_clause = std.mem.trim(u8, soql[select_start..from_start], " \t\n\r");
        if (std.ascii.indexOfIgnoreCase(select_clause, "FIELDS(") != null or
            std.ascii.indexOfIgnoreCase(select_clause, "COUNT(") != null or
            std.ascii.indexOfIgnoreCase(select_clause, "SUM(") != null)
        {
            return;
        }
        var field_iter = std.mem.splitScalar(u8, select_clause, ',');
        while (field_iter.next()) |raw_field| {
            var field_name = std.mem.trim(u8, raw_field, " \t\n\r");
            if (field_name.len == 0 or field_name[0] == '(') continue;
            var is_to_label = false;
            if (std.ascii.startsWithIgnoreCase(field_name, "toLabel(") and
                std.mem.endsWith(u8, field_name, ")"))
            {
                field_name = field_name[8 .. field_name.len - 1];
                is_to_label = true;
            }
            if (std.mem.indexOfScalar(u8, field_name, '.') != null) continue;
            try self.ensure_selected_field_on_records(records, field_name, is_to_label);
        }
    }

    fn ensure_selected_field_on_records(
        self: *Evaluator,
        records: *std.ArrayListUnmanaged(Value),
        field_name: []const u8,
        is_to_label: bool,
    ) !void {
        for (records.items) |item| {
            if (item != .sobject) continue;
            const selected_value =
                self.get_s_object_field_value_case_insensitive(item.sobject, field_name) orelse
                Value.null_val;
            try utils.sobject_put(&item.sobject.fields, self.arena, field_name, selected_value);
            if (!is_to_label) continue;
            if (utils.sobject_get(&item.sobject.fields, field_name)) |fv| {
                if (fv == .string) {
                    if (self.resolve_picklist_label(
                        item.sobject.type_name,
                        field_name,
                        fv.string,
                    )) |label| {
                        try utils.sobject_put(
                            &item.sobject.fields,
                            self.arena,
                            field_name,
                            Value{ .string = label },
                        );
                    }
                }
            }
        }
    }

    fn seed_empty_soql_records(
        self: *Evaluator,
        from_type: []const u8,
        soql: []const u8,
        current_env: *Env,
        records: *std.ArrayListUnmanaged(Value),
    ) !void {
        try self.seed_metadata_query_records(from_type, soql, current_env, records);
        try self.seed_builtin_identity_query_records(from_type, soql, current_env, records);
        try self.seed_builtin_user_profile_query_records(from_type, soql, current_env, records);
        try self.seed_business_hours_query_record(from_type, soql, current_env, records);
    }

    fn seed_metadata_query_records(
        self: *Evaluator,
        from_type: []const u8,
        soql: []const u8,
        current_env: *Env,
        records: *std.ArrayListUnmanaged(Value),
    ) !void {
        if (records.items.len != 0) return;
        if (try self.seed_profile_permission_set_assignment_query(
            from_type,
            soql,
            current_env,
            records,
        )) {
            return;
        }
        if (try self.seed_field_permissions_query_records(from_type, soql, current_env, records)) {
            return;
        }
        if (try self.seed_metadata_in_clause_query_records(from_type, soql, current_env, records)) {
            return;
        }
        if (try self.seed_apex_class_or_query_records(from_type, soql, current_env, records)) {
            return;
        }
        if (try self.generate_metadata_stub(from_type, soql, current_env)) |stub_record| {
            try records.append(self.arena, stub_record);
        }
    }

    fn seed_profile_permission_set_assignment_query(
        self: *Evaluator,
        from_type: []const u8,
        soql: []const u8,
        current_env: *Env,
        records: *std.ArrayListUnmanaged(Value),
    ) !bool {
        if (!std.ascii.eqlIgnoreCase(from_type, "PermissionSetAssignment")) return false;

        var emitted_any = false;
        if (self.current_profile_name()) |profile_name| {
            if (self.is_system_admin_profile_name(profile_name)) {
                emitted_any = try self.append_profile_permission_set_assignment(
                    self.current_user_id,
                    self.current_profile_id,
                    soql,
                    current_env,
                    records,
                ) or emitted_any;
            }
        }

        if (self.store.get("User")) |users| {
            for (users.items) |user_val| {
                if (user_val != .sobject or user_val.sobject.id == null) continue;
                const profile_name = self.get_user_profile_name(user_val.sobject) orelse continue;
                if (!self.is_system_admin_profile_name(profile_name)) continue;
                const profile_id = self.user_profile_id(user_val.sobject) orelse continue;
                emitted_any = try self.append_profile_permission_set_assignment(
                    user_val.sobject.id.?,
                    profile_id,
                    soql,
                    current_env,
                    records,
                ) or emitted_any;
            }
        }

        return emitted_any;
    }

    fn append_profile_permission_set_assignment(
        self: *Evaluator,
        user_id: []const u8,
        profile_id: []const u8,
        soql: []const u8,
        current_env: *Env,
        records: *std.ArrayListUnmanaged(Value),
    ) !bool {
        const permission_set_id = try self.ensure_profile_permission_set(profile_id);
        const psa = try self.arena.create(types.SObject);
        psa.* = .{ .type_name = "PermissionSetAssignment" };
        const psa_id = try std.fmt.allocPrint(self.arena, "0Pa{d:0>15}", .{self.next_id});
        self.next_id += 1;
        psa.id = psa_id;
        try psa.fields.put(self.arena, "Id", Value{ .string = psa_id });
        try psa.fields.put(self.arena, "AssigneeId", Value{ .string = user_id });
        try psa.fields.put(self.arena, "PermissionSetId", Value{ .string = permission_set_id });

        const value = Value{ .sobject = psa };
        if (!self.matches_where(value, soql, current_env)) return false;
        try records.append(self.arena, value);
        return true;
    }

    fn ensure_profile_permission_set(self: *Evaluator, profile_id: []const u8) ![]const u8 {
        if (self.store.get("PermissionSet")) |permission_sets| {
            for (permission_sets.items) |item| {
                if (item != .sobject or item.sobject.id == null) continue;
                const stored_profile =
                    utils.sobject_get(&item.sobject.fields, "ProfileId") orelse continue;
                if (stored_profile == .string and
                    std.ascii.eqlIgnoreCase(stored_profile.string, profile_id))
                {
                    return item.sobject.id.?;
                }
            }
        }

        const ps = try self.arena.create(types.SObject);
        ps.* = .{ .type_name = "PermissionSet" };
        const ps_id = try std.fmt.allocPrint(self.arena, "0PS{d:0>15}", .{self.next_id});
        self.next_id += 1;
        ps.id = ps_id;
        try ps.fields.put(self.arena, "Id", Value{ .string = ps_id });
        try ps.fields.put(self.arena, "Name", Value{ .string = "System_Administrator_Profile" });
        try ps.fields.put(self.arena, "Label", Value{ .string = "System Administrator Profile" });
        try ps.fields.put(self.arena, "ProfileId", Value{ .string = profile_id });
        try ps.fields.put(self.arena, "PermissionsCustomizeApplication", Value{ .boolean = true });
        try ps.fields.put(self.arena, "PermissionsModifyAllData", Value{ .boolean = true });
        try ps.fields.put(self.arena, "PermissionsAuthorApex", Value{ .boolean = true });
        try self.append_store_record("PermissionSet", ps);
        return ps_id;
    }

    fn seed_field_permissions_query_records(
        self: *Evaluator,
        from_type: []const u8,
        soql: []const u8,
        current_env: *Env,
        records: *std.ArrayListUnmanaged(Value),
    ) !bool {
        if (!std.ascii.eqlIgnoreCase(from_type, "FieldPermissions")) return false;
        const obj_type =
            self.extract_where_field_value(soql, "SobjectType", current_env) orelse "Account";
        const fields = [_]struct { name: []const u8, read: bool, edit: bool }{
            .{ .name = "Name", .read = true, .edit = true },
            .{ .name = "Id", .read = true, .edit = false },
            .{ .name = "Description", .read = true, .edit = true },
            .{ .name = "Website", .read = true, .edit = true },
            .{ .name = "Industry", .read = true, .edit = true },
            .{ .name = "Phone", .read = true, .edit = true },
            .{ .name = "ShippingStreet", .read = true, .edit = true },
            .{ .name = "BillingStreet", .read = true, .edit = true },
        };
        for (fields) |f| {
            const fp = try self.arena.create(types.SObject);
            fp.* = .{ .type_name = "FieldPermissions" };
            const fp_id = try self.alloc_id();
            fp.id = fp_id;
            try fp.fields.put(self.arena, "Id", Value{ .string = fp_id });
            try fp.fields.put(
                self.arena,
                "Field",
                Value{
                    .string = try std.fmt.allocPrint(
                        self.arena,
                        "{s}.{s}",
                        .{ obj_type, f.name },
                    ),
                },
            );
            try fp.fields.put(self.arena, "PermissionsRead", Value{ .boolean = f.read });
            try fp.fields.put(self.arena, "PermissionsEdit", Value{ .boolean = f.edit });
            try fp.fields.put(self.arena, "SobjectType", Value{ .string = obj_type });
            try records.append(self.arena, Value{ .sobject = fp });
        }
        return true;
    }

    fn seed_metadata_in_clause_query_records(
        self: *Evaluator,
        from_type: []const u8,
        soql: []const u8,
        current_env: *Env,
        records: *std.ArrayListUnmanaged(Value),
    ) !bool {
        if ((!std.ascii.eqlIgnoreCase(from_type, "StaticResource") and
            !std.ascii.eqlIgnoreCase(from_type, "ApexClass")) or
            std.ascii.indexOfIgnoreCase(soql, " IN (") == null)
        {
            return false;
        }
        const where_clause = extract_where_clause(soql) orelse return false;
        const in_pos = std.ascii.indexOfIgnoreCase(where_clause, " IN ") orelse return false;
        var pp = in_pos + 4;
        while (pp < where_clause.len and where_clause[pp] != '(') pp += 1;
        if (pp >= where_clause.len) return false;
        pp += 1;
        while (pp < where_clause.len and where_clause[pp] != ')') {
            while (pp < where_clause.len and
                where_clause[pp] != '\'' and
                where_clause[pp] != ')') : (pp += 1)
            {}
            if (pp < where_clause.len and where_clause[pp] == '\'') {
                pp += 1;
                const start = pp;
                while (pp < where_clause.len and where_clause[pp] != '\'') pp += 1;
                if (pp > start) {
                    const in_name = where_clause[start..pp];
                    const tmp_soql = try std.fmt.allocPrint(
                        self.arena,
                        "SELECT Id, Name FROM {s} WHERE Name = '{s}'",
                        .{ from_type, in_name },
                    );
                    if (try self.generate_metadata_stub(from_type, tmp_soql, current_env)) |stub| {
                        try records.append(self.arena, stub);
                    }
                }
                if (pp < where_clause.len) pp += 1;
            }
        }
        return true;
    }

    fn seed_apex_class_or_query_records(
        self: *Evaluator,
        from_type: []const u8,
        soql: []const u8,
        current_env: *Env,
        records: *std.ArrayListUnmanaged(Value),
    ) !bool {
        if (!std.ascii.eqlIgnoreCase(from_type, "ApexClass") or
            std.ascii.indexOfIgnoreCase(soql, " OR ") == null)
        {
            return false;
        }
        const where_clause = extract_where_clause(soql) orelse return false;
        var wpos: usize = 0;
        while (wpos < where_clause.len) {
            const name_pos =
                std.ascii.indexOfIgnoreCasePos(where_clause, wpos, "Name") orelse break;
            var j = name_pos + 4;
            while (j < where_clause.len and
                (where_clause[j] == ' ' or where_clause[j] == '\t')) : (j += 1)
            {}
            if (j + 4 <= where_clause.len and
                std.ascii.eqlIgnoreCase(where_clause[j .. j + 4], "LIKE"))
            {
                j += 4;
            } else if (j < where_clause.len and where_clause[j] == '=') {
                j += 1;
            } else {
                wpos = j;
                continue;
            }
            while (j < where_clause.len and
                (where_clause[j] == ' ' or where_clause[j] == '\t')) : (j += 1)
            {}
            const name_val =
                self.extract_apex_class_query_name(where_clause, current_env, &wpos, j);
            if (name_val) |nv| {
                const tmp_soql = try std.fmt.allocPrint(
                    self.arena,
                    "SELECT Name, Body FROM {s} WHERE Name = '{s}'",
                    .{ from_type, nv },
                );
                if (try self.generate_metadata_stub(from_type, tmp_soql, current_env)) |stub| {
                    try records.append(self.arena, stub);
                }
            }
        }
        return true;
    }

    fn extract_apex_class_query_name(
        _: *Evaluator,
        where_clause: []const u8,
        current_env: *Env,
        wpos: *usize,
        start_pos: usize,
    ) ?[]const u8 {
        const j = start_pos;
        if (j < where_clause.len and where_clause[j] == '\'') {
            const start = j + 1;
            if (std.mem.indexOfPos(u8, where_clause, start, "'")) |end| {
                wpos.* = end + 1;
                return where_clause[start..end];
            }
            wpos.* = j + 1;
            return null;
        }
        if (j < where_clause.len and where_clause[j] == ':') {
            const start = j + 1;
            var end = start;
            while (end < where_clause.len and
                (std.ascii.isAlphanumeric(where_clause[end]) or where_clause[end] == '_'))
            {
                end += 1;
            }
            wpos.* = end;
            if (end > start) {
                if (current_env.get(where_clause[start..end])) |bv| {
                    if (bv == .string) return bv.string;
                }
            }
            return null;
        }
        wpos.* = j + 1;
        return null;
    }

    fn seed_builtin_identity_query_records(
        self: *Evaluator,
        from_type: []const u8,
        soql: []const u8,
        current_env: *Env,
        records: *std.ArrayListUnmanaged(Value),
    ) !void {
        if (records.items.len != 0 or self.store.get(from_type) != null) return;
        if (std.ascii.eqlIgnoreCase(from_type, "User")) {
            const use_query_specific_user =
                self.has_exact_where_field_comparison(soql, "Profile.Name") or
                self.has_exact_where_field_comparison(soql, "Profile.UserType") or
                self.has_exact_where_field_comparison(soql, "UserType");
            const user_record = if (self.query_matches_current_user(soql, current_env))
                try self.create_current_user_record()
            else if (self.query_matches_default_synthetic_user(soql, current_env))
                try self.create_default_user_record()
            else if (use_query_specific_user)
                try self.create_user_for_query(soql, current_env)
            else
                try self.create_current_user_record();
            try self.append_seeded_store_record("User", user_record, soql, current_env, records);
            return;
        }
        if (std.ascii.eqlIgnoreCase(from_type, "Profile")) {
            const profile_record = if (!self.has_where_field_like_comparison(soql, "Name"))
                try self.create_profile_for_query(soql, current_env)
            else
                try self.create_default_profile_record();
            try self.append_seeded_store_record(
                "Profile",
                profile_record,
                soql,
                current_env,
                records,
            );
            return;
        }
        if (std.ascii.eqlIgnoreCase(from_type, "RecordType")) {
            try self.seed_record_type_store();
            try self.append_matching_store_records("RecordType", soql, current_env, records);
            return;
        }
        if (std.ascii.eqlIgnoreCase(from_type, "OpportunityStage")) {
            try self.seed_opportunity_stage_store();
            try self.append_matching_store_records("OpportunityStage", soql, current_env, records);
        }
    }

    fn append_matching_store_records(
        self: *Evaluator,
        store_type: []const u8,
        soql: []const u8,
        current_env: *Env,
        records: *std.ArrayListUnmanaged(Value),
    ) !void {
        const store_records = self.store.get(store_type) orelse return;
        for (store_records.items) |record| {
            if (self.matches_where(record, soql, current_env) and record == .sobject) {
                const copy = try self.clone_s_object(record.sobject);
                try records.append(self.arena, Value{ .sobject = copy });
            }
        }
    }

    fn seed_opportunity_stage_store(self: *Evaluator) !void {
        const gop = try self.store.getOrPut(self.arena, "OpportunityStage");
        if (!gop.found_existing) gop.value_ptr.* = .empty;
        if (gop.value_ptr.items.len > 0) return;

        const stages = [_]struct {
            name: []const u8,
            sort_order: i64,
            probability: i64,
            is_closed: bool,
            is_won: bool,
            forecast: []const u8,
        }{
            .{
                .name = "Prospecting",
                .sort_order = 1,
                .probability = 10,
                .is_closed = false,
                .is_won = false,
                .forecast = "Pipeline",
            },
            .{
                .name = "Pledged",
                .sort_order = 2,
                .probability = 50,
                .is_closed = false,
                .is_won = false,
                .forecast = "Pipeline",
            },
            .{
                .name = "Closed Won",
                .sort_order = 3,
                .probability = 100,
                .is_closed = true,
                .is_won = true,
                .forecast = "Closed",
            },
            .{
                .name = "Closed Lost",
                .sort_order = 4,
                .probability = 0,
                .is_closed = true,
                .is_won = false,
                .forecast = "Omitted",
            },
        };

        for (stages) |stage| try self.append_opportunity_stage(gop.value_ptr, stage);
    }

    fn append_opportunity_stage(
        self: *Evaluator,
        records: *std.ArrayListUnmanaged(Value),
        stage: anytype,
    ) !void {
        const row = try self.arena.create(types.SObject);
        row.* = .{ .type_name = "OpportunityStage" };
        const id = try self.alloc_id_for_type("OpportunityStage");
        row.id = id;
        try row.fields.put(self.arena, "Id", Value{ .string = id });
        try row.fields.put(self.arena, "MasterLabel", Value{ .string = stage.name });
        try row.fields.put(self.arena, "ApiName", Value{ .string = stage.name });
        try row.fields.put(self.arena, "SortOrder", Value{ .integer = stage.sort_order });
        try row.fields.put(
            self.arena,
            "DefaultProbability",
            Value{ .integer = stage.probability },
        );
        try row.fields.put(self.arena, "IsActive", Value{ .boolean = true });
        try row.fields.put(self.arena, "IsClosed", Value{ .boolean = stage.is_closed });
        try row.fields.put(self.arena, "IsWon", Value{ .boolean = stage.is_won });
        try row.fields.put(self.arena, "ForecastCategory", Value{ .string = stage.forecast });
        try row.fields.put(
            self.arena,
            "ForecastCategoryName",
            Value{ .string = stage.forecast },
        );
        try records.append(self.arena, Value{ .sobject = row });
    }

    fn append_seeded_store_record(
        self: *Evaluator,
        store_type: []const u8,
        record: Value,
        soql: []const u8,
        current_env: *Env,
        records: *std.ArrayListUnmanaged(Value),
    ) !void {
        if (record == .null_val or !self.matches_where(record, soql, current_env)) return;
        try records.append(self.arena, record);
        if (record == .sobject) {
            const gop = try self.store.getOrPut(self.arena, store_type);
            if (!gop.found_existing) gop.value_ptr.* = .empty;
            try gop.value_ptr.append(self.arena, record);
        }
    }

    fn seed_builtin_user_profile_query_records(
        self: *Evaluator,
        from_type: []const u8,
        soql: []const u8,
        current_env: *Env,
        records: *std.ArrayListUnmanaged(Value),
    ) !void {
        if (records.items.len == 0 and
            std.ascii.eqlIgnoreCase(from_type, "User") and
            self.should_synthesize_builtin_user(soql, current_env))
        {
            const user_record = if (self.query_matches_current_user(soql, current_env))
                try self.create_current_user_record()
            else if (self.has_exact_where_field_comparison(soql, "Alias") or
                self.has_exact_where_field_comparison(soql, "Username"))
                try self.create_user_for_query(soql, current_env)
            else
                try self.create_current_user_record();
            try self.append_seeded_store_record("User", user_record, soql, current_env, records);
        }
        if (records.items.len == 0 and std.ascii.eqlIgnoreCase(from_type, "Profile")) {
            const profile_record = if (!self.has_where_field_like_comparison(soql, "Name"))
                try self.create_profile_for_query(soql, current_env)
            else
                try self.create_default_profile_record();
            try self.append_seeded_store_record(
                "Profile",
                profile_record,
                soql,
                current_env,
                records,
            );
        }
    }

    fn seed_business_hours_query_record(
        self: *Evaluator,
        from_type: []const u8,
        soql: []const u8,
        current_env: *Env,
        records: *std.ArrayListUnmanaged(Value),
    ) !void {
        if (records.items.len != 0 or !std.ascii.eqlIgnoreCase(from_type, "BusinessHours")) return;
        const business_hours = try self.arena.create(types.SObject);
        business_hours.* = .{ .type_name = "BusinessHours", .id = "01m000000000001AAA" };
        try business_hours.fields.put(self.arena, "Id", Value{ .string = "01m000000000001AAA" });
        try business_hours.fields.put(self.arena, "Name", Value{ .string = "Default" });
        if (self.matches_where(Value{ .sobject = business_hours }, soql, current_env)) {
            try records.append(self.arena, Value{ .sobject = business_hours });
        }
    }

    const unsupported_soql_type_message =
        "sObject type '{s}' is not supported. " ++
        "If you are attempting to use a custom object, be sure to " ++
        "append the '__c' after the entity name.";

    fn ensure_known_soql_type(
        self: *Evaluator,
        from_type: []const u8,
        soql: []const u8,
        current_env: *Env,
        has_records: bool,
    ) !void {
        if (has_records or self.store.get(from_type) != null) return;
        if (try self.is_known_soql_type(from_type, soql, current_env)) return;
        const exc = try self.arena.create(types.ObjectInstance);
        exc.* = .{ .class_name = "System.QueryException" };
        try exc.fields.put(
            self.arena,
            "message",
            Value{
                .string = try std.fmt.allocPrint(
                    self.arena,
                    unsupported_soql_type_message,
                    .{from_type},
                ),
            },
        );
        self.pending_exception = Value{ .object = exc };
        return error.ApexException;
    }

