        const created_by_id = if (created_by == .sobject and created_by.sobject.id != null)
            created_by.sobject.id.?
        else
            self.current_user_id;
        const id = "00D000000000001";
        sob.id = id;
        try sob.fields.put(self.arena, "Id", Value{ .string = id });
