    fn scan_bind_expression_end(source: []const u8, start: usize) usize {
        var j = start;
        var paren_depth: usize = 0;
        var bracket_depth: usize = 0;
        while (j < source.len) : (j += 1) {
            const ch = source[j];
            if (std.ascii.isAlphanumeric(ch) or ch == '_' or ch == '.') continue;
            if (ch == '(') {
                paren_depth += 1;
                continue;
            }
            if (ch == '[') {
                bracket_depth += 1;
                continue;
            }
            if (ch == ')') {
                if (paren_depth == 0 and bracket_depth == 0) break;
                paren_depth -|= 1;
                continue;
            }
            if (ch == ']') {
                if (paren_depth == 0 and bracket_depth == 0) break;
                bracket_depth -|= 1;
                continue;
            }
            break;
        }
        return j;
    }

    fn lookup_evaluated_bind_expression(
        self: *Evaluator,
        current_env: *Env,
        bind_expr: []const u8,
    ) ?Value {
        const tokens = lexer_mod.tokenize(bind_expr, self.arena) catch return null;
        const expr = parser_mod.parseExpr(tokens, self.arena) catch return null;
        const saved_pending = self.pending_exception;
        return self.eval_expr(expr, current_env) catch {
            self.pending_exception = saved_pending;
            return null;
        };
    }

    fn lookup_bind_value(self: *Evaluator, current_env: *Env, var_name: []const u8) ?Value {
        if (current_env.get(var_name)) |bv| {
            if (bv != .null_val) return bv;
        }
        if (self.lookup_evaluated_bind_expression(current_env, var_name)) |bv| return bv;

        if (self.current_class) |cc| {
            self.ensure_static_init(cc);
            const key = std.fmt.allocPrint(self.arena, "{s}.{s}", .{ cc, var_name }) catch null;
            if (key) |k| {
                if (self.global_env.get(k)) |bv| return bv;
            }
            if (self.find_outer_class_name(cc)) |oc| {
                self.ensure_static_init(oc);
                const okey =
                    std.fmt.allocPrint(self.arena, "{s}.{s}", .{ oc, var_name }) catch null;
                if (okey) |k| {
                    if (self.global_env.get(k)) |bv| return bv;
                }
            }
        }

        if (current_env.get_this()) |tv| {
            if (tv == .object) {
                const this_cn = tv.object.class_name;
                self.ensure_static_init(this_cn);
                const tkey =
                    std.fmt.allocPrint(self.arena, "{s}.{s}", .{ this_cn, var_name }) catch null;
                if (tkey) |k| {
                    if (self.global_env.get(k)) |bv| return bv;
                }
                if (self.find_outer_class_name(this_cn)) |oc| {
                    self.ensure_static_init(oc);
                    const okey =
                        std.fmt.allocPrint(self.arena, "{s}.{s}", .{ oc, var_name }) catch null;
                    if (okey) |k| {
                        if (self.global_env.get(k)) |bv| return bv;
                    }
                }
            }
        }

        return null;
    }

    /// Extract the first value used in WHERE Name ... conditions.
    /// Supports =, LIKE, IN (:bind), and IN ('a', 'b') through the generic field extractor.
    fn extract_where_name_value(self: *Evaluator, soql: []const u8, current_env: *Env) ?[]const u8 {
        return self.extract_where_field_value(soql, "Name", current_env);
    }

    const WhereFieldOperator = struct {
        index: usize,
        is_in: bool,
    };

    /// Extract a specific field value from WHERE clause
    fn extract_where_field_value(
        self: *Evaluator,
        soql: []const u8,
        field_name: []const u8,
        current_env: *Env,
    ) ?[]const u8 {
        const where_clause = extract_where_clause(soql) orelse return null;
        var pos: usize = 0;
        while (pos + field_name.len <= where_clause.len) : (pos += 1) {
            if (!where_field_matches_at(where_clause, field_name, pos)) continue;
            const op = scan_where_field_operator(where_clause, pos + field_name.len);
            if (self.extract_where_value_after_operator(where_clause, op, current_env)) |value| {
                return value;
            }
        }
        return null;
    }

    fn where_field_matches_at(where_clause: []const u8, field_name: []const u8, pos: usize) bool {
        if (!std.ascii.eqlIgnoreCase(where_clause[pos .. pos + field_name.len], field_name)) {
            return false;
        }
        const has_left_boundary = pos == 0 or
            is_soql_whitespace(where_clause[pos - 1]) or
            where_clause[pos - 1] == '(';
        const field_end = pos + field_name.len;
        const has_right_boundary = field_end == where_clause.len or
            is_soql_whitespace(where_clause[field_end]) or
            where_clause[field_end] == ')';
        return has_left_boundary and has_right_boundary;
    }

    fn scan_where_field_operator(where_clause: []const u8, field_end: usize) WhereFieldOperator {
        var j = field_end;
        while (j < where_clause.len and is_soql_whitespace(where_clause[j])) j += 1;

        var is_in = false;
        if (j + 2 <= where_clause.len and std.ascii.eqlIgnoreCase(where_clause[j .. j + 2], "IN")) {
            is_in = true;
            j += 2;
        } else if (j + 4 <= where_clause.len and
            std.ascii.eqlIgnoreCase(where_clause[j .. j + 4], "LIKE"))
        {
            j += 4;
        } else if (j < where_clause.len and where_clause[j] == '=') {
            j += 1;
        } else {
            while (j < where_clause.len and where_clause[j] != '\'' and where_clause[j] != ':' and
                where_clause[j] != '(' and where_clause[j] != ' ')
            {
                j += 1;
            }
        }

        while (j < where_clause.len and is_soql_whitespace(where_clause[j])) j += 1;
        return .{ .index = j, .is_in = is_in };
    }

    fn extract_where_value_after_operator(
        self: *Evaluator,
        where_clause: []const u8,
        op: WhereFieldOperator,
        current_env: *Env,
    ) ?[]const u8 {
        var j = op.index;
        if (op.is_in and j < where_clause.len and where_clause[j] == '(') {
            return extract_where_in_list_first_value(where_clause, j + 1);
        }

        if (j < where_clause.len and where_clause[j] == '\'') {
            j += 1;
            const start = j;
            while (j < where_clause.len and where_clause[j] != '\'') j += 1;
            return where_clause[start..j];
        }

        if (extract_where_bare_literal(where_clause, j)) |raw| return raw;
        if (j < where_clause.len and where_clause[j] == ':') {
            j += 1;
            const start = j;
            j = scan_bind_expression_end(where_clause, j);
            return self.extract_where_bind_value(current_env, where_clause[start..j]);
        }
        return null;
    }

    fn extract_where_in_list_first_value(where_clause: []const u8, start_index: usize) ?[]const u8 {
        var j = start_index;
        while (j < where_clause.len and (where_clause[j] == ' ' or where_clause[j] == '\t')) j += 1;
        if (j < where_clause.len and where_clause[j] == '\'') {
            j += 1;
            const start = j;
            while (j < where_clause.len and where_clause[j] != '\'') j += 1;
            return where_clause[start..j];
        }
        const start = j;
        while (j < where_clause.len and where_clause[j] != ',' and where_clause[j] != ')' and
            where_clause[j] != ' ' and where_clause[j] != '\t')
        {
            j += 1;
        }
        if (j > start) return std.mem.trim(u8, where_clause[start..j], " \t\n\r'");
        return null;
    }

    fn extract_where_bare_literal(where_clause: []const u8, start_index: usize) ?[]const u8 {
        var j = start_index;
        if (j >= where_clause.len or
            where_clause[j] == '\'' or
            where_clause[j] == ':' or
            where_clause[j] == '(')
        {
            return null;
        }
        const start = j;
        while (j < where_clause.len) : (j += 1) {
            const ch = where_clause[j];
            if (ch == ' ' or ch == '\t' or ch == '\n' or
                ch == '\r' or ch == ')' or ch == ',') break;
        }
        if (j <= start) return null;
        const raw = std.mem.trim(u8, where_clause[start..j], " \t\n\r");
        return if (raw.len > 0) raw else null;
    }

    fn extract_where_bind_value(
        self: *Evaluator,
        current_env: *Env,
        var_name: []const u8,
    ) ?[]const u8 {
        const v = self.lookup_bind_value(current_env, var_name) orelse return null;
        switch (v) {
            .string => return v.string,
            .list => return self.extract_where_bind_list_value(v.list),
            .set => {
                var it = v.set.entries.iterator();
                if (it.next()) |entry| {
                    if (entry.value_ptr.* == .string) return entry.value_ptr.*.string;
                }
                return null;
            },
            .map => {
                var it = v.map.entries.iterator();
                if (it.next()) |entry| return entry.key_ptr.*;
                return null;
            },
            else => return (utils.coerce_to_string(v, self.arena) catch null),
        }
    }

    fn extract_where_bind_list_value(self: *Evaluator, list: *types.ListValue) ?[]const u8 {
        for (list.items.items) |item| {
            switch (item) {
                .string => return item.string,
                .sobject => {
                    if (item.sobject.id) |id| return id;
                },
                else => {
                    const coerced = utils.coerce_to_string(item, self.arena) catch continue;
                    return coerced;
                },
            }
        }
        return null;
    }

    fn has_where_field_null_literal(
        self: *Evaluator,
        soql_or_cond: []const u8,
        field_name: []const u8,
    ) bool {
        _ = self;
        const clause = extract_where_clause(soql_or_cond) orelse soql_or_cond;
        var pos: usize = 0;
        while (pos + field_name.len <= clause.len) : (pos += 1) {
            if (!std.ascii.eqlIgnoreCase(clause[pos .. pos + field_name.len], field_name)) continue;
            if (!(pos == 0 or
                is_soql_whitespace(clause[pos - 1]) or
                clause[pos - 1] == '(')) continue;
            var j = pos + field_name.len;
            while (j < clause.len and is_soql_whitespace(clause[j])) j += 1;
            if (j >= clause.len or clause[j] != '=') continue;
            j += 1;
            while (j < clause.len and is_soql_whitespace(clause[j])) j += 1;
            if (j + 4 <= clause.len and
                std.ascii.eqlIgnoreCase(clause[j .. j + 4], "NULL")) return true;
        }
        return false;
    }

    /// Allocate a unique fake Salesforce ID
    fn alloc_id(self: *Evaluator) ![]const u8 {
        const id = try std.fmt.allocPrint(self.arena, "{d:0>18}", .{self.next_id});
        self.next_id += 1;
        return id;
    }

    fn alloc_id_for_type(self: *Evaluator, type_name: []const u8) ![]const u8 {
        const key_prefix = sobject_key_prefix(type_name);
        const id = try std.fmt.allocPrint(
            self.arena,
            "{s}{d:0>15}",
            .{ &key_prefix, self.next_id },
        );
        self.next_id += 1;
        try self.id_type_map.put(self.arena, id, type_name);
        return id;
    }

    /// Load a StaticResource body from the file system.
    /// Searches source_paths for staticresources/<name>.json, .csv, .xml, or .resource.
    fn load_static_resource_body(self: *Evaluator, name: []const u8) ?[]const u8 {
        const extensions = [_][]const u8{ ".json", ".csv", ".xml", ".txt", ".resource", "" };
        for (self.source_paths) |sp| {
            // Try walking the directory tree to find staticresources/<name>.<ext>
            if (self.find_static_resource_in_dir(sp, name, &extensions)) |content| return content;
        }
        return null;
    }

    fn find_static_resource_in_dir(
        self: *Evaluator,
        base_path: []const u8,
        name: []const u8,
        extensions: []const []const u8,
    ) ?[]const u8 {
        var dir = std.Io.Dir.cwd().openDir(
            self.io,
            base_path,
            .{ .iterate = true },
        ) catch return null;
        defer dir.close(self.io);

        var walker = dir.walk(self.arena) catch return null;
        defer walker.deinit();

        while (walker.next(self.io) catch null) |entry| {
            if (entry.kind != .file) continue;
            // Check if the file is in a "staticresources" directory and matches name
            const path_str = entry.path;
            // Look for "/staticresources/<name>.<ext>" or "staticresources/<name>.<ext>"
            if (std.mem.indexOf(u8, path_str, "staticresources/")) |sr_pos| {
                const after_sr = path_str[sr_pos + "staticresources/".len ..];
                // Check if the filename matches <name>.<ext>
                for (extensions) |ext| {
                    const expected =
                        std.fmt.allocPrint(self.arena, "{s}{s}", .{ name, ext }) catch continue;
                    if (std.mem.eql(u8, after_sr, expected)) {
                        const full_path = std.fmt.allocPrint(
                            self.arena,
                            "{s}/{s}",
                            .{ base_path, path_str },
                        ) catch continue;
                        if (std.Io.Dir.cwd().readFileAlloc(
                            self.io,
                            full_path,
                            self.arena,
                            .limited(10 * 1024 * 1024),
                        )) |content| {
                            return content;
                        } else |_| {}
                    }
                }
            }
        }
        return null;
    }

    fn has_flow_definition(self: *Evaluator, flow_name: []const u8) bool {
        const suffix =
            std.fmt.allocPrint(self.arena, "{s}.flow-meta.xml", .{flow_name}) catch return false;
        for (self.source_paths) |base_path| {
            var dir = std.Io.Dir.cwd().openDir(
                self.io,
                base_path,
                .{ .iterate = true },
            ) catch continue;
            defer dir.close(self.io);

            var walker = dir.walk(self.arena) catch continue;
            defer walker.deinit();

            while (walker.next(self.io) catch null) |entry| {
                if (entry.kind != .file) continue;
                if (std.mem.endsWith(u8, entry.path, suffix)) return true;
            }
        }
        return false;
    }

    /// Load custom metadata records from .md-meta.xml files in source_paths.
    /// Parses files matching `customMetadata/<TypeName>.<RecordName>.md-meta.xml` and
    /// populates the store with SObject records containing the field values.
    fn load_custom_metadata_from_files(self: *Evaluator, mdt_type: []const u8) !void {
        const loaded_key = try ascii_lower_alloc(self.arena, mdt_type);
        const loaded_gop = try self.custom_metadata_loaded_types.getOrPut(self.arena, loaded_key);
        if (loaded_gop.found_existing) {
            self.arena.free(loaded_key);
            return;
        }

        if (self.custom_metadata_records.get(mdt_type)) |cached_records| {
            try self.clone_custom_metadata_records_into_store(mdt_type, cached_records.items);
            return;
        }
        if (self.custom_metadata_paths_indexed) return;

        try self.load_custom_metadata_from_source_paths(mdt_type);
    }

    fn load_custom_metadata_from_source_paths(self: *Evaluator, mdt_type: []const u8) !void {
        // Strip __mdt suffix to get the base type name for file matching
        const base_name = if (std.mem.endsWith(u8, mdt_type, "__mdt"))
            mdt_type[0 .. mdt_type.len - 5]
        else
            mdt_type;

        for (self.source_paths) |sp| {
            var dir = std.Io.Dir.cwd().openDir(self.io, sp, .{ .iterate = true }) catch continue;
            defer dir.close(self.io);

            var walker = dir.walk(self.arena) catch continue;
            defer walker.deinit();

            while (walker.next(self.io) catch null) |entry| {
                if (entry.kind != .file) continue;
                if (!std.mem.endsWith(u8, entry.path, ".md-meta.xml")) continue;
                // Check if filename matches: customMetadata/<BaseName>.<RecordName>.md-meta.xml
                if (std.mem.indexOf(u8, entry.path, "customMetadata/")) |cm_pos| {
                    const after_cm = entry.path[cm_pos + "customMetadata/".len ..];
                    // after_cm should be like "Customer_Fields.Contact_Config.md-meta.xml"
                    if (std.ascii.startsWithIgnoreCase(after_cm, base_name) and
                        after_cm.len > base_name.len and after_cm[base_name.len] == '.')
                    {
                        // Extract DeveloperName from filename: <BaseName>.<RecordName>.md-meta.xml
                        const after_dot =
                            after_cm[base_name.len + 1 ..]; // "RecordName.md-meta.xml"
                        const dev_name_raw = if (std.mem.indexOf(u8, after_dot, ".")) |next_dot|
                            after_dot[0..next_dot]
                        else
                            after_dot;
                        // Duplicate on arena since walker memory is temporary
                        const dev_name = self.arena.dupe(u8, dev_name_raw) catch continue;

                        const full_path = std.fmt.allocPrint(
                            self.arena,
                            "{s}/{s}",
                            .{ sp, entry.path },
                        ) catch continue;
                        const content = std.Io.Dir.cwd().readFileAlloc(
                            self.io,
                            full_path,
                            self.arena,
                            .limited(1024 * 1024),
                        ) catch continue;
                        if (try self.parse_custom_metadata_xml(mdt_type, content)) |sob| {
                            // Set DeveloperName from filename
                            try sob.fields.put(
                                self.arena,
                                "DeveloperName",
                                Value{ .string = dev_name },
                            );
                            const gop = try self.store.getOrPut(self.arena, mdt_type);
                            if (!gop.found_existing) gop.value_ptr.* = .empty;
                            try gop.value_ptr.append(self.arena, Value{ .sobject = sob });
                        }
                    }
                }
            }
        }
    }

    pub fn index_custom_metadata_from_path(self: *Evaluator, path: []const u8) !void {
        var dir = try std.Io.Dir.cwd().openDir(self.io, path, .{ .iterate = true });
        defer dir.close(self.io);

        var walker = try dir.walk(self.arena);
        defer walker.deinit();

        while (try walker.next(self.io)) |entry| {
            if (entry.kind != .file) continue;
            if (!std.mem.endsWith(u8, entry.path, ".md-meta.xml")) continue;
            const cm_pos = std.mem.indexOf(u8, entry.path, "customMetadata/") orelse continue;
            const after_cm = entry.path[cm_pos + "customMetadata/".len ..];
            const first_dot = std.mem.indexOfScalar(u8, after_cm, '.') orelse continue;
            const type_base = after_cm[0..first_dot];
            const after_dot = after_cm[first_dot + 1 ..];
            const dev_end = std.mem.indexOfScalar(u8, after_dot, '.') orelse after_dot.len;
            try self.index_custom_metadata_file(path, entry.path, type_base, after_dot[0..dev_end]);
        }
        self.custom_metadata_paths_indexed = true;
    }

    fn index_custom_metadata_file(
        self: *Evaluator,
        base_path: []const u8,
        entry_path: []const u8,
        type_base: []const u8,
        dev_name_raw: []const u8,
    ) !void {
        const full_path = try std.fmt.allocPrint(self.arena, "{s}/{s}", .{ base_path, entry_path });
        const file_key = try ascii_lower_alloc(self.arena, full_path);
        const indexed_gop = try self.custom_metadata_indexed_files.getOrPut(self.arena, file_key);
        if (indexed_gop.found_existing) {
            self.arena.free(file_key);
            return;
        }

        const mdt_type = if (std.mem.endsWith(u8, type_base, "__mdt"))
            try self.arena.dupe(u8, type_base)
        else
            try std.fmt.allocPrint(self.arena, "{s}__mdt", .{type_base});
        const content = try std.Io.Dir.cwd().readFileAlloc(
            self.io,
            full_path,
            self.arena,
            .limited(1024 * 1024),
        );
        const sob = (try self.parse_custom_metadata_xml(mdt_type, content)) orelse return;
        const dev_name = try self.arena.dupe(u8, dev_name_raw);
        try sob.fields.put(self.arena, "DeveloperName", Value{ .string = dev_name });

        const gop = try self.custom_metadata_records.getOrPut(self.arena, mdt_type);
        if (!gop.found_existing) gop.value_ptr.* = .empty;
        try gop.value_ptr.append(self.arena, Value{ .sobject = sob });
    }

    fn clone_custom_metadata_records_into_store(
        self: *Evaluator,
        mdt_type: []const u8,
        cached_records: []const Value,
    ) !void {
        const gop = try self.store.getOrPut(self.arena, mdt_type);
        if (!gop.found_existing) gop.value_ptr.* = .empty;
        for (cached_records) |record| {
            if (record != .sobject) continue;
            const copy = try self.clone_s_object(record.sobject);
            try gop.value_ptr.append(self.arena, Value{ .sobject = copy });
        }
    }

    /// Parse a single .md-meta.xml file and return an SObject with the field values.
    fn parse_custom_metadata_xml(
        self: *Evaluator,
        mdt_type: []const u8,
        xml: []const u8,
    ) !?*types.SObject {
        const sob = try self.arena.create(types.SObject);
        sob.* = .{ .type_name = mdt_type };
        const id = try self.alloc_id();
        sob.id = id;
        try sob.fields.put(self.arena, "Id", Value{ .string = id });

        // Simple XML parser: find <values><field>...</field><value ...>...</value></values> pairs
        var pos: usize = 0;
        while (pos < xml.len) {
            // Find <field>...</field>
            const field_start_tag = std.mem.indexOfPos(u8, xml, pos, "<field>") orelse break;
            const field_content_start = field_start_tag + "<field>".len;
            const field_end_tag =
                std.mem.indexOfPos(u8, xml, field_content_start, "</field>") orelse break;
            const field_name = std.mem.trim(u8, xml[field_content_start..field_end_tag], " \t\n\r");

            // Find corresponding <value ...>...</value>
            const value_search_start = field_end_tag + "</field>".len;
            const values_end =
                std.mem.indexOfPos(u8, xml, value_search_start, "</values>") orelse break;

            // Look for <value ...>content</value> within this <values> block
            // First check for xsi:nil="true" (self-closing tag: <value xsi:nil="true"/>)
            const val_region = xml[value_search_start..values_end];
            if (std.mem.indexOf(u8, val_region, "xsi:nil") != null) {
                // Field is explicitly null — skip it
                pos = values_end + "</values>".len;
                continue;
            }
            try self.apply_mdt_field_from_xml(sob, xml, value_search_start, values_end, field_name);

            pos = values_end + "</values>".len;
        }

        // Extract label
        if (std.mem.indexOf(u8, xml, "<label>")) |label_start| {
            const label_content = label_start + "<label>".len;
            if (std.mem.indexOfPos(u8, xml, label_content, "</label>")) |label_end| {
                const label_value = std.mem.trim(
                    u8,
                    xml[label_content..label_end],
                    " \t\n\r",
                );
                try sob.fields.put(self.arena, "Label", Value{ .string = label_value });
                try sob.fields.put(self.arena, "MasterLabel", Value{ .string = label_value });
            }
        }

        if (std.mem.endsWith(u8, mdt_type, "__mdt")) {
            try self.put_default_sobject_field(
                sob,
                "Is_Deleted__c",
                Value{ .boolean = false },
            );
        }

        return sob;
    }

    /// `parse_custom_metadata_xml` から抽出。`<values>` ブロック内の
    /// `<value xsi:type="xsd:xxx">...</value>` を `xsi:type` に応じて
    /// `Value{ .boolean / .double / .integer / .string }` として sob に
    /// 格納し、必要なら `__r` 関係 SObject も張る。
    fn apply_mdt_field_from_xml(
        self: *Evaluator,
        sob: *types.SObject,
        xml: []const u8,
        value_search_start: usize,
        values_end: usize,
        field_name: []const u8,
    ) !void {
        const val_tag_end = std.mem.indexOfPos(u8, xml, value_search_start, ">") orelse return;
        if (val_tag_end >= values_end) return;
        const val_content_start = val_tag_end + 1;
        const val_end = std.mem.indexOfPos(u8, xml, val_content_start, "</value>") orelse return;
        if (val_end > values_end) return;
        const field_value = std.mem.trim(u8, xml[val_content_start..val_end], " \t\n\r");
        const val_tag = xml[value_search_start..val_tag_end];
        const typed_value: Value = if (std.mem.indexOf(u8, val_tag, "xsd:boolean") != null)
            Value{ .boolean = std.ascii.eqlIgnoreCase(field_value, "true") }
        else if (std.mem.indexOf(u8, val_tag, "xsd:double") != null or
            std.mem.indexOf(u8, val_tag, "xsd:decimal") != null)
            if (std.fmt.parseFloat(f64, field_value)) |f|
                Value{ .double = f }
            else |_|
                Value{ .string = field_value }
        else if (std.mem.indexOf(u8, val_tag, "xsd:int") != null)
            if (std.fmt.parseInt(i64, field_value, 10)) |i|
                Value{ .integer = i }
            else |_|
                Value{ .string = field_value }
        else
            Value{ .string = field_value };
        try sob.fields.put(self.arena, field_name, typed_value);
        // Custom field (`__c`) → FieldDefinition `__r` relationship stub.
        if (std.mem.endsWith(u8, field_name, "__c") and field_name.len > 3) {
            const base = field_name[0 .. field_name.len - 3];
            const rel_name = try std.fmt.allocPrint(self.arena, "{s}__r", .{base});
            const fd = try self.arena.create(types.SObject);
            fd.* = .{ .type_name = "FieldDefinition" };
            try fd.fields.put(
                self.arena,
                "DeveloperName",
                Value{ .string = field_value },
            );
            try fd.fields.put(
                self.arena,
                "QualifiedAPIName",
                Value{ .string = field_value },
            );
            try self.apply_known_mdt_relationship_fields(fd, field_name, field_value);
            try sob.fields.put(self.arena, rel_name, Value{ .sobject = fd });
        }
    }

    fn apply_known_mdt_relationship_fields(
        self: *Evaluator,
        rel: *types.SObject,
        field_name: []const u8,
        field_value: []const u8,
    ) !void {
        if (!std.ascii.eqlIgnoreCase(field_name, "Target_Object_Mapping__c")) return;
        const object_api = npsp_data_import_target_object_api(field_value) orelse return;
        try rel.fields.put(self.arena, "Object_API_Name__c", Value{ .string = object_api });
        try rel.fields.put(
            self.arena,
            "Legacy_Data_Import_Object_Name__c",
            Value{ .string = field_value },
        );
    }

    fn npsp_data_import_target_object_api(mapping_name: []const u8) ?[]const u8 {
        const mappings = [_]struct { name: []const u8, object_api: []const u8 }{
            .{ .name = "Account1", .object_api = "Account" },
            .{ .name = "Account2", .object_api = "Account" },
            .{ .name = "Address", .object_api = "Address__c" },
            .{ .name = "Contact1", .object_api = "Contact" },
            .{ .name = "Contact2", .object_api = "Contact" },
            .{ .name = "Household", .object_api = "Account" },
            .{ .name = "Opportunity", .object_api = "Opportunity" },
            .{ .name = "Payment", .object_api = "npe01__OppPayment__c" },
            .{ .name = "Recurring_Donation", .object_api = "npe03__Recurring_Donation__c" },
            .{ .name = "GAU_Allocation_1", .object_api = "npsp__Allocation__c" },
            .{ .name = "GAU_Allocation_2", .object_api = "npsp__Allocation__c" },
            .{ .name = "Opportunity_Contact_Role_1", .object_api = "OpportunityContactRole" },
            .{ .name = "Opportunity_Contact_Role_2", .object_api = "OpportunityContactRole" },
        };
        for (mappings) |mapping| {
            if (std.ascii.eqlIgnoreCase(mapping_name, mapping.name)) return mapping.object_api;
        }
        return null;
    }

    fn xml_tag_value(self: *Evaluator, xml: []const u8, tag_name: []const u8) ?[]const u8 {
        const start_tag = std.fmt.allocPrint(self.arena, "<{s}>", .{tag_name}) catch return null;
        const end_tag = std.fmt.allocPrint(self.arena, "</{s}>", .{tag_name}) catch return null;
        const start = std.mem.indexOf(u8, xml, start_tag) orelse return null;
        const value_start = start + start_tag.len;
        const value_end = std.mem.indexOfPos(u8, xml, value_start, end_tag) orelse return null;
        return std.mem.trim(u8, xml[value_start..value_end], " \t\n\r");
    }

    fn xml_tag_bool_value(self: *Evaluator, xml: []const u8, tag_name: []const u8) ?bool {
        const raw = self.xml_tag_value(xml, tag_name) orelse return null;
        if (std.ascii.eqlIgnoreCase(raw, "true")) return true;
        if (std.ascii.eqlIgnoreCase(raw, "false")) return false;
        return null;
    }

    fn append_store_record(self: *Evaluator, type_name: []const u8, record: *types.SObject) !void {
        const gop = try self.store.getOrPut(self.arena, type_name);
        if (!gop.found_existing) gop.value_ptr.* = .empty;
        try gop.value_ptr.append(self.arena, Value{ .sobject = record });
    }

    fn find_permission_set_record_by_name(
        self: *Evaluator,
        permission_set_name: []const u8,
    ) ?Value {
        const permission_sets = self.store.get("PermissionSet") orelse return null;
        for (permission_sets.items) |item| {
            if (item != .sobject) continue;
            const name_val = utils.sobject_get(&item.sobject.fields, "Name") orelse continue;
            if (name_val != .string) continue;
            if (std.ascii.eqlIgnoreCase(name_val.string, permission_set_name)) return item;
        }
        return null;
    }

    fn composite_permission_field_components(field_name: []const u8) ?[]const []const u8 {
        if (std.ascii.eqlIgnoreCase(field_name, "BillingAddress")) {
            return &.{
                "BillingStreet",
                "BillingCity",
                "BillingState",
                "BillingPostalCode",
                "BillingCountry",
            };
        }
        if (std.ascii.eqlIgnoreCase(field_name, "ShippingAddress")) {
            return &.{
                "ShippingStreet",
                "ShippingCity",
                "ShippingState",
                "ShippingPostalCode",
                "ShippingCountry",
            };
        }
        if (std.ascii.eqlIgnoreCase(field_name, "MailingAddress")) {
            return &.{
                "MailingStreet",
                "MailingCity",
                "MailingState",
                "MailingPostalCode",
                "MailingCountry",
            };
        }
        if (std.ascii.eqlIgnoreCase(field_name, "OtherAddress")) {
            return &.{
                "OtherStreet",
                "OtherCity",
                "OtherState",
                "OtherPostalCode",
                "OtherCountry",
            };
        }
        return null;
    }

    fn append_expanded_permission_fields(
        self: *Evaluator,
        expanded: *std.ArrayListUnmanaged([]const u8),
        full_field_name: []const u8,
    ) !void {
        try expanded.append(self.arena, full_field_name);
        const dot = std.mem.lastIndexOfScalar(u8, full_field_name, '.') orelse return;
        const object_name = full_field_name[0..dot];
        const field_name = full_field_name[dot + 1 ..];
        const components = composite_permission_field_components(field_name) orelse return;
        for (components) |component_name| {
            try expanded.append(
                self.arena,
                try std.fmt.allocPrint(self.arena, "{s}.{s}", .{ object_name, component_name }),
            );
        }
    }

    fn load_permission_set_metadata_from_files(self: *Evaluator, requested_name: []const u8) !void {
        if (self.find_permission_set_record_by_name(requested_name) != null) return;

        for (self.source_paths) |sp| {
            var dir = std.Io.Dir.cwd().openDir(self.io, sp, .{ .iterate = true }) catch continue;
            defer dir.close(self.io);

            var walker = dir.walk(self.arena) catch continue;
            defer walker.deinit();

            while (walker.next(self.io) catch null) |entry| {
                if (entry.kind != .file) continue;
                if (std.mem.indexOf(u8, entry.path, "permissionsets/") == null) continue;
                if (!std.mem.endsWith(u8, entry.path, ".permissionset-meta.xml")) continue;

                const file_name = std.fs.path.basename(entry.path);
                const suffix = ".permissionset-meta.xml";
                if (file_name.len <= suffix.len) continue;
                const permission_set_name = file_name[0 .. file_name.len - suffix.len];
                if (!std.ascii.eqlIgnoreCase(permission_set_name, requested_name)) continue;

                const full_path =
                    std.fmt.allocPrint(self.arena, "{s}/{s}", .{ sp, entry.path }) catch continue;
                const xml = std.Io.Dir.cwd().readFileAlloc(
                    self.io,
                    full_path,
                    self.arena,
                    .limited(1024 * 1024),
                ) catch continue;
                if (self.find_permission_set_record_by_name(permission_set_name) != null) return;

                try self.load_permission_set_metadata_xml(permission_set_name, xml);
                return;
            }
        }
    }

    fn load_permission_set_metadata_xml(
        self: *Evaluator,
        permission_set_name: []const u8,
        xml: []const u8,
    ) !void {
        const permission_set = try self.arena.create(types.SObject);
        const permission_set_id = try self.alloc_id();
        permission_set.* = .{ .type_name = "PermissionSet", .id = permission_set_id };
        try permission_set.fields.put(self.arena, "Id", Value{ .string = permission_set_id });
        try permission_set.fields.put(
            self.arena,
            "Name",
            Value{ .string = try self.arena.dupe(u8, permission_set_name) },
        );
        try permission_set.fields.put(
            self.arena,
            "Label",
            Value{
                .string = try self.arena.dupe(
                    u8,
                    self.xml_tag_value(xml, "label") orelse permission_set_name,
                ),
            },
        );
        try self.append_store_record("PermissionSet", permission_set);
        try self.load_object_permission_metadata(xml, permission_set_id);
        try self.load_field_permission_metadata(xml, permission_set_id);
    }

    fn load_object_permission_metadata(
        self: *Evaluator,
        xml: []const u8,
        permission_set_id: []const u8,
    ) !void {
        var object_pos: usize = 0;
        while (object_pos < xml.len) {
            const block_start =
                std.mem.indexOfPos(u8, xml, object_pos, "<objectPermissions>") orelse break;
            const block_content_start = block_start + "<objectPermissions>".len;
            const block_end = std.mem.indexOfPos(
                u8,
                xml,
                block_content_start,
                "</objectPermissions>",
            ) orelse break;
            const block = xml[block_content_start..block_end];

            const object_name = self.xml_tag_value(block, "object") orelse {
                object_pos = block_end + "</objectPermissions>".len;
                continue;
            };

            try self.append_object_permission_metadata(
                permission_set_id,
                block,
                object_name,
            );

            object_pos = block_end + "</objectPermissions>".len;
        }
    }

    fn append_object_permission_metadata(
        self: *Evaluator,
        permission_set_id: []const u8,
        block: []const u8,
        object_name: []const u8,
    ) !void {
        const object_permission = try self.arena.create(types.SObject);
        object_permission.* = .{ .type_name = "ObjectPermissions", .id = try self.alloc_id() };
        try object_permission.fields.put(
            self.arena,
            "Id",
            Value{ .string = object_permission.id.? },
        );
        try object_permission.fields.put(
            self.arena,
            "ParentId",
            Value{ .string = permission_set_id },
        );
        try object_permission.fields.put(
            self.arena,
            "SobjectType",
            Value{ .string = try self.arena.dupe(u8, object_name) },
        );
        try object_permission.fields.put(
            self.arena,
            "PermissionsRead",
            Value{ .boolean = self.xml_tag_bool_value(block, "allowRead") orelse false },
        );
        try object_permission.fields.put(
            self.arena,
            "PermissionsCreate",
            Value{ .boolean = self.xml_tag_bool_value(block, "allowCreate") orelse false },
        );
        try object_permission.fields.put(
            self.arena,
            "PermissionsEdit",
            Value{ .boolean = self.xml_tag_bool_value(block, "allowEdit") orelse false },
        );
        try object_permission.fields.put(
            self.arena,
            "PermissionsDelete",
            Value{ .boolean = self.xml_tag_bool_value(block, "allowDelete") orelse false },
        );
        try self.append_store_record("ObjectPermissions", object_permission);
    }

    fn load_field_permission_metadata(
        self: *Evaluator,
        xml: []const u8,
        permission_set_id: []const u8,
    ) !void {
        var field_pos: usize = 0;
        while (field_pos < xml.len) {
            const block_start =
                std.mem.indexOfPos(u8, xml, field_pos, "<fieldPermissions>") orelse break;
            const block_content_start = block_start + "<fieldPermissions>".len;
            const block_end = std.mem.indexOfPos(
                u8,
                xml,
                block_content_start,
                "</fieldPermissions>",
            ) orelse break;
            const block = xml[block_content_start..block_end];

            const full_field_name = self.xml_tag_value(block, "field") orelse {
                field_pos = block_end + "</fieldPermissions>".len;
                continue;
            };

            var expanded_fields: std.ArrayListUnmanaged([]const u8) = .empty;
            try self.append_expanded_permission_fields(&expanded_fields, full_field_name);
            for (expanded_fields.items) |expanded_field_name| {
                try self.append_field_permission_metadata(
                    permission_set_id,
                    block,
                    expanded_field_name,
                );
            }

            field_pos = block_end + "</fieldPermissions>".len;
        }
    }

    fn append_field_permission_metadata(
        self: *Evaluator,
        permission_set_id: []const u8,
        block: []const u8,
        expanded_field_name: []const u8,
    ) !void {
        const field_permission = try self.arena.create(types.SObject);
        field_permission.* = .{ .type_name = "FieldPermissions", .id = try self.alloc_id() };
        try field_permission.fields.put(
            self.arena,
            "Id",
            Value{ .string = field_permission.id.? },
        );
        try field_permission.fields.put(
            self.arena,
            "ParentId",
            Value{ .string = permission_set_id },
        );
        try field_permission.fields.put(
            self.arena,
            "Field",
            Value{ .string = try self.arena.dupe(u8, expanded_field_name) },
        );
        try field_permission.fields.put(
            self.arena,
            "PermissionsRead",
            Value{ .boolean = self.xml_tag_bool_value(block, "readable") orelse false },
        );
        try field_permission.fields.put(
            self.arena,
            "PermissionsCreate",
            Value{ .boolean = self.xml_tag_bool_value(block, "editable") orelse false },
        );
        try field_permission.fields.put(
            self.arena,
            "PermissionsEdit",
            Value{ .boolean = self.xml_tag_bool_value(block, "editable") orelse false },
        );
        try self.append_store_record("FieldPermissions", field_permission);
    }

    /// Execute an aggregate SOQL query (with SUM/AVG/MIN/MAX/COUNT and optional GROUP BY).
    /// Returns List<AggregateResult>.
    const AggregateItem = struct {
        fn_name: ?[]const u8,
        field: []const u8,
        alias: []const u8,
    };

    const AggregateItemList = struct {
        items: [16]AggregateItem = undefined,
        count: usize = 0,
    };

    const GroupByFieldList = struct {
        fields: [8][]const u8 = undefined,
        count: usize = 0,
    };

    fn execute_aggregate_query(
        self: *Evaluator,
        soql: []const u8,
        current_env: *Env,
        include_all_rows: bool,
    ) !Value {
        const from_type_agg = extract_from_type(soql) orelse return self.make_empty_list();
        const select_start = if (std.ascii.indexOfIgnoreCase(soql, "SELECT")) |si| si + 6 else 0;
        const from_start = std.ascii.indexOfIgnoreCase(soql, "FROM") orelse soql.len;
        const select_clause = std.mem.trim(u8, soql[select_start..from_start], " \t\n\r");

        const group_by = parse_aggregate_group_by_fields(soql);
        const agg_items = try self.parse_aggregate_items(select_clause);
        const matched = try self.collect_aggregate_records(
            from_type_agg,
            soql,
            current_env,
            include_all_rows,
        );

        if (group_by.count == 0) {
            return try self.build_single_aggregate_result(
                agg_items.items[0..agg_items.count],
                matched.items,
            );
        }
        return try self.build_grouped_aggregate_results(
            agg_items.items[0..agg_items.count],
            group_by.fields[0..group_by.count],
            matched.items,
        );
    }

    fn parse_aggregate_group_by_fields(soql: []const u8) GroupByFieldList {
        var result: GroupByFieldList = .{};
        const group_by_idx = std.ascii.indexOfIgnoreCase(soql, "group by");
        if (group_by_idx) |gbi| {
            const gb_clause = std.mem.trim(u8, soql[gbi + 8 ..], " \t\n\r");
            var gb_iter = std.mem.splitScalar(u8, gb_clause, ',');
            while (gb_iter.next()) |raw_f| {
                const f = std.mem.trim(u8, raw_f, " \t\n\r");
                if (f.len == 0) continue;
                if (result.count < result.fields.len) {
                    result.fields[result.count] = f;
                    result.count += 1;
                }
            }
        }
        return result;
    }

    fn parse_aggregate_items(self: *Evaluator, select_clause: []const u8) !AggregateItemList {
        var result: AggregateItemList = .{};
        var expr_idx: usize = 0;
        var sel_iter = std.mem.splitScalar(u8, select_clause, ',');
        while (sel_iter.next()) |raw_item| {
            const item = std.mem.trim(u8, raw_item, " \t\n\r");
            if (item.len == 0) continue;
            if (result.count >= result.items.len) break;
            result.items[result.count] = try self.parse_aggregate_item(item, &expr_idx);
            result.count += 1;
        }
        return result;
    }

    fn parse_aggregate_item(
        self: *Evaluator,
        item: []const u8,
        expr_idx: *usize,
    ) !AggregateItem {
        if (std.mem.indexOf(u8, item, "(")) |paren_start| {
            const fn_name = std.mem.trim(u8, item[0..paren_start], " \t\n\r");
            if (std.mem.indexOf(u8, item[paren_start..], ")")) |paren_end_rel| {
                const paren_end = paren_start + paren_end_rel;
                const field = std.mem.trim(u8, item[paren_start + 1 .. paren_end], " \t\n\r");
                const after = std.mem.trim(u8, item[paren_end + 1 ..], " \t\n\r");
                const alias = if (after.len > 0)
                    after
                else
                    try std.fmt.allocPrint(self.arena, "expr{d}", .{expr_idx.*});
                expr_idx.* += 1;
                return .{ .fn_name = fn_name, .field = field, .alias = alias };
            }
        }
        var parts = std.mem.splitScalar(u8, item, ' ');
        const field = parts.next() orelse item;
        const alias = parts.next() orelse field;
        return .{ .fn_name = null, .field = field, .alias = alias };
    }

    fn collect_aggregate_records(
        self: *Evaluator,
        from_type: []const u8,
        soql: []const u8,
        current_env: *Env,
        include_all_rows: bool,
    ) !std.ArrayListUnmanaged(Value) {
        var matched: std.ArrayListUnmanaged(Value) = .empty;
        var store_iter = self.store.iterator();
        while (store_iter.next()) |entry| {
            if (std.ascii.eqlIgnoreCase(entry.key_ptr.*, from_type)) {
                for (entry.value_ptr.items) |record| {
                    if (self.matches_where(record, soql, current_env))
                        try matched.append(self.arena, record);
                }
                break;
            }
        }
        if (include_all_rows) {
            var trash_iter = self.trash.iterator();
            while (trash_iter.next()) |entry| {
                if (std.ascii.eqlIgnoreCase(entry.key_ptr.*, from_type)) {
                    for (entry.value_ptr.items) |record| {
                        if (self.matches_where(record, soql, current_env))
                            try matched.append(self.arena, record);
                    }
                    break;
                }
            }
        }
        return matched;
    }

    fn build_single_aggregate_result(
        self: *Evaluator,
        agg_items: []const AggregateItem,
        matched: []const Value,
    ) !Value {
        const agg = try self.arena.create(types.SObject);
        agg.* = .{ .type_name = "AggregateResult" };
        try self.append_aggregate_result_fields(agg, agg_items, matched, false);
        const result_list = try self.arena.create(types.ListValue);
        result_list.* = .{};
        try result_list.items.append(self.arena, Value{ .sobject = agg });
        return Value{ .list = result_list };
    }

    fn build_grouped_aggregate_results(
        self: *Evaluator,
        agg_items: []const AggregateItem,
        group_by_fields: []const []const u8,
        matched: []const Value,
    ) !Value {
        var group_keys: std.ArrayListUnmanaged([]const u8) = .empty;
        var group_records: std.ArrayListUnmanaged(std.ArrayListUnmanaged(Value)) = .empty;
        try self.collect_aggregate_groups(&group_keys, &group_records, matched, group_by_fields);
        const result_list = try self.arena.create(types.ListValue);
        result_list.* = .{};
        for (group_records.items) |group| {
            const agg = try self.arena.create(types.SObject);
            agg.* = .{ .type_name = "AggregateResult" };
            try self.append_aggregate_result_fields(agg, agg_items, group.items, true);
            try result_list.items.append(self.arena, Value{ .sobject = agg });
        }
        return Value{ .list = result_list };
    }

    fn collect_aggregate_groups(
        self: *Evaluator,
        group_keys: *std.ArrayListUnmanaged([]const u8),
        group_records: *std.ArrayListUnmanaged(std.ArrayListUnmanaged(Value)),
        matched: []const Value,
        group_by_fields: []const []const u8,
    ) !void {
        for (matched) |record| {
            const key = try self.aggregate_group_key(record, group_by_fields);
            for (group_keys.items, 0..) |gk, idx| {
                if (std.mem.eql(u8, gk, key)) {
                    try group_records.items[idx].append(self.arena, record);
                    break;
                }
            } else {
                try group_keys.append(self.arena, key);
                var new_group: std.ArrayListUnmanaged(Value) = .empty;
                try new_group.append(self.arena, record);
                try group_records.append(self.arena, new_group);
            }
        }
    }

    fn aggregate_group_key(
        self: *Evaluator,
        record: Value,
        group_by_fields: []const []const u8,
    ) ![]const u8 {
        var key_buf: std.ArrayListUnmanaged(u8) = .empty;
        for (group_by_fields) |gb_field| {
            if (key_buf.items.len > 0) try key_buf.append(self.arena, '|');
            const fv = self.resolve_field_path(record, gb_field);
            const fv_str = if (fv != null and fv.? != .null_val)
                (utils.coerce_to_string(fv.?, self.arena) catch "")
            else
                "";
            try key_buf.appendSlice(self.arena, fv_str);
        }
        return key_buf.items;
    }

    fn append_aggregate_result_fields(
        self: *Evaluator,
        agg: *types.SObject,
        agg_items: []const AggregateItem,
        records: []const Value,
        include_plain_fields: bool,
    ) !void {
        for (agg_items) |ai| {
            if (ai.fn_name) |fn_name| {
                try agg.fields.put(
                    self.arena,
                    ai.alias,
                    self.compute_aggregate(fn_name, ai.field, records),
                );
            } else if (include_plain_fields and records.len > 0) {
                const fv = self.resolve_field_path(records[0], ai.field) orelse Value.null_val;
                try agg.fields.put(self.arena, ai.alias, fv);
            }
        }
    }

    /// Compute a single aggregate value (COUNT/SUM/AVG/MIN/MAX) over a set of records.
    fn compute_aggregate(
        self: *Evaluator,
        fn_name: []const u8,
        field: []const u8,
        records: []const Value,
    ) Value {
        _ = self;
        if (std.ascii.eqlIgnoreCase(fn_name, "COUNT")) {
            var count: i64 = 0;
            for (records) |r| {
                if (r == .sobject) {
                    // COUNT(Id) or COUNT(field) — count non-null values
                    if (utils.sobject_get(&r.sobject.fields, field)) |v| {
                        if (v != .null_val) count += 1;
                    } else if (std.ascii.eqlIgnoreCase(field, "Id") and r.sobject.id != null) {
                        count += 1;
                    }
                }
            }
            return Value{ .integer = count };
        }
        // SUM, AVG, MIN, MAX
        var sum: f64 = 0;
        var count: i64 = 0;
        var min_val: ?f64 = null;
        var max_val: ?f64 = null;
        for (records) |r| {
            if (r == .sobject) {
                if (utils.sobject_get(&r.sobject.fields, field)) |fv| {
                    const num: ?f64 = if (fv == .double)
                        fv.double
                    else if (fv == .integer)
                        @floatFromInt(fv.integer)
                    else
                        null;
                    if (num) |n| {
                        sum += n;
                        count += 1;
                        if (min_val == null or n < min_val.?) min_val = n;
                        if (max_val == null or n > max_val.?) max_val = n;
                    }
                }
            }
        }
        if (std.ascii.eqlIgnoreCase(fn_name, "SUM")) return Value{ .double = sum };
        if (std.ascii.eqlIgnoreCase(fn_name, "AVG")) {
            return if (count > 0)
                Value{ .double = sum / @as(f64, @floatFromInt(count)) }
            else
                Value{ .double = 0 };
        }
        if (std.ascii.eqlIgnoreCase(fn_name, "MIN")) {
            return if (min_val) |v| Value{ .double = v } else Value.null_val;
        }
        if (std.ascii.eqlIgnoreCase(fn_name, "MAX")) {
            return if (max_val) |v| Value{ .double = v } else Value.null_val;
        }
        return Value{ .integer = count };
    }

    /// Resolve a dotted field path like "Log__r.LogPurgeAction__c" on a record.
    fn resolve_field_path(self: *Evaluator, record: Value, path: []const u8) ?Value {
        if (record != .sobject) return null;
        if (std.mem.indexOfScalar(u8, path, '.') == null) {
            return self.get_s_object_field_value_case_insensitive(record.sobject, path);
        }
        return self.resolve_field_path_value(record.sobject, path);
    }

    /// Execute a SOSL query using fixed search results.
    /// Returns List<List<SObject>> - one list per RETURNING type.
    fn execute_sosl(self: *Evaluator, sosl: []const u8) !Value {
        // Parse RETURNING clause to find type names
        // e.g., FIND 'search' IN ALL FIELDS RETURNING Account(Name), Contact(LastName)
        var type_names: [8][]const u8 = undefined;
        var type_count: usize = 0;
        if (std.ascii.indexOfIgnoreCase(sosl, "RETURNING")) |ret_pos| {
            const returning = sosl[ret_pos + 9 ..];
            var iter = std.mem.splitScalar(u8, returning, ',');
            while (iter.next()) |part| {
                const trimmed = std.mem.trim(u8, part, " \t\n\r");
                if (trimmed.len == 0) continue;
                // Extract type name (before parenthesis)
                var end: usize = 0;
                while (end < trimmed.len and trimmed[end] != '(' and trimmed[end] != ' ') end += 1;
                if (end > 0 and type_count < type_names.len) {
                    type_names[type_count] = trimmed[0..end];
                    type_count += 1;
                }
            }
        }

        // Build result: List<List<SObject>>
        const outer = try self.arena.create(types.ListValue);
        outer.* = .{};
        if (type_count == 0) {
            try self.append_empty_sosl_result(outer);
            return Value{ .list = outer };
        }

        // Get fixed search result Ids
        var search_ids: std.ArrayListUnmanaged([]const u8) = .empty;
        if (self.fixed_search_results) |fsr| {
            if (fsr == .list) {
                for (fsr.list.items.items) |item| {
                    if (item == .string) {
                        try search_ids.append(self.arena, item.string);
                    }
                }
            }
        }

        try self.append_sosl_returning_results(outer, type_names[0..type_count], search_ids.items);

        return Value{ .list = outer };
    }

    fn append_empty_sosl_result(self: *Evaluator, outer: *types.ListValue) !void {
        const inner = try self.arena.create(types.ListValue);
        inner.* = .{};
        try outer.items.append(self.arena, Value{ .list = inner });
    }

    fn append_sosl_returning_results(
        self: *Evaluator,
        outer: *types.ListValue,
        type_names: []const []const u8,
        search_ids: []const []const u8,
    ) !void {
        for (type_names) |type_name| {
            const inner = try self.arena.create(types.ListValue);
            inner.* = .{};
            var store_iter = self.store.iterator();
            while (store_iter.next()) |entry| {
                if (!std.ascii.eqlIgnoreCase(entry.key_ptr.*, type_name)) continue;
                try self.append_sosl_records(inner, entry.value_ptr.items, search_ids);
                break;
            }
            try outer.items.append(self.arena, Value{ .list = inner });
        }
    }

    fn append_sosl_records(
        self: *Evaluator,
        inner: *types.ListValue,
        records: []const Value,
        search_ids: []const []const u8,
    ) !void {
        for (records) |record| {
            if (record != .sobject or record.sobject.id == null) continue;
            if (search_ids.len == 0 or sosl_id_selected(record.sobject.id.?, search_ids)) {
                try inner.items.append(self.arena, record);
            }
        }
    }

    fn sosl_id_selected(record_id: []const u8, search_ids: []const []const u8) bool {
        for (search_ids) |sid| {
            if (std.ascii.eqlIgnoreCase(record_id, sid)) return true;
        }
        return false;
    }

    fn matches_where(self: *Evaluator, record: Value, soql: []const u8, current_env: *Env) bool {
        const where_clause = extract_where_clause(soql) orelse return true;
        if (record != .sobject) return true;
        return self.eval_where_condition(record.sobject, where_clause, current_env);
    }

    fn extract_where_in_bind_info(
        self: *Evaluator,
        soql: []const u8,
    ) ?struct {
        field_name: []const u8,
        bind_name: []const u8,
    } {
        _ = self;
        const where_clause = extract_where_clause(soql) orelse return null;
        const in_pos = std.ascii.indexOfIgnoreCase(where_clause, " IN :") orelse return null;

        var field_end = in_pos;
        while (field_end > 0 and
            is_soql_whitespace(where_clause[field_end - 1])) : (field_end -= 1)
        {}
        var field_start = field_end;
        while (field_start > 0) {
            const ch = where_clause[field_start - 1];
            if (std.ascii.isAlphanumeric(ch) or ch == '_' or ch == '.') {
                field_start -= 1;
            } else break;
        }
        if (field_start == field_end) return null;

        var bind_start = in_pos + " IN :".len;
        while (bind_start < where_clause.len and
            is_soql_whitespace(where_clause[bind_start])) : (bind_start += 1)
        {}
        var bind_end = bind_start;
        while (bind_end < where_clause.len and
            (std.ascii.isAlphanumeric(where_clause[bind_end]) or
                where_clause[bind_end] == '_')) : (bind_end += 1)
        {}
        if (bind_end == bind_start) return null;

        return .{
            .field_name = where_clause[field_start..field_end],
            .bind_name = where_clause[bind_start..bind_end],
        };
    }

    fn reorder_records_by_in_bind(
        self: *Evaluator,
        records: *std.ArrayListUnmanaged(Value),
        field_name: []const u8,
        bind_val: Value,
    ) !void {
        if (records.items.len <= 1) return;

        const bind_items: []const Value = switch (bind_val) {
            .list => bind_val.list.items.items,
            .set => bind_val.set.entries.values(),
            else => return,
        };
        if (bind_items.len == 0) return;

        const consumed = try self.arena.alloc(bool, records.items.len);
        @memset(consumed, false);

        var reordered: std.ArrayListUnmanaged(Value) = .empty;

        for (bind_items) |bind_item| {
            const expected = if (bind_item == .sobject and
                std.ascii.eqlIgnoreCase(field_name, "Id"))
            blk: {
                if (self.sobject_id_for_result(bind_item.sobject)) |record_id| {
                    break :blk Value{ .string = record_id };
                }
                break :blk bind_item;
            } else bind_item;

            for (records.items, 0..) |record, idx| {
                if (consumed[idx] or record != .sobject) continue;
                const actual = if (std.ascii.eqlIgnoreCase(field_name, "Id")) blk: {
                    if (self.sobject_id_for_result(record.sobject)) |record_id| {
                        break :blk Value{ .string = record_id };
                    }
                    break :blk self.get_s_object_field_value_case_insensitive(
                        record.sobject,
                        field_name,
                    ) orelse Value.null_val;
                } else self.get_s_object_field_value_case_insensitive(
                    record.sobject,
                    field_name,
                ) orelse Value.null_val;
                if (utils.value_eql(actual, expected)) {
                    try reordered.append(self.arena, record);
                    consumed[idx] = true;
                    break;
                }
            }
        }

        for (records.items, 0..) |record, idx| {
            if (!consumed[idx]) try reordered.append(self.arena, record);
        }

        records.* = reordered;
    }

    fn bind_collection_contains(self: *Evaluator, field_val: Value, bind_val: Value) bool {
        switch (bind_val) {
            .list => |list| {
                for (list.items.items) |item| {
                    if (utils.value_eql(field_val, item)) return true;
                    if (field_val == .string and item == .sobject) {
                        if (item.sobject.id) |item_id| {
                            if (std.ascii.eqlIgnoreCase(field_val.string, item_id)) return true;
                        }
                    }
                }
                return false;
            },
            .map => |map| {
                if (field_val == .string) {
                    for (map.entries.keys()) |key| {
                        if (std.ascii.eqlIgnoreCase(field_val.string, key)) return true;
                    }
                }
                return false;
            },
            .set => {
                const field_str = utils.coerce_to_string(field_val, self.arena) catch return false;
                return bind_val.set.entries.contains(field_str);
            },
            else => return false,
        }
    }

    fn eval_where_condition(
        self: *Evaluator,
        sob: *types.SObject,
        clause: []const u8,
        current_env: *Env,
    ) bool {
        const trimmed = std.mem.trim(u8, clause, " \t\n\r");
        if (trimmed.len == 0) return true;

        // Handle AND
        if (find_logical_op(trimmed, "AND")) |and_pos| {
            const left_part = trimmed[0..and_pos];
            const right_part = trimmed[and_pos + 3 ..];
            return self.eval_where_condition(sob, left_part, current_env) and
                self.eval_where_condition(sob, right_part, current_env);
        }

        // Handle OR
        if (find_logical_op(trimmed, "OR")) |or_pos| {
            const left_part = trimmed[0..or_pos];
            const right_part = trimmed[or_pos + 2 ..];
            return self.eval_where_condition(sob, left_part, current_env) or
                self.eval_where_condition(sob, right_part, current_env);
        }

        // Strip outer parens
        if (trimmed.len > 2 and trimmed[0] == '(') {
            // Find matching paren
            var depth: u32 = 0;
            var all_enclosed = false;
            for (trimmed, 0..) |ch, i| {
                if (ch == '(') depth += 1;
                if (ch == ')') {
                    depth -= 1;
                    if (depth == 0 and i == trimmed.len - 1) all_enclosed = true;
                }
            }
            if (all_enclosed) {
                return self.eval_where_condition(sob, trimmed[1 .. trimmed.len - 1], current_env);
            }
        }

        // Simple condition: field = 'value' or field = :bindVar or field != 'value'
        return self.eval_simple_condition(sob, trimmed, current_env);
    }

    const WhereOperatorKind = enum {
        eq,
        neq,
        like,
        in,
        gt,
        gte,
        lt,
        lte,
    };

    const WhereOperator = struct {
        pos: usize,
        len: usize,
        kind: WhereOperatorKind,
    };

    const WhereFieldValue = struct {
        value: Value,
        found: bool,
    };

    const WhereValueResolution = union(enum) {
        value: Value,
        result: bool,
    };

    fn eval_simple_condition(
        self: *Evaluator,
        sob: *types.SObject,
        cond: []const u8,
        current_env: *Env,
    ) bool {
        const op = parse_where_operator(cond) orelse return true;
        const op_start = op.pos;
        const field_name = std.mem.trim(u8, cond[0..op_start], " \t\n\r");
        const value_str = std.mem.trim(u8, cond[op_start + op.len ..], " \t\n\r");
        const field = self.resolve_where_field_value(sob, field_name);
        if (!field.found) {
            return self.eval_missing_where_field(cond, field_name, value_str, op.kind, current_env);
        }
        if (op.kind == .like) return self.eval_like_condition(field.value, value_str, current_env);
        if (op.kind == .in) return self.eval_in_condition(field.value, value_str, current_env);

        const cmp_val = switch (self.resolve_where_comparison_value(
            value_str,
            current_env,
        )) {
            .value => |value| value,
            .result => |result| return result,
        };
        if (cmp_val == .list or cmp_val == .map or cmp_val == .set) {
            const contains = self.bind_collection_contains(field.value, cmp_val);
            return if (op.kind == .neq) !contains else contains;
        }
        if (op.kind == .neq) return !where_values_equal(field_name, field.value, cmp_val);
        if (where_operator_is_ordered(op.kind)) {
            return eval_ordered_where_comparison(field.value, cmp_val, op.kind);
        }
        return where_values_equal(field_name, field.value, cmp_val);
    }

    fn where_values_equal(field_name: []const u8, lhs: Value, rhs: Value) bool {
        if (std.mem.endsWith(u8, field_name, ".NamespacePrefix") or
            std.ascii.eqlIgnoreCase(field_name, "NamespacePrefix"))
        {
            if (lhs == .null_val and rhs == .string and rhs.string.len == 0) return true;
            if (rhs == .null_val and lhs == .string and lhs.string.len == 0) return true;
        }
        return utils.value_eql(lhs, rhs);
    }

    fn parse_where_operator(cond: []const u8) ?WhereOperator {
        var i: usize = 0;
        while (i < cond.len) : (i += 1) {
            if (i + 1 < cond.len and cond[i] == '>' and cond[i + 1] == '=') {
                return .{ .pos = i, .len = 2, .kind = .gte };
            }
            if (i + 1 < cond.len and cond[i] == '<' and cond[i + 1] == '=') {
                return .{ .pos = i, .len = 2, .kind = .lte };
            }
            if (cond[i] == '>' and (i + 1 >= cond.len or cond[i + 1] != '=')) {
                return .{ .pos = i, .len = 1, .kind = .gt };
            }
            if (cond[i] == '<' and
                (i + 1 >= cond.len or (cond[i + 1] != '=' and cond[i + 1] != '>')))
            {
                return .{ .pos = i, .len = 1, .kind = .lt };
            }
            if (cond[i] == '=' and
                (i == 0 or cond[i - 1] != '!' and cond[i - 1] != '<' and cond[i - 1] != '>'))
            {
                return .{ .pos = i, .len = 1, .kind = .eq };
            }
            if (i + 1 < cond.len and cond[i] == '!' and cond[i + 1] == '=') {
                return .{ .pos = i, .len = 2, .kind = .neq };
            }
            if (i + 1 < cond.len and cond[i] == '<' and cond[i + 1] == '>') {
                return .{ .pos = i, .len = 2, .kind = .neq };
            }
            if (where_word_matches(cond, i, "LIKE")) return .{ .pos = i, .len = 4, .kind = .like };
            if (where_word_matches(cond, i, "IN")) return .{ .pos = i, .len = 2, .kind = .in };
        }
        return null;
    }

    fn where_word_matches(cond: []const u8, pos: usize, word: []const u8) bool {
        if (pos + word.len > cond.len) return false;
        if (!std.ascii.eqlIgnoreCase(cond[pos .. pos + word.len], word)) return false;
        return (pos == 0 or cond[pos - 1] == ' ') and
            (pos + word.len >= cond.len or cond[pos + word.len] == ' ');
    }

    fn resolve_where_field_value(
        self: *Evaluator,
        sob: *types.SObject,
        field_name: []const u8,
    ) WhereFieldValue {
        if (std.mem.indexOf(u8, field_name, ".") != null) {
            if (self.resolve_field_path_value(sob, field_name)) |value| {
                return .{ .value = value, .found = true };
            }
        } else if (self.get_s_object_field_value_case_insensitive(sob, field_name)) |value| {
            return .{ .value = value, .found = true };
        }
        if (computed_where_field_value(sob, field_name)) |value| {
            return .{ .value = value, .found = true };
        }
        if (std.ascii.eqlIgnoreCase(field_name, "IsDeleted")) {
            return .{ .value = Value{ .boolean = false }, .found = true };
        }
        return .{ .value = Value.null_val, .found = false };
    }

    fn computed_where_field_value(sob: *types.SObject, field_name: []const u8) ?Value {
        if (!std.ascii.eqlIgnoreCase(sob.type_name, "Opportunity")) return null;
        if (std.ascii.eqlIgnoreCase(field_name, "IsClosed")) {
            return Value{ .boolean = opportunity_stage_is_closed(sob) };
        }
        if (std.ascii.eqlIgnoreCase(field_name, "IsWon")) {
            return Value{ .boolean = opportunity_stage_is_won(sob) };
        }
        return null;
    }

    fn opportunity_stage_is_closed(sob: *types.SObject) bool {
        const stage = utils.sobject_get(&sob.fields, "StageName") orelse return false;
        if (stage != .string) return false;
        return std.ascii.indexOfIgnoreCase(stage.string, "Closed") != null;
    }

    fn opportunity_stage_is_won(sob: *types.SObject) bool {
        const stage = utils.sobject_get(&sob.fields, "StageName") orelse return false;
        if (stage != .string) return false;
        return std.ascii.indexOfIgnoreCase(stage.string, "Won") != null;
    }

    fn eval_missing_where_field(
        self: *Evaluator,
        cond: []const u8,
        field_name: []const u8,
        value_str: []const u8,
        op: WhereOperatorKind,
        current_env: *Env,
    ) bool {
        if (self.has_where_field_null_literal(cond, field_name)) return op != .neq;
        if (value_str.len > 0 and value_str[0] == ':') {
            if (self.lookup_bind_value(current_env, value_str[1..])) |bind_value| {
                if (bind_value == .null_val) return true;
            }
        }
        return op == .neq;
    }

    fn eval_like_condition(
        self: *Evaluator,
        field_val: Value,
        value_str: []const u8,
        current_env: *Env,
    ) bool {
        if (field_val != .string) return false;
        var pattern = std.mem.trim(u8, value_str, " \t\n\r");
        if (pattern.len > 0 and pattern[0] == ':') {
            const bind_value = self.lookup_bind_value(
                current_env,
                pattern[1..],
            ) orelse return false;
            if (bind_value != .string) return false;
            pattern = bind_value.string;
        }
        if (pattern.len >= 2 and pattern[0] == '\'') pattern = pattern[1..];
        if (pattern.len >= 1 and pattern[pattern.len - 1] == '\'') {
            pattern = pattern[0 .. pattern.len - 1];
        }
        pattern = self.collapse_like_wildcards(pattern);
        if (pattern.len == 0) return field_val.string.len == 0;
        var non_wildcard_len: usize = 0;
        for (pattern) |ch| {
            if (ch != '%') non_wildcard_len += 1;
        }
        if (non_wildcard_len == 0) return true;
        const starts_wild = pattern[0] == '%';
        const ends_wild = pattern[pattern.len - 1] == '%';
        const inner = pattern[@intFromBool(starts_wild) .. pattern.len - @intFromBool(ends_wild)];
        if (starts_wild and ends_wild) {
            return std.ascii.indexOfIgnoreCase(field_val.string, inner) != null;
        }
        if (starts_wild) return std.ascii.endsWithIgnoreCase(field_val.string, inner);
        if (ends_wild) return std.ascii.startsWithIgnoreCase(field_val.string, inner);
        return std.ascii.eqlIgnoreCase(field_val.string, pattern);
    }

    fn eval_in_condition(
        self: *Evaluator,
        field_val: Value,
        value_str: []const u8,
        current_env: *Env,
    ) bool {
        const in_str = std.mem.trim(u8, value_str, " \t\n\r");
        if (in_str.len > 0 and in_str[0] == ':') {
            if (self.lookup_bind_value(current_env, in_str[1..])) |bind_val| {
                if (self.bind_collection_contains(field_val, bind_val)) return true;
                if (bind_val == .list or bind_val == .map or bind_val == .set) return false;
            }
        }
        const paren_start = std.mem.indexOf(u8, in_str, "(") orelse return true;
        const inner = if (std.mem.lastIndexOf(u8, in_str, ")")) |paren_end|
            in_str[paren_start + 1 .. paren_end]
        else
            in_str[paren_start + 1 ..];
        if (std.ascii.indexOfIgnoreCase(inner, "SELECT") != null) {
            return self.subquery_contains_value(field_val, inner, current_env);
        }
        var iter = std.mem.splitScalar(u8, inner, ',');
        while (iter.next()) |part| {
            if (where_in_literal_matches(field_val, std.mem.trim(u8, part, " \t\n\r'"))) {
                return true;
            }
        }
        return false;
    }

    fn where_in_literal_matches(field_val: Value, literal: []const u8) bool {
        if (field_val == .string and std.ascii.eqlIgnoreCase(field_val.string, literal)) {
            return true;
        }
        if (field_val == .integer) {
            if (std.fmt.parseInt(i64, literal, 10)) |int_val| {
                return field_val.integer == int_val;
            } else |_| {}
        }
        return false;
    }

    fn resolve_where_comparison_value(
        self: *Evaluator,
        value_str: []const u8,
        current_env: *Env,
    ) WhereValueResolution {
        if (value_str.len > 0 and value_str[0] == '\'') {
            if (value_str.len >= 2) {
                var end = value_str.len;
                if (value_str[end - 1] == '\'') end -= 1;
                return .{ .value = Value{ .string = value_str[1..end] } };
            }
            return .{ .value = Value.null_val };
        }
        if (value_str.len > 0 and value_str[0] == ':') {
            return self.resolve_where_bind_comparison_value(value_str[1..], current_env);
        }
        if (std.fmt.parseInt(i64, std.mem.trim(u8, value_str, " \t\n\r"), 10)) |int_val| {
            return .{ .value = Value{ .integer = int_val } };
        } else |_| {}

        const trimmed_value = std.mem.trim(u8, value_str, " \t\n\r");
        if (std.ascii.eqlIgnoreCase(trimmed_value, "null")) return .{ .value = Value.null_val };
        if (std.ascii.eqlIgnoreCase(trimmed_value, "true")) {
            return .{ .value = Value{ .boolean = true } };
        }
        if (std.ascii.eqlIgnoreCase(trimmed_value, "false")) {
            return .{ .value = Value{ .boolean = false } };
        }
        return .{ .result = true };
    }

    fn resolve_where_bind_comparison_value(
        self: *Evaluator,
        var_name: []const u8,
        current_env: *Env,
    ) WhereValueResolution {
        if (self.lookup_bind_value(current_env, var_name)) |bind_val| {
            return .{ .value = bind_val };
        }
        const dot_pos = std.mem.indexOf(u8, var_name, ".") orelse return .{ .result = false };
        const base_val = resolve_dotted_bind_base_value(
            current_env,
            var_name[0..dot_pos],
        ) orelse return .{ .result = true };
        const prop_name = var_name[dot_pos + 1 ..];
        if (base_val == .sobject) {
            return .{
                .value = utils.sobject_get(&base_val.sobject.fields, prop_name) orelse
                    Value.null_val,
            };
        }
        if (base_val == .object) {
            return .{
                .value = utils.sobject_get(&base_val.object.fields, prop_name) orelse
                    Value.null_val,
            };
        }
        return .{ .result = false };
    }

    fn resolve_dotted_bind_base_value(current_env: *Env, base_name: []const u8) ?Value {
        if (std.mem.indexOf(u8, base_name, "[")) |bracket_pos| {
            const arr_name = base_name[0..bracket_pos];
            const idx_end = std.mem.indexOfPos(
                u8,
                base_name,
                bracket_pos,
                "]",
            ) orelse return current_env.get(base_name);
            const idx_str = base_name[bracket_pos + 1 .. idx_end];
            const idx = std.fmt.parseInt(
                usize,
                idx_str,
                10,
            ) catch return current_env.get(base_name);
            const arr_val = current_env.get(arr_name) orelse return null;
            if (arr_val == .list and idx < arr_val.list.items.items.len) {
                return arr_val.list.items.items[idx];
            }
            return null;
        }
        return current_env.get(base_name);
    }

    fn where_operator_is_ordered(op: WhereOperatorKind) bool {
        return op == .gt or op == .gte or op == .lt or op == .lte;
    }

    fn eval_ordered_where_comparison(field_val: Value, cmp_val: Value, op: WhereOperatorKind) bool {
        if (builtins.extract_date_string(field_val)) |lhs_date| {
            if (builtins.extract_date_string(cmp_val)) |rhs_date| {
                return compare_where_order(std.mem.order(u8, lhs_date, rhs_date), op);
            }
        }
        if (field_val == .string and cmp_val == .string) {
            return compare_where_order(std.mem.order(u8, field_val.string, cmp_val.string), op);
        }
        const lhs = numeric_where_value(field_val) orelse return false;
        const rhs = numeric_where_value(cmp_val) orelse return false;
        return switch (op) {
            .gt => lhs > rhs,
            .gte => lhs >= rhs,
            .lt => lhs < rhs,
            .lte => lhs <= rhs,
            else => false,
        };
    }

    fn compare_where_order(order: std.math.Order, op: WhereOperatorKind) bool {
        return switch (op) {
            .gt => order == .gt,
            .gte => order == .gt or order == .eq,
            .lt => order == .lt,
            .lte => order == .lt or order == .eq,
            else => false,
        };
    }

    fn numeric_where_value(value: Value) ?f64 {
        if (value == .integer) return @floatFromInt(value.integer);
        if (value == .double) return value.double;
        return null;
    }

    fn subquery_contains_value(
        self: *Evaluator,
        field_val: Value,
        subquery: []const u8,
        current_env: *Env,
    ) bool {
        const select_start = std.ascii.indexOfIgnoreCase(subquery, "SELECT") orelse return false;
        const from_start = std.ascii.indexOfIgnoreCase(subquery, "FROM") orelse return false;
        if (from_start <= select_start + 6) return false;
        const select_clause = std.mem.trim(u8, subquery[select_start + 6 .. from_start], " \t\n\r");
        if (select_clause.len == 0) return false;
        const selected_field = std.mem.trim(
            u8,
            if (std.mem.indexOfScalar(u8, select_clause, ',')) |comma_pos|
                select_clause[0..comma_pos]
            else
                select_clause,
            " \t\n\r",
        );

        const subquery_result = self.execute_soql(subquery, current_env) catch return false;
        if (subquery_result != .list) return false;
        for (subquery_result.list.items.items) |item| {
            if (item != .sobject) continue;
            const candidate = if (std.ascii.eqlIgnoreCase(selected_field, "Id"))
                (if (item.sobject.id) |record_id| Value{ .string = record_id } else Value.null_val)
            else
                self.resolve_field_path_value(item.sobject, selected_field) orelse
                    self.get_s_object_field_value_case_insensitive(
                        item.sobject,
                        selected_field,
                    ) orelse Value.null_val;
            if (utils.value_eql(field_val, candidate)) return true;
        }
        return false;
    }

    fn make_empty_list(self: *Evaluator) !Value {
        const list = try self.arena.create(types.ListValue);
        list.* = .{};
        return Value{ .list = list };
    }

    /// Resolve the child SObject type from a relationship name.
    /// e.g., "Contacts" on Account → "Contact"
    fn resolve_child_type(
        self: *Evaluator,
        parent_type: []const u8,
        relationship: []const u8,
    ) ?[]const u8 {
        if (self.resolve_custom_child_relationship(parent_type, relationship)) |custom| {
            return custom.child_type;
        }
        if (std.ascii.eqlIgnoreCase(parent_type, "Data_Import_Object_Mapping__mdt") and
            std.ascii.eqlIgnoreCase(relationship, "Data_Import_Field_Mappings__r"))
        {
            return "Data_Import_Field_Mapping__mdt";
        }
        // Common Salesforce relationship mappings
        const mappings = .{
            .{ "Contacts", "Contact" },
            .{ "Opportunities", "Opportunity" },
            .{ "Cases", "Case" },
            .{ "Tasks", "Task" },
            .{ "Events", "Event" },
            .{ "Notes", "Note" },
            .{ "Attachments", "Attachment" },
            .{ "ContentDocumentLinks", "ContentDocumentLink" },
            .{ "Leads", "Lead" },
            .{ "AccountContactRoles", "AccountContactRole" },
            .{ "OpportunityContactRoles", "OpportunityContactRole" },
            .{ "CampaignMemberStatuses", "CampaignMemberStatus" },
            .{ "CampaignMembers", "CampaignMember" },
            // Self-referencing standard relationships (Parent/Owner hierarchy).
            .{ "ChildAccounts", "Account" },
            .{ "ParentAccounts", "Account" },
            .{ "ChildOpportunities", "Opportunity" },
            .{ "ChildCases", "Case" },
            .{ "Assets", "Asset" },
            .{ "AssetContactRoles", "AssetContactRole" },
            .{ "Orders", "Order" },
            .{ "Quotes", "Quote" },
            .{ "Contracts", "Contract" },
        };
        inline for (mappings) |m| {
            if (std.ascii.eqlIgnoreCase(relationship, m[0])) return m[1];
        }
        // Try removing trailing 'es' (statuses → status, boxes → box)
        if (relationship.len > 2 and std.ascii.endsWithIgnoreCase(relationship, "es")) {
            const candidate = relationship[0 .. relationship.len - 2];
            // Only accept if candidate ends in 's' (statuses), 'x', 'sh', 'ch'
            if (std.ascii.endsWithIgnoreCase(candidate, "s") or
                std.ascii.endsWithIgnoreCase(candidate, "x") or
                std.ascii.endsWithIgnoreCase(candidate, "sh") or
                std.ascii.endsWithIgnoreCase(candidate, "ch"))
            {
                return candidate;
            }
        }
        // Try removing trailing 's' for standard plural
        if (relationship.len > 1 and relationship[relationship.len - 1] == 's') {
            return relationship[0 .. relationship.len - 1];
        }
        return null;
    }

    /// Resolve the foreign key field name from child to parent.
    /// e.g., Contact to Account → "AccountId"
    fn resolve_foreign_key(
        self: *Evaluator,
        child_type: []const u8,
        parent_type: []const u8,
        relationship: []const u8,
    ) []const u8 {
        if (self.resolve_custom_child_relationship(parent_type, relationship)) |custom| {
            if (std.ascii.eqlIgnoreCase(custom.child_type, child_type)) return custom.fk_field;
        }
        if (std.ascii.eqlIgnoreCase(parent_type, "Data_Import_Object_Mapping__mdt") and
            std.ascii.eqlIgnoreCase(child_type, "Data_Import_Field_Mapping__mdt") and
            std.ascii.eqlIgnoreCase(relationship, "Data_Import_Field_Mappings__r"))
        {
            return "Target_Object_Mapping__c";
        }
        // Self-referencing hierarchy relationships use ParentId regardless of
        // the logical parent type name.
        const hierarchy_rels = .{
            "ChildAccounts",
            "ChildOpportunities",
            "ChildCases",
            "ParentAccounts",
        };
        inline for (hierarchy_rels) |r| {
            if (std.ascii.eqlIgnoreCase(relationship, r)) return "ParentId";
        }
        // Standard convention: ParentType + "Id"
        const common_fks = .{
            .{ "Account", "AccountId" },
            .{ "Contact", "ContactId" },
            .{ "Opportunity", "OpportunityId" },
            .{ "Case", "CaseId" },
            .{ "Lead", "LeadId" },
            .{ "User", "OwnerId" },
            .{ "Campaign", "CampaignId" },
        };
        inline for (common_fks) |m| {
            if (std.ascii.eqlIgnoreCase(parent_type, m[0])) return m[1];
        }
        // Default: use parent_type + "Id" convention
        return std.fmt.allocPrint(self.arena, "{s}Id", .{parent_type}) catch "ParentId";
    }

    fn resolve_custom_child_relationship(
        self: *Evaluator,
        parent_type: []const u8,
        relationship: []const u8,
    ) ?CustomChildRelationship {
        const key = self.make_child_relationship_key(parent_type, relationship) catch return null;
        return self.child_relationships.get(key);
    }

    fn make_child_relationship_key(
        self: *Evaluator,
        parent_type: []const u8,
        relationship: []const u8,
    ) ![]const u8 {
        const raw = try std.fmt.allocPrint(self.arena, "{s}|{s}", .{ parent_type, relationship });
        const lowered = try self.arena.alloc(u8, raw.len);
        _ = std.ascii.lowerString(lowered, raw);
        return lowered;
    }

    /// Apply parent field lookups like Account.Name, parent__r.Name to query results.
    fn apply_parent_field_lookups(
        self: *Evaluator,
        soql: []const u8,
        from_type: []const u8,
        records: *std.ArrayListUnmanaged(Value),
    ) !void {
        const select_clause = extract_parent_fields(soql) orelse return;

        // Find fields like Account.Name, Account.ShippingState, parent__r.Name,
        // and also multi-level chains such as Account.Parent.Parent.Name.
        var iter = std.mem.splitScalar(u8, select_clause, ',');
        while (iter.next()) |field_part| {
            const trimmed = std.mem.trim(u8, field_part, " \t\n\r");
            // Skip sub-queries (start with '(')
            if (trimmed.len > 0 and trimmed[0] == '(') continue;
            // Skip non-dotted fields
            if (std.mem.indexOfScalar(u8, trimmed, '.') == null) continue;

            for (records.items) |*rec| {
                if (rec.* != .sobject) continue;
                try self.hydrate_parent_chain(rec.sobject, from_type, trimmed);
            }
        }
    }

    /// Walk a dotted SELECT path like `Account.Parent.Parent.Name` and
    /// materialize each intermediate SObject on `host`, copying the final
    /// leaf value across at the end.  Handles arbitrary-depth parent chains
    /// including self-referencing hierarchies.
    fn hydrate_parent_chain(
        self: *Evaluator,
        host: *types.SObject,
        host_type: []const u8,
        path: []const u8,
    ) !void {
        var remaining = path;
        var current_sob: *types.SObject = host;
        var current_type: []const u8 = host_type;
        while (std.mem.indexOfScalar(u8, remaining, '.')) |dot_pos| {
            const parent_ref = remaining[0..dot_pos];
            const rest = remaining[dot_pos + 1 ..];
            const fk_field = self.parent_ref_to_fk(parent_ref);
            const parent_type_opt = self.parent_ref_to_type_for_s_object(current_type, parent_ref);
            const fk_val_opt = utils.sobject_get(&current_sob.fields, fk_field);
            if (parent_type_opt == null or fk_val_opt == null) return;
            if (fk_val_opt.? != .string) return;
            const parent_type = parent_type_opt.?;
            const parent_rec = self.find_parent_relationship_record(
                current_type,
                parent_ref,
                parent_type,
                fk_val_opt.?.string,
            ) orelse return;
            if (parent_rec != .sobject) return;

            const parent_sob = try self.ensure_parent_relationship_sobject(
                current_sob,
                parent_ref,
                parent_type,
            );

            // Always copy the parent's Id so subsequent deep lookups can
            // consume it through the same fk_field convention.
            if (parent_rec.sobject.id) |pid| {
                parent_sob.id = pid;
                try parent_sob.fields.put(self.arena, "Id", Value{ .string = pid });
            }

            // If this is the last segment's parent, copy the leaf field value.
            if (std.mem.indexOfScalar(u8, rest, '.') == null) {
                if (self.get_s_object_field_value_case_insensitive(
                    parent_rec.sobject,
                    rest,
                )) |field_val| {
                    try parent_sob.fields.put(self.arena, rest, field_val);
                }
                return;
            }

            // Otherwise mirror across the parent's own FK fields so the
            // next iteration can chase them.  Copy any FK fields we might
            // need (identified by looking ahead at the next segment's FK).
            const next_dot = std.mem.indexOfScalar(u8, rest, '.').?;
            const next_parent_ref = rest[0..next_dot];
            const next_fk = self.parent_ref_to_fk(next_parent_ref);
            if (self.get_s_object_field_value_case_insensitive(
                parent_rec.sobject,
                next_fk,
            )) |nfk_val| {
                try parent_sob.fields.put(self.arena, next_fk, nfk_val);
            }

            current_sob = parent_sob;
            current_type = parent_type;
            remaining = rest;
        }
    }

    fn ensure_parent_relationship_sobject(
        self: *Evaluator,
        current_sob: *types.SObject,
        parent_ref: []const u8,
        parent_type: []const u8,
    ) !*types.SObject {
        if (utils.sobject_get(&current_sob.fields, parent_ref)) |existing| {
            if (existing == .sobject) return existing.sobject;
        }
        const parent_sob = try self.arena.create(types.SObject);
        parent_sob.* = .{ .type_name = parent_type };
        try current_sob.fields.put(
            self.arena,
            parent_ref,
            Value{ .sobject = parent_sob },
        );
        return parent_sob;
    }

    fn find_parent_relationship_record(
        self: *Evaluator,
        current_type: []const u8,
        parent_ref: []const u8,
        parent_type: []const u8,
        fk_value: []const u8,
    ) ?Value {
        if (self.find_record_by_id(parent_type, fk_value)) |record| return record;
        if (std.mem.endsWith(u8, current_type, "__mdt")) {
            if (self.find_custom_metadata_record_by_developer_name(
                parent_type,
                fk_value,
            )) |record| return record;
            if (self.known_custom_metadata_parent_type(current_type, parent_ref)) |known_type| {
                if (self.find_custom_metadata_record_by_developer_name(
                    known_type,
                    fk_value,
                )) |record| return record;
            }
        }
        return null;
    }

    /// SOQL SELECT 内の数式フィールド（<Relationship>_<Field>__c）を FK 経由で親から解決する。
    /// 例: Experience_Name__c → Experience__c FK → 親の Name
    fn resolve_formula_fields(
        self: *Evaluator,
        soql: []const u8,
        records: *std.ArrayListUnmanaged(Value),
    ) !void {
        const select_clause = extract_parent_fields(soql) orelse return;
        var iter = std.mem.splitScalar(u8, select_clause, ',');
        while (iter.next()) |field_part| {
            const trimmed = std.mem.trim(u8, field_part, " \t\n\r");
            // Skip dotted fields (already handled) and sub-queries
            if (std.mem.indexOf(u8, trimmed, ".") != null) continue;
            if (trimmed.len > 0 and trimmed[0] == '(') continue;
            // Pattern: <Prefix>_<Suffix>__c where <Prefix>__c is a FK and
            // <Suffix> is a parent field.
            // e.g. Experience_Name__c → FK=Experience__c, parent field=Name
            if (!std.mem.endsWith(u8, trimmed, "__c")) continue;
            const base = trimmed[0 .. trimmed.len - 3]; // strip __c
            // Find underscore separator (last one before __c)
            const sep_pos = std.mem.lastIndexOfScalar(u8, base, '_') orelse continue;
            if (sep_pos == 0) continue;
            const parent_prefix = base[0..sep_pos]; // "Experience"
            const field_suffix = base[sep_pos + 1 ..]; // "Name"
            // Construct FK field: Experience__c
            const fk_field = try std.fmt.allocPrint(self.arena, "{s}__c", .{parent_prefix});

            for (records.items) |*rec| {
                if (rec.* != .sobject) continue;
                // Skip if field already has a non-null value
                if (utils.sobject_get(&rec.sobject.fields, trimmed)) |existing| {
                    if (existing != .null_val) continue;
                }
                // Look up FK
                const fk_val = utils.sobject_get(&rec.sobject.fields, fk_field) orelse continue;
                if (fk_val != .string) continue;
                // Find parent type
                const parent_type = self.find_record_type_by_id(fk_val.string) orelse continue;
                // Find parent record
                const parent_rec =
                    self.find_record_by_id(parent_type, fk_val.string) orelse continue;
                if (parent_rec != .sobject) continue;
                // Copy the field from parent
                if (utils.sobject_get(&parent_rec.sobject.fields, field_suffix)) |val| {
                    try rec.sobject.fields.put(self.arena, trimmed, val);
                }
            }
        }
    }

    /// Convert a parent reference to FK field name.
    /// Account → AccountId, parent__r → parent__c
    fn parent_ref_to_fk(self: *Evaluator, ref: []const u8) []const u8 {
        // Custom relationship: ends with __r → change to __c
        if (ref.len > 3 and std.ascii.eqlIgnoreCase(ref[ref.len - 3 ..], "__r")) {
            // Replace __r with __c
            const fk =
                std.fmt.allocPrint(self.arena, "{s}__c", .{ref[0 .. ref.len - 3]}) catch return ref;
            return fk;
        }
        // Standard: Account → AccountId
        const common = .{
            .{ "Account", "AccountId" },
            .{ "Contact", "ContactId" },
            .{ "Opportunity", "OpportunityId" },
            .{ "Case", "CaseId" },
            .{ "Lead", "LeadId" },
            .{ "Owner", "OwnerId" },
            .{ "CreatedBy", "CreatedById" },
            .{ "LastModifiedBy", "LastModifiedById" },
            .{ "Parent", "ParentId" },
            .{ "Profile", "ProfileId" },
            .{ "UserRole", "UserRoleId" },
            .{ "UserLicense", "UserLicenseId" },
        };
        inline for (common) |m| {
            if (std.ascii.eqlIgnoreCase(ref, m[0])) return m[1];
        }
        return ref;
    }

    /// Convert a FK field name back to its relationship name.
    /// AccountId → Account, parent__c → parent__r
    fn fk_to_parent_ref(self: *Evaluator, fk_field: []const u8) []const u8 {
        if (fk_field.len > 3 and std.ascii.eqlIgnoreCase(fk_field[fk_field.len - 3 ..], "__c")) {
            const rel = std.fmt.allocPrint(
                self.arena,
                "{s}__r",
                .{fk_field[0 .. fk_field.len - 3]},
            ) catch return fk_field;
            return rel;
        }
        const common = .{
            .{ "AccountId", "Account" },
            .{ "ContactId", "Contact" },
            .{ "OpportunityId", "Opportunity" },
            .{ "CaseId", "Case" },
            .{ "LeadId", "Lead" },
            .{ "OwnerId", "Owner" },
            .{ "CreatedById", "CreatedBy" },
            .{ "LastModifiedById", "LastModifiedBy" },
            .{ "ParentId", "Parent" },
            .{ "ProfileId", "Profile" },
            .{ "UserRoleId", "UserRole" },
            .{ "UserLicenseId", "UserLicense" },
        };
        inline for (common) |m| {
            if (std.ascii.eqlIgnoreCase(fk_field, m[0])) return m[1];
        }
        return fk_field;
    }

    /// Convert a parent reference to SObject type name.
    /// Account → Account, parent__r → look up FK value's type in store
    fn parent_ref_to_type(self: *Evaluator, ref: []const u8) ?[]const u8 {
        // Custom relationship: parent1__r → parent1__c is the FK field
        // We need to find what type the FK points to
        if (ref.len > 3 and std.ascii.eqlIgnoreCase(ref[ref.len - 3 ..], "__r")) {
            const fk_field = self.parent_ref_to_fk(ref);
            // Search for the FK value in any record and look up the target type
            var store_iter = self.store.iterator();
            while (store_iter.next()) |entry| {
                for (entry.value_ptr.items) |record| {
                    if (record == .sobject) {
                        if (utils.sobject_get(&record.sobject.fields, fk_field)) |fk_val| {
                            if (fk_val == .string) {
                                // Find which type has a record with this Id
                                if (self.find_record_type_by_id(fk_val.string)) |found_type| {
                                    return found_type;
                                }
                            }
                        }
                    }
                }
            }
            return null;
        }
        // Standard relationship → SObject type mapping
        if (std.ascii.eqlIgnoreCase(ref, "Owner") or
            std.ascii.eqlIgnoreCase(ref, "CreatedBy") or
            std.ascii.eqlIgnoreCase(ref, "LastModifiedBy"))
        {
            return "User";
        }
        return ref;
    }

    fn parent_ref_to_type_for_s_object(
        self: *Evaluator,
        object_type: []const u8,
        ref: []const u8,
    ) ?[]const u8 {
        if (self.known_custom_metadata_parent_type(object_type, ref)) |target| return target;
        const fk_field = self.parent_ref_to_fk(ref);
        if (self.get_field_metadata(object_type, fk_field)) |meta| {
            if (meta.reference_to) |target_type| return target_type;
        }
        // Self-referencing "Parent" lookup: on Account, Parent → Account; on
        // Case, Parent → Case; etc.  Only Account / Case / Opportunity have a
        // ParentId field at the platform level.
        if (std.ascii.eqlIgnoreCase(ref, "Parent")) {
            if (std.ascii.eqlIgnoreCase(object_type, "Account") or
                std.ascii.eqlIgnoreCase(object_type, "Case") or
                std.ascii.eqlIgnoreCase(object_type, "Opportunity") or
                std.ascii.eqlIgnoreCase(object_type, "Contact"))
            {
                return object_type;
            }
        }
        return self.parent_ref_to_type(ref);
    }

    fn known_custom_metadata_parent_type(
        self: *Evaluator,
        object_type: []const u8,
        ref: []const u8,
    ) ?[]const u8 {
        _ = self;
        if (!std.mem.endsWith(u8, object_type, "__mdt")) return null;
        const mappings = .{
            .{
                "Data_Import_Field_Mapping_Set__mdt",
                "Data_Import_Object_Mapping_Set__r",
                "Data_Import_Object_Mapping_Set__mdt",
            },
            .{
                "Data_Import_Object_Mapping__mdt",
                "Data_Import_Object_Mapping_Set__r",
                "Data_Import_Object_Mapping_Set__mdt",
            },
            .{
                "Data_Import_Field_Mapping__mdt",
                "Data_Import_Field_Mapping_Set__r",
                "Data_Import_Field_Mapping_Set__mdt",
            },
            .{
                "Data_Import_Field_Mapping__mdt",
                "Target_Object_Mapping__r",
                "Data_Import_Object_Mapping__mdt",
            },
        };
        inline for (mappings) |mapping| {
            if (std.ascii.eqlIgnoreCase(object_type, mapping[0]) and
                std.ascii.eqlIgnoreCase(ref, mapping[1]))
            {
                return mapping[2];
            }
        }
        return null;
    }

    /// Find a record by Id in the store.
    fn find_record_by_id(self: *Evaluator, type_name: []const u8, id: []const u8) ?Value {
        var store_iter = self.store.iterator();
        while (store_iter.next()) |entry| {
            if (std.ascii.eqlIgnoreCase(entry.key_ptr.*, type_name)) {
                for (entry.value_ptr.items) |record| {
                    if (record == .sobject) {
                        if (record.sobject.id) |rec_id| {
                            if (std.ascii.eqlIgnoreCase(rec_id, id)) return record;
                        }
                    }
                }
                return null;
            }
        }
        // Fallback: for User type, return synthetic user if id matches UserInfo.getUserId()
        if (std.ascii.eqlIgnoreCase(type_name, "User") and
            std.ascii.eqlIgnoreCase(id, self.current_user_id))
        {
            return self.create_current_user_record() catch null;
        }
        return null;
    }

    fn find_custom_metadata_record_by_developer_name(
        self: *Evaluator,
        type_name: []const u8,
        developer_name: []const u8,
    ) ?Value {
        if (!std.mem.endsWith(u8, type_name, "__mdt")) return null;
        self.ensure_custom_metadata_loaded(type_name);
        var store_iter = self.store.iterator();
        while (store_iter.next()) |entry| {
            if (!std.ascii.eqlIgnoreCase(entry.key_ptr.*, type_name)) continue;
            for (entry.value_ptr.items) |record| {
                if (record != .sobject) continue;
                if (utils.sobject_get(&record.sobject.fields, "DeveloperName")) |value| {
                    if (value == .string and
                        std.ascii.eqlIgnoreCase(value.string, developer_name))
                    {
                        return record;
                    }
                }
            }
        }
        return null;
    }

    pub fn relationship_records_value(_: *Evaluator, value: Value) ?Value {
        return switch (value) {
            .object => |obj| blk: {
                if (obj.fields.get("records")) |records| {
                    if (records == .list) break :blk records;
                }
                break :blk null;
            },
            .sobject => |sob| blk: {
                if (utils.sobject_get(&sob.fields, "records")) |records| {
                    if (records == .list) break :blk records;
                }
                break :blk null;
            },
            .map => |map| blk: {
                for (map.entries.keys(), map.entries.values()) |k, records| {
                    if (std.ascii.eqlIgnoreCase(k, "records") and records == .list) {
                        break :blk records;
                    }
                }
                break :blk null;
            },
            else => null,
        };
    }

    fn normalize_parsed_json_s_object_field(
        self: *Evaluator,
        sob: *types.SObject,
        field_name: []const u8,
        value: Value,
    ) Value {
        var bctx = builtins.BuiltinContext{
            .arena = self.arena,
            .stdout = &self.stdout,
            .pending_exception = &self.pending_exception,
            .see_all_data = self.see_all_data,
            .eval = self,
        };
        return builtins.normalize_s_object_field_assignment(
            &bctx,
            sob,
            field_name,
            value,
        ) catch value;
    }

    fn find_visible_enum_decl(self: *Evaluator, enum_name: []const u8) ?*ast.EnumDecl {
        const scope = self.current_class orelse "";
        var key_buf: [512]u8 = undefined;
        if (std.fmt.bufPrint(&key_buf, "{s}|{s}", .{ scope, enum_name })) |key| {
            if (self.visible_enum_decl_cache.get(key)) |cached| return cached;
            const resolved = self.find_visible_enum_decl_uncached(enum_name);
            const owned_key = self.arena.dupe(u8, key) catch return resolved;
            self.visible_enum_decl_cache.put(self.arena, owned_key, resolved) catch {};
            return resolved;
        } else |_| {}
        return self.find_visible_enum_decl_uncached(enum_name);
    }

    fn find_visible_enum_decl_uncached(self: *Evaluator, enum_name: []const u8) ?*ast.EnumDecl {
        const Search = struct {
            fn in_class(cd: *ast.ClassDecl, target: []const u8) ?*ast.EnumDecl {
                for (cd.members) |member| {
                    switch (member) {
                        .enum_decl => |ed| {
                            if (std.ascii.eqlIgnoreCase(ed.name, target)) return ed;
                        },
                        else => {},
                    }
                }
                return null;
            }
        };

        if (self.current_class) |class_name| {
            if (self.find_class(class_name)) |cd| {
                if (Search.in_class(cd, enum_name)) |ed| return ed;
            }
            if (self.find_outer_class_name(class_name)) |outer_name| {
                if (self.find_class(outer_name)) |outer_cd| {
                    if (Search.in_class(outer_cd, enum_name)) |ed| return ed;
                }
            }
        }

        var class_iter = self.classes.iterator();
        while (class_iter.next()) |entry| {
            if (std.mem.indexOfScalar(u8, entry.key_ptr.*, '.') != null) continue;
            if (Search.in_class(entry.value_ptr.*, enum_name)) |ed| return ed;
        }
        return null;
    }

    pub fn get_s_object_field_value_case_insensitive(
        self: *Evaluator,
        sob: *types.SObject,
        field_name: []const u8,
    ) ?Value {
        var matched_value: ?Value = null;
        for (sob.fields.keys(), sob.fields.values()) |k, v| {
            if (std.ascii.eqlIgnoreCase(k, field_name)) {
                matched_value = v;
                break;
            }
        }
        if (matched_value) |value| {
            if (value != .null_val) {
                if (value == .string) {
                    var bctx = builtins.BuiltinContext{
                        .arena = self.arena,
                        .stdout = &self.stdout,
                        .pending_exception = &self.pending_exception,
                        .see_all_data = self.see_all_data,
                        .eval = self,
                    };
                    const display_type =
                        builtins.get_s_object_field_display_type(&bctx, sob, field_name);
                    if (std.ascii.eqlIgnoreCase(display_type, "DATETIME")) {
                        return builtins.make_datetime_value(self.arena, value.string) catch value;
                    }
                    if (std.ascii.eqlIgnoreCase(display_type, "DATE")) {
                        const date_str = if (value.string.len >= 10)
                            value.string[0..10]
                        else
                            value.string;
                        return builtins.make_date_value(self.arena, date_str) catch value;
                    }
                }
                if (self.relationship_records_value(value)) |records| return records;
                return value;
            }
        }
        if (self.resolve_derived_field_value(sob, field_name)) |derived| return derived;
        if (self.resolve_custom_child_relationship(sob.type_name, field_name) != null or
            (field_name.len > 3 and
                std.ascii.eqlIgnoreCase(field_name[field_name.len - 3 ..], "__r") and
                self.resolve_custom_child_relationship(
                    sob.type_name,
                    field_name[0 .. field_name.len - 3],
                ) != null))
        {
            return self.make_empty_list() catch matched_value;
        }
        return matched_value;
    }

    fn resolve_field_path_value(
        self: *Evaluator,
        sob: *types.SObject,
        field_path: []const u8,
    ) ?Value {
        var current = sob;
        var remaining = field_path;
        while (true) {
            const dot_pos = std.mem.indexOfScalar(u8, remaining, '.') orelse {
                return self.get_s_object_field_value_case_insensitive(current, remaining);
            };
            const segment = remaining[0..dot_pos];
            remaining = remaining[dot_pos + 1 ..];

            if (self.get_s_object_field_value_case_insensitive(current, segment)) |segment_val| {
                if (segment_val == .sobject) {
                    current = segment_val.sobject;
                    continue;
                }
                return null;
            }

            const fk_field = self.parent_ref_to_fk(segment);
            const fk_val = utils.sobject_get(&current.fields, fk_field) orelse return null;
            if (fk_val != .string) return null;

            const parent_type =
                self.parent_ref_to_type_for_s_object(
                    current.type_name,
                    segment,
                ) orelse
                self.find_record_type_by_id(fk_val.string) orelse
                blk: {
                    if (fk_val.string.len < 3) break :blk null;
                    const inferred = sobject_type_from_prefix(fk_val.string[0..3]);
                    if (std.ascii.eqlIgnoreCase(inferred, "SObject")) break :blk null;
                    break :blk inferred;
                } orelse return null;

            const parent_record =
                self.find_record_by_id(parent_type, fk_val.string) orelse return null;
            if (parent_record != .sobject) return null;
            current = parent_record.sobject;
        }
    }

    fn resolve_derived_field_value(
        self: *Evaluator,
        sob: *types.SObject,
        field_name: []const u8,
    ) ?Value {
        const metadata = self.get_field_metadata(sob.type_name, field_name) orelse return null;
        if (metadata.summary_operation != null) {
            if (self.compute_summary_field_value(sob, metadata)) |value| return value;
        }
        if (metadata.formula != null) {
            if (self.compute_formula_field_value(sob, metadata)) |value| return value;
        }
        return null;
    }

    fn collect_summary_impact_ids_from_records(
        self: *Evaluator,
        impacted_ids: *std.StringArrayHashMapUnmanaged(void),
        records: []const Value,
        fk_field: []const u8,
    ) !void {
        for (records) |record| {
            if (record != .sobject) continue;
            const fk_val =
                self.get_s_object_field_value_case_insensitive(
                    record.sobject,
                    fk_field,
                ) orelse continue;
            if (fk_val != .string or fk_val.string.len == 0) continue;
            try impacted_ids.put(self.arena, fk_val.string, {});
        }
    }

    fn apply_rollup_summary_side_effects(
        self: *Evaluator,
        child_type: []const u8,
        new_records: []const Value,
        old_records: ?std.ArrayListUnmanaged(Value),
    ) !void {
        var parent_iter = self.field_metadata.iterator();
        while (parent_iter.next()) |parent_entry| {
            const parent_type = parent_entry.key_ptr.*;
            const type_meta = parent_entry.value_ptr.*;

            var impacted_ids: std.StringArrayHashMapUnmanaged(void) = .empty;
            var has_matching_rollups = false;

            var field_iter = type_meta.iterator();
            while (field_iter.next()) |field_entry| {
                const metadata = field_entry.value_ptr.*;
                const summary_fk = metadata.summary_foreign_key orelse continue;
                const dot_idx = std.mem.indexOfScalar(u8, summary_fk, '.') orelse continue;
                if (!std.ascii.eqlIgnoreCase(summary_fk[0..dot_idx], child_type)) continue;

                has_matching_rollups = true;
                const fk_field = summary_fk[dot_idx + 1 ..];
                try self.collect_summary_impact_ids_from_records(
                    &impacted_ids,
                    new_records,
                    fk_field,
                );
                if (old_records) |previous_records| {
                    try self.collect_summary_impact_ids_from_records(
                        &impacted_ids,
                        previous_records.items,
                        fk_field,
                    );
                }
            }

            if (!has_matching_rollups or impacted_ids.count() == 0) continue;

            try self.flush_parent_rollup_updates(
                parent_type,
                child_type,
                type_meta,
                impacted_ids,
                new_records,
                old_records,
            );
        }
    }

    /// `apply_rollup_summary_side_effects` から抽出した helper。親レコードの
    /// rollup summary フィールドを再計算し、差分があれば DML update を発行する。
    fn flush_parent_rollup_updates(
        self: *Evaluator,
        parent_type: []const u8,
        child_type: []const u8,
        type_meta: anytype,
        impacted_ids: std.StringArrayHashMapUnmanaged(void),
        new_records: []const Value,
        old_records: ?std.ArrayListUnmanaged(Value),
    ) !void {
        const parent_updates = try self.arena.create(types.ListValue);
        parent_updates.* = .{};
        var parent_old_records: std.ArrayListUnmanaged(Value) = .empty;

        var impacted_iter = impacted_ids.iterator();
        while (impacted_iter.next()) |impacted_entry| {
            const parent_id = impacted_entry.key_ptr.*;
            const parent_record = self.find_record_by_id(parent_type, parent_id) orelse continue;
            if (parent_record != .sobject) continue;

            const updated_parent = try self.clone_s_object(parent_record.sobject);
            const old_parent = try self.clone_s_object(parent_record.sobject);
            var changed = false;

            var summary_iter = type_meta.iterator();
            while (summary_iter.next()) |summary_entry| {
                const field_name = summary_entry.key_ptr.*;
                const metadata = summary_entry.value_ptr.*;
                const summary_fk = metadata.summary_foreign_key orelse continue;
                const dot_idx = std.mem.indexOfScalar(u8, summary_fk, '.') orelse continue;
                if (!std.ascii.eqlIgnoreCase(summary_fk[0..dot_idx], child_type)) continue;

                const new_value =
                    self.compute_summary_field_value(updated_parent, metadata) orelse
                    Value.null_val;
                const old_value =
                    self.compute_summary_field_value_before_delta(
                        parent_record.sobject,
                        metadata,
                        new_records,
                        old_records,
                    ) orelse Value.null_val;
                try old_parent.fields.put(self.arena, field_name, old_value);
                try updated_parent.fields.put(self.arena, field_name, new_value);
                if (utils.value_eql(old_value, new_value)) continue;

                changed = true;
            }

            if (!changed) continue;
            try parent_updates.items.append(self.arena, Value{ .sobject = updated_parent });
            try parent_old_records.append(self.arena, Value{ .sobject = old_parent });
        }

        if (parent_updates.items.items.len > 0) {
            try self.execute_dml_with_external_id_internal(
                .update,
                Value{ .list = parent_updates },
                null,
                false,
                parent_old_records,
            );
        }
    }

    fn normalize_summary_field_path(
        _: *Evaluator,
        child_type: []const u8,
        field_path: []const u8,
    ) []const u8 {
        if (std.mem.startsWith(u8, field_path, child_type) and
            field_path.len > child_type.len and
            field_path[child_type.len] == '.')
        {
            return field_path[child_type.len + 1 ..];
        }
        return field_path;
    }

    fn summary_filter_matches(
        self: *Evaluator,
        child: *types.SObject,
        child_type: []const u8,
        filter: SummaryFilter,
    ) bool {
        const field_path = self.normalize_summary_field_path(child_type, filter.field_path);
        const field_val = if (std.mem.indexOfScalar(u8, field_path, '.')) |_|
            self.resolve_field_path_value(child, field_path)
        else
            self.get_s_object_field_value_case_insensitive(child, field_path);
        if (field_val == null) return false;

        if (std.ascii.eqlIgnoreCase(filter.operation, "equals")) {
            return switch (field_val.?) {
                .string => std.ascii.eqlIgnoreCase(field_val.?.string, filter.value),
                .integer => blk: {
                    const expected = std.fmt.parseInt(i64, filter.value, 10) catch break :blk false;
                    break :blk field_val.?.integer == expected;
                },
                .double => blk: {
                    const expected = std.fmt.parseFloat(f64, filter.value) catch break :blk false;
                    break :blk field_val.?.double == expected;
                },
                .boolean => if (std.ascii.eqlIgnoreCase(filter.value, "true"))
                    field_val.?.boolean
                else if (std.ascii.eqlIgnoreCase(filter.value, "false"))
                    !field_val.?.boolean
                else
                    false,
                .null_val => std.ascii.eqlIgnoreCase(filter.value, "null"),
                else => {
                    const actual = utils.coerce_to_string(
                        field_val.?,
                        self.arena,
                    ) catch return false;
                    return std.ascii.eqlIgnoreCase(actual, filter.value);
                },
            };
        }

        if (std.ascii.eqlIgnoreCase(filter.operation, "notEqual")) {
            return !self.summary_filter_matches(child, child_type, .{
                .field_path = filter.field_path,
                .operation = "equals",
                .value = filter.value,
            });
        }

        return false;
    }

    fn find_s_object_by_id_in_values(
        _: *Evaluator,
        records: []const Value,
        id: []const u8,
    ) ?*types.SObject {
        for (records) |record| {
            if (record != .sobject or record.sobject.id == null) continue;
            if (std.mem.eql(u8, record.sobject.id.?, id)) return record.sobject;
        }
        return null;
    }

    fn summary_record_matches(
        self: *Evaluator,
        child: *types.SObject,
        child_type: []const u8,
        fk_field: []const u8,
        parent_id: []const u8,
        metadata: FieldMetadata,
    ) bool {
        const fk_val =
            self.get_s_object_field_value_case_insensitive(child, fk_field) orelse
            return false;
        if (fk_val != .string or !std.ascii.eqlIgnoreCase(fk_val.string, parent_id)) return false;

        for (metadata.summary_filters) |filter| {
            if (!self.summary_filter_matches(child, child_type, filter)) return false;
        }
        return true;
    }

    fn accumulate_summary_value(
        self: *Evaluator,
        child: *types.SObject,
        child_type: []const u8,
        metadata: FieldMetadata,
        count: *i64,
        aggregate: *?Value,
    ) void {
        const summary_operation = metadata.summary_operation orelse return;
        if (std.ascii.eqlIgnoreCase(summary_operation, "count")) {
            count.* += 1;
            return;
        }

        const summarized_field = if (metadata.summarized_field) |field_path|
            self.normalize_summary_field_path(child_type, field_path)
        else
            "";
        if (summarized_field.len == 0) return;

        const child_value = blk: {
            if (std.mem.indexOfScalar(u8, summarized_field, '.')) |_| {
                break :blk self.resolve_field_path_value(
                    child,
                    summarized_field,
                ) orelse Value.null_val;
            }
            break :blk self.get_s_object_field_value_case_insensitive(
                child,
                summarized_field,
            ) orelse Value.null_val;
        };
        if (child_value == .null_val) return;

        if (aggregate.* == null) {
            aggregate.* = child_value;
            return;
        }

        const cmp = self.compare_values(aggregate.*.?, child_value);
        if (std.ascii.eqlIgnoreCase(summary_operation, "min")) {
            if (cmp > 0) aggregate.* = child_value;
        } else if (std.ascii.eqlIgnoreCase(summary_operation, "max")) {
            if (cmp < 0) aggregate.* = child_value;
        }
    }

    fn compute_summary_field_value_before_delta(
        self: *Evaluator,
        sob: *types.SObject,
        metadata: FieldMetadata,
        new_records: []const Value,
        old_records: ?std.ArrayListUnmanaged(Value),
    ) ?Value {
        const summary_operation = metadata.summary_operation orelse return null;
        const summary_fk = metadata.summary_foreign_key orelse return null;
        const dot_idx = std.mem.indexOfScalar(u8, summary_fk, '.') orelse return null;
        const child_type = summary_fk[0..dot_idx];
        const fk_field = summary_fk[dot_idx + 1 ..];

        const parent_id = self.summary_parent_id(sob);
        if (parent_id == null) return self.empty_summary_value(summary_operation);

        const child_records = self.store.get(child_type) orelse {
            return self.empty_summary_value(summary_operation);
        };

        var count: i64 = 0;
        var aggregate: ?Value = null;

        for (child_records.items) |record| {
            if (record != .sobject or record.sobject.id == null) continue;
            const record_id = record.sobject.id.?;

            if (old_records) |previous_records| {
                if (self.accumulate_previous_summary_record(
                    previous_records.items,
                    record_id,
                    child_type,
                    fk_field,
                    parent_id.?,
                    metadata,
                    &count,
                    &aggregate,
                )) {
                    continue;
                }
            }

            self.accumulate_current_summary_record_before_delta(
                record.sobject,
                new_records,
                record_id,
                child_type,
                fk_field,
                parent_id.?,
                metadata,
                &count,
                &aggregate,
            );
        }

        if (old_records) |previous_records| {
            self.accumulate_deleted_summary_records(
                previous_records.items,
                child_type,
                fk_field,
                parent_id.?,
                metadata,
                &count,
                &aggregate,
            );
        }

        if (std.ascii.eqlIgnoreCase(summary_operation, "count")) return Value{ .integer = count };
        return aggregate orelse Value.null_val;
    }

    fn summary_parent_id(_: *Evaluator, sob: *types.SObject) ?[]const u8 {
        return sob.id orelse blk: {
            if (utils.sobject_get(&sob.fields, "Id")) |id_val| {
                if (id_val == .string) break :blk id_val.string;
            }
            break :blk null;
        };
    }

    fn empty_summary_value(_: *Evaluator, summary_operation: []const u8) Value {
        if (std.ascii.eqlIgnoreCase(summary_operation, "count")) {
            return Value{ .integer = 0 };
        }
        return Value.null_val;
    }

    fn accumulate_previous_summary_record(
        self: *Evaluator,
        previous_records: []const Value,
        record_id: []const u8,
        child_type: []const u8,
        fk_field: []const u8,
        parent_id: []const u8,
        metadata: FieldMetadata,
        count: *i64,
        aggregate: *?Value,
    ) bool {
        const old_child =
            self.find_s_object_by_id_in_values(previous_records, record_id) orelse
            return false;
        if (self.summary_record_matches(
            old_child,
            child_type,
            fk_field,
            parent_id,
            metadata,
        )) {
            self.accumulate_summary_value(
                old_child,
                child_type,
                metadata,
                count,
                aggregate,
            );
        }
        return true;
    }

    fn accumulate_current_summary_record_before_delta(
        self: *Evaluator,
        record: *types.SObject,
        new_records: []const Value,
        record_id: []const u8,
        child_type: []const u8,
        fk_field: []const u8,
        parent_id: []const u8,
        metadata: FieldMetadata,
        count: *i64,
        aggregate: *?Value,
    ) void {
        const inserted_now =
            self.find_s_object_by_id_in_values(new_records, record_id) != null;
        if (inserted_now) return;
        if (self.summary_record_matches(
            record,
            child_type,
            fk_field,
            parent_id,
            metadata,
        )) {
            self.accumulate_summary_value(
                record,
                child_type,
                metadata,
                count,
                aggregate,
            );
        }
    }

    fn accumulate_deleted_summary_records(
        self: *Evaluator,
        previous_records: []const Value,
        child_type: []const u8,
        fk_field: []const u8,
        parent_id: []const u8,
        metadata: FieldMetadata,
        count: *i64,
        aggregate: *?Value,
    ) void {
        for (previous_records) |record| {
            if (record != .sobject or record.sobject.id == null) continue;
            if (self.find_record_in_store(child_type, record.sobject.id.?)) |_| continue;
            if (self.summary_record_matches(
                record.sobject,
                child_type,
                fk_field,
                parent_id,
                metadata,
            )) {
                self.accumulate_summary_value(
                    record.sobject,
                    child_type,
                    metadata,
                    count,
                    aggregate,
                );
            }
        }
    }

    fn compute_summary_field_value(
        self: *Evaluator,
        sob: *types.SObject,
        metadata: FieldMetadata,
    ) ?Value {
        const summary_operation = metadata.summary_operation orelse return null;
        const summary_fk = metadata.summary_foreign_key orelse return null;
        const dot_idx = std.mem.indexOfScalar(u8, summary_fk, '.') orelse return null;
        const child_type = summary_fk[0..dot_idx];
        const fk_field = summary_fk[dot_idx + 1 ..];

        const parent_id = self.summary_parent_id(sob);

        if (parent_id == null) {
            return self.empty_summary_value(summary_operation);
        }

        const child_records = self.store.get(child_type) orelse {
            return self.empty_summary_value(summary_operation);
        };

        var count: i64 = 0;
        var aggregate: ?Value = null;

        for (child_records.items) |record| {
            if (record != .sobject) continue;
            if (!self.summary_record_matches(
                record.sobject,
                child_type,
                fk_field,
                parent_id.?,
                metadata,
            )) continue;
            self.accumulate_summary_value(record.sobject, child_type, metadata, &count, &aggregate);
        }

        if (std.ascii.eqlIgnoreCase(summary_operation, "count")) return Value{ .integer = count };
        return aggregate orelse Value.null_val;
    }

    fn compute_formula_field_value(
        self: *Evaluator,
        sob: *types.SObject,
        metadata: FieldMetadata,
    ) ?Value {
        const formula = metadata.formula orelse return null;
        const trimmed = std.mem.trim(u8, formula, " \t\n\r");
        if (trimmed.len == 0) return null;

        if (std.mem.indexOfScalar(u8, trimmed, '+')) |_| {
            var total: i64 = 0;
            var term_iter = std.mem.splitScalar(u8, trimmed, '+');
            while (term_iter.next()) |raw_term| {
                const term = std.mem.trim(u8, raw_term, " \t\n\r()");
                if (term.len == 0) continue;
                const term_value =
                    self.get_s_object_field_value_case_insensitive(
                        sob,
                        term,
                    ) orelse Value.null_val;
                switch (term_value) {
                    .integer => |i| total += i,
                    .double => |d| total += @intFromFloat(d),
                    .null_val => {
                        if (!metadata.formula_blank_as_zero) return Value.null_val;
                    },
                    else => return Value.null_val,
                }
            }
            return Value{ .integer = total };
        }

        if (std.mem.indexOfScalar(u8, trimmed, '.')) |_| {
            return self.resolve_field_path_value(sob, trimmed);
        }

        if (std.ascii.indexOfIgnoreCase(trimmed, "!= null")) |idx| {
            const lhs = std.mem.trim(u8, trimmed[0..idx], " \t\n\r");
            const lhs_value =
                self.get_s_object_field_value_case_insensitive(
                    sob,
                    lhs,
                ) orelse Value.null_val;
            return Value{ .boolean = lhs_value != .null_val };
        }

        if (std.ascii.indexOfIgnoreCase(trimmed, "== null")) |idx| {
            const lhs = std.mem.trim(u8, trimmed[0..idx], " \t\n\r");
            const lhs_value =
                self.get_s_object_field_value_case_insensitive(
                    sob,
                    lhs,
                ) orelse Value.null_val;
            return Value{ .boolean = lhs_value == .null_val };
        }

        return self.get_s_object_field_value_case_insensitive(sob, trimmed);
    }

    /// Create a shallow clone of an SObject (copies the fields map).
    fn clone_s_object(self: *Evaluator, src: *types.SObject) !*types.SObject {
        const copy = try self.arena.create(types.SObject);
        copy.* = .{ .type_name = src.type_name, .id = src.id };
        for (src.fields.keys(), src.fields.values()) |k, v| {
            try copy.fields.put(self.arena, k, v);
        }
        return copy;
    }

    fn default_custom_setting_record(
        self: *Evaluator,
        class_name: []const u8,
        setup_owner_id: ?[]const u8,
    ) !Value {
        const sob = try self.arena.create(types.SObject);
        sob.* = .{ .type_name = class_name };
        if (self.field_defaults.get(class_name)) |defaults| {
            for (defaults.keys(), defaults.values()) |fk, fv| {
                try sob.fields.put(self.arena, fk, fv);
            }
        }
        if (setup_owner_id) |owner_id| {
            try sob.fields.put(self.arena, "SetupOwnerId", Value{ .string = owner_id });
        }
        return Value{ .sobject = sob };
    }

    fn put_default_sobject_field(
        self: *Evaluator,
        sob: *types.SObject,
        field_name: []const u8,
        value: Value,
    ) !void {
        if (utils.sobject_get(&sob.fields, field_name)) |existing| {
            if (existing != .null_val) return;
        }
        try sob.fields.put(self.arena, field_name, value);
    }

    fn clone_custom_setting_record(
        self: *Evaluator,
        record: *types.SObject,
        setup_owner_id: ?[]const u8,
        clear_id: bool,
    ) !Value {
        const copy = try self.clone_s_object(record);
        if (clear_id) {
            copy.id = null;
            try copy.fields.put(self.arena, "Id", Value.null_val);
        }
        if (setup_owner_id) |owner_id| {
            try copy.fields.put(self.arena, "SetupOwnerId", Value{ .string = owner_id });
        }
        return Value{ .sobject = copy };
    }

    fn find_custom_setting_record(
        self: *Evaluator,
        class_name: []const u8,
        owner_id: []const u8,
    ) ?*types.SObject {
        var cs_iter = self.store.iterator();
        while (cs_iter.next()) |entry| {
            if (!std.ascii.eqlIgnoreCase(entry.key_ptr.*, class_name)) continue;
            for (entry.value_ptr.items) |item| {
                if (item != .sobject) continue;
                if (utils.sobject_get(&item.sobject.fields, "SetupOwnerId")) |stored_owner| {
                    if (stored_owner == .string and
                        std.ascii.eqlIgnoreCase(stored_owner.string, owner_id))
                    {
                        return item.sobject;
                    }
                }
            }
        }
        return null;
    }

    fn first_custom_setting_record(self: *Evaluator, class_name: []const u8) ?*types.SObject {
        var cs_iter = self.store.iterator();
        while (cs_iter.next()) |entry| {
            if (!std.ascii.eqlIgnoreCase(entry.key_ptr.*, class_name)) continue;
            for (entry.value_ptr.items) |item| {
                if (item == .sobject) return item.sobject;
            }
        }
        return null;
    }

    fn list_custom_setting_record_key(record: *types.SObject) ?[]const u8 {
        if (utils.sobject_get(&record.fields, "Name")) |name| {
            if (name == .string and name.string.len > 0) return name.string;
        }
        if (utils.sobject_get(&record.fields, "DeveloperName")) |dev_name| {
            if (dev_name == .string and dev_name.string.len > 0) return dev_name.string;
        }
        return record.id;
    }

    fn find_list_custom_setting_record(
        self: *Evaluator,
        class_name: []const u8,
        name: []const u8,
    ) ?*types.SObject {
        var cs_iter = self.store.iterator();
        while (cs_iter.next()) |entry| {
            if (!std.ascii.eqlIgnoreCase(entry.key_ptr.*, class_name)) continue;
            for (entry.value_ptr.items) |item| {
                if (item != .sobject) continue;
                const key = list_custom_setting_record_key(item.sobject) orelse continue;
                if (std.ascii.eqlIgnoreCase(key, name)) return item.sobject;
            }
        }
        return null;
    }

    fn list_custom_setting_get_all(self: *Evaluator, class_name: []const u8) !Value {
        const map = try self.arena.create(types.MapValue);
        map.* = .{};
        var cs_iter = self.store.iterator();
        while (cs_iter.next()) |entry| {
            if (!std.ascii.eqlIgnoreCase(entry.key_ptr.*, class_name)) continue;
            for (entry.value_ptr.items) |item| {
                if (item != .sobject) continue;
                const key = list_custom_setting_record_key(item.sobject) orelse continue;
                try map.entries.put(
                    self.arena,
                    key,
                    try self.clone_custom_setting_record(item.sobject, null, false),
                );
            }
        }
        return Value{ .map = map };
    }

    fn custom_setting_kind(self: *Evaluator, class_name: []const u8) ?[]const u8 {
        if (self.custom_setting_kinds.get(class_name)) |kind| return kind;
        if (self.custom_setting_types.get(class_name) != null) return "Hierarchy";
        return null;
    }

    fn resolve_bare_static_value(self: *Evaluator, current_env: *Env, name: []const u8) ?Value {
        if (current_env.get_this()) |this_val| {
            if (this_val == .object) {
                const this_cn = this_val.object.class_name;
                if (self.resolve_static_field_value_on_class(this_cn, name)) |val| return val;
                if (self.find_class(this_cn)) |cd| {
                    if (cd.super_class) |sc| {
                        if (self.resolve_static_field_value_on_class(sc.name, name)) |val| {
                            return val;
                        }
                    }
                }
                if (self.resolve_outer_static_field(this_cn, name)) |val| return val;
            }
        }

        if (self.current_class) |cc| {
            if (self.resolve_static_field_value_on_class(cc, name)) |val| return val;
            if (self.find_class(cc)) |cd| {
                if (cd.super_class) |sc| {
                    if (self.resolve_static_field_value_on_class(sc.name, name)) |val| return val;
                }
            }
            if (self.resolve_outer_static_field(cc, name)) |val| return val;
        }

        return null;
    }

    fn handle_custom_setting_static_method(
        self: *Evaluator,
        class_name: []const u8,
        method_name: []const u8,
        args: []const Value,
    ) !?Value {
        if (!std.mem.endsWith(u8, class_name, "__c")) return null;

        const kind = self.custom_setting_kind(class_name);
        const is_hierarchy = kind != null and std.ascii.eqlIgnoreCase(kind.?, "Hierarchy");

        if (std.ascii.eqlIgnoreCase(method_name, "getOrgDefaults")) {
            return try self.custom_setting_get_org_defaults(class_name, is_hierarchy);
        }

        if (std.ascii.eqlIgnoreCase(method_name, "getInstance")) {
            if (is_hierarchy) {
                return try self.hierarchy_custom_setting_get_instance(class_name, args);
            }

            return try self.handle_list_custom_setting_static_method(
                class_name,
                method_name,
                args,
            );
        }

        if (!is_hierarchy) {
            return try self.handle_list_custom_setting_static_method(
                class_name,
                method_name,
                args,
            );
        }

        if (std.ascii.eqlIgnoreCase(method_name, "getValues") and
            args.len > 0 and
            args[0] == .string)
        {
            if (self.find_custom_setting_record(class_name, args[0].string)) |found| {
                return try self.clone_custom_setting_record(found, null, false);
            }
            return Value.null_val;
        }

        return null;
    }

    fn custom_setting_get_org_defaults(
        self: *Evaluator,
        class_name: []const u8,
        is_hierarchy: bool,
    ) !Value {
        if (is_hierarchy) {
            if (self.find_custom_setting_record(class_name, "00D000000000001")) |record| {
                return try self.clone_custom_setting_record(record, null, false);
            }
            return try self.default_custom_setting_record(class_name, "00D000000000001");
        }
        if (self.first_custom_setting_record(class_name)) |record| {
            return try self.clone_custom_setting_record(record, null, false);
        }
        return try self.default_custom_setting_record(class_name, null);
    }

    fn hierarchy_custom_setting_get_instance(
        self: *Evaluator,
        class_name: []const u8,
        args: []const Value,
    ) !Value {
        const owner_id = if (args.len > 0 and args[0] == .string and args[0].string.len > 0)
            args[0].string
        else
            self.current_user_id;
        const profile_id = self.current_profile_id;
        const org_id = "00D000000000001";

        if (self.find_custom_setting_record(class_name, owner_id)) |user_record| {
            return try self.clone_custom_setting_record(user_record, owner_id, false);
        }
        if (self.find_custom_setting_record(class_name, profile_id)) |profile_record| {
            return try self.clone_custom_setting_record(profile_record, owner_id, true);
        }
        if (self.find_custom_setting_record(class_name, org_id)) |org_defaults| {
            return try self.clone_custom_setting_record(org_defaults, owner_id, true);
        }
        return try self.default_custom_setting_record(class_name, owner_id);
    }

    fn handle_list_custom_setting_static_method(
        self: *Evaluator,
        class_name: []const u8,
        method_name: []const u8,
        args: []const Value,
    ) !?Value {
        if (std.ascii.eqlIgnoreCase(method_name, "getAll")) {
            return try self.list_custom_setting_get_all(class_name);
        }
        if (std.ascii.eqlIgnoreCase(method_name, "getInstance")) {
            if (args.len > 0 and args[0] == .string) {
                if (self.find_list_custom_setting_record(class_name, args[0].string)) |record| {
                    return try self.clone_custom_setting_record(record, null, false);
                }
                return Value.null_val;
            }
            if (self.first_custom_setting_record(class_name)) |record| {
                return try self.clone_custom_setting_record(record, null, false);
            }
            return try self.default_custom_setting_record(class_name, null);
        }
        if (std.ascii.eqlIgnoreCase(method_name, "getValues") and
            args.len > 0 and
            args[0] == .string)
        {
            if (self.find_list_custom_setting_record(class_name, args[0].string)) |record| {
                return try self.clone_custom_setting_record(record, null, false);
            }
            return Value.null_val;
        }
        return null;
    }

    /// Find the type name of a record by its Id, searching all types in store.
    fn find_record_type_by_id(self: *Evaluator, id: []const u8) ?[]const u8 {
        var store_iter = self.store.iterator();
        while (store_iter.next()) |entry| {
            for (entry.value_ptr.items) |record| {
                if (record == .sobject) {
                    if (record.sobject.id) |rec_id| {
                        if (std.ascii.eqlIgnoreCase(rec_id, id)) return entry.key_ptr.*;
                    }
                }
            }
        }
        return null;
    }

    // -----------------------------------------------------------------------
    // 式の評価
    // -----------------------------------------------------------------------

    pub fn eval_expr(self: *Evaluator, expr: *const ast.Expr, current_env: *Env) anyerror!Value {
        self.call_depth +|= 1;
        defer self.call_depth -|= 1;

        if (self.call_depth > self.max_call_depth) {
            // error を返すと error return trace の記録でスタックを消費し
            // OS スタックオーバーフローを引き起こす場合があるため null を返す
            return .null_val;
        }
        return switch (expr.*) {
            .integer_literal => |v| .{ .integer = v },
            .long_literal => |v| .{ .long = v },
            .double_literal => |v| .{ .double = v },
            .string_literal => |v| .{ .string = v },
            .boolean_literal => |v| .{ .boolean = v },
            .null_literal => .null_val,
            .this_expr, .super_expr => current_env.get_this() orelse .null_val,
            .identifier => |id| self.eval_identifier_expr(id, current_env),
            .binary => |bin| self.eval_binary_expr(bin, current_env),
            .unary => |un| self.eval_unary_expr(un, current_env),
            .assignment => |asgn| self.eval_assignment_expr(asgn, current_env),
            .call => |call| self.eval_call_expr(call, current_env),
            .method_call => |mc| self.eval_method_call(mc, current_env),
            .field_access => |fa| self.eval_field_access_expr(fa, current_env),
            .index_access => |ia| self.eval_index_access_expr(ia, current_env),
            .new_expr => |ne| self.eval_new_expr_with_trace(ne, current_env),
            .cast_expr => |ce| self.eval_cast_expr(ce, current_env),
            .ternary => |te| self.eval_ternary_expr(te, current_env),
            .instanceof => |ie| self.eval_instanceof_expr(ie, current_env),
            .soql => |sq| self.execute_soql(sq.raw, current_env),
            .grouped => |inner| self.eval_expr(inner, current_env),
        };
    }

    fn eval_identifier_expr(self: *Evaluator, id: anytype, current_env: *Env) anyerror!Value {
        if (self.eval_identifier_env_or_instance_value(id.name, current_env)) |value| return value;
        if (self.eval_identifier_enum_value(id.name)) |value| return value;
        if (try self.eval_schema_identifier_value(id.name)) |value| return value;
        if (try self.eval_identifier_property_value(id.name, current_env)) |value| return value;
        if (self.eval_identifier_static_value(id.name, current_env)) |value| return value;
        if (self.eval_identifier_inner_type_value(id.name, current_env)) |value| return value;
        return .null_val;
    }

    fn eval_identifier_env_or_instance_value(
        self: *Evaluator,
        id_name: []const u8,
        current_env: *Env,
    ) ?Value {
        if (current_env.get(id_name)) |val| {
            if (val != .null_val) return val;
        }
        if (current_env.get_this()) |this_live| {
            if (this_live == .object) {
                if (utils.sobject_get(&this_live.object.fields, id_name)) |live| {
                    if (live != .null_val) {
                        if (self.find_class(this_live.object.class_name)) |live_cd| {
                            if (self.is_instance_field(live_cd, id_name) or
                                self.is_parent_instance_field(live_cd, id_name))
                            {
                                if (current_env.get_declared_type(id_name) == null) {
                                    return live;
                                }
                            }
                        }
                    }
                }
            }
        }
        return null;
    }

    fn eval_identifier_enum_value(self: *Evaluator, id_name: []const u8) ?Value {
        const dot_idx = std.mem.lastIndexOfScalar(u8, id_name, '.') orelse return null;
        const owner_name = id_name[0..dot_idx];
        const value_name = id_name[dot_idx + 1 ..];
        if (value_name.len == 0) return null;

        if (self.find_visible_enum_decl(owner_name)) |ed| {
            for (ed.values) |value| {
                if (std.ascii.eqlIgnoreCase(value, value_name)) {
                    return Value{ .string = value_name };
                }
            }
        }
        if (std.mem.lastIndexOfScalar(u8, owner_name, '.')) |owner_dot| {
            const outer_name = owner_name[0..owner_dot];
            const enum_name = owner_name[owner_dot + 1 ..];
            if (self.find_class(outer_name)) |outer_cd| {
                if (find_enum_in_class_members(outer_cd, enum_name)) |ed| {
                    for (ed.values) |value| {
                        if (std.ascii.eqlIgnoreCase(value, value_name)) {
                            return Value{ .string = value_name };
                        }
                    }
                }
            }
        }
        return null;
    }

    fn eval_schema_identifier_value(self: *Evaluator, id_name: []const u8) !?Value {
        if (std.mem.startsWith(u8, id_name, "SObjectType.") and
            std.mem.indexOfScalar(u8, id_name["SObjectType.".len..], '.') == null)
        {
            return try self.make_schema_sobject_type_object(id_name["SObjectType.".len..]);
        }
        if (!std.mem.startsWith(u8, id_name, "Schema.")) return null;
        const suffix = id_name["Schema.".len..];
        const dot_idx = std.mem.lastIndexOfScalar(u8, suffix, '.') orelse return null;
        const owner_name = suffix[0..dot_idx];
        const member_name = suffix[dot_idx + 1 ..];
        if (std.ascii.eqlIgnoreCase(owner_name, "SObjectType")) {
            return try self.make_schema_sobject_type_object(member_name);
        }
        if (std.ascii.eqlIgnoreCase(member_name, "SObjectType")) {
            return try self.make_schema_sobject_type_object(owner_name);
        }
        if (!std.ascii.eqlIgnoreCase(member_name, "class")) {
            return try self.make_s_object_field_token(owner_name, member_name);
        }
        return null;
    }

    fn eval_identifier_property_value(
        self: *Evaluator,
        id_name: []const u8,
        current_env: *Env,
    ) anyerror!?Value {
        const this_check = current_env.get_this() orelse return null;
        if (this_check != .object) return null;
        const already_in_instance_getter = if (self.evaluating_getter) |eg|
            std.ascii.eqlIgnoreCase(eg, id_name) and
                self.evaluating_getter_instance == this_check.object
        else
            false;
        const shadowed_by_typed_local = current_env.get_declared_type(id_name) != null;
        if (!already_in_instance_getter and !shadowed_by_typed_local) {
            if (self.find_class(this_check.object.class_name)) |this_cd| {
                var scan_cd: ?*ast.ClassDecl = this_cd;
                while (scan_cd) |scd| {
                    for (scd.members) |m| {
                        switch (m) {
                            .field_decl => |pfd| {
                                if (std.ascii.eqlIgnoreCase(pfd.name, id_name) and
                                    pfd.getter_body != null)
                                {
                                    const this_expr_node = try self.arena.create(ast.Expr);
                                    this_expr_node.* = .this_expr;
                                    const fa_node = try self.arena.create(ast.FieldAccess);
                                    fa_node.* = .{
                                        .object = this_expr_node,
                                        .field = id_name,
                                        .null_safe = false,
                                    };
                                    const fa_expr = try self.arena.create(ast.Expr);
                                    fa_expr.* = .{ .field_access = fa_node };
                                    return try self.eval_expr(fa_expr, current_env);
                                }
                            },
                            else => {},
                        }
                    }
                    scan_cd = if (scd.super_class) |sc| self.find_class(sc.name) else null;
                }
            }
            return null;
        }
        if (!already_in_instance_getter) return null;
        if (self.find_field_decl_with_owner(this_check.object.class_name, id_name)) |lookup| {
            if (lookup.field_decl.modifiers.is_static) {
                return self.read_static_backing_value(lookup.owner_name, id_name);
            }
        }
        if (this_check.object.fields.get(id_name)) |fv| return fv;
        for (this_check.object.fields.keys(), this_check.object.fields.values()) |fk, fv| {
            if (std.ascii.eqlIgnoreCase(fk, id_name)) return fv;
        }
        return .null_val;
    }

    fn eval_identifier_static_value(
        self: *Evaluator,
        id_name: []const u8,
        current_env: *Env,
    ) ?Value {
        if (current_env.get_this()) |this_val| {
            if (this_val == .object) {
                const this_cn = this_val.object.class_name;
                const key =
                    std.fmt.allocPrint(
                        self.arena,
                        "{s}.{s}",
                        .{ this_cn, id_name },
                    ) catch return .null_val;
                if (self.global_env.get(key)) |val| return val;
                if (self.find_class(this_cn)) |cd| {
                    if (cd.super_class) |sc| {
                        self.ensure_static_init(sc.name);
                        const pkey =
                            std.fmt.allocPrint(
                                self.arena,
                                "{s}.{s}",
                                .{ sc.name, id_name },
                            ) catch return .null_val;
                        if (self.global_env.get(pkey)) |val| return val;
                    }
                }
                if (self.resolve_outer_static_field(this_cn, id_name)) |val| return val;
            }
        }
        if (self.current_class) |cc| {
            if (self.resolve_static_field_value_on_class(cc, id_name)) |val| return val;
            if (self.find_class(cc)) |cd| {
                if (cd.super_class) |sc| {
                    if (self.resolve_static_field_value_on_class(sc.name, id_name)) |val| {
                        return val;
                    }
                }
            }
            if (self.resolve_outer_static_field(cc, id_name)) |val| return val;
        }
        return null;
    }

    fn eval_identifier_inner_type_value(
        self: *Evaluator,
        id_name: []const u8,
        current_env: *Env,
    ) ?Value {
        const check_classes = [_]?[]const u8{
            if (current_env.get_this()) |tv|
                (if (tv == .object) tv.object.class_name else null)
            else
                null,
            self.current_class,
        };
        for (check_classes) |cc_opt| {
            var cur_class: ?[]const u8 = cc_opt;
            while (cur_class) |ccn| {
                if (self.find_class(ccn)) |ccd| {
                    for (ccd.members) |member| {
                        switch (member) {
                            .enum_decl => |ed| {
                                if (std.ascii.eqlIgnoreCase(ed.name, id_name)) {
                                    return Value{ .string = id_name };
                                }
                            },
                            .class_decl => |inner_cd| {
                                if (std.ascii.eqlIgnoreCase(inner_cd.name, id_name)) {
                                    return Value{ .string = id_name };
                                }
                            },
                            else => {},
                        }
                    }
                    cur_class = if (ccd.super_class) |sc| sc.name else null;
                } else break;
            }
            if (cc_opt) |ccn| {
                if (self.find_outer_class_name(ccn)) |outer_name| {
                    if (self.find_class(outer_name)) |outer_cd| {
                        for (outer_cd.members) |member| {
                            switch (member) {
                                .enum_decl => |ed| {
                                    if (std.ascii.eqlIgnoreCase(ed.name, id_name)) {
                                        return Value{ .string = id_name };
                                    }
                                },
                                .class_decl => |inner_cd| {
                                    if (std.ascii.eqlIgnoreCase(inner_cd.name, id_name)) {
                                        return Value{ .string = id_name };
                                    }
                                },
                                else => {},
                            }
                        }
                    }
                }
            }
        }
        return null;
    }

    fn eval_binary_expr(self: *Evaluator, bin: anytype, current_env: *Env) anyerror!Value {
        const left = try self.eval_expr(bin.left, current_env);
        switch (bin.op) {
            .and_op => {
                if (!(utils.coerce_to_bool(left) catch false)) {
                    return Value{ .boolean = false };
                }
            },
            .or_op => {
                if (utils.coerce_to_bool(left) catch false) {
                    return Value{ .boolean = true };
                }
            },
            else => {},
        }
        const right = try self.eval_expr(bin.right, current_env);
        return eval_binary(self, left, bin.op, right, self.arena);
    }

    fn eval_unary_expr(self: *Evaluator, un: anytype, current_env: *Env) anyerror!Value {
        const operand = try self.eval_expr(un.operand, current_env);
        return eval_unary(un.op, operand);
    }

    fn eval_assignment_expr(self: *Evaluator, asgn: anytype, current_env: *Env) anyerror!Value {
        const val = try self.eval_expr(asgn.value, current_env);
        if (asgn.is_postfix) {
            const original = self.eval_expr(asgn.target, current_env) catch Value.null_val;
            _ = try self.eval_assignment(asgn, val, current_env);
            return original;
        }
        return self.eval_assignment(asgn, val, current_env);
    }

    fn eval_call_expr(self: *Evaluator, call: anytype, current_env: *Env) anyerror!Value {
        if (call.loc.line > 0) {
            self.current_call_line = call.loc.line;
            if (self.call_stack.items.len > 0)
                self.call_stack.items[self.call_stack.items.len - 1].line = call.loc.line;
        }
        var args: std.ArrayListUnmanaged(Value) = .empty;
        var call_type_hints: std.ArrayListUnmanaged(?[]const u8) = .empty;
        for (call.args) |*arg| {
            var arg_value = try self.eval_expr(arg, current_env);
            arg_value = try self.maybe_coerce_schema_expr_value(arg, arg_value);
            try args.append(self.arena, arg_value);
            try call_type_hints.append(self.arena, self.extract_expr_type_hint(arg, current_env));
        }
        const prev_hints = self.cast_type_hints;
        self.cast_type_hints = call_type_hints.items;
        defer self.cast_type_hints = prev_hints;

        if (try self.eval_constructor_call_expr(call, args.items, current_env)) |result| {
            return result;
        }
        if (try self.eval_this_instance_call_expr(call, args.items, current_env)) |result| {
            return result;
        }
        if (try self.eval_dotted_static_call_expr(call.callee, args.items, current_env)) |result| {
            return result;
        }
        if (try self.eval_static_or_loaded_call_expr(call.callee, args.items)) |result| {
            return result;
        }
        if (current_env.get_this()) |this_val| {
            if (this_val == .object or this_val == .sobject or this_val == .string or
                this_val == .list or this_val == .map or this_val == .set)
            {
                return self.eval_instance_method(this_val, call.callee, args.items, current_env);
            }
        }
        return Value.null_val;
    }

    fn eval_constructor_call_expr(
        self: *Evaluator,
        call: anytype,
        args: []const Value,
        current_env: *Env,
    ) anyerror!?Value {
        if (std.mem.eql(u8, call.callee, "super")) {
            if (current_env.get_this()) |this_val| {
                if (this_val == .object) {
                    const ctor_class = if (self.current_constructor_class) |cc|
                        self.find_class(cc)
                    else
                        self.find_class(this_val.object.class_name);
                    if (ctor_class) |cd| {
                        if (cd.super_class) |sc| {
                            if (self.find_class(sc.name)) |parent_decl| {
                                try self.run_constructor(parent_decl, this_val.object, args);
                            }
                        }
                    }
                }
            }
            return Value.void_val;
        }
        if (!std.mem.eql(u8, call.callee, "this")) return null;
        if (current_env.get_this()) |this_val| {
            if (this_val == .object) {
                const ctor_class_name = if (self.current_constructor_class) |cc|
                    cc
                else
                    this_val.object.class_name;
                if (self.find_class(ctor_class_name)) |cd| {
                    try self.run_constructor(cd, this_val.object, args);
                }
            }
        }
        return Value.void_val;
    }

    fn eval_this_instance_call_expr(
        self: *Evaluator,
        call: anytype,
        args: []const Value,
        current_env: *Env,
    ) anyerror!?Value {
        const this_val = current_env.get_this() orelse return null;
        if (this_val != .object) return null;
        if (try self.eval_field_expression_matching_method(
            this_val,
            call.callee,
            args,
        )) |result| {
            return result;
        }
        const actual_decl: ?*ast.ClassDecl = self.find_class(this_val.object.class_name);
        const dispatch_decl = blk: {
            if (self.current_class) |current_class_name| {
                if (self.find_class(current_class_name)) |owner_decl| break :blk owner_decl;
            }
            break :blk actual_decl orelse return Value.null_val;
        };
        const md = self.find_method_in_hierarchy(actual_decl, dispatch_decl, call.callee, args.len);
        if (md == null) return null;
        var pre_fields: [16]Value = undefined;
        const field_keys = this_val.object.fields.keys();
        const n_snap = @min(field_keys.len, pre_fields.len);
        for (this_val.object.fields.values()[0..n_snap], 0..) |v, fi| {
            pre_fields[fi] = v;
        }
        const result = try self.call_instance_method(
            dispatch_decl,
            this_val.object,
            call.callee,
            args,
        );
        try self.sync_instance_call_fields(current_env, this_val.object, pre_fields[0..n_snap]);
        return result;
    }

    fn sync_instance_call_fields(
        self: *Evaluator,
        current_env: *Env,
        object: *types.ObjectInstance,
        pre_fields: []const Value,
    ) !void {
        for (object.fields.keys(), object.fields.values(), 0..) |fk, fv, fi| {
            if (fi < pre_fields.len) {
                const pre = pre_fields[fi];
                const changed = switch (fv) {
                    .null_val => pre != .null_val,
                    .string => |s| if (pre == .string)
                        s.ptr != pre.string.ptr or s.len != pre.string.len
                    else
                        true,
                    .integer => |i| if (pre == .integer) i != pre.integer else true,
                    .boolean => |b| if (pre == .boolean) b != pre.boolean else true,
                    else => true,
                };
                if (changed) current_env.set(fk, fv) catch {};
            } else {
                current_env.set(fk, fv) catch {};
            }
        }
        _ = self;
    }

    fn eval_dotted_static_call_expr(
        self: *Evaluator,
        callee: []const u8,
        args: []const Value,
        current_env: *Env,
    ) anyerror!?Value {
        const dot_idx = std.mem.lastIndexOfScalar(u8, callee, '.') orelse return null;
        const class_name = callee[0..dot_idx];
        const method_name = callee[dot_idx + 1 ..];
        if (class_name.len == 0 or method_name.len == 0) return null;
        if (std.ascii.eqlIgnoreCase(class_name, "Database")) {
            return try self.handle_database_method(method_name, args, current_env);
        }
        var builtin_ctx = self.make_builtin_context();
        if (try builtins.dispatch_static(&builtin_ctx, class_name, method_name, args)) |result| {
            return result;
        }
        if (try self.eval_identifier_custom_metadata_method(
            class_name,
            method_name,
            args,
        )) |result| {
            return result;
        }
        if (try self.handle_custom_setting_static_method(class_name, method_name, args)) |result| {
            return result;
        }
        if (self.find_class(class_name) != null) {
            return try self.call_method(class_name, method_name, args);
        }
        return null;
    }

    fn eval_static_or_loaded_call_expr(
        self: *Evaluator,
        callee: []const u8,
        args: []const Value,
    ) anyerror!?Value {
        if (self.current_lexical_method_class()) |lexical_class| {
            if (try self.eval_static_call_from_lexical_class(
                lexical_class,
                callee,
                args,
            )) |result| return result;
        }
        if (self.current_class) |cc| {
            if (self.find_class(cc)) |cd| {
                if (self.find_best_method_in_class_filtered(cd, callee, args, true) != null) {
                    return try self.call_method(cc, callee, args);
                }
            }
            if (self.resolve_outer_static_method_owner(cc, callee, args)) |outer_owner| {
                return try self.call_method(outer_owner, callee, args);
            }
        }
        var class_iter = self.classes.iterator();
        while (class_iter.next()) |entry| {
            if (self.find_best_method_in_class_filtered(
                entry.value_ptr.*,
                callee,
                args,
                true,
            ) != null) {
                return try self.call_method(entry.key_ptr.*, callee, args);
            }
        }
        return null;
    }

    fn current_lexical_method_class(self: *Evaluator) ?[]const u8 {
        if (self.call_stack.items.len == 0) return null;
        const frame = self.call_stack.items[self.call_stack.items.len - 1];
        return frame.class_name;
    }

    fn eval_static_call_from_lexical_class(
        self: *Evaluator,
        class_name: []const u8,
        callee: []const u8,
        args: []const Value,
    ) anyerror!?Value {
        if (self.find_class(class_name)) |cd| {
            if (self.find_best_method_in_class_filtered(cd, callee, args, true) != null) {
                return try self.call_method(class_name, callee, args);
            }
        }
        if (self.resolve_outer_static_method_owner(class_name, callee, args)) |outer_owner| {
            return try self.call_method(outer_owner, callee, args);
        }
        return null;
    }

    fn eval_field_access_expr(
        self: *Evaluator,
        fa: *ast.FieldAccess,
        current_env: *Env,
    ) anyerror!Value {
        if (self.field_access_is_enum_value(fa)) return Value{ .string = fa.field };
        if (try self.eval_schema_field_access_expr(fa)) |value| return value;
        if (try self.eval_nested_static_field_access_expr(fa)) |value| return value;
        if (try self.eval_null_safe_field_access_expr(fa, current_env)) |value| return value;
        const obj = try self.eval_expr(fa.object, current_env);
        return try self.eval_field_access(fa, obj, current_env);
    }

    fn eval_schema_field_access_expr(self: *Evaluator, fa: *ast.FieldAccess) !?Value {
        if (!(fa.object.* == .identifier and
            std.mem.startsWith(u8, fa.object.identifier.name, "Schema.")))
        {
            return null;
        }
        const schema_name = fa.object.identifier.name["Schema.".len..];
        if (is_known_schema_enum_type(schema_name)) {
            return Value{ .string = fa.field };
        }
        if (std.ascii.eqlIgnoreCase(schema_name, "SObjectType")) {
            return try self.make_schema_sobject_type_object(fa.field);
        }
        if (std.ascii.eqlIgnoreCase(fa.field, "SObjectType")) {
            return try self.make_schema_sobject_type_object(schema_name);
        }
        if (self.is_s_object_type_name(schema_name) and
            !std.ascii.eqlIgnoreCase(fa.field, "class"))
        {
            return try self.make_s_object_field_token(schema_name, fa.field);
        }
        return null;
    }

    fn eval_nested_static_field_access_expr(self: *Evaluator, fa: *ast.FieldAccess) !?Value {
        if (fa.object.* != .field_access) return null;
        const inner_fa = fa.object.field_access;
        if (inner_fa.object.* != .identifier) return null;
        const outer_name = inner_fa.object.identifier.name;
        const inner_name = inner_fa.field;
        self.ensure_static_init(outer_name);
        const inner_fq = try std.fmt.allocPrint(self.arena, "{s}.{s}", .{ outer_name, inner_name });
        self.ensure_static_init(inner_fq);
        const fq_key = try std.fmt.allocPrint(
            self.arena,
            "{s}.{s}.{s}",
            .{ outer_name, inner_name, fa.field },
        );
        if (self.global_env.get(fq_key)) |v| return v;
        if (self.find_class(outer_name)) |cd| {
            for (cd.members) |member| {
                switch (member) {
                    .enum_decl => |ed| {
                        if (std.ascii.eqlIgnoreCase(ed.name, inner_name)) {
                            return Value{ .string = fa.field };
                        }
                    },
                    else => {},
                }
            }
        }
        if (std.ascii.eqlIgnoreCase(outer_name, "System") and
            (std.ascii.eqlIgnoreCase(inner_name, "AccessType") or
                std.ascii.eqlIgnoreCase(inner_name, "AccessLevel") or
                std.ascii.eqlIgnoreCase(inner_name, "LoggingLevel") or
                std.ascii.eqlIgnoreCase(inner_name, "TriggerOperation")))
        {
            return Value{ .string = fa.field };
        }
        if (std.ascii.eqlIgnoreCase(outer_name, "Metadata") and
            is_known_metadata_enum_type(inner_name))
        {
            return Value{ .string = fa.field };
        }
        if (std.ascii.eqlIgnoreCase(outer_name, "Schema") and
            is_known_schema_enum_type(inner_name))
        {
            return Value{ .string = fa.field };
        }
        if (std.ascii.eqlIgnoreCase(outer_name, "Schema") and
            !std.ascii.eqlIgnoreCase(inner_name, "sObjectType") and
            !std.ascii.eqlIgnoreCase(inner_name, "SObjectType") and
            self.is_s_object_type_name(inner_name))
        {
            if (std.ascii.eqlIgnoreCase(fa.field, "SObjectType")) {
                return try self.make_schema_sobject_type_object(inner_name);
            }
            if (!std.ascii.eqlIgnoreCase(fa.field, "class")) {
                return try self.make_s_object_field_token(inner_name, fa.field);
            }
        }
        return null;
    }

    fn eval_null_safe_field_access_expr(
        self: *Evaluator,
        fa: *ast.FieldAccess,
        current_env: *Env,
    ) anyerror!?Value {
        if (!fa.null_safe) return null;
        const obj = self.eval_expr(fa.object, current_env) catch |err| {
            if (err == error.ApexException and self.pending_exception != null) {
                if (self.pending_exception.? == .object) {
                    const cn = self.pending_exception.?.object.class_name;
                    if (std.ascii.indexOfIgnoreCase(cn, "NullPointer") != null) {
                        self.pending_exception = null;
                        return Value.null_val;
                    }
                }
            }
            return err;
        };
        if (obj == .null_val) return Value.null_val;
        return try self.eval_field_access(fa, obj, current_env);
    }

    fn eval_index_access_expr(
        self: *Evaluator,
        ia: *ast.IndexAccess,
        current_env: *Env,
    ) anyerror!Value {
        const obj = try self.eval_expr(ia.object, current_env);
        const idx = try self.eval_expr(ia.index, current_env);
        if (obj == .list and idx == .integer) {
            if (idx.integer >= 0) {
                const i: usize = @intCast(idx.integer);
                if (i < obj.list.items.items.len) return obj.list.items.items[i];
            }
            const exc = try self.arena.create(types.ObjectInstance);
            exc.* = .{ .class_name = "ListException" };
            try exc.fields.put(
                self.arena,
                "message",
                Value{ .string = try std.fmt.allocPrint(
                    self.arena,
                    "List index out of bounds: {d}",
                    .{idx.integer},
                ) },
            );
            self.pending_exception = Value{ .object = exc };
            return error.ApexException;
        }
        if (obj == .map and idx == .string) {
            return obj.map.entries.get(idx.string) orelse Value.null_val;
        }
        return Value.null_val;
    }

    fn eval_new_expr_with_trace(
        self: *Evaluator,
        ne: *ast.NewExpr,
        current_env: *Env,
    ) anyerror!Value {
        if (ne.loc.line > 0) {
            self.current_call_line = ne.loc.line;
            if (self.call_stack.items.len > 0)
                self.call_stack.items[self.call_stack.items.len - 1].line = ne.loc.line;
        }
        const val = try self.eval_new_expr(ne, current_env);
        if (val == .object and std.mem.endsWith(u8, val.object.class_name, "Exception")) {
            if (val.object.fields.get("stackTraceString") == null) {
                const line = if (ne.loc.line > 0) ne.loc.line else 1;
                const trace = try self.build_stack_trace_string();
                try val.object.fields.put(self.arena, "stackTraceString", Value{ .string = trace });
                try val.object.fields.put(
                    self.arena,
                    "lineNumber",
                    Value{ .integer = @intCast(line) },
                );
            }
        }
        return val;
    }

    fn eval_cast_expr(self: *Evaluator, ce: anytype, current_env: *Env) anyerror!Value {
        const val = try self.eval_expr(ce.operand, current_env);
        if (val != .object) return val;
        return self.eval_object_cast_expr(val, ce.target_type.name);
    }

    fn raise_type_exception(
        self: *Evaluator,
        src_name: []const u8,
        target: []const u8,
    ) anyerror!Value {
        const msg = try std.fmt.allocPrint(
            self.arena,
            "Invalid conversion from runtime type {s} to {s}",
            .{ src_name, target },
        );
        const exc = try self.arena.create(types.ObjectInstance);
        exc.* = .{ .class_name = "System.TypeException" };
        try exc.fields.put(self.arena, "message", Value{ .string = msg });
        self.pending_exception = Value{ .object = exc };
        return error.ApexException;
    }

    fn eval_ternary_expr(self: *Evaluator, te: anytype, current_env: *Env) anyerror!Value {
        const cond = try self.eval_expr(te.condition, current_env);
        if (utils.coerce_to_bool(cond) catch false) {
            return self.eval_expr(te.then_expr, current_env);
        }
        return self.eval_expr(te.else_expr, current_env);
    }

    fn eval_object_cast_expr(self: *Evaluator, val: Value, target: []const u8) anyerror!Value {
        const src_name = val.object.class_name;
        if (try self.eval_temporal_object_cast(val, src_name, target)) |result| return result;
        if (std.ascii.eqlIgnoreCase(src_name, target)) return val;
        if (self.is_compatible_object_cast(src_name, target)) return val;
        if (self.is_known_interface_name(target)) {
            return self.raise_type_exception(src_name, target);
        }
        if (self.find_class(target)) |tgt_cd| {
            if (tgt_cd.modifiers.is_abstract and self.find_class(src_name) != null) {
                return self.raise_type_exception(src_name, target);
            }
        }
        return val;
    }

    fn eval_temporal_object_cast(
        self: *Evaluator,
        val: Value,
        src_name: []const u8,
        target: []const u8,
    ) anyerror!?Value {
        if (!std.ascii.eqlIgnoreCase(target, "DateTime") and
            !std.ascii.eqlIgnoreCase(target, "Date") and
            !std.ascii.eqlIgnoreCase(target, "Time"))
        {
            return null;
        }
        if (std.ascii.eqlIgnoreCase(src_name, "Date") and
            std.ascii.eqlIgnoreCase(target, "DateTime"))
        {
            if (val.object.fields.get("value")) |v| {
                if (v == .string) {
                    const dt_str = try std.fmt.allocPrint(self.arena, "{s}T00:00:00Z", .{v.string});
                    return try builtins.make_datetime_value(self.arena, dt_str);
                }
            }
            return val;
        }
        if (!std.ascii.eqlIgnoreCase(src_name, target)) {
            const normalized_target = if (std.ascii.eqlIgnoreCase(target, "DateTime"))
                "Datetime"
            else if (std.ascii.eqlIgnoreCase(target, "Date"))
                "Date"
            else if (std.ascii.eqlIgnoreCase(target, "Time"))
                "Time"
            else
                target;
            return try self.raise_type_exception(src_name, normalized_target);
        }
        return val;
    }

    fn is_compatible_object_cast(self: *Evaluator, src_name: []const u8, target: []const u8) bool {
        return self.object_cast_matches_source_hierarchy(src_name, target) or
            self.object_cast_matches_target_hierarchy(src_name, target);
    }

    fn object_cast_matches_source_hierarchy(
        self: *Evaluator,
        src_name: []const u8,
        target: []const u8,
    ) bool {
        const src_cd = self.find_class(src_name) orelse return false;
        var cur: ?*ast.ClassDecl = src_cd;
        while (cur) |cd| {
            if (std.ascii.eqlIgnoreCase(cd.name, target)) return true;
            for (cd.interfaces) |iface| {
                if (std.ascii.eqlIgnoreCase(iface.name, target)) return true;
                if (std.mem.lastIndexOfScalar(u8, target, '.')) |di| {
                    if (std.ascii.eqlIgnoreCase(iface.name, target[di + 1 ..])) return true;
                }
                if (std.mem.lastIndexOfScalar(u8, iface.name, '.')) |di| {
                    if (std.ascii.eqlIgnoreCase(iface.name[di + 1 ..], target)) return true;
                }
            }
            if (cd.super_class) |sc| {
                if (std.ascii.eqlIgnoreCase(sc.name, target)) return true;
                cur = self.find_class(sc.name);
            } else break;
        }
        return false;
    }

    fn object_cast_matches_target_hierarchy(
        self: *Evaluator,
        src_name: []const u8,
        target: []const u8,
    ) bool {
        const tgt_cd = self.find_class(target) orelse return false;
        var cur: ?*ast.ClassDecl = tgt_cd;
        while (cur) |cd| {
            if (std.ascii.eqlIgnoreCase(cd.name, src_name)) return true;
            if (cd.super_class) |sc| {
                if (std.ascii.eqlIgnoreCase(sc.name, src_name)) return true;
                cur = self.find_class(sc.name);
            } else break;
        }
        return false;
    }

    fn eval_instanceof_expr(self: *Evaluator, ie: anytype, current_env: *Env) anyerror!Value {
        const val = try self.eval_expr(ie.operand, current_env);
        if (instanceof_matches_primitive(val, ie.type_name.name)) {
            return Value{ .boolean = true };
        }
        if (val == .sobject) {
            if (std.ascii.eqlIgnoreCase(ie.type_name.name, "SObject") or
                std.ascii.eqlIgnoreCase(ie.type_name.name, "Sobject") or
                std.ascii.eqlIgnoreCase(ie.type_name.name, "sObject"))
            {
                return Value{ .boolean = true };
            }
            return Value{
                .boolean = std.ascii.eqlIgnoreCase(val.sobject.type_name, ie.type_name.name),
            };
        }
        if (val == .object) {
            return self.eval_object_instanceof_expr(val.object.class_name, ie.type_name.name);
        }
        if (val == .list) return self.eval_list_instanceof_expr(val.list, ie.type_name);
        if (val == .map) {
            return Value{ .boolean = std.ascii.eqlIgnoreCase(ie.type_name.name, "Map") };
        }
        if (val == .set) {
            const tn = ie.type_name.name;
            const tn_base = if (std.mem.lastIndexOfScalar(u8, tn, '.')) |di| tn[di + 1 ..] else tn;
            return Value{
                .boolean = std.ascii.eqlIgnoreCase(tn, "Set") or
                    std.ascii.eqlIgnoreCase(tn_base, "Iterable"),
            };
        }
        if (val == .string) {
            if (std.ascii.eqlIgnoreCase(ie.type_name.name, "String")) {
                return Value{ .boolean = true };
            }
            if (std.ascii.eqlIgnoreCase(ie.type_name.name, "Id")) {
                return Value{ .boolean = is_salesforce_id_string(val.string) };
            }
            return Value{ .boolean = false };
        }
        if (val == .integer or val == .long or val == .double) {
            return Value{ .boolean = instanceof_matches_primitive(val, ie.type_name.name) };
        }
        if (val == .boolean) {
            return Value{ .boolean = std.ascii.eqlIgnoreCase(ie.type_name.name, "Boolean") };
        }
        return Value{ .boolean = false };
    }

    fn eval_object_instanceof_expr(
        self: *Evaluator,
        class_name: []const u8,
        type_name: []const u8,
    ) Value {
        if (std.ascii.eqlIgnoreCase(class_name, type_name)) return Value{ .boolean = true };
        if (std.mem.lastIndexOfScalar(u8, type_name, '.')) |dot_pos| {
            if (std.ascii.eqlIgnoreCase(class_name, type_name[dot_pos + 1 ..])) {
                return Value{ .boolean = true };
            }
        }
        if (std.mem.lastIndexOfScalar(u8, class_name, '.')) |dot_pos| {
            if (std.ascii.eqlIgnoreCase(class_name[dot_pos + 1 ..], type_name)) {
                return Value{ .boolean = true };
            }
        }
        if (self.find_class(class_name)) |cd| {
            var cur: ?*ast.ClassDecl = cd;
            while (cur) |ccd| {
                for (ccd.interfaces) |iface| {
                    if (std.ascii.eqlIgnoreCase(iface.name, type_name)) {
                        return Value{ .boolean = true };
                    }
                    if (std.mem.lastIndexOfScalar(u8, iface.name, '.')) |dot_pos| {
                        if (std.ascii.eqlIgnoreCase(iface.name[dot_pos + 1 ..], type_name)) {
                            return Value{ .boolean = true };
                        }
                    }
                }
                if (ccd.super_class) |sc| {
                    if (std.ascii.eqlIgnoreCase(sc.name, type_name)) {
                        return Value{ .boolean = true };
                    }
                    cur = self.find_class(sc.name);
                } else break;
            }
        }
        if (std.mem.endsWith(u8, type_name, "Exception") and
            std.mem.endsWith(u8, class_name, "Exception"))
        {
            return Value{ .boolean = true };
        }
        return Value{ .boolean = false };
    }

    fn eval_list_instanceof_expr(
        self: *Evaluator,
        list: *types.ListValue,
        type_ref: types.TypeRef,
    ) Value {
        const tn = type_ref.name;
        const tn_base = blk: {
            if (std.mem.lastIndexOfScalar(u8, tn, '.')) |di| break :blk tn[di + 1 ..];
            break :blk tn;
        };
        const is_list_match = std.ascii.eqlIgnoreCase(tn, "List");
        const is_iter_match = std.ascii.eqlIgnoreCase(tn_base, "Iterable");
        if (!is_list_match and !is_iter_match) return Value{ .boolean = false };
        if (type_ref.params.len == 0) return Value{ .boolean = true };
        const elem_type = type_ref.params[0].name;
        if (std.ascii.eqlIgnoreCase(elem_type, "Object")) return Value{ .boolean = true };
        if (elem_type.len > 0 and elem_type.len <= 128) {
            for (list.items.items) |item| {
                if (item == .null_val) continue;
                if (instanceof_matches_primitive(item, elem_type)) return Value{ .boolean = true };
                if (item == .object and self.is_subclass_of(item.object.class_name, elem_type)) {
                    return Value{ .boolean = true };
                }
                return Value{ .boolean = false };
            }
        }
        return Value{ .boolean = true };
    }

    fn is_collection_type_name(type_name: []const u8) bool {
        const base = type_base_name(strip_type_namespace(type_name));
        return std.ascii.eqlIgnoreCase(base, "List") or
            std.ascii.eqlIgnoreCase(base, "Set") or
            std.ascii.eqlIgnoreCase(base, "Iterable") or
            std.ascii.eqlIgnoreCase(base, "Map");
    }

    fn strip_type_namespace(type_name: []const u8) []const u8 {
        if (std.ascii.startsWithIgnoreCase(type_name, "System.")) return type_name["System.".len..];
        if (std.ascii.startsWithIgnoreCase(type_name, "Schema.")) return type_name["Schema.".len..];
        return type_name;
    }

    fn extract_collection_element_type_name(type_name: []const u8) ?[]const u8 {
        const stripped = strip_type_namespace(type_name);
        if (std.ascii.startsWithIgnoreCase(stripped, "List<") or
            std.ascii.startsWithIgnoreCase(stripped, "Set<") or
            std.ascii.startsWithIgnoreCase(stripped, "Iterable<"))
        {
            const lt = std.mem.indexOfScalar(u8, stripped, '<') orelse return null;
            const gt = std.mem.lastIndexOfScalar(u8, stripped, '>') orelse return null;
            if (gt <= lt + 1) return null;
            return std.mem.trim(u8, stripped[lt + 1 .. gt], " \t");
        }
        if (std.mem.endsWith(u8, stripped, "[]")) return stripped[0 .. stripped.len - 2];
        return null;
    }

    fn extract_map_type_args(type_name: []const u8) ?struct { key: []const u8, value: []const u8 } {
        const stripped = strip_type_namespace(type_name);
        if (!std.ascii.startsWithIgnoreCase(stripped, "Map<")) return null;
        const lt = std.mem.indexOfScalar(u8, stripped, '<') orelse return null;
        const gt = std.mem.lastIndexOfScalar(u8, stripped, '>') orelse return null;
        if (gt <= lt + 1) return null;

        const inner = stripped[lt + 1 .. gt];
        var depth: usize = 0;
        for (inner, 0..) |ch, idx| {
            switch (ch) {
                '<' => depth += 1,
                '>' => {
                    if (depth > 0) depth -= 1;
                },
                ',' => if (depth == 0) {
                    return .{
                        .key = std.mem.trim(u8, inner[0..idx], " \t"),
                        .value = std.mem.trim(u8, inner[idx + 1 ..], " \t"),
                    };
                },
                else => {},
            }
        }
        return null;
    }

    fn annotate_declared_collection_type(
        self: *Evaluator,
        value: Value,
        declared_type: ?[]const u8,
    ) Value {
        if (declared_type) |type_name| {
            if (value == .list) {
                if (value.list.element_type == null) {
                    if (extract_collection_element_type_name(type_name)) |elem_type| {
                        value.list.element_type = strip_type_namespace(elem_type);
                    }
                }
            }
        }
        _ = self;
        return value;
    }

    fn names_match_by_simple_name(left: []const u8, right: []const u8) bool {
        if (std.ascii.eqlIgnoreCase(left, right)) return true;
        const left_simple = if (std.mem.lastIndexOfScalar(u8, left, '.')) |idx|
            left[idx + 1 ..]
        else
            left;
        const right_simple = if (std.mem.lastIndexOfScalar(u8, right, '.')) |idx|
            right[idx + 1 ..]
        else
            right;
        return std.ascii.eqlIgnoreCase(left_simple, right_simple);
    }

    fn infer_list_element_type(
        self: *Evaluator,
        list: *types.ListValue,
        arg_hint: ?[]const u8,
    ) ?[]const u8 {
        _ = self;
        if (list.element_type) |element_type| return strip_type_namespace(element_type);
        if (arg_hint) |hint| {
            if (extract_collection_element_type_name(hint)) |element_type| {
                return strip_type_namespace(element_type);
            }
        }
        if (list.items.items.len == 0) return null;

        return switch (list.items.items[0]) {
            .sobject => |sob| strip_type_namespace(sob.type_name),
            .object => |obj| strip_type_namespace(obj.class_name),
            .string => |s| if (Evaluator.is_salesforce_id_string(s)) "Id" else null,
            else => null,
        };
    }

    fn score_list_argument_for_param(
        self: *Evaluator,
        list: *types.ListValue,
        arg_hint: ?[]const u8,
        param_type: types.TypeRef,
    ) i32 {
        const param_base = type_base_name(param_type.name);
        if (!std.ascii.eqlIgnoreCase(param_base, "List") and
            !std.ascii.eqlIgnoreCase(param_base, "Iterable"))
        {
            return overload_score_for_arg(Value{ .list = list }, param_type.name);
        }
        if (param_type.params.len == 0) return 2;

        const param_elem_type = strip_type_namespace(self.render_type_ref(param_type.params[0]));
        const param_elem_base = type_base_name(param_elem_type);
        const actual_elem_type = self.infer_list_element_type(list, arg_hint);
        const actual_items_are_sobjects = blk: {
            if (list.items.items.len == 0) break :blk false;
            break :blk list.items.items[0] == .sobject;
        };
        if (actual_elem_type == null) return 2;

        const actual_elem_base = type_base_name(actual_elem_type.?);
        if (std.ascii.eqlIgnoreCase(param_elem_base, "SObject")) {
            if (actual_items_are_sobjects or
                std.ascii.eqlIgnoreCase(actual_elem_base, "SObject") or
                self.is_s_object_type_name(actual_elem_base))
            {
                return 3;
            }
            return 0;
        }
        if (names_match_by_simple_name(actual_elem_base, param_elem_base)) return 3;
        if (self.is_s_object_type_name(actual_elem_base) and
            self.is_s_object_type_name(param_elem_base) and
            self.is_subclass_of(actual_elem_base, param_elem_base))
        {
            return 2;
        }
        return 0;
    }

    fn type_base_name(type_name: []const u8) []const u8 {
        const stripped = strip_type_namespace(type_name);
        if (std.mem.indexOfScalar(u8, stripped, '<')) |lt| return stripped[0..lt];
        return stripped;
    }

    fn find_declared_field_type(
        self: *Evaluator,
        class_name: []const u8,
        field_name: []const u8,
    ) ?[]const u8 {
        if (self.find_class(class_name)) |cd| {
            var cur: ?*ast.ClassDecl = cd;
            while (cur) |ccd| {
                for (ccd.members) |member| {
                    switch (member) {
                        .field_decl => |fd| {
                            if (std.ascii.eqlIgnoreCase(fd.name, field_name)) {
                                return self.render_type_ref(fd.type_ref);
                            }
                        },
                        else => {},
                    }
                }
                cur = if (ccd.super_class) |sc| self.find_class(sc.name) else null;
            }
        }
        return null;
    }

    fn resolve_assignment_target_type(
        self: *Evaluator,
        target: *const ast.Expr,
        current_env: *Env,
    ) ?[]const u8 {
        switch (target.*) {
            .identifier => |id| {
                if (current_env.get_declared_type(id.name)) |type_name| return type_name;
                if (current_env.get_this()) |this_val| {
                    if (this_val == .object) {
                        if (self.find_declared_field_type(
                            this_val.object.class_name,
                            id.name,
                        )) |type_name| {
                            return type_name;
                        }
                    }
                }
                if (self.current_class) |cc| {
                    if (self.find_declared_field_type(cc, id.name)) |type_name| return type_name;
                    if (self.find_outer_class_name(cc)) |outer| {
                        if (self.find_declared_field_type(outer, id.name)) |type_name| {
                            return type_name;
                        }
                    }
                }
                return null;
            },
            .field_access => |fa| return self.resolve_field_access_assignment_target_type(
                fa,
                current_env,
            ),
            else => return null,
        }
    }

    fn resolve_field_access_assignment_target_type(
        self: *Evaluator,
        fa: *const ast.FieldAccess,
        current_env: *Env,
    ) ?[]const u8 {
        if (fa.object.* == .this_expr) {
            if (current_env.get_this()) |this_val| {
                if (this_val == .object) {
                    return self.find_declared_field_type(
                        this_val.object.class_name,
                        fa.field,
                    );
                }
            }
            return null;
        }
        if (fa.object.* == .identifier) {
            const owner_name = fa.object.identifier.name;
            if (current_env.get_declared_type(owner_name)) |owner_type| {
                if (self.find_declared_field_type(
                    type_base_name(owner_type),
                    fa.field,
                )) |type_name| {
                    return type_name;
                }
            }
            const is_class = self.find_class(owner_name) != null;
            const is_var = current_env.get(owner_name) != null;
            if (is_class and !is_var) {
                if (self.find_declared_field_type(owner_name, fa.field)) |type_name| {
                    return type_name;
                }
            }
        }
        if (self.resolve_assignment_target_type(fa.object, current_env)) |owner_type| {
            if (self.find_declared_field_type(
                type_base_name(owner_type),
                fa.field,
            )) |type_name| {
                return type_name;
            }
        }
        return null;
    }

    fn extract_expr_type_hint(
        self: *Evaluator,
        expr: *const ast.Expr,
        current_env: *Env,
    ) ?[]const u8 {
        switch (expr.*) {
            .cast_expr => |ce| return self.render_type_ref(ce.target_type),
            .new_expr => |ne| {
                // Only surface container-shape hints (Set<X>, List<X>, Map<K,V>) so that
                // generic-element overloads can disambiguate. For user types we rely on
                // the regular subclass-scoring pass in the ranker.
                const rendered = self.render_type_ref(ne.type_name);
                if (std.mem.indexOfScalar(u8, rendered, '<') != null) return rendered;
                return null;
            },
            .ternary => |te| {
                // `cond ? then : else` — if both branches have a compatible hint
                // (typically enum expressions like `flag ? MyEnum.A : MyEnum.B`),
                // surface it so overload resolution can prefer the enum-typed
                // parameter. If either branch lacks a hint or they disagree,
                // fall back to null so the regular Value-based scoring runs.
                const then_hint = self.extract_expr_type_hint(te.then_expr, current_env) orelse
                    self.enum_access_type_name(te.then_expr) orelse null;
                const else_hint = self.extract_expr_type_hint(te.else_expr, current_env) orelse
                    self.enum_access_type_name(te.else_expr) orelse null;
                if (then_hint != null and else_hint != null and
                    std.ascii.eqlIgnoreCase(then_hint.?, else_hint.?))
                {
                    return then_hint;
                }
                if (then_hint != null) return then_hint;
                if (else_hint != null) return else_hint;
                return null;
            },
            .identifier, .field_access => {
                if (self.resolve_assignment_target_type(expr, current_env)) |type_name| {
                    return strip_type_namespace(type_name);
                }
                // Fall back to enum detection for bare `MyEnum.VALUE` forms.
                return self.enum_access_type_name(expr);
            },
            .method_call => |mc| return self.method_call_return_type_hint(mc, current_env),
            else => return null,
        }
    }

    /// `extract_expr_type_hint` から抽出。メソッド呼び出し式の **戻り値型** を
    /// 推論する。`Foo.bar()` / `foo.bar()` / `Foo.Bar.baz()` の三形のみ扱う。
    fn method_call_return_type_hint(
        self: *Evaluator,
        mc: anytype,
        current_env: *Env,
    ) ?[]const u8 {
        const arg_count = mc.args.len;

        if (mc.object.* == .identifier) {
            const target_name = mc.object.identifier.name;
            if (self.find_class(target_name)) |class_decl| {
                if (self.find_method_in_hierarchy(
                    null,
                    class_decl,
                    mc.method,
                    arg_count,
                )) |method_decl| {
                    return strip_type_namespace(self.render_type_ref(method_decl.return_type));
                }
            }
            if (self.resolve_assignment_target_type(mc.object, current_env)) |instance_type| {
                const base_type = type_base_name(instance_type);
                if (self.find_class(base_type)) |class_decl| {
                    if (self.find_method_in_hierarchy(
                        null,
                        class_decl,
                        mc.method,
                        arg_count,
                    )) |method_decl| {
                        return strip_type_namespace(self.render_type_ref(method_decl.return_type));
                    }
                }
            }
        }

        if (mc.object.* == .field_access) {
            const fa = mc.object.field_access;
            if (fa.object.* == .identifier) {
                const qualified_name = std.fmt.allocPrint(
                    self.arena,
                    "{s}.{s}",
                    .{ fa.object.identifier.name, fa.field },
                ) catch return null;
                if (self.find_class(qualified_name)) |class_decl| {
                    if (self.find_method_in_hierarchy(
                        null,
                        class_decl,
                        mc.method,
                        arg_count,
                    )) |method_decl| {
                        return strip_type_namespace(self.render_type_ref(method_decl.return_type));
                    }
                }
            }
        }

        return null;
    }

    fn maybe_coerce_schema_expr_value(
        self: *Evaluator,
        expr: *const ast.Expr,
        value: Value,
    ) !Value {
        if (value != .string) return value;

        switch (expr.*) {
            .identifier => |id| {
                if (!std.mem.startsWith(u8, id.name, "Schema.")) return value;
                const suffix = id.name["Schema.".len..];
                const dot_idx = std.mem.lastIndexOfScalar(u8, suffix, '.') orelse return value;
                const owner_name = suffix[0..dot_idx];
                const member_name = suffix[dot_idx + 1 ..];
                if (is_known_schema_enum_type(owner_name)) {
                    return Value{ .string = member_name };
                }
                if (std.ascii.eqlIgnoreCase(owner_name, "SObjectType")) {
                    const sot = try self.arena.create(types.ObjectInstance);
                    sot.* = .{ .class_name = "Schema.SObjectType" };
                    try sot.fields.put(self.arena, "name", Value{ .string = member_name });
                    return Value{ .object = sot };
                }
                if (std.ascii.eqlIgnoreCase(member_name, "SObjectType")) {
                    const sot = try self.arena.create(types.ObjectInstance);
                    sot.* = .{ .class_name = "Schema.SObjectType" };
                    try sot.fields.put(self.arena, "name", Value{ .string = owner_name });
                    return Value{ .object = sot };
                }
                if (std.ascii.eqlIgnoreCase(member_name, "class")) return value;
                return self.make_s_object_field_token(owner_name, member_name);
            },
            .field_access => |fa| return try self.coerce_schema_field_access(fa, value),
            else => return value,
        }
    }

    /// `maybe_coerce_schema_expr_value` の `.field_access` 分岐を抽出。
    /// `Schema.X.Y` および `Schema.X.Y.Z` 形式のネストされた field access を
    /// 扱う。known enum は member を string として、`SObjectType` は
    /// `Schema.SObjectType` オブジェクトとして、それ以外は
    /// `SObjectField` トークンとして返す。
    fn coerce_schema_field_access(self: *Evaluator, fa: anytype, value: Value) !Value {
        if (fa.object.* == .field_access) {
            const inner_fa = fa.object.field_access;
            if (inner_fa.object.* == .identifier and
                std.ascii.eqlIgnoreCase(inner_fa.object.identifier.name, "Schema"))
            {
                if (is_known_schema_enum_type(inner_fa.field)) {
                    return Value{ .string = fa.field };
                }
                if (std.ascii.eqlIgnoreCase(inner_fa.field, "sObjectType") or
                    std.ascii.eqlIgnoreCase(inner_fa.field, "SObjectType"))
                {
                    return try self.make_schema_sobject_type_object(fa.field);
                }
                if (std.ascii.eqlIgnoreCase(fa.field, "SObjectType")) {
                    return try self.make_schema_sobject_type_object(inner_fa.field);
                }
                if (!std.ascii.eqlIgnoreCase(fa.field, "class")) {
                    return self.make_s_object_field_token(inner_fa.field, fa.field);
                }
            }
        }
        if (fa.object.* == .identifier and
            std.mem.startsWith(u8, fa.object.identifier.name, "Schema."))
        {
            const schema_name = fa.object.identifier.name["Schema.".len..];
            if (is_known_schema_enum_type(schema_name)) {
                return Value{ .string = fa.field };
            }
            if (std.ascii.eqlIgnoreCase(schema_name, "SObjectType")) {
                return try self.make_schema_sobject_type_object(fa.field);
            }
            if (std.ascii.eqlIgnoreCase(fa.field, "SObjectType")) {
                return try self.make_schema_sobject_type_object(schema_name);
            }
            if (!std.ascii.eqlIgnoreCase(fa.field, "class")) {
                return self.make_s_object_field_token(schema_name, fa.field);
            }
        }
        return value;
    }

    /// `Schema.SObjectType` オブジェクトを `name = type_name` で 1 個作る。
    fn make_schema_sobject_type_object(self: *Evaluator, type_name: []const u8) !Value {
        const sot = try self.arena.create(types.ObjectInstance);
        sot.* = .{ .class_name = "Schema.SObjectType" };
        try sot.fields.put(self.arena, "name", Value{ .string = type_name });
        return Value{ .object = sot };
    }

    fn render_type_ref(self: *Evaluator, type_ref: types.TypeRef) []const u8 {
        if (type_ref.params.len == 0) return strip_type_namespace(type_ref.name);

        var buf: std.ArrayListUnmanaged(u8) = .empty;
        buf.appendSlice(
            self.arena,
            strip_type_namespace(type_ref.name),
        ) catch return strip_type_namespace(type_ref.name);
        buf.append(self.arena, '<') catch return strip_type_namespace(type_ref.name);
        for (type_ref.params, 0..) |param, i| {
            if (i > 0) buf.appendSlice(self.arena, ",") catch {};
            buf.appendSlice(self.arena, self.render_type_ref(param)) catch {};
        }
        buf.append(self.arena, '>') catch {};
        return buf.toOwnedSlice(self.arena) catch strip_type_namespace(type_ref.name);
    }

    fn coerce_soql_assignment_to_declared_type(
        self: *Evaluator,
        val: Value,
        source_expr: ?*const ast.Expr,
        target_type: []const u8,
    ) !Value {
        if (source_expr == null or
            source_expr.?.* != .soql or
            val != .list or
            is_collection_type_name(target_type))
        {
            return val;
        }
        if (val.list.items.items.len > 0) return val.list.items.items[0];

        const exc = try self.arena.create(types.ObjectInstance);
        exc.* = .{ .class_name = "QueryException" };
        try exc.fields.put(
            self.arena,
            "message",
            Value{ .string = "List has no rows for assignment to SObject" },
        );
        self.pending_exception = Value{ .object = exc };
        return error.ApexException;
    }

    fn eval_assignment(
        self: *Evaluator,
        asgn: *ast.Assignment,
        val: Value,
        current_env: *Env,
    ) !Value {
        var coerced_val = val;
        if (self.resolve_assignment_target_type(asgn.target, current_env)) |target_type| {
            coerced_val = try self.coerce_soql_assignment_to_declared_type(
                coerced_val,
                asgn.value,
                target_type,
            );
            coerced_val = self.annotate_declared_collection_type(coerced_val, target_type);
        }
        return switch (asgn.target.*) {
            .identifier => |id| try self.eval_identifier_assignment(
                id.name,
                asgn,
                coerced_val,
                current_env,
            ),
            .field_access => |fa| try self.eval_field_assignment(
                fa,
                asgn,
                coerced_val,
                current_env,
            ),
            .index_access => |ia| try self.eval_index_assignment(ia, val, current_env),
            else => return val,
        };
    }

    fn eval_identifier_assignment(
        self: *Evaluator,
        id_name: []const u8,
        asgn: *ast.Assignment,
        coerced_val: Value,
        current_env: *Env,
    ) anyerror!Value {
        if (asgn.op == .null_coalesce_assign) {
            const current = self.eval_expr(asgn.target, current_env) catch Value.null_val;
            if (current != .null_val) return current;
            const assign = try self.arena.create(ast.Assignment);
            assign.* = .{
                .target = asgn.target,
                .op = .assign,
                .value = asgn.value,
                .loc = asgn.loc,
            };
            return self.eval_assignment(assign, coerced_val, current_env);
        }

        const final_val = if (asgn.op == .assign)
            coerced_val
        else
            try self.eval_identifier_compound_assignment(
                id_name,
                asgn.op,
                coerced_val,
                current_env,
            );
        try self.assign_identifier_binding(id_name, final_val, current_env);
        try self.update_this_identifier_field(id_name, final_val, current_env);
        self.update_static_identifier_field(id_name, final_val, current_env);
        return final_val;
    }

    fn eval_identifier_compound_assignment(
        self: *Evaluator,
        id_name: []const u8,
        op: ast.AssignOp,
        coerced_val: Value,
        current_env: *Env,
    ) !Value {
        const current = if (current_env.has(id_name))
            (current_env.get(id_name) orelse Value.null_val)
        else
            (self.resolve_bare_static_value(current_env, id_name) orelse Value.null_val);
        return try self.apply_compound_assignment(current, op, coerced_val);
    }

    fn assign_identifier_binding(
        self: *Evaluator,
        id_name: []const u8,
        final_val: Value,
        current_env: *Env,
    ) !void {
        current_env.set(id_name, final_val) catch {
            var found_static = false;
            if (self.current_class) |class_name| {
                found_static = self.assign_existing_static_field(class_name, id_name, final_val);
            }
            if (!found_static) {
                if (current_env.get_this()) |this_val| {
                    if (this_val == .object) {
                        found_static = self.assign_existing_static_field(
                            this_val.object.class_name,
                            id_name,
                            final_val,
                        );
                    }
                }
            }
            if (!found_static) try current_env.define(id_name, final_val);
        };
    }

    fn update_this_identifier_field(
        self: *Evaluator,
        id_name: []const u8,
        final_val: Value,
        current_env: *Env,
    ) !void {
        const this_val = current_env.get_this() orelse return;
        if (this_val != .object) return;
        if (self.should_update_this_field(this_val.object, id_name)) {
            try this_val.object.fields.put(self.arena, id_name, final_val);
        }
        _ = self.assign_existing_static_field(this_val.object.class_name, id_name, final_val);
    }

    fn should_update_this_field(
        self: *Evaluator,
        object: *types.ObjectInstance,
        id_name: []const u8,
    ) bool {
        for (object.fields.keys()) |key| {
            if (std.ascii.eqlIgnoreCase(key, id_name)) return true;
        }
        if (self.find_class(object.class_name)) |class_decl| {
            if (self.is_instance_field(class_decl, id_name) or
                self.is_parent_instance_field(class_decl, id_name))
            {
                return true;
            }
        }
        if (self.current_class) |current_class_name| {
            if (self.find_class(current_class_name)) |current_decl| {
                return self.is_instance_field(current_decl, id_name) or
                    self.is_parent_instance_field(current_decl, id_name);
            }
        }
        return false;
    }

    fn update_static_identifier_field(
        self: *Evaluator,
        id_name: []const u8,
        final_val: Value,
        current_env: *Env,
    ) void {
        if (current_env.get_this() != null) return;
        if (self.current_class) |class_name| {
            _ = self.assign_existing_static_field(class_name, id_name, final_val);
        }
    }

    fn assign_existing_static_field(
        self: *Evaluator,
        class_name: []const u8,
        field_name: []const u8,
        value: Value,
    ) bool {
        const owner = self.find_static_field_owner(class_name, field_name) orelse return false;
        const static_key = std.fmt.allocPrint(
            self.arena,
            "{s}.{s}",
            .{ owner.owner_name, owner.field_decl.name },
        ) catch "";
        if (self.global_env.bindings.getIndex(static_key)) |idx| {
            self.global_env.bindings.values()[idx] = value;
            return true;
        }
        self.global_env.define(static_key, value) catch return false;
        return true;
    }

    fn find_static_field_owner(
        self: *Evaluator,
        class_name: []const u8,
        field_name: []const u8,
    ) ?FieldLookup {
        var stack_key: [512]u8 = undefined;
        const key_len = class_name.len + 1 + field_name.len;
        if (key_len <= stack_key.len) {
            const lookup_key =
                static_field_cache_key_into(stack_key[0..key_len], class_name, field_name);
            if (self.static_field_owner_cache.get(lookup_key)) |cached| return cached;
        }

        const result = self.find_static_field_owner_uncached(class_name, field_name);
        const cache_key = self.static_field_cache_key(class_name, field_name) catch return result;
        const gop = self.static_field_owner_cache.getOrPut(
            self.arena,
            cache_key,
        ) catch return result;
        if (gop.found_existing) return gop.value_ptr.*;
        gop.value_ptr.* = result;
        return result;
    }

    fn find_static_field_owner_uncached(
        self: *Evaluator,
        class_name: []const u8,
        field_name: []const u8,
    ) ?FieldLookup {
        if (self.find_field_decl_with_owner(class_name, field_name)) |lookup| {
            if (lookup.field_decl.modifiers.is_static) return lookup;
        }
        const outer_name = self.find_outer_class_name(class_name) orelse return null;
        if (self.find_field_decl_with_owner(outer_name, field_name)) |lookup| {
            if (lookup.field_decl.modifiers.is_static) return lookup;
        }
        return null;
    }

    fn static_field_cache_key(
        self: *Evaluator,
        class_name: []const u8,
        field_name: []const u8,
    ) ![]const u8 {
        const key = try self.arena.alloc(u8, class_name.len + 1 + field_name.len);
        return static_field_cache_key_into(key, class_name, field_name);
    }

    fn static_field_cache_key_into(
        key: []u8,
        class_name: []const u8,
        field_name: []const u8,
    ) []const u8 {
        _ = ascii_lower_into(key[0..class_name.len], class_name);
        key[class_name.len] = '.';
        _ = ascii_lower_into(key[class_name.len + 1 ..], field_name);
        return key;
    }

    fn eval_field_assignment(
        self: *Evaluator,
        fa: *ast.FieldAccess,
        asgn: *ast.Assignment,
        coerced_val: Value,
        current_env: *Env,
    ) !Value {
        if (try self.assign_static_field_access(fa, asgn.op, coerced_val, current_env)) |result| {
            return result;
        }
        const obj = try self.eval_expr(fa.object, current_env);
        const final_val = try self.field_assignment_value(obj, fa.field, asgn.op, coerced_val);
        if (obj == .sobject) {
            try utils.sobject_put(&obj.sobject.fields, self.arena, fa.field, final_val);
            if (std.ascii.eqlIgnoreCase(fa.field, "Id")) {
                obj.sobject.id = if (final_val == .string) final_val.string else null;
            }
        } else if (obj == .object) {
            try self.assign_object_field(fa, obj.object, final_val, current_env);
        }
        return final_val;
    }

    fn assign_static_field_access(
        self: *Evaluator,
        fa: *ast.FieldAccess,
        op: ast.AssignOp,
        coerced_val: Value,
        current_env: *Env,
    ) !?Value {
        if (fa.object.* != .identifier) return null;
        const class_name = fa.object.identifier.name;
        const is_class = self.find_class(class_name) != null or
            std.ascii.eqlIgnoreCase(class_name, "RestContext") or
            std.ascii.eqlIgnoreCase(class_name, "System") or
            std.ascii.eqlIgnoreCase(class_name, "Trigger");
        const is_var = current_env.get(class_name) != null or
            self.resolve_bare_static_value(current_env, class_name) != null;
        if (!is_class or is_var) return null;

        self.ensure_static_init(class_name);
        const key = try std.fmt.allocPrint(self.arena, "{s}.{s}", .{ class_name, fa.field });
        const current = self.global_env.get(key) orelse Value.null_val;
        const final_val = if (op == .assign)
            coerced_val
        else
            try self.apply_compound_assignment(current, op, coerced_val);
        self.global_env.set(key, final_val) catch {
            try self.global_env.define(key, final_val);
        };
        return final_val;
    }

    fn field_assignment_value(
        self: *Evaluator,
        obj: Value,
        field_name: []const u8,
        op: ast.AssignOp,
        value: Value,
    ) !Value {
        if (op == .assign) return value;
        const current = if (obj == .sobject)
            utils.sobject_get(&obj.sobject.fields, field_name) orelse Value.null_val
        else if (obj == .object)
            utils.sobject_get(&obj.object.fields, field_name) orelse Value.null_val
        else
            Value.null_val;
        return try self.apply_compound_assignment(current, op, value);
    }

    fn apply_compound_assignment(
        self: *Evaluator,
        current: Value,
        op: ast.AssignOp,
        value: Value,
    ) !Value {
        var result = eval_compound_assign(current, op, value, self.arena);
        if (op == .plus_assign and (current == .string or value == .string)) {
            const left = try utils.coerce_to_string(current, self.arena);
            const right = try utils.coerce_to_string(value, self.arena);
            result = Value{ .string = try std.fmt.allocPrint(
                self.arena,
                "{s}{s}",
                .{ left, right },
            ) };
        }
        return result;
    }

    fn assign_object_field(
        self: *Evaluator,
        fa: *ast.FieldAccess,
        object: *types.ObjectInstance,
        final_val: Value,
        current_env: *Env,
    ) !void {
        if (try self.apply_object_field_setter(fa, object, final_val, current_env)) return;
        try self.put_object_field_case_insensitive(object, fa.field, final_val);
        if (fa.object.* == .this_expr) {
            current_env.set(fa.field, final_val) catch {};
        }
    }

    fn apply_object_field_setter(
        self: *Evaluator,
        fa: *ast.FieldAccess,
        object: *types.ObjectInstance,
        final_val: Value,
        current_env: *Env,
    ) !bool {
        const class_decl = self.find_class(object.class_name) orelse return false;
        for (class_decl.members) |member| {
            switch (member) {
                .field_decl => |field_decl| {
                    if (!std.ascii.eqlIgnoreCase(field_decl.name, fa.field) or
                        field_decl.setter_body == null)
                    {
                        continue;
                    }
                    try self.execute_field_setter(object, field_decl.setter_body.?, final_val);
                    if (fa.object.* == .this_expr) {
                        current_env.set(
                            fa.field,
                            object.fields.get(fa.field) orelse final_val,
                        ) catch {};
                    }
                    return true;
                },
                else => {},
            }
        }
        return false;
    }

    fn execute_field_setter(
        self: *Evaluator,
        object: *types.ObjectInstance,
        setter_body: []ast.Stmt,
        value: Value,
    ) !void {
        const setter_env = try self.global_env.child();
        try setter_env.define("this", Value{ .object = object });
        for (object.fields.keys(), object.fields.values()) |key, field_value| {
            setter_env.set(key, field_value) catch {
                try setter_env.define(key, field_value);
            };
        }
        try setter_env.define("value", value);
        _ = try self.exec_block(setter_body, setter_env);
        try self.sync_field_setter_object(object, setter_env);
    }

    fn sync_field_setter_object(
        self: *Evaluator,
        object: *types.ObjectInstance,
        setter_env: *Env,
    ) !void {
        const this_val = setter_env.get_this() orelse return;
        if (this_val == .object and this_val.object == object) {
            var field_keys: std.ArrayListUnmanaged([]const u8) = .empty;
            for (object.fields.keys()) |key| field_keys.append(self.arena, key) catch {};
            for (field_keys.items) |key| {
                if (setter_env.get(key)) |updated| {
                    try object.fields.put(self.arena, key, updated);
                }
            }
        } else if (this_val == .object) {
            for (this_val.object.fields.keys(), this_val.object.fields.values()) |key, value| {
                try object.fields.put(self.arena, key, value);
            }
        }
    }

    fn put_object_field_case_insensitive(
        self: *Evaluator,
        object: *types.ObjectInstance,
        field_name: []const u8,
        value: Value,
    ) !void {
        var existing_key: ?[]const u8 = null;
        for (object.fields.keys()) |key| {
            if (std.ascii.eqlIgnoreCase(key, field_name)) {
                existing_key = key;
                break;
            }
        }
        try object.fields.put(self.arena, existing_key orelse field_name, value);
    }

    fn eval_index_assignment(
        self: *Evaluator,
        ia: *ast.IndexAccess,
        val: Value,
        current_env: *Env,
    ) !Value {
        const obj = try self.eval_expr(ia.object, current_env);
        const idx = try self.eval_expr(ia.index, current_env);
        if (obj == .list and idx == .integer and idx.integer >= 0) {
            const index: usize = @intCast(idx.integer);
            if (index < obj.list.items.items.len) {
                obj.list.items.items[index] = val;
            }
        }
        return val;
    }

    fn eval_method_call(
        self: *Evaluator,
        mc: *ast.MethodCallExpr,
        current_env: *Env,
    ) anyerror!Value {
        if (mc.loc.line > 0) {
            self.current_call_line = mc.loc.line;
            if (self.call_stack.items.len > 0)
                self.call_stack.items[self.call_stack.items.len - 1].line = mc.loc.line;
        }
        if (try self.eval_field_add_error_sugar_method_call(mc, current_env)) |result| {
            return result;
        }

        if (mc.null_safe) {
            const obj_val = self.eval_expr(mc.object, current_env) catch |err| {
                if (err == error.ApexException and self.pending_exception != null) {
                    if (self.pending_exception.? == .object) {
                        const class_name = self.pending_exception.?.object.class_name;
                        if (std.ascii.indexOfIgnoreCase(class_name, "NullPointer") != null) {
                            self.pending_exception = null;
                            return Value.null_val;
                        }
                    }
                }
                return err;
            };
            if (obj_val == .null_val) return Value.null_val;
        }

        var args: std.ArrayListUnmanaged(Value) = .empty;
        var arg_type_hints: std.ArrayListUnmanaged(?[]const u8) = .empty;
        for (mc.args) |*arg| {
            var arg_value = try self.eval_expr(arg, current_env);
            arg_value = try self.maybe_coerce_schema_expr_value(arg, arg_value);
            try args.append(self.arena, arg_value);
            try arg_type_hints.append(self.arena, self.extract_expr_type_hint(arg, current_env));
        }
        const prev_hints = self.cast_type_hints;
        self.cast_type_hints = arg_type_hints.items;
        defer self.cast_type_hints = prev_hints;

        if (try self.eval_system_search_method_call(mc, args.items)) |result| return result;
        if (try self.eval_super_method_call(mc, current_env, args.items)) |result| return result;
        if (try self.eval_identifier_method_call(mc, current_env, args.items)) |result| {
            return result;
        }
        if (try self.eval_field_access_method_call(mc, current_env, args.items)) |result| {
            return result;
        }

        const obj = try self.eval_expr(mc.object, current_env);
        return self.eval_instance_method(obj, mc.method, args.items, current_env);
    }

    fn eval_field_add_error_sugar_method_call(
        self: *Evaluator,
        mc: *ast.MethodCallExpr,
        current_env: *Env,
    ) anyerror!?Value {
        if (!(std.ascii.eqlIgnoreCase(mc.method, "addError") and
            mc.args.len == 1 and
            mc.object.* == .field_access))
        {
            return null;
        }

        const fa = mc.object.field_access;
        const receiver_val = self.eval_expr(fa.object, current_env) catch Value.null_val;
        if (receiver_val != .sobject) return null;

        const msg_val = try self.eval_expr(&mc.args[0], current_env);
        const msg_str: []const u8 = switch (msg_val) {
            .string => |s| s,
            else => try utils.coerce_to_string(msg_val, self.arena),
        };
        const err_obj = try self.arena.create(types.ObjectInstance);
        err_obj.* = .{ .class_name = "Database.Error" };
        try err_obj.fields.put(self.arena, "message", Value{ .string = msg_str });
        try err_obj.fields.put(
            self.arena,
            "statusCode",
            Value{ .string = "FIELD_CUSTOM_VALIDATION_EXCEPTION" },
        );
        try err_obj.fields.put(self.arena, "field", Value{ .string = fa.field });
        const fields_list = try self.arena.create(types.ListValue);
        fields_list.* = .{};
        try fields_list.items.append(self.arena, Value{ .string = fa.field });
        try err_obj.fields.put(self.arena, "fields", Value{ .list = fields_list });

        var errors_list = if (utils.sobject_get(&receiver_val.sobject.fields, "errors")) |existing|
            if (existing == .list) existing.list else blk: {
                const lst = try self.arena.create(types.ListValue);
                lst.* = .{};
                break :blk lst;
            }
        else blk: {
            const lst = try self.arena.create(types.ListValue);
            lst.* = .{};
            break :blk lst;
        };
        try errors_list.items.append(self.arena, Value{ .object = err_obj });
        try utils.sobject_put(
            &receiver_val.sobject.fields,
            self.arena,
            "errors",
            Value{ .list = errors_list },
        );
        return Value.void_val;
    }

    fn eval_system_search_method_call(
        self: *Evaluator,
        mc: *ast.MethodCallExpr,
        args: []const Value,
    ) anyerror!?Value {
        if (mc.object.* != .field_access) return null;
        const search_fa = mc.object.field_access;
        if (!(search_fa.object.* == .identifier and
            std.ascii.eqlIgnoreCase(search_fa.object.identifier.name, "System") and
            std.ascii.eqlIgnoreCase(search_fa.field, "Search") and
            std.ascii.eqlIgnoreCase(mc.method, "query")))
        {
            return null;
        }

        if (args.len > 0 and args[0] == .string) return try self.execute_sosl(args[0].string);
        const outer = try self.arena.create(types.ListValue);
        outer.* = .{};
        return Value{ .list = outer };
    }

    fn eval_super_method_call(
        self: *Evaluator,
        mc: *ast.MethodCallExpr,
        current_env: *Env,
        args: []const Value,
    ) anyerror!?Value {
        if (mc.object.* != .super_expr) return null;
        if (current_env.get_this()) |this_val| {
            if (this_val == .object) {
                if (self.current_class) |current_class_name| {
                    if (self.find_class(current_class_name)) |current_decl| {
                        if (current_decl.super_class) |sc| {
                            if (self.find_class(sc.name)) |super_decl| {
                                return try self.call_super_instance_method(
                                    super_decl,
                                    this_val.object,
                                    mc.method,
                                    args,
                                );
                            }
                        }
                    }
                }
            }
        }
        return Value.null_val;
    }

    fn eval_identifier_method_call(
        self: *Evaluator,
        mc: *ast.MethodCallExpr,
        current_env: *Env,
        args: []const Value,
    ) anyerror!?Value {
        if (mc.object.* != .identifier) return null;
        const class_name = mc.object.identifier.name;

        if (try self.eval_identifier_assert_or_test_method_call(
            class_name,
            mc.method,
            args,
        )) |result| {
            return result;
        }
        if (try self.eval_identifier_system_special_method_call(
            class_name,
            mc.method,
            args,
            current_env,
        )) |result| {
            return result;
        }
        if (try self.eval_identifier_json_method_call(class_name, mc.method, args)) |result| {
            return result;
        }
        if (try self.eval_identifier_early_custom_metadata_method(
            class_name,
            mc.method,
            args,
        )) |result| {
            return result;
        }
        if (try self.eval_identifier_integer_value_of_method_call(
            class_name,
            mc.method,
            args,
        )) |result| {
            return result;
        }
        if (try self.eval_resolved_identifier_method_call(
            class_name,
            mc.method,
            args,
            current_env,
            mc,
        )) |result| {
            return result;
        }
        return try self.eval_identifier_static_dispatch(
            class_name,
            mc.method,
            args,
            current_env,
            mc,
        );
    }

    fn eval_identifier_assert_or_test_method_call(
        self: *Evaluator,
        class_name: []const u8,
        method: []const u8,
        args: []const Value,
    ) anyerror!?Value {
        if (std.ascii.eqlIgnoreCase(class_name, "Assert")) {
            return try self.handle_assert(method, args);
        }
        if (std.ascii.eqlIgnoreCase(class_name, "Test")) return try self.handle_test(method, args);
        if (std.ascii.eqlIgnoreCase(class_name, "System") and
            (std.ascii.startsWithIgnoreCase(method, "assert") or
                std.ascii.eqlIgnoreCase(method, "assert")))
        {
            return try self.handle_assert(method, args);
        }
        return null;
    }

    fn eval_identifier_system_special_method_call(
        self: *Evaluator,
        class_name: []const u8,
        method: []const u8,
        args: []const Value,
        current_env: *Env,
    ) anyerror!?Value {
        if (!(std.ascii.eqlIgnoreCase(class_name, "System"))) return null;
        if (std.ascii.eqlIgnoreCase(method, "enqueueJob")) {
            if (args.len > 0 and args[0] == .object) return try self.enqueue_job(args[0].object);
            return Value.void_val;
        }
        if (std.ascii.eqlIgnoreCase(method, "schedule")) {
            return try self.handle_system_method("schedule", method, args, current_env);
        }
        return null;
    }

    fn eval_identifier_integer_value_of_method_call(
        self: *Evaluator,
        class_name: []const u8,
        method: []const u8,
        args: []const Value,
    ) anyerror!?Value {
        if (!(std.ascii.eqlIgnoreCase(class_name, "Integer") and
            std.ascii.eqlIgnoreCase(method, "valueOf") and
            args.len > 0 and
            args[0] == .string))
        {
            return null;
        }
        if (std.fmt.parseInt(i64, args[0].string, 10)) |value| {
            return Value{ .integer = value };
        } else |_| {
            const message = try std.fmt.allocPrint(
                self.arena,
                "Invalid integer: {s}",
                .{args[0].string},
            );
            return try self.throw_named_exception("System.TypeException", message);
        }
    }

    fn eval_identifier_json_method_call(
        self: *Evaluator,
        class_name: []const u8,
        method: []const u8,
        args: []const Value,
    ) anyerror!?Value {
        if (!(std.ascii.eqlIgnoreCase(class_name, "JSON"))) return null;
        if (try self.eval_json_serialize_method_call(method, args)) |result| return result;
        if (try self.eval_json_deserialize_method_call(method, args)) |result| return result;
        if (std.ascii.eqlIgnoreCase(method, "createParser")) {
            return try self.handle_system_json_create_parser(args);
        }
        return null;
    }

    fn eval_json_serialize_method_call(
        self: *Evaluator,
        method: []const u8,
        args: []const Value,
    ) anyerror!?Value {
        if (!(std.ascii.eqlIgnoreCase(method, "serialize") or
            std.ascii.eqlIgnoreCase(method, "serializePretty")))
        {
            return null;
        }
        if (args.len == 0) return Value{ .string = "{}" };
        if (args[0] == .object and
            (std.ascii.eqlIgnoreCase(args[0].object.class_name, "Schema.SObjectField") or
                std.ascii.eqlIgnoreCase(args[0].object.class_name, "SObjectField")))
        {
            return try self.throw_system_json_exception(
                "Apex Type unsupported in JSON: Schema.SObjectField",
            );
        }
        self.last_json_value = args[0];
        return Value{ .string = try utils.to_json(args[0], self.arena) };
    }

    fn eval_json_deserialize_method_call(
        self: *Evaluator,
        method: []const u8,
        args: []const Value,
    ) anyerror!?Value {
        if (!(std.ascii.eqlIgnoreCase(method, "deserialize") or
            std.ascii.eqlIgnoreCase(method, "deserializeStrict")))
        {
            return null;
        }
        if (args.len >= 1 and args[0] == .null_val) {
            return try self.throw_named_exception("JSONException", "Argument cannot be null.");
        }
        if (!(args.len >= 1 and args[0] == .string)) return Value.null_val;

        const json_str = args[0].string;
        const trimmed_json = std.mem.trim(u8, json_str, " \t\r\n");
        if (trimmed_json.len == 0 or
            (trimmed_json[0] != '{' and trimmed_json[0] != '[' and trimmed_json[0] != '"' and
                !std.ascii.isDigit(trimmed_json[0]) and
                !std.mem.startsWith(u8, trimmed_json, "null") and
                !std.mem.startsWith(u8, trimmed_json, "true") and
                !std.mem.startsWith(u8, trimmed_json, "false")))
        {
            const message = try std.fmt.allocPrint(self.arena, "Malformed JSON: {s}", .{json_str});
            return try self.throw_named_exception("JSONException", message);
        }

        const type_name = json_deserialize_type_name(args);
        const is_list_type = std.ascii.startsWithIgnoreCase(type_name, "List") or
            std.mem.endsWith(u8, type_name, "[]");
        if (!utils.is_json_balanced(trimmed_json)) {
            const message = try std.fmt.allocPrint(self.arena, "Malformed JSON: {s}", .{json_str});
            return try self.throw_named_exception("System.JSONException", message);
        }
        if (self.parse_json_value(json_str, type_name)) |parsed| return parsed;
        if (trimmed_json.len > 2) {
            const message = try std.fmt.allocPrint(self.arena, "Malformed JSON: {s}", .{json_str});
            return try self.throw_named_exception("JSONException", message);
        }
        if (is_list_type) {
            const list = try self.arena.create(types.ListValue);
            list.* = .{};
            return Value{ .list = list };
        }
        const obj = try self.arena.create(types.SObject);
        obj.* = .{ .type_name = "Object" };
        return Value{ .sobject = obj };
    }

    fn json_deserialize_type_name(args: []const Value) []const u8 {
        if (args.len >= 2 and args[1] == .object) {
            const type_obj = args[1].object;
            if (std.ascii.eqlIgnoreCase(type_obj.class_name, "Type")) {
                if (type_obj.fields.get("name")) |name| {
                    if (name == .string) return name.string;
                }
            }
            return type_obj.class_name;
        }
        return "Object";
    }

    fn throw_named_exception(
        self: *Evaluator,
        class_name: []const u8,
        message: []const u8,
    ) anyerror!Value {
        const exc = try self.arena.create(types.ObjectInstance);
        exc.* = .{ .class_name = class_name };
        try exc.fields.put(self.arena, "message", Value{ .string = message });
        self.pending_exception = Value{ .object = exc };
        return error.ApexException;
    }

    fn eval_identifier_early_custom_metadata_method(
        self: *Evaluator,
        class_name: []const u8,
        method: []const u8,
        args: []const Value,
    ) anyerror!?Value {
        if (!(std.mem.endsWith(u8, class_name, "__mdt") and
            (std.ascii.eqlIgnoreCase(method, "getInstance") or
                std.ascii.eqlIgnoreCase(method, "getAll"))))
        {
            return null;
        }
        self.ensure_custom_metadata_loaded(class_name);
        if (std.ascii.eqlIgnoreCase(method, "getInstance")) {
            const dev_name = if (args.len > 0 and args[0] == .string) args[0].string else "";
            if (dev_name.len == 0) return Value.null_val;
            return try self.custom_metadata_get_instance(class_name, dev_name);
        }
        return try self.custom_metadata_get_all(class_name);
    }

    fn ensure_custom_metadata_loaded(self: *Evaluator, class_name: []const u8) void {
        var found_in_store = false;
        var store_iter = self.store.iterator();
        while (store_iter.next()) |entry| {
            if (std.ascii.eqlIgnoreCase(entry.key_ptr.*, class_name)) {
                found_in_store = true;
                break;
            }
        }
        if (!found_in_store) self.load_custom_metadata_from_files(class_name) catch {};
    }

    fn custom_metadata_get_instance(
        self: *Evaluator,
        class_name: []const u8,
        developer_name: []const u8,
    ) anyerror!Value {
        var store_iter = self.store.iterator();
        while (store_iter.next()) |entry| {
            if (!std.ascii.eqlIgnoreCase(entry.key_ptr.*, class_name)) continue;
            for (entry.value_ptr.items) |item| {
                if (item != .sobject) continue;
                if (utils.sobject_get(&item.sobject.fields, "DeveloperName")) |dn| {
                    if (dn == .string and
                        std.ascii.eqlIgnoreCase(dn.string, developer_name))
                    {
                        return item;
                    }
                }
            }
        }
        return Value.null_val;
    }

    fn custom_metadata_get_all(self: *Evaluator, class_name: []const u8) anyerror!Value {
        const map = try self.arena.create(types.MapValue);
        map.* = .{};
        var store_iter = self.store.iterator();
        while (store_iter.next()) |entry| {
            if (!std.ascii.eqlIgnoreCase(entry.key_ptr.*, class_name)) continue;
            for (entry.value_ptr.items) |item| {
                if (item != .sobject) continue;
                if (utils.sobject_get(&item.sobject.fields, "DeveloperName")) |dn| {
                    if (dn == .string) try map.entries.put(self.arena, dn.string, item);
                }
            }
        }
        return Value{ .map = map };
    }

    fn eval_resolved_identifier_method_call(
        self: *Evaluator,
        class_name: []const u8,
        method: []const u8,
        args: []const Value,
        current_env: *Env,
        mc: *ast.MethodCallExpr,
    ) anyerror!?Value {
        const resolved_var = try self.resolve_identifier_method_receiver_value(
            class_name,
            current_env,
        );
        switch (resolved_var) {
            .list, .map, .set, .sobject, .object, .string, .double, .integer, .boolean => {
                return try self.eval_instance_method(resolved_var, method, args, current_env);
            },
            else => {},
        }
        if (resolved_var == .null_val and current_env.has(class_name)) {
            const rebound = try self.eval_expr(mc.object, current_env);
            return try self.eval_instance_method(rebound, method, args, current_env);
        }
        if (is_builtin_static_namespace(class_name)) {
            if (self.resolve_visible_user_class_in_scope(current_env, class_name)) |visible_class| {
                return try self.call_method(visible_class, method, args);
            }
        }
        return null;
    }

    fn resolve_identifier_method_receiver_value(
        self: *Evaluator,
        class_name: []const u8,
        current_env: *Env,
    ) anyerror!Value {
        if (current_env.get(class_name)) |value| return value;
        if (try self.resolve_current_class_method_receiver_value(class_name)) |value| return value;
        if (self.resolve_this_class_method_receiver_value(class_name, current_env)) |value| {
            return value;
        }
        return Value.null_val;
    }

    fn resolve_current_class_method_receiver_value(
        self: *Evaluator,
        class_name: []const u8,
    ) anyerror!?Value {
        const current_class_name = self.current_class orelse return null;
        const already_in_getter = if (self.evaluating_getter) |getter_name|
            std.ascii.eqlIgnoreCase(getter_name, class_name)
        else
            false;
        if (!already_in_getter) {
            if (try self.resolve_current_class_static_getter_value(
                current_class_name,
                class_name,
            )) |value| {
                return value;
            }
        }
        const current_key = std.fmt.allocPrint(
            self.arena,
            "{s}.{s}",
            .{ current_class_name, class_name },
        ) catch {
            return Value.null_val;
        };
        if (self.global_env.get(current_key)) |value| return value;
        return self.resolve_outer_static_field(current_class_name, class_name);
    }

    fn resolve_current_class_static_getter_value(
        self: *Evaluator,
        current_class_name: []const u8,
        class_name: []const u8,
    ) anyerror!?Value {
        const class_decl = self.find_class(current_class_name) orelse return null;
        for (class_decl.members) |member| {
            switch (member) {
                .field_decl => |field_decl| {
                    if (!(field_decl.modifiers.is_static and
                        std.ascii.eqlIgnoreCase(field_decl.name, class_name) and
                        field_decl.getter_body != null))
                    {
                        continue;
                    }
                    const getter_env = self.global_env.child() catch return Value.null_val;
                    const saved_class = self.current_class;
                    const saved_getter = self.evaluating_getter;
                    const saved_getter_instance = self.evaluating_getter_instance;
                    self.current_class = current_class_name;
                    self.evaluating_getter = class_name;
                    self.evaluating_getter_instance = null;
                    defer {
                        self.current_class = saved_class;
                        self.evaluating_getter = saved_getter;
                        self.evaluating_getter_instance = saved_getter_instance;
                    }

                    const getter_result = self.exec_block(
                        field_decl.getter_body.?,
                        getter_env,
                    ) catch {
                        return Value.null_val;
                    };
                    return switch (getter_result) {
                        .return_val => |value| value,
                        else => self.return_value,
                    };
                },
                else => {},
            }
        }
        return null;
    }

    fn resolve_this_class_method_receiver_value(
        self: *Evaluator,
        class_name: []const u8,
        current_env: *Env,
    ) ?Value {
        const this_val = current_env.get_this() orelse return null;
        if (this_val != .object) return null;

        const this_class_name = this_val.object.class_name;
        const this_key = std.fmt.allocPrint(
            self.arena,
            "{s}.{s}",
            .{ this_class_name, class_name },
        ) catch {
            return Value.null_val;
        };
        if (self.global_env.get(this_key)) |value| return value;
        if (self.find_class(this_class_name)) |this_class_decl| {
            var current_parent = this_class_decl.super_class;
            while (current_parent) |super_class| {
                self.ensure_static_init(super_class.name);
                const parent_key = std.fmt.allocPrint(
                    self.arena,
                    "{s}.{s}",
                    .{ super_class.name, class_name },
                ) catch break;
                if (self.global_env.get(parent_key)) |value| return value;
                current_parent = if (self.find_class(super_class.name)) |parent_decl|
                    parent_decl.super_class
                else
                    null;
            }
        }
        return self.resolve_outer_static_field(this_class_name, class_name);
    }

    fn eval_identifier_static_dispatch(
        self: *Evaluator,
        class_name: []const u8,
        method: []const u8,
        args: []const Value,
        current_env: *Env,
        mc: *ast.MethodCallExpr,
    ) anyerror!?Value {
        if (std.ascii.eqlIgnoreCase(class_name, "Database")) {
            return try self.handle_database_method(method, args, current_env);
        }
        var builtin_ctx = self.make_builtin_context();
        if (try builtins.dispatch_static(&builtin_ctx, class_name, method, args)) |result| {
            return result;
        }
        if (try self.eval_identifier_custom_metadata_method(class_name, method, args)) |result| {
            return result;
        }
        if (try self.handle_custom_setting_static_method(class_name, method, args)) |result| {
            return result;
        }
        if (!std.ascii.eqlIgnoreCase(class_name, "Database") and
            self.find_class(class_name) != null)
        {
            return try self.call_method(class_name, method, args);
        }
        if (try self.handle_test_factory(class_name, method, args)) |result| return result;
        if (std.ascii.eqlIgnoreCase(method, "getSObjectType")) {
            return try self.schema_s_object_type_value(class_name);
        }
        if (self.find_class(class_name) == null) {
            if (self.eval_expr(mc.object, current_env)) |obj_val| {
                if (obj_val != .null_val) {
                    return try self.eval_instance_method(obj_val, method, args, current_env);
                }
            } else |_| {}
        }
        return try self.call_method(class_name, method, args);
    }

    fn eval_identifier_custom_metadata_method(
        self: *Evaluator,
        class_name: []const u8,
        method: []const u8,
        args: []const Value,
    ) anyerror!?Value {
        if (!(std.mem.endsWith(u8, class_name, "__mdt"))) return null;
        self.ensure_custom_metadata_loaded(class_name);
        if (std.ascii.eqlIgnoreCase(method, "getInstance")) {
            const dev_name = if (args.len > 0 and args[0] == .string) args[0].string else "";
            return try self.custom_metadata_get_instance(class_name, dev_name);
        }
        if (std.ascii.eqlIgnoreCase(method, "getAll")) {
            return try self.custom_metadata_get_all(class_name);
        }
        return null;
    }

    fn eval_field_access_method_call(
        self: *Evaluator,
        mc: *ast.MethodCallExpr,
        current_env: *Env,
        args: []const Value,
    ) anyerror!?Value {
        if (mc.object.* != .field_access) return null;
        const field_access = mc.object.field_access;
        if (try self.eval_three_level_field_access_method_call(
            field_access,
            mc.method,
            args,
            current_env,
        )) |result| {
            return result;
        }
        return try self.eval_identifier_field_access_method_call(
            field_access,
            mc.method,
            args,
            current_env,
        );
    }

    fn eval_three_level_field_access_method_call(
        self: *Evaluator,
        field_access: *ast.FieldAccess,
        method: []const u8,
        args: []const Value,
        current_env: *Env,
    ) anyerror!?Value {
        if (field_access.object.* != .field_access) return null;
        const inner_access = field_access.object.field_access;
        if (inner_access.object.* != .identifier) return null;

        const outer_name = inner_access.object.identifier.name;
        const type_name = inner_access.field;
        if (std.ascii.eqlIgnoreCase(outer_name, "Schema") and
            std.ascii.eqlIgnoreCase(type_name, "SObjectType"))
        {
            return try self.eval_instance_method(
                try self.schema_s_object_type_value(field_access.field),
                method,
                args,
                current_env,
            );
        }
        if (std.ascii.eqlIgnoreCase(outer_name, "Schema") and
            std.ascii.eqlIgnoreCase(field_access.field, "SObjectType"))
        {
            return try self.eval_instance_method(
                try self.schema_s_object_type_value(type_name),
                method,
                args,
                current_env,
            );
        }
        if (std.ascii.eqlIgnoreCase(outer_name, "Schema") and
            std.ascii.eqlIgnoreCase(method, "getDescribe"))
        {
            var builtin_ctx = self.make_builtin_context();
            return try builtins.create_field_describe_result(
                &builtin_ctx,
                type_name,
                field_access.field,
            );
        }
        return null;
    }

    fn eval_identifier_field_access_method_call(
        self: *Evaluator,
        field_access: *ast.FieldAccess,
        method: []const u8,
        args: []const Value,
        current_env: *Env,
    ) anyerror!?Value {
        if (field_access.object.* != .identifier) return null;
        const outer_class = field_access.object.identifier.name;
        const inner = field_access.field;

        if (try self.eval_system_namespace_method_call(
            outer_class,
            inner,
            method,
            args,
            current_env,
        )) |result| {
            return result;
        }
        if (try self.eval_schema_field_token_method_call(
            outer_class,
            inner,
            method,
            args,
            current_env,
        )) |result| {
            return result;
        }
        if (try self.eval_dataweave_script_method_call(outer_class, inner, method, args)) |result| {
            return result;
        }
        if (try self.eval_invocable_action_method_call(outer_class, inner, method, args)) |result| {
            return result;
        }
        if (try self.eval_flow_interview_namespace_method_call(
            outer_class,
            inner,
            method,
            args,
        )) |result| {
            return result;
        }
        if (std.ascii.eqlIgnoreCase(outer_class, "ConnectApi")) {
            return (try self.handle_connect_api_namespace(inner, method, args)) orelse
                Value.null_val;
        }
        return try self.eval_cache_namespace_method_call(outer_class, inner, method, args);
    }

    fn eval_system_namespace_method_call(
        self: *Evaluator,
        outer_class: []const u8,
        inner: []const u8,
        method: []const u8,
        args: []const Value,
        current_env: *Env,
    ) anyerror!?Value {
        if (!(std.ascii.eqlIgnoreCase(outer_class, "System"))) return null;
        if (std.ascii.eqlIgnoreCase(inner, "Assert")) return try self.handle_assert(method, args);
        return try self.handle_system_method(inner, method, args, current_env);
    }

    fn eval_schema_field_token_method_call(
        self: *Evaluator,
        outer_class: []const u8,
        inner: []const u8,
        method: []const u8,
        args: []const Value,
        current_env: *Env,
    ) anyerror!?Value {
        if (!(std.ascii.eqlIgnoreCase(method, "getDescribe"))) return null;
        if (std.ascii.eqlIgnoreCase(inner, "SObjectType")) {
            return try self.eval_instance_method(
                try self.schema_s_object_type_value(outer_class),
                method,
                args,
                current_env,
            );
        }
        var builtin_ctx = self.make_builtin_context();
        return try builtins.create_field_describe_result(&builtin_ctx, outer_class, inner);
    }

    fn eval_dataweave_script_method_call(
        self: *Evaluator,
        outer_class: []const u8,
        inner: []const u8,
        method: []const u8,
        args: []const Value,
    ) anyerror!?Value {
        if (!(std.ascii.eqlIgnoreCase(outer_class, "DataWeave") and
            std.ascii.eqlIgnoreCase(inner, "Script") and
            std.ascii.eqlIgnoreCase(method, "createScript") and
            args.len > 0 and
            args[0] == .string))
        {
            return null;
        }
        const dataweave = try self.arena.create(types.ObjectInstance);
        dataweave.* = .{ .class_name = "DataWeave.Script" };
        try dataweave.fields.put(self.arena, "scriptName", args[0]);
        return Value{ .object = dataweave };
    }

    fn eval_invocable_action_method_call(
        self: *Evaluator,
        outer_class: []const u8,
        inner: []const u8,
        method: []const u8,
        args: []const Value,
    ) anyerror!?Value {
        if (!(std.ascii.eqlIgnoreCase(outer_class, "Invocable") and
            std.ascii.eqlIgnoreCase(inner, "Action")))
        {
            return null;
        }
        var builtin_ctx = self.make_builtin_context();
        return try builtins.dispatch_static(&builtin_ctx, "Invocable.Action", method, args);
    }

    fn eval_flow_interview_namespace_method_call(
        self: *Evaluator,
        outer_class: []const u8,
        inner: []const u8,
        method: []const u8,
        args: []const Value,
    ) anyerror!?Value {
        if (!(std.ascii.eqlIgnoreCase(outer_class, "Flow") and
            std.ascii.eqlIgnoreCase(inner, "Interview") and
            std.ascii.eqlIgnoreCase(method, "createInterview") and
            args.len > 0 and
            args[0] == .string))
        {
            return null;
        }
        if (!self.has_flow_definition(args[0].string)) {
            return try self.throw_named_exception("TypeException", "Unknown Flow");
        }
        const interview = try self.arena.create(types.ObjectInstance);
        interview.* = .{ .class_name = "Flow.Interview" };
        try interview.fields.put(self.arena, "flowName", args[0]);
        if (args.len > 1 and args[1] == .map) {
            for (args[1].map.entries.keys(), args[1].map.entries.values()) |key, value| {
                try interview.fields.put(self.arena, key, value);
            }
        }
        return Value{ .object = interview };
    }

    fn eval_cache_namespace_method_call(
        self: *Evaluator,
        outer_class: []const u8,
        inner: []const u8,
        method: []const u8,
        args: []const Value,
    ) anyerror!?Value {
        if (!(std.ascii.eqlIgnoreCase(outer_class, "Cache") and
            (std.ascii.eqlIgnoreCase(inner, "Session") or
                std.ascii.eqlIgnoreCase(inner, "Org")) and
            std.ascii.eqlIgnoreCase(method, "getPartition")))
        {
            return null;
        }
        const partition_name = if (args.len > 0 and args[0] == .string)
            args[0].string
        else
            "default";
        const cache_key = try std.fmt.allocPrint(
            self.arena,
            "Cache.{s}.partition:{s}",
            .{ inner, partition_name },
        );
        if (self.global_env.get(cache_key)) |existing| {
            if (existing == .object) return existing;
        }
        const partition = try self.arena.create(types.ObjectInstance);
        partition.* = .{ .class_name = "Cache.Partition" };
        const cache_map = try self.arena.create(types.MapValue);
        cache_map.* = .{};
        const is_available = std.ascii.indexOfIgnoreCase(partition_name, "NeverExist") == null;
        try partition.fields.put(self.arena, "_cache", Value{ .map = cache_map });
        try partition.fields.put(self.arena, "_is_available", Value{ .boolean = is_available });
        self.global_env.set(cache_key, Value{ .object = partition }) catch {
            try self.global_env.define(cache_key, Value{ .object = partition });
        };
        return Value{ .object = partition };
    }

    fn connect_api_create_object(self: *Evaluator, class_name: []const u8) !*types.ObjectInstance {
        const obj = try self.arena.create(types.ObjectInstance);
        obj.* = .{ .class_name = class_name };
        return obj;
    }

    fn prepare_method_arg_value(self: *Evaluator, value: Value) !Value {
        return switch (value) {
            .string => |s| Value{ .string = try self.arena.dupe(u8, s) },
            else => value,
        };
    }

    fn connect_api_create_record_ref(self: *Evaluator, record_id: []const u8) !Value {
        const record = try self.connect_api_create_object("ConnectApi.Record");
        try record.fields.put(self.arena, "id", Value{ .string = record_id });
        return Value{ .object = record };
    }

    fn connect_api_markup_tag(markup_value: Value) ?[]const u8 {
        return switch (markup_value) {
            .string => |name| blk: {
                if (std.ascii.eqlIgnoreCase(name, "Bold")) break :blk "b";
                if (std.ascii.eqlIgnoreCase(name, "Code")) break :blk "code";
                if (std.ascii.eqlIgnoreCase(name, "Italic")) break :blk "i";
                if (std.ascii.eqlIgnoreCase(name, "ListItem")) break :blk "li";
                if (std.ascii.eqlIgnoreCase(name, "OrderedList")) break :blk "ol";
                if (std.ascii.eqlIgnoreCase(name, "Paragraph")) break :blk "p";
                if (std.ascii.eqlIgnoreCase(name, "Strikethrough")) break :blk "s";
                if (std.ascii.eqlIgnoreCase(name, "Underline")) break :blk "u";
                if (std.ascii.eqlIgnoreCase(name, "UnorderedList")) break :blk "ul";
                break :blk null;
            },
            else => null,
        };
    }

    fn is_connect_api_hashtag_char(ch: u8) bool {
        return std.ascii.isAlphanumeric(ch) or ch == '_';
    }

    fn is_connect_api_whitespace(ch: u8) bool {
        return ch == ' ' or ch == '\t' or ch == '\n' or ch == '\r';
    }

    fn is_connect_api_mention_id(self: *Evaluator, record_id: []const u8) bool {
        _ = self;
        if (record_id.len != 15 and record_id.len != 18) return false;
        for (record_id) |ch| {
            if (!std.ascii.isAlphanumeric(ch)) return false;
        }
        if (std.mem.startsWith(u8, record_id, "005")) return true;
        if (std.mem.startsWith(u8, record_id, "00G")) return true;
        if (std.mem.startsWith(u8, record_id, "0F9")) return true;
        return false;
    }

    fn connect_api_class_name_equals(class_name: []const u8, simple_name: []const u8) bool {
        if (std.ascii.eqlIgnoreCase(class_name, simple_name)) return true;
        if (std.mem.lastIndexOfScalar(u8, class_name, '.')) |dot| {
            return std.ascii.eqlIgnoreCase(class_name[dot + 1 ..], simple_name);
        }
        return false;
    }

    fn connect_api_append_output_segment(
        self: *Evaluator,
        segments: *types.ListValue,
        segment: *types.ObjectInstance,
    ) !void {
        try segments.items.append(self.arena, Value{ .object = segment });
    }

    fn connect_api_append_text_segment(
        self: *Evaluator,
        segments: *types.ListValue,
        text: []const u8,
    ) !void {
        if (text.len == 0) return;
        const segment = try self.connect_api_create_object("ConnectApi.TextSegment");
        try segment.fields.put(self.arena, "text", Value{ .string = text });
        try self.connect_api_append_output_segment(segments, segment);
    }

    fn connect_api_append_parsed_text(
        self: *Evaluator,
        segments: *types.ListValue,
        text: []const u8,
    ) !void {
        var text_start: usize = 0;
        var i: usize = 0;
        while (i < text.len) {
            const is_http = std.mem.startsWith(u8, text[i..], "http://") or
                std.mem.startsWith(u8, text[i..], "https://");
            if (is_http) {
                try self.connect_api_append_text_segment(segments, text[text_start..i]);
                var end = i;
                while (end < text.len and !is_connect_api_whitespace(text[end])) : (end += 1) {}
                const link = try self.connect_api_create_object("ConnectApi.LinkSegment");
                try link.fields.put(self.arena, "url", Value{ .string = text[i..end] });
                try self.connect_api_append_output_segment(segments, link);
                i = end;
                text_start = end;
                continue;
            }

            if (text[i] == '#' and i + 1 < text.len and is_connect_api_hashtag_char(text[i + 1])) {
                try self.connect_api_append_text_segment(segments, text[text_start..i]);
                var end = i + 1;
                while (end < text.len and is_connect_api_hashtag_char(text[end])) : (end += 1) {}
                const hashtag = try self.connect_api_create_object("ConnectApi.HashtagSegment");
                try hashtag.fields.put(self.arena, "tag", Value{ .string = text[i + 1 .. end] });
                try self.connect_api_append_output_segment(segments, hashtag);
                i = end;
                text_start = end;
                continue;
            }

            i += 1;
        }

        try self.connect_api_append_text_segment(segments, text[text_start..]);
    }

    fn connect_api_build_output_segments(
        self: *Evaluator,
        message_segments: Value,
    ) !*types.ListValue {
        const output = try self.arena.create(types.ListValue);
        output.* = .{};
        if (message_segments != .list) return output;

        for (message_segments.list.items.items) |segment_input| {
            if (segment_input != .object) continue;
            const class_name = segment_input.object.class_name;

            if (connect_api_class_name_equals(class_name, "TextSegmentInput")) {
                const text = utils.sobject_get(
                    &segment_input.object.fields,
                    "text",
                ) orelse Value.null_val;
                if (text == .string) try self.connect_api_append_parsed_text(output, text.string);
                continue;
            }

            try self.connect_api_append_non_text_segment_input(
                output,
                segment_input.object,
                class_name,
            );
        }

        return output;
    }

    fn connect_api_append_non_text_segment_input(
        self: *Evaluator,
        output: *types.ListValue,
        input: *types.ObjectInstance,
        class_name: []const u8,
    ) !void {
        if (connect_api_class_name_equals(class_name, "MentionSegmentInput")) {
            try self.connect_api_append_mention_segment_input(output, input);
            return;
        }

        if (connect_api_class_name_equals(class_name, "LinkSegmentInput")) {
            const url = utils.sobject_get(&input.fields, "url") orelse Value.null_val;
            if (url == .string) {
                const link = try self.connect_api_create_object("ConnectApi.LinkSegment");
                try link.fields.put(self.arena, "url", url);
                try self.connect_api_append_output_segment(output, link);
            }
            return;
        }

        if (connect_api_class_name_equals(class_name, "HashtagSegmentInput")) {
            const tag = utils.sobject_get(&input.fields, "tag") orelse Value.null_val;
            if (tag == .string) {
                const hashtag = try self.connect_api_create_object("ConnectApi.HashtagSegment");
                try hashtag.fields.put(self.arena, "tag", tag);
                try self.connect_api_append_output_segment(output, hashtag);
            }
            return;
        }

        if (connect_api_class_name_equals(class_name, "MarkupBeginSegmentInput")) {
            try self.connect_api_append_markup_segment_input(
                output,
                input,
                "ConnectApi.MarkupBeginSegment",
            );
            return;
        }

        if (connect_api_class_name_equals(class_name, "MarkupEndSegmentInput")) {
            try self.connect_api_append_markup_segment_input(
                output,
                input,
                "ConnectApi.MarkupEndSegment",
            );
            return;
        }

        if (connect_api_class_name_equals(class_name, "EntityLinkSegmentInput")) {
            const entity = try self.connect_api_create_object("ConnectApi.EntityLinkSegment");
            if (utils.sobject_get(&input.fields, "entityId")) |entity_id| {
                try entity.fields.put(self.arena, "record", entity_id);
            }
            try self.connect_api_append_output_segment(output, entity);
            return;
        }

        if (connect_api_class_name_equals(class_name, "InlineImageSegmentInput")) {
            try self.connect_api_append_inline_image_segment_input(output, input);
        }
    }

    fn connect_api_append_mention_segment_input(
        self: *Evaluator,
        output: *types.ListValue,
        input: *types.ObjectInstance,
    ) !void {
        const mention_id = utils.sobject_get(&input.fields, "id") orelse Value.null_val;
        if (mention_id != .string) return;
        if (!self.is_connect_api_mention_id(mention_id.string)) {
            const exc = try self.arena.create(types.ObjectInstance);
            exc.* = .{ .class_name = "ConnectApi.ConnectApiException" };
            try exc.fields.put(
                self.arena,
                "message",
                Value{ .string = "Only user and group IDs may be used in inline mentions." },
            );
            self.pending_exception = Value{ .object = exc };
            return error.ApexException;
        }
        const mention = try self.connect_api_create_object("ConnectApi.MentionSegment");
        try mention.fields.put(
            self.arena,
            "record",
            try self.connect_api_create_record_ref(mention_id.string),
        );
        try self.connect_api_append_output_segment(output, mention);
    }

    fn connect_api_append_markup_segment_input(
        self: *Evaluator,
        output: *types.ListValue,
        input: *types.ObjectInstance,
        output_class_name: []const u8,
    ) !void {
        const markup = try self.connect_api_create_object(output_class_name);
        if (utils.sobject_get(&input.fields, "markupType")) |markup_type| {
            try markup.fields.put(self.arena, "markupType", markup_type);
        }
        try self.connect_api_append_output_segment(output, markup);
    }

    fn connect_api_append_inline_image_segment_input(
        self: *Evaluator,
        output: *types.ListValue,
        input: *types.ObjectInstance,
    ) !void {
        const image = try self.connect_api_create_object("ConnectApi.InlineImageSegment");
        const thumbnails = try self.connect_api_create_object("ConnectApi.InlineImageThumbnails");
        if (utils.sobject_get(&input.fields, "fileId")) |file_id| {
            try thumbnails.fields.put(self.arena, "fileId", file_id);
        }
        try image.fields.put(self.arena, "thumbnails", Value{ .object = thumbnails });
        if (utils.sobject_get(&input.fields, "altText")) |alt_text| {
            try image.fields.put(self.arena, "altText", alt_text);
        }
        try self.connect_api_append_output_segment(output, image);
    }

    fn connect_api_render_body_text(
        self: *Evaluator,
        output_segments: *types.ListValue,
    ) ![]const u8 {
        var buf: std.ArrayListUnmanaged(u8) = .empty;
        for (output_segments.items.items) |segment| {
            if (segment != .object) continue;
            const class_name = segment.object.class_name;
            if (std.ascii.eqlIgnoreCase(class_name, "ConnectApi.TextSegment")) {
                if (utils.sobject_get(&segment.object.fields, "text")) |text| {
                    if (text == .string) try buf.appendSlice(self.arena, text.string);
                }
                continue;
            }
            if (std.ascii.eqlIgnoreCase(class_name, "ConnectApi.LinkSegment")) {
                if (utils.sobject_get(&segment.object.fields, "url")) |url| {
                    if (url == .string) try buf.appendSlice(self.arena, url.string);
                }
                continue;
            }
            if (std.ascii.eqlIgnoreCase(class_name, "ConnectApi.HashtagSegment")) {
                if (utils.sobject_get(&segment.object.fields, "tag")) |tag| {
                    if (tag == .string) {
                        try buf.append(self.arena, '#');
                        try buf.appendSlice(self.arena, tag.string);
                    }
                }
                continue;
            }
            if (std.ascii.eqlIgnoreCase(class_name, "ConnectApi.MentionSegment")) {
                if (utils.sobject_get(&segment.object.fields, "record")) |record| {
                    if (record == .object) {
                        if (utils.sobject_get(&record.object.fields, "id")) |record_id| {
                            if (record_id == .string) {
                                try buf.append(self.arena, '{');
                                try buf.appendSlice(self.arena, record_id.string);
                                try buf.append(self.arena, '}');
                            }
                        }
                    }
                }
                continue;
            }
            if (std.ascii.eqlIgnoreCase(class_name, "ConnectApi.MarkupBeginSegment") or
                std.ascii.eqlIgnoreCase(class_name, "ConnectApi.MarkupEndSegment"))
            {
                try append_connect_api_markup_tag(self.arena, &buf, segment.object, class_name);
                continue;
            }
            if (std.ascii.eqlIgnoreCase(class_name, "ConnectApi.InlineImageSegment")) {
                try append_connect_api_inline_image(self.arena, &buf, segment.object);
                continue;
            }
            if (std.ascii.eqlIgnoreCase(class_name, "ConnectApi.EntityLinkSegment")) {
                if (utils.sobject_get(&segment.object.fields, "text")) |text| {
                    if (text == .string) try buf.appendSlice(self.arena, text.string);
                }
            }
        }
        return buf.items;
    }

    /// `connect_api_render_body_text` の MarkupBegin/End 分岐。
    /// `<tag>` / `</tag>` を buffer に追記する。
    fn append_connect_api_markup_tag(
        arena: std.mem.Allocator,
        buf: *std.ArrayListUnmanaged(u8),
        obj: *types.ObjectInstance,
        class_name: []const u8,
    ) !void {
        const markup_type = utils.sobject_get(&obj.fields, "markupType") orelse Value.null_val;
        const tag_name = connect_api_markup_tag(markup_type) orelse return;
        if (std.ascii.eqlIgnoreCase(class_name, "ConnectApi.MarkupBeginSegment")) {
            try buf.appendSlice(arena, "<");
            try buf.appendSlice(arena, tag_name);
            try buf.appendSlice(arena, ">");
        } else {
            try buf.appendSlice(arena, "</");
            try buf.appendSlice(arena, tag_name);
            try buf.appendSlice(arena, ">");
        }
    }

    /// `connect_api_render_body_text` の InlineImage 分岐。
    /// `thumbnails.fileId` が文字列なら `"image: <id>"` を buffer に追記。
    fn append_connect_api_inline_image(
        arena: std.mem.Allocator,
        buf: *std.ArrayListUnmanaged(u8),
        obj: *types.ObjectInstance,
    ) !void {
        const thumbs = utils.sobject_get(&obj.fields, "thumbnails") orelse return;
        if (thumbs != .object) return;
        const file_id = utils.sobject_get(&thumbs.object.fields, "fileId") orelse return;
        if (file_id != .string) return;
        try buf.appendSlice(arena, "image: ");
        try buf.appendSlice(arena, file_id.string);
    }

    fn connect_api_extract_message_segments(
        self: *Evaluator,
        value: Value,
        depth: u8,
    ) ?Value {
        if (depth == 0) return null;
        switch (value) {
            .list => return value,
            .object => |obj| {
                if (utils.sobject_get(&obj.fields, "messageSegments")) |segments| {
                    if (segments == .list) return segments;
                }
                for (obj.fields.values()) |field_value| {
                    if (self.connect_api_extract_message_segments(
                        field_value,
                        depth - 1,
                    )) |segments| {
                        return segments;
                    }
                }
                return null;
            },
            else => return null,
        }
    }

    fn connect_api_create_feed_body(self: *Evaluator, message_segments: Value) !Value {
        const output_segments = try self.connect_api_build_output_segments(message_segments);
        const body_text = try self.connect_api_render_body_text(output_segments);
        const body = try self.connect_api_create_object("ConnectApi.FeedBody");
        try body.fields.put(self.arena, "messageSegments", Value{ .list = output_segments });
        try body.fields.put(self.arena, "text", Value{ .string = body_text });
        return Value{ .object = body };
    }

    fn connect_api_persist_feed_item(
        self: *Evaluator,
        parent_id: Value,
        body_value: Value,
    ) ![]const u8 {
        const feed_item = try self.arena.create(types.SObject);
        feed_item.* = .{ .type_name = "FeedItem" };
        if (parent_id == .string) {
            try feed_item.fields.put(self.arena, "ParentId", parent_id);
        } else if (parent_id != .null_val) {
            try feed_item.fields.put(
                self.arena,
                "ParentId",
                Value{ .string = try utils.coerce_to_string(parent_id, self.arena) },
            );
        }
        if (body_value == .object) {
            if (utils.sobject_get(&body_value.object.fields, "text")) |body_text| {
                if (body_text == .string) {
                    try feed_item.fields.put(self.arena, "Body", body_text);
                }
            }
        }
        try self.insert_record(feed_item);
        return feed_item.id orelse "";
    }

    fn handle_connect_api_namespace(
        self: *Evaluator,
        namespace: []const u8,
        method: []const u8,
        args: []const Value,
    ) !?Value {
        if (!self.see_all_data) {
            const exc = try self.arena.create(types.ObjectInstance);
            exc.* = .{ .class_name = "UnsupportedOperationException" };
            try exc.fields.put(
                self.arena,
                "message",
                Value{ .string = "ConnectApi is not supported in data-siloed tests" },
            );
            self.pending_exception = Value{ .object = exc };
            return error.ApexException;
        }

        if (!std.ascii.eqlIgnoreCase(namespace, "ChatterFeeds")) return Value.null_val;

        if (std.ascii.eqlIgnoreCase(method, "postFeedElement")) {
            var subject_id: Value = Value.null_val;
            var message_segments: Value = Value.null_val;

            if (args.len >= 2 and args[1] == .object) {
                subject_id = utils.sobject_get(&args[1].object.fields, "subjectId") orelse
                    Value.null_val;
                message_segments = self.connect_api_extract_message_segments(args[1], 4) orelse
                    Value.null_val;
            } else if (args.len >= 4) {
                subject_id = args[1];
                const text_segments = try self.arena.create(types.ListValue);
                text_segments.* = .{};
                const text_segment = try self.connect_api_create_object(
                    "ConnectApi.TextSegmentInput",
                );
                const text_value = switch (args[3]) {
                    .string => args[3].string,
                    else => try utils.coerce_to_string(args[3], self.arena),
                };
                try text_segment.fields.put(self.arena, "text", Value{ .string = text_value });
                try text_segments.items.append(self.arena, Value{ .object = text_segment });
                message_segments = Value{ .list = text_segments };
            }

            const body_value = try self.connect_api_create_feed_body(message_segments);
            const feed_id = try self.connect_api_persist_feed_item(subject_id, body_value);
            const feed_element = try self.connect_api_create_object("ConnectApi.FeedElement");
            try feed_element.fields.put(self.arena, "id", Value{ .string = feed_id });
            try feed_element.fields.put(self.arena, "body", body_value);
            return Value{ .object = feed_element };
        }

        if (std.ascii.eqlIgnoreCase(method, "postCommentToFeedElement")) {
            var message_segments: Value = Value.null_val;
            if (args.len >= 3 and args[2] == .object) {
                message_segments = self.connect_api_extract_message_segments(
                    args[2],
                    4,
                ) orelse Value.null_val;
            }
            const body_value = try self.connect_api_create_feed_body(message_segments);
            const comment = try self.connect_api_create_object("ConnectApi.Comment");
            try comment.fields.put(self.arena, "id", Value{ .string = try self.alloc_id() });
            try comment.fields.put(self.arena, "body", body_value);
            return Value{ .object = comment };
        }

        return Value.null_val;
    }

    fn eval_instance_method(
        self: *Evaluator,
        obj: Value,
        method: []const u8,
        args: []const Value,
        current_env: *Env,
    ) anyerror!Value {
        if (obj == .null_val) {
            try self.throw_null_pointer_exception();
            return error.ApexException;
        }
        if (try self.eval_search_object_instance_method(obj, method, args)) |result| return result;
        if (try self.eval_primitive_scalar_instance_method(obj, method)) |result| return result;
        if (try self.eval_http_send_instance_method(obj, method, args)) |result| return result;
        if (try self.eval_type_instance_method(obj, method)) |result| return result;
        if (try self.eval_stub_provider_instance_method(obj, method, args)) |result| return result;
        if (try self.eval_json_parser_instance_method(obj, method, args)) |result| return result;
        if (try self.eval_metadata_framework_instance_method(obj, method, args)) |result| {
            return result;
        }
        if (try self.eval_time_instance_method(obj, method)) |result| return result;
        if (try self.eval_date_like_instance_method(obj, method, args)) |result| return result;
        if (try self.eval_field_expression_matching_method(obj, method, args)) |result| {
            return result;
        }
        if (try self.eval_user_defined_object_instance_method(
            obj,
            method,
            args,
            current_env,
        )) |result| {
            return result;
        }
        if (try self.eval_builtin_instance_dispatch(obj, method, args)) |result| return result;
        if (try self.eval_s_object_instance_method(obj, method, args)) |result| return result;
        if (try self.eval_collection_or_string_instance_method(obj, method, args)) |result| {
            return result;
        }
        return try self.eval_object_class_instance_method(obj, method, args);
    }

    fn eval_search_object_instance_method(
        self: *Evaluator,
        obj: Value,
        method: []const u8,
        args: []const Value,
    ) anyerror!?Value {
        if (!(obj == .object and
            (std.ascii.eqlIgnoreCase(obj.object.class_name, "Search") or
                std.ascii.eqlIgnoreCase(obj.object.class_name, "System.Search")) and
            std.ascii.eqlIgnoreCase(method, "query")))
        {
            return null;
        }
        if (args.len > 0 and args[0] == .string) return try self.execute_sosl(args[0].string);
        const outer = try self.arena.create(types.ListValue);
        outer.* = .{};
        return Value{ .list = outer };
    }

    fn eval_field_expression_matching_method(
        self: *Evaluator,
        obj: Value,
        method: []const u8,
        args: []const Value,
    ) !?Value {
        if (!(obj == .object and
            std.ascii.eqlIgnoreCase(method, "isMatching") and
            args.len > 0 and
            field_expression_class_name(obj.object.class_name)))
        {
            return null;
        }
        const operant = obj.object.fields.get("operant") orelse Value.null_val;
        const values = obj.object.fields.get("values") orelse Value.null_val;
        if (!(operant == .string and std.ascii.eqlIgnoreCase(operant.string, "IN_SET") and
            values == .set))
        {
            return null;
        }
        return Value{ .boolean = self.field_expression_set_contains(values.set, args[0]) };
    }

    fn field_expression_class_name(class_name: []const u8) bool {
        return std.ascii.eqlIgnoreCase(class_name, "FieldExpression") or
            std.ascii.endsWithIgnoreCase(class_name, ".FieldExpression");
    }

    fn field_expression_set_contains(
        self: *Evaluator,
        values: *types.SetValue,
        field_value: Value,
    ) bool {
        if (field_value == .null_val or field_value == .string) {
            if (self.find_set_entry_key(values, field_value) != null) return true;
        }
        if (field_value == .string) {
            const lowered = std.ascii.allocLowerString(self.arena, field_value.string) catch
                field_value.string;
            if (self.find_set_entry_key(values, Value{ .string = lowered }) != null) return true;
        }
        return false;
    }

    fn eval_metadata_framework_instance_method(
        self: *Evaluator,
        obj: Value,
        method: []const u8,
        args: []const Value,
    ) !?Value {
        if (!(obj == .object and
            std.ascii.eqlIgnoreCase(obj.object.class_name, "Metadata.DeployContainer") and
            std.ascii.eqlIgnoreCase(method, "addMetadata")))
        {
            return null;
        }
        if (args.len > 0) {
            const items = try self.ensure_object_list_field(obj.object, "metadata");
            try items.items.append(self.arena, args[0]);
        }
        return Value.null_val;
    }

    fn ensure_object_list_field(
        self: *Evaluator,
        instance: *types.ObjectInstance,
        field_name: []const u8,
    ) !*types.ListValue {
        if (instance.fields.get(field_name)) |existing| {
            if (existing == .list) return existing.list;
        }
        const list = try self.arena.create(types.ListValue);
        list.* = .{};
        try instance.fields.put(self.arena, field_name, Value{ .list = list });
        return list;
    }

    fn eval_primitive_scalar_instance_method(
        self: *Evaluator,
        obj: Value,
        method: []const u8,
    ) anyerror!?Value {
        if (obj == .boolean and std.ascii.eqlIgnoreCase(method, "toString")) {
            return Value{ .string = if (obj.boolean) "true" else "false" };
        }
        if (obj == .boolean and std.ascii.eqlIgnoreCase(method, "hashCode")) {
            return Value{ .integer = if (obj.boolean) 1231 else 1237 };
        }
        if (obj == .integer and std.ascii.eqlIgnoreCase(method, "toString")) {
            return Value{ .string = try utils.coerce_to_string(obj, self.arena) };
        }
        if (obj == .integer and std.ascii.eqlIgnoreCase(method, "hashCode")) return obj;
        if (obj == .long and std.ascii.eqlIgnoreCase(method, "toString")) {
            return Value{ .string = try utils.coerce_to_string(obj, self.arena) };
        }
        if (obj == .long and std.ascii.eqlIgnoreCase(method, "hashCode")) {
            return Value{ .integer = @intCast(obj.long) };
        }
        if (obj == .double and std.ascii.eqlIgnoreCase(method, "toString")) {
            return Value{ .string = try utils.coerce_to_string(obj, self.arena) };
        }
        if (obj == .double and std.ascii.eqlIgnoreCase(method, "hashCode")) {
            return Value{ .integer = @intFromFloat(obj.double) };
        }
        return null;
    }

    fn eval_http_send_instance_method(
        self: *Evaluator,
        obj: Value,
        method: []const u8,
        args: []const Value,
    ) anyerror!?Value {
        if (!(obj == .object and
            std.ascii.eqlIgnoreCase(method, "send") and
            (std.ascii.eqlIgnoreCase(obj.object.class_name, "Http") or
                std.ascii.eqlIgnoreCase(obj.object.class_name, "HttpRequest"))))
        {
            return null;
        }
        self.limits_callouts += 1;
        const mock = self.callout_mock orelse return null;
        if (mock != .object) return null;
        const mock_class = self.find_class(mock.object.class_name) orelse return null;
        const req_arg = if (args.len > 0) args[0] else Value.null_val;
        return try self.call_instance_method(mock_class, mock.object, "respond", &.{req_arg});
    }

    fn eval_type_instance_method(
        self: *Evaluator,
        obj: Value,
        method: []const u8,
    ) anyerror!?Value {
        if (try self.eval_type_name_instance_method(obj, method)) |result| return result;
        return try self.eval_type_new_instance_method(obj, method);
    }

    fn eval_type_name_instance_method(
        self: *Evaluator,
        obj: Value,
        method: []const u8,
    ) anyerror!?Value {
        _ = self;
        if (!(obj == .object and
            std.ascii.eqlIgnoreCase(obj.object.class_name, "Type") and
            (std.ascii.eqlIgnoreCase(method, "getName") or
                std.ascii.eqlIgnoreCase(method, "toString") or
                std.ascii.eqlIgnoreCase(method, "getSimpleName"))))
        {
            return null;
        }
        if (obj.object.fields.get("name")) |name| {
            if (name == .string) return name;
        }
        return Value.null_val;
    }

    fn eval_type_new_instance_method(
        self: *Evaluator,
        obj: Value,
        method: []const u8,
    ) anyerror!?Value {
        if (!(obj == .object and
            std.ascii.eqlIgnoreCase(obj.object.class_name, "Type") and
            std.ascii.eqlIgnoreCase(method, "newInstance")))
        {
            return null;
        }
        const type_name = type_name_from_value(obj);
        if (std.ascii.startsWithIgnoreCase(type_name, "Map")) {
            return try self.alloc_empty_map_value();
        }
        if (std.ascii.startsWithIgnoreCase(type_name, "List")) {
            return try self.alloc_empty_list_value();
        }
        if (std.ascii.startsWithIgnoreCase(type_name, "Set")) {
            return try self.alloc_empty_set_value();
        }
        if (self.is_s_object_type_name(type_name)) {
            const sob = try self.arena.create(types.SObject);
            sob.* = .{ .type_name = type_name };
            return Value{ .sobject = sob };
        }
        return try self.instantiate_class(type_name);
    }

    fn type_name_from_value(value: Value) []const u8 {
        if (value == .object) {
            if (std.ascii.eqlIgnoreCase(value.object.class_name, "Type")) {
                if (value.object.fields.get("name")) |name| {
                    if (name == .string) return name.string;
                }
            }
            return value.object.class_name;
        }
        return "Object";
    }

    fn alloc_empty_map_value(self: *Evaluator) anyerror!Value {
        const map = try self.arena.create(types.MapValue);
        map.* = .{};
        return Value{ .map = map };
    }

    fn alloc_empty_list_value(self: *Evaluator) anyerror!Value {
        const list = try self.arena.create(types.ListValue);
        list.* = .{};
        return Value{ .list = list };
    }

    fn alloc_empty_set_value(self: *Evaluator) anyerror!Value {
        const set = try self.arena.create(types.SetValue);
        set.* = .{};
        return Value{ .set = set };
    }

    fn eval_stub_provider_instance_method(
        self: *Evaluator,
        obj: Value,
        method: []const u8,
        args: []const Value,
    ) anyerror!?Value {
        if (obj != .object) return null;
        const provider = obj.object.fields.get("__stubProvider__") orelse return null;
        if (provider != .object) return null;
        const provider_class = self.find_class(provider.object.class_name) orelse return null;
        const stub_method = self.resolve_stub_provider_method_decl(
            obj.object.class_name,
            method,
            args,
        );
        if (stub_uses_default_object_method(method, args.len) and stub_method == null) {
            return null;
        }
        const handle_args = try self.build_stub_provider_handle_method_args(
            obj,
            method,
            args,
            stub_method,
        );
        return try self.call_instance_method(
            provider_class,
            provider.object,
            "handleMethodCall",
            &handle_args,
        );
    }

    fn resolve_stub_provider_method_decl(
        self: *Evaluator,
        class_name: []const u8,
        method: []const u8,
        args: []const Value,
    ) ?*ast.MethodDecl {
        const stub_class = self.find_class(class_name) orelse return null;
        return self.find_method_in_hierarchy_typed(null, stub_class, method, args) orelse
            self.find_method_in_hierarchy(null, stub_class, method, args.len);
    }

    fn stub_uses_default_object_method(method: []const u8, arg_len: usize) bool {
        if (arg_len == 0) {
            return std.ascii.eqlIgnoreCase(method, "toString") or
                std.ascii.eqlIgnoreCase(method, "hashCode");
        }
        return arg_len == 1 and std.ascii.eqlIgnoreCase(method, "equals");
    }

    fn build_stub_provider_handle_method_args(
        self: *Evaluator,
        obj: Value,
        method: []const u8,
        args: []const Value,
        stub_method: ?*ast.MethodDecl,
    ) anyerror![6]Value {
        const args_list = try self.arena.create(types.ListValue);
        args_list.* = .{};
        for (args) |arg| try args_list.items.append(self.arena, arg);

        const type_list = try self.arena.create(types.ListValue);
        type_list.* = .{};
        for (args, 0..) |arg, index| {
            const type_obj = try self.arena.create(types.ObjectInstance);
            type_obj.* = .{ .class_name = "Type" };
            try type_obj.fields.put(
                self.arena,
                "name",
                Value{ .string = self.stub_provider_arg_type_name(arg, index, stub_method) },
            );
            try type_list.items.append(self.arena, Value{ .object = type_obj });
        }

        const name_list = try self.arena.create(types.ListValue);
        name_list.* = .{};
        if (stub_method) |method_decl| {
            for (method_decl.params) |param| {
                try name_list.items.append(self.arena, Value{ .string = param.name });
            }
        }

        return .{
            obj,
            Value{ .string = method },
            Value.null_val,
            Value{ .list = type_list },
            Value{ .list = name_list },
            Value{ .list = args_list },
        };
    }

    fn stub_provider_arg_type_name(
        self: *Evaluator,
        arg: Value,
        index: usize,
        stub_method: ?*ast.MethodDecl,
    ) []const u8 {
        if (stub_method) |method_decl| {
            if (index < method_decl.params.len) {
                return self.render_type_ref(method_decl.params[index].type_ref);
            }
        }
        return switch (arg) {
            .string => "String",
            .integer => "Integer",
            .double => "Double",
            .boolean => "Boolean",
            .list => "List",
            .map => "Map",
            .set => "Set",
            .sobject => "SObject",
            .object => |object| object.class_name,
            .null_val => "Object",
            else => "Object",
        };
    }

    fn eval_json_parser_instance_method(
        self: *Evaluator,
        obj: Value,
        method: []const u8,
        args: []const Value,
    ) anyerror!?Value {
        if (!(obj == .object and
            std.ascii.eqlIgnoreCase(obj.object.class_name, "JSONParser")))
        {
            return null;
        }
        const body = json_parser_body(obj.object);
        if (std.ascii.eqlIgnoreCase(method, "nextToken")) {
            return try self.eval_json_parser_next_token(obj.object, body);
        }
        if (std.ascii.eqlIgnoreCase(method, "getCurrentToken")) {
            return obj.object.fields.get("__token__") orelse Value.null_val;
        }
        if (std.ascii.eqlIgnoreCase(method, "getCurrentName")) {
            const token_value = obj.object.fields.get("__token__") orelse Value.null_val;
            if (token_value == .string and
                std.ascii.eqlIgnoreCase(token_value.string, "FIELD_NAME"))
            {
                return obj.object.fields.get("__text__") orelse Value.null_val;
            }
            return Value.null_val;
        }
        if (std.ascii.eqlIgnoreCase(method, "getText")) {
            return obj.object.fields.get("__text__") orelse Value{ .string = "" };
        }
        if (std.ascii.eqlIgnoreCase(method, "readValueAs")) {
            return try self.eval_json_parser_read_value_as(obj.object, body, args);
        }
        return null;
    }

    fn json_parser_body(parser: *types.ObjectInstance) ?[]const u8 {
        const body_value = parser.fields.get("__json_body__") orelse return null;
        return if (body_value == .string) body_value.string else null;
    }

    fn stored_json_parser_position(parser: *types.ObjectInstance, require_positive: bool) usize {
        const pos_value = parser.fields.get("__pos__") orelse return 0;
        if (pos_value != .integer) return 0;
        if (require_positive and pos_value.integer <= 0) return 0;
        return @intCast(@as(u64, @bitCast(pos_value.integer)));
    }

    fn skip_json_parser_trivia(body: []const u8, start: usize) usize {
        var pos = start;
        while (pos < body.len and
            (body[pos] == ' ' or
                body[pos] == '\t' or
                body[pos] == '\n' or
                body[pos] == '\r' or
                body[pos] == ','))
        {
            pos += 1;
        }
        return pos;
    }

    fn set_json_parser_token(
        self: *Evaluator,
        parser: *types.ObjectInstance,
        token_name: []const u8,
        text: []const u8,
    ) anyerror!void {
        try parser.fields.put(self.arena, "__token__", Value{ .string = token_name });
        try parser.fields.put(self.arena, "__text__", Value{ .string = text });
    }

    fn advance_json_parser_string_token(
        self: *Evaluator,
        parser: *types.ObjectInstance,
        body: []const u8,
        start: usize,
    ) anyerror!usize {
        var pos = start + 1;
        while (pos < body.len and body[pos] != '"') : (pos += 1) {
            if (body[pos] == '\\') pos += 1;
        }
        const text = body[start + 1 .. pos];
        if (pos < body.len) pos += 1;
        var peek = pos;
        while (peek < body.len and (body[peek] == ' ' or body[peek] == '\t')) : (peek += 1) {}
        if (peek < body.len and body[peek] == ':') {
            try self.set_json_parser_token(parser, "FIELD_NAME", text);
            return peek + 1;
        }
        try self.set_json_parser_token(parser, "VALUE_STRING", text);
        return pos;
    }

    fn advance_json_parser_boolean_token(
        self: *Evaluator,
        parser: *types.ObjectInstance,
        body: []const u8,
        start: usize,
    ) anyerror!usize {
        if (std.mem.startsWith(u8, body[start..], "true")) {
            try self.set_json_parser_token(parser, "VALUE_TRUE", "true");
            return start + 4;
        }
        try self.set_json_parser_token(parser, "VALUE_FALSE", "false");
        return start + 5;
    }

    fn advance_json_parser_number_token(
        self: *Evaluator,
        parser: *types.ObjectInstance,
        body: []const u8,
        start: usize,
    ) anyerror!usize {
        var pos = start;
        while (pos < body.len and
            (std.ascii.isDigit(body[pos]) or
                body[pos] == '.' or
                body[pos] == '-' or
                body[pos] == 'e' or
                body[pos] == 'E' or
                body[pos] == '+'))
        {
            pos += 1;
        }
        const number_text = body[start..pos];
        const token_name = if (std.mem.indexOfAny(u8, number_text, ".eE") != null)
            "VALUE_NUMBER_FLOAT"
        else
            "VALUE_NUMBER_INT";
        try self.set_json_parser_token(parser, token_name, number_text);
        return pos;
    }

    fn eval_json_parser_next_token(
        self: *Evaluator,
        parser: *types.ObjectInstance,
        body: ?[]const u8,
    ) anyerror!Value {
        const json_body = body orelse return Value.null_val;
        var pos = skip_json_parser_trivia(json_body, stored_json_parser_position(parser, false));
        if (pos >= json_body.len) {
            try parser.fields.put(self.arena, "__token__", Value.null_val);
            return Value.null_val;
        }
        switch (json_body[pos]) {
            '{' => {
                try self.set_json_parser_token(parser, "START_OBJECT", "{");
                pos += 1;
            },
            '}' => {
                try self.set_json_parser_token(parser, "END_OBJECT", "}");
                pos += 1;
            },
            '[' => {
                try self.set_json_parser_token(parser, "START_ARRAY", "[");
                pos += 1;
            },
            ']' => {
                try self.set_json_parser_token(parser, "END_ARRAY", "]");
                pos += 1;
            },
            '"' => pos = try self.advance_json_parser_string_token(parser, json_body, pos),
            't', 'f' => pos = try self.advance_json_parser_boolean_token(parser, json_body, pos),
            'n' => {
                try self.set_json_parser_token(parser, "VALUE_NULL", "null");
                pos += 4;
            },
            else => {
                if (std.ascii.isDigit(json_body[pos]) or json_body[pos] == '-') {
                    pos = try self.advance_json_parser_number_token(parser, json_body, pos);
                } else {
                    pos += 1;
                }
            },
        }
        try parser.fields.put(self.arena, "__pos__", Value{ .integer = @intCast(pos) });
        return parser.fields.get("__token__") orelse Value.null_val;
    }

    fn eval_json_parser_read_value_as(
        self: *Evaluator,
        parser: *types.ObjectInstance,
        body: ?[]const u8,
        args: []const Value,
    ) anyerror!Value {
        const json_body = body orelse return Value.null_val;
        const pos = stored_json_parser_position(parser, true);
        const start = if (pos > 0) pos - 1 else 0;
        const type_name = if (args.len >= 1) type_name_from_value(args[0]) else "Object";
        if (self.parse_json_value(json_body[start..], type_name)) |value| return value;
        return Value.null_val;
    }

    fn eval_time_instance_method(
        self: *Evaluator,
        obj: Value,
        method: []const u8,
    ) anyerror!?Value {
        _ = self;
        if (!(obj == .object and std.ascii.eqlIgnoreCase(obj.object.class_name, "Time"))) {
            return null;
        }
        if (std.ascii.eqlIgnoreCase(method, "hour")) {
            return obj.object.fields.get("hour") orelse Value{ .integer = 0 };
        }
        if (std.ascii.eqlIgnoreCase(method, "minute")) {
            return obj.object.fields.get("minute") orelse Value{ .integer = 0 };
        }
        if (std.ascii.eqlIgnoreCase(method, "second")) {
            return obj.object.fields.get("second") orelse Value{ .integer = 0 };
        }
        if (std.ascii.eqlIgnoreCase(method, "millisecond")) {
            return obj.object.fields.get("millisecond") orelse Value{ .integer = 0 };
        }
        return null;
    }

    fn eval_date_like_instance_method(
        self: *Evaluator,
        obj: Value,
        method: []const u8,
        args: []const Value,
    ) anyerror!?Value {
        if (!(obj == .object and
            (std.ascii.eqlIgnoreCase(obj.object.class_name, "Date") or
                std.ascii.eqlIgnoreCase(obj.object.class_name, "Datetime"))))
        {
            return null;
        }
        const date_str = builtins.extract_date_string(obj) orelse return null;
        if (args.len == 0 and std.ascii.eqlIgnoreCase(method, "format")) {
            if (parse_iso_date(date_str)) |dt| {
                return try self.format_date_like_instance(obj.object.class_name, dt);
            }
        }
        const result = try self.eval_string_method(date_str, method, args);
        if (result != .string) return result;
        if (std.ascii.eqlIgnoreCase(method, "date") or std.ascii.eqlIgnoreCase(method, "dateGmt")) {
            return try builtins.make_date_value(self.arena, result.string);
        }
        if (std.ascii.eqlIgnoreCase(method, "addDays") or
            std.ascii.eqlIgnoreCase(method, "addMonths") or
            std.ascii.eqlIgnoreCase(method, "addYears") or
            std.ascii.eqlIgnoreCase(method, "addHours") or
            std.ascii.eqlIgnoreCase(method, "addMinutes") or
            std.ascii.eqlIgnoreCase(method, "addSeconds"))
        {
            if (std.ascii.eqlIgnoreCase(obj.object.class_name, "Date")) {
                return try builtins.make_date_value(self.arena, result.string);
            }
            return try builtins.make_datetime_value(self.arena, result.string);
        }
        return result;
    }

    fn format_date_like_instance(
        self: *Evaluator,
        class_name: []const u8,
        dt: anytype,
    ) anyerror!Value {
        if (std.ascii.eqlIgnoreCase(class_name, "Date")) {
            return Value{ .string = try std.fmt.allocPrint(self.arena, "{d}/{d}/{d:0>4}", .{
                dt.m,
                dt.d,
                @as(u32, @intCast(dt.y)),
            }) };
        }
        const hour12: u8 = blk: {
            const h_mod = dt.h % 12;
            break :blk if (h_mod == 0) 12 else h_mod;
        };
        const am_pm: []const u8 = if (dt.h < 12) "AM" else "PM";
        return Value{ .string = try std.fmt.allocPrint(
            self.arena,
            "{d}/{d}/{d:0>4}, {d}:{d:0>2} {s}",
            .{
                dt.m,
                dt.d,
                @as(u32, @intCast(dt.y)),
                hour12,
                dt.mi,
                am_pm,
            },
        ) };
    }

    fn eval_user_defined_object_instance_method(
        self: *Evaluator,
        obj: Value,
        method: []const u8,
        args: []const Value,
        current_env: *Env,
    ) anyerror!?Value {
        if (obj != .object) return null;
        const class_decl = self.resolve_instance_dispatch_class(
            obj.object,
            current_env,
        ) orelse return null;
        const method_decl = self.find_method_in_hierarchy_typed(
            null,
            class_decl,
            method,
            args,
        ) orelse
            self.find_method_in_hierarchy(null, class_decl, method, args.len);
        if (method_decl != null) {
            return try self.call_instance_method(class_decl, obj.object, method, args);
        }
        const shadow_decl = self.find_shadowed_inner_dispatch_class(
            class_decl,
            obj.object.class_name,
            method,
            args,
        ) orelse {
            return null;
        };
        return try self.call_instance_method(shadow_decl, obj.object, method, args);
    }

    fn resolve_instance_dispatch_class(
        self: *Evaluator,
        obj: *types.ObjectInstance,
        current_env: *Env,
    ) ?*ast.ClassDecl {
        if (current_env.get_this()) |this_val| {
            if (this_val == .object and this_val.object == obj) {
                if (self.current_class) |current_class_name| {
                    if (self.find_class(current_class_name)) |owner_decl| return owner_decl;
                }
            }
        }
        return self.find_class(obj.class_name);
    }

    fn find_shadowed_inner_dispatch_class(
        self: *Evaluator,
        current_decl: *ast.ClassDecl,
        class_name: []const u8,
        method: []const u8,
        args: []const Value,
    ) ?*ast.ClassDecl {
        var class_iter = self.classes.iterator();
        while (class_iter.next()) |entry| {
            const class_decl = entry.value_ptr.*;
            for (class_decl.members) |member| {
                switch (member) {
                    .class_decl => |inner_decl| {
                        if (!std.ascii.eqlIgnoreCase(inner_decl.name, class_name) or
                            inner_decl == current_decl) continue;
                        const inner_method = self.find_method_in_hierarchy_typed(
                            null,
                            inner_decl,
                            method,
                            args,
                        ) orelse
                            self.find_method_in_hierarchy(null, inner_decl, method, args.len);
                        if (inner_method != null) return inner_decl;
                    },
                    else => {},
                }
            }
        }
        return null;
    }

    fn eval_builtin_instance_dispatch(
        self: *Evaluator,
        obj: Value,
        method: []const u8,
        args: []const Value,
    ) anyerror!?Value {
        var builtin_ctx = self.make_builtin_context();
        return try builtins.dispatch_instance(&builtin_ctx, obj, method, args);
    }

    fn eval_s_object_instance_method(
        self: *Evaluator,
        obj: Value,
        method: []const u8,
        args: []const Value,
    ) anyerror!?Value {
        if (obj != .sobject) return null;
        if (try self.eval_s_object_get_s_objects_method(
            obj.sobject,
            method,
            args,
        )) |result| return result;
        if (try self.eval_s_object_get_method(obj.sobject, method, args)) |result| return result;
        if (try self.eval_s_object_get_s_object_method(
            obj.sobject,
            method,
            args,
        )) |result| return result;
        if (try self.eval_s_object_put_method(obj.sobject, method, args)) |result| return result;
        if (try self.eval_s_object_clone_method(obj.sobject, method, args)) |result| return result;
        if (try self.eval_s_object_metadata_result_method(
            obj.sobject,
            method,
        )) |result| return result;
        if (try self.eval_s_object_populated_fields_method(
            obj.sobject,
            method,
        )) |result| return result;
        if (try self.eval_s_object_add_error_method(
            obj.sobject,
            method,
            args,
        )) |result| return result;
        return null;
    }

    fn s_object_field_name_from_arg(self: *Evaluator, arg: Value) anyerror![]const u8 {
        return if (arg == .string)
            arg.string
        else if (arg == .object) blk: {
            if (arg.object.fields.get("fieldName")) |name| {
                if (name == .string) break :blk name.string;
            }
            if (arg.object.fields.get("name")) |name| {
                if (name == .string) break :blk name.string;
            }
            break :blk try utils.coerce_to_string(arg, self.arena);
        } else try utils.coerce_to_string(arg, self.arena);
    }

    fn eval_s_object_get_s_objects_method(
        self: *Evaluator,
        sob: *types.SObject,
        method: []const u8,
        args: []const Value,
    ) anyerror!?Value {
        if (!(std.ascii.eqlIgnoreCase(method, "getSObjects") and
            args.len > 0 and
            args[0] == .string)) return null;
        if (utils.sobject_get(&sob.fields, args[0].string)) |raw| {
            if (self.relationship_records_value(raw)) |records| return records;
            return raw;
        }
        return try self.make_empty_list();
    }

    fn eval_s_object_get_method(
        self: *Evaluator,
        sob: *types.SObject,
        method: []const u8,
        args: []const Value,
    ) anyerror!?Value {
        if (!(std.ascii.eqlIgnoreCase(method, "get") and args.len > 0)) return null;
        const field_name = try self.s_object_field_name_from_arg(args[0]);
        if (self.get_s_object_field_value_case_insensitive(sob, field_name)) |value| return value;
        var builtin_ctx = self.make_builtin_context();
        if (builtins.sobject_field_exists(&builtin_ctx, sob, field_name)) return Value.null_val;
        return try self.throw_invalid_s_object_field(sob.type_name, field_name);
    }

    fn throw_invalid_s_object_field(
        self: *Evaluator,
        type_name: []const u8,
        field_name: []const u8,
    ) anyerror!Value {
        const message = try std.fmt.allocPrint(
            self.arena,
            "Invalid field {s} for {s}",
            .{ field_name, type_name },
        );
        return try self.throw_named_exception("System.SObjectException", message);
    }

    fn eval_s_object_get_s_object_method(
        self: *Evaluator,
        sob: *types.SObject,
        method: []const u8,
        args: []const Value,
    ) anyerror!?Value {
        if (!(std.ascii.eqlIgnoreCase(method, "getSObject") and args.len > 0)) return null;
        const raw_name = try self.s_object_field_name_from_arg(args[0]);
        if (self.get_s_object_field_value_case_insensitive(sob, raw_name)) |loaded| {
            if (loaded == .sobject) return loaded;
        }
        const relationship_name = if (std.mem.endsWith(u8, raw_name, "__c") or
            std.mem.endsWith(u8, raw_name, "Id"))
            self.fk_to_parent_ref(raw_name)
        else
            raw_name;
        if (!std.ascii.eqlIgnoreCase(relationship_name, raw_name)) {
            if (self.get_s_object_field_value_case_insensitive(sob, relationship_name)) |loaded| {
                if (loaded == .sobject) return loaded;
            }
        }
        const fk_field = if (std.mem.endsWith(u8, raw_name, "__c") or
            std.mem.endsWith(u8, raw_name, "Id"))
            raw_name
        else
            self.parent_ref_to_fk(raw_name);
        const fk_value = self.get_s_object_field_value_case_insensitive(
            sob,
            fk_field,
        ) orelse return Value.null_val;
        if (fk_value != .string) return Value.null_val;
        const target_type = self.resolve_s_object_target_type(
            sob,
            fk_field,
            fk_value.string,
        ) orelse return Value.null_val;
        if (self.find_record_by_id(target_type, fk_value.string)) |record| {
            if (record == .sobject) return record;
        }
        const related = try self.arena.create(types.SObject);
        related.* = .{ .type_name = target_type };
        related.id = fk_value.string;
        try related.fields.put(self.arena, "Id", fk_value);
        return Value{ .sobject = related };
    }

    fn resolve_s_object_target_type(
        self: *Evaluator,
        sob: *types.SObject,
        fk_field: []const u8,
        record_id: []const u8,
    ) ?[]const u8 {
        if (self.get_field_metadata(sob.type_name, fk_field)) |meta| {
            if (meta.reference_to) |reference_to| return reference_to;
        }
        if (self.find_record_type_by_id(record_id)) |record_type| return record_type;
        if (record_id.len >= 3) {
            const inferred = sobject_type_from_prefix(record_id[0..3]);
            if (!std.ascii.eqlIgnoreCase(inferred, "SObject")) return inferred;
        }
        return null;
    }

    fn eval_s_object_put_method(
        self: *Evaluator,
        sob: *types.SObject,
        method: []const u8,
        args: []const Value,
    ) anyerror!?Value {
        if (!(std.ascii.eqlIgnoreCase(method, "put") and args.len >= 2)) return null;
        const field_name = try self.s_object_field_name_from_arg(args[0]);
        var builtin_ctx = self.make_builtin_context();
        const normalized = try builtins.normalize_s_object_field_assignment(
            &builtin_ctx,
            sob,
            field_name,
            args[1],
        );
        try utils.sobject_put(&sob.fields, self.arena, field_name, normalized);
        if (std.ascii.eqlIgnoreCase(field_name, "Id") and normalized == .string) {
            sob.id = normalized.string;
        }
        return normalized;
    }

    fn eval_s_object_clone_method(
        self: *Evaluator,
        sob: *types.SObject,
        method: []const u8,
        args: []const Value,
    ) anyerror!?Value {
        if (!(std.ascii.eqlIgnoreCase(method, "clone") or
            std.ascii.eqlIgnoreCase(method, "deepClone"))) return null;
        const clone = try self.arena.create(types.SObject);
        clone.* = .{ .type_name = sob.type_name, .is_clone = true };
        const preserve_id = if (args.len >= 1 and args[0] == .boolean) args[0].boolean else true;
        if (preserve_id and sob.id != null) clone.id = sob.id;
        for (sob.fields.keys(), sob.fields.values()) |key, value| {
            if (!preserve_id and std.ascii.eqlIgnoreCase(key, "Id")) continue;
            try clone.fields.put(self.arena, key, value);
        }
        return Value{ .sobject = clone };
    }

    fn eval_s_object_metadata_result_method(
        self: *Evaluator,
        sob: *types.SObject,
        method: []const u8,
    ) anyerror!?Value {
        if (std.ascii.eqlIgnoreCase(method, "isClone")) return Value{ .boolean = sob.is_clone };
        if (std.ascii.eqlIgnoreCase(method, "getSObjectType")) {
            return try self.schema_s_object_type_value(sob.type_name);
        }
        if (std.ascii.eqlIgnoreCase(method, "isSuccess")) {
            return utils.sobject_get(&sob.fields, "success") orelse
                utils.sobject_get(&sob.fields, "isSuccess") orelse Value{ .boolean = true };
        }
        if (std.ascii.eqlIgnoreCase(method, "isCreated")) {
            return utils.sobject_get(&sob.fields, "created") orelse
                utils.sobject_get(&sob.fields, "isCreated") orelse Value{ .boolean = false };
        }
        if (std.ascii.eqlIgnoreCase(method, "getErrors")) {
            return utils.sobject_get(&sob.fields, "errors") orelse
                try self.make_empty_list();
        }
        if (std.ascii.eqlIgnoreCase(method, "hasErrors")) {
            if (utils.sobject_get(&sob.fields, "errors")) |errs_val| {
                if (errs_val == .list) {
                    return Value{ .boolean = errs_val.list.items.items.len > 0 };
                }
            }
            return Value{ .boolean = false };
        }
        if (std.ascii.eqlIgnoreCase(method, "getId")) {
            return utils.sobject_get(&sob.fields, "Id") orelse
                utils.sobject_get(&sob.fields, "id") orelse Value.null_val;
        }
        if (std.ascii.eqlIgnoreCase(method, "getMessage")) {
            return self.get_s_object_field_value_case_insensitive(sob, "message") orelse
                Value{ .string = "" };
        }
        if (std.ascii.eqlIgnoreCase(method, "getStatusCode")) {
            return self.get_s_object_field_value_case_insensitive(
                sob,
                "statusCode",
            ) orelse Value.null_val;
        }
        if (std.ascii.eqlIgnoreCase(method, "getFields")) {
            return self.get_s_object_field_value_case_insensitive(sob, "fields") orelse
                try self.make_empty_list();
        }
        return null;
    }

    fn eval_s_object_populated_fields_method(
        self: *Evaluator,
        sob: *types.SObject,
        method: []const u8,
    ) anyerror!?Value {
        if (!(std.ascii.eqlIgnoreCase(method, "getPopulatedFieldsAsMap"))) {
            return null;
        }
        const map = try self.arena.create(types.MapValue);
        map.* = .{};
        for (sob.fields.keys(), sob.fields.values()) |key, value| {
            if (value == .null_val) continue;
            if (std.ascii.eqlIgnoreCase(key, "errors")) continue;
            try map.entries.put(self.arena, key, value);
        }
        return Value{ .map = map };
    }

    fn eval_s_object_add_error_method(
        self: *Evaluator,
        sob: *types.SObject,
        method: []const u8,
        args: []const Value,
    ) anyerror!?Value {
        if (!(std.ascii.eqlIgnoreCase(method, "addError") and args.len > 0)) {
            return null;
        }
        const msg_val = if (args.len >= 2) args[1] else args[0];
        const err_obj = try self.arena.create(types.ObjectInstance);
        err_obj.* = .{ .class_name = "Database.Error" };
        try err_obj.fields.put(self.arena, "message", msg_val);
        try err_obj.fields.put(
            self.arena,
            "statusCode",
            Value{ .string = "FIELD_CUSTOM_VALIDATION_EXCEPTION" },
        );

        const fields_list = try self.arena.create(types.ListValue);
        fields_list.* = .{};
        if (args.len >= 2) {
            const field_name = try self.s_object_field_name_from_arg(args[0]);
            try fields_list.items.append(self.arena, Value{ .string = field_name });
            try err_obj.fields.put(self.arena, "field", Value{ .string = field_name });
        }
        try err_obj.fields.put(self.arena, "fields", Value{ .list = fields_list });

        var errors_list = try self.get_or_create_s_object_errors_list(sob);
        try errors_list.items.append(self.arena, Value{ .object = err_obj });
        try utils.sobject_put(&sob.fields, self.arena, "errors", Value{ .list = errors_list });
        return Value.void_val;
    }

    fn get_or_create_s_object_errors_list(
        self: *Evaluator,
        sob: *types.SObject,
    ) anyerror!*types.ListValue {
        if (utils.sobject_get(&sob.fields, "errors")) |existing| {
            if (existing == .list) return existing.list;
        }
        const list = try self.arena.create(types.ListValue);
        list.* = .{};
        return list;
    }

    fn eval_collection_or_string_instance_method(
        self: *Evaluator,
        obj: Value,
        method: []const u8,
        args: []const Value,
    ) anyerror!?Value {
        if (obj == .list) return try self.eval_list_method(obj.list, method, args);
        if (obj == .map) return try self.eval_map_method(obj.map, method, args);
        if (obj == .set) return try self.eval_set_method(obj.set, method, args);
        if (obj == .string) return try self.eval_string_method(obj.string, method, args);
        return null;
    }

    fn eval_object_class_instance_method(
        self: *Evaluator,
        obj: Value,
        method: []const u8,
        args: []const Value,
    ) anyerror!Value {
        if (obj == .object) {
            if (self.find_class(obj.object.class_name)) |class_decl| {
                return try self.call_instance_method(class_decl, obj.object, method, args);
            }
        }
        return Value.null_val;
    }

    fn eval_list_method(
        self: *Evaluator,
        list: *types.ListValue,
        method: []const u8,
        args: []const Value,
    ) !Value {
        if (std.ascii.eqlIgnoreCase(method, "iterator")) {
            return try self.eval_list_iterator(list);
        }
        if (std.ascii.eqlIgnoreCase(method, "toString")) {
            return try self.eval_list_to_string(list);
        }
        if (try self.eval_list_basic_method(list, method, args)) |result| return result;
        if (std.ascii.eqlIgnoreCase(method, "sort")) {
            try self.eval_list_sort(list, args);
            return .void_val;
        }
        if (std.ascii.eqlIgnoreCase(method, "clone") or
            std.ascii.eqlIgnoreCase(method, "deepClone"))
        {
            return try self.eval_list_clone(list, std.ascii.eqlIgnoreCase(method, "deepClone"));
        }
        if (std.ascii.eqlIgnoreCase(method, "indexOf") and args.len > 0) {
            for (list.items.items, 0..) |item, idx| {
                if (self.values_equal(item, args[0])) return Value{ .integer = @intCast(idx) };
            }
            return Value{ .integer = -1 };
        }
        if (std.ascii.eqlIgnoreCase(method, "getSObjectType")) {
            return try self.eval_list_s_object_type(list);
        }
        return Value.null_val;
    }

    fn eval_list_basic_method(
        self: *Evaluator,
        list: *types.ListValue,
        method: []const u8,
        args: []const Value,
    ) !?Value {
        if (std.ascii.eqlIgnoreCase(method, "add")) return try self.eval_list_add(list, args);
        if (std.ascii.eqlIgnoreCase(method, "hashCode")) {
            return Value{ .integer = try self.value_hash_code(Value{ .list = list }) };
        }
        if (std.ascii.eqlIgnoreCase(method, "equals") and args.len > 0) {
            return Value{ .boolean = self.values_equal(Value{ .list = list }, args[0]) };
        }
        if (std.ascii.eqlIgnoreCase(method, "size")) {
            return Value{ .integer = @intCast(list.items.items.len) };
        }
        if (std.ascii.eqlIgnoreCase(method, "isEmpty")) {
            return Value{ .boolean = list.items.items.len == 0 };
        }
        if (std.ascii.eqlIgnoreCase(method, "get") and args.len > 0 and args[0] == .integer) {
            if (args[0].integer < 0) return Value.null_val;
            const i: usize = @intCast(args[0].integer);
            return if (i < list.items.items.len) list.items.items[i] else Value.null_val;
        }
        if (std.ascii.eqlIgnoreCase(method, "set") and
            args.len >= 2 and
            args[0] == .integer)
        {
            if (args[0].integer >= 0) {
                const i: usize = @intCast(args[0].integer);
                if (i < list.items.items.len) list.items.items[i] = args[1];
            }
            return .void_val;
        }
        if (std.ascii.eqlIgnoreCase(method, "clear")) {
            list.items.items.len = 0;
            return .void_val;
        }
        if (std.ascii.eqlIgnoreCase(method, "contains") and args.len > 0) {
            for (list.items.items) |item| {
                if (self.values_equal(item, args[0])) return Value{ .boolean = true };
            }
            return Value{ .boolean = false };
        }
        if (std.ascii.eqlIgnoreCase(method, "remove") and
            args.len > 0 and
            args[0] == .integer)
        {
            if (args[0].integer < 0) return .void_val;
            const i: usize = @intCast(args[0].integer);
            return if (i < list.items.items.len) list.items.orderedRemove(i) else Value.void_val;
        }
        if (std.ascii.eqlIgnoreCase(method, "addAll") and args.len > 0) {
            try self.eval_list_add_all(list, args[0]);
            return .void_val;
        }
        return null;
    }

    fn eval_list_add(self: *Evaluator, list: *types.ListValue, args: []const Value) !Value {
        if (args.len >= 2 and args[0] == .integer) {
            if (args[0].integer < 0) return .void_val;
            const i: usize = @intCast(args[0].integer);
            if (i <= list.items.items.len) try list.items.insert(self.arena, i, args[1]);
            return .void_val;
        }
        if (args.len > 0) try list.items.append(self.arena, args[0]);
        return .void_val;
    }

    fn eval_list_add_all(self: *Evaluator, list: *types.ListValue, source: Value) !void {
        if (source == .list) {
            for (source.list.items.items) |item| try list.items.append(self.arena, item);
        } else if (source == .set) {
            for (source.set.entries.values()) |item| try list.items.append(self.arena, item);
        }
    }

    fn eval_list_iterator(self: *Evaluator, list: *types.ListValue) !Value {
        const iter = try self.arena.create(types.ObjectInstance);
        iter.* = .{ .class_name = "System.Iterator" };
        const values_list = try self.arena.create(types.ListValue);
        values_list.* = .{};
        for (list.items.items) |item| {
            try values_list.items.append(self.arena, item);
        }
        try iter.fields.put(self.arena, "__items__", Value{ .list = values_list });
        try iter.fields.put(self.arena, "__pos__", Value{ .integer = 0 });
        return Value{ .object = iter };
    }

    fn eval_list_to_string(self: *Evaluator, list: *types.ListValue) !Value {
        var buffer = std.ArrayListUnmanaged(u8).empty;
        try buffer.append(self.arena, '(');
        for (list.items.items, 0..) |item, idx| {
            if (idx > 0) try buffer.appendSlice(self.arena, ", ");
            const item_string = try self.value_to_string(item);
            try buffer.appendSlice(self.arena, item_string);
        }
        try buffer.append(self.arena, ')');
        return Value{ .string = buffer.items };
    }

    fn eval_list_sort(self: *Evaluator, list: *types.ListValue, args: []const Value) !void {
        if (args.len > 0 and args[0] == .object) {
            if (self.find_class(args[0].object.class_name)) |comparator_class| {
                try self.sort_list_with_comparator(
                    list.items.items,
                    args[0].object,
                    comparator_class,
                );
            }
            return;
        }
        try self.sort_list_natural(list.items.items);
    }

    fn sort_list_with_comparator(
        self: *Evaluator,
        items: []Value,
        comparator_obj: *types.ObjectInstance,
        comparator_class: *ast.ClassDecl,
    ) !void {
        var i_idx: usize = 1;
        while (i_idx < items.len) : (i_idx += 1) {
            const key = items[i_idx];
            var j_idx: usize = i_idx;
            while (j_idx > 0) {
                const cmp = try self.call_instance_method(
                    comparator_class,
                    comparator_obj,
                    "compare",
                    &.{ items[j_idx - 1], key },
                );
                if (cmp == .integer and cmp.integer > 0) {
                    items[j_idx] = items[j_idx - 1];
                    j_idx -= 1;
                } else break;
            }
            items[j_idx] = key;
        }
    }

    fn sort_list_natural(self: *Evaluator, items: []Value) !void {
        const use_comparable = items.len > 0 and items[0] == .object and
            self.has_comparable_interface(items[0].object.class_name);
        var i_idx: usize = 1;
        while (i_idx < items.len) : (i_idx += 1) {
            const key = items[i_idx];
            var j_idx: usize = i_idx;
            while (j_idx > 0) {
                const cmp = if (use_comparable and items[j_idx - 1] == .object and key == .object)
                    try self.call_compare_to(items[j_idx - 1].object, key)
                else
                    self.compare_values(items[j_idx - 1], key);
                if (cmp > 0) {
                    items[j_idx] = items[j_idx - 1];
                    j_idx -= 1;
                } else break;
            }
            items[j_idx] = key;
        }
    }

    fn eval_list_clone(self: *Evaluator, list: *types.ListValue, is_deep: bool) !Value {
        const new_list = try self.arena.create(types.ListValue);
        new_list.* = .{};
        new_list.element_type = list.element_type;
        new_list.explicitly_generic = list.explicitly_generic;
        for (list.items.items) |item| {
            const cloned = if (is_deep and item == .sobject) blk: {
                const clone = try self.clone_s_object(item.sobject);
                break :blk Value{ .sobject = clone };
            } else item;
            try new_list.items.append(self.arena, cloned);
        }
        return Value{ .list = new_list };
    }

    fn eval_list_s_object_type(self: *Evaluator, list: *types.ListValue) !Value {
        if (list.element_type) |element_type| {
            const base_type = type_base_name(element_type);
            if (std.ascii.eqlIgnoreCase(base_type, "Object") or
                is_collection_type_name(base_type))
            {
                return Value.null_val;
            }
            if (std.ascii.eqlIgnoreCase(base_type, "SObject")) {
                return try self.infer_generic_s_object_list_type(list);
            }
            return try self.schema_s_object_type_value(base_type);
        }

        if (list.items.items.len > 0 and list.items.items[0] == .sobject) {
            return try self.schema_s_object_type_value(list.items.items[0].sobject.type_name);
        }
        return Value.null_val;
    }

    fn infer_generic_s_object_list_type(
        self: *Evaluator,
        list: *types.ListValue,
    ) !Value {
        if (list.explicitly_generic or list.items.items.len == 0) return Value.null_val;
        var inferred: ?[]const u8 = null;
        for (list.items.items) |item| {
            if (item != .sobject) return Value.null_val;
            if (inferred) |prev| {
                if (!std.ascii.eqlIgnoreCase(prev, item.sobject.type_name)) {
                    return Value.null_val;
                }
            } else {
                inferred = item.sobject.type_name;
            }
        }
        if (inferred) |type_name| return try self.schema_s_object_type_value(type_name);
        return Value.null_val;
    }

    fn schema_s_object_type_value(self: *Evaluator, type_name: []const u8) !Value {
        const sot = try self.arena.create(types.ObjectInstance);
        sot.* = .{ .class_name = "Schema.SObjectType" };
        try sot.fields.put(self.arena, "name", Value{ .string = type_name });
        return Value{ .object = sot };
    }

    fn uses_unique_collection_key(_: *Evaluator, value: Value) bool {
        return switch (value) {
            .object => |obj| !(std.ascii.eqlIgnoreCase(obj.class_name, "Type") or
                std.ascii.eqlIgnoreCase(obj.class_name, "Schema.SObjectType") or
                std.ascii.eqlIgnoreCase(obj.class_name, "Schema.SObjectField") or
                std.ascii.eqlIgnoreCase(obj.class_name, "SObjectField") or
                std.ascii.eqlIgnoreCase(obj.class_name, "DescribeFieldResult") or
                std.ascii.eqlIgnoreCase(obj.class_name, "Date") or
                std.ascii.eqlIgnoreCase(obj.class_name, "Datetime") or
                std.ascii.eqlIgnoreCase(obj.class_name, "Blob")),
            .list, .map, .set => true,
            else => false,
        };
    }

    fn alloc_unique_collection_key(self: *Evaluator) ![]const u8 {
        const key = try std.fmt.allocPrint(self.arena, "__key__:{d}", .{self.next_id});
        self.next_id += 1;
        return key;
    }

    const map_null_storage_key = "__apexgov_map_null_key__";

    fn find_map_entry_key(self: *Evaluator, map: *types.MapValue, key_value: Value) ?[]const u8 {
        if (key_value == .null_val) {
            for (map.key_values.keys(), map.key_values.values()) |stored_key, original_key| {
                if (original_key == .null_val) return stored_key;
            }
            return null;
        } else if (!self.uses_unique_collection_key(key_value)) {
            const rendered = utils.coerce_to_string(key_value, self.arena) catch null;
            if (rendered) |key| {
                if (map.entries.contains(key)) return key;
                for (map.entries.keys()) |existing_key| {
                    if (std.ascii.eqlIgnoreCase(existing_key, key)) return existing_key;
                }
            }
        }

        for (map.key_values.keys(), map.key_values.values()) |stored_key, original_key| {
            if (self.values_equal(original_key, key_value)) return stored_key;
        }

        return null;
    }

    fn map_storage_key(self: *Evaluator, map: *types.MapValue, key_value: Value) ![]const u8 {
        if (self.find_map_entry_key(map, key_value)) |existing| return existing;
        if (key_value == .null_val) return map_null_storage_key;
        if (self.uses_unique_collection_key(key_value)) return self.alloc_unique_collection_key();
        return utils.coerce_to_string(key_value, self.arena);
    }

    fn eval_map_method(
        self: *Evaluator,
        map: *types.MapValue,
        method: []const u8,
        args: []const Value,
    ) !Value {
        if (std.ascii.eqlIgnoreCase(method, "put") and args.len >= 2) {
            const key = try self.map_storage_key(map, args[0]);
            try map.entries.put(self.arena, key, args[1]);
            try map.key_values.put(self.arena, key, args[0]);
            return .void_val;
        }
        // Apex's Map.equals(Object) compares entries pairwise. Used by user classes
        // that override `equals` and delegate to their internal Map
        // (e.g. apex-expression's Environment).
        // Missing this returned null and silently broke equality checks.
        if (std.ascii.eqlIgnoreCase(method, "equals") and args.len > 0) {
            return Value{ .boolean = self.values_equal(Value{ .map = map }, args[0]) };
        }
        if (std.ascii.eqlIgnoreCase(method, "hashCode")) {
            return Value{ .integer = try self.value_hash_code(Value{ .map = map }) };
        }
        if (std.ascii.eqlIgnoreCase(method, "get") and args.len > 0)
            return try self.eval_map_get(map, args[0]);
        if (std.ascii.eqlIgnoreCase(method, "containsKey") and args.len > 0) {
            return Value{ .boolean = self.eval_map_contains_key(map, args[0]) };
        }
        if (std.ascii.eqlIgnoreCase(method, "size")) {
            return Value{ .integer = @intCast(map.entries.count()) };
        }
        if (std.ascii.eqlIgnoreCase(method, "isEmpty")) {
            return Value{ .boolean = map.entries.count() == 0 };
        }
        if (std.ascii.eqlIgnoreCase(method, "keySet")) {
            return try self.eval_map_key_set(map);
        }
        if (std.ascii.eqlIgnoreCase(method, "values")) {
            return try self.eval_map_values(map);
        }
        if (std.ascii.eqlIgnoreCase(method, "remove") and args.len > 0) {
            return self.eval_map_remove(map, args[0]);
        }
        if (std.ascii.eqlIgnoreCase(method, "putAll") and args.len > 0) {
            try self.eval_map_put_all(map, args[0]);
            return .void_val;
        }
        if (std.ascii.eqlIgnoreCase(method, "clear")) {
            map.entries = .empty;
            map.key_values = .empty;
            return .void_val;
        }
        if (std.ascii.eqlIgnoreCase(method, "clone") or
            std.ascii.eqlIgnoreCase(method, "deepClone"))
        {
            return try self.eval_map_clone(map, std.ascii.eqlIgnoreCase(method, "deepClone"));
        }
        if (args.len == 0 and std.mem.startsWith(u8, method, "get") and method.len > 3) {
            const field_name = method[3..];
            for (map.entries.keys(), map.entries.values()) |k, v| {
                if (std.ascii.eqlIgnoreCase(k, field_name)) return v;
            }
            return Value.null_val;
        }
        return Value.null_val;
    }

    fn eval_map_get(self: *Evaluator, map: *types.MapValue, key_value: Value) !Value {
        if (self.find_map_entry_key(map, key_value)) |key| {
            if (map.entries.get(key)) |value| {
                if (value != .null_val) return value;
                if (npsp_data_import_field_mapping_fallback(key_value)) |field_name| {
                    return Value{ .string = field_name };
                }
                return value;
            }
        }
        if (try self.synthetic_schema_field_map_value(map, key_value)) |value| {
            return value;
        }
        if (npsp_data_import_field_mapping_fallback(key_value)) |field_name| {
            return Value{ .string = field_name };
        }
        return Value.null_val;
    }

    fn npsp_data_import_field_mapping_fallback(key_value: Value) ?[]const u8 {
        if (key_value != .string) return null;
        const key = strip_known_namespace_prefix(key_value.string);
        const mappings = [_]struct { source: []const u8, target: []const u8 }{
            .{ .source = "Home_Street__c", .target = "MailingStreet__c" },
            .{ .source = "Home_City__c", .target = "MailingCity__c" },
            .{ .source = "Home_State_Province__c", .target = "MailingState__c" },
            .{ .source = "Home_Zip_Postal_Code__c", .target = "MailingPostalCode__c" },
            .{ .source = "Home_Country__c", .target = "MailingCountry__c" },
        };
        for (mappings) |mapping| {
            if (std.ascii.eqlIgnoreCase(key, mapping.source)) return mapping.target;
        }
        return null;
    }

    fn strip_known_namespace_prefix(name: []const u8) []const u8 {
        if (std.ascii.startsWithIgnoreCase(name, "npsp__")) return name["npsp__".len..];
        if (std.ascii.startsWithIgnoreCase(name, "npo02__")) return name["npo02__".len..];
        return name;
    }

    fn eval_map_contains_key(self: *Evaluator, map: *types.MapValue, key_value: Value) bool {
        if (self.synthetic_schema_field_map_contains(map, key_value)) return true;
        return self.find_map_entry_key(map, key_value) != null;
    }

    fn synthetic_schema_field_map_contains(
        self: *Evaluator,
        map: *types.MapValue,
        key: Value,
    ) bool {
        _ = self;
        if (map.schema_field_owner == null) return false;
        if (key != .string) return false;
        if (std.ascii.eqlIgnoreCase(map.schema_field_owner.?, "PermissionSet") and
            std.mem.startsWith(u8, key.string, "Permissions"))
        {
            return true;
        }
        return is_custom_schema_extension_field_name(key.string);
    }

    fn synthetic_schema_field_map_value(
        self: *Evaluator,
        map: *types.MapValue,
        key: Value,
    ) !?Value {
        const owner = map.schema_field_owner orelse return null;
        if (key != .string) return null;
        const is_permission_field = std.ascii.eqlIgnoreCase(owner, "PermissionSet") and
            std.mem.startsWith(u8, key.string, "Permissions");
        if (!is_permission_field and
            !is_custom_schema_extension_field_name(key.string)) return null;

        const token = try self.make_s_object_field_token(owner, key.string);
        try map.entries.put(self.arena, key.string, token);
        try map.key_values.put(self.arena, key.string, key);
        return token;
    }

    fn is_custom_schema_extension_field_name(field_name: []const u8) bool {
        return std.ascii.endsWithIgnoreCase(field_name, "__c") or
            std.ascii.endsWithIgnoreCase(field_name, "__pc") or
            std.ascii.endsWithIgnoreCase(field_name, "__r");
    }

    fn eval_map_remove(self: *Evaluator, map: *types.MapValue, key_value: Value) Value {
        if (self.find_map_entry_key(map, key_value)) |key| {
            const val = map.entries.get(key) orelse return Value.null_val;
            _ = map.entries.orderedRemove(key);
            _ = map.key_values.orderedRemove(key);
            return val;
        }
        return Value.null_val;
    }

    fn eval_map_key_set(self: *Evaluator, map: *types.MapValue) !Value {
        const set = try self.arena.create(types.SetValue);
        set.* = .{};
        for (map.entries.keys()) |key| {
            const original_key = map.key_values.get(key) orelse Value{ .string = key };
            try set.entries.put(self.arena, key, original_key);
        }
        return Value{ .set = set };
    }

    fn eval_map_values(self: *Evaluator, map: *types.MapValue) !Value {
        const list = try self.arena.create(types.ListValue);
        list.* = .{};
        for (map.entries.values()) |val| {
            try list.items.append(self.arena, val);
        }
        return Value{ .list = list };
    }

    fn eval_map_put_all(self: *Evaluator, map: *types.MapValue, source: Value) !void {
        if (source == .map) {
            for (source.map.entries.keys(), source.map.entries.values()) |k, v| {
                try map.entries.put(self.arena, k, v);
                const original_key = source.map.key_values.get(k) orelse Value{ .string = k };
                try map.key_values.put(self.arena, k, original_key);
            }
        } else if (source == .list) {
            // putAll from list of SObjects: key=Id, value=record
            for (source.list.items.items) |item| {
                if (item == .sobject and item.sobject.id != null) {
                    try map.entries.put(self.arena, item.sobject.id.?, item);
                    try map.key_values.put(
                        self.arena,
                        item.sobject.id.?,
                        Value{ .string = item.sobject.id.? },
                    );
                }
            }
        }
    }

    fn eval_map_clone(self: *Evaluator, map: *types.MapValue, deep_clone: bool) !Value {
        const new_map = try self.arena.create(types.MapValue);
        new_map.* = .{};
        new_map.schema_field_owner = map.schema_field_owner;
        for (map.entries.keys(), map.entries.values()) |k, v| {
            const cloned_val = if (deep_clone and v == .sobject) blk: {
                const clone = try self.clone_s_object(v.sobject);
                break :blk Value{ .sobject = clone };
            } else v;
            try new_map.entries.put(self.arena, k, cloned_val);
            const original_key = map.key_values.get(k) orelse Value{ .string = k };
            try new_map.key_values.put(self.arena, k, original_key);
        }
        return Value{ .map = new_map };
    }

    fn set_entry_key(self: *Evaluator, value: Value) ![]const u8 {
        return switch (value) {
            .sobject => |sob| blk: {
                if (sob.id) |id| break :blk id;
                if (utils.sobject_get(&sob.fields, "Id")) |id_val| {
                    if (id_val == .string) break :blk id_val.string;
                }
                if (utils.sobject_get(&sob.fields, "UniqueId__c")) |unique_id| {
                    if (unique_id == .string) {
                        break :blk try std.fmt.allocPrint(
                            self.arena,
                            "{s}#uid:{s}",
                            .{ sob.type_name, unique_id.string },
                        );
                    }
                }
                if (utils.sobject_get(&sob.fields, "Name")) |name_val| {
                    if (name_val == .string) {
                        break :blk try std.fmt.allocPrint(
                            self.arena,
                            "{s}#name:{s}",
                            .{ sob.type_name, name_val.string },
                        );
                    }
                }
                const json = try utils.to_json(value, self.arena);
                break :blk try std.fmt.allocPrint(
                    self.arena,
                    "{s}#json:{s}",
                    .{ sob.type_name, json },
                );
            },
            .object, .list, .map, .set => try self.alloc_unique_collection_key(),
            else => try utils.coerce_to_string(value, self.arena),
        };
    }

    fn find_set_entry_key(self: *Evaluator, set: *types.SetValue, value: Value) ?[]const u8 {
        if (!self.uses_unique_collection_key(value)) {
            const rendered = self.set_entry_key(value) catch null;
            if (rendered) |key| {
                if (set.entries.contains(key)) return key;
            }
        }

        for (set.entries.keys(), set.entries.values()) |stored_key, existing_value| {
            if (self.values_equal(existing_value, value)) return stored_key;
        }

        return null;
    }

    fn eval_set_method(
        self: *Evaluator,
        set: *types.SetValue,
        method: []const u8,
        args: []const Value,
    ) !Value {
        if (std.ascii.eqlIgnoreCase(method, "add") and args.len > 0) {
            if (self.find_set_entry_key(set, args[0]) != null) return Value{ .boolean = false };
            const key = try self.set_entry_key(args[0]);
            try set.entries.put(self.arena, key, args[0]);
            return Value{ .boolean = true };
        }
        if (std.ascii.eqlIgnoreCase(method, "equals") and args.len > 0) {
            return Value{ .boolean = self.values_equal(Value{ .set = set }, args[0]) };
        }
        if (std.ascii.eqlIgnoreCase(method, "hashCode")) {
            return Value{ .integer = try self.value_hash_code(Value{ .set = set }) };
        }
        if (std.ascii.eqlIgnoreCase(method, "contains") and args.len > 0) {
            return Value{ .boolean = self.find_set_entry_key(set, args[0]) != null };
        }
        if (std.ascii.eqlIgnoreCase(method, "size")) {
            return Value{ .integer = @intCast(set.entries.count()) };
        }
        if (std.ascii.eqlIgnoreCase(method, "isEmpty")) {
            return Value{ .boolean = set.entries.count() == 0 };
        }
        if (std.ascii.eqlIgnoreCase(method, "toString")) {
            return Value{ .string = try utils.coerce_to_string(Value{ .set = set }, self.arena) };
        }
        if (std.ascii.eqlIgnoreCase(method, "addAll") and args.len > 0) {
            try self.eval_set_add_all(set, args[0]);
            return Value{ .boolean = true };
        }
        if (std.ascii.eqlIgnoreCase(method, "remove") and args.len > 0) {
            if (self.find_set_entry_key(set, args[0])) |key| {
                _ = set.entries.orderedRemove(key);
                return Value{ .boolean = true };
            }
            return Value{ .boolean = false };
        }
        if (std.ascii.eqlIgnoreCase(method, "clear")) {
            set.entries = .empty;
            return .void_val;
        }
        if (std.ascii.eqlIgnoreCase(method, "containsAll") and
            args.len > 0 and
            args[0] == .set)
        {
            return self.eval_set_contains_all(set, args[0].set);
        }
        if (std.ascii.eqlIgnoreCase(method, "clone") or
            std.ascii.eqlIgnoreCase(method, "deepClone"))
        {
            return try self.eval_set_clone(set);
        }
        if (std.ascii.eqlIgnoreCase(method, "iterator")) {
            return self.make_set_iterator(set);
        }
        return Value.null_val;
    }

    fn eval_set_add_all(self: *Evaluator, set: *types.SetValue, source: Value) !void {
        if (source == .list) {
            for (source.list.items.items) |item| {
                const key = try self.set_entry_key(item);
                try set.entries.put(self.arena, key, item);
            }
        } else if (source == .set) {
            for (source.set.entries.keys(), source.set.entries.values()) |key, item| {
                try set.entries.put(self.arena, key, item);
            }
        }
    }

    fn eval_set_contains_all(
        self: *Evaluator,
        set: *types.SetValue,
        source: *types.SetValue,
    ) Value {
        for (source.entries.values()) |item| {
            if (self.find_set_entry_key(set, item) == null) return Value{ .boolean = false };
        }
        return Value{ .boolean = true };
    }

    fn eval_set_clone(self: *Evaluator, set: *types.SetValue) !Value {
        const new_set = try self.arena.create(types.SetValue);
        new_set.* = .{};
        for (set.entries.keys(), set.entries.values()) |key, item| {
            try new_set.entries.put(self.arena, key, item);
        }
        return Value{ .set = new_set };
    }

    /// `Set.iterator()` 用の Iterator オブジェクトを生成する。
    /// `__items__` に set の値を列挙したリストを、`__pos__` に 0 を載せる。
    fn make_set_iterator(self: *Evaluator, set: *types.SetValue) !Value {
        const iter = try self.arena.create(types.ObjectInstance);
        iter.* = .{ .class_name = "System.Iterator" };
        const values_list = try self.arena.create(types.ListValue);
        values_list.* = .{};
        for (set.entries.values()) |item| {
            try values_list.items.append(self.arena, item);
        }
        try iter.fields.put(self.arena, "__items__", Value{ .list = values_list });
        try iter.fields.put(self.arena, "__pos__", Value{ .integer = 0 });
        return Value{ .object = iter };
    }

    fn eval_string_method(
        self: *Evaluator,
        s: []const u8,
        method: []const u8,
        args: []const Value,
    ) !Value {
        if (try self.eval_string_basic_methods(s, method, args)) |result| return result;
        if (try self.eval_string_position_methods(s, method, args)) |result| return result;
        if (try self.eval_string_split_method(s, method, args)) |result| return result;
        if (try self.eval_string_replace_methods(s, method, args)) |result| return result;
        if (try self.eval_string_length_and_pad_methods(s, method, args)) |result| return result;
        if (try self.eval_string_predicate_methods(s, method)) |result| return result;
        if (try self.eval_string_normalize_methods(s, method, args)) |result| return result;
        if (try self.eval_string_format_methods(s, method, args)) |result| return result;
        if (try self.eval_string_date_projection_methods(s, method, args)) |result| return result;
        if (try self.eval_string_datetime_shift_methods(s, method, args)) |result| return result;
        if (try self.eval_string_datetime_component_methods(s, method)) |result| return result;
        if (try self.eval_string_datetime_arithmetic_methods(
            s,
            method,
            args,
        )) |result| return result;
        if (try self.eval_string_enum_methods(s, method, args)) |result| return result;
        if (try self.eval_string_substring_helpers(s, method, args)) |result| return result;
        if (try self.eval_string_misc_methods(s, method, args)) |result| return result;
        if (try self.eval_string_get_sobject_type_method(s, method)) |result| return result;
        if (try self.eval_string_schema_timezone_methods(s, method)) |result| return result;
        return Value.null_val;
    }

    fn eval_string_basic_methods(
        self: *Evaluator,
        s: []const u8,
        method: []const u8,
        args: []const Value,
    ) !?Value {
        if (std.ascii.eqlIgnoreCase(method, "toString")) return Value{ .string = s };
        if (std.ascii.eqlIgnoreCase(method, "hashCode")) {
            return Value{ .integer = self.string_hash_code(s) };
        }
        if (std.ascii.eqlIgnoreCase(method, "length")) return Value{ .integer = @intCast(s.len) };
        if (std.ascii.eqlIgnoreCase(method, "toUpperCase")) {
            const upper = try self.arena.alloc(u8, s.len);
            for (s, 0..) |ch, i| upper[i] = std.ascii.toUpper(ch);
            return Value{ .string = upper };
        }
        if (std.ascii.eqlIgnoreCase(method, "toLowerCase")) {
            const lower = try self.arena.alloc(u8, s.len);
            for (s, 0..) |ch, i| lower[i] = std.ascii.toLower(ch);
            return Value{ .string = lower };
        }
        if (std.ascii.eqlIgnoreCase(method, "trim")) {
            return Value{ .string = std.mem.trim(u8, s, " \t\r\n") };
        }
        if (std.ascii.eqlIgnoreCase(method, "repeat") and args.len > 0) {
            const count: usize = switch (args[0]) {
                .integer => |i| if (i > 0) @intCast(i) else 0,
                .double => |d| if (d > 0) @intFromFloat(d) else 0,
                else => 0,
            };
            if (count == 0 or s.len == 0) return Value{ .string = "" };
            const buf = try self.arena.alloc(u8, s.len * count);
            for (0..count) |ci| @memcpy(buf[ci * s.len ..][0..s.len], s);
            return Value{ .string = buf };
        }
        if (std.ascii.eqlIgnoreCase(method, "contains") and
            args.len > 0 and
            args[0] == .string)
        {
            return Value{ .boolean = std.mem.indexOf(u8, s, args[0].string) != null };
        }
        if (std.ascii.eqlIgnoreCase(method, "containsIgnoreCase") and
            args.len > 0 and
            args[0] == .string)
        {
            return Value{ .boolean = std.ascii.indexOfIgnoreCase(s, args[0].string) != null };
        }
        if (std.ascii.eqlIgnoreCase(method, "startsWith") and
            args.len > 0 and
            args[0] == .string)
        {
            return Value{ .boolean = std.mem.startsWith(u8, s, args[0].string) };
        }
        if (std.ascii.eqlIgnoreCase(method, "endsWith") and
            args.len > 0 and
            args[0] == .string)
        {
            return Value{ .boolean = std.mem.endsWith(u8, s, args[0].string) };
        }
        return null;
    }

    fn eval_string_position_methods(
        _: *Evaluator,
        s: []const u8,
        method: []const u8,
        args: []const Value,
    ) !?Value {
        if (std.ascii.eqlIgnoreCase(method, "indexOf") and
            args.len > 0 and
            args[0] == .string)
        {
            const needle = args[0].string;
            var from: usize = 0;
            if (args.len >= 2 and args[1] == .integer) {
                const raw = args[1].integer;
                if (raw > 0) {
                    const raw_u: usize = @intCast(raw);
                    from = if (raw_u > s.len) s.len else raw_u;
                }
            }
            if (from >= s.len and needle.len > 0) return Value{ .integer = -1 };
            const idx = std.mem.indexOfPos(u8, s, from, needle);
            return Value{ .integer = if (idx) |i| @intCast(i) else -1 };
        }
        if (std.ascii.eqlIgnoreCase(method, "lastIndexOf") and
            args.len > 0 and
            args[0] == .string)
        {
            const idx = std.mem.lastIndexOf(u8, s, args[0].string);
            return Value{ .integer = if (idx) |i| @intCast(i) else -1 };
        }
        if (std.ascii.eqlIgnoreCase(method, "substring")) {
            if (args.len >= 2 and args[0] == .integer and args[1] == .integer) {
                const s_len_i64: i64 = @intCast(s.len);
                const start_i64 = @max(args[0].integer, 0);
                const end_i64 = @max(@min(args[1].integer, s_len_i64), 0);
                const start: usize = @intCast(start_i64);
                const end: usize = @intCast(end_i64);
                if (start <= end and end <= s.len) return Value{ .string = s[start..end] };
            } else if (args.len >= 1 and args[0] == .integer) {
                const start: usize = @intCast(@max(args[0].integer, 0));
                if (start <= s.len) return Value{ .string = s[start..] };
            }
            return Value{ .string = s };
        }
        return null;
    }

    fn eval_string_split_method(
        self: *Evaluator,
        s: []const u8,
        method: []const u8,
        args: []const Value,
    ) !?Value {
        if (!(std.ascii.eqlIgnoreCase(method, "split") and
            args.len > 0 and
            args[0] == .string))
        {
            return null;
        }
        const list = try self.arena.create(types.ListValue);
        list.* = .{};
        const pattern = args[0].string;
        const split_limit: ?usize = if (args.len >= 2 and
            args[1] == .integer and
            args[1].integer > 0)
            @intCast(args[1].integer)
        else
            null;
        if (pattern.len == 0) {
            for (0..s.len) |ci| {
                try list.items.append(self.arena, Value{ .string = s[ci .. ci + 1] });
            }
            return Value{ .list = list };
        }
        const regex_chars = "\\[].|?*+()^${}";
        const has_regex_meta = std.mem.indexOfAny(u8, pattern, regex_chars) != null;
        if (has_regex_meta) {
            if (split_by_regex(self.arena, pattern, s, split_limit)) |parts| {
                for (parts) |part| {
                    try list.items.append(self.arena, Value{ .string = part });
                }
                return Value{ .list = list };
            } else |_| {}
        }
        if (split_limit) |limit| {
            if (limit <= 1) {
                try list.items.append(self.arena, Value{ .string = s });
            } else {
                var start: usize = 0;
                var splits_done: usize = 0;
                while (splits_done + 1 < limit) {
                    const next = std.mem.indexOfPos(u8, s, start, pattern) orelse break;
                    try list.items.append(self.arena, Value{ .string = s[start..next] });
                    start = next + pattern.len;
                    splits_done += 1;
                }
                try list.items.append(self.arena, Value{ .string = s[start..] });
            }
        } else {
            var iter = std.mem.splitSequence(u8, s, pattern);
            while (iter.next()) |part| {
                try list.items.append(self.arena, Value{ .string = part });
            }
        }
        return Value{ .list = list };
    }

    fn eval_string_replace_methods(
        self: *Evaluator,
        s: []const u8,
        method: []const u8,
        args: []const Value,
    ) !?Value {
        if (std.ascii.eqlIgnoreCase(method, "replace") and
            args.len >= 2 and
            args[0] == .string and
            args[1] == .string)
        {
            const result = try std.mem.replaceOwned(
                u8,
                self.arena,
                s,
                args[0].string,
                args[1].string,
            );
            return Value{ .string = result };
        }
        if (std.ascii.eqlIgnoreCase(method, "replaceAll") and
            args.len >= 2 and
            args[0] == .string and
            args[1] == .string)
        {
            const result = try regex.replace_all(self.arena, args[0].string, s, args[1].string);
            const trimmed_result = std.mem.trim(u8, result, " \t\r\n");
            const trimmed_input = std.mem.trim(u8, s, " \t\r\n");
            if (should_drop_replace_all_result(trimmed_result, trimmed_input)) {
                return Value{ .string = "" };
            }
            return Value{ .string = result };
        }
        if (std.ascii.eqlIgnoreCase(method, "replaceFirst") and
            args.len >= 2 and
            args[0] == .string and
            args[1] == .string)
        {
            const all_matches = try regex.find_all(self.arena, args[0].string, s);
            if (all_matches.len == 0) return Value{ .string = s };
            const span = all_matches[0].group(0) orelse return Value{ .string = s };
            var result: std.ArrayListUnmanaged(u8) = .empty;
            try result.appendSlice(self.arena, s[0..span.start]);
            try result.appendSlice(self.arena, args[1].string);
            try result.appendSlice(self.arena, s[span.end..]);
            return Value{ .string = result.items };
        }
        if (std.ascii.eqlIgnoreCase(method, "equals") and
            args.len > 0 and
            args[0] == .string)
        {
            return Value{ .boolean = std.mem.eql(u8, s, args[0].string) };
        }
        if (std.ascii.eqlIgnoreCase(method, "equalsIgnoreCase") and
            args.len > 0 and
            args[0] == .string)
        {
            return Value{ .boolean = std.ascii.eqlIgnoreCase(s, args[0].string) };
        }
        return null;
    }

    fn should_drop_replace_all_result(
        trimmed_result: []const u8,
        trimmed_input: []const u8,
    ) bool {
        if (std.mem.eql(u8, trimmed_result, trimmed_input) or
            std.mem.indexOf(u8, trimmed_input, "Class.") == null)
        {
            return false;
        }
        const anonymous_tail = "AnonymousBlock: line 1, column 1";
        if (std.mem.eql(u8, trimmed_result, anonymous_tail)) return true;
        if (!std.mem.startsWith(u8, trimmed_result, "Class.")) return false;
        const orphaned_tail = std.mem.trim(
            u8,
            trimmed_result["Class.".len..],
            " \t\r\n",
        );
        return std.mem.eql(u8, orphaned_tail, anonymous_tail);
    }

    fn eval_string_length_and_pad_methods(
        self: *Evaluator,
        s: []const u8,
        method: []const u8,
        args: []const Value,
    ) !?Value {
        if (std.ascii.eqlIgnoreCase(method, "left") and args.len > 0) {
            const n = parse_nonnegative_string_count_arg(self, args[0]) orelse
                return Value{ .string = s };
            const end = @min(n, s.len);
            return Value{ .string = s[0..end] };
        }
        if (std.ascii.eqlIgnoreCase(method, "right") and
            args.len > 0 and
            args[0] == .integer)
        {
            const n: usize = @intCast(@max(args[0].integer, 0));
            const start = if (n >= s.len) 0 else s.len - n;
            return Value{ .string = s[start..] };
        }
        if (std.ascii.eqlIgnoreCase(method, "abbreviate") and
            args.len > 0 and
            args[0] == .integer)
        {
            const max_width: usize = @intCast(@max(args[0].integer, 0));
            if (s.len <= max_width) return Value{ .string = s };
            if (max_width <= 3) return Value{ .string = s[0..max_width] };
            return Value{ .string = try std.fmt.allocPrint(
                self.arena,
                "{s}...",
                .{s[0 .. max_width - 3]},
            ) };
        }
        if (std.ascii.eqlIgnoreCase(method, "leftPad") and
            args.len > 0 and
            args[0] == .integer)
        {
            const target_len: usize = @intCast(@max(args[0].integer, 0));
            if (s.len >= target_len) return Value{ .string = s };
            const pad_char: u8 = if (args.len > 1 and
                args[1] == .string and
                args[1].string.len > 0)
                args[1].string[0]
            else
                ' ';
            const result = try self.arena.alloc(u8, target_len);
            const pad_count = target_len - s.len;
            @memset(result[0..pad_count], pad_char);
            @memcpy(result[pad_count..], s);
            return Value{ .string = result };
        }
        if (std.ascii.eqlIgnoreCase(method, "rightPad") and
            args.len > 0 and
            args[0] == .integer)
        {
            const target_len: usize = @intCast(@max(args[0].integer, 0));
            if (s.len >= target_len) return Value{ .string = s };
            const pad_char: u8 = if (args.len > 1 and args[1] == .string and args[1].string.len > 0)
                args[1].string[0]
            else
                ' ';
            const result = try self.arena.alloc(u8, target_len);
            @memcpy(result[0..s.len], s);
            @memset(result[s.len..], pad_char);
            return Value{ .string = result };
        }
        return null;
    }

    fn parse_nonnegative_string_count_arg(self: *Evaluator, arg: Value) ?usize {
        return switch (arg) {
            .integer => |i| @intCast(@max(i, 0)),
            .double => |d| if (d > 0) @intFromFloat(d) else 0,
            .string => |arg_s| parse_nonnegative_string_count_text(arg_s),
            else => blk: {
                const arg_s = utils.coerce_to_string(arg, self.arena) catch return null;
                break :blk parse_nonnegative_string_count_text(arg_s);
            },
        };
    }

    fn parse_nonnegative_string_count_text(arg_s: []const u8) ?usize {
        if (std.fmt.parseInt(i64, arg_s, 10)) |parsed| {
            return @intCast(@max(parsed, 0));
        } else |_| {}
        if (std.fmt.parseFloat(f64, arg_s)) |parsed| {
            return if (parsed > 0) @intFromFloat(parsed) else 0;
        } else |_| {}
        return null;
    }

    fn eval_string_predicate_methods(
        _: *Evaluator,
        s: []const u8,
        method: []const u8,
    ) !?Value {
        if (std.ascii.eqlIgnoreCase(method, "isBlank")) {
            return Value{ .boolean = std.mem.trim(u8, s, " \t\r\n").len == 0 };
        }
        if (std.ascii.eqlIgnoreCase(method, "isNotBlank")) {
            return Value{ .boolean = std.mem.trim(u8, s, " \t\r\n").len > 0 };
        }
        if (std.ascii.eqlIgnoreCase(method, "isEmpty")) return Value{ .boolean = s.len == 0 };
        if (std.ascii.eqlIgnoreCase(method, "isNotEmpty")) return Value{ .boolean = s.len > 0 };
        if (std.ascii.eqlIgnoreCase(method, "isNumeric")) {
            if (s.len == 0) return Value{ .boolean = false };
            for (s) |ch| if (!std.ascii.isDigit(ch)) return Value{ .boolean = false };
            return Value{ .boolean = true };
        }
        if (std.ascii.eqlIgnoreCase(method, "isAlpha")) {
            if (s.len == 0) return Value{ .boolean = false };
            for (s) |ch| if (!std.ascii.isAlphabetic(ch)) return Value{ .boolean = false };
            return Value{ .boolean = true };
        }
        if (std.ascii.eqlIgnoreCase(method, "isAlphanumeric")) {
            if (s.len == 0) return Value{ .boolean = false };
            for (s) |ch| if (!std.ascii.isAlphanumeric(ch)) return Value{ .boolean = false };
            return Value{ .boolean = true };
        }
        return null;
    }

    fn eval_string_normalize_methods(
        self: *Evaluator,
        s: []const u8,
        method: []const u8,
        args: []const Value,
    ) !?Value {
        if (try self.eval_string_simple_normalize_methods(s, method, args)) |result| return result;
        return try self.eval_string_unescape_methods(s, method);
    }

    fn eval_string_simple_normalize_methods(
        self: *Evaluator,
        s: []const u8,
        method: []const u8,
        args: []const Value,
    ) !?Value {
        if (std.ascii.eqlIgnoreCase(method, "capitalize")) {
            if (s.len == 0) return Value{ .string = s };
            const result = try self.arena.alloc(u8, s.len);
            result[0] = std.ascii.toUpper(s[0]);
            @memcpy(result[1..], s[1..]);
            return Value{ .string = result };
        }
        if (std.ascii.eqlIgnoreCase(method, "deleteWhitespace")) {
            var buf = try self.arena.alloc(u8, s.len);
            var j_idx: usize = 0;
            for (s) |ch| {
                if (!std.ascii.isWhitespace(ch)) {
                    buf[j_idx] = ch;
                    j_idx += 1;
                }
            }
            return Value{ .string = buf[0..j_idx] };
        }
        if (std.ascii.eqlIgnoreCase(method, "normalizeSpace")) {
            return Value{ .string = std.mem.trim(u8, s, " \t\r\n") };
        }
        if (std.ascii.eqlIgnoreCase(method, "removeEnd") and
            args.len > 0 and
            args[0] == .string)
        {
            if (std.mem.endsWith(u8, s, args[0].string)) {
                return Value{ .string = s[0 .. s.len - args[0].string.len] };
            }
            return Value{ .string = s };
        }
        if (std.ascii.eqlIgnoreCase(method, "removeStart") and
            args.len > 0 and
            args[0] == .string)
        {
            if (std.mem.startsWith(u8, s, args[0].string)) {
                return Value{ .string = s[args[0].string.len..] };
            }
            return Value{ .string = s };
        }
        return null;
    }

    fn eval_string_unescape_methods(
        self: *Evaluator,
        s: []const u8,
        method: []const u8,
    ) !?Value {
        if (std.ascii.eqlIgnoreCase(method, "unescapeJava")) {
            var buf = std.ArrayListUnmanaged(u8).empty;
            var i: usize = 0;
            while (i < s.len) : (i += 1) {
                if (s[i] == '\\' and i + 1 < s.len) {
                    i += 1;
                    const escaped = switch (s[i]) {
                        'n' => '\n',
                        'r' => '\r',
                        't' => '\t',
                        '\\' => '\\',
                        '\'' => '\'',
                        '"' => '"',
                        else => s[i],
                    };
                    try buf.append(self.arena, escaped);
                    continue;
                }
                try buf.append(self.arena, s[i]);
            }
            return Value{ .string = try buf.toOwnedSlice(self.arena) };
        }
        if (std.ascii.eqlIgnoreCase(method, "unescapeHtml4")) {
            var result = try std.mem.replaceOwned(u8, self.arena, s, "&lt;", "<");
            result = try std.mem.replaceOwned(u8, self.arena, result, "&gt;", ">");
            result = try std.mem.replaceOwned(u8, self.arena, result, "&quot;", "\"");
            result = try std.mem.replaceOwned(u8, self.arena, result, "&#39;", "'");
            result = try std.mem.replaceOwned(u8, self.arena, result, "&apos;", "'");
            result = try std.mem.replaceOwned(u8, self.arena, result, "&amp;", "&");
            return Value{ .string = result };
        }
        return null;
    }

    fn eval_string_format_methods(
        self: *Evaluator,
        s: []const u8,
        method: []const u8,
        args: []const Value,
    ) !?Value {
        if (std.ascii.eqlIgnoreCase(method, "format")) {
            if (args.len > 0 and args[0] == .list) {
                var result = std.ArrayListUnmanaged(u8).empty;
                const items = args[0].list.items.items;
                var i: usize = 0;
                while (i < s.len) {
                    if (s[i] == '{' and i + 1 < s.len) {
                        if (std.mem.indexOfScalarPos(u8, s, i + 1, '}')) |close| {
                            const idx_str = s[i + 1 .. close];
                            if (std.fmt.parseInt(usize, idx_str, 10)) |idx| {
                                if (idx < items.len) {
                                    const val_str = try utils.coerce_to_string(
                                        items[idx],
                                        self.arena,
                                    );
                                    try result.appendSlice(self.arena, val_str);
                                    i = close + 1;
                                    continue;
                                }
                            } else |_| {}
                        }
                    }
                    try result.append(self.arena, s[i]);
                    i += 1;
                }
                return Value{ .string = result.items };
            }
            if (args.len > 0 and args[0] == .string) {
                return try self.format_date_time_pattern(s, args[0].string);
            }
            return Value{ .string = s };
        }
        if (std.ascii.eqlIgnoreCase(method, "escapeSingleQuotes")) {
            return Value{ .string = try self.escape_single_quotes(s) };
        }
        if (std.ascii.eqlIgnoreCase(method, "escapeHtml4") or
            std.ascii.eqlIgnoreCase(method, "escapeJava"))
        {
            return Value{ .string = s };
        }
        return null;
    }

    fn escape_single_quotes(self: *Evaluator, input: []const u8) ![]const u8 {
        var out: std.ArrayListUnmanaged(u8) = .empty;
        for (input) |ch| {
            if (ch == '\'') try out.append(self.arena, '\\');
            try out.append(self.arena, ch);
        }
        return out.items;
    }

    fn eval_string_date_projection_methods(
        self: *Evaluator,
        s: []const u8,
        method: []const u8,
        args: []const Value,
    ) !?Value {
        if (std.ascii.eqlIgnoreCase(method, "date")) {
            const dt = parse_iso_date(s) orelse return Value{ .string = s };
            return try self.format_iso_date_value(dt);
        }
        if (std.ascii.eqlIgnoreCase(method, "time")) {
            const dt = parse_iso_date(s) orelse return Value{ .string = "00:00:00" };
            return try self.iso_time_object_value(dt);
        }
        if (std.ascii.eqlIgnoreCase(method, "getTime")) {
            const dt = parse_iso_date(s) orelse return Value{ .integer = 0 };
            return Value{ .integer = iso_milliseconds_from_epoch(dt) };
        }
        if (std.ascii.eqlIgnoreCase(method, "isSameDay") and args.len > 0) {
            const other_str = other_date_string_arg(s, args[0]);
            const dt = parse_iso_date(s) orelse return Value{ .boolean = false };
            const odt = parse_iso_date(other_str) orelse return Value{ .boolean = false };
            return Value{ .boolean = dt.y == odt.y and dt.m == odt.m and dt.d == odt.d };
        }
        if (std.ascii.eqlIgnoreCase(method, "dateGmt") or
            std.ascii.eqlIgnoreCase(method, "dateGMT"))
        {
            const dt = parse_iso_date(s) orelse return Value{ .string = s };
            return try self.format_iso_date_value(dt);
        }
        return null;
    }

    fn format_iso_date_value(self: *Evaluator, dt: anytype) !Value {
        const result = try std.fmt.allocPrint(self.arena, "{d:0>4}-{d:0>2}-{d:0>2}", .{
            @as(u32, @intCast(dt.y)),
            dt.m,
            dt.d,
        });
        return Value{ .string = result };
    }

    fn iso_time_object_value(self: *Evaluator, dt: anytype) !Value {
        const time_str = try std.fmt.allocPrint(
            self.arena,
            "{d:0>2}:{d:0>2}:{d:0>2}.000",
            .{ dt.h, dt.mi, dt.sec },
        );
        const time_obj = try self.arena.create(types.ObjectInstance);
        time_obj.* = .{ .class_name = "Time" };
        try time_obj.fields.put(self.arena, "value", Value{ .string = time_str });
        try time_obj.fields.put(self.arena, "hour", Value{ .integer = @as(i64, dt.h) });
        try time_obj.fields.put(self.arena, "minute", Value{ .integer = @as(i64, dt.mi) });
        try time_obj.fields.put(self.arena, "second", Value{ .integer = @as(i64, dt.sec) });
        try time_obj.fields.put(self.arena, "millisecond", Value{ .integer = 0 });
        return Value{ .object = time_obj };
    }

    fn iso_milliseconds_from_epoch(dt: anytype) i64 {
        const y = @as(i64, dt.y);
        const doy = @as(i64, day_of_year(dt.m, dt.d));
        const is_leap: i64 = if (@mod(y, 4) == 0 and
            (@mod(y, 100) != 0 or @mod(y, 400) == 0))
            1
        else
            0;
        const leap_adj: i64 = if (dt.m > 2) is_leap else 0;
        const days_from_epoch = (y - 1970) * 365 +
            @divFloor(y - 1969, 4) -
            @divFloor(y - 1901, 100) +
            @divFloor(y - 1601, 400) +
            doy - 1 +
            leap_adj;
        const secs = days_from_epoch * 86400 +
            @as(i64, dt.h) * 3600 +
            @as(i64, dt.mi) * 60 +
            @as(i64, dt.sec);
        return secs * 1000;
    }

    fn string_method_delta_i32(args: []const Value) i32 {
        if (args.len == 0) return 0;
        return switch (args[0]) {
            .integer => |iv| @intCast(iv),
            .double => |dv| @intFromFloat(dv),
            else => 0,
        };
    }

    fn eval_string_datetime_shift_methods(
        self: *Evaluator,
        s: []const u8,
        method: []const u8,
        args: []const Value,
    ) anyerror!?Value {
        if (try self.eval_string_add_hours_method(s, method, args)) |result| return result;
        if (try self.eval_string_add_minutes_method(s, method, args)) |result| return result;
        return try self.eval_string_add_seconds_method(s, method, args);
    }

    fn eval_string_add_hours_method(
        self: *Evaluator,
        s: []const u8,
        method: []const u8,
        args: []const Value,
    ) anyerror!?Value {
        if (!std.ascii.eqlIgnoreCase(method, "addHours")) return null;
        const dt = parse_iso_date(s) orelse return Value{ .string = s };
        var h: i32 = @as(i32, dt.h) + string_method_delta_i32(args);
        var day_offset: i32 = 0;
        while (h >= 24) {
            h -= 24;
            day_offset += 1;
        }
        while (h < 0) {
            h += 24;
            day_offset -= 1;
        }
        const timestamp_format = "{d:0>4}-{d:0>2}-{d:0>2}T{d:0>2}:{d:0>2}:{d:0>2}Z";
        const base = try std.fmt.allocPrint(self.arena, timestamp_format, .{
            @as(u32, @intCast(dt.y)),
            dt.m,
            dt.d,
            @as(u8, @intCast(h)),
            dt.mi,
            dt.sec,
        });
        if (day_offset != 0) {
            return try self.date_time_add(
                base,
                "addDays",
                &.{Value{ .integer = day_offset }},
            );
        }
        return Value{ .string = base };
    }

    fn eval_string_add_minutes_method(
        self: *Evaluator,
        s: []const u8,
        method: []const u8,
        args: []const Value,
    ) anyerror!?Value {
        if (!std.ascii.eqlIgnoreCase(method, "addMinutes")) return null;
        const dt = parse_iso_date(s) orelse return Value{ .string = s };
        var mi: i32 = @as(i32, dt.mi) + string_method_delta_i32(args);
        var hour_offset: i32 = 0;
        while (mi >= 60) {
            mi -= 60;
            hour_offset += 1;
        }
        while (mi < 0) {
            mi += 60;
            hour_offset -= 1;
        }
        const timestamp_format = "{d:0>4}-{d:0>2}-{d:0>2}T{d:0>2}:{d:0>2}:{d:0>2}Z";
        const base = try std.fmt.allocPrint(self.arena, timestamp_format, .{
            @as(u32, @intCast(dt.y)),
            dt.m,
            dt.d,
            dt.h,
            @as(u8, @intCast(mi)),
            dt.sec,
        });
        if (hour_offset != 0) {
            return try self.eval_string_method(
                base,
                "addHours",
                &.{Value{ .integer = hour_offset }},
            );
        }
        return Value{ .string = base };
    }

    fn eval_string_add_seconds_method(
        self: *Evaluator,
        s: []const u8,
        method: []const u8,
        args: []const Value,
    ) anyerror!?Value {
        if (!std.ascii.eqlIgnoreCase(method, "addSeconds")) return null;
        const dt = parse_iso_date(s) orelse return Value{ .string = s };
        var sec: i32 = @as(i32, dt.sec) + string_method_delta_i32(args);
        var min_offset: i32 = 0;
        while (sec >= 60) {
            sec -= 60;
            min_offset += 1;
        }
        while (sec < 0) {
            sec += 60;
            min_offset -= 1;
        }
        const timestamp_format = "{d:0>4}-{d:0>2}-{d:0>2}T{d:0>2}:{d:0>2}:{d:0>2}Z";
        const base = try std.fmt.allocPrint(self.arena, timestamp_format, .{
            @as(u32, @intCast(dt.y)),
            dt.m,
            dt.d,
            dt.h,
            dt.mi,
            @as(u8, @intCast(sec)),
        });
        if (min_offset != 0) {
            return try self.eval_string_method(
                base,
                "addMinutes",
                &.{Value{ .integer = min_offset }},
            );
        }
        return Value{ .string = base };
    }

    fn eval_string_datetime_component_methods(
        _: *Evaluator,
        s: []const u8,
        method: []const u8,
    ) !?Value {
        if (std.ascii.eqlIgnoreCase(method, "year") or
            std.ascii.eqlIgnoreCase(method, "month") or
            std.ascii.eqlIgnoreCase(method, "day"))
        {
            const dt = parse_iso_date(s) orelse return Value.null_val;
            if (std.ascii.eqlIgnoreCase(method, "year")) return Value{ .integer = dt.y };
            if (std.ascii.eqlIgnoreCase(method, "month")) return Value{ .integer = dt.m };
            return Value{ .integer = dt.d };
        }
        if (std.ascii.eqlIgnoreCase(method, "hour") or
            std.ascii.eqlIgnoreCase(method, "hourGmt") or
            std.ascii.eqlIgnoreCase(method, "minute") or
            std.ascii.eqlIgnoreCase(method, "minuteGmt") or
            std.ascii.eqlIgnoreCase(method, "second") or
            std.ascii.eqlIgnoreCase(method, "secondGmt") or
            std.ascii.eqlIgnoreCase(method, "millisecond") or
            std.ascii.eqlIgnoreCase(method, "millisecondGmt"))
        {
            const dt = parse_iso_date(s) orelse return Value{ .integer = 0 };
            if (std.ascii.eqlIgnoreCase(method, "hour") or
                std.ascii.eqlIgnoreCase(method, "hourGmt"))
            {
                return Value{ .integer = dt.h };
            }
            if (std.ascii.eqlIgnoreCase(method, "minute") or
                std.ascii.eqlIgnoreCase(method, "minuteGmt"))
            {
                return Value{ .integer = dt.mi };
            }
            if (std.ascii.eqlIgnoreCase(method, "second") or
                std.ascii.eqlIgnoreCase(method, "secondGmt"))
            {
                return Value{ .integer = dt.sec };
            }
            return Value{ .integer = 0 };
        }
        if (std.ascii.eqlIgnoreCase(method, "yearGmt") or
            std.ascii.eqlIgnoreCase(method, "monthGmt") or
            std.ascii.eqlIgnoreCase(method, "dayGmt"))
        {
            const dt = parse_iso_date(s) orelse return Value.null_val;
            if (std.ascii.eqlIgnoreCase(method, "yearGmt")) return Value{ .integer = dt.y };
            if (std.ascii.eqlIgnoreCase(method, "monthGmt")) return Value{ .integer = dt.m };
            return Value{ .integer = dt.d };
        }
        if (std.ascii.eqlIgnoreCase(method, "dayOfYear")) {
            const dt = parse_iso_date(s) orelse return Value.null_val;
            const is_leap = @mod(dt.y, 4) == 0 and
                (@mod(dt.y, 100) != 0 or @mod(dt.y, 400) == 0);
            var doy: i32 = @as(i32, day_of_year(dt.m, dt.d));
            if (is_leap and dt.m > 2) doy += 1;
            return Value{ .integer = doy };
        }
        return null;
    }

    fn eval_string_datetime_arithmetic_methods(
        self: *Evaluator,
        s: []const u8,
        method: []const u8,
        args: []const Value,
    ) !?Value {
        if (std.ascii.eqlIgnoreCase(method, "addYears") or
            std.ascii.eqlIgnoreCase(method, "addMonths") or
            std.ascii.eqlIgnoreCase(method, "addDays"))
        {
            return try self.date_time_add(s, method, args);
        }
        if (std.ascii.eqlIgnoreCase(method, "daysBetween") and args.len > 0) {
            const other_str = other_date_string_arg(s, args[0]);
            const a = parse_iso_date(s) orelse return Value.null_val;
            const b = parse_iso_date(other_str) orelse return Value.null_val;
            const a_days = iso_date_to_epoch_days(a.y, a.m, a.d);
            const b_days = iso_date_to_epoch_days(b.y, b.m, b.d);
            return Value{ .integer = b_days - a_days };
        }
        if (std.ascii.eqlIgnoreCase(method, "monthsBetween") and args.len > 0) {
            const other_str = other_date_string_arg(s, args[0]);
            const a = parse_iso_date(s) orelse return Value.null_val;
            const b = parse_iso_date(other_str) orelse return Value.null_val;
            const diff = (@as(i64, b.y) - @as(i64, a.y)) * 12 +
                (@as(i64, b.m) - @as(i64, a.m));
            return Value{ .integer = diff };
        }
        if (std.ascii.eqlIgnoreCase(method, "formatGMT") or
            std.ascii.eqlIgnoreCase(method, "formatGmt"))
        {
            if (args.len > 0 and args[0] == .string) {
                return try self.format_date_time_pattern(s, args[0].string);
            }
            return try self.format_gmt_fallback(s);
        }
        return null;
    }

    fn other_date_string_arg(s: []const u8, arg: Value) []const u8 {
        return builtins.extract_date_string(arg) orelse
            (if (arg == .string) arg.string else s);
    }

    fn format_gmt_fallback(self: *Evaluator, s: []const u8) !Value {
        if (!(s.len >= 19 and s[4] == '-' and s[7] == '-' and s[10] == 'T')) {
            return Value{ .string = s };
        }
        const year = s[0..4];
        const month_num = std.fmt.parseInt(u8, s[5..7], 10) catch 1;
        const day = s[8..10];
        const hour24 = std.fmt.parseInt(u8, s[11..13], 10) catch 0;
        const minute = s[14..16];
        const second = s[17..19];
        const month_names = [_][]const u8{
            "January",
            "February",
            "March",
            "April",
            "May",
            "June",
            "July",
            "August",
            "September",
            "October",
            "November",
            "December",
        };
        const month_name = if (month_num >= 1 and month_num <= 12)
            month_names[month_num - 1]
        else
            "January";
        const hour12: u8 = if (hour24 == 0)
            12
        else if (hour24 > 12)
            hour24 - 12
        else
            hour24;
        const am_pm: []const u8 = if (hour24 < 12) "AM" else "PM";
        return Value{ .string = try std.fmt.allocPrint(
            self.arena,
            "{d:0>2}:{s}:{s} {s}, {s} {s}, {s}",
            .{ hour12, minute, second, am_pm, month_name, day, year },
        ) };
    }

    fn eval_string_enum_methods(
        self: *Evaluator,
        s: []const u8,
        method: []const u8,
        args: []const Value,
    ) !?Value {
        if (std.ascii.eqlIgnoreCase(method, "valueOf") and args.len > 0) {
            if (self.find_visible_enum_decl(s)) |enum_decl| {
                if (args[0] == .null_val) return Value.null_val;
                const raw_value = if (args[0] == .string)
                    args[0].string
                else
                    try utils.coerce_to_string(args[0], self.arena);
                for (enum_decl.values) |enum_value| {
                    if (std.ascii.eqlIgnoreCase(enum_value, raw_value)) {
                        return Value{ .string = enum_value };
                    }
                }
                const exc = try self.arena.create(types.ObjectInstance);
                exc.* = .{ .class_name = "System.NoSuchElementException" };
                const message = try std.fmt.allocPrint(
                    self.arena,
                    "No enum constant {s}.{s}",
                    .{ s, raw_value },
                );
                try exc.fields.put(self.arena, "message", Value{ .string = message });
                self.pending_exception = Value{ .object = exc };
                return error.ApexException;
            }
            return args[0];
        }
        if (std.ascii.eqlIgnoreCase(method, "valueOf") and args.len == 0) {
            return Value{ .string = s };
        }
        if (std.ascii.eqlIgnoreCase(method, "name")) return Value{ .string = s };
        if (std.ascii.eqlIgnoreCase(method, "values")) {
            var class_iter = self.classes.iterator();
            while (class_iter.next()) |entry| {
                for (entry.value_ptr.*.members) |member| {
                    switch (member) {
                        .enum_decl => |ed| {
                            if (std.ascii.eqlIgnoreCase(ed.name, s)) {
                                const list = try self.arena.create(types.ListValue);
                                list.* = .{};
                                for (ed.values) |v| {
                                    try list.items.append(self.arena, Value{ .string = v });
                                }
                                return Value{ .list = list };
                            }
                        },
                        else => {},
                    }
                }
            }
            return null;
        }
        if (std.ascii.eqlIgnoreCase(method, "ordinal")) {
            return Value{ .integer = lookup_enum_ordinal(s) };
        }
        return null;
    }

    fn eval_string_substring_helpers(
        _: *Evaluator,
        s: []const u8,
        method: []const u8,
        args: []const Value,
    ) !?Value {
        if (std.ascii.eqlIgnoreCase(method, "substringAfter") and
            args.len > 0 and
            args[0] == .string)
        {
            const sep = args[0].string;
            if (std.mem.indexOf(u8, s, sep)) |idx| {
                return Value{ .string = s[idx + sep.len ..] };
            }
            return Value{ .string = "" };
        }
        if (std.ascii.eqlIgnoreCase(method, "substringBefore") and
            args.len > 0 and
            args[0] == .string)
        {
            const sep = args[0].string;
            if (std.mem.indexOf(u8, s, sep)) |idx| {
                return Value{ .string = s[0..idx] };
            }
            return Value{ .string = s };
        }
        if (eval_string_substring_suffix_methods(s, method, args)) |result| {
            return result;
        }
        return null;
    }

    fn eval_string_substring_suffix_methods(
        s: []const u8,
        method: []const u8,
        args: []const Value,
    ) ?Value {
        if (std.ascii.eqlIgnoreCase(method, "substringAfterLast") and
            args.len > 0 and
            args[0] == .string)
        {
            const sep = args[0].string;
            if (sep.len == 0) return Value{ .string = "" };
            var last_idx: ?usize = null;
            var k: usize = 0;
            while (k + sep.len <= s.len) : (k += 1) {
                if (std.mem.eql(u8, s[k .. k + sep.len], sep)) last_idx = k;
            }
            if (last_idx) |idx| return Value{ .string = s[idx + sep.len ..] };
            return Value{ .string = "" };
        }
        if (std.ascii.eqlIgnoreCase(method, "substringBeforeLast") and
            args.len > 0 and
            args[0] == .string)
        {
            const sep = args[0].string;
            if (sep.len == 0) return Value{ .string = s };
            var last_idx: ?usize = null;
            var k: usize = 0;
            while (k + sep.len <= s.len) : (k += 1) {
                if (std.mem.eql(u8, s[k .. k + sep.len], sep)) last_idx = k;
            }
            if (last_idx) |idx| return Value{ .string = s[0..idx] };
            return Value{ .string = s };
        }
        if (std.ascii.eqlIgnoreCase(method, "countMatches") and
            args.len > 0 and
            args[0] == .string)
        {
            const sep = args[0].string;
            if (sep.len == 0) return Value{ .integer = 0 };
            var count: i64 = 0;
            var k: usize = 0;
            while (k + sep.len <= s.len) {
                if (std.mem.eql(u8, s[k .. k + sep.len], sep)) {
                    count += 1;
                    k += sep.len;
                } else {
                    k += 1;
                }
            }
            return Value{ .integer = count };
        }
        return null;
    }

    fn eval_string_misc_methods(
        self: *Evaluator,
        s: []const u8,
        method: []const u8,
        args: []const Value,
    ) !?Value {
        if (std.ascii.eqlIgnoreCase(method, "toInteger")) {
            return Value{ .integer = std.fmt.parseInt(i64, s, 10) catch 0 };
        }
        if (std.ascii.eqlIgnoreCase(method, "reverse")) {
            const reversed = try self.arena.alloc(u8, s.len);
            for (s, 0..) |ch, i| reversed[s.len - 1 - i] = ch;
            return Value{ .string = reversed };
        }
        if (std.ascii.eqlIgnoreCase(method, "charAt") and
            args.len > 0 and
            args[0] == .integer)
        {
            const idx: usize = @intCast(@max(args[0].integer, 0));
            if (idx < s.len) return Value{ .integer = @intCast(s[idx]) };
            return Value{ .integer = 0 };
        }
        if (std.ascii.eqlIgnoreCase(method, "compareTo") and
            args.len > 0 and
            args[0] == .string)
        {
            const other = args[0].string;
            const len = @min(s.len, other.len);
            for (0..len) |i| {
                if (s[i] < other[i]) return Value{ .integer = -1 };
                if (s[i] > other[i]) return Value{ .integer = 1 };
            }
            if (s.len < other.len) return Value{ .integer = -1 };
            if (s.len > other.len) return Value{ .integer = 1 };
            return Value{ .integer = 0 };
        }
        if (std.ascii.eqlIgnoreCase(method, "startsWithIgnoreCase") and
            args.len > 0 and
            args[0] == .string)
        {
            return Value{ .boolean = std.ascii.startsWithIgnoreCase(s, args[0].string) };
        }
        if (std.ascii.eqlIgnoreCase(method, "endsWithIgnoreCase") and
            args.len > 0 and
            args[0] == .string)
        {
            return Value{ .boolean = std.ascii.endsWithIgnoreCase(s, args[0].string) };
        }
        if (std.ascii.eqlIgnoreCase(method, "remove") and
            args.len > 0 and
            args[0] == .string)
        {
            const result = try std.mem.replaceOwned(u8, self.arena, s, args[0].string, "");
            return Value{ .string = result };
        }
        return null;
    }

    fn eval_string_get_sobject_type_method(
        self: *Evaluator,
        s: []const u8,
        method: []const u8,
    ) !?Value {
        if (!(std.ascii.eqlIgnoreCase(method, "getSobjectType") or
            std.ascii.eqlIgnoreCase(method, "getSObjectType")))
        {
            return null;
        }
        var type_name: []const u8 = "SObject";
        var store_iter = self.store.iterator();
        while (store_iter.next()) |entry| {
            for (entry.value_ptr.items) |rec| {
                if (rec == .sobject and
                    rec.sobject.id != null and
                    std.ascii.eqlIgnoreCase(rec.sobject.id.?, s))
                {
                    type_name = rec.sobject.type_name;
                    break;
                }
            }
        }
        if (std.mem.eql(u8, type_name, "SObject")) {
            if (self.id_type_map.get(s)) |tn| type_name = tn;
        }
        if (std.mem.eql(u8, type_name, "SObject") and s.len >= 3) {
            type_name = sobject_type_from_prefix(s[0..3]);
        }
        if (std.mem.eql(u8, type_name, "SObject") and s.len >= 3) {
            const id_prefix = s[0..3];
            var store_iter2 = self.store.iterator();
            while (store_iter2.next()) |entry| {
                const entry_prefix = sobject_key_prefix(entry.key_ptr.*);
                if (std.mem.eql(u8, &entry_prefix, id_prefix)) {
                    type_name = entry.key_ptr.*;
                    break;
                }
            }
            if (std.mem.eql(u8, type_name, "SObject")) {
                var ft_iter = self.field_types.iterator();
                while (ft_iter.next()) |entry| {
                    const entry_prefix = sobject_key_prefix(entry.key_ptr.*);
                    if (std.mem.eql(u8, &entry_prefix, id_prefix)) {
                        type_name = entry.key_ptr.*;
                        break;
                    }
                }
            }
        }
        if (is_template_s_object_type(type_name)) {
            const exc = try self.arena.create(types.ObjectInstance);
            exc.* = .{ .class_name = "System.SObjectException" };
            try exc.fields.put(self.arena, "message", Value{ .string = try std.fmt.allocPrint(
                self.arena,
                "Cannot locate Apex Type for {s}",
                .{type_name},
            ) });
            self.pending_exception = Value{ .object = exc };
            return error.ApexException;
        }
        const sot = try self.arena.create(types.ObjectInstance);
        sot.* = .{ .class_name = "Schema.SObjectType" };
        try sot.fields.put(self.arena, "name", Value{ .string = type_name });
        return Value{ .object = sot };
    }

    fn eval_string_schema_timezone_methods(
        self: *Evaluator,
        s: []const u8,
        method: []const u8,
    ) !?Value {
        if (std.ascii.eqlIgnoreCase(method, "getDescribe")) {
            const dfr = try self.arena.create(types.ObjectInstance);
            dfr.* = .{ .class_name = "Schema.DescribeFieldResult" };
            try dfr.fields.put(self.arena, "fieldName", Value{ .string = s });
            return Value{ .object = dfr };
        }
        if (std.ascii.eqlIgnoreCase(method, "getOffset")) {
            return Value{ .integer = 0 };
        }
        if (std.ascii.eqlIgnoreCase(method, "getID") or std.ascii.eqlIgnoreCase(method, "getId")) {
            return Value{ .string = s };
        }
        if (std.ascii.eqlIgnoreCase(method, "getDisplayName")) {
            return Value{ .string = s };
        }
        return null;
    }

    // -----------------------------------------------------------------------
    // new 式
    // -----------------------------------------------------------------------

    fn eval_new_expr(self: *Evaluator, ne: *ast.NewExpr, current_env: *Env) !Value {
        const raw_type_name = ne.type_name.name;
        const is_platform_qualified = is_platform_qualified_new_type(raw_type_name);
        const type_name = normalized_new_type_name(raw_type_name);

        if (try self.new_type_literal_value(ne, type_name)) |result| return result;
        if (try self.new_collection_value(ne, type_name, current_env)) |result| return result;
        if (try self.new_builtin_object_value(ne, type_name, current_env)) |result| return result;
        if (try self.instantiate_metadata_framework_class(type_name)) |result| return result;

        const obj = try self.new_sobject_from_assignments(ne, type_name, current_env);
        if (self.is_s_object_type_name(type_name)) return Value{ .sobject = obj };
        if (try self.new_user_class_value(
            ne,
            type_name,
            is_platform_qualified,
            current_env,
        )) |result| {
            return result;
        }
        if (try self.new_fallback_exception_value(
            ne,
            type_name,
            current_env,
        )) |result| return result;
        return Value{ .sobject = obj };
    }

    fn is_platform_qualified_new_type(raw_type_name: []const u8) bool {
        return std.ascii.startsWithIgnoreCase(raw_type_name, "System.") or
            std.ascii.startsWithIgnoreCase(raw_type_name, "Schema.");
    }

    fn normalized_new_type_name(raw_type_name: []const u8) []const u8 {
        if (std.ascii.startsWithIgnoreCase(raw_type_name, "System.")) return raw_type_name[7..];
        if (std.ascii.startsWithIgnoreCase(raw_type_name, "Schema.")) return raw_type_name[7..];
        return raw_type_name;
    }

    fn new_type_literal_value(
        self: *Evaluator,
        ne: *ast.NewExpr,
        type_name: []const u8,
    ) !?Value {
        if ((std.mem.indexOf(u8, type_name, "<") == null and
            !std.mem.endsWith(u8, type_name, "[]")) or
            ne.args.len != 0)
        {
            return null;
        }
        const type_obj = try self.arena.create(types.ObjectInstance);
        type_obj.* = .{ .class_name = "Type" };
        try type_obj.fields.put(self.arena, "name", Value{ .string = type_name });
        return Value{ .object = type_obj };
    }

    fn new_collection_value(
        self: *Evaluator,
        ne: *ast.NewExpr,
        type_name: []const u8,
        current_env: *Env,
    ) !?Value {
        if (std.ascii.eqlIgnoreCase(type_name, "List")) {
            return try self.new_list_value(ne, current_env);
        }
        if (std.ascii.eqlIgnoreCase(type_name, "Map")) {
            return try self.new_map_value(ne, current_env);
        }
        if (std.ascii.startsWithIgnoreCase(type_name, "DataWeaveScriptResource")) {
            return try self.new_dataweave_script_value(type_name);
        }
        if (std.ascii.eqlIgnoreCase(type_name, "Set")) {
            return try self.new_set_value(ne, current_env);
        }
        return null;
    }

    fn new_list_value(self: *Evaluator, ne: *ast.NewExpr, current_env: *Env) !Value {
        const list = try self.arena.create(types.ListValue);
        list.* = .{};
        if (ne.type_name.params.len > 0) {
            const rendered = strip_type_namespace(self.render_type_ref(ne.type_name.params[0]));
            list.element_type = rendered;
            const rendered_base = type_base_name(rendered);
            if (std.ascii.eqlIgnoreCase(rendered_base, "SObject") or
                std.ascii.eqlIgnoreCase(rendered_base, "Object"))
            {
                list.explicitly_generic = true;
            }
        }
        if (ne.args.len == 1 and !ne.is_brace_initializer) {
            var arg_copy = ne.args[0];
            const arg_val = try self.eval_expr(&arg_copy, current_env);
            try self.populate_new_list_from_single_arg(list, arg_val);
            return Value{ .list = list };
        }
        for (ne.args) |*arg| {
            try list.items.append(self.arena, try self.eval_expr(arg, current_env));
        }
        return Value{ .list = list };
    }

    fn populate_new_list_from_single_arg(
        self: *Evaluator,
        list: *types.ListValue,
        arg_val: Value,
    ) !void {
        if (arg_val == .set) {
            for (arg_val.set.entries.values()) |item| try list.items.append(self.arena, item);
            return;
        }
        if (arg_val == .list) {
            for (arg_val.list.items.items) |item| try list.items.append(self.arena, item);
            return;
        }
        try list.items.append(self.arena, arg_val);
    }

    fn new_map_value(self: *Evaluator, ne: *ast.NewExpr, current_env: *Env) !Value {
        const map = try self.arena.create(types.MapValue);
        map.* = .{};
        for (ne.args) |*arg| {
            if (arg.* != .assignment) continue;
            const asgn = arg.assignment;
            const key_val = try self.eval_expr(asgn.target, current_env);
            const val_val = try self.eval_expr(asgn.value, current_env);
            const key_str = if (key_val == .null_val)
                ""
            else
                try utils.coerce_to_string(key_val, self.arena);
            try map.entries.put(self.arena, key_str, val_val);
            try map.key_values.put(self.arena, key_str, key_val);
        }
        try self.populate_new_map_from_single_arg(map, ne, current_env);
        return Value{ .map = map };
    }

    fn populate_new_map_from_single_arg(
        self: *Evaluator,
        map: *types.MapValue,
        ne: *ast.NewExpr,
        current_env: *Env,
    ) !void {
        if (ne.args.len != 1 or ne.args[0] == .assignment) return;
        var arg_copy = ne.args[0];
        const arg_val = try self.eval_expr(&arg_copy, current_env);
        if (arg_val != .list) return;
        for (arg_val.list.items.items) |item| {
            if (item == .sobject and item.sobject.id != null) {
                try map.entries.put(self.arena, item.sobject.id.?, item);
                try map.key_values.put(
                    self.arena,
                    item.sobject.id.?,
                    Value{ .string = item.sobject.id.? },
                );
            }
        }
    }

    fn new_dataweave_script_value(self: *Evaluator, type_name: []const u8) !Value {
        const instance = try self.arena.create(types.ObjectInstance);
        instance.* = .{ .class_name = "DataWeave.Script" };
        const dot_pos = std.mem.lastIndexOfScalar(u8, type_name, '.');
        const script_name = if (dot_pos) |dp| type_name[dp + 1 ..] else type_name;
        try instance.fields.put(self.arena, "scriptName", Value{ .string = script_name });
        return Value{ .object = instance };
    }

    fn new_set_value(self: *Evaluator, ne: *ast.NewExpr, current_env: *Env) !Value {
        const set = try self.arena.create(types.SetValue);
        set.* = .{};
        for (ne.args) |*arg| {
            const v = try self.eval_expr(arg, current_env);
            try self.append_new_set_value(set, v);
        }
        return Value{ .set = set };
    }

    fn append_new_set_value(self: *Evaluator, set: *types.SetValue, value: Value) !void {
        if (value == .list) {
            for (value.list.items.items) |item| {
                const key = try self.set_entry_key(item);
                try set.entries.put(self.arena, key, item);
            }
            return;
        }
        if (value == .set) {
            for (value.set.entries.keys(), value.set.entries.values()) |k, item| {
                try set.entries.put(self.arena, k, item);
            }
            return;
        }
        const key = try self.set_entry_key(value);
        try set.entries.put(self.arena, key, value);
    }

    fn new_builtin_object_value(
        self: *Evaluator,
        ne: *ast.NewExpr,
        type_name: []const u8,
        current_env: *Env,
    ) !?Value {
        if (try self.new_builtin_exception_value(
            ne,
            type_name,
            current_env,
        )) |result| return result;
        if (try self.new_standard_controller_value(
            ne,
            type_name,
            current_env,
        )) |result| return result;
        return try self.new_known_non_sobject_value(ne, type_name, current_env);
    }

    fn new_builtin_exception_value(
        self: *Evaluator,
        ne: *ast.NewExpr,
        type_name: []const u8,
        current_env: *Env,
    ) !?Value {
        const builtin_exception_types = [_][]const u8{
            "Exception",
            "DMLException",
            "DmlException",
            "NullPointerException",
            "TypeException",
            "QueryException",
            "JSONException",
            "ListException",
            "MathException",
            "SecurityException",
            "NoAccessException",
            "InvalidParameterValueException",
            "CalloutException",
            "StringException",
            "NoSuchElementException",
            "NoDataFoundException",
            "SearchException",
            "SObjectException",
            "HandledException",
            "IllegalArgumentException",
            "LimitException",
            "AsyncException",
            "SerializationException",
            "FlowException",
            "FinalException",
            "UnsupportedOperationException",
            "EventBusException",
        };
        inline for (builtin_exception_types) |exc_type| {
            if (std.ascii.eqlIgnoreCase(type_name, exc_type)) {
                const instance = try self.arena.create(types.ObjectInstance);
                instance.* = .{ .class_name = exc_type };
                if (ne.args.len > 0) {
                    var arg_copy = ne.args[0];
                    const message = try self.eval_expr(&arg_copy, current_env);
                    try instance.fields.put(self.arena, "message", message);
                }
                return Value{ .object = instance };
            }
        }
        return null;
    }

    fn new_standard_controller_value(
        self: *Evaluator,
        ne: *ast.NewExpr,
        type_name: []const u8,
        current_env: *Env,
    ) !?Value {
        if (std.ascii.eqlIgnoreCase(type_name, "ApexPages.StandardController") or
            std.ascii.eqlIgnoreCase(type_name, "StandardController"))
        {
            const instance = try self.arena.create(types.ObjectInstance);
            instance.* = .{ .class_name = "ApexPages.StandardController" };
            if (ne.args.len > 0) {
                var arg_copy = ne.args[0];
                const record = try self.eval_expr(&arg_copy, current_env);
                try instance.fields.put(self.arena, "record", record);
            }
            return Value{ .object = instance };
        }
        if (std.ascii.eqlIgnoreCase(type_name, "ApexPages.StandardSetController") or
            std.ascii.eqlIgnoreCase(type_name, "StandardSetController"))
        {
            const instance = try self.arena.create(types.ObjectInstance);
            instance.* = .{ .class_name = "ApexPages.StandardSetController" };
            if (ne.args.len > 0) {
                var arg_copy = ne.args[0];
                const records = try self.eval_expr(&arg_copy, current_env);
                try instance.fields.put(self.arena, "records", records);
            }
            try instance.fields.put(self.arena, "pageSize", Value{ .integer = 20 });
            return Value{ .object = instance };
        }
        return null;
    }

    fn new_known_non_sobject_value(
        self: *Evaluator,
        ne: *ast.NewExpr,
        type_name: []const u8,
        current_env: *Env,
    ) !?Value {
        const non_sobject_types = [_][]const u8{
            "RestRequest",
            "RestResponse",
            "HttpRequest",
            "HttpResponse",
            "Http",
            "PageReference",
            "SelectOption",
            "Messaging.SingleEmailMessage",
            "Messaging.InboundEmail",
            "QueryException",
            "DmlException",
            "AuraHandledException",
            "CalloutException",
            "Database.DmlOptions",
            "DmlOptions",
            "ApexPages.Message",
            "VisualEditor.DataRow",
            "DataRow",
            "VisualEditor.DynamicPickListRows",
            "DynamicPickListRows",
        };
        for (non_sobject_types) |nst| {
            if (!std.ascii.eqlIgnoreCase(type_name, nst)) continue;
            const instance = try self.arena.create(types.ObjectInstance);
            instance.* = .{ .class_name = type_name };
            try self.populate_new_known_non_sobject(instance, ne, type_name, current_env);
            return Value{ .object = instance };
        }
        return null;
    }

    fn populate_new_known_non_sobject(
        self: *Evaluator,
        instance: *types.ObjectInstance,
        ne: *ast.NewExpr,
        type_name: []const u8,
        current_env: *Env,
    ) !void {
        if (try self.populate_new_known_non_sobject_special(
            instance,
            ne,
            type_name,
            current_env,
        )) return;
        if (ne.args.len == 0 or !std.mem.endsWith(u8, type_name, "Exception")) return;

        var arg_copy = ne.args[0];
        const arg_val = try self.eval_expr(&arg_copy, current_env);
        if (std.ascii.eqlIgnoreCase(type_name, "AuraHandledException")) {
            try instance.fields.put(
                self.arena,
                "message",
                Value{ .string = "Script-thrown exception" },
            );
            return;
        }
        try instance.fields.put(self.arena, "message", arg_val);
    }

    fn populate_new_known_non_sobject_special(
        self: *Evaluator,
        instance: *types.ObjectInstance,
        ne: *ast.NewExpr,
        type_name: []const u8,
        current_env: *Env,
    ) !bool {
        if (std.ascii.eqlIgnoreCase(type_name, "SelectOption")) {
            try self.populate_new_select_option(instance, ne, current_env);
            return true;
        }
        if (std.ascii.eqlIgnoreCase(type_name, "VisualEditor.DataRow") or
            std.ascii.eqlIgnoreCase(type_name, "DataRow"))
        {
            try self.populate_new_data_row(instance, ne, current_env);
            return true;
        }
        if (std.ascii.eqlIgnoreCase(type_name, "VisualEditor.DynamicPickListRows") or
            std.ascii.eqlIgnoreCase(type_name, "DynamicPickListRows"))
        {
            try self.populate_new_dynamic_picklist_rows(instance);
            return true;
        }
        if (std.ascii.eqlIgnoreCase(type_name, "ApexPages.Message")) {
            try self.populate_new_apex_pages_message(instance, ne, current_env);
            return true;
        }
        if (std.ascii.eqlIgnoreCase(type_name, "PageReference")) {
            try self.populate_new_page_reference(instance, ne, current_env);
            return true;
        }
        if (std.ascii.eqlIgnoreCase(type_name, "RestRequest")) {
            try self.populate_new_rest_request(instance);
            return true;
        }
        if (std.ascii.eqlIgnoreCase(type_name, "RestResponse")) {
            try self.populate_new_rest_response(instance);
            return true;
        }
        return false;
    }

    fn populate_new_select_option(
        self: *Evaluator,
        instance: *types.ObjectInstance,
        ne: *ast.NewExpr,
        current_env: *Env,
    ) !void {
        if (ne.args.len < 2) return;
        var arg0_copy = ne.args[0];
        var arg1_copy = ne.args[1];
        const val = try self.eval_expr(&arg0_copy, current_env);
        const label = try self.eval_expr(&arg1_copy, current_env);
        const val_str = try utils.coerce_to_string(val, self.arena);
        const label_str = try utils.coerce_to_string(label, self.arena);
        try instance.fields.put(self.arena, "value", Value{ .string = val_str });
        try instance.fields.put(self.arena, "label", Value{ .string = label_str });
        if (ne.args.len >= 3) {
            var arg2_copy = ne.args[2];
            const disabled = try self.eval_expr(&arg2_copy, current_env);
            try instance.fields.put(self.arena, "disabled", disabled);
        } else {
            try instance.fields.put(self.arena, "disabled", Value{ .boolean = false });
        }
    }

    fn populate_new_data_row(
        self: *Evaluator,
        instance: *types.ObjectInstance,
        ne: *ast.NewExpr,
        current_env: *Env,
    ) !void {
        if (ne.args.len < 2) return;
        var arg0_copy = ne.args[0];
        var arg1_copy = ne.args[1];
        const label = try self.eval_expr(&arg0_copy, current_env);
        const value = try self.eval_expr(&arg1_copy, current_env);
        try instance.fields.put(self.arena, "label", label);
        try instance.fields.put(self.arena, "value", value);
    }

    fn populate_new_dynamic_picklist_rows(self: *Evaluator, instance: *types.ObjectInstance) !void {
        const data_rows = try self.arena.create(types.ListValue);
        data_rows.* = .{};
        try instance.fields.put(self.arena, "dataRows", Value{ .list = data_rows });
    }

    fn populate_new_apex_pages_message(
        self: *Evaluator,
        instance: *types.ObjectInstance,
        ne: *ast.NewExpr,
        current_env: *Env,
    ) !void {
        const severity = try self.new_message_arg_string(ne, current_env, 0, "ERROR");
        const summary = try self.new_message_arg_string(ne, current_env, 1, "");
        const detail = try self.new_message_arg_string(ne, current_env, 2, summary);
        try instance.fields.put(self.arena, "severity", Value{ .string = severity });
        try instance.fields.put(self.arena, "summary", Value{ .string = summary });
        try instance.fields.put(self.arena, "detail", Value{ .string = detail });
        try instance.fields.put(self.arena, "message", Value{ .string = summary });
    }

    fn new_message_arg_string(
        self: *Evaluator,
        ne: *ast.NewExpr,
        current_env: *Env,
        index: usize,
        fallback: []const u8,
    ) ![]const u8 {
        if (ne.args.len <= index) return fallback;
        var arg_copy = ne.args[index];
        const arg_val = try self.eval_expr(&arg_copy, current_env);
        return try utils.coerce_to_string(arg_val, self.arena);
    }

    fn populate_new_page_reference(
        self: *Evaluator,
        instance: *types.ObjectInstance,
        ne: *ast.NewExpr,
        current_env: *Env,
    ) !void {
        if (ne.args.len > 0) {
            var arg0_copy = ne.args[0];
            const url_val = try self.eval_expr(&arg0_copy, current_env);
            if (url_val == .string) {
                try instance.fields.put(self.arena, "url", url_val);
            } else {
                try instance.fields.put(
                    self.arena,
                    "url",
                    Value{ .string = try utils.coerce_to_string(url_val, self.arena) },
                );
            }
        } else {
            try instance.fields.put(self.arena, "url", Value{ .string = "" });
        }
        const params = try self.arena.create(types.MapValue);
        params.* = .{};
        try instance.fields.put(self.arena, "parameters", Value{ .map = params });
    }

    fn populate_new_rest_request(self: *Evaluator, instance: *types.ObjectInstance) !void {
        const params = try self.arena.create(types.MapValue);
        params.* = .{};
        try instance.fields.put(self.arena, "params", Value{ .map = params });
        const headers = try self.arena.create(types.MapValue);
        headers.* = .{};
        try instance.fields.put(self.arena, "headers", Value{ .map = headers });
        const blob = try self.arena.create(types.ObjectInstance);
        blob.* = .{ .class_name = "Blob" };
        try blob.fields.put(self.arena, "value", Value.null_val);
        try instance.fields.put(self.arena, "requestBody", Value{ .object = blob });
    }

    fn populate_new_rest_response(self: *Evaluator, instance: *types.ObjectInstance) !void {
        const blob = try self.arena.create(types.ObjectInstance);
        blob.* = .{ .class_name = "Blob" };
        try blob.fields.put(self.arena, "value", Value{ .string = "" });
        try instance.fields.put(self.arena, "responseBody", Value{ .object = blob });
        const headers = try self.arena.create(types.MapValue);
        headers.* = .{};
        try instance.fields.put(self.arena, "headers", Value{ .map = headers });
    }

    fn new_sobject_from_assignments(
        self: *Evaluator,
        ne: *ast.NewExpr,
        type_name: []const u8,
        current_env: *Env,
    ) !*types.SObject {
        const sob_type_name = if (std.ascii.startsWithIgnoreCase(type_name, "Schema."))
            type_name[7..]
        else
            type_name;
        const obj = try self.arena.create(types.SObject);
        obj.* = .{ .type_name = sob_type_name };
        for (ne.args) |*arg| {
            if (arg.* != .assignment) continue;
            const asgn = arg.assignment;
            if (asgn.target.* != .identifier) continue;
            const field_name = asgn.target.identifier.name;
            const field_val = try self.eval_expr(asgn.value, current_env);
            try obj.fields.put(self.arena, field_name, field_val);
            if (std.ascii.eqlIgnoreCase(field_name, "Id") and field_val == .string) {
                obj.id = field_val.string;
            }
        }
        return obj;
    }

    fn new_user_class_value(
        self: *Evaluator,
        ne: *ast.NewExpr,
        type_name: []const u8,
        is_platform_qualified: bool,
        current_env: *Env,
    ) !?Value {
        const resolved_class_name = self.resolve_new_user_class_name(
            type_name,
            is_platform_qualified,
            current_env,
        );
        const class_name = resolved_class_name orelse return null;
        const class_decl = self.find_class(class_name) orelse return null;
        return try self.instantiate_new_user_class(
            class_name,
            class_decl,
            ne,
            type_name,
            current_env,
        );
    }

    fn resolve_new_user_class_name(
        self: *Evaluator,
        type_name: []const u8,
        is_platform_qualified: bool,
        current_env: *Env,
    ) ?[]const u8 {
        const simple_name = simple_type_name(type_name);
        const fq_inner_name: ?[]const u8 = if (self.current_class) |cc|
            (if (std.mem.indexOfScalar(u8, type_name, '.') == null)
                (std.fmt.allocPrint(self.arena, "{s}.{s}", .{ cc, type_name }) catch null)
            else
                null)
        else
            null;
        const allow_simple_name_fallback =
            !is_platform_qualified and std.mem.indexOfScalar(u8, type_name, '.') == null;
        if (!is_platform_qualified) {
            if (!std.ascii.eqlIgnoreCase(simple_name, "Database")) {
                if (self.resolve_visible_user_class_in_scope(
                    current_env,
                    type_name,
                )) |visible_class| {
                    return visible_class;
                }
            }
            if (fq_inner_name) |fqn| {
                if (self.find_class(fqn) != null) return fqn;
            }
            if (self.find_class(type_name) != null) return type_name;
        }
        if (allow_simple_name_fallback and self.find_class(simple_name) != null) {
            if (self.find_outer_class_name(simple_name)) |outer| {
                return std.fmt.allocPrint(
                    self.arena,
                    "{s}.{s}",
                    .{ outer, simple_name },
                ) catch simple_name;
            }
            return simple_name;
        }
        return null;
    }

    const ConstructorEvalResult = struct {
        args: std.ArrayListUnmanaged(Value),
        hints: std.ArrayListUnmanaged(?[]const u8),
        has_enum_hint: bool,
    };

    fn instantiate_new_user_class(
        self: *Evaluator,
        class_name: []const u8,
        class_decl: *ast.ClassDecl,
        ne: *ast.NewExpr,
        type_name: []const u8,
        current_env: *Env,
    ) !Value {
        const instance = try self.arena.create(types.ObjectInstance);
        instance.* = .{ .class_name = class_name };
        self.ensure_static_init(class_decl.name);
        if (class_decl.super_class) |sc| self.ensure_static_init(sc.name);

        if (try self.new_user_exception_without_constructor(
            class_decl,
            type_name,
            instance,
            ne,
            current_env,
        )) |result| {
            return result;
        }
        try self.init_new_user_class_fields(class_decl, instance);

        const ctor_eval = try self.evaluate_new_constructor_args(ne, current_env);
        const prev_ctor_hints = self.cast_type_hints;
        if (ctor_eval.has_enum_hint) self.cast_type_hints = ctor_eval.hints.items;
        defer if (ctor_eval.has_enum_hint) {
            self.cast_type_hints = prev_ctor_hints;
        };

        try self.run_implicit_parent_constructor(
            class_decl,
            instance,
            ctor_eval.args.items,
        );
        try self.run_constructor(class_decl, instance, ctor_eval.args.items);
        return Value{ .object = instance };
    }

    fn new_user_exception_without_constructor(
        self: *Evaluator,
        class_decl: *ast.ClassDecl,
        type_name: []const u8,
        instance: *types.ObjectInstance,
        ne: *ast.NewExpr,
        current_env: *Env,
    ) !?Value {
        const is_exc = if (class_decl.super_class) |sc|
            std.mem.endsWith(u8, sc.name, "Exception")
        else
            std.mem.endsWith(u8, type_name, "Exception");
        if (!is_exc or class_decl_has_constructor(class_decl)) return null;
        if (ne.args.len > 0) {
            var arg_copy = ne.args[0];
            const msg_val = try self.eval_expr(&arg_copy, current_env);
            try instance.fields.put(self.arena, "message", msg_val);
        }
        return Value{ .object = instance };
    }

    fn class_decl_has_constructor(class_decl: *ast.ClassDecl) bool {
        for (class_decl.members) |member| {
            switch (member) {
                .constructor_decl => return true,
                else => {},
            }
        }
        return false;
    }

    fn init_new_user_class_fields(
        self: *Evaluator,
        class_decl: *ast.ClassDecl,
        instance: *types.ObjectInstance,
    ) !void {
        var chain: std.ArrayListUnmanaged(*ast.ClassDecl) = .empty;
        defer chain.deinit(self.arena);

        var cursor: ?*ast.ClassDecl = if (class_decl.super_class) |sc|
            self.find_class(sc.name)
        else
            null;
        while (cursor) |cd_cursor| {
            try chain.append(self.arena, cd_cursor);
            cursor = if (cd_cursor.super_class) |sc| self.find_class(sc.name) else null;
        }
        var i: usize = chain.items.len;
        while (i > 0) {
            i -= 1;
            self.init_instance_fields(chain.items[i], instance) catch {};
        }
        self.init_instance_fields(class_decl, instance) catch {};
    }

    fn evaluate_new_constructor_args(
        self: *Evaluator,
        ne: *ast.NewExpr,
        current_env: *Env,
    ) !ConstructorEvalResult {
        var eval_args: std.ArrayListUnmanaged(Value) = .empty;
        var ctor_type_hints: std.ArrayListUnmanaged(?[]const u8) = .empty;
        var any_enum_hint = false;
        for (ne.args) |*arg| {
            const enum_hint = self.new_constructor_enum_hint(arg, current_env);
            if (enum_hint != null) any_enum_hint = true;
            try ctor_type_hints.append(self.arena, enum_hint);
            try eval_args.append(self.arena, try self.eval_expr(arg, current_env));
        }
        return .{
            .args = eval_args,
            .hints = ctor_type_hints,
            .has_enum_hint = any_enum_hint,
        };
    }

    fn new_constructor_enum_hint(self: *Evaluator, arg: *ast.Expr, current_env: *Env) ?[]const u8 {
        return self.enum_access_type_name(arg) orelse blk: {
            if (arg.* != .identifier) break :blk null;
            if (self.resolve_assignment_target_type(arg, current_env)) |t| {
                const base = type_base_name(strip_type_namespace(t));
                if (is_system_enum_type_name(base)) break :blk base;
                if (self.find_visible_enum_decl(base) != null) break :blk base;
            }
            break :blk null;
        };
    }

    fn run_implicit_parent_constructor(
        self: *Evaluator,
        class_decl: *ast.ClassDecl,
        instance: *types.ObjectInstance,
        eval_args: []const Value,
    ) !void {
        if (class_decl.super_class) |sc| {
            if (self.find_class(sc.name)) |parent_decl| {
                const child_chosen = self.find_matching_constructor(class_decl, eval_args);
                const child_explicit = if (child_chosen) |cc|
                    ctor_starts_with_super_or_this(cc)
                else
                    false;
                if (!child_explicit and class_has_no_arg_ctor(parent_decl)) {
                    try self.run_constructor(parent_decl, instance, &.{});
                }
            }
        }
    }

    fn new_fallback_exception_value(
        self: *Evaluator,
        ne: *ast.NewExpr,
        type_name: []const u8,
        current_env: *Env,
    ) !?Value {
        if (!std.mem.endsWith(u8, type_name, "Exception")) return null;
        const instance = try self.arena.create(types.ObjectInstance);
        instance.* = .{ .class_name = type_name };
        if (ne.args.len > 0) {
            var arg_copy = ne.args[0];
            const msg_val = try self.eval_expr(&arg_copy, current_env);
            try instance.fields.put(self.arena, "message", msg_val);
        }
        return Value{ .object = instance };
    }

    // -----------------------------------------------------------------------
    // フィールドアクセス
    // -----------------------------------------------------------------------

    fn eval_field_access(
        self: *Evaluator,
        fa: *ast.FieldAccess,
        obj: Value,
        current_env: *Env,
    ) !Value {
        if (try self.eval_field_access_special_cases(fa)) |value| return value;
        if (try self.eval_field_access_value_path(fa, obj)) |value| return value;
        if (try self.eval_field_access_static_path(fa, obj, current_env)) |value| return value;
        return Value.null_val;
    }

    fn eval_field_access_special_cases(
        self: *Evaluator,
        fa: *ast.FieldAccess,
    ) anyerror!?Value {
        if (fa.object.* == .field_access) {
            const inner_fa = fa.object.field_access;
            if (inner_fa.object.* == .identifier and
                std.ascii.eqlIgnoreCase(inner_fa.object.identifier.name, "ApexPages") and
                std.ascii.eqlIgnoreCase(inner_fa.field, "Severity"))
            {
                return Value{ .string = fa.field };
            }
        }

        const schema_value = try self.coerce_schema_field_access(fa, Value.null_val);
        if (schema_value != .null_val) return schema_value;

        if (fa.object.* == .identifier and
            std.ascii.eqlIgnoreCase(fa.object.identifier.name, "SObjectType"))
        {
            return try self.schema_s_object_type_value(fa.field);
        }
        if (fa.object.* == .identifier and
            std.ascii.eqlIgnoreCase(fa.object.identifier.name, "System") and
            std.ascii.eqlIgnoreCase(fa.field, "Search"))
        {
            const search = try self.arena.create(types.ObjectInstance);
            search.* = .{ .class_name = "Search" };
            return Value{ .object = search };
        }
        if (fa.object.* == .field_access) {
            const inner = fa.object.field_access;
            const is_system_label = (inner.object.* == .identifier and
                std.ascii.eqlIgnoreCase(inner.object.identifier.name, "System") and
                std.ascii.eqlIgnoreCase(inner.field, "Label")) or
                (inner.object.* == .identifier and
                    std.ascii.eqlIgnoreCase(inner.object.identifier.name, "Label"));
            if (is_system_label) {
                return Value{ .string = try self.arena.dupe(u8, fa.field) };
            }
        }
        if (fa.object.* == .identifier and
            std.ascii.eqlIgnoreCase(fa.object.identifier.name, "Label"))
        {
            return Value{ .string = try self.arena.dupe(u8, fa.field) };
        }
        return null;
    }

    fn eval_field_access_value_path(
        self: *Evaluator,
        fa: *ast.FieldAccess,
        obj: Value,
    ) anyerror!?Value {
        return switch (obj) {
            .list => try self.eval_list_field_access(fa, obj),
            .sobject => try self.eval_sobject_field_access(fa, obj),
            .object => try self.eval_object_field_access(fa, obj),
            .string => try self.eval_string_field_access(fa, obj.string),
            else => null,
        };
    }

    fn eval_list_field_access(
        self: *Evaluator,
        fa: *ast.FieldAccess,
        obj: Value,
    ) anyerror!Value {
        if (obj.list.items.items.len == 0 and fa.object.* == .soql) {
            const exc = try self.arena.create(types.ObjectInstance);
            exc.* = .{ .class_name = "QueryException" };
            try exc.fields.put(
                self.arena,
                "message",
                Value{ .string = "List has no rows for assignment to SObject" },
            );
            self.pending_exception = Value{ .object = exc };
            return error.ApexException;
        }
        if (obj.list.items.items.len > 0) {
            const first = obj.list.items.items[0];
            if (first == .sobject) {
                return self.get_s_object_field_value_case_insensitive(
                    first.sobject,
                    fa.field,
                ) orelse Value.null_val;
            }
        }
        if (std.ascii.eqlIgnoreCase(fa.field, "size")) {
            return Value{ .integer = @intCast(obj.list.items.items.len) };
        }
        return Value.null_val;
    }

    fn eval_sobject_field_access(
        self: *Evaluator,
        fa: *ast.FieldAccess,
        obj: Value,
    ) anyerror!Value {
        if (self.get_s_object_field_value_case_insensitive(
            obj.sobject,
            fa.field,
        )) |value| return value;
        if (obj.sobject.is_stripped) {
            const exc = try self.arena.create(types.ObjectInstance);
            exc.* = .{ .class_name = "SObjectException" };
            try exc.fields.put(
                self.arena,
                "message",
                Value{ .string = soql_missing_field_message },
            );
            self.pending_exception = Value{ .object = exc };
            return error.ApexException;
        }
        return Value.null_val;
    }

    fn eval_object_field_access(
        self: *Evaluator,
        fa: *ast.FieldAccess,
        obj: Value,
    ) anyerror!Value {
        if (self.find_class(obj.object.class_name)) |cd| {
            if (try self.eval_object_property_getter(
                obj.object,
                cd,
                fa.field,
            )) |value| return value;
        }
        if (try self.eval_schema_object_field_access(
            obj.object,
            fa.field,
        )) |value| return value;
        for (obj.object.fields.keys(), obj.object.fields.values()) |k, v| {
            if (std.ascii.eqlIgnoreCase(k, fa.field)) return v;
        }
        return Value.null_val;
    }

    fn eval_object_property_getter(
        self: *Evaluator,
        instance: *types.ObjectInstance,
        root_class_decl: *ast.ClassDecl,
        field_name: []const u8,
    ) anyerror!?Value {
        var cur_cd: ?*ast.ClassDecl = root_class_decl;
        while (cur_cd) |cd| {
            for (cd.members) |member| {
                switch (member) {
                    .field_decl => |fd| {
                        if (std.ascii.eqlIgnoreCase(fd.name, field_name) and
                            fd.getter_body != null)
                        {
                            return try self.execute_object_property_getter(
                                instance,
                                root_class_decl,
                                cd.name,
                                fd,
                            );
                        }
                    },
                    else => {},
                }
            }
            cur_cd = if (cd.super_class) |sc| self.find_class(sc.name) else null;
        }
        return null;
    }

    fn execute_object_property_getter(
        self: *Evaluator,
        instance: *types.ObjectInstance,
        root_class_decl: *ast.ClassDecl,
        owner_class_name: []const u8,
        field_decl: anytype,
    ) anyerror!Value {
        if (self.evaluating_getter) |eg| {
            if (std.ascii.eqlIgnoreCase(eg, field_decl.name) and
                self.evaluating_getter_instance == instance)
            {
                if (field_decl.modifiers.is_static) {
                    return self.read_static_backing_value(owner_class_name, field_decl.name);
                }
                if (instance.fields.get(field_decl.name)) |value| return value;
                for (instance.fields.keys(), instance.fields.values()) |key, value| {
                    if (std.ascii.eqlIgnoreCase(key, field_decl.name)) return value;
                }
                return Value.null_val;
            }
        }

        const getter_env = self.global_env.child() catch return Value.null_val;
        getter_env.define("this", Value{ .object = instance }) catch {};
        try self.populate_getter_env_instance_fields(
            getter_env,
            instance,
            root_class_decl,
            field_decl.name,
        );

        const saved_class = self.current_class;
        const saved_getter = self.evaluating_getter;
        const saved_getter_instance = self.evaluating_getter_instance;
        self.current_class = owner_class_name;
        self.evaluating_getter = field_decl.name;
        self.evaluating_getter_instance = instance;
        defer {
            self.current_class = saved_class;
            self.evaluating_getter = saved_getter;
            self.evaluating_getter_instance = saved_getter_instance;
        }

        const result = self.exec_block(field_decl.getter_body.?, getter_env) catch |err| {
            if (err == error.StackOverflow) return Value.null_val;
            return err;
        };
        return switch (result) {
            .return_val => |value| value,
            else => self.return_value,
        };
    }

    fn populate_getter_env_instance_fields(
        self: *Evaluator,
        getter_env: *Env,
        instance: *types.ObjectInstance,
        root_class_decl: *ast.ClassDecl,
        current_field_name: []const u8,
    ) anyerror!void {
        for (instance.fields.keys(), instance.fields.values()) |key, value| {
            if (!std.ascii.eqlIgnoreCase(key, current_field_name) and
                self.class_hierarchy_has_getter(root_class_decl, key))
            {
                continue;
            }
            getter_env.set(key, value) catch {
                getter_env.define(key, value) catch {};
            };
        }
    }

    fn class_hierarchy_has_getter(
        self: *Evaluator,
        root_class_decl: *ast.ClassDecl,
        field_name: []const u8,
    ) bool {
        var cur_cd: ?*ast.ClassDecl = root_class_decl;
        while (cur_cd) |cd| {
            for (cd.members) |member| {
                switch (member) {
                    .field_decl => |fd| {
                        if (std.ascii.eqlIgnoreCase(fd.name, field_name) and
                            fd.getter_body != null)
                        {
                            return true;
                        }
                    },
                    else => {},
                }
            }
            cur_cd = if (cd.super_class) |sc| self.find_class(sc.name) else null;
        }
        return false;
    }

    fn eval_schema_object_field_access(
        self: *Evaluator,
        instance: *types.ObjectInstance,
        field_name: []const u8,
    ) anyerror!?Value {
        if (std.ascii.eqlIgnoreCase(instance.class_name, "Schema.SObjectTypeNamespace")) {
            return try self.schema_s_object_type_value(field_name);
        }
        if (std.ascii.eqlIgnoreCase(instance.class_name, "Schema.SObjectType")) {
            return try self.eval_schema_s_object_type_field_access(instance, field_name);
        }
        if (std.ascii.eqlIgnoreCase(instance.class_name, "FieldDescribeMap")) {
            return try self.eval_field_describe_map_field_access(instance, field_name);
        }
        if (std.ascii.eqlIgnoreCase(instance.class_name, "DescribeSObjectResult") or
            std.ascii.eqlIgnoreCase(instance.class_name, "Schema.DescribeSObjectResult"))
        {
            return try self.eval_describe_s_object_result_field_access(instance, field_name);
        }
        return null;
    }

    fn eval_schema_s_object_type_field_access(
        self: *Evaluator,
        instance: *types.ObjectInstance,
        field_name: []const u8,
    ) anyerror!?Value {
        if (std.ascii.eqlIgnoreCase(field_name, "fieldSets")) {
            if (instance.fields.get("fieldSets")) |field_sets| return field_sets;
            const field_sets = try builtins.create_field_set_collection_value(
                self.arena,
                self,
                self.named_object_name(instance),
            );
            try instance.fields.put(self.arena, "fieldSets", field_sets);
            return field_sets;
        }
        if (std.ascii.eqlIgnoreCase(field_name, "fields")) {
            if (instance.fields.get("fields")) |existing| return existing;
            var ctx = builtins.BuiltinContext{
                .arena = self.arena,
                .stdout = &self.stdout,
                .pending_exception = &self.pending_exception,
                .see_all_data = self.see_all_data,
                .eval = self,
            };
            const fields = try builtins.create_field_describe_map_value(
                &ctx,
                self.named_object_name(instance),
            );
            try instance.fields.put(self.arena, "fields", fields);
            return fields;
        }
        return null;
    }

    fn named_object_name(self: *Evaluator, instance: *types.ObjectInstance) []const u8 {
        _ = self;
        if (instance.fields.get("name")) |name_val| {
            if (name_val == .string) return name_val.string;
        }
        return "SObject";
    }

    fn eval_field_describe_map_field_access(
        self: *Evaluator,
        instance: *types.ObjectInstance,
        field_name: []const u8,
    ) anyerror!?Value {
        if (std.ascii.eqlIgnoreCase(field_name, "map")) {
            if (instance.fields.get("map")) |value| return value;
        }
        if (instance.fields.get("owner")) |owner_val| {
            if (owner_val == .string) {
                return try self.make_s_object_field_token(owner_val.string, field_name);
            }
        }
        return null;
    }

    fn eval_describe_s_object_result_field_access(
        self: *Evaluator,
        instance: *types.ObjectInstance,
        field_name: []const u8,
    ) anyerror!?Value {
        if (!std.ascii.eqlIgnoreCase(field_name, "fieldSets")) return null;
        if (instance.fields.get("fieldSets")) |field_sets| return field_sets;
        const field_sets = try builtins.create_field_set_collection_value(
            self.arena,
            self,
            self.named_object_name(instance),
        );
        try instance.fields.put(self.arena, "fieldSets", field_sets);
        return field_sets;
    }

    fn eval_string_field_access(
        self: *Evaluator,
        fa: *ast.FieldAccess,
        value: []const u8,
    ) anyerror!?Value {
        if (fa.object.* == .field_access) {
            const inner_fa = fa.object.field_access;
            if (inner_fa.object.* == .identifier and
                std.ascii.eqlIgnoreCase(inner_fa.object.identifier.name, "Schema"))
            {
                if (is_known_schema_enum_type(inner_fa.field)) {
                    return Value{ .string = fa.field };
                }
                return try self.make_s_object_field_token(value, fa.field);
            }
        }
        if (fa.object.* == .identifier and
            std.mem.startsWith(u8, fa.object.identifier.name, "Schema."))
        {
            const schema_name = fa.object.identifier.name["Schema.".len..];
            if (is_known_schema_enum_type(schema_name)) {
                return Value{ .string = fa.field };
            }
            if (std.ascii.eqlIgnoreCase(schema_name, "SObjectType")) {
                return try self.schema_s_object_type_value(fa.field);
            }
            return try self.make_s_object_field_token(schema_name, fa.field);
        }
        if (std.ascii.eqlIgnoreCase(fa.field, "length")) {
            return Value{ .integer = @intCast(value.len) };
        }
        var enum_iter = self.classes.iterator();
        while (enum_iter.next()) |entry| {
            for (entry.value_ptr.*.members) |member| {
                switch (member) {
                    .enum_decl => |ed| {
                        if (std.ascii.eqlIgnoreCase(ed.name, value)) {
                            return Value{ .string = fa.field };
                        }
                    },
                    else => {},
                }
            }
        }
        return null;
    }

    fn eval_field_access_static_path(
        self: *Evaluator,
        fa: *ast.FieldAccess,
        obj: Value,
        current_env: *Env,
    ) anyerror!?Value {
        if (try self.eval_field_access_null_identifier_base(
            fa,
            obj,
            current_env,
        )) |value| return value;
        if (try self.eval_field_access_identifier_static(fa)) |value| return value;
        if (try self.eval_field_access_nested_static(fa)) |value| return value;
        if (try self.eval_field_access_dotted_class_literal(fa)) |value| return value;
        if (try self.eval_string_class_literal(obj, fa.field)) |value| return value;
        return null;
    }

    fn eval_field_access_null_identifier_base(
        self: *Evaluator,
        fa: *ast.FieldAccess,
        obj: Value,
        current_env: *Env,
    ) anyerror!?Value {
        if (obj != .null_val or fa.object.* != .identifier) return null;
        const base_name = fa.object.identifier.name;
        if (self.current_class) |cc| {
            if (self.resolve_static_field_value_on_class(cc, base_name)) |base| {
                if (base != .null_val) {
                    return try self.eval_field_access_on_resolved_value(
                        base,
                        fa.field,
                        current_env,
                    );
                }
            }
            if (self.find_outer_class_name(cc)) |outer| {
                if (self.resolve_static_field_value_on_class(outer, base_name)) |base| {
                    if (base != .null_val) {
                        return try self.eval_field_access_on_resolved_value(
                            base,
                            fa.field,
                            current_env,
                        );
                    }
                }
            }
        }
        return null;
    }

    fn eval_field_access_identifier_static(
        self: *Evaluator,
        fa: *ast.FieldAccess,
    ) anyerror!?Value {
        if (fa.object.* != .identifier) return null;
        const class_name = fa.object.identifier.name;
        self.ensure_static_init(class_name);

        if (try self.eval_schema_identifier_static_access(
            class_name,
            fa.field,
        )) |value| return value;
        if (try self.eval_builtin_identifier_static_access(
            class_name,
            fa.field,
        )) |value| return value;
        if (try self.eval_rest_context_static_field(class_name, fa.field)) |value| return value;
        if (try self.eval_trigger_static_field_access(class_name, fa.field)) |value| return value;
        if (try self.eval_class_member_static_access(class_name, fa.field)) |value| return value;

        const key = try std.fmt.allocPrint(
            self.arena,
            "{s}.{s}",
            .{ class_name, fa.field },
        );
        if (self.global_env.get(key)) |value| return value;
        return Value{ .string = fa.field };
    }

    fn eval_schema_identifier_static_access(
        self: *Evaluator,
        class_name: []const u8,
        field_name: []const u8,
    ) anyerror!?Value {
        if (!std.mem.startsWith(u8, class_name, "Schema.")) return null;
        const schema_name = class_name["Schema.".len..];
        if (is_known_schema_enum_type(schema_name)) {
            return Value{ .string = field_name };
        }
        if (std.ascii.eqlIgnoreCase(schema_name, "SObjectType")) {
            return try self.schema_s_object_type_value(field_name);
        }
        if (std.ascii.eqlIgnoreCase(field_name, "SObjectType")) {
            return try self.schema_s_object_type_value(schema_name);
        }
        if (!std.ascii.eqlIgnoreCase(field_name, "class")) {
            return try self.make_s_object_field_token(schema_name, field_name);
        }
        return null;
    }

    fn eval_builtin_identifier_static_access(
        self: *Evaluator,
        class_name: []const u8,
        field_name: []const u8,
    ) anyerror!?Value {
        if (std.ascii.eqlIgnoreCase(class_name, "Date") and
            std.ascii.eqlIgnoreCase(field_name, "today"))
        {
            return try builtins.make_date_value(
                self.arena,
                try builtins.current_date_string(self.arena),
            );
        }
        if (std.ascii.eqlIgnoreCase(class_name, "AccessLevel") or
            std.ascii.eqlIgnoreCase(class_name, "AccessType") or
            std.ascii.eqlIgnoreCase(class_name, "ApexPages.Severity"))
        {
            return Value{ .string = field_name };
        }
        if (std.ascii.eqlIgnoreCase(field_name, "SObjectType")) {
            if (std.ascii.eqlIgnoreCase(class_name, "Schema")) {
                const ns = try self.arena.create(types.ObjectInstance);
                ns.* = .{ .class_name = "Schema.SObjectTypeNamespace" };
                return Value{ .object = ns };
            }
            return try self.schema_s_object_type_value(class_name);
        }
        if (std.ascii.eqlIgnoreCase(field_name, "class")) {
            const type_name: []const u8 = if (self.current_class) |cc| blk: {
                if (std.mem.indexOfScalar(u8, class_name, '.') == null) {
                    const fq = std.fmt.allocPrint(
                        self.arena,
                        "{s}.{s}",
                        .{ cc, class_name },
                    ) catch class_name;
                    if (self.find_class(fq) != null) break :blk fq;
                }
                break :blk self.resolve_full_class_name(class_name);
            } else self.resolve_full_class_name(class_name);
            return try self.make_type_value(type_name);
        }
        if (self.is_s_object_type_name(class_name)) {
            return try self.make_s_object_field_token(class_name, field_name);
        }
        return null;
    }

    fn eval_rest_context_static_field(
        self: *Evaluator,
        class_name: []const u8,
        field_name: []const u8,
    ) anyerror!?Value {
        if (!std.ascii.eqlIgnoreCase(class_name, "RestContext")) return null;
        if (std.ascii.eqlIgnoreCase(field_name, "request")) {
            const key = try std.fmt.allocPrint(self.arena, "RestContext.request", .{});
            if (self.global_env.get(key)) |existing| return existing;
            const req = try self.arena.create(types.ObjectInstance);
            req.* = .{ .class_name = "RestRequest" };
            try req.fields.put(
                self.arena,
                "requestURI",
                Value{ .string = "/services/apexrest/test" },
            );
            try req.fields.put(self.arena, "httpMethod", Value{ .string = "GET" });
            try self.populate_new_rest_request(req);
            const value = Value{ .object = req };
            try self.global_env.define(key, value);
            return value;
        }
        if (std.ascii.eqlIgnoreCase(field_name, "response")) {
            const key = try std.fmt.allocPrint(self.arena, "RestContext.response", .{});
            if (self.global_env.get(key)) |existing| return existing;
            const resp = try self.arena.create(types.ObjectInstance);
            resp.* = .{ .class_name = "RestResponse" };
            try self.populate_new_rest_response(resp);
            const value = Value{ .object = resp };
            try self.global_env.define(key, value);
            return value;
        }
        return null;
    }

    fn eval_trigger_static_field_access(
        self: *Evaluator,
        class_name: []const u8,
        field_name: []const u8,
    ) anyerror!?Value {
        if (!std.ascii.eqlIgnoreCase(class_name, "Trigger")) return null;
        if (self.trigger_context) |tc| {
            return self.eval_active_trigger_static_field(tc, field_name);
        }
        return try self.eval_default_trigger_static_field(field_name);
    }

    fn eval_active_trigger_static_field(
        self: *Evaluator,
        tc: anytype,
        field_name: []const u8,
    ) ?Value {
        _ = self;
        if (std.ascii.eqlIgnoreCase(field_name, "new")) {
            return tc.new_list orelse Value.null_val;
        }
        if (std.ascii.eqlIgnoreCase(field_name, "old")) {
            return tc.old_list orelse Value.null_val;
        }
        if (std.ascii.eqlIgnoreCase(field_name, "newMap")) {
            return tc.new_map orelse Value.null_val;
        }
        if (std.ascii.eqlIgnoreCase(field_name, "oldMap")) {
            return tc.old_map orelse Value.null_val;
        }
        if (std.ascii.eqlIgnoreCase(field_name, "isBefore")) {
            return Value{ .boolean = tc.is_before };
        }
        if (std.ascii.eqlIgnoreCase(field_name, "isAfter")) {
            return Value{ .boolean = tc.is_after };
        }
        if (std.ascii.eqlIgnoreCase(field_name, "isInsert")) {
            return Value{ .boolean = tc.is_insert };
        }
        if (std.ascii.eqlIgnoreCase(field_name, "isUpdate")) {
            return Value{ .boolean = tc.is_update };
        }
        if (std.ascii.eqlIgnoreCase(field_name, "isDelete")) {
            return Value{ .boolean = tc.is_delete };
        }
        if (std.ascii.eqlIgnoreCase(field_name, "isUndelete")) {
            return Value{ .boolean = tc.is_undelete };
        }
        if (std.ascii.eqlIgnoreCase(field_name, "isExecuting")) {
            return Value{ .boolean = tc.is_executing };
        }
        if (std.ascii.eqlIgnoreCase(field_name, "size")) return Value{ .integer = tc.size };
        if (std.ascii.eqlIgnoreCase(field_name, "operationType")) {
            return if (tc.operation_type) |op| Value{ .string = op } else Value.null_val;
        }
        return null;
    }

    fn eval_default_trigger_static_field(
        self: *Evaluator,
        field_name: []const u8,
    ) anyerror!?Value {
        if (std.ascii.eqlIgnoreCase(field_name, "new") or
            std.ascii.eqlIgnoreCase(field_name, "old") or
            std.ascii.eqlIgnoreCase(field_name, "newMap") or
            std.ascii.eqlIgnoreCase(field_name, "oldMap"))
        {
            const key = try std.fmt.allocPrint(self.arena, "Trigger.{s}", .{field_name});
            return self.global_env.get(key) orelse Value.null_val;
        }
        if (std.ascii.eqlIgnoreCase(field_name, "isBefore") or
            std.ascii.eqlIgnoreCase(field_name, "isAfter") or
            std.ascii.eqlIgnoreCase(field_name, "isInsert") or
            std.ascii.eqlIgnoreCase(field_name, "isUpdate") or
            std.ascii.eqlIgnoreCase(field_name, "isDelete") or
            std.ascii.eqlIgnoreCase(field_name, "isUndelete") or
            std.ascii.eqlIgnoreCase(field_name, "isExecuting"))
        {
            return Value{ .boolean = false };
        }
        if (std.ascii.eqlIgnoreCase(field_name, "size")) return Value{ .integer = 0 };
        if (std.ascii.eqlIgnoreCase(field_name, "operationType")) return Value.null_val;
        return null;
    }

    fn eval_class_member_static_access(
        self: *Evaluator,
        class_name: []const u8,
        field_name: []const u8,
    ) anyerror!?Value {
        if (self.is_top_level_enum_name(class_name)) {
            return Value{ .string = field_name };
        }
        const cd = self.find_class(class_name) orelse return null;
        for (cd.members) |member| {
            switch (member) {
                .enum_decl => |ed| {
                    if (std.ascii.eqlIgnoreCase(ed.name, field_name)) {
                        return Value{ .string = field_name };
                    }
                },
                .field_decl => |fd| {
                    if (std.ascii.eqlIgnoreCase(fd.name, field_name) and
                        fd.modifiers.is_static)
                    {
                        return self.resolve_static_field_value_on_class(
                            class_name,
                            field_name,
                        ) orelse Value.null_val;
                    }
                },
                .class_decl => |inner_cd| {
                    if (std.ascii.eqlIgnoreCase(inner_cd.name, field_name)) {
                        const fq_name = try std.fmt.allocPrint(
                            self.arena,
                            "{s}.{s}",
                            .{ class_name, inner_cd.name },
                        );
                        return Value{ .string = fq_name };
                    }
                },
                .interface_decl => |inner_iface| {
                    if (std.ascii.eqlIgnoreCase(inner_iface.name, field_name)) {
                        const fq_name = try std.fmt.allocPrint(
                            self.arena,
                            "{s}.{s}",
                            .{ class_name, inner_iface.name },
                        );
                        return Value{ .string = fq_name };
                    }
                },
                else => {},
            }
        }
        return null;
    }

    fn is_top_level_enum_name(self: *Evaluator, class_name: []const u8) bool {
        var class_iter = self.classes.iterator();
        while (class_iter.next()) |entry| {
            for (entry.value_ptr.*.members) |member| {
                switch (member) {
                    .enum_decl => |ed| {
                        if (std.ascii.eqlIgnoreCase(ed.name, class_name)) return true;
                    },
                    else => {},
                }
            }
        }
        return false;
    }

    fn eval_field_access_nested_static(
        self: *Evaluator,
        fa: *ast.FieldAccess,
    ) anyerror!?Value {
        if (fa.object.* != .field_access) return null;
        const inner_fa = fa.object.field_access;
        if (inner_fa.object.* != .identifier) return null;
        const outer_name = inner_fa.object.identifier.name;
        const inner_name = inner_fa.field;

        if (try self.eval_nested_class_member_access(
            outer_name,
            inner_name,
            fa.field,
        )) |value| return value;
        if (try self.eval_system_nested_static_access(
            outer_name,
            inner_name,
            fa.field,
        )) |value| return value;
        if (try self.eval_schema_nested_static_access(
            outer_name,
            inner_name,
            fa.field,
        )) |value| return value;
        return null;
    }

    fn eval_nested_class_member_access(
        self: *Evaluator,
        outer_name: []const u8,
        inner_name: []const u8,
        field_name: []const u8,
    ) anyerror!?Value {
        const cd = self.find_class(outer_name) orelse return null;
        for (cd.members) |member| {
            switch (member) {
                .enum_decl => |ed| {
                    if (std.ascii.eqlIgnoreCase(ed.name, inner_name)) {
                        return Value{ .string = field_name };
                    }
                },
                .class_decl => |inner_cd| {
                    if (std.ascii.eqlIgnoreCase(inner_cd.name, inner_name)) {
                        const fq_name = try std.fmt.allocPrint(
                            self.arena,
                            "{s}.{s}",
                            .{ outer_name, inner_cd.name },
                        );
                        if (std.ascii.eqlIgnoreCase(field_name, "class")) {
                            return try self.make_type_value(fq_name);
                        }
                        const static_key = try std.fmt.allocPrint(
                            self.arena,
                            "{s}.{s}",
                            .{ fq_name, field_name },
                        );
                        if (self.global_env.get(static_key)) |value| return value;
                        return Value{ .string = field_name };
                    }
                },
                .interface_decl => |inner_iface| {
                    if (std.ascii.eqlIgnoreCase(inner_iface.name, inner_name) and
                        std.ascii.eqlIgnoreCase(field_name, "class"))
                    {
                        const fq_name = try std.fmt.allocPrint(
                            self.arena,
                            "{s}.{s}",
                            .{ outer_name, inner_iface.name },
                        );
                        return try self.make_type_value(fq_name);
                    }
                },
                else => {},
            }
        }
        return null;
    }

    fn eval_system_nested_static_access(
        self: *Evaluator,
        outer_name: []const u8,
        inner_name: []const u8,
        field_name: []const u8,
    ) anyerror!?Value {
        if (std.ascii.eqlIgnoreCase(outer_name, "System") and
            (std.ascii.eqlIgnoreCase(inner_name, "AccessType") or
                std.ascii.eqlIgnoreCase(inner_name, "AccessLevel") or
                std.ascii.eqlIgnoreCase(inner_name, "Quiddity") or
                std.ascii.eqlIgnoreCase(inner_name, "TriggerOperation") or
                std.ascii.eqlIgnoreCase(inner_name, "LoggingLevel") or
                std.ascii.eqlIgnoreCase(inner_name, "StatusCode")))
        {
            return Value{ .string = field_name };
        }
        if (std.ascii.eqlIgnoreCase(outer_name, "Metadata") and
            is_known_metadata_enum_type(inner_name))
        {
            return Value{ .string = field_name };
        }
        if (std.ascii.eqlIgnoreCase(field_name, "class") and
            std.ascii.eqlIgnoreCase(outer_name, "System"))
        {
            const fq_name = try std.fmt.allocPrint(self.arena, "System.{s}", .{inner_name});
            return try self.make_type_value(fq_name);
        }
        return null;
    }

    fn eval_schema_nested_static_access(
        self: *Evaluator,
        outer_name: []const u8,
        inner_name: []const u8,
        field_name: []const u8,
    ) anyerror!?Value {
        if (!std.ascii.eqlIgnoreCase(outer_name, "Schema")) return null;
        if (std.ascii.eqlIgnoreCase(inner_name, "SObjectType")) {
            return try self.schema_s_object_type_value(field_name);
        }
        if (is_known_schema_enum_type(inner_name)) {
            return Value{ .string = field_name };
        }
        return try self.make_s_object_field_token(inner_name, field_name);
    }

    fn eval_field_access_dotted_class_literal(
        self: *Evaluator,
        fa: *ast.FieldAccess,
    ) anyerror!?Value {
        if (!std.ascii.eqlIgnoreCase(fa.field, "class") or fa.object.* != .field_access) {
            return null;
        }
        const chain = self.collect_dotted_identifier_chain(fa.object) orelse return null;
        const display_name: []const u8 = blk: {
            if (std.ascii.startsWithIgnoreCase(chain, "Flow.Interview.")) {
                const leaf = chain["Flow.Interview.".len..];
                if (leaf.len > 0 and std.mem.indexOfScalar(u8, leaf, '.') == null) {
                    if (self.find_class(leaf) == null) break :blk "Flow.Interview";
                }
            }
            break :blk chain;
        };
        return try self.make_type_value(display_name);
    }

    fn eval_string_class_literal(
        self: *Evaluator,
        obj: Value,
        field_name: []const u8,
    ) anyerror!?Value {
        if (obj != .string or !std.ascii.eqlIgnoreCase(field_name, "class")) return null;
        const type_name: []const u8 = if (self.current_class) |cc| blk: {
            const fq = std.fmt.allocPrint(
                self.arena,
                "{s}.{s}",
                .{ cc, obj.string },
            ) catch obj.string;
            break :blk if (self.find_class(fq) != null)
                fq
            else
                self.resolve_full_class_name(obj.string);
        } else self.resolve_full_class_name(obj.string);
        return try self.make_type_value(type_name);
    }

    fn make_type_value(self: *Evaluator, type_name: []const u8) !Value {
        const type_obj = try self.arena.create(types.ObjectInstance);
        type_obj.* = .{ .class_name = "Type" };
        try type_obj.fields.put(self.arena, "name", Value{ .string = type_name });
        return Value{ .object = type_obj };
    }

    fn eval_field_access_on_resolved_value(
        self: *Evaluator,
        obj: Value,
        field_name: []const u8,
        current_env: *Env,
    ) !Value {
        const placeholder_expr = try self.arena.create(ast.Expr);
        placeholder_expr.* = .null_literal;
        const synthetic_fa = try self.arena.create(ast.FieldAccess);
        synthetic_fa.* = .{
            .object = placeholder_expr,
            .field = field_name,
            .null_safe = false,
        };
        return self.eval_field_access(synthetic_fa, obj, current_env);
    }

    /// expr が `Identifier.Field.Field...` の形で全てドット連結のパスになっている場合、
    /// そのパスを `A.B.C` の形式で返す。非ドット式が混ざっていれば null を返す。
    fn collect_dotted_identifier_chain(self: *Evaluator, expr: *const ast.Expr) ?[]const u8 {
        var parts: std.ArrayListUnmanaged([]const u8) = .empty;
        defer parts.deinit(self.arena);

        var cur: *const ast.Expr = expr;
        while (true) {
            switch (cur.*) {
                .identifier => |id| {
                    parts.append(self.arena, id.name) catch return null;
                    break;
                },
                .field_access => |fa| {
                    parts.append(self.arena, fa.field) catch return null;
                    cur = fa.object;
                },
                else => return null,
            }
        }
        // Reverse: parts holds leaf-to-root, we want root-to-leaf.
        std.mem.reverse([]const u8, parts.items);
        // Compute total length
        var total: usize = 0;
        for (parts.items, 0..) |p, i| {
            if (i > 0) total += 1; // dot
            total += p.len;
        }
        const buf = self.arena.alloc(u8, total) catch return null;
        var idx: usize = 0;
        for (parts.items, 0..) |p, i| {
            if (i > 0) {
                buf[idx] = '.';
                idx += 1;
            }
            std.mem.copyForwards(u8, buf[idx..], p);
            idx += p.len;
        }
        return buf;
    }

    // -----------------------------------------------------------------------
    // Datetime ヘルパー
    // -----------------------------------------------------------------------

    /// 文字列が Date 形式 (YYYY-MM-DD, 10文字ちょうど) かどうかを判定する。
    fn is_date_only_format_string(s: []const u8) bool {
        if (s.len != 10) return false;
        if (s[4] != '-' or s[7] != '-') return false;
        _ = std.fmt.parseInt(i32, s[0..4], 10) catch return false;
        _ = std.fmt.parseInt(u8, s[5..7], 10) catch return false;
        _ = std.fmt.parseInt(u8, s[8..10], 10) catch return false;
        return true;
    }

    /// 文字列が DateTime 形式 (YYYY-MM-DDThh:mm:ss...) かどうかを判定する。
    fn is_date_time_format_string(s: []const u8) bool {
        if (s.len < 19) return false;
        if (s[4] != '-' or s[7] != '-' or s[10] != 'T') return false;
        _ = std.fmt.parseInt(i32, s[0..4], 10) catch return false;
        _ = std.fmt.parseInt(u8, s[5..7], 10) catch return false;
        _ = std.fmt.parseInt(u8, s[8..10], 10) catch return false;
        _ = std.fmt.parseInt(u8, s[11..13], 10) catch return false;
        _ = std.fmt.parseInt(u8, s[14..16], 10) catch return false;
        _ = std.fmt.parseInt(u8, s[17..19], 10) catch return false;
        return true;
    }

    fn is_salesforce_id_string(value: []const u8) bool {
        if (value.len != 15 and value.len != 18) return false;
        for (value) |ch| {
            if (!std.ascii.isAlphanumeric(ch)) return false;
        }
        return true;
    }

    /// instanceof チェック: Value がプリミティブ型名にマッチするか。
    fn instanceof_matches_primitive(val: Value, tn: []const u8) bool {
        if (std.ascii.eqlIgnoreCase(tn, "Object")) return val != .null_val and val != .void_val;
        if (val == .integer) {
            return std.ascii.eqlIgnoreCase(tn, "Integer") or
                std.ascii.eqlIgnoreCase(tn, "Long") or
                std.ascii.eqlIgnoreCase(tn, "Decimal") or
                std.ascii.eqlIgnoreCase(tn, "Double") or
                std.ascii.eqlIgnoreCase(tn, "Number");
        }
        if (val == .long) {
            return std.ascii.eqlIgnoreCase(tn, "Long") or
                std.ascii.eqlIgnoreCase(tn, "Decimal") or
                std.ascii.eqlIgnoreCase(tn, "Double") or
                std.ascii.eqlIgnoreCase(tn, "Number");
        }
        if (val == .double) {
            return std.ascii.eqlIgnoreCase(tn, "Decimal") or
                std.ascii.eqlIgnoreCase(tn, "Double") or
                std.ascii.eqlIgnoreCase(tn, "Number");
        }
        if (val == .boolean) return std.ascii.eqlIgnoreCase(tn, "Boolean");
        if (val == .string) {
            return std.ascii.eqlIgnoreCase(tn, "String") or
                (std.ascii.eqlIgnoreCase(tn, "Id") and
                    Evaluator.is_salesforce_id_string(val.string));
        }
        if (val == .sobject) {
            return std.ascii.eqlIgnoreCase(tn, "SObject") or
                std.ascii.eqlIgnoreCase(tn, "Sobject") or
                std.ascii.eqlIgnoreCase(tn, "sObject") or
                std.ascii.eqlIgnoreCase(tn, val.sobject.type_name);
        }
        if (val == .object) {
            const cn = val.object.class_name;
            if (cn.len > 0 and cn.len < 256) {
                if (std.ascii.eqlIgnoreCase(cn, "Date")) {
                    return std.ascii.eqlIgnoreCase(tn, "Date") or
                        std.ascii.eqlIgnoreCase(tn, "DateTime") or
                        std.ascii.eqlIgnoreCase(tn, "Datetime");
                }
                if (std.ascii.eqlIgnoreCase(cn, "Datetime")) {
                    return std.ascii.eqlIgnoreCase(tn, "DateTime") or
                        std.ascii.eqlIgnoreCase(tn, "Datetime");
                }
                if (std.ascii.eqlIgnoreCase(cn, "Time")) return std.ascii.eqlIgnoreCase(tn, "Time");
                if (std.ascii.eqlIgnoreCase(cn, "Schema.SObjectField") or
                    std.ascii.eqlIgnoreCase(cn, "SObjectField"))
                {
                    return std.ascii.eqlIgnoreCase(tn, "Schema.SObjectField") or
                        std.ascii.eqlIgnoreCase(tn, "SObjectField");
                }
                if (std.ascii.eqlIgnoreCase(cn, "Schema.SObjectType")) {
                    return std.ascii.eqlIgnoreCase(tn, "Schema.SObjectType") or
                        std.ascii.eqlIgnoreCase(tn, "SObjectType");
                }
                if (std.ascii.eqlIgnoreCase(cn, "Schema.FieldSet")) {
                    return std.ascii.eqlIgnoreCase(tn, "Schema.FieldSet") or
                        std.ascii.eqlIgnoreCase(tn, "FieldSet");
                }
            }
        }
        return false;
    }

    /// child_class が parent_type のサブクラスかどうかを継承チェーンで確認する。
    fn is_subclass_of(self: *Evaluator, child_class: []const u8, parent_type: []const u8) bool {
        // Direct match
        if (std.ascii.eqlIgnoreCase(child_class, parent_type)) return true;
        // Check simple name match (inner class: "OuterClass.InnerClass" → "InnerClass")
        if (std.mem.lastIndexOfScalar(u8, child_class, '.')) |di| {
            if (std.ascii.eqlIgnoreCase(child_class[di + 1 ..], parent_type)) return true;
        }
        // Walk the inheritance chain
        var cd = self.find_class(child_class);
        var depth: u8 = 0;
        while (cd) |c| : (depth += 1) {
            if (depth > 20) break; // Safety limit
            if (c.super_class) |sc| {
                if (std.ascii.eqlIgnoreCase(sc.name, parent_type)) return true;
                if (std.mem.lastIndexOfScalar(u8, sc.name, '.')) |di| {
                    if (std.ascii.eqlIgnoreCase(sc.name[di + 1 ..], parent_type)) return true;
                }
                // Also check interfaces
                for (c.interfaces) |iface| {
                    if (std.ascii.eqlIgnoreCase(iface.name, parent_type)) return true;
                }
                cd = self.find_class(sc.name);
            } else {
                // Check interfaces at this level
                for (c.interfaces) |iface| {
                    if (std.ascii.eqlIgnoreCase(iface.name, parent_type)) return true;
                }
                break;
            }
        }
        // All *Exception classes are subclasses of Exception / System.Exception
        if ((std.ascii.eqlIgnoreCase(parent_type, "Exception") or
            std.ascii.eqlIgnoreCase(parent_type, "System.Exception")) and
            std.mem.endsWith(u8, child_class, "Exception"))
        {
            return true;
        }
        return false;
    }

    /// System enum の文字列値から ordinal 値を返す。
    /// System.LoggingLevel, System.StatusCode, DisplayType など既知のenumに対応。
    fn lookup_enum_ordinal(s: []const u8) i64 {
        // System.LoggingLevel: Salesforce declaration order (most verbose first)
        // INTERNAL=0, FINEST=1, FINER=2, FINE=3, DEBUG=4, INFO=5, WARN=6, ERROR=7, NONE=8
        const logging_levels = [_][]const u8{
            "INTERNAL",
            "FINEST",
            "FINER",
            "FINE",
            "DEBUG",
            "INFO",
            "WARN",
            "ERROR",
            "NONE",
        };
        for (logging_levels, 0..) |name, i| {
            if (std.ascii.eqlIgnoreCase(s, name)) return @intCast(i);
        }
        // System.TriggerOperation: BEFORE_INSERT=0, BEFORE_UPDATE=1, BEFORE_DELETE=2,
        // AFTER_INSERT=3, AFTER_UPDATE=4, AFTER_DELETE=5, AFTER_UNDELETE=6
        const trigger_ops = [_][]const u8{
            "BEFORE_INSERT",
            "BEFORE_UPDATE",
            "BEFORE_DELETE",
            "AFTER_INSERT",
            "AFTER_UPDATE",
            "AFTER_DELETE",
            "AFTER_UNDELETE",
        };
        for (trigger_ops, 0..) |name, i| {
            if (std.ascii.eqlIgnoreCase(s, name)) return @intCast(i);
        }
        return 0;
    }

    /// ISO 日付文字列 (YYYY-MM-DD or YYYY-MM-DDTHH:MM:SSZ) をパースする。
    const ParsedIsoDate = struct {
        y: i32,
        m: u8,
        d: u8,
        h: u8,
        mi: u8,
        sec: u8,
        has_time: bool,
    };

    fn parse_iso_date(s: []const u8) ?ParsedIsoDate {
        if (s.len < 10 or s[4] != '-' or s[7] != '-') return null;
        const y = std.fmt.parseInt(i32, s[0..4], 10) catch return null;
        const m = std.fmt.parseInt(u8, s[5..7], 10) catch return null;
        const day = std.fmt.parseInt(u8, s[8..10], 10) catch return null;
        if (s.len >= 19 and s[10] == 'T') {
            const h = std.fmt.parseInt(u8, s[11..13], 10) catch 0;
            const mi = std.fmt.parseInt(u8, s[14..16], 10) catch 0;
            const sec = std.fmt.parseInt(u8, s[17..19], 10) catch 0;
            return .{
                .y = y,
                .m = m,
                .d = day,
                .h = h,
                .mi = mi,
                .sec = sec,
                .has_time = true,
            };
        }
        return .{
            .y = y,
            .m = m,
            .d = day,
            .h = 0,
            .mi = 0,
            .sec = 0,
            .has_time = false,
        };
    }

    /// 月と日から年内通算日を返す (1-indexed)
    fn day_of_year(m: u8, d: u8) u16 {
        const cumulative = [_]u16{
            0,
            31,
            59,
            90,
            120,
            151,
            181,
            212,
            243,
            273,
            304,
            334,
        };
        return cumulative[m - 1] + d;
    }

    /// 年月日から 1970-01-01 を原点とする連続日数を返す。負の年でも動作する。
    fn iso_date_to_epoch_days(year: i32, month: u8, day: u8) i64 {
        const y = @as(i64, year);
        const doy = @as(i64, day_of_year(month, day));
        const is_leap: i64 = if (@mod(y, 4) == 0 and
            (@mod(y, 100) != 0 or @mod(y, 400) == 0))
            @as(i64, 1)
        else
            0;
        const leap_adj: i64 = if (month > 2) is_leap else 0;
        return (y - 1970) * 365 +
            @divFloor(y - 1969, 4) -
            @divFloor(y - 1901, 100) +
            @divFloor(y - 1601, 400) +
            doy - 1 +
            leap_adj;
    }

    /// ISO 8601 day-of-week: Monday=1 ... Sunday=7.
    fn iso_day_of_week(year: i32, month: u8, day: u8) u8 {
        // 1970-01-01 was a Thursday (ISO dow=4).
        const epoch_days = iso_date_to_epoch_days(year, month, day);
        const r = @mod(epoch_days + 3, 7); // Mon=0..Sun=6
        return @as(u8, @intCast(r + 1));
    }

    const IsoWeek = struct { year: i32, week: u8 };

    /// ISO 8601 week-of-year / week-year. Week 1 contains the first Thursday.
    fn iso_week_of_year(year: i32, month: u8, day: u8) IsoWeek {
        // Day-of-year (1-based).
        const is_leap = (@mod(year, 4) == 0 and
            (@mod(year, 100) != 0 or @mod(year, 400) == 0));
        var doy: i32 = @as(i32, day_of_year(month, day));
        if (is_leap and month > 2) doy += 1;
        const dow: i32 = @as(i32, iso_day_of_week(year, month, day));
        const woy_num = @divFloor((doy - dow + 10), 7);
        if (woy_num < 1) {
            // Week belongs to the previous year's last ISO week (52 or 53).
            return iso_week_of_year(year - 1, 12, 31);
        }
        const is_leap_this = if (@mod(year, 4) == 0 and
            (@mod(year, 100) != 0 or @mod(year, 400) == 0))
            true
        else
            false;
        _ = is_leap_this;
        // How many ISO weeks does this year have? Either 52 or 53.
        const jan1_dow: i32 = @as(i32, iso_day_of_week(year, 1, 1));
        const dec31_dow: i32 = @as(i32, iso_day_of_week(year, 12, 31));
        const weeks_in_year: i32 = if (jan1_dow == 4 or dec31_dow == 4) 53 else 52;
        if (woy_num > weeks_in_year) {
            return IsoWeek{ .year = year + 1, .week = 1 };
        }
        return IsoWeek{ .year = year, .week = @as(u8, @intCast(woy_num)) };
    }

    /// Datetime パターンフォーマット (Java SimpleDateFormat 互換サブセット)
    fn format_date_time_pattern(self: *Evaluator, s: []const u8, pattern: []const u8) !Value {
        const dt = parse_iso_date(s) orelse return Value{ .string = s };
        const month_names = [_][]const u8{
            "January",
            "February",
            "March",
            "April",
            "May",
            "June",
            "July",
            "August",
            "September",
            "October",
            "November",
            "December",
        };
        const month_abbr = [_][]const u8{
            "Jan",
            "Feb",
            "Mar",
            "Apr",
            "May",
            "Jun",
            "Jul",
            "Aug",
            "Sep",
            "Oct",
            "Nov",
            "Dec",
        };
        const month_name = if (dt.m >= 1 and dt.m <= 12) month_names[dt.m - 1] else "January";
        const month_short = if (dt.m >= 1 and dt.m <= 12) month_abbr[dt.m - 1] else "Jan";

        var result: std.ArrayListUnmanaged(u8) = .empty;
        var i: usize = 0;
        while (i < pattern.len) {
            const c = pattern[i];
            // Count consecutive same characters
            var count: usize = 1;
            while (i + count < pattern.len and pattern[i + count] == c) : (count += 1) {}

            if (c == '\'') {
                i = try self.append_quoted_date_time_pattern_literal(&result, pattern, i + 1);
                continue;
            }
            try self.append_date_time_pattern_token(
                &result,
                dt,
                month_name,
                month_short,
                c,
                count,
            );
            i += count;
        }
        return Value{ .string = result.items };
    }

    fn append_date_time_pattern_token(
        self: *Evaluator,
        result: *std.ArrayListUnmanaged(u8),
        dt: anytype,
        month_name: []const u8,
        month_short: []const u8,
        c: u8,
        count: usize,
    ) !void {
        switch (c) {
            'y' => try self.append_date_time_year_token(result, dt.y, count),
            'M' => try self.append_date_time_month_token(
                result,
                dt.m,
                month_name,
                month_short,
                count,
            ),
            'd' => try self.append_padded_date_time_number(result, dt.d, count),
            'H' => try self.append_padded_date_time_number(result, dt.h, count),
            'h' => try self.append_padded_date_time_number(result, date_time_hour_12(dt.h), count),
            'm' => try self.append_padded_date_time_number(result, dt.mi, count),
            's' => try self.append_padded_date_time_number(result, dt.sec, count),
            'a' => try result.appendSlice(self.arena, if (dt.h < 12) "AM" else "PM"),
            'w', 'Y' => try self.append_iso_week_date_time_token(result, dt, c),
            'u' => try self.append_iso_day_of_week_token(result, dt),
            'D' => try self.append_day_of_year_token(result, dt),
            else => for (0..count) |_| try result.append(self.arena, c),
        }
    }

    fn append_date_time_year_token(
        self: *Evaluator,
        result: *std.ArrayListUnmanaged(u8),
        year: i32,
        count: usize,
    ) !void {
        if (count <= 2) {
            const short_y: u32 = @intCast(@mod(year, 100));
            const ys = try std.fmt.allocPrint(self.arena, "{d:0>2}", .{short_y});
            try result.appendSlice(self.arena, ys);
        } else {
            const ys = try std.fmt.allocPrint(self.arena, "{d:0>4}", .{@as(u32, @intCast(year))});
            try result.appendSlice(self.arena, ys);
        }
    }

    fn append_date_time_month_token(
        self: *Evaluator,
        result: *std.ArrayListUnmanaged(u8),
        month: u8,
        month_name: []const u8,
        month_short: []const u8,
        count: usize,
    ) !void {
        if (count >= 4) {
            try result.appendSlice(self.arena, month_name);
        } else if (count == 3) {
            try result.appendSlice(self.arena, month_short);
        } else {
            try self.append_padded_date_time_number(result, month, count);
        }
    }

    fn append_padded_date_time_number(
        self: *Evaluator,
        result: *std.ArrayListUnmanaged(u8),
        value: anytype,
        count: usize,
    ) !void {
        const formatted = if (count >= 2)
            try std.fmt.allocPrint(self.arena, "{d:0>2}", .{value})
        else
            try std.fmt.allocPrint(self.arena, "{d}", .{value});
        try result.appendSlice(self.arena, formatted);
    }

    fn date_time_hour_12(hour: u8) u8 {
        return if (hour == 0) 12 else if (hour > 12) hour - 12 else hour;
    }

    fn append_iso_week_date_time_token(
        self: *Evaluator,
        result: *std.ArrayListUnmanaged(u8),
        dt: anytype,
        c: u8,
    ) !void {
        const iso = iso_week_of_year(dt.y, dt.m, dt.d);
        if (c == 'w') {
            const ws = try std.fmt.allocPrint(self.arena, "{d}", .{iso.week});
            try result.appendSlice(self.arena, ws);
        } else {
            const iso_year: u32 = @intCast(iso.year);
            const ys = try std.fmt.allocPrint(self.arena, "{d:0>4}", .{iso_year});
            try result.appendSlice(self.arena, ys);
        }
    }

    fn append_iso_day_of_week_token(
        self: *Evaluator,
        result: *std.ArrayListUnmanaged(u8),
        dt: anytype,
    ) !void {
        const dow = iso_day_of_week(dt.y, dt.m, dt.d);
        const ds = try std.fmt.allocPrint(self.arena, "{d}", .{dow});
        try result.appendSlice(self.arena, ds);
    }

    fn append_day_of_year_token(
        self: *Evaluator,
        result: *std.ArrayListUnmanaged(u8),
        dt: anytype,
    ) !void {
        const is_leap = @mod(dt.y, 4) == 0 and
            (@mod(dt.y, 100) != 0 or @mod(dt.y, 400) == 0);
        var doy: u16 = day_of_year(dt.m, dt.d);
        if (is_leap and dt.m > 2) doy += 1;
        const ds = try std.fmt.allocPrint(self.arena, "{d}", .{doy});
        try result.appendSlice(self.arena, ds);
    }

    fn append_quoted_date_time_pattern_literal(
        self: *Evaluator,
        result: *std.ArrayListUnmanaged(u8),
        pattern: []const u8,
        start_index: usize,
    ) !usize {
        var i = start_index;
        while (i < pattern.len and pattern[i] != '\'') : (i += 1) {
            try result.append(self.arena, pattern[i]);
        }
        if (i < pattern.len) i += 1;
        return i;
    }

    /// addYears / addMonths / addDays — ISO 日付文字列に対する日付演算
    fn date_time_add(
        self: *Evaluator,
        s: []const u8,
        method: []const u8,
        args: []const Value,
    ) !Value {
        const dt = parse_iso_date(s) orelse return Value{ .string = s };
        const delta: i32 = if (args.len > 0) switch (args[0]) {
            .integer => |i| @intCast(i),
            .double => |d| @intFromFloat(d),
            else => 0,
        } else 0;

        var y = dt.y;
        var m: i32 = dt.m;
        var d: i32 = dt.d;

        if (std.ascii.eqlIgnoreCase(method, "addYears")) {
            y += delta;
        } else if (std.ascii.eqlIgnoreCase(method, "addMonths")) {
            normalize_date_time_add_months(&y, &m, delta);
        } else if (std.ascii.eqlIgnoreCase(method, "addDays")) {
            normalize_date_time_add_days(&y, &m, &d, delta);
        }

        if (dt.has_time) {
            const timestamp = try std.fmt.allocPrint(
                self.arena,
                "{d:0>4}-{d:0>2}-{d:0>2}T{d:0>2}:{d:0>2}:{d:0>2}Z",
                .{
                    @as(u32, @intCast(y)),
                    @as(u32, @intCast(m)),
                    @as(u32, @intCast(d)),
                    dt.h,
                    dt.mi,
                    dt.sec,
                },
            );
            return Value{ .string = timestamp };
        }
        const date = try std.fmt.allocPrint(self.arena, "{d:0>4}-{d:0>2}-{d:0>2}", .{
            @as(u32, @intCast(y)),
            @as(u32, @intCast(m)),
            @as(u32, @intCast(d)),
        });
        return Value{ .string = date };
    }

    fn normalize_date_time_add_months(year: *i32, month: *i32, delta: i32) void {
        month.* += delta;
        while (month.* < 1) {
            month.* += 12;
            year.* -= 1;
        }
        while (month.* > 12) {
            month.* -= 12;
            year.* += 1;
        }
    }

    fn normalize_date_time_add_days(year: *i32, month: *i32, day: *i32, delta: i32) void {
        day.* += delta;
        // 簡易実装: 各月の日数でオーバーフロー/アンダーフローを処理
        const days_in_month = [_]u8{ 31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31 };
        while (day.* > days_in_month[@intCast(month.* - 1)]) {
            day.* -= days_in_month[@intCast(month.* - 1)];
            month.* += 1;
            if (month.* > 12) {
                month.* = 1;
                year.* += 1;
            }
        }
        while (day.* < 1) {
            month.* -= 1;
            if (month.* < 1) {
                month.* = 12;
                year.* -= 1;
            }
            day.* += days_in_month[@intCast(month.* - 1)];
        }
    }

    // -----------------------------------------------------------------------
    // テストフレームワーク
    // -----------------------------------------------------------------------

    fn handle_assert(self: *Evaluator, method: []const u8, args: []const Value) !Value {
        if (std.ascii.eqlIgnoreCase(method, "areEqual") or
            std.ascii.eqlIgnoreCase(method, "assertEquals"))
        {
            if (args.len >= 2) {
                if (!self.values_equal(args[0], args[1])) {
                    try self.set_assert_equal_failure(args);
                }
            }
        } else if (std.ascii.eqlIgnoreCase(method, "areNotEqual") or
            std.ascii.eqlIgnoreCase(method, "assertNotEquals"))
        {
            if (args.len >= 2) {
                if (self.values_equal(args[0], args[1])) {
                    try self.set_assert_not_equal_failure(args);
                }
            }
        } else if (std.ascii.eqlIgnoreCase(method, "isTrue") or
            std.ascii.eqlIgnoreCase(method, "assertTrue"))
        {
            if (args.len >= 1) {
                const val = utils.coerce_to_bool(args[0]) catch false;
                if (!val) {
                    try self.set_assert_boolean_failure(args, true);
                }
            }
        } else if (std.ascii.eqlIgnoreCase(method, "isFalse") or
            std.ascii.eqlIgnoreCase(method, "assertFalse"))
        {
            if (args.len >= 1) {
                const val = utils.coerce_to_bool(args[0]) catch false;
                if (val) {
                    try self.set_assert_boolean_failure(args, false);
                }
            }
        } else if (std.ascii.eqlIgnoreCase(method, "isNotNull") or
            std.ascii.eqlIgnoreCase(method, "assertNotNull"))
        {
            if (args.len >= 1 and args[0] == .null_val) {
                try self.set_assert_not_null_failure(args);
            }
        } else if (std.ascii.eqlIgnoreCase(method, "isNull")) {
            if (args.len >= 1 and args[0] != .null_val) {
                try self.set_assert_null_failure(args);
            }
        } else if (std.ascii.eqlIgnoreCase(method, "isInstanceOfType")) {
            // simplified: always pass
        } else if (std.ascii.eqlIgnoreCase(method, "fail")) {
            self.assertion_failure = if (args.len >= 1 and args[0] == .string)
                args[0].string
            else
                "Assert.fail called";
        }
        return .void_val;
    }

    fn set_assert_not_null_failure(self: *Evaluator, args: []const Value) !void {
        self.assertion_failure = if (args.len >= 2 and args[1] == .string)
            try std.fmt.allocPrint(
                self.arena,
                "{s} | Expected: non-null, Actual: null",
                .{args[1].string},
            )
        else
            "Expected: non-null, Actual: null";
    }

    fn set_assert_null_failure(self: *Evaluator, args: []const Value) !void {
        const actual_str = try utils.coerce_to_string(args[0], self.arena);
        self.assertion_failure = if (args.len >= 2 and args[1] == .string)
            try std.fmt.allocPrint(
                self.arena,
                "{s} | Expected: null, Actual: {s}",
                .{ args[1].string, actual_str },
            )
        else
            try std.fmt.allocPrint(
                self.arena,
                "Expected: null, Actual: {s}",
                .{actual_str},
            );
    }

    fn set_assert_equal_failure(self: *Evaluator, args: []const Value) !void {
        const expected_str = try utils.coerce_to_string(args[0], self.arena);
        const actual_str = try utils.coerce_to_string(args[1], self.arena);
        self.assertion_failure = if (args.len >= 3 and args[2] == .string)
            try std.fmt.allocPrint(
                self.arena,
                "{s} | Expected: {s}, Actual: {s}",
                .{ args[2].string, expected_str, actual_str },
            )
        else
            try std.fmt.allocPrint(
                self.arena,
                "Expected: {s}, Actual: {s}",
                .{ expected_str, actual_str },
            );
    }

    fn set_assert_not_equal_failure(self: *Evaluator, args: []const Value) !void {
        const val_str = try utils.coerce_to_string(args[0], self.arena);
        self.assertion_failure = if (args.len >= 3 and args[2] == .string)
            try std.fmt.allocPrint(
                self.arena,
                "{s} | Both values: {s}",
                .{ args[2].string, val_str },
            )
        else
            try std.fmt.allocPrint(
                self.arena,
                "Values should not be equal: {s}",
                .{val_str},
            );
    }

    fn set_assert_boolean_failure(
        self: *Evaluator,
        args: []const Value,
        expected: bool,
    ) !void {
        const actual_str = try utils.coerce_to_string(args[0], self.arena);
        const expected_str = if (expected) "true" else "false";
        self.assertion_failure = if (args.len >= 2 and args[1] == .string)
            try std.fmt.allocPrint(
                self.arena,
                "{s} | Expected: {s}, Actual: {s}",
                .{ args[1].string, expected_str, actual_str },
            )
        else
            try std.fmt.allocPrint(
                self.arena,
                "Expected: {s}, Actual: {s}",
                .{ expected_str, actual_str },
            );
    }

    fn handle_test(self: *Evaluator, method: []const u8, args: []const Value) !Value {
        // Test.startTest() — reset governor limits (Salesforce resets at startTest)
        if (std.ascii.eqlIgnoreCase(method, "startTest")) {
            self.limits_dml = 0;
            self.limits_dml_rows = 0;
            self.limits_soql = 0;
            self.limits_publish_immediate = 0;
            self.limits_queueable = 0;
            self.limits_callouts = 0;
            self.limits_email_invocations = 0;
            self.reserved_single_email_capacity = 0;
            return .void_val;
        }
        if (std.ascii.eqlIgnoreCase(method, "stopTest")) {
            try self.handle_test_stop_test();
            return .void_val;
        }
        if (std.ascii.eqlIgnoreCase(method, "setCurrentPage") and args.len >= 1) {
            try self.set_current_page_reference(args[0]);
            return .void_val;
        }
        // Test.setFixedSearchResults(List<Id>)
        if (std.ascii.eqlIgnoreCase(method, "setFixedSearchResults") and args.len >= 1) {
            self.fixed_search_results = args[0];
            return .void_val;
        }
        // Test.setMock(Type, mockInstance)
        if (std.ascii.eqlIgnoreCase(method, "setMock") and args.len >= 2) {
            self.callout_mock = args[1];
            return .void_val;
        }
        if (std.ascii.eqlIgnoreCase(method, "isRunningTest")) {
            return Value{ .boolean = true };
        }
        if (std.ascii.eqlIgnoreCase(method, "testInstall") and
            args.len >= 1 and
            args[0] == .object)
        {
            try self.handle_test_install(args);
            return .void_val;
        }
        if (std.ascii.eqlIgnoreCase(method, "setCreatedDate")) {
            var bctx = builtins.BuiltinContext{
                .arena = self.arena,
                .stdout = &self.stdout,
                .pending_exception = &self.pending_exception,
                .see_all_data = self.see_all_data,
                .eval = self,
            };
            _ = try builtins.dispatch_static(&bctx, "Test", method, args);
            return .void_val;
        }
        // Test.getEventBus() → return an EventBus stub with deliver() method
        if (std.ascii.eqlIgnoreCase(method, "getEventBus")) {
            const eb = try self.arena.create(types.ObjectInstance);
            eb.* = .{ .class_name = "EventBus" };
            return Value{ .object = eb };
        }
        // Test.createStub(Type, StubProvider) → create a stub proxy
        if (std.ascii.eqlIgnoreCase(method, "createStub") and args.len >= 2) {
            return try self.handle_test_create_stub(args);
        }
        return .void_val;
    }

    pub fn set_current_page_reference(self: *Evaluator, page_value: Value) !void {
        const page_ref = if (page_value == .object and
            std.ascii.eqlIgnoreCase(page_value.object.class_name, "PageReference"))
            page_value
        else
            try self.make_page_reference_value(page_value);

        const key = "ApexPages.currentPageRef";
        if (self.global_env.bindings.getPtr(key)) |slot| {
            slot.* = page_ref;
        } else {
            try self.global_env.define(key, page_ref);
        }
    }

    fn make_page_reference_value(self: *Evaluator, page_value: Value) !Value {
        const pr = try self.arena.create(types.ObjectInstance);
        pr.* = .{ .class_name = "PageReference" };
        const raw_name = try utils.coerce_to_string(page_value, self.arena);
        const url = if (raw_name.len == 0)
            ""
        else if (raw_name[0] == '/')
            raw_name
        else
            try std.fmt.allocPrint(self.arena, "/apex/{s}", .{raw_name});
        try pr.fields.put(self.arena, "url", Value{ .string = url });
        const params = try self.arena.create(types.MapValue);
        params.* = .{};
        try pr.fields.put(self.arena, "parameters", Value{ .map = params });
        return Value{ .object = pr };
    }

    fn handle_test_stop_test(self: *Evaluator) !void {
        // Execute any Schedulable instances queued via System.schedule between startTest/stopTest.
        while (self.pending_schedulables.items.len > 0) {
            const sched = self.pending_schedulables.orderedRemove(0);
            if (sched == .object) {
                if (self.find_class(sched.object.class_name)) |class_decl| {
                    const ctx_obj = try self.arena.create(types.ObjectInstance);
                    ctx_obj.* = .{ .class_name = "System.SchedulableContext" };
                    try ctx_obj.fields.put(
                        self.arena,
                        "triggerId",
                        Value{ .string = "08e000000000001" },
                    );
                    _ = self.call_instance_method(
                        class_decl,
                        sched.object,
                        "execute",
                        &.{Value{ .object = ctx_obj }},
                    ) catch {};
                }
            }
        }
    }

    fn handle_test_install(self: *Evaluator, args: []const Value) !void {
        const install_handler_class = self.find_class(args[0].object.class_name) orelse return;
        const install_context = try self.arena.create(types.ObjectInstance);
        install_context.* = .{ .class_name = "System.InstallContext" };
        if (args.len >= 2) {
            try install_context.fields.put(self.arena, "previousVersion", args[1]);
        }
        if (args.len >= 3) try install_context.fields.put(self.arena, "upgrade", args[2]);
        if (args.len >= 3 and args[2] == .boolean) {
            try install_context.fields.put(
                self.arena,
                "firstInstall",
                Value{ .boolean = !args[2].boolean },
            );
        }
        _ = try self.call_instance_method(
            install_handler_class,
            args[0].object,
            "onInstall",
            &.{Value{ .object = install_context }},
        );
    }

    fn handle_test_create_stub(self: *Evaluator, args: []const Value) !Value {
        const type_val = args[0]; // Type object
        const provider = args[1]; // StubProvider instance
        const type_name: []const u8 = if (type_val == .object)
            (if (type_val.object.fields.get("name")) |n|
                (if (n == .string) n.string else "Object")
            else
                "Object")
        else
            "Object";
        const stub = try self.arena.create(types.ObjectInstance);
        stub.* = .{ .class_name = type_name };
        try stub.fields.put(self.arena, "__stubProvider__", provider);
        try stub.fields.put(
            self.arena,
            "__stubDisplayClassName__",
            Value{ .string = try std.fmt.allocPrint(
                self.arena,
                "{s}__sfdc_ApexStub",
                .{type_name},
            ) },
        );
        self.initialize_stub_instance_fields(type_name, stub);
        return Value{ .object = stub };
    }

    fn initialize_stub_instance_fields(
        self: *Evaluator,
        type_name: []const u8,
        stub: *types.ObjectInstance,
    ) void {
        const class_decl = self.find_class(type_name) orelse return;
        self.init_instance_fields(class_decl, stub) catch {};
        if (class_decl.super_class) |sc| {
            if (self.find_class(sc.name)) |parent| {
                self.init_instance_fields(parent, stub) catch {};
            }
        }
    }

    fn handle_trigger_handler(self: *Evaluator, method: []const u8, args: []const Value) !Value {
        if (std.ascii.eqlIgnoreCase(method, "bypass") and
            args.len > 0 and
            args[0] == .string)
        {
            try self.bypasses.put(self.arena, args[0].string, {});
        }
        return .void_val;
    }

    fn get_dml_options_all_or_none(_: *Evaluator, value: Value) ?bool {
        const fields = switch (value) {
            .object => value.object.fields,
            .sobject => value.sobject.fields,
            else => return null,
        };
        if (fields.get("OptAllOrNone")) |opt| {
            if (opt == .boolean) return opt.boolean;
        }
        for (fields.keys(), fields.values()) |k, v| {
            if (std.ascii.eqlIgnoreCase(k, "OptAllOrNone") and v == .boolean) {
                return v.boolean;
            }
        }
        return null;
    }

    fn sobject_id_for_result(_: *Evaluator, obj: *types.SObject) ?[]const u8 {
        if (obj.id) |id| return id;
        if (utils.sobject_get(&obj.fields, "Id")) |id_val| {
            if (id_val == .string) return id_val.string;
        }
        return null;
    }

    fn create_dml_result_value(
        self: *Evaluator,
        result_class: []const u8,
        success: bool,
        id: ?[]const u8,
        is_created: ?bool,
    ) !Value {
        const sr = try self.arena.create(types.ObjectInstance);
        sr.* = .{ .class_name = result_class };
        try sr.fields.put(self.arena, "isSuccess", Value{ .boolean = success });
        try sr.fields.put(self.arena, "success", Value{ .boolean = success });
        if (id) |record_id| {
            try sr.fields.put(self.arena, "id", Value{ .string = record_id });
            try sr.fields.put(self.arena, "Id", Value{ .string = record_id });
        }
        if (is_created) |created| {
            try sr.fields.put(self.arena, "isCreated", Value{ .boolean = created });
            try sr.fields.put(self.arena, "created", Value{ .boolean = created });
        }
        return Value{ .object = sr };
    }

    fn create_empty_result_list_value(self: *Evaluator) !Value {
        const empty = try self.arena.create(types.ListValue);
        empty.* = .{};
        return Value{ .list = empty };
    }

    fn build_failed_dml_result(
        self: *Evaluator,
        result_class: []const u8,
        target: Value,
        is_upsert: bool,
    ) !Value {
        const result_id = if (target == .sobject)
            self.sobject_id_for_result(target.sobject)
        else
            null;
        const result = try self.create_dml_result_value(
            result_class,
            false,
            result_id,
            if (is_upsert) false else null,
        );
        if (self.pending_exception) |pe| {
            const errors_list = try self.arena.create(types.ListValue);
            errors_list.* = .{};
            const err_obj = try self.arena.create(types.ObjectInstance);
            err_obj.* = .{ .class_name = "Database.Error" };
            var message_val: Value = Value{ .string = "" };
            var fields_val: Value = Value{ .list = blk: {
                const empty = try self.arena.create(types.ListValue);
                empty.* = .{};
                break :blk empty;
            } };
            if (pe == .object) {
                if (pe.object.fields.get("message")) |m| message_val = m;
                if (pe.object.fields.get("field")) |f| {
                    if (f == .string) {
                        const fl = try self.arena.create(types.ListValue);
                        fl.* = .{};
                        try fl.items.append(self.arena, f);
                        fields_val = Value{ .list = fl };
                    }
                }
            } else if (pe == .string) {
                message_val = pe;
            }
            try err_obj.fields.put(self.arena, "message", message_val);
            try err_obj.fields.put(
                self.arena,
                "statusCode",
                Value{ .string = dml_error_status_code(result_class, message_val) },
            );
            try err_obj.fields.put(self.arena, "fields", fields_val);
            try errors_list.items.append(self.arena, Value{ .object = err_obj });
            if (result == .object) {
                try result.object.fields.put(self.arena, "errors", Value{ .list = errors_list });
            }
        }
        return result;
    }

    fn dml_error_status_code(result_class: []const u8, message: Value) []const u8 {
        if (message == .string and
            std.mem.startsWith(u8, message.string, "REQUIRED_FIELD_MISSING:"))
        {
            return "REQUIRED_FIELD_MISSING";
        }
        if (std.ascii.eqlIgnoreCase(result_class, "Database.DeleteResult") or
            std.ascii.eqlIgnoreCase(result_class, "Database.UndeleteResult"))
        {
            return "UNKNOWN_EXCEPTION";
        }
        return "FIELD_CUSTOM_VALIDATION_EXCEPTION";
    }

    fn execute_partial_database_method(
        self: *Evaluator,
        op: ast.DmlOp,
        result_class: []const u8,
        target: Value,
        external_id_field: ?[]const u8,
    ) !Value {
        switch (target) {
            .null_val, .void_val => return self.create_empty_result_list_value(),
            .sobject => {
                self.limits_dml += 1;
                self.limits_dml_rows += 1;
                return try self.execute_partial_single_sobject_dml(
                    op,
                    result_class,
                    target,
                    external_id_field,
                );
            },
            .list => |records| {
                return try self.execute_partial_dml_items(
                    op,
                    result_class,
                    records.items.items,
                    external_id_field,
                );
            },
            .set => |records| {
                return try self.execute_partial_dml_items(
                    op,
                    result_class,
                    records.entries.values(),
                    external_id_field,
                );
            },
            else => {
                const list = try self.arena.create(types.ListValue);
                list.* = .{};
                try list.items.append(
                    self.arena,
                    try self.build_failed_dml_result(result_class, target, op == .upsert),
                );
                return Value{ .list = list };
            },
        }
    }

    fn execute_partial_dml_items(
        self: *Evaluator,
        op: ast.DmlOp,
        result_class: []const u8,
        items: []const Value,
        external_id_field: ?[]const u8,
    ) !Value {
        if (items.len == 0) return self.create_empty_result_list_value();

        self.limits_dml += 1;
        self.limits_dml_rows += @intCast(items.len);

        const list = try self.arena.create(types.ListValue);
        list.* = .{};
        for (items) |item| {
            const result = try self.execute_partial_dml_item(
                op,
                result_class,
                item,
                external_id_field,
            );
            try list.items.append(self.arena, result);
        }
        return Value{ .list = list };
    }

    fn execute_partial_dml_item(
        self: *Evaluator,
        op: ast.DmlOp,
        result_class: []const u8,
        item: Value,
        external_id_field: ?[]const u8,
    ) !Value {
        if (item != .sobject) {
            return try self.build_failed_dml_result(result_class, item, op == .upsert);
        }
        return self.execute_partial_single_sobject_dml(
            op,
            result_class,
            item,
            external_id_field,
        ) catch {
            const failed = try self.build_failed_dml_result(result_class, item, op == .upsert);
            self.pending_exception = null;
            return failed;
        };
    }

    fn execute_partial_single_sobject_dml(
        self: *Evaluator,
        op: ast.DmlOp,
        result_class: []const u8,
        target: Value,
        external_id_field: ?[]const u8,
    ) !Value {
        return switch (op) {
            .insert => try self.execute_successful_partial_dml(
                .insert,
                result_class,
                target,
                null,
                null,
            ),
            .update => try self.execute_successful_partial_dml(
                .update,
                result_class,
                target,
                null,
                null,
            ),
            .upsert => try self.execute_successful_partial_dml(
                .upsert,
                result_class,
                target,
                external_id_field,
                self.will_upsert_create_record(target.sobject, external_id_field),
            ),
            .delete => try self.execute_successful_partial_dml(
                .delete,
                result_class,
                target,
                null,
                null,
            ),
            .undelete => try self.execute_successful_partial_dml(
                .undelete,
                result_class,
                target,
                null,
                null,
            ),
            else => Value.null_val,
        };
    }

    fn execute_successful_partial_dml(
        self: *Evaluator,
        op: ast.DmlOp,
        result_class: []const u8,
        target: Value,
        external_id_field: ?[]const u8,
        is_created: ?bool,
    ) !Value {
        try self.execute_dml_with_external_id_internal(
            op,
            target,
            external_id_field,
            false,
            null,
        );
        return try self.create_dml_result_value(
            result_class,
            true,
            self.sobject_id_for_result(target.sobject),
            is_created,
        );
    }

    fn handle_database_method(
        self: *Evaluator,
        method: []const u8,
        args: []const Value,
        env: *Env,
    ) anyerror!Value {
        if (database_dml_method(method)) {
            return try self.handle_database_dml_method(method, args);
        }
        if (std.ascii.eqlIgnoreCase(method, "query")) {
            return try self.handle_database_query(args, env);
        }
        if (std.ascii.eqlIgnoreCase(method, "queryWithBinds")) {
            return try self.handle_database_query_with_binds(args, env);
        }
        if (std.ascii.eqlIgnoreCase(method, "countQuery") or
            std.ascii.eqlIgnoreCase(method, "countQueryWithBinds"))
        {
            return try self.handle_database_count_query(args, env);
        }
        if (std.ascii.eqlIgnoreCase(method, "getQueryLocator")) {
            return try self.handle_database_query_locator(args);
        }
        if (std.ascii.eqlIgnoreCase(method, "emptyRecycleBin")) {
            return self.handle_database_empty_recycle_bin(args);
        }
        if (std.ascii.eqlIgnoreCase(method, "setSavepoint")) {
            return try self.handle_database_set_savepoint();
        }
        if (std.ascii.eqlIgnoreCase(method, "rollback")) return self.handle_database_rollback();
        if (std.ascii.eqlIgnoreCase(method, "executeBatch")) {
            return try self.handle_database_execute_batch(args);
        }
        if (std.ascii.eqlIgnoreCase(method, "merge")) return try self.handle_database_merge(args);
        return .void_val;
    }

    fn database_dml_method(method: []const u8) bool {
        return std.ascii.eqlIgnoreCase(method, "insert") or
            std.ascii.eqlIgnoreCase(method, "update") or
            std.ascii.eqlIgnoreCase(method, "upsert") or
            std.ascii.eqlIgnoreCase(method, "delete") or
            std.ascii.eqlIgnoreCase(method, "undelete");
    }

    fn handle_database_dml_method(
        self: *Evaluator,
        method: []const u8,
        args: []const Value,
    ) anyerror!Value {
        const result_class = database_dml_result_class(method);
        const is_upsert = std.ascii.eqlIgnoreCase(method, "upsert");
        const external_id_field = if (is_upsert and args.len >= 2 and args[1] != .boolean)
            extract_s_object_field_name(args[1])
        else
            null;
        const all_or_nothing = self.database_dml_all_or_nothing(args, is_upsert);

        try self.reject_user_mode_database_dml(args);
        const upsert_creates = try self.collect_upsert_creates(
            args,
            is_upsert,
            external_id_field,
        );
        if (args.len > 0) {
            const op = database_dml_op(method);
            if (all_or_nothing) {
                try self.execute_database_dml_all_or_nothing(
                    op,
                    args[0],
                    is_upsert,
                    external_id_field,
                );
            } else {
                return try self.execute_database_dml_best_effort(
                    op,
                    result_class,
                    args[0],
                    external_id_field,
                    is_upsert,
                );
            }
        }
        return try self.build_database_dml_success_result(
            result_class,
            args,
            is_upsert,
            upsert_creates.items,
        );
    }

    fn database_dml_result_class(method: []const u8) []const u8 {
        if (std.ascii.eqlIgnoreCase(method, "upsert")) return "Database.UpsertResult";
        if (std.ascii.eqlIgnoreCase(method, "undelete")) return "Database.UndeleteResult";
        if (std.ascii.eqlIgnoreCase(method, "delete")) return "Database.DeleteResult";
        return "Database.SaveResult";
    }

    fn database_dml_op(method: []const u8) ast.DmlOp {
        if (std.ascii.eqlIgnoreCase(method, "insert")) return .insert;
        if (std.ascii.eqlIgnoreCase(method, "update")) return .update;
        if (std.ascii.eqlIgnoreCase(method, "upsert")) return .upsert;
        if (std.ascii.eqlIgnoreCase(method, "undelete")) return .undelete;
        return .delete;
    }

    fn database_dml_all_or_nothing(
        self: *Evaluator,
        args: []const Value,
        is_upsert: bool,
    ) bool {
        if (is_upsert and args.len >= 3 and args[2] == .boolean) return args[2].boolean;
        if (is_upsert and args.len >= 3) {
            if (self.get_dml_options_all_or_none(args[2])) |opt| return opt;
        }
        if (args.len >= 2 and args[1] == .boolean) return args[1].boolean;
        if (args.len >= 2) {
            if (self.get_dml_options_all_or_none(args[1])) |opt| return opt;
        }
        return true;
    }

    fn reject_user_mode_database_dml(self: *Evaluator, args: []const Value) anyerror!void {
        const has_permset_db = if (self.store.get("PermissionSetAssignment")) |psa|
            psa.items.len > 0
        else
            false;
        if (!self.is_min_access_user or has_permset_db or args.len < 2) return;
        if (!is_database_user_mode_arg(args[1])) return;

        const from_type = database_dml_first_type(args);
        const msg = try std.fmt.allocPrint(
            self.arena,
            "Access to entity '{s}' denied",
            .{from_type},
        );
        const exc = try self.arena.create(types.ObjectInstance);
        exc.* = .{ .class_name = "System.SecurityException" };
        try exc.fields.put(self.arena, "message", Value{ .string = msg });
        self.pending_exception = Value{ .object = exc };
        return error.ApexException;
    }

    fn is_database_user_mode_arg(arg: Value) bool {
        if (arg == .string) return std.ascii.eqlIgnoreCase(arg.string, "USER_MODE");
        if (arg == .object) {
            if (arg.object.fields.get("name")) |n| {
                if (n == .string) return std.ascii.eqlIgnoreCase(n.string, "USER_MODE");
            }
        }
        return false;
    }

    fn database_dml_first_type(args: []const Value) []const u8 {
        if (args.len == 0) return "SObject";
        if (args[0] == .sobject) return args[0].sobject.type_name;
        if (args[0] == .list and args[0].list.items.items.len > 0 and
            args[0].list.items.items[0] == .sobject)
        {
            return args[0].list.items.items[0].sobject.type_name;
        }
        return "SObject";
    }

    fn collect_upsert_creates(
        self: *Evaluator,
        args: []const Value,
        is_upsert: bool,
        external_id_field: ?[]const u8,
    ) anyerror!std.ArrayListUnmanaged(bool) {
        var creates: std.ArrayListUnmanaged(bool) = .empty;
        if (!is_upsert or args.len == 0) return creates;
        if (args[0] == .sobject) {
            const will_create =
                self.will_upsert_create_record(args[0].sobject, external_id_field);
            try creates.append(self.arena, will_create);
        } else if (args[0] == .list) {
            for (args[0].list.items.items) |item| {
                const will_create = item != .sobject or
                    self.will_upsert_create_record(item.sobject, external_id_field);
                try creates.append(self.arena, will_create);
            }
        }
        return creates;
    }

    fn execute_database_dml_all_or_nothing(
        self: *Evaluator,
        op: ast.DmlOp,
        target: Value,
        is_upsert: bool,
        external_id_field: ?[]const u8,
    ) anyerror!void {
        if (is_upsert) {
            try self.execute_dml_with_external_id(op, target, external_id_field);
        } else {
            try self.execute_dml(op, target);
        }
    }

    fn execute_database_dml_best_effort(
        self: *Evaluator,
        op: ast.DmlOp,
        result_class: []const u8,
        target: Value,
        external_id_field: ?[]const u8,
        is_upsert: bool,
    ) anyerror!Value {
        return self.execute_partial_database_method(
            op,
            result_class,
            target,
            external_id_field,
        ) catch |err| {
            if (err == error.ApexException and target == .sobject) {
                const failed = try self.build_failed_dml_result(result_class, target, is_upsert);
                self.pending_exception = null;
                return failed;
            }
            self.pending_exception = null;
            return err;
        };
    }

    fn build_database_dml_success_result(
        self: *Evaluator,
        result_class: []const u8,
        args: []const Value,
        is_upsert: bool,
        upsert_creates: []const bool,
    ) anyerror!Value {
        if (args.len > 0 and args[0] == .sobject) {
            const was_created = is_upsert and upsert_creates.len > 0 and upsert_creates[0];
            const sr = try self.make_database_dml_success_result(
                result_class,
                args[0].sobject.id orelse "001000000000001",
                is_upsert,
                was_created,
            );
            return Value{ .object = sr };
        }

        const list = try self.arena.create(types.ListValue);
        list.* = .{};
        if (args.len > 0 and args[0] == .list) {
            try self.append_database_dml_success_results(
                list,
                result_class,
                args[0].list,
                is_upsert,
                upsert_creates,
            );
        } else {
            const sr = try self.make_database_dml_success_result(
                result_class,
                "001000000000001",
                false,
                false,
            );
            try list.items.append(self.arena, Value{ .object = sr });
        }
        return Value{ .list = list };
    }

    fn append_database_dml_success_results(
        self: *Evaluator,
        list: *types.ListValue,
        result_class: []const u8,
        records: *types.ListValue,
        is_upsert: bool,
        upsert_creates: []const bool,
    ) anyerror!void {
        for (records.items.items, 0..) |item, idx| {
            const was_created = is_upsert and if (idx < upsert_creates.len)
                upsert_creates[idx]
            else
                true;
            const sr = try self.make_database_dml_success_result(
                result_class,
                database_dml_item_id(item),
                is_upsert,
                was_created,
            );
            try list.items.append(self.arena, Value{ .object = sr });
        }
    }

    fn make_database_dml_success_result(
        self: *Evaluator,
        result_class: []const u8,
        id: []const u8,
        is_upsert: bool,
        was_created: bool,
    ) anyerror!*types.ObjectInstance {
        const sr = try self.arena.create(types.ObjectInstance);
        sr.* = .{ .class_name = result_class };
        try sr.fields.put(self.arena, "isSuccess", Value{ .boolean = true });
        try sr.fields.put(self.arena, "success", Value{ .boolean = true });
        try sr.fields.put(self.arena, "Id", Value{ .string = id });
        if (is_upsert) {
            try sr.fields.put(
                self.arena,
                "isCreated",
                Value{ .boolean = was_created },
            );
            try sr.fields.put(
                self.arena,
                "created",
                Value{ .boolean = was_created },
            );
        }
        return sr;
    }

    fn database_dml_item_id(item: Value) []const u8 {
        if (item == .sobject) return item.sobject.id orelse "001000000000001";
        return "001000000000001";
    }

    fn handle_database_query(self: *Evaluator, args: []const Value, env: *Env) anyerror!Value {
        if (args.len > 0 and args[0] == .string) return self.execute_soql(args[0].string, env);
        const list = try self.arena.create(types.ListValue);
        list.* = .{};
        return Value{ .list = list };
    }

    fn handle_database_query_with_binds(
        self: *Evaluator,
        args: []const Value,
        env: *Env,
    ) anyerror!Value {
        if (args.len >= 2 and args[0] == .string) {
            var soql_str = args[0].string;
            if (args[1] == .map) {
                soql_str = try self.database_query_with_bound_map(soql_str, args[1]);
            }
            return self.execute_soql(soql_str, env);
        }
        return try self.make_empty_list();
    }

    fn database_query_with_bound_map(
        self: *Evaluator,
        soql_str: []const u8,
        bind_arg: Value,
    ) anyerror![]const u8 {
        var result_buf: std.ArrayListUnmanaged(u8) = .empty;
        var pos: usize = 0;
        while (pos < soql_str.len) {
            if (soql_str[pos] != ':') {
                try result_buf.append(self.arena, soql_str[pos]);
                pos += 1;
                continue;
            }
            var end = pos + 1;
            while (end < soql_str.len and
                (std.ascii.isAlphanumeric(soql_str[end]) or soql_str[end] == '_'))
            {
                end += 1;
            }
            const bind_name = soql_str[pos + 1 .. end];
            if (bind_arg.map.entries.get(bind_name)) |bind_val| {
                const s = try utils.coerce_to_string(bind_val, self.arena);
                try result_buf.append(self.arena, '\'');
                try result_buf.appendSlice(self.arena, s);
                try result_buf.append(self.arena, '\'');
            } else {
                try result_buf.appendSlice(self.arena, soql_str[pos..end]);
            }
            pos = end;
        }
        return try result_buf.toOwnedSlice(self.arena);
    }

    fn handle_database_count_query(
        self: *Evaluator,
        args: []const Value,
        env: *Env,
    ) anyerror!Value {
        if (args.len == 0 or args[0] != .string) return Value{ .integer = 0 };

        const soql = args[0].string;
        if (std.ascii.indexOfIgnoreCase(soql, "count()")) |_| {
            return self.execute_soql(soql, env);
        }
        const count_result = try self.execute_soql(soql, env);
        if (count_result == .list) {
            return Value{ .integer = @intCast(count_result.list.items.items.len) };
        }
        return count_result;
    }

    fn handle_database_query_locator(self: *Evaluator, args: []const Value) anyerror!Value {
        const ql = try self.arena.create(types.ObjectInstance);
        ql.* = .{ .class_name = "Database.QueryLocator" };
        if (args.len > 0 and args[0] == .string) {
            try ql.fields.put(self.arena, "query", args[0]);
        } else if (args.len > 0 and args[0] == .list) {
            try ql.fields.put(self.arena, "records", args[0]);
        }
        return Value{ .object = ql };
    }

    fn handle_database_empty_recycle_bin(self: *Evaluator, args: []const Value) Value {
        self.limits_dml += 1;
        if (args.len > 0 and args[0] == .list) {
            self.limits_dml_rows += @intCast(args[0].list.items.items.len);
        } else if (args.len > 0) {
            self.limits_dml_rows += 1;
        }
        return .void_val;
    }

    fn handle_database_set_savepoint(self: *Evaluator) anyerror!Value {
        self.limits_dml += 1;
        const sp = try self.arena.create(types.ObjectInstance);
        sp.* = .{ .class_name = "Database.SavePoint" };
        return Value{ .object = sp };
    }

    fn handle_database_rollback(self: *Evaluator) Value {
        self.limits_dml += 1;
        return .void_val;
    }

    const DatabaseLimitSnapshot = struct {
        dml: u32,
        dml_rows: u32,
        soql: u32,
        publish_immediate: u32,
        callouts: u32,
    };

    fn capture_database_limits(self: *Evaluator) DatabaseLimitSnapshot {
        return .{
            .dml = self.limits_dml,
            .dml_rows = self.limits_dml_rows,
            .soql = self.limits_soql,
            .publish_immediate = self.limits_publish_immediate,
            .callouts = self.limits_callouts,
        };
    }

    fn restore_database_limits(self: *Evaluator, snapshot: DatabaseLimitSnapshot) void {
        self.limits_dml = snapshot.dml;
        self.limits_dml_rows = snapshot.dml_rows;
        self.limits_soql = snapshot.soql;
        self.limits_publish_immediate = snapshot.publish_immediate;
        self.limits_callouts = snapshot.callouts;
    }

    fn handle_database_execute_batch(self: *Evaluator, args: []const Value) anyerror!Value {
        const snapshot = self.capture_database_limits();
        defer self.restore_database_limits(snapshot);

        if (args.len > 0 and args[0] == .object) {
            return Value{ .string = try self.execute_database_batch_object(args[0].object) };
        }
        return Value{ .string = try self.alloc_id() };
    }

    fn execute_database_batch_object(
        self: *Evaluator,
        batch: *types.ObjectInstance,
    ) anyerror![]const u8 {
        if (self.batch_job_runner_active or self.batch_lifecycle_depth > 0) {
            return try self.enqueue_nested_database_batch(batch);
        }
        const job_id = try self.create_async_apex_job("BatchApex", batch.class_name, "execute");
        try batch.fields.put(self.arena, "__batchJobId", Value{ .string = job_id });
        self.batch_job_runner_active = true;
        self.pending_batch_jobs = .empty;
        defer {
            self.pending_batch_jobs = .empty;
            self.batch_job_runner_active = false;
        }

        try self.pending_batch_jobs.append(self.arena, Value{ .object = batch });
        var job_index: usize = 0;
        while (job_index < self.pending_batch_jobs.items.len) : (job_index += 1) {
            const batch_value = self.pending_batch_jobs.items[job_index];
            if (batch_value != .object) continue;
            try self.execute_pending_batch_job(batch_value.object);
        }
        return job_id;
    }

    fn enqueue_nested_database_batch(
        self: *Evaluator,
        batch: *types.ObjectInstance,
    ) anyerror![]const u8 {
        const job_id = try self.create_async_apex_job("BatchApex", batch.class_name, "execute");
        try batch.fields.put(self.arena, "__batchJobId", Value{ .string = job_id });
        if (self.active_batch_context) |batch_context| {
            try batch_context.fields.put(self.arena, "ChildJobId", Value{ .string = job_id });
        }
        if (self.batch_job_runner_active) {
            try self.pending_batch_jobs.append(self.arena, Value{ .object = batch });
        }
        return job_id;
    }

    fn handle_database_merge(self: *Evaluator, args: []const Value) anyerror!Value {
        if (args.len >= 2) {
            const secondary_ids = try self.collect_database_merge_secondary_ids(args[1]);
            self.remove_database_merge_secondaries(secondary_ids.items);
            self.remove_duplicate_record_items_for_merge(secondary_ids.items);
        }
        try self.cleanup_orphaned_duplicate_record_sets();
        return try self.build_database_merge_result();
    }

    fn collect_database_merge_secondary_ids(
        self: *Evaluator,
        secondaries: Value,
    ) anyerror!std.ArrayListUnmanaged([]const u8) {
        var secondary_ids: std.ArrayListUnmanaged([]const u8) = .empty;
        if (secondaries == .sobject and secondaries.sobject.id != null) {
            try secondary_ids.append(self.arena, secondaries.sobject.id.?);
        } else if (secondaries == .list) {
            for (secondaries.list.items.items) |item| {
                if (item == .sobject and item.sobject.id != null) {
                    try secondary_ids.append(self.arena, item.sobject.id.?);
                }
            }
        }
        return secondary_ids;
    }

    fn remove_database_merge_secondaries(self: *Evaluator, secondary_ids: []const []const u8) void {
        for (secondary_ids) |sec_id| {
            var store_iter = self.store.iterator();
            while (store_iter.next()) |entry| {
                var i: usize = 0;
                while (i < entry.value_ptr.items.len) {
                    if (database_merge_record_matches(entry.value_ptr.items[i], sec_id)) {
                        _ = entry.value_ptr.orderedRemove(i);
                    } else {
                        i += 1;
                    }
                }
            }
        }
    }

    fn database_merge_record_matches(item: Value, sec_id: []const u8) bool {
        return item == .sobject and item.sobject.id != null and
            std.mem.eql(u8, item.sobject.id.?, sec_id);
    }

    fn remove_duplicate_record_items_for_merge(
        self: *Evaluator,
        secondary_ids: []const []const u8,
    ) void {
        if (self.store.getPtr("DuplicateRecordItem")) |dri_records| {
            var i: usize = 0;
            while (i < dri_records.items.len) {
                const item = dri_records.items[i];
                if (database_duplicate_item_deleted(item, secondary_ids)) {
                    self.update_duplicate_record_set_count(item.sobject, -1) catch {};
                    _ = dri_records.orderedRemove(i);
                    continue;
                }
                i += 1;
            }
        }
    }

    fn database_duplicate_item_deleted(item: Value, secondary_ids: []const []const u8) bool {
        if (item != .sobject) return false;
        const rec_id_val = utils.sobject_get(&item.sobject.fields, "RecordId");
        if (rec_id_val == null or rec_id_val.? != .string) return false;
        for (secondary_ids) |sec_id| {
            if (std.mem.eql(u8, rec_id_val.?.string, sec_id)) return true;
        }
        return false;
    }

    fn build_database_merge_result(self: *Evaluator) anyerror!Value {
        const mr_list = try self.arena.create(types.ListValue);
        mr_list.* = .{};
        const mr = try self.arena.create(types.ObjectInstance);
        mr.* = .{ .class_name = "Database.MergeResult" };
        try mr.fields.put(self.arena, "isSuccess", Value{ .boolean = true });
        try mr.fields.put(self.arena, "success", Value{ .boolean = true });
        try mr_list.items.append(self.arena, Value{ .object = mr });
        return Value{ .list = mr_list };
    }

    fn handle_system_method(
        self: *Evaluator,
        inner: []const u8,
        method: []const u8,
        args: []const Value,
        current_env: *Env,
    ) !Value {
        if (try self.handle_system_runtime_method(inner, args)) |result| return result;
        // System.Request.getCurrent() → return a Request object
        if (std.ascii.eqlIgnoreCase(inner, "Request")) {
            return self.handle_system_request(method, args);
        }
        // System.AccessType/AccessLevel
        if (std.ascii.eqlIgnoreCase(inner, "AccessType") or
            std.ascii.eqlIgnoreCase(inner, "AccessLevel"))
        {
            return Value{ .string = method };
        }
        // System.LoggingLevel / System.TriggerOperation
        if (std.ascii.eqlIgnoreCase(inner, "LoggingLevel") or
            std.ascii.eqlIgnoreCase(inner, "TriggerOperation"))
        {
            return self.handle_system_enum(inner, method, args);
        }
        // System.SObjectAccessDecision
        if (std.ascii.eqlIgnoreCase(inner, "SObjectAccessDecision")) {
            return .void_val;
        }
        // System.Limits → all methods return 0
        if (std.ascii.eqlIgnoreCase(inner, "Limits")) {
            var bctx = self.make_builtin_context();
            if (try builtins.dispatch_static(&bctx, "Limits", method, args)) |result| {
                return result;
            }
            return Value{ .integer = 0 };
        }
        // System.JSON.serialize / System.JSON.deserialize / System.JSON.deserializeUntyped
        if (std.ascii.eqlIgnoreCase(inner, "JSON")) {
            if (try self.handle_system_json(method, args)) |result| return result;
        }
        // System.Test.startTest / System.Test.stopTest / setMock / etc.
        if (std.ascii.eqlIgnoreCase(inner, "Test")) {
            return self.handle_test(method, args);
        }
        // System.Database.insert / update / delete / upsert / undelete
        if (std.ascii.eqlIgnoreCase(inner, "Database")) {
            return self.handle_database_method(method, args, current_env);
        }
        // Delegate System.EventBus.publish through the EventBus handler.
        if (std.ascii.eqlIgnoreCase(inner, "EventBus") and
            std.ascii.eqlIgnoreCase(method, "publish"))
        {
            return self.call_method("EventBus", "publish", args) catch .void_val;
        }
        // Generic fallback: delegate System.X.method to builtins.dispatchStatic(X, method, args)
        // This covers System.UserInfo, System.Type, System.Assert, System.URL, etc.
        {
            var bctx = self.make_builtin_context();
            if (try builtins.dispatch_static(&bctx, inner, method, args)) |result| {
                return result;
            }
        }
        return .void_val;
    }

    fn handle_system_runtime_method(
        self: *Evaluator,
        inner: []const u8,
        args: []const Value,
    ) !?Value {
        if (std.ascii.eqlIgnoreCase(inner, "enqueueJob") and
            args.len > 0 and
            args[0] == .object)
        {
            return try self.enqueue_job(args[0].object);
        }
        if (std.ascii.eqlIgnoreCase(inner, "enqueueJob")) return .void_val;
        if (std.ascii.eqlIgnoreCase(inner, "attachFinalizer")) {
            if (self.active_queueable_job_id != null and
                args.len > 0 and
                args[0] == .object)
            {
                self.attached_finalizer = args[0].object;
            }
            return .void_val;
        }
        if (std.ascii.eqlIgnoreCase(inner, "runAs")) return .void_val;
        if (std.ascii.eqlIgnoreCase(inner, "schedule")) {
            return try self.handle_system_schedule(args);
        }
        if (std.ascii.eqlIgnoreCase(inner, "abortJob")) return .void_val;
        if (std.ascii.eqlIgnoreCase(inner, "debug") and args.len > 0) {
            const msg = try utils.coerce_to_string(args[0], self.arena);
            try self.stdout.appendSlice(self.arena, msg);
            try self.stdout.append(self.arena, '\n');
            return .void_val;
        }
        return null;
    }

    fn handle_system_schedule(self: *Evaluator, args: []const Value) !Value {
        const job_id = try std.fmt.allocPrint(self.arena, "08e{d:0>15}", .{self.next_id});
        self.next_id += 1;
        const job_name = if (args.len >= 1 and args[0] == .string) args[0].string else job_id;
        const cron_expr = if (args.len >= 2 and args[1] == .string)
            args[1].string
        else
            "0 0 0 28 5 ? 2099";
        try self.scheduled_jobs.put(self.arena, job_id, cron_expr);
        try self.store_scheduled_cron_trigger(job_id, job_name, cron_expr);
        if (args.len >= 3 and args[2] == .object) {
            try self.pending_schedulables.append(self.arena, args[2]);
        }
        return Value{ .string = job_id };
    }

    fn store_scheduled_cron_trigger(
        self: *Evaluator,
        job_id: []const u8,
        job_name: []const u8,
        cron_expr: []const u8,
    ) !void {
        const detail = try self.arena.create(types.SObject);
        detail.* = .{ .type_name = "CronJobDetail" };
        const detail_id = try std.fmt.allocPrint(self.arena, "08a{d:0>15}", .{self.next_id});
        self.next_id += 1;
        detail.id = detail_id;
        try detail.fields.put(self.arena, "Id", Value{ .string = detail_id });
        try detail.fields.put(self.arena, "Name", Value{ .string = job_name });
        try detail.fields.put(self.arena, "JobType", Value{ .string = "7" });

        const trigger = try self.arena.create(types.SObject);
        trigger.* = .{ .type_name = "CronTrigger", .id = job_id };
        try trigger.fields.put(self.arena, "Id", Value{ .string = job_id });
        try trigger.fields.put(self.arena, "CronExpression", Value{ .string = cron_expr });
        try trigger.fields.put(self.arena, "TimesTriggered", Value{ .integer = 0 });
        try trigger.fields.put(
            self.arena,
            "NextFireTime",
            Value{ .string = "2099-05-28 00:00:00" },
        );
        try trigger.fields.put(self.arena, "CronJobDetail", Value{ .sobject = detail });
        try trigger.fields.put(self.arena, "CronJobDetailId", Value{ .string = detail_id });

        const gop = try self.store.getOrPut(self.arena, "CronTrigger");
        if (!gop.found_existing) gop.value_ptr.* = .empty;
        try gop.value_ptr.append(self.arena, Value{ .sobject = trigger });
        try self.id_type_map.put(self.arena, job_id, "CronTrigger");
    }

    fn handle_system_request(self: *Evaluator, method: []const u8, args: []const Value) !Value {
        var bctx = self.make_builtin_context();
        if (try builtins.dispatch_static(&bctx, "Request", method, args)) |result| return result;
        const obj = try self.arena.create(types.ObjectInstance);
        obj.* = .{ .class_name = "Request" };
        return Value{ .object = obj };
    }

    fn handle_system_enum(
        self: *Evaluator,
        inner: []const u8,
        method: []const u8,
        args: []const Value,
    ) !Value {
        if (std.ascii.eqlIgnoreCase(method, "valueOf") and
            args.len > 0 and
            args[0] == .string)
        {
            return try self.system_enum_value_of(inner, args[0].string);
        }
        if (std.ascii.eqlIgnoreCase(method, "values")) {
            return try self.system_enum_values(inner);
        }
        return Value{ .string = method };
    }

    fn system_enum_value_of(self: *Evaluator, inner: []const u8, name: []const u8) !Value {
        for (system_enum_values_for(inner)) |v| {
            if (std.ascii.eqlIgnoreCase(name, v)) return Value{ .string = v };
        }
        const exc = try self.arena.create(types.ObjectInstance);
        exc.* = .{ .class_name = "System.NoSuchElementException" };
        const msg = try std.fmt.allocPrint(
            self.arena,
            "No enum constant System.{s}.{s}",
            .{ inner, name },
        );
        try exc.fields.put(self.arena, "message", Value{ .string = msg });
        self.pending_exception = Value{ .object = exc };
        return error.ApexException;
    }

    fn system_enum_values(self: *Evaluator, inner: []const u8) !Value {
        const list = try self.arena.create(types.ListValue);
        list.* = .{};
        for (system_enum_values_for(inner)) |name| {
            try list.items.append(self.arena, Value{ .string = name });
        }
        return Value{ .list = list };
    }

    fn system_enum_values_for(inner: []const u8) []const []const u8 {
        if (std.ascii.eqlIgnoreCase(inner, "LoggingLevel")) {
            return &.{
                "INTERNAL",
                "FINEST",
                "FINER",
                "FINE",
                "DEBUG",
                "INFO",
                "WARN",
                "ERROR",
                "NONE",
            };
        }
        return &.{
            "BEFORE_INSERT",
            "BEFORE_UPDATE",
            "BEFORE_DELETE",
            "AFTER_INSERT",
            "AFTER_UPDATE",
            "AFTER_DELETE",
            "AFTER_UNDELETE",
        };
    }

    fn handle_system_json(
        self: *Evaluator,
        method: []const u8,
        args: []const Value,
    ) !?Value {
        if (std.ascii.eqlIgnoreCase(method, "serialize") or
            std.ascii.eqlIgnoreCase(method, "serializePretty"))
        {
            return try self.handle_system_json_serialize(args);
        }
        if (std.ascii.eqlIgnoreCase(method, "deserialize") or
            std.ascii.eqlIgnoreCase(method, "deserializeUntyped"))
        {
            return try self.handle_system_json_deserialize(method, args);
        }
        if (std.ascii.eqlIgnoreCase(method, "createParser")) {
            return try self.handle_system_json_create_parser(args);
        }
        var bctx = self.make_builtin_context();
        return try builtins.dispatch_static(&bctx, "JSON", method, args);
    }

    fn handle_system_json_serialize(self: *Evaluator, args: []const Value) !Value {
        if (args.len == 0) return Value{ .string = "{}" };
        if (args[0] == .object and
            (std.ascii.eqlIgnoreCase(args[0].object.class_name, "Schema.SObjectField") or
                std.ascii.eqlIgnoreCase(args[0].object.class_name, "SObjectField")))
        {
            return self.throw_system_json_exception(
                "Apex Type unsupported in JSON: Schema.SObjectField",
            );
        }
        return Value{ .string = try utils.to_json(args[0], self.arena) };
    }

    fn handle_system_json_deserialize(
        self: *Evaluator,
        method: []const u8,
        args: []const Value,
    ) !Value {
        if (args.len >= 1 and args[0] == .null_val) {
            return self.throw_system_json_exception("Argument cannot be null.");
        }
        if (args.len >= 1 and args[0] == .string) {
            return try self.deserialize_system_json_string(method, args);
        }
        return Value.null_val;
    }

    fn deserialize_system_json_string(
        self: *Evaluator,
        method: []const u8,
        args: []const Value,
    ) !Value {
        const json_str = args[0].string;
        const trimmed_json = std.mem.trim(u8, json_str, " \t\r\n");
        if (!utils.is_json_balanced(trimmed_json)) {
            return self.throw_system_json_exception("Unexpected end-of-input");
        }
        var bctx = self.make_builtin_context();
        if (try builtins.dispatch_static(&bctx, "JSON", method, args)) |result| {
            return result;
        }
        if (self.parse_json_value(json_str, system_json_type_name(args))) |pv| return pv;
        return Value.null_val;
    }

    fn system_json_type_name(args: []const Value) []const u8 {
        if (args.len >= 2 and args[1] == .object) {
            if (std.ascii.eqlIgnoreCase(args[1].object.class_name, "Type")) {
                if (args[1].object.fields.get("name")) |n| {
                    if (n == .string) return n.string;
                }
            }
            return args[1].object.class_name;
        }
        return "Object";
    }

    fn handle_system_json_create_parser(self: *Evaluator, args: []const Value) !Value {
        if (args.len >= 1 and args[0] == .string) {
            const parser_obj = try self.arena.create(types.ObjectInstance);
            parser_obj.* = .{ .class_name = "JSONParser" };
            try parser_obj.fields.put(self.arena, "__json_body__", args[0]);
            return Value{ .object = parser_obj };
        }
        return Value.null_val;
    }

    fn throw_system_json_exception(self: *Evaluator, message: []const u8) !Value {
        const exc = try self.arena.create(types.ObjectInstance);
        exc.* = .{ .class_name = "System.JSONException" };
        try exc.fields.put(self.arena, "message", Value{ .string = message });
        self.pending_exception = Value{ .object = exc };
        return error.ApexException;
    }

    fn make_builtin_context(self: *Evaluator) builtins.BuiltinContext {
        return .{
            .arena = self.arena,
            .stdout = &self.stdout,
            .pending_exception = &self.pending_exception,
            .see_all_data = self.see_all_data,
            .eval = self,
        };
    }

    // -----------------------------------------------------------------------
    // ヘルパー
    // -----------------------------------------------------------------------

    fn handle_test_factory(
        self: *Evaluator,
        class_name: []const u8,
        method_name: []const u8,
        args: []const Value,
    ) !?Value {
        if (std.ascii.eqlIgnoreCase(class_name, "TestFactory")) {
            return try self.handle_test_factory_class(method_name, args);
        }
        if (std.ascii.eqlIgnoreCase(class_name, "TestDataHelpers")) {
            return try self.handle_test_data_helpers(method_name, args);
        }
        if (std.ascii.eqlIgnoreCase(class_name, "TestHelper")) {
            return self.handle_test_helper(method_name, args);
        }
        return null;
    }

    fn handle_test_factory_class(
        self: *Evaluator,
        method_name: []const u8,
        args: []const Value,
    ) !?Value {
        if (std.ascii.eqlIgnoreCase(method_name, "createSObject")) {
            return try self.create_test_factory_s_object(args);
        }
        if (std.ascii.eqlIgnoreCase(method_name, "createSObjectList")) {
            return try self.create_test_factory_s_object_list(args);
        }
        if (std.ascii.eqlIgnoreCase(method_name, "assignPermSetToUser")) {
            if (self.user_class_has_method("TestFactory", method_name, args)) return null;
            return .void_val;
        }
        if (test_factory_user_method(method_name)) {
            if (self.user_class_has_method("TestFactory", method_name, args)) return null;
            return try self.create_test_factory_user(method_name, args);
        }
        return null;
    }

    fn create_test_factory_s_object(self: *Evaluator, args: []const Value) !Value {
        if (args.len < 1 or args[0] != .sobject) return Value.null_val;
        if (utils.sobject_get(&args[0].sobject.fields, "Name") == null) {
            try args[0].sobject.fields.put(
                self.arena,
                "Name",
                Value{ .string = "Test Record" },
            );
        }
        if (std.ascii.eqlIgnoreCase(args[0].sobject.type_name, "Contact") and
            utils.sobject_get(&args[0].sobject.fields, "LastName") == null)
        {
            try args[0].sobject.fields.put(
                self.arena,
                "LastName",
                Value{ .string = "Test Record" },
            );
        }
        if (args.len >= 2 and args[1] == .boolean and args[1].boolean) {
            try self.insert_record(args[0].sobject);
        }
        if (args.len >= 2 and args[1] == .string) {
            try self.insert_record(args[0].sobject);
        }
        return args[0];
    }

    fn create_test_factory_s_object_list(self: *Evaluator, args: []const Value) !Value {
        const template: ?*types.SObject = if (args.len >= 1 and args[0] == .sobject)
            args[0].sobject
        else
            null;
        const count = if (args.len >= 2 and args[1] == .integer) args[1].integer else 5;
        const do_insert = args.len >= 3 and args[2] == .boolean and args[2].boolean;
        const list = try self.arena.create(types.ListValue);
        list.* = .{};
        var i: i64 = 0;
        while (i < count) : (i += 1) {
            const obj = try self.create_test_factory_list_item(template, i);
            try list.items.append(self.arena, Value{ .sobject = obj });
        }
        if (do_insert) {
            self.execute_dml(.insert, Value{ .list = list }) catch |err| {
                if (err == error.ApexException) return err;
            };
        }
        return Value{ .list = list };
    }

    fn create_test_factory_list_item(
        self: *Evaluator,
        template: ?*types.SObject,
        index: i64,
    ) !*types.SObject {
        const obj = try self.arena.create(types.SObject);
        obj.* = .{ .type_name = if (template) |t| t.type_name else "Account" };
        if (template) |t| {
            for (t.fields.keys(), t.fields.values()) |key, value| {
                try obj.fields.put(self.arena, key, value);
            }
        }
        const name = try std.fmt.allocPrint(self.arena, "Test Record {d}", .{index});
        try obj.fields.put(self.arena, "Name", Value{ .string = name });
        if (std.ascii.eqlIgnoreCase(obj.type_name, "Contact") and
            utils.sobject_get(&obj.fields, "LastName") == null)
        {
            try obj.fields.put(self.arena, "LastName", Value{ .string = name });
        }
        if (std.ascii.eqlIgnoreCase(obj.type_name, "Opportunity") and
            utils.sobject_get(&obj.fields, "StageName") == null)
        {
            try obj.fields.put(self.arena, "StageName", Value{ .string = "Prospecting" });
        }
        return obj;
    }

    fn test_factory_user_method(method_name: []const u8) bool {
        return std.ascii.eqlIgnoreCase(method_name, "createTestUser") or
            std.ascii.eqlIgnoreCase(method_name, "createMinAccessUser") or
            std.ascii.eqlIgnoreCase(method_name, "createMarketingUser");
    }

    fn create_test_factory_user(
        self: *Evaluator,
        method_name: []const u8,
        args: []const Value,
    ) !Value {
        const user = try self.arena.create(types.SObject);
        user.* = .{ .type_name = "User" };
        try user.fields.put(self.arena, "Name", Value{ .string = "Test User" });
        const user_id = try self.alloc_id();
        try user.fields.put(self.arena, "Id", Value{ .string = user_id });
        user.id = user_id;

        const profile = try self.arena.create(types.SObject);
        profile.* = .{ .type_name = "Profile" };
        if (std.ascii.eqlIgnoreCase(method_name, "createMinAccessUser")) {
            try profile.fields.put(
                self.arena,
                "Name",
                Value{ .string = "Minimum Access - Salesforce" },
            );
        } else if (std.ascii.eqlIgnoreCase(method_name, "createMarketingUser")) {
            try profile.fields.put(self.arena, "Name", Value{ .string = "Marketing User" });
        } else {
            try profile.fields.put(self.arena, "Name", Value{ .string = "Standard User" });
        }
        try user.fields.put(self.arena, "Profile", Value{ .sobject = profile });
        if (args.len >= 1 and args[0] == .boolean and args[0].boolean) {
            try self.insert_record(user);
        }
        return Value{ .sobject = user };
    }

    fn handle_test_data_helpers(
        self: *Evaluator,
        method_name: []const u8,
        args: []const Value,
    ) !?Value {
        if (self.user_class_has_method("TestDataHelpers", method_name, args)) return null;
        if (std.ascii.eqlIgnoreCase(method_name, "createAccount")) {
            return try self.create_test_data_account(args);
        }
        if (std.ascii.eqlIgnoreCase(method_name, "genXnumberOfAccounts")) {
            return try self.create_test_data_accounts(args);
        }
        if (std.ascii.eqlIgnoreCase(method_name, "genAccountWithOptions")) {
            return try self.create_test_data_account_with_options(args);
        }
        if (std.ascii.eqlIgnoreCase(method_name, "genContactForAccount")) {
            return try self.create_test_data_contact_for_account(args);
        }
        return null;
    }

    fn create_test_data_account(self: *Evaluator, args: []const Value) !Value {
        const acct = try self.arena.create(types.SObject);
        acct.* = .{ .type_name = "Account" };
        try acct.fields.put(self.arena, "Name", Value{ .string = "Awesome Test Account" });
        if (args.len >= 2 and args[1] == .string and args[1].string.len > 0) {
            try acct.fields.put(self.arena, "ShippingCountry", args[1]);
        }
        try self.insert_record(acct);
        return Value{ .sobject = acct };
    }

    fn create_test_data_accounts(self: *Evaluator, args: []const Value) !Value {
        const count = if (args.len >= 1 and args[0] == .integer) args[0].integer else 5;
        const list = try self.arena.create(types.ListValue);
        list.* = .{};
        var i: i64 = 0;
        while (i < count) : (i += 1) {
            const acct = try self.arena.create(types.SObject);
            acct.* = .{ .type_name = "Account" };
            const name = try std.fmt.allocPrint(self.arena, "Awesome Test Account {d}", .{i});
            try acct.fields.put(self.arena, "Name", Value{ .string = name });
            try list.items.append(self.arena, Value{ .sobject = acct });
        }
        return Value{ .list = list };
    }

    fn create_test_data_account_with_options(self: *Evaluator, args: []const Value) !Value {
        const acct = try self.arena.create(types.SObject);
        acct.* = .{ .type_name = "Account" };
        try acct.fields.put(self.arena, "Name", Value{ .string = "Awesome Test Account" });
        try acct.fields.put(self.arena, "ShippingStreet", Value{ .string = "123 Sessame St." });
        try acct.fields.put(self.arena, "ShippingCity", Value{ .string = "Wehawkin" });
        if (args.len >= 1 and args[0] == .boolean and args[0].boolean) {
            if (args.len >= 2 and args[1] == .string) {
                try acct.fields.put(self.arena, "ShippingCountry", args[1]);
            }
        }
        return Value{ .sobject = acct };
    }

    fn create_test_data_contact_for_account(self: *Evaluator, args: []const Value) !Value {
        const contact = try self.arena.create(types.SObject);
        contact.* = .{ .type_name = "Contact" };
        try contact.fields.put(self.arena, "LastName", Value{ .string = "Test Contact" });
        try contact.fields.put(self.arena, "Name", Value{ .string = "Test Contact" });
        if (args.len >= 1) {
            try contact.fields.put(self.arena, "AccountId", args[0]);
            try contact.fields.put(self.arena, "accountId", args[0]);
        }
        return Value{ .sobject = contact };
    }

    fn handle_test_helper(self: *Evaluator, method_name: []const u8, args: []const Value) ?Value {
        if (self.user_class_has_method("TestHelper", method_name, args)) return null;
        if (!std.ascii.eqlIgnoreCase(method_name, "getUnknownObjectType")) return null;
        if (args.len == 0) return Value{ .string = "null" };
        return Value{ .string = test_helper_value_type_name(args[0]) };
    }

    fn test_helper_value_type_name(value: Value) []const u8 {
        return switch (value) {
            .object => |object| object.class_name,
            .sobject => |sobject| sobject.type_name,
            .string => "String",
            .integer => "Integer",
            .long => "Long",
            .double => "Double",
            .boolean => "Boolean",
            .list => "List",
            .map => "Map",
            .set => "Set",
            .null_val => "null",
            .void_val => "void",
        };
    }

    fn user_class_has_method(
        self: *Evaluator,
        class_name: []const u8,
        method_name: []const u8,
        args: []const Value,
    ) bool {
        var class_iter = self.classes.iterator();
        while (class_iter.next()) |entry| {
            if (!std.ascii.eqlIgnoreCase(entry.key_ptr.*, class_name)) continue;
            if (self.find_best_method_in_class(
                entry.value_ptr.*,
                method_name,
                args,
            ) != null) return true;
        }
        return false;
    }

    /// Create a new instance of the named class and call a method on it.
    pub fn call_instance_method_by_name(
        self: *Evaluator,
        class_name: []const u8,
        method_name: []const u8,
        args: []const Value,
    ) anyerror!Value {
        const class_decl = self.find_class(class_name) orelse return Value.null_val;
        const instance = try self.arena.create(types.ObjectInstance);
        instance.* = .{ .class_name = class_name };
        // Run constructor if exists
        for (class_decl.members) |member| {
            switch (member) {
                .constructor_decl => |cd| {
                    if (cd.params.len == 0) {
                        const ctor_env = try self.global_env.child();
                        try ctor_env.define("this", Value{ .object = instance });
                        _ = self.exec_block(cd.body, ctor_env) catch {};
                        break;
                    }
                },
                else => {},
            }
        }
        return self.call_instance_method(class_decl, instance, method_name, args);
    }

    pub fn call_instance_method_public(
        self: *Evaluator,
        class_decl: *ast.ClassDecl,
        instance: *types.ObjectInstance,
        method_name: []const u8,
        args: []const Value,
    ) anyerror!Value {
        return self.call_instance_method(class_decl, instance, method_name, args);
    }

    pub fn resolve_full_class_name_public(self: *Evaluator, name: []const u8) []const u8 {
        return self.resolve_full_class_name(name);
    }

    pub fn handle_database_method_public(
        self: *Evaluator,
        method: []const u8,
        args: []const Value,
        env: *Env,
    ) anyerror!Value {
        return self.handle_database_method(method, args, env);
    }

    pub fn value_to_string_public(self: *Evaluator, value: Value) anyerror![]const u8 {
        return self.value_to_string(value);
    }

    pub fn value_hash_code_public(self: *Evaluator, value: Value) anyerror!i64 {
        return self.value_hash_code(value);
    }

    pub fn values_equal_public(self: *Evaluator, left: Value, right: Value) bool {
        return self.values_equal(left, right);
    }

    const ResolvedInstanceMethod = struct {
        owner: *ast.ClassDecl,
        method: *ast.MethodDecl,
    };

    fn value_to_string(self: *Evaluator, value: Value) anyerror![]const u8 {
        if (value == .null_val) return "null";

        if (value == .object) {
            if (value.object.fields.get("__stubProvider__") != null) {
                if (value.object.fields.get("__stubDisplayClassName__")) |display_name| {
                    if (display_name == .string) {
                        return try std.fmt.allocPrint(
                            self.arena,
                            "{s}:[instance]",
                            .{display_name.string},
                        );
                    }
                }
                return utils.coerce_to_string(value, self.arena);
            }
        }

        switch (value) {
            .object, .list, .map, .set, .sobject => {
                const result = self.eval_instance_method(
                    value,
                    "toString",
                    &.{},
                    self.global_env,
                ) catch return utils.coerce_to_string(value, self.arena);
                if (result == .string) return result.string;
            },
            else => {},
        }

        return utils.coerce_to_string(value, self.arena);
    }

    fn string_hash_code(_: *Evaluator, value: []const u8) i64 {
        var result: i32 = 0;
        for (value) |ch| {
            result = result *% 31 +% @as(i32, ch);
        }
        return @as(i64, result);
    }

    fn strict_values_equal(self: *Evaluator, left: Value, right: Value) bool {
        _ = self;
        if (left == .object and right == .object) return left.object == right.object;
        if (left == .sobject and right == .sobject) return left.sobject == right.sobject;
        if (left == .list and right == .list) return left.list == right.list;
        if (left == .map and right == .map) return left.map == right.map;
        if (left == .set and right == .set) return left.set == right.set;
        return utils.value_eql(left, right);
    }

    fn values_equal(self: *Evaluator, left: Value, right: Value) bool {
        if (left == .list and right == .list) {
            if (left.list == right.list) return true;
            if (left.list.items.items.len != right.list.items.items.len) return false;
            for (left.list.items.items, right.list.items.items) |left_item, right_item| {
                if (!self.values_equal(left_item, right_item)) return false;
            }
            return true;
        }

        if (left == .map and right == .map) {
            if (left.map == right.map) return true;
            if (left.map.entries.count() != right.map.entries.count()) return false;
            for (left.map.entries.keys(), left.map.entries.values()) |left_key, left_value| {
                const right_value = right.map.entries.get(left_key) orelse return false;
                if (!self.values_equal(left_value, right_value)) return false;
            }
            return true;
        }

        if (left == .set and right == .set) {
            if (left.set == right.set) return true;
            if (left.set.entries.count() != right.set.entries.count()) return false;
            outer: for (left.set.entries.values()) |left_item| {
                for (right.set.entries.values()) |right_item| {
                    if (self.values_equal(left_item, right_item)) continue :outer;
                }
                return false;
            }
            return true;
        }

        if (left == .object and right == .object) {
            if (self.objects_equal(left.object, right.object)) return true;
        }

        return utils.value_eql(left, right);
    }

    /// `values_equal` の ObjectInstance 比較部分。
    /// 1) pointer-identity / value_eql で同一判定、
    /// 2) Date / Datetime / Time / Blob の built-in value class は "value"
    ///    フィールドで比較、
    /// 3) ユーザ定義クラスが `equals(Object)` を持つ場合はそれを呼び出す。
    fn objects_equal(
        self: *Evaluator,
        left: *types.ObjectInstance,
        right: *types.ObjectInstance,
    ) bool {
        if (utils.value_eql(Value{ .object = left }, Value{ .object = right })) return true;

        // Built-in value classes (Date / Datetime / Time / Blob) compare by
        // their stored "value" rather than by ObjectInstance identity.
        const builtin_value_class = blk: {
            const cn = left.class_name;
            if (!std.ascii.eqlIgnoreCase(cn, right.class_name)) break :blk false;
            break :blk std.ascii.eqlIgnoreCase(cn, "Date") or
                std.ascii.eqlIgnoreCase(cn, "Datetime") or
                std.ascii.eqlIgnoreCase(cn, "Time") or
                std.ascii.eqlIgnoreCase(cn, "Blob");
        };
        if (builtin_value_class) {
            const lv = left.fields.get("value") orelse Value.null_val;
            const rv = right.fields.get("value") orelse Value.null_val;
            if (lv == .string and rv == .string) {
                return std.mem.eql(u8, lv.string, rv.string);
            }
        }

        const right_val = Value{ .object = right };
        const left_val = Value{ .object = left };
        if (self.find_class(left.class_name)) |left_class| {
            if (self.find_method_in_hierarchy_typed(
                null,
                left_class,
                "equals",
                &.{right_val},
            ) != null or
                self.find_method_in_hierarchy(null, left_class, "equals", 1) != null)
            {
                const result = self.call_instance_method(
                    left_class,
                    left,
                    "equals",
                    &.{right_val},
                ) catch return false;
                return result == .boolean and result.boolean;
            }
        }
        if (self.find_class(right.class_name)) |right_class| {
            if (self.find_method_in_hierarchy_typed(
                null,
                right_class,
                "equals",
                &.{left_val},
            ) != null or
                self.find_method_in_hierarchy(null, right_class, "equals", 1) != null)
            {
                const result = self.call_instance_method(
                    right_class,
                    right,
                    "equals",
                    &.{left_val},
                ) catch return false;
                return result == .boolean and result.boolean;
            }
        }
        return false;
    }

    fn value_hash_code(self: *Evaluator, value: Value) anyerror!i64 {
        return switch (value) {
            .null_val => 0,
            .boolean => |b| if (b) 1231 else 1237,
            .integer => |i| i,
            .long => |i| i,
            .double => |d| @intFromFloat(d),
            .string => |s| self.string_hash_code(s),
            .sobject => |sob| blk: {
                if (sob.id) |id| break :blk self.string_hash_code(id);
                const json = try utils.to_json(value, self.arena);
                break :blk self.string_hash_code(json);
            },
            .list => |list| blk: {
                var result: i64 = 1;
                for (list.items.items) |item| {
                    result = result *% 31 +% try self.value_hash_code(item);
                }
                break :blk result;
            },
            .map => |map| blk: {
                var result: i64 = 1;
                for (map.entries.keys(), map.entries.values()) |key, entry_value| {
                    result = result *% 31 +% self.string_hash_code(key);
                    result = result *% 31 +% try self.value_hash_code(entry_value);
                }
                break :blk result;
            },
            .set => |set| blk: {
                var result: i64 = 1;
                for (set.entries.values()) |item| {
                    result = result *% 31 +% try self.value_hash_code(item);
                }
                break :blk result;
            },
            .object => |obj| try self.object_hash_code(obj),
            .void_val => 0,
        };
    }

    /// `value_hash_code` の `.object` 分岐を抽出。
    /// 1) Type / Schema.SObjectType / SObjectField は `name` / `fieldName` の文字列ハッシュ、
    /// 2) Date / Datetime / Blob は `value` 文字列ハッシュ、
    /// 3) ユーザ定義 `hashCode()` があれば呼び出し、
    /// 4) いずれでもなければ pointer 下位ビットを `__hashCode__` にキャッシュして返す。
    fn object_hash_code(self: *Evaluator, obj: *types.ObjectInstance) !i64 {
        if (std.ascii.eqlIgnoreCase(obj.class_name, "Type") or
            std.ascii.eqlIgnoreCase(obj.class_name, "Schema.SObjectType") or
            std.ascii.eqlIgnoreCase(obj.class_name, "Schema.SObjectField") or
            std.ascii.eqlIgnoreCase(obj.class_name, "SObjectField"))
        {
            const name_value = obj.fields.get("name") orelse
                obj.fields.get("fieldName") orelse
                Value.null_val;
            if (name_value == .string) return self.string_hash_code(name_value.string);
        }

        if (std.ascii.eqlIgnoreCase(obj.class_name, "Date") or
            std.ascii.eqlIgnoreCase(obj.class_name, "Datetime") or
            std.ascii.eqlIgnoreCase(obj.class_name, "Blob"))
        {
            if (obj.fields.get("value")) |raw_value| {
                if (raw_value == .string) return self.string_hash_code(raw_value.string);
            }
        }

        if (self.find_class(obj.class_name)) |class_decl| {
            if (self.find_method_in_hierarchy_typed(
                null,
                class_decl,
                "hashCode",
                &.{},
            ) != null or
                self.find_method_in_hierarchy(null, class_decl, "hashCode", 0) != null)
            {
                const result = self.call_instance_method(
                    class_decl,
                    obj,
                    "hashCode",
                    &.{},
                ) catch Value{ .integer = 0 };
                switch (result) {
                    .integer => |i| return i,
                    .double => |d| return @intFromFloat(d),
                    else => {},
                }
            }
        }

        if (obj.fields.get("__hashCode__")) |existing| {
            if (existing == .integer) return existing.integer;
        }
        const generated = @as(i64, @intCast(@intFromPtr(obj) & 0x7fffffff));
        try obj.fields.put(self.arena, "__hashCode__", Value{ .integer = generated });
        return generated;
    }

    fn call_instance_method(
        self: *Evaluator,
        class_decl: *ast.ClassDecl,
        instance: *types.ObjectInstance,
        method_name: []const u8,
        args: []const Value,
    ) anyerror!Value {
        const actual_class = self.find_class(instance.class_name);
        return self.call_instance_method_resolved(
            class_decl,
            actual_class,
            instance,
            method_name,
            args,
        );
    }

    fn call_super_instance_method(
        self: *Evaluator,
        super_decl: *ast.ClassDecl,
        instance: *types.ObjectInstance,
        method_name: []const u8,
        args: []const Value,
    ) anyerror!Value {
        return self.call_instance_method_resolved(
            super_decl,
            null,
            instance,
            method_name,
            args,
        );
    }

    fn call_instance_method_resolved(
        self: *Evaluator,
        class_decl: *ast.ClassDecl,
        actual_class: ?*ast.ClassDecl,
        instance: *types.ObjectInstance,
        method_name: []const u8,
        args: []const Value,
    ) anyerror!Value {
        self.call_depth +|= 1;
        defer self.call_depth -|= 1;

        if (self.call_depth > self.max_call_depth) {
            return .null_val;
        }
        // Push call frame for stack trace generation (use current_call_line set by caller)
        const frame_line = self.current_call_line;
        self.current_call_line = 0;
        // Lazy static init for the instance's class and its parent hierarchy
        self.ensure_static_init(instance.class_name);
        self.ensure_static_init(class_decl.name);
        if (class_decl.super_class) |sc| self.ensure_static_init(sc.name);
        // For virtual dispatch: find method in instance's actual class first (child override),
        // then in the provided class_decl, then in parent classes.
        // `actual_class = null` is used for super.method() dispatch.
        const resolved = self.find_resolved_method_in_hierarchy_typed(
            actual_class,
            class_decl,
            method_name,
            args,
        ) orelse self.find_resolved_method_in_hierarchy(
            actual_class,
            class_decl,
            method_name,
            args.len,
        );

        if (resolved) |rm| {
            return self.call_resolved_instance_method(
                rm,
                instance,
                method_name,
                args,
                frame_line,
            );
        }
        // Try static method as fallback
        return self.call_method(class_decl.name, method_name, args);
    }

    fn call_resolved_instance_method(
        self: *Evaluator,
        resolved: ResolvedInstanceMethod,
        instance: *types.ObjectInstance,
        method_name: []const u8,
        args: []const Value,
        frame_line: u32,
    ) anyerror!Value {
        const owner_decl = resolved.owner;
        const method = resolved.method;
        const frame_class_name = instance_method_frame_class_name(
            instance.class_name,
            owner_decl.name,
        );
        try self.call_stack.append(self.arena, .{
            .class_name = frame_class_name,
            .method_name = method_name,
            .line = frame_line,
        });
        defer _ = self.call_stack.pop();

        const method_env = try self.prepare_instance_method_env(instance, method, args);
        const saved_class = self.current_class;
        self.current_class = owner_decl.name;
        defer self.current_class = saved_class;

        const batch_lifecycle = self.is_batch_lifecycle_method(owner_decl.name, method_name) or
            self.is_batch_lifecycle_method(instance.class_name, method_name);
        if (batch_lifecycle) self.batch_lifecycle_depth += 1;
        defer {
            if (batch_lifecycle) self.batch_lifecycle_depth -= 1;
        }

        const result = try self.exec_block(method.body, method_env);
        self.sync_method_this_to_instance(method_env, instance);
        sync_instance_fields_to_method_env(method_env, instance, method);
        return self.resolve_instance_method_result(result, method, owner_decl, instance);
    }

    fn instance_method_frame_class_name(
        instance_class_name: []const u8,
        owner_name: []const u8,
    ) []const u8 {
        if (std.mem.lastIndexOfScalar(u8, instance_class_name, '.')) |di| {
            if (std.ascii.eqlIgnoreCase(instance_class_name[di + 1 ..], owner_name)) {
                return instance_class_name;
            }
        }
        return owner_name;
    }

    fn prepare_instance_method_env(
        self: *Evaluator,
        instance: *types.ObjectInstance,
        method: *ast.MethodDecl,
        args: []const Value,
    ) anyerror!*Env {
        const method_env = try self.global_env.child();
        try method_env.define("this", Value{ .object = instance });
        for (instance.fields.keys(), instance.fields.values()) |k, v| {
            method_env.set(k, v) catch {
                try method_env.define(k, v);
            };
        }
        for (method.params, 0..) |param, i| {
            const val = if (i < args.len)
                try self.prepare_method_arg_value(args[i])
            else
                Value.null_val;
            const declared_type = self.render_type_ref(param.type_ref);
            try method_env.define_typed(
                param.name,
                self.annotate_declared_collection_type(val, declared_type),
                declared_type,
            );
        }
        return method_env;
    }

    fn sync_method_this_to_instance(
        self: *Evaluator,
        method_env: *Env,
        instance: *types.ObjectInstance,
    ) void {
        const this_val = method_env.get_this() orelse return;
        if (this_val != .object) return;
        const updated = this_val.object;
        if (updated == instance) return;
        for (updated.fields.keys(), updated.fields.values()) |k, v| {
            instance.fields.put(self.arena, k, v) catch {};
        }
    }

    fn sync_instance_fields_to_method_env(
        method_env: *Env,
        instance: *types.ObjectInstance,
        method: *ast.MethodDecl,
    ) void {
        for (instance.fields.keys(), instance.fields.values()) |fk, fv| {
            if (method_has_param_named(method, fk)) continue;
            method_env.set(fk, fv) catch {};
        }
    }

    fn method_has_param_named(method: *ast.MethodDecl, name: []const u8) bool {
        for (method.params) |p| {
            if (std.ascii.eqlIgnoreCase(p.name, name)) return true;
        }
        return false;
    }

    fn resolve_instance_method_result(
        self: *Evaluator,
        result: StmtResult,
        method: *ast.MethodDecl,
        owner_decl: *ast.ClassDecl,
        instance: *types.ObjectInstance,
    ) Value {
        if (result == .return_val) return result.return_val;
        if (method.return_type.name.len == 0 or
            std.ascii.eqlIgnoreCase(method.return_type.name, "void"))
            return self.return_value;
        if (std.ascii.eqlIgnoreCase(method.return_type.name, owner_decl.name) or
            std.ascii.eqlIgnoreCase(method.return_type.name, instance.class_name))
            return Value{ .object = instance };
        if (owner_decl.super_class) |sc| {
            if (std.ascii.eqlIgnoreCase(method.return_type.name, sc.name)) {
                return Value{ .object = instance };
            }
        }
        return self.return_value;
    }

    fn find_resolved_method_in_hierarchy_typed(
        self: *Evaluator,
        actual_class: ?*ast.ClassDecl,
        class_decl: *ast.ClassDecl,
        method_name: []const u8,
        args: []const Value,
    ) ?ResolvedInstanceMethod {
        const arg_type_hints = self.cast_type_hints;
        var best: ?ResolvedInstanceMethod = null;
        var best_score: i32 = -1;

        const considerOwner = struct {
            fn run(
                eval: *Evaluator,
                owner: *ast.ClassDecl,
                method_name_inner: []const u8,
                args_inner: []const Value,
                hints: ?[]const ?[]const u8,
                best_inner: *?ResolvedInstanceMethod,
                best_score_inner: *i32,
            ) void {
                for (owner.members) |member| {
                    switch (member) {
                        .method_decl => |md| {
                            if (!std.ascii.eqlIgnoreCase(md.name, method_name_inner) or
                                md.params.len != args_inner.len)
                            {
                                continue;
                            }
                            if (eval.single_method_candidate_score(md, args_inner, hints)) |score| {
                                if (best_inner.* == null or score > best_score_inner.*) {
                                    best_inner.* = .{ .owner = owner, .method = md };
                                    best_score_inner.* = score;
                                }
                            }
                        },
                        else => {},
                    }
                }
            }
        }.run;

        // Walk the runtime-type chain first so intermediate overrides are seen.
        if (actual_class) |ac| {
            var cur: ?*ast.ClassDecl = ac;
            while (cur) |cd| {
                considerOwner(self, cd, method_name, args, arg_type_hints, &best, &best_score);
                cur = if (cd.super_class) |sc| self.find_class(sc.name) else null;
            }
        }

        considerOwner(self, class_decl, method_name, args, arg_type_hints, &best, &best_score);

        var current: ?*ast.ClassDecl = class_decl;
        while (current) |cd| {
            if (cd.super_class) |sc| {
                const parent = self.find_class(sc.name) orelse break;
                considerOwner(self, parent, method_name, args, arg_type_hints, &best, &best_score);
                current = parent;
            } else break;
        }

        return best;
    }

    fn find_resolved_method_in_hierarchy(
        self: *Evaluator,
        actual_class: ?*ast.ClassDecl,
        class_decl: *ast.ClassDecl,
        method_name: []const u8,
        arg_count: usize,
    ) ?ResolvedInstanceMethod {
        // Walk the runtime-type chain first so intermediate overrides are seen.
        if (actual_class) |ac| {
            var cur: ?*ast.ClassDecl = ac;
            while (cur) |cd| {
                if (self.find_method_in_class(cd, method_name, arg_count)) |md| {
                    return .{ .owner = cd, .method = md };
                }
                cur = if (cd.super_class) |sc| self.find_class(sc.name) else null;
            }
        }
        if (self.find_method_in_class(class_decl, method_name, arg_count)) |md| {
            return .{ .owner = class_decl, .method = md };
        }
        var current: ?*ast.ClassDecl = class_decl;
        while (current) |cd| {
            if (cd.super_class) |sc| {
                const parent = self.find_class(sc.name);
                if (parent) |p| {
                    if (self.find_method_in_class(p, method_name, arg_count)) |md| {
                        return .{ .owner = p, .method = md };
                    }
                    current = p;
                } else break;
            } else break;
        }
        return null;
    }

    /// Type-aware version of findMethodInHierarchy. Walks the runtime (child)
    /// type chain first so intermediate overrides aren't skipped.
    fn find_method_in_hierarchy_typed(
        self: *Evaluator,
        actual_class: ?*ast.ClassDecl,
        class_decl: *ast.ClassDecl,
        method_name: []const u8,
        args: []const Value,
    ) ?*ast.MethodDecl {
        if (actual_class) |ac| {
            var cur: ?*ast.ClassDecl = ac;
            while (cur) |cd| {
                if (self.find_best_method_in_class(cd, method_name, args)) |md| {
                    return md;
                }
                cur = if (cd.super_class) |sc| self.find_class(sc.name) else null;
            }
        }
        if (self.find_best_method_in_class(class_decl, method_name, args)) |md| {
            return md;
        }
        var current: ?*ast.ClassDecl = class_decl;
        while (current) |cd| {
            if (cd.super_class) |sc| {
                const parent = self.find_class(sc.name);
                if (parent) |p| {
                    if (self.find_best_method_in_class(p, method_name, args)) |md| {
                        return md;
                    }
                    current = p;
                } else break;
            } else break;
        }
        return null;
    }

    /// Find a method in the class hierarchy. Searches:
    /// 1. The actual (child) class for overrides
    /// 2. The provided class_decl
    /// 3. Parent classes via super_class chain
    fn find_method_in_hierarchy(
        self: *Evaluator,
        actual_class: ?*ast.ClassDecl,
        class_decl: *ast.ClassDecl,
        method_name: []const u8,
        arg_count: usize,
    ) ?*ast.MethodDecl {
        // Virtual dispatch: walk the full runtime-type chain first (child overrides
        // may live at any intermediate ancestor, not just at the most-derived class).
        if (actual_class) |ac| {
            var cur: ?*ast.ClassDecl = ac;
            while (cur) |cd| {
                if (self.find_method_in_class(cd, method_name, arg_count)) |md| {
                    return md;
                }
                cur = if (cd.super_class) |sc| self.find_class(sc.name) else null;
            }
        }
        // Fallback: search from the statically-known declaring class upward
        // (used for super.method() dispatch or when the actual class isn't loaded).
        if (self.find_method_in_class(class_decl, method_name, arg_count)) |md| {
            return md;
        }
        var current: ?*ast.ClassDecl = class_decl;
        while (current) |cd| {
            if (cd.super_class) |sc| {
                const parent = self.find_class(sc.name);
                if (parent) |p| {
                    if (self.find_method_in_class(p, method_name, arg_count)) |md| {
                        return md;
                    }
                    current = p;
                } else break;
            } else break;
        }
        return null;
    }

    fn find_method_in_class(
        _: *Evaluator,
        class_decl: *ast.ClassDecl,
        method_name: []const u8,
        arg_count: usize,
    ) ?*ast.MethodDecl {
        for (class_decl.members) |member| {
            switch (member) {
                .method_decl => |md| {
                    if (std.ascii.eqlIgnoreCase(md.name, method_name)) {
                        if (md.params.len == arg_count) return md;
                    }
                },
                else => {},
            }
        }
        return null;
    }

    /// Type-aware method resolution filtered by static/instance.
    fn find_best_method_in_class_filtered(
        self: *Evaluator,
        class_decl: *ast.ClassDecl,
        method_name: []const u8,
        args: []const Value,
        static_only: bool,
    ) ?*ast.MethodDecl {
        var candidates: [64]*ast.MethodDecl = undefined;
        var count: usize = 0;
        var best_any: ?*ast.MethodDecl = null;

        for (class_decl.members) |member| {
            switch (member) {
                .method_decl => |md| {
                    if (std.ascii.eqlIgnoreCase(md.name, method_name) and
                        md.modifiers.is_static == static_only)
                    {
                        if (md.params.len == args.len) {
                            if (count < candidates.len) {
                                candidates[count] = md;
                                count += 1;
                            }
                        }
                        if (best_any == null) best_any = md;
                    }
                },
                else => {},
            }
        }

        if (count == 0) return if (best_any != null) best_any else null;
        if (count == 1) return candidates[0];

        const arg_type_hints = self.cast_type_hints;

        // Multiple candidates: score each by type compatibility
        var best: ?*ast.MethodDecl = null;
        var best_score: i32 = -1;
        for (candidates[0..count]) |md| {
            const score = self.filtered_method_candidate_score(md, args, arg_type_hints);
            if (score > best_score) {
                best_score = score;
                best = md;
            }
        }
        return best orelse candidates[0];
    }

    fn filtered_method_candidate_score(
        self: *Evaluator,
        method_decl: *ast.MethodDecl,
        args: []const Value,
        arg_type_hints: ?[]const ?[]const u8,
    ) i32 {
        var score: i32 = 0;
        for (method_decl.params, 0..) |param, i| {
            if (i >= args.len) break;
            const arg = args[i];
            const arg_hint = overload_arg_type_hint(arg_type_hints, i);
            if (arg_hint) |hint| {
                const hint_score = self.overload_score_for_type_hint(
                    hint,
                    self.render_type_ref(param.type_ref),
                );
                if (hint_score > 0) {
                    score += hint_score;
                    if (arg == .null_val) continue;
                }
            }
            var arg_score = overload_score_for_arg(arg, param.type_ref.name);
            if (arg_score == 0 and arg == .object) {
                if (self.is_subclass_of(arg.object.class_name, param.type_ref.name)) {
                    arg_score = 2;
                }
            }
            if (arg == .list and
                std.ascii.eqlIgnoreCase(param.type_ref.name, "List") and
                param.type_ref.params.len > 0)
            {
                arg_score = self.score_list_argument_for_param(arg.list, arg_hint, param.type_ref);
            }
            score += arg_score;
        }
        return score;
    }

    /// Type-aware method resolution for overloaded methods.
    /// When multiple methods match by name and arg count, picks the one
    /// whose parameter types best match the actual argument types.
    fn find_best_method_in_class(
        self: *Evaluator,
        class_decl: *ast.ClassDecl,
        method_name: []const u8,
        args: []const Value,
    ) ?*ast.MethodDecl {
        var candidates: [64]*ast.MethodDecl = undefined;
        var count: usize = 0;
        var best_any: ?*ast.MethodDecl = null;

        for (class_decl.members) |member| {
            switch (member) {
                .method_decl => |md| {
                    if (std.ascii.eqlIgnoreCase(md.name, method_name)) {
                        if (md.params.len == args.len) {
                            if (count < candidates.len) {
                                candidates[count] = md;
                                count += 1;
                            }
                        }
                        if (best_any == null) best_any = md;
                    }
                },
                else => {},
            }
        }

        if (count == 0) return best_any;
        if (count == 1) return candidates[0];

        // Multiple candidates: score each by type compatibility
        const arg_type_hints = self.cast_type_hints;
        var best: ?*ast.MethodDecl = null;
        var best_score: i32 = -1;
        for (candidates[0..count]) |md| {
            const score = self.score_overload_candidate(md, args, arg_type_hints);
            if (best == null or score > best_score) {
                best = md;
                best_score = score;
            }
        }
        return best orelse candidates[0];
    }

    /// `find_best_method_in_class` の内側ループを抽出したスコアリング helper。
    /// 1 つのオーバーロード候補について、引数列との型互換性スコアを返す。
    fn score_overload_candidate(
        self: *Evaluator,
        md: *ast.MethodDecl,
        args: []const Value,
        arg_type_hints: ?[]const ?[]const u8,
    ) i32 {
        var score: i32 = 0;
        for (md.params, 0..) |param, i| {
            if (i >= args.len) break;
            const pt = param.type_ref.name;
            const arg = args[i];
            const arg_hint = overload_arg_type_hint(arg_type_hints, i);
            if (arg_hint) |hint| {
                const hint_score = self.overload_score_for_type_hint(
                    hint,
                    self.render_type_ref(param.type_ref),
                );
                if (hint_score > 0) {
                    score += hint_score;
                    if (arg == .null_val) continue;
                }
            }
            // Score: higher is better match (with special cases for collection mismatches)
            if (arg == .sobject and std.ascii.eqlIgnoreCase(pt, "List")) {
                // SObject passed where List expected = poor match
                score -= 1;
            } else if (arg == .list and !std.ascii.eqlIgnoreCase(pt, "List")) {
                // List passed where non-List expected = poor match
                score -= 1;
            } else {
                var arg_score = overload_score_for_arg(arg, pt);
                if (arg_score == 0 and arg == .object) {
                    if (self.is_subclass_of(arg.object.class_name, pt)) {
                        arg_score = 2;
                    }
                }
                // List generic element type check
                if (arg == .list and
                    std.ascii.eqlIgnoreCase(pt, "List") and
                    param.type_ref.params.len > 0)
                {
                    arg_score = self.score_list_argument_for_param(
                        arg.list,
                        arg_hint,
                        param.type_ref,
                    );
                }
                score += arg_score;
            }
        }
        return score;
    }

    fn overload_arg_type_hint(hints: ?[]const ?[]const u8, index: usize) ?[]const u8 {
        if (hints == null or index >= hints.?.len) return null;
        return hints.?[index];
    }

    fn find_compatible_method_in_class(
        self: *Evaluator,
        class_decl: *ast.ClassDecl,
        method_name: []const u8,
        args: []const Value,
    ) ?*ast.MethodDecl {
        var candidates: [64]*ast.MethodDecl = undefined;
        var count: usize = 0;
        for (class_decl.members) |member| {
            switch (member) {
                .method_decl => |md| {
                    if (std.ascii.eqlIgnoreCase(md.name, method_name) and
                        md.params.len == args.len)
                    {
                        if (count < candidates.len) {
                            candidates[count] = md;
                            count += 1;
                        }
                    }
                },
                else => {},
            }
        }

        if (count == 0) return null;

        const arg_type_hints = self.cast_type_hints;
        var best: ?*ast.MethodDecl = null;
        var best_score: i32 = -1;
        for (candidates[0..count]) |md| {
            if (self.single_method_candidate_score(md, args, arg_type_hints)) |score| {
                if (best == null or score > best_score) {
                    best = md;
                    best_score = score;
                }
            }
        }
        return best;
    }

    fn single_method_candidate_score(
        self: *Evaluator,
        md: *ast.MethodDecl,
        args: []const Value,
        arg_type_hints: ?[]const ?[]const u8,
    ) ?i32 {
        var score: i32 = 0;
        for (md.params, 0..) |param, i| {
            if (i >= args.len) break;
            const arg = args[i];
            const rendered_param_type = self.render_type_ref(param.type_ref);
            const param_base = type_base_name(rendered_param_type);
            const arg_hint = overload_arg_type_hint(arg_type_hints, i);

            var enum_bridge = false;
            if (self.overload_hint_match(arg_hint, rendered_param_type, arg)) |hint_match| {
                score += hint_match.score;
                if (hint_match.null_match) continue;
                enum_bridge = hint_match.enum_bridge;
            }

            if (arg == .null_val) {
                const null_score = overload_score_for_null_arg(param_base);
                if (null_score <= 0) return null;
                score += null_score;
                continue;
            }

            const arg_score = self.single_method_arg_score(arg, param, arg_hint, param_base) orelse
                return null;

            if (arg_score <= 0) {
                // Without an enum bridge we reject; with one, the hint already
                // credited the match and we skip the argument score.
                if (enum_bridge) continue;
                return null;
            }
            score += arg_score;
        }
        return score;
    }

    fn single_method_arg_score(
        self: *Evaluator,
        arg: Value,
        param: ast.Param,
        arg_hint: ?[]const u8,
        param_base: []const u8,
    ) ?i32 {
        if (arg == .sobject and std.ascii.eqlIgnoreCase(param_base, "List")) return null;
        if (arg == .list) {
            if (std.ascii.eqlIgnoreCase(param_base, "List") or
                std.ascii.eqlIgnoreCase(param_base, "Iterable"))
            {
                return self.score_list_argument_for_param(arg.list, arg_hint, param.type_ref);
            }
            return if (std.ascii.eqlIgnoreCase(param_base, "Object")) 1 else null;
        }

        var arg_score = overload_score_for_arg(arg, param.type_ref.name);
        if (arg_score == 0 and arg == .string and std.ascii.eqlIgnoreCase(param_base, "Blob")) {
            arg_score = 1;
        }
        if (arg_score == 0 and
            arg == .object and
            self.is_subclass_of(arg.object.class_name, param.type_ref.name))
        {
            arg_score = 2;
        }
        return arg_score;
    }

    const OverloadHintMatch = struct {
        score: i32,
        enum_bridge: bool,
        null_match: bool,
    };

    fn overload_hint_match(
        self: *Evaluator,
        arg_hint: ?[]const u8,
        rendered_param_type: []const u8,
        arg: Value,
    ) ?OverloadHintMatch {
        const hint = arg_hint orelse return null;
        const hint_score = self.overload_score_for_type_hint(hint, rendered_param_type);
        if (hint_score <= 0) return null;
        return .{
            .score = hint_score,
            .enum_bridge = arg == .string and
                self.overload_param_accepts_enum_bridge(rendered_param_type),
            .null_match = arg == .null_val,
        };
    }

    fn overload_param_accepts_enum_bridge(
        self: *Evaluator,
        rendered_param_type: []const u8,
    ) bool {
        if (is_system_enum_type_name(rendered_param_type)) return true;
        const enum_name = if (std.mem.lastIndexOfScalar(u8, rendered_param_type, '.')) |di|
            rendered_param_type[di + 1 ..]
        else
            rendered_param_type;
        return self.find_visible_enum_decl(enum_name) != null;
    }

    /// If `expr` syntactically accesses an enum value (e.g. `SortOrder.ASCENDING`,
    /// `fflib_QueryFactory.SortOrder.ASCENDING`), return the enum type name for use
    /// as an overload-resolution type hint. Returns null otherwise.
    fn enum_access_type_name(self: *Evaluator, expr: *const ast.Expr) ?[]const u8 {
        if (expr.* != .field_access) return null;
        const fa = expr.field_access;
        // Direct identifier owner: SortOrder.ASCENDING (bare enum) — also handles
        // dotted identifiers the parser collapsed into a single name.
        if (fa.object.* == .identifier) {
            const owner_name = fa.object.identifier.name;
            if (self.find_visible_enum_decl(owner_name)) |ed| {
                for (ed.values) |v| {
                    if (std.ascii.eqlIgnoreCase(v, fa.field)) return ed.name;
                }
            }
            // Qualified identifier "Outer.Enum" that the parser did not split up.
            if (std.mem.lastIndexOfScalar(u8, owner_name, '.')) |di| {
                const outer_name = owner_name[0..di];
                const enum_name = owner_name[di + 1 ..];
                if (self.find_class(outer_name)) |cd| {
                    if (find_enum_in_class_members(cd, enum_name)) |ed| {
                        for (ed.values) |v| {
                            if (std.ascii.eqlIgnoreCase(v, fa.field)) return ed.name;
                        }
                    }
                }
            }
        }
        // Nested owner: ClassName.EnumName.VALUE
        if (fa.object.* == .field_access) {
            const inner = fa.object.field_access;
            if (inner.object.* == .identifier) {
                const outer_name = inner.object.identifier.name;
                const enum_name = inner.field;
                if (self.find_class(outer_name)) |cd| {
                    if (find_enum_in_class_members(cd, enum_name)) |ed| {
                        for (ed.values) |v| {
                            if (std.ascii.eqlIgnoreCase(v, fa.field)) return ed.name;
                        }
                    }
                }
            }
        }
        return null;
    }

    fn field_access_is_enum_value(self: *Evaluator, fa: *ast.FieldAccess) bool {
        if (fa.object.* != .identifier) return false;
        const owner_name = fa.object.identifier.name;
        const ed = self.find_visible_enum_decl(owner_name) orelse return false;
        for (ed.values) |value| {
            if (std.ascii.eqlIgnoreCase(value, fa.field)) return true;
        }
        return false;
    }

    fn find_enum_in_class_members(cd: *ast.ClassDecl, enum_name: []const u8) ?*ast.EnumDecl {
        for (cd.members) |member| {
            switch (member) {
                .enum_decl => |ed| {
                    if (std.ascii.eqlIgnoreCase(ed.name, enum_name)) return ed;
                },
                else => {},
            }
        }
        return null;
    }

    /// True when `arg_str` looks like a value of the enum type named by `param_type`.
    /// Handles both bare enum names ("SortOrder") and qualified forms
    /// ("fflib_QueryFactory.SortOrder").
    fn string_matches_enum_param_type(
        self: *Evaluator,
        arg_str: []const u8,
        param_type: []const u8,
    ) bool {
        if (arg_str.len == 0) return false;
        const simple = if (std.mem.lastIndexOfScalar(u8, param_type, '.')) |di|
            param_type[di + 1 ..]
        else
            param_type;
        if (simple.len == 0) return false;
        // System built-in enums (TriggerOperation, LoggingLevel, AccessType, etc.)
        if (is_system_enum_value(simple, arg_str)) return true;
        if (self.find_visible_enum_decl(simple)) |ed| {
            for (ed.values) |v| {
                if (std.ascii.eqlIgnoreCase(v, arg_str)) return true;
            }
        }
        // Also scan all classes for an enum member with this simple name.
        var iter = self.classes.iterator();
        while (iter.next()) |entry| {
            for (entry.value_ptr.*.members) |member| {
                switch (member) {
                    .enum_decl => |ed| {
                        if (std.ascii.eqlIgnoreCase(ed.name, simple)) {
                            for (ed.values) |v| {
                                if (std.ascii.eqlIgnoreCase(v, arg_str)) return true;
                            }
                        }
                    },
                    else => {},
                }
            }
        }
        return false;
    }

    fn overload_score_for_type_hint(
        self: *Evaluator,
        raw_hint: []const u8,
        raw_param_type: []const u8,
    ) i32 {
        if (std.ascii.eqlIgnoreCase(raw_hint, raw_param_type)) return 6;
        const hint = strip_type_namespace(raw_hint);
        const pt = strip_type_namespace(raw_param_type);
        const hint_base = type_base_name(hint);
        const pt_base = type_base_name(pt);
        const hint_has_generics = std.mem.indexOfScalar(u8, hint, '<') != null;
        const pt_has_generics = std.mem.indexOfScalar(u8, pt, '<') != null;
        if (std.ascii.eqlIgnoreCase(hint, pt)) return 3;
        if (hint_has_generics and pt_has_generics and
            self.generic_type_hint_matches_param(hint, pt, hint_base, pt_base))
            return 3;

        if (!(hint_has_generics and pt_has_generics) and
            std.ascii.eqlIgnoreCase(hint_base, pt_base))
        {
            return 3;
        }
        // Match dotted form against its simple tail (and vice versa) so that a
        // `ModeTarget2.Mode` declared-type hint scores against a bare `Mode`
        // parameter declaration. This is common when user code references an
        // inner enum from outside the declaring class.
        if (!(hint_has_generics and pt_has_generics)) {
            if (std.mem.lastIndexOfScalar(u8, hint_base, '.')) |di| {
                if (std.ascii.eqlIgnoreCase(hint_base[di + 1 ..], pt_base)) return 3;
            }
            if (std.mem.lastIndexOfScalar(u8, pt_base, '.')) |di| {
                if (std.ascii.eqlIgnoreCase(pt_base[di + 1 ..], hint_base)) return 3;
            }
        }
        if (std.ascii.eqlIgnoreCase(pt, "Object")) return 1;

        if (is_collection_type_name(hint_base)) {
            return self.collection_type_hint_score(
                hint,
                pt,
                hint_base,
                pt_base,
                hint_has_generics and pt_has_generics,
            );
        }

        if (self.s_object_type_hint_matches_param(hint_base, pt_base)) return 3;

        if (self.find_class(hint_base) != null and
            self.is_subclass_of(hint_base, pt_base))
        {
            return 2;
        }
        return 0;
    }

    fn generic_type_hint_matches_param(
        self: *Evaluator,
        hint: []const u8,
        param_type: []const u8,
        hint_base: []const u8,
        param_base: []const u8,
    ) bool {
        if (!std.ascii.eqlIgnoreCase(hint_base, param_base)) return false;
        if (std.ascii.eqlIgnoreCase(hint_base, "Map")) {
            return self.map_type_hint_matches_param(hint, param_type);
        }
        const hint_elem_type = extract_collection_element_type_name(hint) orelse return false;
        const param_elem_type =
            extract_collection_element_type_name(param_type) orelse return false;
        return self.element_type_hint_matches_param(hint_elem_type, param_elem_type);
    }

    fn collection_type_hint_score(
        self: *Evaluator,
        hint: []const u8,
        param_type: []const u8,
        hint_base: []const u8,
        param_base: []const u8,
        both_have_generics: bool,
    ) i32 {
        if (!std.ascii.eqlIgnoreCase(param_base, "Iterable")) return 0;
        if (both_have_generics) {
            const hint_elem_type = extract_collection_element_type_name(hint);
            const param_elem_type = extract_collection_element_type_name(param_type);
            if (hint_elem_type != null and
                param_elem_type != null and
                self.element_type_hint_matches_param(hint_elem_type.?, param_elem_type.?))
            {
                return if (std.ascii.eqlIgnoreCase(hint_base, "Set")) 4 else 3;
            }
        }
        if (std.ascii.eqlIgnoreCase(hint_base, "Set")) return 2;
        if (std.ascii.eqlIgnoreCase(hint_base, "List")) return 1;
        return 0;
    }

    fn s_object_type_hint_matches_param(
        self: *Evaluator,
        hint_base: []const u8,
        param_base: []const u8,
    ) bool {
        return self.is_s_object_type_name(hint_base) and
            std.ascii.eqlIgnoreCase(param_base, "SObject");
    }

    fn map_type_hint_matches_param(
        self: *Evaluator,
        hint: []const u8,
        param_type: []const u8,
    ) bool {
        const hint_args = extract_map_type_args(hint) orelse return false;
        const param_args = extract_map_type_args(param_type) orelse return false;
        const hint_key = strip_type_namespace(hint_args.key);
        const param_key = strip_type_namespace(param_args.key);
        if (!names_match_by_simple_name(hint_key, param_key)) return false;
        return self.element_type_hint_matches_param(hint_args.value, param_args.value);
    }

    fn element_type_hint_matches_param(
        self: *Evaluator,
        hint_elem_type: []const u8,
        param_elem_type: []const u8,
    ) bool {
        const hint_elem = strip_type_namespace(hint_elem_type);
        const param_elem = strip_type_namespace(param_elem_type);
        if (names_match_by_simple_name(hint_elem, param_elem)) return true;
        return std.ascii.eqlIgnoreCase(type_base_name(param_elem), "SObject") and
            self.is_s_object_type_name(type_base_name(hint_elem));
    }

    fn init_instance_fields(
        self: *Evaluator,
        class_decl: *ast.ClassDecl,
        instance: *types.ObjectInstance,
    ) !void {
        // Set current_class so that unqualified static field references (e.g. BASE_URL)
        // resolve to ClassName.BASE_URL in the global environment.
        const saved_class = self.current_class;
        self.current_class = class_decl.name;
        defer self.current_class = saved_class;

        const init_env = try self.global_env.child();
        try init_env.define("this", Value{ .object = instance });

        for (class_decl.members) |member| {
            switch (member) {
                .field_decl => |fd| {
                    if (!fd.modifiers.is_static) {
                        const val = if (fd.initializer) |init_expr|
                            self.eval_expr(init_expr, init_env) catch Value.null_val
                        else
                            default_value(fd.type_ref);
                        try instance.fields.put(self.arena, fd.name, val);
                        init_env.set(fd.name, val) catch {
                            try init_env.define(fd.name, val);
                        };
                    }
                },
                else => {},
            }
        }
    }

    fn class_has_no_arg_ctor(class_decl: *ast.ClassDecl) bool {
        var has_any_ctor = false;
        for (class_decl.members) |member| {
            switch (member) {
                .constructor_decl => |cd| {
                    has_any_ctor = true;
                    if (cd.params.len == 0) return true;
                },
                else => {},
            }
        }
        // No explicit constructors ⇒ synthetic no-arg default exists.
        return !has_any_ctor;
    }

    fn ctor_starts_with_super_or_this(cd: *ast.ConstructorDecl) bool {
        if (cd.body.len == 0) return false;
        const first = cd.body[0];
        if (first != .expr_stmt) return false;
        const e = first.expr_stmt;
        if (e.* != .call) return false;
        const callee = e.call.callee;
        return std.mem.eql(u8, callee, "super") or std.mem.eql(u8, callee, "this");
    }

    fn find_matching_constructor(
        self: *Evaluator,
        class_decl: *ast.ClassDecl,
        args: []const Value,
    ) ?*ast.ConstructorDecl {
        var candidates: [8]*ast.ConstructorDecl = undefined;
        var count: usize = 0;
        for (class_decl.members) |member| {
            switch (member) {
                .constructor_decl => |cd| {
                    if (cd.params.len == args.len and count < candidates.len) {
                        candidates[count] = cd;
                        count += 1;
                    }
                },
                else => {},
            }
        }
        if (count == 0) return null;
        if (count == 1) return candidates[0];
        var best: ?*ast.ConstructorDecl = null;
        var best_score: i32 = -1;
        for (candidates[0..count]) |cd| {
            var score: i32 = 0;
            for (cd.params, 0..) |param, i| {
                if (i >= args.len) break;
                const pt = param.type_ref.name;
                const arg = args[i];
                if (arg == .string and
                    (std.ascii.eqlIgnoreCase(pt, "String") or
                        std.ascii.eqlIgnoreCase(pt, "Id")))
                {
                    score += 2;
                } else if (arg == .integer and
                    (std.ascii.eqlIgnoreCase(pt, "Integer") or
                        std.ascii.eqlIgnoreCase(pt, "int")))
                {
                    score += 2;
                } else if (arg == .boolean and std.ascii.eqlIgnoreCase(pt, "Boolean")) {
                    score += 2;
                } else if (arg == .object) {
                    if (std.ascii.eqlIgnoreCase(arg.object.class_name, pt)) {
                        score += 3;
                    } else if (self.is_subclass_of(arg.object.class_name, pt)) {
                        score += 2;
                    }
                } else if (arg == .list and std.ascii.eqlIgnoreCase(pt, "List")) {
                    score += 2;
                }
            }
            if (best == null or score > best_score) {
                best = cd;
                best_score = score;
            }
        }
        return best;
    }

    const ConstructorCandidateSet = struct {
        candidates: [8]*ast.ConstructorDecl = undefined,
        count: usize = 0,
        best_any: ?*ast.ConstructorDecl = null,
    };

    fn run_constructor(
        self: *Evaluator,
        class_decl: *ast.ClassDecl,
        instance: *types.ObjectInstance,
        args: []const Value,
    ) anyerror!void {
        const chosen = self.choose_constructor_for_run(class_decl, args) orelse return;
        try self.execute_constructor_body(class_decl, instance, chosen, args);
    }

    fn choose_constructor_for_run(
        self: *Evaluator,
        class_decl: *ast.ClassDecl,
        args: []const Value,
    ) ?*ast.ConstructorDecl {
        const candidates = collect_constructor_candidates(class_decl, args);
        if (candidates.count == 0) return candidates.best_any;
        if (candidates.count == 1) return candidates.candidates[0];
        return self.choose_best_constructor(candidates.candidates[0..candidates.count], args);
    }

    fn collect_constructor_candidates(
        class_decl: *ast.ClassDecl,
        args: []const Value,
    ) ConstructorCandidateSet {
        var result: ConstructorCandidateSet = .{};
        for (class_decl.members) |member| {
            switch (member) {
                .constructor_decl => |cd| {
                    if (cd.params.len == args.len and result.count < result.candidates.len) {
                        result.candidates[result.count] = cd;
                        result.count += 1;
                    }
                    if (result.best_any == null and (cd.params.len == args.len or args.len == 0)) {
                        result.best_any = cd;
                    }
                },
                else => {},
            }
        }
        return result;
    }

    fn choose_best_constructor(
        self: *Evaluator,
        candidates: []const *ast.ConstructorDecl,
        args: []const Value,
    ) ?*ast.ConstructorDecl {
        const arg_type_hints = self.cast_type_hints;
        var best: ?*ast.ConstructorDecl = null;
        var best_score: i32 = -1;
        for (candidates) |cd| {
            const score = self.score_constructor_candidate(cd, args, arg_type_hints);
            if (best == null or score > best_score) {
                best = cd;
                best_score = score;
            }
        }
        return best;
    }

    fn score_constructor_candidate(
        self: *Evaluator,
        cd: *ast.ConstructorDecl,
        args: []const Value,
        arg_type_hints: ?[]const ?[]const u8,
    ) i32 {
        var score: i32 = 0;
        for (cd.params, 0..) |param, i| {
            if (i >= args.len) break;
            const arg_hint = if (arg_type_hints != null and i < arg_type_hints.?.len)
                arg_type_hints.?[i]
            else
                null;
            score += self.score_constructor_arg(args[i], param, arg_hint);
        }
        return score;
    }

    fn score_constructor_arg(
        self: *Evaluator,
        arg: Value,
        param: ast.Param,
        arg_hint: ?[]const u8,
    ) i32 {
        const pt = param.type_ref.name;
        var score: i32 = 0;
        if (arg_hint) |hint| {
            const rendered_type = self.render_type_ref(param.type_ref);
            const hint_score = self.overload_score_for_type_hint(hint, rendered_type);
            if (hint_score > 0) score += hint_score;
        }
        if (arg == .string and
            (std.ascii.eqlIgnoreCase(pt, "String") or std.ascii.eqlIgnoreCase(pt, "Id")))
            return score + 2;
        if (arg == .integer and
            (std.ascii.eqlIgnoreCase(pt, "Integer") or std.ascii.eqlIgnoreCase(pt, "int")))
            return score + 2;
        if (arg == .long and std.ascii.eqlIgnoreCase(pt, "Long")) return score + 2;
        if (arg == .boolean and std.ascii.eqlIgnoreCase(pt, "Boolean")) return score + 2;
        if (arg == .object and std.mem.endsWith(u8, pt, "Exception")) return score + 2;
        if (arg == .object) return score + self.score_constructor_object_arg(arg.object, pt);
        if (arg == .list and std.ascii.eqlIgnoreCase(pt, "List")) return score + 2;
        if (arg == .sobject) return score + score_constructor_sobject_arg(arg.sobject, pt);
        if (arg == .null_val) return score + score_constructor_null_arg(pt);
        return score;
    }

    fn score_constructor_object_arg(
        self: *Evaluator,
        obj: *types.ObjectInstance,
        param_type: []const u8,
    ) i32 {
        if (std.ascii.eqlIgnoreCase(obj.class_name, param_type)) return 3;
        if (self.is_subclass_of(obj.class_name, param_type)) return 2;
        return 0;
    }

    fn score_constructor_sobject_arg(sob: *types.SObject, param_type: []const u8) i32 {
        const arg_type = sob.type_name;
        if (std.ascii.eqlIgnoreCase(arg_type, param_type)) return 4;
        if (std.mem.lastIndexOfScalar(u8, param_type, '.')) |di| {
            if (std.ascii.eqlIgnoreCase(arg_type, param_type[di + 1 ..])) return 4;
            if (is_constructor_sobject_param(param_type)) return 2;
        } else if (is_constructor_sobject_param(param_type)) {
            return 2;
        }
        return 0;
    }

    fn is_constructor_sobject_param(param_type: []const u8) bool {
        return std.ascii.eqlIgnoreCase(param_type, "SObject");
    }

    fn score_constructor_null_arg(param_type: []const u8) i32 {
        if (std.ascii.eqlIgnoreCase(param_type, "String") or
            std.ascii.eqlIgnoreCase(param_type, "Id"))
            return 2;
        if (std.mem.endsWith(u8, param_type, "Exception")) return 0;
        return 1;
    }

    fn execute_constructor_body(
        self: *Evaluator,
        class_decl: *ast.ClassDecl,
        instance: *types.ObjectInstance,
        cd: *ast.ConstructorDecl,
        args: []const Value,
    ) anyerror!void {
        const ctor_env = try self.prepare_constructor_env(instance, cd, args);
        const ctor_line = self.consume_constructor_call_line(cd);
        const frame_class_name = constructor_frame_class_name(instance.class_name, class_decl.name);
        try self.call_stack.append(self.arena, .{
            .class_name = frame_class_name,
            .method_name = "<init>",
            .line = ctor_line,
        });
        defer _ = self.call_stack.pop();

        const saved_ctor_class = self.current_constructor_class;
        self.current_constructor_class = frame_class_name;
        defer self.current_constructor_class = saved_ctor_class;

        const saved_class = self.current_class;
        self.current_class = frame_class_name;
        defer self.current_class = saved_class;

        _ = try self.exec_block(cd.body, ctor_env);
    }

    fn prepare_constructor_env(
        self: *Evaluator,
        instance: *types.ObjectInstance,
        cd: *ast.ConstructorDecl,
        args: []const Value,
    ) anyerror!*Env {
        const ctor_env = try self.global_env.child();
        try ctor_env.define("this", Value{ .object = instance });
        for (instance.fields.keys(), instance.fields.values()) |k, v| {
            ctor_env.set(k, v) catch {
                try ctor_env.define(k, v);
            };
        }
        for (cd.params, 0..) |param, pi| {
            const pval = if (pi < args.len) args[pi] else Value.null_val;
            const declared_type = self.render_type_ref(param.type_ref);
            try ctor_env.define_typed(
                param.name,
                self.annotate_declared_collection_type(pval, declared_type),
                declared_type,
            );
        }
        return ctor_env;
    }

    fn consume_constructor_call_line(self: *Evaluator, cd: *ast.ConstructorDecl) u32 {
        const ctor_line = if (self.current_call_line > 0)
            self.current_call_line
        else if (cd.loc.line > 0)
            cd.loc.line
        else
            1;
        self.current_call_line = 0;
        return ctor_line;
    }

    fn constructor_frame_class_name(
        instance_class_name: []const u8,
        class_name: []const u8,
    ) []const u8 {
        if (std.mem.lastIndexOfScalar(u8, instance_class_name, '.')) |di| {
            if (std.ascii.eqlIgnoreCase(instance_class_name[di + 1 ..], class_name)) {
                return instance_class_name;
            }
        }
        return class_name;
    }

    fn is_instance_field(
        _: *Evaluator,
        class_decl: *ast.ClassDecl,
        name: []const u8,
    ) bool {
        for (class_decl.members) |member| {
            switch (member) {
                .field_decl => |fd| {
                    if (!fd.modifiers.is_static and
                        std.ascii.eqlIgnoreCase(fd.name, name))
                    {
                        return true;
                    }
                },
                else => {},
            }
        }
        return false;
    }

    const FieldLookup = struct {
        owner_name: []const u8,
        field_decl: *ast.FieldDecl,
    };

    fn find_field_decl_with_owner(
        self: *Evaluator,
        class_name: []const u8,
        field_name: []const u8,
    ) ?FieldLookup {
        var current = self.find_class(class_name);
        while (current) |cd| {
            for (cd.members) |member| {
                switch (member) {
                    .field_decl => |fd| {
                        if (std.ascii.eqlIgnoreCase(fd.name, field_name)) {
                            return .{ .owner_name = cd.name, .field_decl = fd };
                        }
                    },
                    else => {},
                }
            }
            current = if (cd.super_class) |sc| self.find_class(sc.name) else null;
        }
        return null;
    }

    fn read_static_backing_value(
        self: *Evaluator,
        owner_name: []const u8,
        field_name: []const u8,
    ) Value {
        self.ensure_static_init(owner_name);
        const key = std.fmt.allocPrint(
            self.arena,
            "{s}.{s}",
            .{ owner_name, field_name },
        ) catch return .null_val;
        if (self.global_env.get(key)) |v| return v;
        if (self.find_outer_class_name(owner_name)) |outer| {
            const outer_key = std.fmt.allocPrint(
                self.arena,
                "{s}.{s}",
                .{ outer, field_name },
            ) catch return .null_val;
            if (self.global_env.get(outer_key)) |v| return v;
        }
        return .null_val;
    }

    fn is_parent_instance_field(
        self: *Evaluator,
        class_decl: *ast.ClassDecl,
        name: []const u8,
    ) bool {
        if (class_decl.super_class) |sc| {
            if (self.find_class(sc.name)) |parent| {
                if (self.is_instance_field(parent, name)) return true;
                return self.is_parent_instance_field(parent, name);
            }
        }
        return false;
    }

    pub fn find_class_public(self: *Evaluator, name: []const u8) ?*ast.ClassDecl {
        return self.find_class(name);
    }

    pub fn instantiate_class_public(self: *Evaluator, class_name: []const u8) !Value {
        return self.instantiate_class(class_name);
    }

    /// True for a bare SObject simple name (e.g. "Account", "MyObject__c").
    /// Public wrapper around the internal `isSObjectTypeName` used by builtin dispatch.
    pub fn is_s_object_type_name_public(self: *Evaluator, name: []const u8) bool {
        return self.is_s_object_type_name(name);
    }

    /// Returns true when `name` matches an interface declaration loaded from the source
    /// set, including inner interfaces declared as `Outer.Inner`. Used by the cast path
    /// to decide whether to throw TypeException for a failed interface cast.
    fn is_known_interface_name(self: *Evaluator, name: []const u8) bool {
        if (name.len == 0) return false;
        // Top-level interface?
        var iter = self.classes.iterator();
        while (iter.next()) |entry| {
            const cd = entry.value_ptr.*;
            for (cd.members) |member| {
                switch (member) {
                    .interface_decl => |iface| {
                        // Match either "Outer.Inner" or just "Inner"
                        if (std.ascii.eqlIgnoreCase(iface.name, name)) return true;
                        if (std.mem.lastIndexOfScalar(u8, name, '.')) |di| {
                            if (std.ascii.eqlIgnoreCase(name[0..di], entry.key_ptr.*) and
                                std.ascii.eqlIgnoreCase(name[di + 1 ..], iface.name))
                            {
                                return true;
                            }
                        }
                    },
                    else => {},
                }
            }
        }
        return false;
    }

    fn find_class(self: *Evaluator, name: []const u8) ?*ast.ClassDecl {
        var iter = self.classes.iterator();
        while (iter.next()) |entry| {
            if (std.ascii.eqlIgnoreCase(entry.key_ptr.*, name)) return entry.value_ptr.*;
        }
        return null;
    }

    pub fn build_class_lookup_cache(self: *Evaluator, alloc: std.mem.Allocator) !void {
        if (self.class_lookup_cache_built) return;
        var iter = self.classes.iterator();
        while (iter.next()) |entry| {
            const outer_name = entry.key_ptr.*;
            if (std.mem.indexOfScalar(u8, outer_name, '.') != null) continue;
            for (entry.value_ptr.*.members) |member| {
                switch (member) {
                    .class_decl => |inner_cd| {
                        try self.put_outer_class_cache_entry(alloc, inner_cd.name, outer_name);
                        const fq = try std.fmt.allocPrint(
                            alloc,
                            "{s}.{s}",
                            .{ outer_name, inner_cd.name },
                        );
                        try self.put_outer_class_cache_entry(alloc, fq, outer_name);
                    },
                    else => {},
                }
            }
        }
        self.class_lookup_cache_built = true;
    }

    fn put_outer_class_cache_entry(
        self: *Evaluator,
        alloc: std.mem.Allocator,
        name: []const u8,
        outer_name: []const u8,
    ) !void {
        const key = try ascii_lower_alloc(alloc, name);
        const gop = try self.outer_class_by_inner_name.getOrPut(alloc, key);
        if (gop.found_existing) {
            alloc.free(key);
            return;
        }
        gop.value_ptr.* = outer_name;
    }

    /// Find the outer (enclosing) class name for a given inner class.
    /// Returns null if the class is not an inner class.
    /// Accepts either simple inner class name ("Inner") or FQ form ("Outer.Inner");
    /// when FQ is passed and the prefix matches an outer class, returns it directly.
    fn find_outer_class_name(self: *Evaluator, inner_class_name: []const u8) ?[]const u8 {
        var stack_buf: [256]u8 = undefined;
        if (inner_class_name.len <= stack_buf.len) {
            const key = ascii_lower_into(stack_buf[0..], inner_class_name);
            if (self.outer_class_by_inner_name.get(key)) |outer_name| return outer_name;
        } else {
            const key = ascii_lower_alloc(self.arena, inner_class_name) catch return null;
            defer self.arena.free(key);

            if (self.outer_class_by_inner_name.get(key)) |outer_name| return outer_name;
        }
        if (self.class_lookup_cache_built) return null;

        // Fallback preserves direct Evaluator tests and any caller that registers
        // classes without first building the lookup cache.
        if (std.mem.lastIndexOfScalar(u8, inner_class_name, '.')) |di| {
            const outer = inner_class_name[0..di];
            if (self.find_class(outer)) |_| return outer;
        }
        const simple = if (std.mem.lastIndexOfScalar(u8, inner_class_name, '.')) |di|
            inner_class_name[di + 1 ..]
        else
            inner_class_name;
        var iter = self.classes.iterator();
        while (iter.next()) |entry| {
            if (std.mem.indexOfScalar(u8, entry.key_ptr.*, '.') != null) continue;
            for (entry.value_ptr.*.members) |member| {
                switch (member) {
                    .class_decl => |inner_cd| {
                        if (std.ascii.eqlIgnoreCase(inner_cd.name, simple))
                            return entry.key_ptr.*;
                    },
                    else => {},
                }
            }
        }
        return null;
    }

    fn register_class_recursive(
        self: *Evaluator,
        ca: std.mem.Allocator,
        cd: *ast.ClassDecl,
        fq_name: ?[]const u8,
    ) !void {
        try self.classes.put(ca, cd.name, cd);
        if (fq_name) |fq| {
            try self.classes.put(ca, fq, cd);
        }
        for (cd.members) |member| {
            switch (member) {
                .field_decl => |fd| {
                    if (fd.modifiers.is_static) {
                        const key = std.fmt.allocPrint(
                            self.arena,
                            "{s}.{s}",
                            .{ cd.name, fd.name },
                        ) catch continue;
                        self.global_env.define(key, default_value(fd.type_ref)) catch {};
                    }
                },
                .class_decl => |inner_cd| {
                    const parent_name = fq_name orelse cd.name;
                    const inner_fq = std.fmt.allocPrint(
                        ca,
                        "{s}.{s}",
                        .{ parent_name, inner_cd.name },
                    ) catch continue;
                    try self.register_class_recursive(ca, inner_cd, inner_fq);
                },
                .enum_decl => |ed| {
                    for (ed.values) |v| {
                        const ekey = std.fmt.allocPrint(
                            self.arena,
                            "{s}.{s}",
                            .{ ed.name, v },
                        ) catch continue;
                        self.global_env.define(ekey, Value{ .string = v }) catch {};
                        const enum_owner = fq_name orelse cd.name;
                        const fq_key = std.fmt.allocPrint(
                            self.arena,
                            "{s}.{s}.{s}",
                            .{ enum_owner, ed.name, v },
                        ) catch continue;
                        self.global_env.define(fq_key, Value{ .string = v }) catch {};
                    }
                },
                else => {},
            }
        }
    }

    fn create_async_apex_job(
        self: *Evaluator,
        apex_job_type: []const u8,
        class_name: []const u8,
        method_name: ?[]const u8,
    ) ![]const u8 {
        const job_id = try std.fmt.allocPrint(self.arena, "707{d:0>15}", .{self.next_id});
        self.next_id += 1;

        const top_level_class = self.find_outer_class_name(class_name) orelse class_name;
        const apex_class_name = if (std.mem.lastIndexOfScalar(u8, top_level_class, '.')) |di|
            top_level_class[di + 1 ..]
        else
            top_level_class;
        const apex_class = try self.arena.create(types.SObject);
        apex_class.* = .{ .type_name = "ApexClass" };
        const generated_apex_class_id = try std.fmt.allocPrint(
            self.arena,
            "01p{d:0>15}",
            .{self.next_id},
        );
        try apex_class.fields.put(
            self.arena,
            "Id",
            Value{ .string = generated_apex_class_id },
        );
        try apex_class.fields.put(self.arena, "Name", Value{ .string = apex_class_name });
        try apex_class.fields.put(self.arena, "NamespacePrefix", Value.null_val);

        const async_job = try self.arena.create(types.SObject);
        async_job.* = .{ .type_name = "AsyncApexJob", .id = job_id };
        try async_job.fields.put(self.arena, "Id", Value{ .string = job_id });
        try async_job.fields.put(self.arena, "Status", Value{ .string = "Completed" });
        try async_job.fields.put(self.arena, "JobType", Value{ .string = apex_job_type });
        try async_job.fields.put(
            self.arena,
            "MethodName",
            if (method_name) |name| Value{ .string = name } else Value.null_val,
        );
        try async_job.fields.put(self.arena, "JobItemsProcessed", Value{ .integer = 0 });
        try async_job.fields.put(self.arena, "NumberOfErrors", Value{ .integer = 0 });
        try async_job.fields.put(self.arena, "ApexClass", Value{ .sobject = apex_class });
        if (utils.sobject_get(&apex_class.fields, "Id")) |apex_class_id| {
            try async_job.fields.put(self.arena, "ApexClassId", apex_class_id);
        }
        try async_job.fields.put(
            self.arena,
            "CreatedById",
            Value{ .string = self.current_user_id },
        );
        const created_by = try self.create_current_user_record();
        if (created_by == .sobject) {
            try async_job.fields.put(self.arena, "CreatedBy", created_by);
        }
        const now_str =
            builtins.current_date_time_string(self.arena) catch "2026-01-01T00:00:00Z";
        try async_job.fields.put(self.arena, "CreatedDate", Value{ .string = now_str });

        const gop = try self.store.getOrPut(self.arena, "AsyncApexJob");
        if (!gop.found_existing) gop.value_ptr.* = .empty;
        try gop.value_ptr.append(self.arena, Value{ .sobject = async_job });
        try self.id_type_map.put(self.arena, job_id, "AsyncApexJob");
        return job_id;
    }

    fn update_async_apex_job(
        self: *Evaluator,
        job_id: []const u8,
        status: []const u8,
        number_of_errors: i64,
    ) void {
        const jobs = self.store.getPtr("AsyncApexJob") orelse return;
        for (jobs.items) |item| {
            if (item != .sobject or item.sobject.id == null) continue;
            if (!std.ascii.eqlIgnoreCase(item.sobject.id.?, job_id)) continue;
            item.sobject.fields.put(self.arena, "Status", Value{ .string = status }) catch {};
            item.sobject.fields.put(
                self.arena,
                "NumberOfErrors",
                Value{ .integer = number_of_errors },
            ) catch {};
            break;
        }
    }

    fn build_batchable_context(
        self: *Evaluator,
        job_id: []const u8,
        child_job_id: ?[]const u8,
    ) !Value {
        const ctx = try self.arena.create(types.ObjectInstance);
        ctx.* = .{ .class_name = "Database.BatchableContext" };
        try ctx.fields.put(self.arena, "JobId", Value{ .string = job_id });
        try ctx.fields.put(
            self.arena,
            "ChildJobId",
            if (child_job_id) |child| Value{ .string = child } else Value.null_val,
        );
        return Value{ .object = ctx };
    }

    fn build_queueable_context(self: *Evaluator, job_id: []const u8) !Value {
        const ctx = try self.arena.create(types.ObjectInstance);
        ctx.* = .{ .class_name = "System.QueueableContext" };
        try ctx.fields.put(self.arena, "JobId", Value{ .string = job_id });
        return Value{ .object = ctx };
    }

    fn build_finalizer_context(
        self: *Evaluator,
        job_id: []const u8,
        exception_value: ?Value,
    ) !Value {
        const ctx = try self.arena.create(types.ObjectInstance);
        ctx.* = .{ .class_name = "System.FinalizerContext" };
        try ctx.fields.put(self.arena, "AsyncApexJobId", Value{ .string = job_id });
        try ctx.fields.put(self.arena, "Exception", exception_value orelse Value.null_val);
        try ctx.fields.put(
            self.arena,
            "Result",
            Value{ .string = if (exception_value == null) "SUCCESS" else "UNHANDLED_EXCEPTION" },
        );
        try ctx.fields.put(self.arena, "RequestId", Value{ .string = "4eR000000000001" });
        return Value{ .object = ctx };
    }

    fn publish_batch_apex_error_event(
        self: *Evaluator,
        batch_obj: *types.ObjectInstance,
        job_id: []const u8,
        phase: []const u8,
        exception_value: Value,
    ) !void {
        const raises_platform_events = self.class_implements_interface(
            batch_obj.class_name,
            "Database.RaisesPlatformEvents",
        );
        const raises_events = raises_platform_events or
            self.class_implements_interface(batch_obj.class_name, "RaisesPlatformEvents");
        if (!raises_events) {
            return;
        }

        const evt = try self.arena.create(types.SObject);
        evt.* = .{ .type_name = "BatchApexErrorEvent" };
        try evt.fields.put(self.arena, "AsyncApexJobId", Value{ .string = job_id });
        try evt.fields.put(self.arena, "Phase", Value{ .string = phase });

        var message_value: Value = Value.null_val;
        var exception_type: []const u8 = "System.Exception";
        var stack_trace: []const u8 = "stacktrace";
        switch (exception_value) {
            .object => |obj| {
                message_value = obj.fields.get("message") orelse Value.null_val;
                exception_type = try self.qualify_builtin_exception_type(obj.class_name);
                if (obj.fields.get("stackTraceString")) |stack_val| {
                    if (stack_val == .string and stack_val.string.len > 0) {
                        stack_trace = stack_val.string;
                    }
                }
            },
            .string => |s| {
                message_value = Value{ .string = s };
            },
            else => {
                const message = try utils.coerce_to_string(exception_value, self.arena);
                message_value = Value{ .string = message };
            },
        }
        try evt.fields.put(self.arena, "ExceptionType", Value{ .string = exception_type });
        try evt.fields.put(self.arena, "Message", message_value);
        try evt.fields.put(self.arena, "StackTrace", Value{ .string = stack_trace });
        _ = self.call_method("EventBus", "publish", &.{Value{ .sobject = evt }}) catch {};
    }

    /// Apex の非限定例外クラス名 (`DmlException`, `NullPointerException` ...)
    /// が渡されたら `System.<name>` に upgrade して返す。既に `.` を含んで
    /// いる、あるいは列挙に含まれない名前はそのまま返す。
    /// `publish_batch_apex_error_event` と同等の exception 名正規化を他でも
    /// 使えるよう切り出した。
    fn qualify_builtin_exception_type(self: *Evaluator, type_name: []const u8) ![]const u8 {
        if (std.mem.indexOfScalar(u8, type_name, '.') != null) return type_name;
        const builtin_exception_types = [_][]const u8{
            "Exception",
            "DMLException",
            "DmlException",
            "NullPointerException",
            "TypeException",
            "QueryException",
            "JSONException",
            "ListException",
            "MathException",
            "SecurityException",
            "NoAccessException",
            "InvalidParameterValueException",
            "CalloutException",
            "StringException",
            "NoSuchElementException",
            "NoDataFoundException",
            "SearchException",
            "SObjectException",
            "HandledException",
            "IllegalArgumentException",
            "LimitException",
            "AsyncException",
            "SerializationException",
            "FlowException",
            "FinalException",
            "UnsupportedOperationException",
            "EventBusException",
        };
        inline for (builtin_exception_types) |builtin_exception_type| {
            if (std.ascii.eqlIgnoreCase(type_name, builtin_exception_type)) {
                return try std.fmt.allocPrint(self.arena, "System.{s}", .{builtin_exception_type});
            }
        }
        return type_name;
    }

    fn invoke_attached_finalizer(
        self: *Evaluator,
        job_id: []const u8,
        exception_value: ?Value,
    ) !void {
        const finalizer_obj = self.attached_finalizer orelse return;
        const finalizer_class = self.find_class(finalizer_obj.class_name) orelse return;
        const finalizer_context = try self.build_finalizer_context(job_id, exception_value);
        const saved_pending_exception = self.pending_exception;
        self.pending_exception = null;
        _ = self.call_instance_method(
            finalizer_class,
            finalizer_obj,
            "execute",
            &.{finalizer_context},
        ) catch |err| {
            if (exception_value != null) {
                self.pending_exception = exception_value;
                return;
            }
            if (self.pending_exception == null) self.pending_exception = saved_pending_exception;
            return err;
        };
        self.pending_exception = saved_pending_exception;
    }

    fn execute_pending_batch_job(self: *Evaluator, batch_obj: *types.ObjectInstance) !void {
        const batch_class = self.find_class(batch_obj.class_name) orelse return;
        const batch_job_id = if (batch_obj.fields.get("__batchJobId")) |job_id_val|
            switch (job_id_val) {
                .string => job_id_val.string,
                else => try self.create_async_apex_job(
                    "BatchApex",
                    batch_obj.class_name,
                    "execute",
                ),
            }
        else
            try self.create_async_apex_job("BatchApex", batch_obj.class_name, "execute");

        const batch_context_value = try self.build_batchable_context(batch_job_id, null);
        const batch_context = batch_context_value.object;
        const saved_batch_context = self.active_batch_context;
        const saved_batch_job_id = self.active_batch_job_id;
        self.active_batch_context = batch_context;
        self.active_batch_job_id = batch_job_id;
        defer {
            self.active_batch_context = saved_batch_context;
            self.active_batch_job_id = saved_batch_job_id;
        }

        const start_scope = try self.call_batch_lifecycle_phase(
            batch_class,
            batch_obj,
            batch_job_id,
            "start",
            &.{batch_context_value},
        );

        const all_records = try self.collect_batch_scope_records(start_scope);

        const record_list = try self.arena.create(types.ListValue);
        record_list.* = .{ .items = all_records };
        _ = try self.call_batch_lifecycle_phase(
            batch_class,
            batch_obj,
            batch_job_id,
            "execute",
            &.{ batch_context_value, Value{ .list = record_list } },
        );
        _ = try self.call_batch_lifecycle_phase(
            batch_class,
            batch_obj,
            batch_job_id,
            "finish",
            &.{batch_context_value},
        );

        self.update_async_apex_job(batch_job_id, "Completed", 0);
    }

    fn call_batch_lifecycle_phase(
        self: *Evaluator,
        batch_class: *ast.ClassDecl,
        batch_obj: *types.ObjectInstance,
        batch_job_id: []const u8,
        phase: []const u8,
        args: []const Value,
    ) !Value {
        return self.call_instance_method(
            batch_class,
            batch_obj,
            phase,
            args,
        ) catch |err| {
            self.update_async_apex_job(batch_job_id, "Failed", 1);
            if (self.pending_exception) |exception_value| {
                const phase_name = try self.uppercase_ascii(phase);
                try self.publish_batch_apex_error_event(
                    batch_obj,
                    batch_job_id,
                    phase_name,
                    exception_value,
                );
            }
            return err;
        };
    }

    fn uppercase_ascii(self: *Evaluator, value: []const u8) ![]const u8 {
        const result = try self.arena.alloc(u8, value.len);
        for (value, 0..) |ch, i| result[i] = std.ascii.toUpper(ch);
        return result;
    }

    fn collect_batch_scope_records(
        self: *Evaluator,
        start_scope: Value,
    ) !std.ArrayListUnmanaged(Value) {
        var all_records: std.ArrayListUnmanaged(Value) = .empty;
        if (start_scope != .object) {
            try self.append_stored_records(&all_records);
            return all_records;
        }

        if (start_scope.object.fields.get("query")) |query_val| {
            if (query_val == .string) {
                const batch_env = try self.global_env.child();
                const query_result =
                    self.execute_soql(query_val.string, batch_env) catch Value.null_val;
                if (query_result == .list) {
                    for (query_result.list.items.items) |item| {
                        try all_records.append(self.arena, item);
                    }
                }
            }
            return all_records;
        }

        if (start_scope.object.fields.get("records")) |records_val| {
            if (records_val == .list) {
                for (records_val.list.items.items) |item| {
                    try all_records.append(self.arena, item);
                }
            }
            return all_records;
        }

        try self.append_stored_records(&all_records);
        return all_records;
    }

    fn append_stored_records(
        self: *Evaluator,
        records: *std.ArrayListUnmanaged(Value),
    ) !void {
        var store_iter = self.store.iterator();
        while (store_iter.next()) |entry| {
            for (entry.value_ptr.items) |item| {
                try records.append(self.arena, item);
            }
        }
    }

    fn enqueue_job(self: *Evaluator, job_obj: *types.ObjectInstance) !Value {
        self.limits_queueable += 1;
        const saved_dml = self.limits_dml;
        const saved_dml_rows = self.limits_dml_rows;
        const saved_soql = self.limits_soql;
        const saved_pub = self.limits_publish_immediate;
        const saved_callouts = self.limits_callouts;
        const saved_attached_finalizer = self.attached_finalizer;
        const saved_active_queueable_job_id = self.active_queueable_job_id;

        const job_id = try self.create_async_apex_job("Queueable", job_obj.class_name, null);
        self.attached_finalizer = null;
        self.active_queueable_job_id = job_id;

        defer {
            self.attached_finalizer = saved_attached_finalizer;
            self.active_queueable_job_id = saved_active_queueable_job_id;
            self.limits_dml = saved_dml;
            self.limits_dml_rows = saved_dml_rows;
            self.limits_soql = saved_soql;
            self.limits_publish_immediate = saved_pub;
            self.limits_callouts = saved_callouts;
        }

        if (self.find_class(job_obj.class_name)) |job_class| {
            const queueable_context = try self.build_queueable_context(job_id);
            const execute_args = [_]Value{queueable_context};
            const execute_result = if (self.find_best_method_in_class_filtered(
                job_class,
                "execute",
                &execute_args,
                true,
            ) != null)
                self.call_method(job_obj.class_name, "execute", &execute_args)
            else
                self.call_instance_method(job_class, job_obj, "execute", &execute_args);
            _ = execute_result catch |err| {
                if (err == error.ApexException) {
                    const thrown_exception = self.pending_exception;
                    self.update_async_apex_job(job_id, "Failed", 1);
                    try self.invoke_attached_finalizer(job_id, thrown_exception);
                    self.pending_exception = thrown_exception;
                }
                return err;
            };
        }

        self.update_async_apex_job(job_id, "Completed", 0);
        try self.invoke_attached_finalizer(job_id, null);
        return Value{ .string = job_id };
    }

    /// Resolve a static field or static property getter from a specific class.
    /// Tries getter first (for lazy-init patterns), then plain global_env lookup.
    fn resolve_static_field_value_on_class(
        self: *Evaluator,
        class_name: []const u8,
        field_name: []const u8,
    ) ?Value {
        self.ensure_static_init(class_name);
        const cd = self.find_class(class_name) orelse return null;
        // Try static property getter first
        const already_in_getter = if (self.evaluating_getter) |eg|
            std.ascii.eqlIgnoreCase(eg, field_name)
        else
            false;
        if (!already_in_getter) {
            for (cd.members) |member| {
                switch (member) {
                    .field_decl => |fd| {
                        if (fd.modifiers.is_static and
                            std.ascii.eqlIgnoreCase(fd.name, field_name) and
                            fd.getter_body != null)
                        {
                            const getter_env = self.global_env.child() catch return null;
                            const saved_class = self.current_class;
                            const saved_getter = self.evaluating_getter;
                            const saved_getter_instance = self.evaluating_getter_instance;
                            self.current_class = class_name;
                            self.evaluating_getter = field_name;
                            self.evaluating_getter_instance = null;
                            defer {
                                self.current_class = saved_class;
                                self.evaluating_getter = saved_getter;
                                self.evaluating_getter_instance = saved_getter_instance;
                            }

                            const result =
                                self.exec_block(fd.getter_body.?, getter_env) catch return null;
                            return switch (result) {
                                .return_val => |v| v,
                                else => self.return_value,
                            };
                        }
                    },
                    else => {},
                }
            }
        }
        // Plain static field lookup
        const key = std.fmt.allocPrint(
            self.arena,
            "{s}.{s}",
            .{ class_name, field_name },
        ) catch return null;
        return self.global_env.get(key);
    }

    /// Resolve a static field or static property getter from the outer class of an inner class.
    /// Tries getter first (for lazy-init patterns), then plain global_env lookup.
    fn resolve_outer_static_field(
        self: *Evaluator,
        inner_class_name: []const u8,
        field_name: []const u8,
    ) ?Value {
        const outer_name = self.find_outer_class_name(inner_class_name) orelse return null;
        return self.resolve_static_field_value_on_class(outer_name, field_name);
    }

    /// Resolve a bare method call from an inner class to the nearest enclosing
    /// outer class that defines a compatible static method with the same name.
    fn resolve_outer_static_method_owner(
        self: *Evaluator,
        inner_class_name: []const u8,
        method_name: []const u8,
        args: []const Value,
    ) ?[]const u8 {
        var current_name = inner_class_name;
        while (self.find_outer_class_name(current_name)) |outer_name| {
            if (std.ascii.eqlIgnoreCase(outer_name, current_name)) break;
            if (self.find_class(outer_name)) |outer_decl| {
                if (self.find_best_method_in_class_filtered(
                    outer_decl,
                    method_name,
                    args,
                    true,
                ) != null) {
                    return outer_name;
                }
            }
            current_name = outer_name;
        }
        return null;
    }

    // -----------------------------------------------------------------------
    // JSON パーサー
    // -----------------------------------------------------------------------

    /// Compare two Values by a field name for ORDER BY.
    /// Returns: -1 if a < b, 0 if equal, 1 if a > b
    fn compare_by_field(self: *Evaluator, a: Value, b: Value, field: []const u8) i32 {
        const av = self.s_object_field_value_or_null(a, field);
        const bv = self.s_object_field_value_or_null(b, field);
        // null sorts last
        if (av == .null_val and bv == .null_val) return 0;
        if (av == .null_val) return 1;
        if (bv == .null_val) return -1;
        if (builtins.extract_date_string(av)) |a_date| {
            if (builtins.extract_date_string(bv)) |b_date| {
                return compare_case_insensitive_strings(a_date, b_date);
            }
        }
        // String comparison (case-insensitive)
        if (av == .string and bv == .string) {
            return compare_case_insensitive_strings(av.string, bv.string);
        }
        // Integer/Long comparison
        if ((av == .integer or av == .long) and (bv == .integer or bv == .long)) {
            const ai = if (av == .integer) av.integer else av.long;
            const bi = if (bv == .integer) bv.integer else bv.long;
            if (ai < bi) return -1;
            if (ai > bi) return 1;
            return 0;
        }
        // Double comparison
        if (av == .double and bv == .double) {
            if (av.double < bv.double) return -1;
            if (av.double > bv.double) return 1;
            return 0;
        }
        return 0;
    }

    fn s_object_field_value_or_null(
        self: *Evaluator,
        value: Value,
        field: []const u8,
    ) Value {
        if (value != .sobject) return Value.null_val;
        if (std.ascii.eqlIgnoreCase(field, "Id")) {
            if (value.sobject.id) |id| return Value{ .string = id };
        }
        return self.get_s_object_field_value_case_insensitive(
            value.sobject,
            field,
        ) orelse Value.null_val;
    }

    /// Compare two Values for natural ordering.
    /// null < non-null; strings case-insensitive; integers/doubles numeric order
    fn compare_values(_: *Evaluator, a: Value, b: Value) i32 {
        // null handling
        if (a == .null_val and b == .null_val) return 0;
        if (a == .null_val) return -1;
        if (b == .null_val) return 1;
        if (builtins.extract_date_string(a)) |a_date| {
            if (builtins.extract_date_string(b)) |b_date| {
                return compare_case_insensitive_strings(a_date, b_date);
            }
        }
        // String comparison
        if (a == .string and b == .string) {
            return compare_case_insensitive_strings(a.string, b.string);
        }
        // Integer/Long comparison
        if ((a == .integer or a == .long) and (b == .integer or b == .long)) {
            const ai = if (a == .integer) a.integer else a.long;
            const bi = if (b == .integer) b.integer else b.long;
            if (ai < bi) return -1;
            if (ai > bi) return 1;
            return 0;
        }
        // Double comparison
        if (a == .double and b == .double) {
            if (a.double < b.double) return -1;
            if (a.double > b.double) return 1;
            return 0;
        }
        // Boolean
        if (a == .boolean and b == .boolean) {
            if (!a.boolean and b.boolean) return -1;
            if (a.boolean and !b.boolean) return 1;
            return 0;
        }
        const a_rank: i32 = switch (a) {
            .string => 0,
            .integer, .long, .double => 1,
            .boolean => 2,
            else => 3,
        };
        const b_rank: i32 = switch (b) {
            .string => 0,
            .integer, .long, .double => 1,
            .boolean => 2,
            else => 3,
        };
        if (a_rank < b_rank) return -1;
        if (a_rank > b_rank) return 1;
        return 0;
    }

    fn compare_case_insensitive_strings(left: []const u8, right: []const u8) i32 {
        const len = @min(left.len, right.len);
        for (0..len) |i| {
            const lhs = std.ascii.toLower(left[i]);
            const rhs = std.ascii.toLower(right[i]);
            const lhs_rank: u8 = if (std.ascii.isAlphabetic(lhs))
                0
            else if (std.ascii.isDigit(lhs))
                1
            else
                2;
            const rhs_rank: u8 = if (std.ascii.isAlphabetic(rhs))
                0
            else if (std.ascii.isDigit(rhs))
                1
            else
                2;
            if (lhs_rank < rhs_rank) return -1;
            if (lhs_rank > rhs_rank) return 1;
            if (lhs < rhs) return -1;
            if (lhs > rhs) return 1;
        }
        if (left.len < right.len) return -1;
        if (left.len > right.len) return 1;
        return 0;
    }

    fn class_implements_interface(
        self: *Evaluator,
        class_name: []const u8,
        interface_name: []const u8,
    ) bool {
        const cd = self.find_class(class_name) orelse return false;
        for (cd.interfaces) |iface| {
            if (std.ascii.eqlIgnoreCase(iface.name, interface_name)) return true;
            if (std.mem.lastIndexOfScalar(u8, iface.name, '.')) |dot_pos| {
                if (std.ascii.eqlIgnoreCase(iface.name[dot_pos + 1 ..], interface_name)) {
                    return true;
                }
            }
        }
        // Check parent class
        if (cd.super_class) |sc| {
            return self.class_implements_interface(sc.name, interface_name);
        }
        return false;
    }

    fn has_comparable_interface(self: *Evaluator, class_name: []const u8) bool {
        return self.class_implements_interface(class_name, "Comparable");
    }

    fn is_batch_lifecycle_method(
        self: *Evaluator,
        class_name: []const u8,
        method_name: []const u8,
    ) bool {
        if (!(std.ascii.eqlIgnoreCase(method_name, "start") or
            std.ascii.eqlIgnoreCase(method_name, "execute") or
            std.ascii.eqlIgnoreCase(method_name, "finish")))
        {
            return false;
        }
        return self.class_implements_interface(class_name, "Database.Batchable") or
            self.class_implements_interface(class_name, "Batchable");
    }

    fn call_compare_to(self: *Evaluator, a: *types.ObjectInstance, b_val: Value) !i32 {
        if (self.find_class(a.class_name)) |cd| {
            const result = try self.call_instance_method(cd, a, "compareTo", &.{b_val});
            if (result == .integer) return @intCast(sign_i64(result.integer));
        }
        return 0;
    }

    fn sign_i64(value: i64) i32 {
        if (value > 0) return 1;
        if (value < 0) return -1;
        return 0;
    }

    /// Find the element type of an array field by scanning the source code.
    /// Looks for patterns like "TypeName[] fieldName" or "List<TypeName> fieldName".
    fn find_field_array_type(
        _: *Evaluator,
        source: []const u8,
        field_name: []const u8,
    ) ?[]const u8 {
        // Search for "fieldName" in source and look backwards for the type
        var pos: usize = 0;
        while (pos < source.len) {
            // Find field_name in source (case-insensitive)
            const found = std.ascii.indexOfIgnoreCasePos(source, pos, field_name) orelse break;
            // Ensure it's a whole-word match (not part of a larger identifier)
            const is_word_start = found == 0 or
                (!std.ascii.isAlphanumeric(source[found - 1]) and source[found - 1] != '_');
            const after_end = found + field_name.len;
            const is_word_end = after_end >= source.len or
                (!std.ascii.isAlphanumeric(source[after_end]) and source[after_end] != '_');
            if (!is_word_start or !is_word_end) {
                pos = found + 1;
                continue;
            }
            // Check that it's preceded by "[] " or "> " (array type indicators)
            if (found >= 3) {
                const before = source[0..found];
                const trimmed_before = std.mem.trimEnd(u8, before, " \t");
                // Check for "[]" suffix → "TypeName[]"
                if (std.mem.endsWith(u8, trimmed_before, "[]")) {
                    // Find the start of the type name
                    const type_end = trimmed_before.len - 2;
                    var type_start = type_end;
                    while (type_start > 0 and
                        (std.ascii.isAlphanumeric(trimmed_before[type_start - 1]) or
                            trimmed_before[type_start - 1] == '_'))
                    {
                        type_start -= 1;
                    }
                    if (type_start < type_end) {
                        return trimmed_before[type_start..type_end];
                    }
                }
                // Check for ">" suffix → "List<TypeName>"
                if (std.mem.endsWith(u8, trimmed_before, ">")) {
                    // Find the opening "<"
                    if (std.mem.lastIndexOfScalar(u8, trimmed_before, '<')) |lt| {
                        const inner = std.mem.trim(
                            u8,
                            trimmed_before[lt + 1 .. trimmed_before.len - 1],
                            " \t",
                        );
                        if (inner.len > 0) {
                            return inner;
                        }
                    }
                }
            }
            pos = found + field_name.len;
        }
        return null;
    }

    /// Parse a JSON string into a Value.
    fn parse_json_value(self: *Evaluator, json_str: []const u8, type_hint: []const u8) ?Value {
        const trimmed = std.mem.trim(u8, json_str, " \t\r\n");
        if (trimmed.len == 0) return null;
        if (trimmed[0] == '[') return self.parse_json_array_value(trimmed, type_hint);
        if (trimmed[0] == '{') return self.parse_json_object_value(trimmed, type_hint);
        return self.parse_json_scalar_value(trimmed, type_hint);
    }

    const JsonArrayElement = struct {
        value: []const u8,
        next_index: usize,
    };

    const JsonObjectField = struct {
        key: []const u8,
        value: []const u8,
        next_index: usize,
    };

    const JsonObjectFieldResult = union(enum) {
        field: JsonObjectField,
        end,
        malformed,
    };

    fn parse_json_array_value(self: *Evaluator, trimmed: []const u8, type_hint: []const u8) ?Value {
        const list = self.arena.create(types.ListValue) catch return null;
        list.* = .{};
        const elem_type = json_array_element_type(type_hint);
        var cursor: usize = 1;
        while (next_json_array_element(trimmed, cursor)) |element| : (cursor = element.next_index) {
            if (element.value.len == 0) continue;
            if (self.parse_json_value(element.value, elem_type)) |v| {
                list.items.append(self.arena, v) catch {};
            }
        }
        return Value{ .list = list };
    }

    fn json_array_element_type(type_hint: []const u8) []const u8 {
        if (std.mem.indexOf(u8, type_hint, "<")) |lt| {
            if (std.mem.indexOf(u8, type_hint[lt + 1 ..], ">")) |gt| {
                return type_hint[lt + 1 .. lt + 1 + gt];
            }
        }
        if (std.mem.endsWith(u8, type_hint, "[]")) return type_hint[0 .. type_hint.len - 2];
        return "Object";
    }

    fn next_json_array_element(source: []const u8, start: usize) ?JsonArrayElement {
        const i = skip_json_spacing_and_commas(source, start);
        if (i >= source.len or source[i] == ']') return null;
        const value_start = i;
        const value_end = scan_json_value_end(source, value_start);
        return .{
            .value = std.mem.trim(u8, source[value_start..value_end], " \t\r\n,"),
            .next_index = advance_json_cursor_after_value(source, value_end),
        };
    }

    fn parse_json_object_value(
        self: *Evaluator,
        trimmed: []const u8,
        type_hint: []const u8,
    ) ?Value {
        if (is_json_map_type(type_hint)) {
            return self.parse_json_map_value(trimmed, type_hint);
        }
        if (is_framework_json_object_type(type_hint)) {
            return self.parse_json_framework_object_value(trimmed, type_hint);
        }
        if (self.find_class(type_hint) != null) {
            return self.parse_json_user_class_object_value(trimmed, type_hint);
        }
        return self.parse_json_s_object_value(trimmed, type_hint);
    }

    fn is_json_map_type(type_hint: []const u8) bool {
        return std.ascii.startsWithIgnoreCase(type_hint, "Map<") or
            std.ascii.eqlIgnoreCase(type_hint, "Map") or
            std.ascii.eqlIgnoreCase(type_hint, "System.Map");
    }

    fn parse_json_map_value(
        self: *Evaluator,
        trimmed: []const u8,
        type_hint: []const u8,
    ) ?Value {
        const map = self.arena.create(types.MapValue) catch return null;
        map.* = .{};
        const value_type = json_map_value_type(type_hint);
        var cursor: usize = 1;
        while (true) {
            switch (next_json_object_field(trimmed, cursor)) {
                .field => |field| {
                    if (field.value.len > 0) {
                        if (self.parse_json_value(field.value, value_type)) |v| {
                            map.entries.put(self.arena, field.key, v) catch {};
                        }
                    }
                    cursor = field.next_index;
                },
                .end => break,
                .malformed => return null,
            }
        }
        return Value{ .map = map };
    }

    fn json_map_value_type(type_hint: []const u8) []const u8 {
        const lt = std.mem.indexOfScalar(u8, type_hint, '<') orelse return "Object";
        const gt = std.mem.lastIndexOfScalar(u8, type_hint, '>') orelse return "Object";
        if (gt <= lt + 1) return "Object";
        const inner = type_hint[lt + 1 .. gt];
        var depth: usize = 0;
        var comma_index: ?usize = null;
        for (inner, 0..) |ch, i| {
            if (ch == '<') {
                depth += 1;
            } else if (ch == '>') {
                if (depth > 0) depth -= 1;
            } else if (ch == ',' and depth == 0) {
                comma_index = i;
                break;
            }
        }
        const comma = comma_index orelse return "Object";
        return std.mem.trim(u8, inner[comma + 1 ..], " \t\r\n");
    }

    fn is_framework_json_object_type(type_hint: []const u8) bool {
        return std.mem.startsWith(u8, type_hint, "Invocable.") or
            std.mem.startsWith(u8, type_hint, "Flow.") or
            std.mem.startsWith(u8, type_hint, "Messaging.") or
            std.mem.startsWith(u8, type_hint, "Auth.") or
            std.mem.startsWith(u8, type_hint, "Reports.");
    }

    fn parse_json_framework_object_value(
        self: *Evaluator,
        trimmed: []const u8,
        type_hint: []const u8,
    ) ?Value {
        const obj = self.arena.create(types.ObjectInstance) catch return null;
        obj.* = .{ .class_name = type_hint };
        var cursor: usize = 1;
        while (true) {
            switch (next_json_object_field(trimmed, cursor)) {
                .field => |field| {
                    if (field.value.len > 0) {
                        if (self.parse_json_value(field.value, "Object")) |v| {
                            obj.fields.put(self.arena, field.key, v) catch {};
                        }
                    }
                    cursor = field.next_index;
                },
                .end => break,
                .malformed => return null,
            }
        }
        return Value{ .object = obj };
    }

    fn parse_json_user_class_object_value(
        self: *Evaluator,
        trimmed: []const u8,
        type_hint: []const u8,
    ) ?Value {
        const obj = self.init_json_user_class_object(type_hint) catch return null;
        var cursor: usize = 1;
        while (true) {
            switch (next_json_object_field(trimmed, cursor)) {
                .field => |field| {
                    const field_type_hint =
                        self.json_user_class_field_type_hint(type_hint, field.key);
                    if (field.value.len > 0) {
                        if (self.parse_json_value(field.value, field_type_hint)) |v| {
                            obj.fields.put(self.arena, field.key, v) catch {};
                        }
                    }
                    cursor = field.next_index;
                },
                .end => break,
                .malformed => return null,
            }
        }
        return Value{ .object = obj };
    }

    fn init_json_user_class_object(self: *Evaluator, type_hint: []const u8) !*types.ObjectInstance {
        const obj = try self.arena.create(types.ObjectInstance);
        obj.* = .{ .class_name = type_hint };
        if (self.find_class(type_hint)) |class_decl| {
            if (class_decl.super_class) |sc| {
                if (self.find_class(sc.name)) |parent_decl| {
                    self.init_instance_fields(parent_decl, obj) catch {};
                }
            }
            self.init_instance_fields(class_decl, obj) catch {};
        }
        return obj;
    }

    fn json_user_class_field_type_hint(
        self: *Evaluator,
        type_hint: []const u8,
        key_name: []const u8,
    ) []const u8 {
        if (self.find_class(type_hint)) |cd| {
            for (cd.members) |member| {
                switch (member) {
                    .field_decl => |fd| {
                        if (!std.ascii.eqlIgnoreCase(fd.name, key_name)) continue;
                        if (std.ascii.eqlIgnoreCase(fd.type_ref.name, "List")) {
                            if (self.find_user_class_list_field_type(
                                type_hint,
                                key_name,
                            )) |elem_type| {
                                return elem_type;
                            }
                        }
                        return fd.type_ref.name;
                    },
                    else => {},
                }
            }
        }
        return "Object";
    }

    fn find_user_class_list_field_type(
        self: *Evaluator,
        type_hint: []const u8,
        key_name: []const u8,
    ) ?[]const u8 {
        for (self.class_sources.keys(), self.class_sources.values()) |k, src| {
            if (!std.ascii.eqlIgnoreCase(k, type_hint)) continue;
            if (self.find_field_array_type(src, key_name)) |elem| {
                if (elem.len > 0 and elem.len < 200) {
                    return std.fmt.allocPrint(self.arena, "{s}[]", .{elem}) catch "Object";
                }
            }
        }
        return null;
    }

    fn parse_json_s_object_value(
        self: *Evaluator,
        trimmed: []const u8,
        type_hint: []const u8,
    ) ?Value {
        const sob = self.arena.create(types.SObject) catch return null;
        var resolved_type = type_hint;
        sob.* = .{ .type_name = resolved_type };
        var cursor: usize = 1;
        while (true) {
            switch (next_json_object_field(trimmed, cursor)) {
                .field => |field| {
                    self.apply_json_s_object_field(sob, &resolved_type, field.key, field.value);
                    cursor = field.next_index;
                },
                .end => break,
                .malformed => return null,
            }
        }
        return Value{ .sobject = sob };
    }

    fn apply_json_s_object_field(
        self: *Evaluator,
        sob: *types.SObject,
        resolved_type: *[]const u8,
        key: []const u8,
        value_str: []const u8,
    ) void {
        if (value_str.len == 0) return;
        if (value_str[0] == '"') {
            self.apply_json_s_object_string_field(sob, key, value_str);
            return;
        }
        if (value_str[0] == '{') {
            self.apply_json_s_object_nested_field(sob, resolved_type, key, value_str);
            return;
        }
        if (value_str[0] == '[') {
            if (self.parse_json_value(value_str, "List")) |av| {
                sob.fields.put(self.arena, key, av) catch {};
            }
            return;
        }
        self.apply_json_s_object_literal_field(sob, key, value_str);
    }

    fn apply_json_s_object_string_field(
        self: *Evaluator,
        sob: *types.SObject,
        key: []const u8,
        value_str: []const u8,
    ) void {
        const val_str = if (value_str.len >= 2) value_str[1 .. value_str.len - 1] else "";
        if (std.mem.eql(u8, key, "attributes")) return;
        if (std.ascii.eqlIgnoreCase(key, "Id")) {
            sob.id = val_str;
            sob.fields.put(self.arena, "Id", Value{ .string = val_str }) catch {};
            return;
        }
        const normalized = self.normalize_parsed_json_s_object_field(
            sob,
            key,
            Value{ .string = val_str },
        );
        sob.fields.put(self.arena, key, normalized) catch {};
    }

    fn apply_json_s_object_nested_field(
        self: *Evaluator,
        sob: *types.SObject,
        resolved_type: *[]const u8,
        key: []const u8,
        value_str: []const u8,
    ) void {
        if (std.mem.eql(u8, key, "attributes")) {
            if (json_object_type_name(value_str)) |type_name| {
                resolved_type.* = type_name;
                sob.type_name = type_name;
            }
            return;
        }
        if (self.parse_json_value(value_str, "Object")) |nv| {
            const stored_value = self.relationship_records_value(nv) orelse
                self.normalize_parsed_json_s_object_field(sob, key, nv);
            sob.fields.put(self.arena, key, stored_value) catch {};
        }
    }

    fn json_object_type_name(value_str: []const u8) ?[]const u8 {
        const type_key_patterns = [_][]const u8{ "\"type\":\"", "\"type\": \"", "\"type\" : \"" };
        for (type_key_patterns) |pattern| {
            if (std.mem.indexOf(u8, value_str, pattern)) |type_pos| {
                const start = type_pos + pattern.len;
                if (std.mem.indexOfPos(u8, value_str, start, "\"")) |end| {
                    return value_str[start..end];
                }
                break;
            }
        }
        return null;
    }

    fn apply_json_s_object_literal_field(
        self: *Evaluator,
        sob: *types.SObject,
        key: []const u8,
        value_str: []const u8,
    ) void {
        if (std.mem.eql(u8, value_str, "null")) {
            sob.fields.put(self.arena, key, Value.null_val) catch {};
            return;
        }
        if (std.mem.eql(u8, value_str, "true")) {
            self.put_normalized_json_s_object_field(sob, key, Value{ .boolean = true });
            return;
        }
        if (std.mem.eql(u8, value_str, "false")) {
            self.put_normalized_json_s_object_field(sob, key, Value{ .boolean = false });
            return;
        }
        if (std.fmt.parseInt(i64, value_str, 10)) |n| {
            self.put_normalized_json_s_object_field(sob, key, Value{ .integer = n });
            return;
        } else |_| {}
        if (std.fmt.parseFloat(f64, value_str)) |f| {
            self.put_normalized_json_s_object_field(sob, key, Value{ .double = f });
            return;
        } else |_| {}
        self.put_normalized_json_s_object_field(sob, key, Value{ .string = value_str });
    }

    fn put_normalized_json_s_object_field(
        self: *Evaluator,
        sob: *types.SObject,
        key: []const u8,
        value: Value,
    ) void {
        const normalized = self.normalize_parsed_json_s_object_field(sob, key, value);
        sob.fields.put(self.arena, key, normalized) catch {};
    }

    fn parse_json_scalar_value(
        self: *Evaluator,
        trimmed: []const u8,
        type_hint: []const u8,
    ) ?Value {
        if (trimmed[0] == '"') {
            if (std.mem.lastIndexOfScalar(u8, trimmed, '"')) |end| {
                if (end > 0) {
                    const str_val = trimmed[1..end];
                    if (std.ascii.eqlIgnoreCase(type_hint, "Date")) {
                        return builtins.make_date_value(self.arena, str_val) catch
                            Value{ .string = str_val };
                    }
                    if (std.ascii.eqlIgnoreCase(type_hint, "DateTime") or
                        std.ascii.eqlIgnoreCase(type_hint, "Datetime"))
                    {
                        return builtins.make_datetime_value(self.arena, str_val) catch
                            Value{ .string = str_val };
                    }
                    return Value{ .string = str_val };
                }
            }
            return Value{ .string = "" };
        }
        if (std.mem.eql(u8, trimmed, "null")) return Value.null_val;
        if (std.mem.eql(u8, trimmed, "true")) return Value{ .boolean = true };
        if (std.mem.eql(u8, trimmed, "false")) return Value{ .boolean = false };
        if (std.fmt.parseInt(i64, trimmed, 10) catch null) |n| {
            return Value{ .integer = n };
        }
        if (std.fmt.parseFloat(f64, trimmed) catch null) |f| {
            return Value{ .double = f };
        }
        return null;
    }

    fn next_json_object_field(source: []const u8, start: usize) JsonObjectFieldResult {
        var i = skip_json_spacing_and_commas(source, start);
        while (i < source.len and source[i] != '"' and source[i] != '}') : (i += 1) {}
        if (i >= source.len or source[i] == '}') return .end;

        const key_start = i + 1;
        const key_end = scan_json_string_end(source, i);
        if (key_end == 0 or key_end > source.len) return .malformed;
        const key = source[key_start .. key_end - 1];

        i = skip_json_spacing(source, key_end);
        if (i >= source.len or source[i] != ':') return .malformed;
        i = skip_json_spacing(source, i + 1);
        if (i >= source.len) return .malformed;

        const value_start = i;
        const value_end = scan_json_value_end(source, value_start);
        return .{ .field = .{
            .key = key,
            .value = std.mem.trim(u8, source[value_start..value_end], " \t\r\n"),
            .next_index = advance_json_cursor_after_value(source, value_end),
        } };
    }

    fn skip_json_spacing(source: []const u8, start: usize) usize {
        var i = start;
        while (i < source.len and is_soql_whitespace(source[i])) : (i += 1) {}
        return i;
    }

    fn skip_json_spacing_and_commas(source: []const u8, start: usize) usize {
        var i = start;
        while (i < source.len and (is_soql_whitespace(source[i]) or source[i] == ',')) : (i += 1) {}
        return i;
    }

    fn advance_json_cursor_after_value(source: []const u8, start: usize) usize {
        var i = skip_json_spacing(source, start);
        if (i < source.len and source[i] == ',') i += 1;
        return i;
    }

    fn scan_json_value_end(source: []const u8, start: usize) usize {
        if (start >= source.len) return start;
        if (source[start] == '"') return scan_json_string_end(source, start);
        if (source[start] == '{' or source[start] == '[') {
            var depth: usize = 1;
            var i = start + 1;
            while (i < source.len and depth > 0) : (i += 1) {
                if (source[i] == '"') {
                    const string_end = scan_json_string_end(source, i);
                    if (string_end <= i) return source.len;
                    i = string_end - 1;
                    continue;
                }
                if (source[i] == '{' or source[i] == '[') {
                    depth += 1;
                } else if (source[i] == '}' or source[i] == ']') {
                    depth -= 1;
                }
            }
            return i;
        }

        var i = start;
        while (i < source.len and json_scalar_char(source[i])) : (i += 1) {}
        return i;
    }

    fn json_scalar_char(ch: u8) bool {
        return ch != ',' and ch != '}' and ch != ']' and !is_soql_whitespace(ch);
    }

    fn scan_json_string_end(source: []const u8, start: usize) usize {
        var i = start + 1;
        while (i < source.len and source[i] != '"') : (i += 1) {
            if (source[i] == '\\' and i + 1 < source.len) i += 1;
        }
        if (i >= source.len) return source.len;
        return i + 1;
    }

