    /// Determine whether a type name represents a Salesforce SObject type.
    fn is_s_object_type_name(self: *Evaluator, name: []const u8) bool {
        // Custom suffixes: __c, __e, __mdt, __b
        if (std.mem.endsWith(u8, name, "__c") or std.mem.endsWith(u8, name, "__e") or
            std.mem.endsWith(u8, name, "__mdt") or std.mem.endsWith(u8, name, "__b"))
            return true;
        // Present in the data store
        if (self.store.get(name) != null) return true;
        for (known_s_object_type_names) |kt| {
            if (std.ascii.eqlIgnoreCase(name, kt)) return true;
        }
        return false;
    }

    fn is_known_schema_enum_type(name: []const u8) bool {
        return std.ascii.eqlIgnoreCase(name, "DisplayType") or
            std.ascii.eqlIgnoreCase(name, "SoapType");
    }

    fn is_known_metadata_enum_type(name: []const u8) bool {
        return std.ascii.eqlIgnoreCase(name, "DeployStatus");
    }

    /// Instantiate a class by name (for Type.forName().newInstance())
    fn instantiate_class(self: *Evaluator, class_name: []const u8) !Value {
        // Lazy static init: ensure the class's static fields/blocks are initialized
        self.ensure_static_init(class_name);
        if (try self.instantiate_metadata_framework_class(class_name)) |value| {
            return value;
        }
        if (self.find_class(class_name)) |class_decl| {
            // Also ensure parent class hierarchy is initialized
            if (class_decl.super_class) |sc| self.ensure_static_init(sc.name);
            const instance = try self.arena.create(types.ObjectInstance);
            // Preserve the requested class name so qualified inner classes
            // continue to dispatch against the intended outer class.
            instance.* = .{ .class_name = class_name };
            // Initialize instance fields
            self.init_instance_fields(class_decl, instance) catch {};
            // Initialize parent class fields
            if (class_decl.super_class) |sc| {
                if (self.find_class(sc.name)) |parent_decl| {
                    self.init_instance_fields(parent_decl, instance) catch {};
                }
            }
            // Execute parent constructor
            if (class_decl.super_class) |sc| {
                if (self.find_class(sc.name)) |parent_decl| {
                    try self.run_constructor(parent_decl, instance, &.{});
                }
            }
            // Execute own constructor
            try self.run_constructor(class_decl, instance, &.{});
            return Value{ .object = instance };
        }
        // SObject type name → return .sobject instead of .object
        if (self.is_s_object_type_name(class_name)) {
            const sob = try self.arena.create(types.SObject);
            sob.* = .{ .type_name = class_name };
            return Value{ .sobject = sob };
        }
        // Fallback: create a bare ObjectInstance
        const instance = try self.arena.create(types.ObjectInstance);
        instance.* = .{ .class_name = class_name };
        return Value{ .object = instance };
    }

    fn instantiate_metadata_framework_class(
        self: *Evaluator,
        class_name: []const u8,
    ) !?Value {
        if (!std.ascii.startsWithIgnoreCase(class_name, "Metadata.")) return null;
        const instance = try self.arena.create(types.ObjectInstance);
        instance.* = .{ .class_name = class_name };

        if (std.ascii.eqlIgnoreCase(class_name, "Metadata.CustomMetadata")) {
            const values = try self.arena.create(types.ListValue);
            values.* = .{};
            try instance.fields.put(self.arena, "values", Value{ .list = values });
            try instance.fields.put(self.arena, "protected_x", Value{ .boolean = false });
        } else if (std.ascii.eqlIgnoreCase(class_name, "Metadata.DeployResult")) {
            try instance.fields.put(self.arena, "status", Value{ .string = "Succeeded" });
            try instance.fields.put(
                self.arena,
                "details",
                (try self.instantiate_metadata_framework_class("Metadata.DeployDetails")).?,
            );
        } else if (std.ascii.eqlIgnoreCase(class_name, "Metadata.DeployDetails")) {
            const failures = try self.arena.create(types.ListValue);
            failures.* = .{};
            try instance.fields.put(self.arena, "componentFailures", Value{ .list = failures });
        }
        return Value{ .object = instance };
    }
};

// ---------------------------------------------------------------------------
// 静的ヘルパー
// ---------------------------------------------------------------------------

fn ascii_lower_alloc(alloc: std.mem.Allocator, value: []const u8) ![]const u8 {
    const out = try alloc.alloc(u8, value.len);
    return ascii_lower_into(out, value);
}

fn ascii_lower_into(out: []u8, value: []const u8) []const u8 {
    for (value, 0..) |ch, i| out[i] = std.ascii.toLower(ch);
    return out[0..value.len];
}

/// Apex-compatible `String.split(regex)` implementation backed by the interpret regex engine.
/// `split_limit` mirrors the `split(regex, limit)` overload: when set and > 1, only that many
/// segments are produced (the final one absorbs any unsplit tail); limit == 1 is a no-op.
/// Callers remain responsible for the "empty regex splits every character" case — this helper
/// only handles non-empty patterns.
fn split_by_regex(
    arena: std.mem.Allocator,
    pattern: []const u8,
    s: []const u8,
    split_limit: ?usize,
) ![][]const u8 {
    var parts = std.ArrayListUnmanaged([]const u8).empty;
    const matches = try regex.find_all(arena, pattern, s);
    if (split_limit) |lim| {
        if (lim <= 1) {
            try parts.append(arena, s);
            return parts.items;
        }
    }
    var start: usize = 0;
    var splits_done: usize = 0;
    for (matches) |m| {
        const span = m.groups[0] orelse continue;
        if (split_limit) |lim| {
            if (splits_done + 1 >= lim) break;
        }
        // Zero-width match on the current cursor — skip to avoid infinite splitting.
        if (span.start == start and span.end == start) continue;
        try parts.append(arena, s[start..span.start]);
        start = span.end;
        splits_done += 1;
    }
    try parts.append(arena, s[start..]);
    return parts.items;
}

/// True when (enum_simple_name, value) matches a well-known built-in System enum.
/// Used for overload resolution since enum values are represented as plain strings.
const trigger_operation_values = [_][]const u8{
    "BEFORE_INSERT",
    "BEFORE_UPDATE",
    "BEFORE_DELETE",
    "AFTER_INSERT",
    "AFTER_UPDATE",
    "AFTER_DELETE",
    "AFTER_UNDELETE",
};

const logging_level_values = [_][]const u8{
    "INTERNAL",
    "FINEST",
    "FINER",
    "FINE",
    "DEBUG",
    "INFO",
    "WARN",
    "ERROR",
    "NONE",
};

const access_type_values = [_][]const u8{ "CREATABLE", "READABLE", "UPDATABLE", "UPSERTABLE" };
const access_level_values = [_][]const u8{ "USER_MODE", "SYSTEM_MODE" };
const system_mode_values = [_][]const u8{ "SANDBOX", "PROD", "DEVELOPER", "TRIAL", "SCRATCH_ORG" };

const quiddity_values = [_][]const u8{
    "ANONYMOUS",
    "AURA",
    "BATCH_APEX",
    "BATCH_CHUNK_PARALLEL",
    "BATCH_CHUNK_SERIAL",
    "BULK_API",
    "FUTURE",
    "INVOCABLE_ACTION",
    "IOT",
    "LIGHTNING_OUT",
    "QUEUEABLE",
    "QUICK_ACTION",
    "REMOTE_ACTION",
    "REST",
    "RUNTEST_ASYNC",
    "RUNTEST_DEPLOY",
    "RUNTEST_SYNC",
    "SCHEDULED",
    "SOAP",
    "SYNCHRONOUS",
    "VF",
    "WAVE",
};

fn is_system_enum_value(enum_simple: []const u8, value: []const u8) bool {
    if (enum_simple.len == 0 or value.len == 0) return false;
    if (std.ascii.eqlIgnoreCase(enum_simple, "TriggerOperation")) {
        for (trigger_operation_values) |n| if (std.ascii.eqlIgnoreCase(n, value)) return true;
        return false;
    }
    if (std.ascii.eqlIgnoreCase(enum_simple, "LoggingLevel")) {
        for (logging_level_values) |n| if (std.ascii.eqlIgnoreCase(n, value)) return true;
        return false;
    }
    if (std.ascii.eqlIgnoreCase(enum_simple, "AccessType")) {
        for (access_type_values) |n| if (std.ascii.eqlIgnoreCase(n, value)) return true;
        return false;
    }
    if (std.ascii.eqlIgnoreCase(enum_simple, "AccessLevel")) {
        for (access_level_values) |n| if (std.ascii.eqlIgnoreCase(n, value)) return true;
        return false;
    }
    if (std.ascii.eqlIgnoreCase(enum_simple, "Quiddity")) {
        for (quiddity_values) |n| if (std.ascii.eqlIgnoreCase(n, value)) return true;
        return false;
    }
    if (std.ascii.eqlIgnoreCase(enum_simple, "OrganizationType") or
        std.ascii.eqlIgnoreCase(enum_simple, "InstanceType"))
    {
        for (system_mode_values) |n| if (std.ascii.eqlIgnoreCase(n, value)) return true;
        return false;
    }
    return false;
}

/// True if `pt` looks like a known built-in System enum type name (simple or qualified).
fn is_system_enum_type_name(pt: []const u8) bool {
    const simple = if (std.mem.lastIndexOfScalar(u8, pt, '.')) |di|
        pt[di + 1 ..]
    else
        pt;
    if (simple.len == 0) return false;
    const names = [_][]const u8{
        "TriggerOperation",
        "LoggingLevel",
        "AccessType",
        "AccessLevel",
        "Quiddity",
        "DisplayType",
        "SoapType",
    };
    for (names) |n| {
        if (std.ascii.eqlIgnoreCase(n, simple)) return true;
    }
    return false;
}

/// メソッドオーバーロード解決用: 引数の Value とパラメータ型名のスコア計算。
fn overload_score_for_arg(arg: Value, pt: []const u8) i32 {
    if (arg == .null_val) {
        return overload_score_for_null_arg(pt);
    }
    if (arg == .string) {
        return overload_score_for_string_arg(arg.string, pt);
    }
    if (arg == .integer) {
        return overload_score_for_integer_arg(pt);
    }
    if (arg == .long) {
        return overload_score_for_long_arg(pt);
    }
    if (arg == .double) {
        return overload_score_for_double_arg(pt);
    }
    if (arg == .boolean) {
        if (std.ascii.eqlIgnoreCase(pt, "Boolean")) return 2;
        if (std.ascii.eqlIgnoreCase(pt, "Object")) return 1;
        return 0;
    }
    if (arg == .list) {
        return overload_score_for_list_arg(arg.list, pt);
    }
    if (arg == .map) {
        if (std.ascii.eqlIgnoreCase(pt, "Map")) return 2;
        if (std.ascii.startsWithIgnoreCase(pt, "Map<")) return 2;
        if (std.ascii.eqlIgnoreCase(pt, "Object")) return 1;
        return 0;
    }
    if (arg == .set) {
        if (std.ascii.eqlIgnoreCase(pt, "Set")) return 2;
        if (std.ascii.startsWithIgnoreCase(pt, "Set<")) return 2;
        if (std.ascii.eqlIgnoreCase(pt, "Object")) return 1;
        if (std.ascii.startsWithIgnoreCase(pt, "Iterable") or
            std.mem.endsWith(u8, pt, "Iterable"))
            return 1;
        return 0;
    }
    if (arg == .sobject) {
        return overload_score_for_sobject_arg(arg.sobject, pt);
    }
    if (arg == .object) {
        return overload_score_for_object_arg(arg.object, pt);
    }
    return 0;
}

fn overload_score_for_null_arg(pt: []const u8) i32 {
    if (std.ascii.eqlIgnoreCase(pt, "String") or
        std.ascii.eqlIgnoreCase(pt, "Id"))
        return 2;
    if (std.ascii.eqlIgnoreCase(pt, "Object")) return 1;
    if (std.ascii.eqlIgnoreCase(pt, "List") or
        std.ascii.startsWithIgnoreCase(pt, "List<") or
        std.ascii.eqlIgnoreCase(pt, "Map") or
        std.ascii.startsWithIgnoreCase(pt, "Map<") or
        std.ascii.eqlIgnoreCase(pt, "Set") or
        std.ascii.startsWithIgnoreCase(pt, "Set<"))
        return 1;
    if (std.ascii.eqlIgnoreCase(pt, "Boolean") or
        std.ascii.eqlIgnoreCase(pt, "Integer") or
        std.ascii.eqlIgnoreCase(pt, "int") or
        std.ascii.eqlIgnoreCase(pt, "Long") or
        std.ascii.eqlIgnoreCase(pt, "Double") or
        std.ascii.eqlIgnoreCase(pt, "Decimal"))
        return 0;
    return 1;
}

fn overload_score_for_string_arg(value: []const u8, pt: []const u8) i32 {
    if (std.ascii.eqlIgnoreCase(pt, "String")) return 2;
    if (std.ascii.eqlIgnoreCase(pt, "Id")) {
        return if (Evaluator.is_salesforce_id_string(value)) 3 else 2;
    }
    if (std.ascii.eqlIgnoreCase(pt, "Object")) return 1;
    if (std.ascii.eqlIgnoreCase(pt, "Date") and
        Evaluator.is_date_only_format_string(value))
        return 2;
    if ((std.ascii.eqlIgnoreCase(pt, "DateTime") or
        std.ascii.eqlIgnoreCase(pt, "Datetime")) and
        Evaluator.is_date_time_format_string(value))
        return 2;
    return 0;
}

fn overload_score_for_integer_arg(pt: []const u8) i32 {
    if (std.ascii.eqlIgnoreCase(pt, "Integer") or std.ascii.eqlIgnoreCase(pt, "int")) return 2;
    if (std.ascii.eqlIgnoreCase(pt, "Long") or
        std.ascii.eqlIgnoreCase(pt, "Decimal") or
        std.ascii.eqlIgnoreCase(pt, "Double"))
        return 1;
    if (std.ascii.eqlIgnoreCase(pt, "Object")) return 1;
    return 0;
}

fn overload_score_for_long_arg(pt: []const u8) i32 {
    if (std.ascii.eqlIgnoreCase(pt, "Long")) return 2;
    if (std.ascii.eqlIgnoreCase(pt, "Decimal") or
        std.ascii.eqlIgnoreCase(pt, "Double"))
        return 1;
    if (std.ascii.eqlIgnoreCase(pt, "Object")) return 1;
    return 0;
}

fn overload_score_for_double_arg(pt: []const u8) i32 {
    if (std.ascii.eqlIgnoreCase(pt, "Decimal") or
        std.ascii.eqlIgnoreCase(pt, "Double"))
        return 2;
    if (std.ascii.eqlIgnoreCase(pt, "Integer") or
        std.ascii.eqlIgnoreCase(pt, "int") or
        std.ascii.eqlIgnoreCase(pt, "Long"))
        return 1;
    if (std.ascii.eqlIgnoreCase(pt, "Object")) return 1;
    return 0;
}

fn overload_score_for_list_arg(list: *types.ListValue, pt: []const u8) i32 {
    if (std.ascii.eqlIgnoreCase(pt, "List")) return 2;
    if (!std.mem.startsWith(u8, pt, "List<") and
        !std.mem.startsWith(u8, pt, "list<"))
        return 0;
    const lt = std.mem.indexOf(u8, pt, "<") orelse return 0;
    const gt = std.mem.lastIndexOf(u8, pt, ">") orelse return 0;
    const elem_type = pt[lt + 1 .. gt];
    if (std.ascii.eqlIgnoreCase(elem_type, "SObject") or
        std.ascii.eqlIgnoreCase(elem_type, "sObject") or
        std.ascii.eqlIgnoreCase(elem_type, "Sobject"))
    {
        if (list.items.items.len > 0) {
            if (list.items.items[0] == .sobject) return 3;
        }
        return 2;
    }
    if (list.items.items.len == 0) return 1;
    const first = list.items.items[0];
    if (first == .sobject) {
        if (std.ascii.eqlIgnoreCase(first.sobject.type_name, elem_type)) return 3;
        if (std.mem.lastIndexOfScalar(u8, elem_type, '.')) |di| {
            if (std.ascii.eqlIgnoreCase(first.sobject.type_name, elem_type[di + 1 ..])) {
                return 3;
            }
        }
    }
    if (first == .object) {
        if (std.ascii.eqlIgnoreCase(first.object.class_name, elem_type)) return 3;
    }
    return 1;
}

fn overload_score_for_sobject_arg(sob: *types.SObject, pt: []const u8) i32 {
    const tn = sob.type_name;
    if (std.ascii.eqlIgnoreCase(tn, pt)) return 3;
    if (std.mem.lastIndexOfScalar(u8, pt, '.')) |di| {
        if (std.ascii.eqlIgnoreCase(tn, pt[di + 1 ..])) return 3;
    }
    if (std.mem.lastIndexOfScalar(u8, tn, '.')) |di| {
        if (std.ascii.eqlIgnoreCase(tn[di + 1 ..], pt)) return 3;
    }
    if (std.ascii.eqlIgnoreCase(pt, "SObject") or
        std.ascii.eqlIgnoreCase(pt, "Sobject") or
        std.ascii.eqlIgnoreCase(pt, "sObject"))
        return 2;
    return 0;
}

fn overload_score_for_object_arg(obj: *types.ObjectInstance, pt: []const u8) i32 {
    const cn = obj.class_name;
    if (std.ascii.eqlIgnoreCase(cn, pt)) return 3;
    if (std.mem.lastIndexOfScalar(u8, cn, '.')) |di| {
        if (std.ascii.eqlIgnoreCase(cn[di + 1 ..], pt)) return 3;
    }
    if (std.mem.lastIndexOfScalar(u8, pt, '.')) |di| {
        if (std.ascii.eqlIgnoreCase(pt[di + 1 ..], cn)) return 3;
    }
    if (std.ascii.eqlIgnoreCase(cn, "Date")) {
        if (std.ascii.eqlIgnoreCase(pt, "Date")) return 2;
        if (std.ascii.eqlIgnoreCase(pt, "Object")) return 1;
        return 0;
    }
    if (std.ascii.eqlIgnoreCase(cn, "Datetime")) {
        if (std.ascii.eqlIgnoreCase(pt, "DateTime") or
            std.ascii.eqlIgnoreCase(pt, "Datetime"))
            return 2;
        if (std.ascii.eqlIgnoreCase(pt, "Object")) return 1;
        return 0;
    }
    if (std.ascii.eqlIgnoreCase(pt, "Object")) return 1;
    return 0;
}

fn eval_binary(
    eval: *Evaluator,
    left: Value,
    op: ast.BinaryOp,
    right: Value,
    arena: std.mem.Allocator,
) !Value {
    const TemporalComparable = struct {
        fn normalize(raw: []const u8) []const u8 {
            if (raw.len > 10 and std.mem.indexOf(u8, raw, "T") != null) {
                if (std.mem.endsWith(u8, raw, ".000+0000")) return raw[0 .. raw.len - 9];
                if (std.mem.endsWith(u8, raw, ".000Z")) return raw[0 .. raw.len - 4];
                if (std.mem.endsWith(u8, raw, "Z")) return raw[0 .. raw.len - 1];
            }
            return raw;
        }

        fn from_value(value: Value) ?[]const u8 {
            return switch (value) {
                .object => |obj| blk: {
                    const date_object = std.ascii.eqlIgnoreCase(obj.class_name, "Date") or
                        std.ascii.eqlIgnoreCase(obj.class_name, "Datetime");
                    if (!date_object) break :blk null;
                    const raw = obj.fields.get("value") orelse break :blk null;
                    if (raw != .string) break :blk null;
                    break :blk normalize(raw.string);
                },
                .string => |raw| blk: {
                    const normalized = normalize(raw);
                    const is_date_like =
                        normalized.len >= 10 and normalized[4] == '-' and normalized[7] == '-';
                    if (!is_date_like) break :blk null;
                    break :blk normalized;
                },
                else => null,
            };
        }
    };

    switch (op) {
        .eq => return .{ .boolean = eval.values_equal(left, right) },
        .neq => return .{ .boolean = !eval.values_equal(left, right) },
        .strict_eq => return .{ .boolean = eval.strict_values_equal(left, right) },
        .strict_neq => return .{ .boolean = !eval.strict_values_equal(left, right) },
        .and_op => return .{ .boolean = coerced_bool(left) and coerced_bool(right) },
        .or_op => return .{ .boolean = coerced_bool(left) or coerced_bool(right) },
        .bit_and, .bit_or, .bit_xor => {
            // Apex accepts `&`/`|`/`^` on both Boolean and integer operands. Preserve
            // the operand type: two Booleans produce a Boolean, mixed integer/long
            // values produce the wider integer type. Anything else collapses to null.
            if (left == .boolean and right == .boolean) {
                const lb = left.boolean;
                const rb = right.boolean;
                const b = switch (op) {
                    .bit_and => lb and rb,
                    .bit_or => lb or rb,
                    .bit_xor => lb != rb,
                    else => unreachable,
                };
                return Value{ .boolean = b };
            }
            const li: i64 = switch (left) {
                .integer => |v| v,
                .long => |v| v,
                .boolean => |b| if (b) 1 else 0,
                .null_val => 0,
                else => return Value.null_val,
            };
            const ri: i64 = switch (right) {
                .integer => |v| v,
                .long => |v| v,
                .boolean => |b| if (b) 1 else 0,
                .null_val => 0,
                else => return Value.null_val,
            };
            const use_long = left == .long or right == .long;
            const v: i64 = switch (op) {
                .bit_and => li & ri,
                .bit_or => li | ri,
                .bit_xor => li ^ ri,
                else => unreachable,
            };
            return if (use_long) Value{ .long = v } else Value{ .integer = v };
        },
        else => {},
    }

    if (integer_like_values(left, right)) {
        const li = if (left == .integer) left.integer else left.long;
        const ri = if (right == .integer) right.integer else right.long;
        const use_long = left == .long or right == .long;
        return if (use_long) .{ .long = switch (op) {
            .add => li + ri,
            .sub => li - ri,
            .mul => li * ri,
            .div => if (ri != 0) @divTrunc(li, ri) else 0,
            .mod => if (ri != 0) @mod(li, ri) else 0,
            .lt => return .{ .boolean = li < ri },
            .gt => return .{ .boolean = li > ri },
            .lte => return .{ .boolean = li <= ri },
            .gte => return .{ .boolean = li >= ri },
            else => 0,
        } } else .{ .integer = switch (op) {
            .add => li + ri,
            .sub => li - ri,
            .mul => li * ri,
            .div => if (ri != 0) @divTrunc(li, ri) else 0,
            .mod => if (ri != 0) @mod(li, ri) else 0,
            .lt => return .{ .boolean = li < ri },
            .gt => return .{ .boolean = li > ri },
            .lte => return .{ .boolean = li <= ri },
            .gte => return .{ .boolean = li >= ri },
            else => 0,
        } };
    }

    if (numeric_value_as_f64(left)) |l| {
        if (numeric_value_as_f64(right)) |r| {
            return switch (op) {
                .add => .{ .double = l + r },
                .sub => .{ .double = l - r },
                .mul => .{ .double = l * r },
                .div => .{ .double = if (r != 0) l / r else 0 },
                .lt => .{ .boolean = l < r },
                .gt => .{ .boolean = l > r },
                .lte => .{ .boolean = l <= r },
                .gte => .{ .boolean = l >= r },
                else => .null_val,
            };
        }
    }

    // String concatenation
    if (op == .add and (left == .string or right == .string)) {
        const ls = try eval.value_to_string(left);
        const rs = try eval.value_to_string(right);
        const result = try std.fmt.allocPrint(arena, "{s}{s}", .{ ls, rs });
        return .{ .string = result };
    }

    if (TemporalComparable.from_value(left)) |lv| {
        if (TemporalComparable.from_value(right)) |rv| {
            const cmp = std.mem.order(u8, lv, rv);
            return switch (op) {
                .lt => .{ .boolean = cmp == .lt },
                .gt => .{ .boolean = cmp == .gt },
                .lte => .{ .boolean = cmp != .gt },
                .gte => .{ .boolean = cmp != .lt },
                else => .null_val,
            };
        }
    }

    // Date/DateTime comparison (objects with "value" field containing ISO strings)
    if (left == .object and right == .object) {
        const left_cn = left.object.class_name;
        const right_cn = right.object.class_name;
        if (date_or_datetime_class(left_cn) and date_or_datetime_class(right_cn)) {
            const lv = object_string_field_or_empty(left.object, "value");
            const rv = object_string_field_or_empty(right.object, "value");
            const cmp = std.mem.order(u8, lv, rv);
            return switch (op) {
                .lt => .{ .boolean = cmp == .lt },
                .gt => .{ .boolean = cmp == .gt },
                .lte => .{ .boolean = cmp != .gt },
                .gte => .{ .boolean = cmp != .lt },
                else => .null_val,
            };
        }
    }
    // String comparison for < > <= >=
    if (left == .string and right == .string) {
        const cmp = std.mem.order(u8, left.string, right.string);
        return switch (op) {
            .lt => .{ .boolean = cmp == .lt },
            .gt => .{ .boolean = cmp == .gt },
            .lte => .{ .boolean = cmp != .gt },
            .gte => .{ .boolean = cmp != .lt },
            else => .null_val,
        };
    }

    return .null_val;
}

fn coerced_bool(value: Value) bool {
    return utils.coerce_to_bool(value) catch false;
}

fn integer_like_values(left: Value, right: Value) bool {
    return (left == .integer or left == .long) and
        (right == .integer or right == .long);
}

fn numeric_value_as_f64(value: Value) ?f64 {
    return switch (value) {
        .double => |v| v,
        .integer => |v| @floatFromInt(v),
        .long => |v| @floatFromInt(v),
        else => null,
    };
}

fn date_or_datetime_class(class_name: []const u8) bool {
    return std.ascii.eqlIgnoreCase(class_name, "Date") or
        std.ascii.eqlIgnoreCase(class_name, "Datetime");
}

fn object_string_field_or_empty(obj: *types.ObjectInstance, field_name: []const u8) []const u8 {
    const value = obj.fields.get(field_name) orelse return "";
    return if (value == .string) value.string else "";
}

fn eval_unary(op: ast.UnaryOp, operand: Value) !Value {
    switch (op) {
        .negate => {
            if (operand == .integer) return .{ .integer = -operand.integer };
            if (operand == .long) return .{ .long = -operand.long };
            if (operand == .double) return .{ .double = -operand.double };
            return .null_val;
        },
        .not => return .{ .boolean = !coerced_bool(operand) },
    }
}

fn eval_compound_assign(
    current: Value,
    op: ast.AssignOp,
    value: Value,
    arena: std.mem.Allocator,
) Value {
    const Numeric = struct {
        fn as_f64(v: Value) ?f64 {
            return switch (v) {
                .integer => |i| @floatFromInt(i),
                .long => |i| @floatFromInt(i),
                .double => |d| d,
                else => null,
            };
        }

        fn is_integral(f: f64) bool {
            return @floor(f) == f;
        }

        fn from_arithmetic(current_value: Value, incoming_value: Value, result: f64) Value {
            if (current_value == .double or incoming_value == .double) {
                if (is_integral(result)) {
                    if (current_value == .integer or incoming_value == .integer) {
                        return .{ .integer = @intFromFloat(result) };
                    }
                    if (current_value == .long or incoming_value == .long) {
                        return .{ .long = @intFromFloat(result) };
                    }
                }
                return .{ .double = result };
            }
            if (current_value == .long or incoming_value == .long) {
                return .{ .long = @intFromFloat(result) };
            }
            return .{ .integer = @intFromFloat(result) };
        }

        fn from_division(current_value: Value, incoming_value: Value, result: f64) Value {
            if (current_value == .double or incoming_value == .double) {
                if (is_integral(result)) return .{ .integer = @intFromFloat(result) };
                return .{ .double = result };
            }
            if (current_value == .long or incoming_value == .long) {
                if (is_integral(result)) return .{ .long = @intFromFloat(result) };
                return .{ .double = result };
            }
            if (is_integral(result)) return .{ .integer = @intFromFloat(result) };
            return .{ .double = result };
        }
    };

    switch (op) {
        .plus_assign => {
            if (current == .integer and value == .integer) {
                return .{ .integer = current.integer + value.integer };
            }
            if (current == .long and value == .long) {
                return .{ .long = current.long + value.long };
            }
            if (current == .double and value == .double) {
                return .{ .double = current.double + value.double };
            }
            if (Numeric.as_f64(current)) |lhs| {
                if (Numeric.as_f64(value)) |rhs| {
                    return Numeric.from_arithmetic(current, value, lhs + rhs);
                }
            }
            // String concatenation for +=
            if (current == .string or value == .string) {
                const ls = utils.coerce_to_string(current, arena) catch return current;
                const rs = utils.coerce_to_string(value, arena) catch return current;
                const result =
                    std.fmt.allocPrint(arena, "{s}{s}", .{ ls, rs }) catch return current;
                return .{ .string = result };
            }
        },
        .minus_assign => {
            if (current == .integer and value == .integer) {
                return .{ .integer = current.integer - value.integer };
            }
            if (current == .long and value == .long) {
                return .{ .long = current.long - value.long };
            }
            if (Numeric.as_f64(current)) |lhs| {
                if (Numeric.as_f64(value)) |rhs| {
                    return Numeric.from_arithmetic(current, value, lhs - rhs);
                }
            }
        },
        .star_assign => {
            if (current == .integer and value == .integer) {
                return .{ .integer = current.integer * value.integer };
            }
            if (current == .long and value == .long) {
                return .{ .long = current.long * value.long };
            }
            if (Numeric.as_f64(current)) |lhs| {
                if (Numeric.as_f64(value)) |rhs| {
                    return Numeric.from_arithmetic(current, value, lhs * rhs);
                }
            }
        },
        .slash_assign => {
            if (current == .integer and value == .integer and value.integer != 0)
                return .{ .integer = @divTrunc(current.integer, value.integer) };
            if (current == .long and value == .long and value.long != 0)
                return .{ .long = @divTrunc(current.long, value.long) };
            if (Numeric.as_f64(current)) |lhs| {
                if (Numeric.as_f64(value)) |rhs| {
                    if (rhs != 0) return Numeric.from_division(current, value, lhs / rhs);
                }
            }
        },
        .assign => return value,
        .null_coalesce_assign => return if (current == .null_val) value else current,
    }
    return value;
}

fn default_value(type_ref: types.TypeRef) Value {
    // Apex treats all types (including Integer, Double, Decimal, Boolean) as
    // reference types whose uninitialized value is null.
    _ = type_ref;
    return .null_val;
}

fn extract_from_type(soql: []const u8) ?[]const u8 {
    // Find "FROM <type>" case-insensitive, skipping sub-queries in parens
    const lower = soql;
    var i: usize = 0;
    var depth: u32 = 0;
    while (i + 5 < lower.len) : (i += 1) {
        if (lower[i] == '(') {
            depth += 1;
            continue;
        }
        if (lower[i] == ')') {
            if (depth > 0) depth -= 1;
            continue;
        }
        if (depth > 0) continue; // Skip content inside parentheses
        if (std.ascii.eqlIgnoreCase(lower[i .. i + 4], "from") and
            is_soql_whitespace(lower[i + 4]))
        {
            var start = i + 5;
            while (start < lower.len and is_soql_whitespace(lower[start])) start += 1;
            var end = start;
            while (end < lower.len and
                !is_soql_whitespace(lower[end]) and
                lower[end] != ']' and
                lower[end] != ')')
                end += 1;
            if (end > start) return lower[start..end];
        }
    }
    return null;
}

/// Check if a character is whitespace (space, tab, newline, carriage return)
fn is_soql_whitespace(c: u8) bool {
    return c == ' ' or c == '\t' or c == '\n' or c == '\r';
}

fn extract_where_clause(soql: []const u8) ?[]const u8 {
    // Find WHERE ... (ends before ORDER BY, GROUP BY, LIMIT, OFFSET, WITH, FOR)
    // Skip content inside parentheses (sub-queries)
    var i: usize = 0;
    var paren_depth: u32 = 0;
    while (i + 5 < soql.len) : (i += 1) {
        if (soql[i] == '(') {
            paren_depth += 1;
            continue;
        }
        if (soql[i] == ')') {
            if (paren_depth > 0) paren_depth -= 1;
            continue;
        }
        if (paren_depth > 0) continue;
        if (std.ascii.eqlIgnoreCase(soql[i .. i + 5], "where") and
            (i == 0 or is_soql_whitespace(soql[i - 1])) and
            is_soql_whitespace(soql[i + 5]))
        {
            const start = i + 6;
            // Find end of WHERE clause
            var end = soql.len;
            var j: usize = start;
            while (j + 3 < soql.len) : (j += 1) {
                // Check for terminating keywords
                const remaining = soql[j..];
                if (soql_clause_starts_at(soql, j, remaining, "ORDER")) {
                    end = j;
                    break;
                }
                if (soql_clause_starts_at(soql, j, remaining, "GROUP")) {
                    end = j;
                    break;
                }
                if (soql_clause_starts_at(soql, j, remaining, "LIMIT")) {
                    end = j;
                    break;
                }
                if (soql_clause_starts_at(soql, j, remaining, "OFFSET")) {
                    end = j;
                    break;
                }
                if (soql_clause_starts_at(soql, j, remaining, "WITH")) {
                    end = j;
                    break;
                }
                if (soql_clause_starts_at(soql, j, remaining, "FOR")) {
                    end = j;
                    break;
                }
            }
            if (start < end) return soql[start..end];
        }
    }
    return null;
}

fn soql_clause_starts_at(
    soql: []const u8,
    index: usize,
    remaining: []const u8,
    keyword: []const u8,
) bool {
    return remaining.len >= keyword.len and
        std.ascii.eqlIgnoreCase(remaining[0..keyword.len], keyword) and
        (index == 0 or is_soql_whitespace(soql[index - 1]));
}

fn find_logical_op(clause: []const u8, keyword: []const u8) ?usize {
    // Find AND/OR at top level (not inside parens)
    var depth: u32 = 0;
    var i: usize = 0;
    while (i < clause.len) : (i += 1) {
        if (clause[i] == '(') {
            depth += 1;
            continue;
        }
        if (clause[i] == ')') {
            if (depth > 0) depth -= 1;
            continue;
        }
        if (clause[i] == '\'') {
            // Skip string literal
            i += 1;
            while (i < clause.len and clause[i] != '\'') : (i += 1) {}
            continue;
        }
        if (depth == 0 and i + keyword.len <= clause.len) {
            if (std.ascii.eqlIgnoreCase(clause[i .. i + keyword.len], keyword)) {
                // Check word boundaries
                const before_ok = i == 0 or logical_op_boundary_before(clause[i - 1]);
                const after_ok = i + keyword.len >= clause.len or
                    logical_op_boundary_after(clause[i + keyword.len]);
                if (before_ok and after_ok) return i;
            }
        }
    }
    return null;
}

fn logical_op_boundary_before(ch: u8) bool {
    return ch == ' ' or ch == '\n' or ch == ')';
}

fn logical_op_boundary_after(ch: u8) bool {
    return ch == ' ' or ch == '\n' or ch == '(';
}

fn extract_offset(soql: []const u8) ?usize {
    var i: usize = 0;
    while (i + 7 < soql.len) : (i += 1) {
        if (soql_keyword_at(soql, i, "offset")) {
            var start = i + 7;
            while (start < soql.len and soql[start] == ' ') start += 1;
            var end = start;
            while (end < soql.len and std.ascii.isDigit(soql[end])) end += 1;
            if (end > start) {
                return std.fmt.parseUnsigned(usize, soql[start..end], 10) catch null;
            }
        }
    }
    return null;
}

fn extract_offset_bind_var(soql: []const u8) ?[]const u8 {
    var i: usize = 0;
    while (i + 7 < soql.len) : (i += 1) {
        if (soql_keyword_at(soql, i, "offset")) {
            var start = i + 7;
            while (start < soql.len and soql[start] == ' ') start += 1;
            if (start < soql.len and soql[start] == ':') {
                var end = start + 1;
                while (end < soql.len and is_soql_identifier_char(soql[end])) end += 1;
                if (end > start + 1) return soql[start + 1 .. end];
            }
        }
    }
    return null;
}

fn soql_keyword_at(soql: []const u8, index: usize, keyword: []const u8) bool {
    const after = index + keyword.len;
    return after < soql.len and
        std.ascii.eqlIgnoreCase(soql[index..after], keyword) and
        is_soql_whitespace(soql[after]);
}

fn is_soql_identifier_char(ch: u8) bool {
    return std.ascii.isAlphanumeric(ch) or ch == '_';
}

const OrderByInfo = struct {
    field: []const u8,
    desc: bool,
};

fn extract_order_by_field(soql: []const u8) ?OrderByInfo {
    var i: usize = 0;
    while (i + 9 < soql.len) : (i += 1) {
        if (std.ascii.eqlIgnoreCase(soql[i .. i + 8], "ORDER BY") and
            (soql[i + 8] == ' ' or soql[i + 8] == '\n' or soql[i + 8] == '\t'))
        {
            var start = i + 9;
            while (start < soql.len and is_soql_whitespace(soql[start])) start += 1;
            var end = start;
            while (end < soql.len and is_order_by_field_char(soql[end])) end += 1;
            if (end > start) {
                const field = soql[start..end];
                // Check for DESC/ASC after the field
                var pos = end;
                while (pos < soql.len and is_soql_whitespace(soql[pos])) pos += 1;
                var descending = false;
                if (pos + 4 <= soql.len and
                    std.ascii.eqlIgnoreCase(soql[pos .. pos + 4], "DESC"))
                {
                    descending = true;
                }
                return OrderByInfo{ .field = field, .desc = descending };
            }
        }
    }
    return null;
}

fn is_order_by_field_char(ch: u8) bool {
    return ch != ' ' and ch != '\n' and ch != '\t' and ch != ',' and ch != ')';
}

fn extract_limit_bind_var(soql: []const u8) ?[]const u8 {
    var i: usize = 0;
    while (i + 6 < soql.len) : (i += 1) {
        if (soql_keyword_at(soql, i, "limit")) {
            var start = i + 6;
            while (start < soql.len and soql[start] == ' ') start += 1;
            if (start < soql.len and soql[start] == ':') {
                var end = start + 1;
                while (end < soql.len and is_soql_identifier_char(soql[end])) end += 1;
                return soql[start + 1 .. end];
            }
        }
    }
    return null;
}

fn extract_limit(soql: []const u8) ?usize {
    var i: usize = 0;
    while (i + 6 < soql.len) : (i += 1) {
        if (soql_keyword_at(soql, i, "limit")) {
            var start = i + 6;
            while (start < soql.len and soql[start] == ' ') start += 1;
            var end = start;
            while (end < soql.len and std.ascii.isDigit(soql[end])) end += 1;
            if (end > start) {
                return std.fmt.parseUnsigned(usize, soql[start..end], 10) catch null;
            }
        }
    }
    return null;
}

// ---------------------------------------------------------------------------
// SOQL sub-query and parent field helpers
// ---------------------------------------------------------------------------

const SubQueryInfo = struct {
    relationship: []const u8,
    query: []const u8,
};

fn extract_sub_query(soql: []const u8) ?SubQueryInfo {
    // Find pattern: (SELECT ... FROM RelationshipName)
    var i: usize = 0;
    while (i < soql.len) : (i += 1) {
        if (soql[i] == '(' and i + 8 < soql.len) {
            var depth: u32 = 1;
            var close_idx = i + 1;
            while (close_idx < soql.len) : (close_idx += 1) {
                if (soql[close_idx] == '(') depth += 1;
                if (soql[close_idx] == ')') {
                    depth -= 1;
                    if (depth == 0) break;
                }
            }
            if (close_idx >= soql.len or depth != 0) continue;
            const inner_query = std.mem.trim(u8, soql[i + 1 .. close_idx], " \t\n\r");
            if (inner_query.len > 6 and
                std.ascii.eqlIgnoreCase(inner_query[0..6], "SELECT"))
            {
                if (std.ascii.indexOfIgnoreCase(inner_query, "FROM")) |from_pos| {
                    var start = from_pos + 4;
                    while (start < inner_query.len and is_soql_whitespace(inner_query[start])) {
                        start += 1;
                    }
                    var end = start;
                    while (end < inner_query.len and
                        sub_query_relationship_char(inner_query[end]))
                    {
                        end += 1;
                    }
                    if (end > start) {
                        const raw_rel = inner_query[start..end];
                        const rel = strip_parent_relationship_prefix(raw_rel);
                        return SubQueryInfo{ .relationship = rel, .query = inner_query };
                    }
                }
            }
        }
    }
    return null;
}

fn sub_query_relationship_char(ch: u8) bool {
    return ch != ' ' and ch != ')' and ch != '\n' and ch != '\t';
}

fn strip_parent_relationship_prefix(raw_rel: []const u8) []const u8 {
    return if (std.mem.lastIndexOfScalar(u8, raw_rel, '.')) |dot_pos|
        raw_rel[dot_pos + 1 ..]
    else
        raw_rel;
}

fn extract_parent_fields(soql: []const u8) ?[]const u8 {
    // Extract SELECT clause
    const select_start = if (std.ascii.indexOfIgnoreCase(soql, "SELECT")) |si|
        si + 6
    else
        return null;
    // Find outer FROM (not inside parens)
    var from_end: usize = soql.len;
    var depth: u32 = 0;
    var idx: usize = select_start;
    while (idx + 4 < soql.len) : (idx += 1) {
        if (soql[idx] == '(') depth += 1;
        if (soql[idx] == ')') {
            if (depth > 0) depth -= 1;
        }
        if (depth == 0 and
            std.ascii.eqlIgnoreCase(soql[idx .. idx + 4], "FROM") and
            (idx == 0 or is_soql_whitespace(soql[idx - 1])))
        {
            from_end = idx;
            break;
        }
    }
    return soql[select_start..from_end];
}

// ---------------------------------------------------------------------------
// テスト
// ---------------------------------------------------------------------------

const lexer_mod = @import("lexer.zig");
const parser_mod = @import("parser.zig");

const EvalTestResult = struct {
    value: Value,
    stdout: []const u8,
    arena: std.heap.ArenaAllocator,

    fn deinit(self: *EvalTestResult) void {
        self.arena.deinit();
    }
};

fn eval_source(
    source: []const u8,
    class_name: []const u8,
    method_name: []const u8,
) !EvalTestResult {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    errdefer arena.deinit();

    const tokens = try lexer_mod.tokenize(source, arena.allocator());
    const decls = try parser_mod.parse(tokens, arena.allocator());
    var eval = try Evaluator.init(arena.allocator(), std.testing.io);
    try eval.load_decls(decls);
    const result = try eval.call_method(class_name, method_name, &.{});

    return .{ .value = result, .stdout = eval.stdout.items, .arena = arena };
}

test "evaluate 1 + 2" {
    const tokens = try lexer_mod.tokenize("1 + 2", std.testing.allocator);
    defer std.testing.allocator.free(tokens);

    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();

    const expr = try parser_mod.parseExpr(tokens, arena.allocator());
    var eval = try Evaluator.init(arena.allocator(), std.testing.io);
    const result = try eval.eval_expr(expr, eval.global_env);
    try std.testing.expectEqual(@as(i64, 3), result.integer);
}

test "evaluate string equality case-insensitive" {
    const tokens = try lexer_mod.tokenize("'Hello' == 'hello'", std.testing.allocator);
    defer std.testing.allocator.free(tokens);

    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();

    const expr = try parser_mod.parseExpr(tokens, arena.allocator());
    var eval = try Evaluator.init(arena.allocator(), std.testing.io);
    const result = try eval.eval_expr(expr, eval.global_env);
    try std.testing.expect(result.boolean);
}

